    public KnCorpGroupInfoRespDTO createGroup(KnIPCorpGroupInfoDTO groupInfoDTO, KnPersisterTxn persisterTxn) {

        String methodName = "createGroup(KnIPCorpGroupInfoDTO, KnPersisterTxn)";
        knLogger.info(methodName, "ENTRY : Input DTO Passed - ", groupInfoDTO);
        KnCorpGroupInfoRespDTO respDto = new KnCorpGroupInfoRespDTO();

        String xdmsHome = "";
        try {
            int corpId = groupInfoDTO.getCorpId();
            Integer videoPermissionObj = groupInfoDTO.getVideoPermission();
            int videoPermission = (videoPermissionObj != null) ? videoPermissionObj : 0;
            boolean groupMemPresent = Boolean.FALSE;
            int clusterId = Integer.parseInt(System.getenv(CLUSTERID_ENV_NAME));
            Map<String, String> paramNameValueMapCommon = genInfoUtil.retrieveMSSvcsCommonConfig(clusterId, persisterTxn);
            String pochomeAutoAssignValue = paramNameValueMapCommon.get(POCHOME_AUTOASSIGN_FLAG);
            boolean pochomeAutoAssignFlag = true;
            if (pochomeAutoAssignValue != null) {
                try {
                    pochomeAutoAssignFlag = Integer.parseInt(pochomeAutoAssignValue) == ENABLED;
                } catch (NumberFormatException e) {
                    knLogger.warn(methodName, "Invalid pochomeAutoAssignValue: ", pochomeAutoAssignValue);
                }
            }
            knLogger.debug(methodName," pochomeAutoAssignFlag : ",pochomeAutoAssignFlag);

            // TP Dynamic group changes
            List<String> tpMdnList = null;
            Map<String, KnCorpSubscriberDTO> tpDBSubMap = null;
            if (groupInfoDTO.getClientType() == DYNAMIC_CGMT_INTF) {
                tpMdnList = new ArrayList<>();
                String tpRequestMDN = groupInfoDTO.getTpRequestMdn();
                String tpGroupOwner = groupInfoDTO.getTpGroupOwner();
                tpMdnList.add(tpRequestMDN);
                tpMdnList.add(tpGroupOwner);
                String pttServerID = genInfoUtil.retrieveLocalXDMPttServerId();
                tpDBSubMap = contactInfoUtil.getPoCSubscriberCorporateDetails(tpMdnList, pttServerID, persisterTxn);
                if (tpDBSubMap.get(tpRequestMDN) != null) {
                    corpId = tpDBSubMap.get(tpRequestMDN).getCorpId();
                    groupInfoDTO.setCorpId(corpId);
                }
            } else if (AREA_BASED_DYNAMIC_GROUP == groupInfoDTO.getClientType()) {
                List<String> grpOwnerList = new ArrayList<>();
                String groupOwner = groupInfoDTO.getTpGroupOwner();
                grpOwnerList.add(groupOwner);
                String pttServerID = genInfoUtil.retrieveLocalXDMPttServerId();
                tpDBSubMap = contactInfoUtil.getPoCSubscriberCorporateDetails(grpOwnerList, pttServerID, persisterTxn);
                if (tpDBSubMap.get(groupOwner) != null) {
                    corpId = tpDBSubMap.get(groupOwner).getCorpId();
                    groupInfoDTO.setCorpId(corpId);
                }
            }

            //Step:
            //get the Corp profile details from cache
            knLogger.debug(methodName, "Fetch the corpProfile profile if cached or fetch from the DB the details");
            KnCorpProfileDTO corpProfile = commonInfoUtil.getProfileDetails("" + corpId, CORP_PROFILE, false, persisterTxn);
            xdmsHome = corpProfile.getXdmsHome();
            String pocHome = corpProfile.getPocHome();
            Collection<KnSIPProxySvcConfigDTO> sipProxySvcConfigInfoDTO = commonInfoUtil.getSipProxySvcConfig(xdmsHome, persisterTxn);
            Map<String, String> rtxParamNameValueMap = genInfoUtil.retrieveRTXConfigValues(persisterTxn);
            knLogger.debug(methodName, "param value of rtxParamName", rtxParamNameValueMap);
            String maxLocWatcherPerGroup = rtxParamNameValueMap.get(MAX_LOC_WATCHERS_PER_GRP);

            //knLogger.debug(methodName, "param value of locWatcherConfig", paramNameValueMapCommon);
            String locWatcherConfigValue = paramNameValueMapCommon.get(KnConstants.GRPMEM_LOC_SVC_ENABLED);
            String maxGroupsPerCRIClient = paramNameValueMapCommon.get(MAX_GROUPS_PER_CRI_CLIENT);
            String maxPreConfigGroup = paramNameValueMapCommon.get(MAX_PRECONFIG_GROUPS);
            Map<String, String> paramNameValueMapService = genInfoUtil.retrieveMSSvcsServiceConfig(clusterId, persisterTxn);
            //  knLogger.debug(methodName, "param value of paramNameValueMapService", paramNameValueMapService);
            //Invoking custom hook
            KnCorpHookRespDTO responseDTO = new KnCorpHookRespDTO();
            Map<String, Object> customParams = groupInfoDTO.getCustomParamMap();
            if (groupInfoDTO.getHierarchyType() == HIERARCHY_TYPE.HIERARCHY && null != customParams) {
                knLogger.debug(methodName, "before validating checking OwnerIdList :", groupInfoDTO.getOwnerIdList());
                if (null != groupInfoDTO.getOwnerIdList() && !groupInfoDTO.getOwnerIdList().isEmpty()) {
                    groupInfoUtil.validateFanIds(corpId, groupInfoDTO.getOwnerIdList(), xdmsHome, persisterTxn);
                }
                customParams.put(CURRENT_MASTER_LIST_ETAG, corpProfile.getCorpMasterListEtag());
                customParams.put(PERSISTER_TXN, persisterTxn);
                customParams.put(PTT_SERVER_ID, xdmsHome);
                groupInfoDTO.setCustomParamMap(customParams);
                KnCorpHookIPDTO hookIPDTO = new KnCorpHookIPDTO();
                hookIPDTO.setAction(KnActions.ACTIONS.CREATE_GROUP);
                hookIPDTO.setData(groupInfoDTO);
                KnProcessInvokerImpl processInvoker = KnProcessInvokerImpl.getInstance();
                Object hookResp = processInvoker.invokeHook(CUSTOM_CORP_USER_HOOK, hookIPDTO);
                if (hookResp instanceof KnCorpHookRespDTO) {
                    responseDTO = (KnCorpHookRespDTO) hookResp;
                    if (com.kodiak.xdms.server.common.resources.KnConstants.RESPONSE_STATUS.FAILURE.value() == responseDTO.getStatus()) {
                        knLogger.error(methodName, "Returning Failure response");
                        populateXdmResponseFroomHook(responseDTO, respDto);
                        return respDto;
                    }
                }
            }
            //Step:
            //prepare for business validation
            //1. Retrieve groups count for corpId
            //2. Retrieve distinct member counts
            //3. Group counts for all the members via privateMemberList or addedSublistIds
            //4. Retrieve sublistIds from DB against the addedSublistIds
            //5. Retrieve subscriber info from DB against
            //  - validate groups count for corporate
            //  - validate group member count for the group
            //  - validate each member's individual group count

            //Step:
            //retrieve group details information
            boolean criFlag=false;
            criFlag=genInfoUtil.retrieveCriLocFlag(clusterId, persisterTxn);
            boolean isMCXGroup=false;
            if ( groupInfoDTO.getMcxGrpInd() != null && groupInfoDTO.getMcxGrpInd() == MCX_GROUP_INDICATOR) {
                groupInfoDTO.setOperationType("createVlgGroup");
                isMCXGroup=true;
            }
            KnCorpGroupInfoPersistDTO groupPersistDTO = groupInfoUtil.getGroupInfo(groupInfoDTO, xdmsHome, persisterTxn);

            //There is no support of the multiple dipatchers in the group .This variable will be used for the validation rule and also where
            //ever required.
            groupPersistDTO.setMultipleDispatcherAllowed(KnConstants.TRUE);
            //set input dto
            groupPersistDTO.setInputDTO(groupInfoDTO);
            Collection<Integer> addedSublistIds = groupInfoDTO.getAddedSublistIds();

            int memberCount = 0;
            Collection<KnCorpContactDTO> addedMemberMdnsDTOLst = groupInfoDTO.getAddedMemberDTOMdns();

            //member string collection for the added members
            Collection<String> addedMemberMdns = new ArrayList<String>();
            Map<String, Integer> supervisorMembers = new HashMap<String, Integer>();
            //this holds the added members superviosr list
            Collection<KnCorpGroupMemberDTO> addedMemberSupervisor = new ArrayList<KnCorpGroupMemberDTO>();
            //holds all the dispatchers in the request
            Set<String> dispatcherSubscribers = new HashSet<String>();
            //holds all the interOPSubscribers in the request
            Set<String> interOPSubsc = new HashSet<String>();

            //getting the added members which are supervisor , dispatchers and interop from the added members tag list
            KnCorpGroupInfoPersistDTO subscListDTO = populateSpecficSubscInList(addedMemberMdnsDTOLst);


            //setting the dispatchers in the added members list with supervisor tag as 2
            if (!isObjectNull(subscListDTO.getRequestDispatcherSubscribers())) {
                dispatcherSubscribers.addAll(new HashSet<String>(subscListDTO.getRequestDispatcherSubscribers()));
            }
            //setting the interOP in the added members list with supervisor tag as 3
            if (!isObjectNull(subscListDTO.getReqInterOpSubs())) {
                interOPSubsc.addAll(new HashSet<String>(subscListDTO.getReqInterOpSubs()));
            }
            //preparing alist with added members as a list of string
            addedMemberMdns = subscListDTO.getAddedMdnList();

            // Validate max groups per subscriber
            Collection<KnCorpSubscriberDTO> subsInfo = contactInfoUtil.getSubscribersInfo(addedMemberMdns, xdmsHome, persisterTxn);
            Map<String, Integer> subsGroupCount = groupInfoUtil.getSubsScrGroupCountExceptABDG(
                    addedMemberMdns.stream().collect(Collectors.toList()), xdmsHome, persisterTxn);

            boolean sysLargeAgencyDispatch = paramNameValueMapCommon.get(LARGE_AGENCY_DISPATCH_FEATURE).equalsIgnoreCase(ENABLED_STRING);
            boolean corpLargeAgencyDispatch = KnGeneralUtil.getFeatureBitValue(corpProfile.getCorpFS2(), FEATURE_SET.LARGE_AGENCY_DISPATCH.value());

            groupPersistDTO.setAddedMDNs(subsInfo);

            // The added members supervisor DTO
            if (!isObjectNull(subscListDTO.getAddedMdnDTO())) {
                addedMemberSupervisor.addAll(subscListDTO.getCompleteSupervisorList());
            }
            if (!isObjectNull(subscListDTO.getSubscSupVals())) {
                supervisorMembers.putAll(subscListDTO.getSubscSupVals());
            }

            knLogger.debug(methodName, " subscListDTO.getSubscSupVals() --",KnGDPRTemplate.mapKeyMdn(subscListDTO.getSubscSupVals()), " supervisorMembers --", KnGDPRTemplate.mapKeyMdn(supervisorMembers));

            groupInfoDTO.setAddedMdnsList(addedMemberMdns);

            //Preparing DTO for locWatcher Validations.
            Collection<KnCorpGroupMemberDTO> locWatcherList = new ArrayList<>();
            if (!isObjectNull(subscListDTO.getLocWatcherList())) {
                locWatcherList.addAll(subscListDTO.getLocWatcherList());
            }
            //populating the supervisors from the supervisor members tag - sublist member properties.
            Collection<KnCorpGroupMemberDTO> groupSupervisors = groupInfoDTO.getGroupSupervisor();

            if (groupSupervisors != null && !groupSupervisors.isEmpty()) {
                for (KnCorpContactDTO contact : groupInfoDTO.getGroupSupervisor()) {
                    supervisorMembers.put(contact.getMdn(), contact.getSupervisory());
                    if (contact.getLocWatcher() == LOCWATCHER) {
                        KnCorpGroupMemberDTO locDto = new KnCorpGroupMemberDTO();
                        locDto.setMdn(contact.getMdn());
                        locDto.setLocWatcher(contact.getLocWatcher());
                        locWatcherList.add(locDto);
                    }
                }
            }
            knLogger.debug(methodName, " locWatcherList", locWatcherList);
            // preparing locWatcherMap:
            Map<String, Integer> locWatcherMap = new HashMap<>();
            boolean locWatcherExists = false;
            if (!locWatcherList.isEmpty()) {
                locWatcherExists = true;
                for (KnCorpGroupMemberDTO subsDetails : locWatcherList) {
                    locWatcherMap.put(subsDetails.getMdn(), subsDetails.getLocWatcher());
                }
                knLogger.debug(methodName, "locWatcherMap : ", KnGDPRTemplate.mapKeyMdn(locWatcherMap));
                locWatcherList = contactInfoUtil.getPoCSubsDetails(locWatcherList, locWatcherMap.keySet(), xdmsHome, persisterTxn);
                groupPersistDTO.setLocWatcherList(locWatcherList);

                knLogger.debug(methodName, "locWatcherMap.keySet() : ", KnGDPRTemplate.mdnList(locWatcherMap.keySet()));
                Map<Integer, KnExtProfileDetails> locWatcherMdnProfileMap = commonInfoUtil.getExtProfileDetails(locWatcherMap.keySet(), xdmsHome, corpId,null, persisterTxn);
                knLogger.debug(methodName, "locWatcherMdnProfileMap : ", locWatcherMdnProfileMap);
                groupPersistDTO.setLocWatcherMdnProfileMap(locWatcherMdnProfileMap);
                groupPersistDTO.setRequestLocWatcherSubscribers(locWatcherMap.keySet());
            }
            knLogger.debug(methodName, "locWatcherExists - ", locWatcherExists);
            groupPersistDTO.setLocWatcherExists(locWatcherExists);
            //removed as its not needed for the validation of the supervisory against the sublist memebers
            //Its added members and sublist supervisory are needeed together for the external subsc cannot be supervisory validation only
            //groupSupervisors.addAll(addedMemberSupervisor);
            //setting all supervisor via sublist and private list to input DTO for the validation
            groupInfoDTO.setGroupSupervisor(groupSupervisors);
            groupInfoDTO.setAddedMdnSupervisor(addedMemberSupervisor);
            knLogger.debug(methodName, "Before getPoCSubscriberInfo for input corpMdnListPersistDto - ", KnGDPRTemplate.mdnList(addedMemberMdns));
            KnCorpMdnListPersistDTO corpMdnList = new KnCorpMdnListPersistDTO();
            if (addedMemberMdns != null && !addedMemberMdns.isEmpty()) {
                corpMdnList.setAddedMdnList(addedMemberMdns);
            }

            //Get the list of supervisor = 1 MDN from supervisorMembers.
            List<String> supervisorMdnList = new ArrayList<>();
            for (Entry<String, Integer> supEntry : supervisorMembers.entrySet()) {
                String mdn = supEntry.getKey();
                if (supEntry.getValue() == 1) {
                    supervisorMdnList.add(mdn);
                }
            }
            knLogger.debug(methodName, "supervisorMdnList : ", KnGDPRTemplate.mdnList(supervisorMdnList));
            Map<Integer, KnExtProfileDetails> supervisorMdnProfileMap = commonInfoUtil.getExtProfileDetails(supervisorMdnList, xdmsHome, corpId,null, persisterTxn);
            knLogger.debug(methodName, "supervisorMdnProfileMap : ", supervisorMdnProfileMap);

            KnMdnDetailsPersistDTO pocMdnPersistDto = null;
            if (!isObjectNull(corpMdnList) && !isObjectNullOrEmpty(corpMdnList.getAddedMdnList())) {
                corpMdnList.setCorpId(corpId);
                pocMdnPersistDto = contactInfoUtil.getPoCSubscriberInfo(corpMdnList, xdmsHome, persisterTxn);
                knLogger.debug(methodName, "After getPoCSubscriberInfo result obtained PocSubscriberList- ",
                        pocMdnPersistDto);
                Map<String, Integer> subscGrpCount = groupInfoUtil.getMembersGroupCount(pocMdnPersistDto.getGroupMdnList(), corpId, xdmsHome, persisterTxn);
                knLogger.debug(methodName, "subscGrpCount --", subscGrpCount.size());
                groupPersistDTO.setGroupMdnGrpCnt(subscGrpCount);

                //Modified for 8.1.1 Release
                knLogger.debug(methodName, "MaxSGPerGroup -- ", corpProfile.getMaxSGPerGrp());
                groupPersistDTO.setMaxSGPerGrp(corpProfile.getMaxSGPerGrp());
                groupPersistDTO.setMaxSGMdnPatchPerGroup(corpProfile.getMaxSGPatchPerGrp());

                groupPersistDTO.setPoCSubscriberList(pocMdnPersistDto.getMdnList());
                groupPersistDTO.setAddedMdnDTO(pocMdnPersistDto.getAddedMdnDTO());
                //populating the dispatchers and the inter op subscribers in the reaquest
                //Add the dispatchers to the request dispatcher
                //populating actual dispatchers and interOpSubscribers Froom DB
                KnCorpGroupInfoPersistDTO dbSpecificSubscDTO =
                        populateDbSpecificSubscInList(pocMdnPersistDto.getAddedMdnDTO());
                if (!isObjectNull(dbSpecificSubscDTO.getRequestDispatcherSubscribers())) {
                    dispatcherSubscribers.addAll(dbSpecificSubscDTO.getRequestDispatcherSubscribers());
                }

                if (!isObjectNull(dbSpecificSubscDTO.getReqInterOpSubs())) {
                    interOPSubsc.addAll(dbSpecificSubscDTO.getReqInterOpSubs());
                }
                if (!isObjectNull(dbSpecificSubscDTO.getSubscSupVals())) {
                    supervisorMembers.putAll(dbSpecificSubscDTO.getSubscSupVals());
                }

            }


            groupPersistDTO.setRequestDispatcherSubscribers(dispatcherSubscribers);
            groupPersistDTO.setReqInterOpSubs(interOPSubsc);

            Collection<Integer> listCommonContactListRejectionIds = sublistInfoUtil.getCommonContactListRejectForGrp(addedSublistIds,corpId,xdmsHome,persisterTxn);
            knLogger.debug("CommonContactListRejectionList: ",listCommonContactListRejectionIds);
            groupPersistDTO.setCommonContactRejectList(listCommonContactListRejectionIds);
            KnSublistDetailsPersistDTO pocSublistIds = sublistInfoUtil.getPoCSublistIdInfo(addedSublistIds,
                    corpId, xdmsHome, persisterTxn);
            knLogger.debug(methodName, "After getPoCSublistIdInfo result obtained pocSublistIds- ", pocSublistIds
            );
            groupPersistDTO.setPoCSublistList(pocSublistIds.getSublistIds());

            //Get the distinch members from added sublist Id list
            List<KnCorpSubscriberDTO> distAddedSublistMemLst = sublistInfoUtil.getSublistDistinctMembers(addedSublistIds, corpId, xdmsHome, persisterTxn);

            //Get the distinct added members among added sublis id list and added member list
            Collection<KnCorpSubscriberDTO> sublistMembers =
                    contactInfoUtil.getDistinctMembersList(null, distAddedSublistMemLst, corpId, xdmsHome, persisterTxn);


            Collection<KnCorpSubscriberDTO> actualMdnToBeAddedToGroup = new ArrayList<KnCorpSubscriberDTO>();
            actualMdnToBeAddedToGroup.addAll(sublistMembers);
            Map<String, KnCorpSubscriberDTO> privateListMemberDetails =
                    contactInfoUtil.getSubsribersCorporateDetails(addedMemberMdns, corpId, xdmsHome, persisterTxn);


            //Adding the private list members in te list only if not existing via the sublist members
            for (Entry<String, KnCorpSubscriberDTO> entry : privateListMemberDetails.entrySet()) {
                KnCorpSubscriberDTO subDTO = entry.getValue();
                if (!actualMdnToBeAddedToGroup.contains(subDTO)) {
                    actualMdnToBeAddedToGroup.add(subDTO);
                }
            }

            // grpMemberProfileMap to hold the external subscribers and ext conatcts profile map from all member lits.
            Map<Integer, KnExtProfileDetails> grpMemberProfileMap = commonInfoUtil.getExtProfileDetails(actualMdnToBeAddedToGroup, xdmsHome, persisterTxn);
            knLogger.debug(methodName, "grpMemberProfileMap : ", grpMemberProfileMap);
            Collection<KnCorpSubscriberDTO> privateMemberList = new ArrayList<KnCorpSubscriberDTO>();
            Collection<KnCorpSubscriberDTO> externalMemberList = new ArrayList<KnCorpSubscriberDTO>();
            Collection<String> memberList = new ArrayList<String>();
            Collection<String> externalMdnList = new ArrayList<String>();
            Collection<KnCorpSubscriberDTO> membersToBeAddedInGroupDocument = new ArrayList<KnCorpSubscriberDTO>();
            List<String> allMdnList = new ArrayList<>();
            //added to validate if the supervisor are a part of group
            if (actualMdnToBeAddedToGroup != null && !actualMdnToBeAddedToGroup.isEmpty()) {
                memberCount = actualMdnToBeAddedToGroup.size();
                //Code modified to get the internal members group count seperately and the external subscriber group count seperately
                for (KnCorpSubscriberDTO subsc : actualMdnToBeAddedToGroup) {
                    allMdnList.add(subsc.getMdn());
                    if (subsc.getCorpId() == corpId) {
                        memberList.add(subsc.getMdn());
                    } else {
                        externalMdnList.add(subsc.getMdn());
                    }
                }
                Map<String, Integer> subsGroupCountMap = groupInfoUtil.getMembersGroupCount(memberList, xdmsHome, persisterTxn);
                Map<String, Integer> externalSubscGroupCountMap =
                        groupInfoUtil.getExternalSubscriberGroupCount(externalMdnList, corpId, xdmsHome, persisterTxn);
                subsGroupCountMap.putAll(externalSubscGroupCountMap);
                groupPersistDTO.setSubsGroupsCount(subsGroupCountMap);
                knLogger.debug(methodName, "subsGroupCountMap - ", KnGDPRTemplate.mapKeyMdn(subsGroupCountMap));
                List<String> criClientList = new ArrayList<>(); // variable to hold the cri clients from the added group members.
                Iterator ite = actualMdnToBeAddedToGroup.iterator();
                while (ite.hasNext()) {
                    KnCorpSubscriberDTO subsc = (KnCorpSubscriberDTO) ite.next();
                    membersToBeAddedInGroupDocument.add(subsc);
                    String mdn = subsc.getMdn();
                    if (addedMemberMdns != null && addedMemberMdns.contains(subsc.getMdn())) {
                        privateMemberList.add(subsc);
                    }
                    if (subsc.getCorpId() != corpId) {
                        externalMemberList.add(subsc);
                        membersToBeAddedInGroupDocument.remove(subsc);
                    }
                    KnCorpGroupMemberDTO memberDTO = new KnCorpGroupMemberDTO();
                    memberDTO.setMdn(mdn);
                    if(subsc.getMcpttCompliance() == MCPTT_COMPLIANCE){
                        //Adding to cri clients because MCPTT_COMPLIANCE = 1
                        criClientList.add(mdn);
                    }
                }
                knLogger.debug(methodName, "criClientList - ", criClientList);
                groupPersistDTO.setCriClientList(criClientList);
                if(maxGroupsPerCRIClient != null){
                    groupPersistDTO.setMaxGroupsPerCRIClient(Integer.parseInt(maxGroupsPerCRIClient));
                }
            }
            boolean isLargeGroup = Boolean.FALSE;
            groupPersistDTO.setGroupMemberCount(memberCount);
            if (STANDARD_GROUP == groupInfoDTO.getGroupType() && memberCount > corpProfile.getMaxMemPerCorpGroup()) {
                groupPersistDTO.setLargeGroup(Boolean.TRUE);
                isLargeGroup = Boolean.TRUE;
            } else if (DISPATCH_GROUP == groupInfoDTO.getGroupType() && memberCount > corpProfile.getMaxMembersPerDispatchGroup()) {
                groupPersistDTO.setLargeGroup(Boolean.TRUE);
                isLargeGroup = Boolean.TRUE;
            }
            Collection<String> extMdns = new ArrayList<>();
            if (externalMemberList != null && !externalMemberList.isEmpty()) {
                KnMdnDetailsPersistDTO externalPocSubsPersistDto = contactInfoUtil.getExternalConatctsInfo(corpId,
                        externalMemberList, xdmsHome, persisterTxn);
                groupInfoDTO.setExternalContacts(externalMemberList);
                groupPersistDTO.setExternalContacts(externalPocSubsPersistDto.getExternalMdnList());
                //setting the proper corpId for the external subscribers
                Map<String, KnCorpSubscriberDTO> subscMap = new HashMap<String, KnCorpSubscriberDTO>();
                for (KnCorpSubscriberDTO subscriber : privateMemberList) {
                    subscMap.put(subscriber.getMdn(), subscriber);
                }
                for (KnCorpSubscriberDTO subsc : externalPocSubsPersistDto.getExternalMdnList()) {
                    String memberMdn = subsc.getMdn();
                    extMdns.add(memberMdn);
                    if (subscMap.containsKey(memberMdn)) {
                        KnCorpSubscriberDTO subscriber = subscMap.get(memberMdn);
                        subscriber.setCorpId(subsc.getCorpId());
                        subscriber.setName(subsc.getName());
                    }
                }
                privateMemberList = subscMap.values();
            }

            // TP Dynamic group changes
            if (groupInfoDTO.getClientType() == DYNAMIC_CGMT_INTF) {
                //added mdn DB thired party mdn list
                List<String> tpDbMDNList = pocMdnPersistDto.getTpMdnList();
                tpDbMDNList.addAll(tpMdnList);

                KnTPVendorDetailsPersistDTO dbVendorDetails = commonInfoUtil.getVendorDetails(groupInfoDTO.getTpVendorID(), xdmsHome, persisterTxn);
                Map<String, String> vendorMdnMap = commonInfoUtil.getVendorID(tpDbMDNList, xdmsHome, persisterTxn);

                groupPersistDTO.setTpVendorPersistDTO(dbVendorDetails);
                groupPersistDTO.setTpRequestMDNMap(tpDBSubMap);
                groupPersistDTO.setVendorMdnMap(vendorMdnMap);
                groupPersistDTO.setTpDbMDNList(tpDbMDNList);
                groupPersistDTO.setTpVendorID(groupInfoDTO.getTpVendorID());
            }
            // ABDG Enhancement:
            if (AREA_BASED_DYNAMIC_GROUP == groupInfoDTO.getClientType() && DISPATCH_GROUP == groupInfoDTO.getGroupType()) {
                int maxAbdgCountSystem = Integer.valueOf(paramNameValueMapService.get(MAX_ABDG_COUNT_SYSTEM).trim());
                int maxAbdgPerGrpOwnerSystem = Integer.valueOf(paramNameValueMapService.get(MAX_ABDG_PER_GRPOWNER).trim());
                int maxAbdgPerGrpMemStstem = Integer.valueOf(paramNameValueMapService.get(MAX_ABDG_PER_GRPMEMBER).trim());
                int maxAbdgLrgGrpPerCorp = Integer.valueOf(paramNameValueMapService.get(MAX_LRGABDG_TALKGRP_PER_CORP).trim());
                int maxAbdgLrgGrpMems = Integer.valueOf(paramNameValueMapService.get(MAX_USR_PER_LRGABDG_TALKGRP).trim());
                knLogger.debug(methodName, "maxAbdgCountSystem : ", maxAbdgCountSystem, "maxAbdgPerGrpOwnerSystem : ", maxAbdgPerGrpOwnerSystem,
                        "maxAbdgPerGrpMemStstem : ", maxAbdgPerGrpMemStstem, "corpProfileMaxAbdgTalkGrp : ", corpProfile.getMaxAbdgTalkGrp());
                //Setting min of corp and System - MaxAbdgTalkGrp
                if (corpProfile.getMaxAbdgTalkGrp() == 0 || corpProfile.getMaxAbdgTalkGrp() > maxAbdgCountSystem) {
                    groupPersistDTO.setMaxAbdgCountSystem(maxAbdgCountSystem);
                } else {
                    groupPersistDTO.setMaxAbdgCountSystem(corpProfile.getMaxAbdgTalkGrp());
                }
                //Setting min of corp and System - MaxAbdgPerGrpOwner
                if (corpProfile.getMaxAbdgPerGrpOwner() == 0 || corpProfile.getMaxAbdgPerGrpOwner() > maxAbdgPerGrpOwnerSystem) {
                    groupPersistDTO.setMaxAbdgPerGrpOwner(maxAbdgPerGrpOwnerSystem);
                } else {
                    groupPersistDTO.setMaxAbdgPerGrpOwner(corpProfile.getMaxAbdgPerGrpOwner());
                }
                //Setting min of corp and System - MaxAbdgPerGrpMem
                if (corpProfile.getMaxAbdgPerGrpMember() == 0 || corpProfile.getMaxAbdgPerGrpMember() > maxAbdgPerGrpMemStstem) {
                    groupPersistDTO.setMaxAbdgPerGrpMem(maxAbdgPerGrpMemStstem);
                } else {
                    groupPersistDTO.setMaxAbdgPerGrpMem(corpProfile.getMaxAbdgPerGrpMember());
                }
                Collection<Integer> abdgGroupIds = groupInfoUtil.getCorpGroupCountIntf(corpId, groupInfoDTO.getGroupCreatedBy(),
                        xdmsHome, persisterTxn);
                int abdgGrpCountPerOwner = groupInfoUtil.getCorpGroupCountIntfPerOwner(corpId, groupInfoDTO.getGroupCreatedBy(),
                        groupInfoDTO.getTpGroupOwner(), xdmsHome, persisterTxn);
                Map<String, Integer> subsAbdgGroupCountMap = groupInfoUtil.getMembersAbdgGroupCount(abdgGroupIds, xdmsHome, persisterTxn);
                knLogger.debug(methodName, "subsAbdgGroupCountMap.size : ", subsAbdgGroupCountMap.size());
                Map<String, Integer> filteredSubsAdbgCountMap = subsAbdgGroupCountMap.entrySet().stream()
                        .filter(map -> memberList.contains(map.getKey())).collect(Collectors.toMap(Entry::getKey, Entry::getValue));
                knLogger.debug(methodName, "filteredSubsAdbgCountMap : ", filteredSubsAdbgCountMap);
                Map<String, Integer> externalSubscAbdgGroupCountMap =
                        groupInfoUtil.getExternalSubscriberAbdgGroupCount(externalMdnList, corpId, xdmsHome, persisterTxn);
                filteredSubsAdbgCountMap.remove(groupInfoDTO.getTpGroupOwner());
                filteredSubsAdbgCountMap.putAll(externalSubscAbdgGroupCountMap);
                knLogger.debug(methodName, "abdgGroupIds.size() : ", abdgGroupIds.size(), "abdgGrpCountPerOwner : ", abdgGrpCountPerOwner,
                        "filteredSubsAdbgCountMap.size : ", filteredSubsAdbgCountMap.size());
                int lrgAbdgGroup = groupInfoUtil.getLrgAbdgGroupCount(corpId, xdmsHome, persisterTxn);
                //get ABDG large group count in the corporation
                groupPersistDTO.setCorpAbdgGroupCount(abdgGroupIds.size());
                groupPersistDTO.setAbdgGroupCountPerOwner(abdgGrpCountPerOwner);
                groupPersistDTO.setAbdgGroupCountPerMemberMap(filteredSubsAdbgCountMap);
                groupPersistDTO.setTpGroupOwner(groupInfoDTO.getTpGroupOwner());
                groupPersistDTO.setGrpOwnerExistsInDB(!tpDBSubMap.isEmpty());
                groupPersistDTO.setTpRequestMDNMap(tpDBSubMap);
                groupPersistDTO.setMaxLrgAbdgGrpPerCorp(maxAbdgLrgGrpPerCorp);
                groupPersistDTO.setMaxMemsPerLrgAbdgGrp(maxAbdgLrgGrpMems);
                groupPersistDTO.setNumOfLrgAbdgGrp(lrgAbdgGroup);
            }

            //check if interOP subscriber is part of any other group
            Map<String, Integer> interOpGrpCnt = groupInfoUtil.getExternalSubscriberGroupCount(groupPersistDTO.getReqInterOpSubs(), corpId, xdmsHome, persisterTxn);
            groupPersistDTO.setInterOPSubscGrpCnt(interOpGrpCnt);
            List<Integer> groupIdList = new ArrayList<>();
            if (STANDARD_GROUP == groupInfoDTO.getGroupType()) {
                groupIdList.add(STANDARD_GROUP);
                groupIdList.add(BROADCAST_GROUP);
            } else {
                groupIdList.add(DISPATCH_GROUP);
            }
            int groupCount = groupInfoUtil.getCorpGroupCount(corpId, groupIdList, xdmsHome, persisterTxn);
            groupPersistDTO.setCorpGroupCount(groupCount);
            groupPersistDTO.setMaxGroups(corpProfile.getMaxCorpGroups());
            int maxMemberPerCorpGroup = corpProfile.getMaxMemPerCorpGroup();
            groupPersistDTO.setMaxNumberOfMembers(maxMemberPerCorpGroup);
            groupPersistDTO.setMaxGroupsPerMemberCount(corpProfile.getMaxGroupsPerSubsc());
            groupPersistDTO.setMaxGroupsPerLargeDispatchMemberCount(corpProfile.getMaxGroupsPerLargeDispatch());
            groupPersistDTO.setIsSysLargeAgencyDispatchEnabled(sysLargeAgencyDispatch);
            groupPersistDTO.setIsCorpLargeAgencyDispatchEnabled(corpLargeAgencyDispatch);
            groupPersistDTO.setSubsGroupCount(subsGroupCount);
            groupPersistDTO.setSublistMembers(sublistMembers);

            //groupPersistDTO.setMaxAllowedContactCountPerRequest(corpProfile.getMaxContactsPerRequest());
            // groupPersistDTO.setContactCountInRequest(memberCount);
            //groupPersistDTO.setMaxAllowedContactCountPerRequest(corpProfile.getMaxContactsPerRequest());
            //groupPersistDTO.setContactCountInRequest(memberCount);
            groupPersistDTO.setMaxDispatchGroup(corpProfile.getMaxDispatchGroup());
            groupPersistDTO.setMaxSubscriberPerDispatchGroup(corpProfile.getMaxMembersPerDispatchGroup());
            groupPersistDTO.setMaxDispatchMembersPerDispatchGroup(corpProfile.getMaxDispatchMembersPerDispatchGroup());
            groupPersistDTO.setDispatchEnabled(corpProfile.getDispatchEnabled());
            groupPersistDTO.setSupervisorProfileMap(supervisorMdnProfileMap);
            groupPersistDTO.setConfiguredProfileMap(grpMemberProfileMap);
            groupPersistDTO.setLocWatcherConfigValue(locWatcherConfigValue.trim());
            groupPersistDTO.setMaxLocWatcherPerGroup(Integer.parseInt(maxLocWatcherPerGroup));
            groupPersistDTO.setMaxLargeGrpCorp(corpProfile.getMaxLrgGrpPerCorp());
            groupPersistDTO.setMaxLargeGrpSystem(Integer.parseInt(genInfoUtil.retrieveRTXConfigValues(persisterTxn).get(NUM_OF_LG_SUPPORTED)));
            groupPersistDTO.setLargeGrpCountInCorp(groupInfoUtil.getLargeGroupCounts(corpId, persisterTxn, xdmsHome).getLrgGrpCountCorp());
            groupPersistDTO.setLargeGrpCountInSystem(groupInfoUtil.getLargeGroupCounts(corpId, persisterTxn, xdmsHome).getLrgGrpCountSystem());
            groupPersistDTO.setMaxMemPerLargeGroup(corpProfile.getMaxMemPerLrgGrp());
            groupPersistDTO.setLargeGroupSupported(corpProfile.getLargeGrpSupported());
            //osm create group list exist check
            Map<Integer, Integer> osmListIdAndDefaultMap = corpOSMInfoUtil
                    .getOSMListIdAndDefaultMap(String.valueOf(groupInfoDTO.getCorpId()), xdmsHome, persisterTxn);
            /*if(groupInfoDTO.getOSMListId()!=null&&!groupInfoDTO.getOSMListId().isEmpty()){
                groupPersistDTO.setOSMListId(groupInfoDTO.getOSMListId());
            }else{
                if(osmListIdAndDefaultMap!=null&&!osmListIdAndDefaultMap.isEmpty()){
                    Optional<Integer> osmPresent =osmListIdAndDefaultMap.entrySet().stream()
                            .filter(entry -> entry.getValue().equals(ENABLED)).map(Map.Entry::getKey).findFirst();
                    if(osmPresent.isPresent()) {
                        groupPersistDTO.setOSMListId(osmPresent.get().toString());
                    }
                }
            }*/
            if (groupInfoDTO.getOSMListId() != null)
                groupPersistDTO.setOSMListId(groupInfoDTO.getOSMListId());

            groupPersistDTO.setOsmListIdAndDefultMap(osmListIdAndDefaultMap);
            //osm create group member mdn osm auth flag check
            if (addedMemberMdns != null && !addedMemberMdns.isEmpty() && addedMemberMdnsDTOLst != null && !addedMemberMdnsDTOLst.isEmpty()) {
                Collection<KnCorpSubscriberDTO> pocSubsInfo = contactInfoUtil.getSubscribersInfo(addedMemberMdns, xdmsHome, persisterTxn);
                knLogger.debug(methodName, "pocSubsInfo - ", pocSubsInfo, KnGDPRTemplate.mdnList(addedMemberMdns));
                groupPersistDTO.setPocSubsInfo(pocSubsInfo);
                groupPersistDTO.setAddedMemberMdnsDTOLst(addedMemberMdnsDTOLst);
                if(isMCXGroup){
                    List<String> addedMdnListReq = addedMemberMdnsDTOLst.stream().map(q -> q.getMdn()).collect(Collectors.toList());
                    Map<String, KnCorpSubscriberDTO> addedMemberDetails
                            = contactInfoUtil.getPoCSubscriberCorporateDetails(addedMdnListReq, xdmsHome, persisterTxn);

                    int dispatcherMdnReqSize = addedMemberDetails.values().stream()
                            .filter(q -> q.getClientType() == DISPATCH_CLIENT.value() || q.getClientType() == THIRDPARTYDISPATCHERCLIENT.value())
                            .map(e -> e.getMdn()).collect(Collectors.toList()).size();
                    //int dispatcherMdnReqSize =subscListDTO.getRequestDispatcherSubscribers().size();
                    int maxAllowedDispatcherPerMcxGroup = paramNameValueMapCommon.get(MAX_DISP_IN_MCXGRP) != null ?
                            Integer.parseInt(paramNameValueMapCommon.get(MAX_DISP_IN_MCXGRP)) : 0;
                    knLogger.debug(methodName,"dispatcherMdnReqSize :",dispatcherMdnReqSize," maxAllowedDispatcherPerMcxGroup :",maxAllowedDispatcherPerMcxGroup);
                    groupPersistDTO.setMaxAllowedDispatcherPerMcxGroup(maxAllowedDispatcherPerMcxGroup);
                    groupPersistDTO.setReachedMaxDispacherAllowedPerMcxGroup(maxAllowedDispatcherPerMcxGroup <= dispatcherMdnReqSize);
                }
            }
            Integer preConfGroup=groupInfoDTO.getIsPreConfiguredGroup();
            boolean isUgwInterop = (null != groupInfoDTO.getUgwInterop() && groupInfoDTO.getUgwInterop().equals(7));
            groupPersistDTO.setCriLocFlag(criFlag);
            groupPersistDTO.setGrpShared(groupInfoDTO.getGrpShared());
            groupPersistDTO.setIsPreConfiguredGroup(groupInfoDTO.getIsPreConfiguredGroup());
            if(isUgwInterop) {
                groupPersistDTO.setUgwInterop(groupInfoDTO.getUgwInterop());
                String ugwInteropFlag = paramNameValueMapCommon.get(UGWINTEROP);
                knLogger.debug(methodName, "Retrieved ugwInterop flag from system config - ", ugwInteropFlag);
                groupPersistDTO.setUgwInteropSystemConfig(ugwInteropFlag);
            }
            List<KnCorpSharedCorpInfo> sharedCorpInfoList = new ArrayList<>();

            if(groupInfoDTO.getCorpSharedCorpInfoList() !=null && groupInfoDTO.getCorpSharedCorpInfoList().size() !=0 &&
                    groupInfoDTO.getGrpShared()!=null && groupInfoDTO.getGrpShared() == GROUP_SHARING_ENABLE_INDICATOR &&
                    groupInfoDTO.getGroupProfileId()!=null) {
                groupPersistDTO.setCorpSharedCorpInfoList(groupInfoDTO.getCorpSharedCorpInfoList());
                injectSourceHierarchyId(groupInfoDTO.getCorpSharedCorpInfoList(), groupInfoDTO.getHierarchyId());
                Set<String> extCorpIds = sharedCorpInfoList.stream().map(KnCorpSharedCorpInfo::getExtCorpId).collect(Collectors.toSet());
                Set<Integer> intCorpIds = sharedCorpInfoList.stream().map(KnCorpSharedCorpInfo::getCorpId).collect(Collectors.toSet());
                knLogger.debug(methodName,"Fetching shared corp information - ",extCorpIds," intCorpIds - ",intCorpIds);
                Map<String,Integer> extIntCorpIDMap = commonInfoUtil.getCorpIdMap(extCorpIds,intCorpIds,persisterTxn);
                knLogger.debug(methodName,"extIntCorpIDMap - ",extIntCorpIDMap);
                groupPersistDTO.setExtIntCorpIdMap(extIntCorpIDMap);
                List<KnCorpTrustMatrixDTO> trustMatrixDTOList = generalCacheUtil.getSharedCorpMatrix(corpProfile.getExtCorpId().trim());
                // P6-3: Pre-fetch hierarchy mappings for each trust matrix entry with a recId,
                // so the validator can check hierarchy scope without making DB calls.
                enrichTrustMatrixWithHierarchyMappings(trustMatrixDTOList);
                groupPersistDTO.setTrustMatrixDTOList(trustMatrixDTOList);
            }
            else{
                knLogger.debug(methodName, "Proceeding create group ..as regular flow");
                if(groupInfoDTO.getCorpSharedCorpInfoList() !=null && groupInfoDTO.getCorpSharedCorpInfoList().size() !=0 && groupInfoDTO.getGrpShared() == GROUP_SHARING_ENABLE_INDICATOR ){
                    List<KnCorpSharedCorpInfo> corpSharedCorpInfos = groupInfoDTO.getCorpSharedCorpInfoList();
                    groupPersistDTO.setCorpSharedCorpInfoList(corpSharedCorpInfos);
                    injectSourceHierarchyId(corpSharedCorpInfos, groupInfoDTO.getHierarchyId());
                    Set<String> extCorpIds = corpSharedCorpInfos.stream().map(KnCorpSharedCorpInfo::getExtCorpId).collect(Collectors.toSet());
                    Set<Integer> intCorpIds = corpSharedCorpInfos.stream().map(KnCorpSharedCorpInfo::getCorpId).collect(Collectors.toSet());
                    knLogger.debug(methodName,"Fetching shared corp information - ",extCorpIds," intCorpIds - ",intCorpIds);
                    Map<String,Integer> extIntCorpIDMap = commonInfoUtil.getCorpIdMap(extCorpIds,intCorpIds,persisterTxn);
                    knLogger.debug(methodName,"extIntCorpIDMap - ",extIntCorpIDMap);
                    groupPersistDTO.setExtIntCorpIdMap(extIntCorpIDMap);
                    List<KnCorpTrustMatrixDTO> trustMatrixDTOList = generalCacheUtil.getSharedCorpMatrix(corpProfile.getExtCorpId().trim());
                    // P6-3: Pre-fetch hierarchy mappings for each trust matrix entry with a recId,
                    // so the validator can check hierarchy scope without making DB calls.
                    enrichTrustMatrixWithHierarchyMappings(trustMatrixDTOList);
                    groupPersistDTO.setTrustMatrixDTOList(trustMatrixDTOList);
                }
            }
            groupPersistDTO.setParamNameValueMapCommon(paramNameValueMapCommon);
            groupPersistDTO.setCorpProfile(corpProfile);
            groupPersistDTO.setMcxGrpInd(groupInfoDTO.getMcxGrpInd());
            groupPersistDTO.setMcxGroup(isMCXGroup);
            int maxDbPreConfigGroupCount = groupInfoUtil.getSystemPreConfigGroupCont(xdmsHome,persisterTxn);
            groupPersistDTO.setSystemMaxAllowedPreConfigGroup(maxPreConfigGroup);
            groupPersistDTO.setDbPreConfiguredGroupCount(maxDbPreConfigGroupCount);
            groupPersistDTO.setIsPreConfiguredGroup(groupInfoDTO.getIsPreConfiguredGroup());
            if(isUgwInterop) {
                groupPersistDTO.setUgwInterop(groupInfoDTO.getUgwInterop());
            }
            groupPersistDTO.setAuthorizedLargeTG(groupInfoDTO.getAuthorizedLargeTG());
            groupPersistDTO.setLargeGroup(isLargeGroup);
            groupPersistDTO.setCorpId(corpId);

            //performs business validation
            knLogger.debug(methodName, "Invoking ValidationFW. DTO - ", groupPersistDTO);
            validatorFW.validate(groupPersistDTO);
            knLogger.debug(methodName, "Validation completed Successfully.");

            if (isUgwInterop) {
                boolean isGroupProfileNotifyRequired = commonInfoUtil.isGroupProfileNotifyRequired(corpId, persisterTxn);
                if (isGroupProfileNotifyRequired) {
                    //Update the UGWINTEROP
                    commonInfoUtil.updateLmrInterOpInDB(corpId, ENABLED, persisterTxn);
                    respDto.setIntCorpId(corpProfile.getCorpId());
                    respDto.setExtCorpId(corpProfile.getExtCorpId());
                    respDto.setNetworkName(corpProfile.getNetworkName());
                    respDto.setCorpNotification(true);
                }
            }

            KnCorpGroupInfoPersistDTO groupInfoPersistDTO = new KnCorpGroupInfoPersistDTO();
            String hierachyRoot=null;
            String hierarchyId=groupInfoDTO.getHierarchyId();
            // ABDG: hierarchyId — derive from group owner's subscriber profile
            if (groupInfoDTO.getGroupCreatedBy() == CREATED_BY.ABDG.value()
                    && hierarchyId == null
                    && groupInfoDTO.getTpGroupOwner() != null) {
                try {
                    String ownerHierarchyId = groupInfoUtil.getSubscriberHierarchyId(
                            groupInfoDTO.getTpGroupOwner(), xdmsHome, persisterTxn);
                    if (ownerHierarchyId != null && !ownerHierarchyId.isEmpty()) {
                        hierarchyId = ownerHierarchyId;
                        groupInfoDTO.setHierarchyId(hierarchyId);
                        knLogger.info(methodName, "ABDG: derived hierarchyId from group owner: ", ownerHierarchyId);
                    }
                } catch (KnDAOException e) {
                    knLogger.warn(methodName, "ABDG: failed to retrieve hierarchyId from group owner, proceeding with null - ", e);
                }
            }
            String pttServerID = genInfoUtil.retrieveLocalXDMPttServerId();
            if(hierarchyId != null) {
                hierachyRoot= KnCorpCommonInfoUtil.getHierachyRoot(corpId, hierarchyId, persisterTxn,pttServerID);
            }
            knLogger.info(methodName, "==>hierachyRoot : ", hierachyRoot);
            //todo not needed remove the code and remove from the insert
            String groupName = groupInfoDTO.getGroupDisplayName();
            if (groupName.equals(groupPersistDTO.getGroupDisplayName())) {
                //generating random groupName
                String newRandomName = groupName + groupPersistDTO.getCorpGroupCount();
                groupInfoPersistDTO.setGroupDisplayName(newRandomName);
            }
            KnGenInfoUtil genInfoUtil = KnGenInfoUtil.getInstance();

            int groupId = genInfoUtil.retrieveIdForTable(CORP_GROUP_INFO_TABLE, xdmsHome, CORP_GROUP_INFO_TABLE_PK, false, DUAL_DATA_STORE);
            //Step:
            //create private sublist for group
            int privateGroupListId = genInfoUtil.retrieveIdForTable(CORP_LIST_TABLE, xdmsHome, CORP_LIST_TABLE_PK, false, DUAL_DATA_STORE);
            KnCorpSublistDTO sublistDTO = new KnCorpSublistDTO();
            sublistDTO.setSublistId(privateGroupListId);
            sublistDTO.setCorpId(corpId);
            sublistDTO.setSublistName(PRIVATE_GROUP_LIST_NAME + groupId);
            sublistDTO.setDistributionPolicy(LIST_DIST_POLICY_NO_DIST);
            sublistDTO.setSublistType(LIST_TYPE_PRIVATE_GRPMEMLIST);
            sublistInfoUtil.createSubListDetails(privateMemberList, sublistDTO, xdmsHome, persisterTxn);
            groupInfoPersistDTO.setGroupMemberListId(privateGroupListId);
            addedSublistIds.add(privateGroupListId); //adding private list as well

            //Step:
            //create the group details
            int etag = INITIAL_ETAG;
            groupInfoPersistDTO.setGroupId(groupId);
            groupInfoPersistDTO.setGroupDisplayName(groupName);
            groupInfoPersistDTO.setCorpId(corpId);
            groupInfoPersistDTO.setETag(etag);
            groupInfoPersistDTO.setGroupType(groupInfoDTO.getGroupType());
            if (groupInfoDTO.getGroupCreatedBy() != CREATED_BY.ABDG.value()) {
                groupInfoPersistDTO.setGroupDistPolicy(DEFAULT_GROUP_DIST_POLICY);
            } else {
                groupInfoPersistDTO.setGroupDistPolicy(ABDG_GROUP_DIST_POLICY);
            }
            int localClusterId = Integer.parseInt(System.getenv(CLUSTERID_ENV_NAME));
            boolean validCorpPocHome = pocHome != null && !pocHome.trim().isEmpty() && !pocHome.trim().equals("0");
            knLogger.debug(methodName, " createGroup: corpPocHome=", pocHome, " validCorpPocHome=", validCorpPocHome, " memberCount=", memberCount, " pochomeAutoAssignFlag=", pochomeAutoAssignFlag," isPreConfiguredGroup ",groupInfoDTO.getIsPreConfiguredGroup());
            if(!pochomeAutoAssignFlag){
                if (groupInfoDTO.getGroupCreatedBy() == CREATED_BY.ABDG.value()) {
                    List<String> groupOwner = new ArrayList<>();
                    if(groupInfoDTO.getTpGroupOwner() != null)groupOwner.add(groupInfoDTO.getTpGroupOwner());
                    Map<String,Object> pocHomeMap = groupInfoUtil.getPocHomeAndClusterIdForCorpGroup(groupOwner,xdmsHome,persisterTxn);
                    pocHome = (String) pocHomeMap.get(POCHOME);
                    groupInfoPersistDTO.setPocHome(pocHome);
                    groupInfoPersistDTO.setClusterId((Integer) pocHomeMap.get(CLUSTERID));
                }else if(groupInfoDTO.getIsPreConfiguredGroup() != null && groupInfoDTO.getIsPreConfiguredGroup() == 1){
                    if(validCorpPocHome){
                        String clusterIdValue = groupInfoUtil.fetchClusterId(pocHome, String.valueOf(localClusterId));
                        groupInfoPersistDTO.setPocHome(pocHome);
                        if (clusterIdValue != null) {
                            groupInfoPersistDTO.setClusterId(Integer.valueOf(clusterIdValue));
                        }
                    }else{
                        pocHome = groupInfoUtil.getPocHomeByHierarchyId(corpId,hierarchyId,xdmsHome,persisterTxn);
                        groupInfoPersistDTO.setPocHome(pocHome);
                        String clusterIdValue = null;
                        if(pocHome!=null)clusterIdValue = groupInfoUtil.fetchClusterId(pocHome, String.valueOf(localClusterId));
                        if (clusterIdValue != null) {
                            groupInfoPersistDTO.setClusterId(Integer.valueOf(clusterIdValue));
                        }
                    }
                }else{
                    if(memberCount == 0){
                        if (validCorpPocHome) {
                            String clusterIdValue = groupInfoUtil.fetchClusterId(pocHome, String.valueOf(localClusterId));
                            groupInfoPersistDTO.setPocHome(pocHome);
                            if (clusterIdValue != null) {
                                groupInfoPersistDTO.setClusterId(Integer.valueOf(clusterIdValue));
                            }
                            knLogger.debug(methodName, "createGroup 0-member validPocHome branch: setting pocHome=", pocHome, " clusterId=", clusterIdValue);
                        } else {
                            groupInfoPersistDTO.setPocHome(null);
                            groupInfoPersistDTO.setClusterId(null);
                            knLogger.debug(methodName, "createGroup 0-member invalidPocHome branch: setting pocHome=null clusterId=null");
                        }
                    }else{
                        knLogger.debug(methodName," allMdnList for deciding POCHOME :",allMdnList);
                        Map<String, Object> pochomeMap = groupInfoUtil.getPocHomeAndClusterIdForCorpGroup(allMdnList,xdmsHome,persisterTxn);
                        pocHome = (String) pochomeMap.get(POCHOME);
                        groupInfoPersistDTO.setPocHome(pocHome);
                        groupInfoPersistDTO.setClusterId((Integer) pochomeMap.get(CLUSTERID));
                        knLogger.debug(methodName, " createGroup memberCount>0 branch: setting pocHome=", pocHome);
                    }
                }
            }else{
                if (validCorpPocHome) {
                    String clusterIdValue = groupInfoUtil.fetchClusterId(pocHome, String.valueOf(localClusterId));
                    groupInfoPersistDTO.setPocHome(pocHome);
                    if (clusterIdValue != null) {
                        groupInfoPersistDTO.setClusterId(Integer.valueOf(clusterIdValue));
                    }
                    knLogger.debug(methodName, "createGroup autoAssign validPocHome branch: setting pocHome=", pocHome, " clusterId=", clusterIdValue);
                } else {
                    groupInfoPersistDTO.setPocHome(null);
                    groupInfoPersistDTO.setClusterId(null);
                    knLogger.debug(methodName, "createGroup autoAssign invalidPocHome branch: setting pocHome=null clusterId=null");
                }
            }
            groupInfoPersistDTO.setOverrideDnd(groupInfoDTO.getOverrideDnd());
            groupInfoPersistDTO.setHangTimeOut(groupInfoDTO.getHangTimeOut());
            groupInfoPersistDTO.setEmergHangTimeAddOn(groupInfoDTO.getEmergHangTimeAddOn());
            groupInfoPersistDTO.setEmergOverrideDND(groupInfoDTO.getEmergOverrideDND());
            groupInfoPersistDTO.setEmergAutoFloorTimer(groupInfoDTO.getEmergAutoFloorTimer());
            groupInfoPersistDTO.setLargeGroup(isLargeGroup);
            if (groupInfoDTO.getAvatar() != null && groupInfoDTO.getAvatar() != AVATAR_NOT_MODIFIED) {
                groupInfoPersistDTO.setAvatar(groupInfoDTO.getAvatar());
            }
            if (groupInfoDTO.getVideoPermission() != null) {
                groupInfoPersistDTO.setVideoPermission(groupInfoDTO.getVideoPermission());
            }
            if (null != groupInfoDTO.getUgwInterop()) {
                groupInfoPersistDTO.setUgwInterop(groupInfoDTO.getUgwInterop());
            }
            for (KnCorpSubscriberDTO corpSubsDto : actualMdnToBeAddedToGroup) {
                if (corpSubsDto.getClientType() == GROUPMDN.value()
                        || corpSubsDto.getClientType() == SUBSCR_CLIENT_TYPE.SGMDNPATCH.value()) {
                    groupInfoPersistDTO.setLmrInteropCapable(LMR_INTEROP_CAPABLE);
                    groupInfoPersistDTO.setUgwInterop(UGWINTEROP_DBVALUE);
                    break;
                }
            }

            groupInfoPersistDTO.setTpGroupOwner(groupInfoDTO.getTpGroupOwner());
            groupInfoPersistDTO.setGroupCreatedBy(groupInfoDTO.getGroupCreatedBy());
            groupInfoPersistDTO.setOSMListId(groupPersistDTO.getOSMListId());
            groupInfoPersistDTO.setMcxGrpInd(groupInfoDTO.getMcxGrpInd());
            groupInfoPersistDTO.setGroupProfileId(groupInfoDTO.getGroupProfileId());
            groupInfoPersistDTO.setGroupServiceType(groupInfoDTO.getGroupServiceType());
            groupInfoPersistDTO.setFeatureAllowed(groupInfoDTO.getFeatureAllowed());
            groupInfoPersistDTO.setAudioCutIn(groupInfoDTO.getAudioCutIn());
            groupInfoPersistDTO.setGrpShared(groupInfoDTO.getGrpShared());
            groupInfoPersistDTO.setIsPreConfiguredGroup(groupInfoDTO.getIsPreConfiguredGroup());
            groupInfoPersistDTO.setAuthorizedLargeTG(groupInfoDTO.getAuthorizedLargeTG());
            groupInfoPersistDTO.setHierarchyId(groupInfoDTO.getHierarchyId());
            groupInfoPersistDTO.setHierarchyRoot(hierachyRoot);
            groupInfoUtil.createGroupInfoDetails(groupInfoPersistDTO, xdmsHome, persisterTxn);

            //Step:
            //associate sublistIds to group
            groupInfoUtil.addSublistsToGroup(groupId, addedSublistIds, xdmsHome, persisterTxn);

            //add entry into the XDM_CorpGroupDoc document
            /* Map<String, KnOPDirChgDTO> changeLogMap =
         groupInfoUtil.addEntryToXDMCorpGroupDoc(membersToBeAddedInGroupDocument, groupId, xdmsHome, persisterTxn);*/

            groupInfoUtil.addToCorpGroupDistInfo(membersToBeAddedInGroupDocument, groupId, xdmsHome, persisterTxn);

            if(groupInfoDTO.getGrpShared()!= null && groupInfoDTO.getGrpShared() == GROUP_SHARING_ENABLE_INDICATOR){

                // Insert into CORPGRP_SHAREDLIST — exclude self-corp entries (same corp cannot be both owner and shared;
                // hierarchy associations are tracked separately in GROUP_HIERARCHY_MAP)
                groupPersistDTO.setCorpId(corpId);
                groupPersistDTO.setGroupId(groupId);
                List<KnCorpSharedCorpInfo> nonSelfSharedList = new ArrayList<>();
                if (groupPersistDTO.getCorpSharedCorpInfoList() != null) {
                    for (KnCorpSharedCorpInfo info : groupPersistDTO.getCorpSharedCorpInfoList()) {
                        if (!Objects.equals(info.getCorpId(), corpId)) {
                            nonSelfSharedList.add(info);
                        }
                    }
                }
                if (!nonSelfSharedList.isEmpty()) {
                    KnCorpGroupInfoPersistDTO sharedCorpDto = new KnCorpGroupInfoPersistDTO();
                    sharedCorpDto.setCorpId(corpId);
                    sharedCorpDto.setGroupId(groupId);
                    sharedCorpDto.setCorpSharedCorpInfoList(nonSelfSharedList);
                    List<KnCorpGroupInfoPersistDTO> groupInfoPersistDTOList = new ArrayList<>();
                    groupInfoPersistDTOList.add(sharedCorpDto);
                    groupInfoUtil.createGroupSharedCorpInfo(groupInfoPersistDTOList, xdmsHome, persisterTxn);
                }

                // P6-3 Step C: insert GROUP_HIERARCHY_MAP rows from hierarchyList (sharedHierarchyId is already an internal ID)
                List<KnCorpSharedCorpInfo> sharedList = groupPersistDTO.getCorpSharedCorpInfoList();
                if (sharedList != null) {
                    List<String> hierarchyIds = new ArrayList<>();
                    List<Integer> hierCorpIds = new ArrayList<>();
                    for (KnCorpSharedCorpInfo info : sharedList) {
                        List<KnXDMHierarchyInfo> hierList = info.getHierarchyList();
                        if (hierList != null && !hierList.isEmpty() && info.getCorpId() != null) {
                            for (KnXDMHierarchyInfo hierInfo : hierList) {
                                String sharedHierarchyId = hierInfo.getSharedHierarchyId();
                                if (sharedHierarchyId != null && !sharedHierarchyId.isEmpty()) {
                                    hierarchyIds.add(sharedHierarchyId);
                                    hierCorpIds.add(info.getCorpId());
                                }
                            }
                        }
                    }
                    if (!hierarchyIds.isEmpty()) {
                        knLogger.debug(methodName, "P6-3: Inserting shared group hierarchy map for groupId=", groupId, " count=", hierarchyIds.size());
                        groupInfoUtil.insertSharedGroupHierarchyMap(groupId, hierarchyIds, hierCorpIds, xdmsHome, persisterTxn);
                    }
                }
            }

            //setting external members
            if(!externalMdnList.isEmpty()){
                knLogger.debug(methodName," externalMdnList :",externalMdnList);
                memberList.addAll(externalMdnList);
                groupInfoDTO.setExternalMdnList(externalMdnList);
            }
            knLogger.debug(methodName," memberList :",memberList);
            //update etags
            Map<Integer, Integer> groupEtagMap = new HashMap<Integer, Integer>();
            groupEtagMap.put(groupId, etag);
            Map<Integer, Collection<String>> grpMemMap = new HashMap<Integer, Collection<String>>();
            grpMemMap.put(groupId, memberList);
            Map<Integer, KnCorpGroupDTO> groupDetailsMap = new HashMap<Integer, KnCorpGroupDTO>();
            groupDetailsMap.put(groupId, groupInfoDTO);

            List<String> preConfigGroupMdns=new ArrayList<>();
            boolean isPreConfGroup=preConfGroup!=null&&preConfGroup.equals(ENABLED);
            Integer grpShared = groupInfoDTO.getGrpShared();
            if(isPreConfGroup){
                List<Integer> intSharedCorpIds =new ArrayList<>();
                if(grpShared!=null&&grpShared.equals(ENABLED)){
                    List<KnCorpSharedCorpInfo> corpSharedCorpInfos = groupInfoDTO.getCorpSharedCorpInfoList();
                    intSharedCorpIds = corpSharedCorpInfos.stream().map(KnCorpSharedCorpInfo::getCorpId).collect(Collectors.toList());
                }
                preConfigGroupMdns=commonInfoUtil.getAllPreConfigGroupMdns(corpId,grpShared,intSharedCorpIds,xdmsHome, persisterTxn);
                grpMemMap.put(groupId, preConfigGroupMdns);
            }
            //Sending notify to to all the base mdns+ baseMdns profile mdns of the ABDG group
            if (AREA_BASED_DYNAMIC_GROUP == groupInfoDTO.getClientType() && !memberList.isEmpty()) {
                Map<String, List<String>> profileBaseMdnMap = corpSubsProvInfoUtil.getMapOfProfileMdnByBaseMdn(new ArrayList<>(memberList), xdmsHome, persisterTxn);
                if (!profileBaseMdnMap.isEmpty()) {
                    ArrayList<String> profileMdns = new ArrayList<>();
                    profileBaseMdnMap.values().forEach(profileMdns::addAll);
                    knLogger.debug(methodName, " fetched all the profile mdns ", KnGDPRTemplate.mdnList(profileMdns));
                    grpMemMap.get(groupId).addAll(profileMdns);
                }
            }

            Map<String, KnOPDirChgDTO> etagMap =new HashMap<>();
            etagMap = commonInfoUtil.formSubscriberNotification(grpMemMap, groupEtagMap,
                    com.kodiak.xdms.server.common.resources.KnConstants.DOC_CHANGE_TYPE.ADD.value(), null, groupDetailsMap, groupInfoDTO.getGroupCreatedBy());
            if(!preConfigGroupMdns.isEmpty()){
                etagMap = contactInfoUtil.updateSetSubcribersDirectory(preConfigGroupMdns, etagMap, xdmsHome, persisterTxn);
            }

            if(!groupInfoDTO.isUpmCall()) {
                Map<String, Collection<KnDocChangeListDTO>> profileMdnEtagMap = corpUserProfileUtil.profileMdnEtagUpdateForCreateGroup(
                        null
                        , String.valueOf(corpId),addedMemberMdns.stream().toList()
                        ,"1", xdmsHome, persisterTxn);
                respDto.setProfileMdnEtagMap(profileMdnEtagMap);
                if (profileMdnEtagMap != null && !profileMdnEtagMap.isEmpty()) {
                    respDto.setMcsXcapRootUriMap(genInfoUtil.getXCAPRootURI(new ArrayList<>(profileMdnEtagMap.keySet()), persisterTxn, true));
                }
            }
            //Step:todo
            Collection<KnCorpContactDTO> memberListToBeAdded = new ArrayList<KnCorpContactDTO>();
            Collection<String> locWatcherMember = new ArrayList<>();
            Collection<String> mcxDispatcherLocWatcherMember = new ArrayList<>();
            Collection<String> mcxCRIMember = new ArrayList<>();
            Collection<String> totalMemMdn = new ArrayList<>();
            int isAffiliation=DISABLED;
            for (KnCorpSubscriberDTO corpSubsDto : actualMdnToBeAddedToGroup) {
                KnCorpContactDTO contact = new KnCorpContactDTO();
                String mdn = corpSubsDto.getMdn();
                //boolean isOSMAuthorizeBit = KnGeneralUtil.getFeatureBitValue(corpSubsDto.getSubsActiveFS2(), IS_OSM_AUTHORIZE_BIT);
                boolean dispatcher = corpSubsDto.getClientType() == DISPATCH_CLIENT.value() || corpSubsDto.getClientType() == THIRDPARTYDISPATCHERCLIENT.value();

                contact.setMdn(mdn);
                totalMemMdn.add(mdn);
                Integer supervisor = supervisorMembers.get(mdn);
                Integer locWatcher = locWatcherMap.get(mdn);
                int clientType = corpSubsDto.getClientType();
                if(isMCXGroup&&corpSubsDto.getMcpttCompliance() == MCPTT_COMPLIANCE){
                    mcxCRIMember.add(mdn);
                }
                if (supervisor != null) {
                    contact.setSupervisory(supervisor);
                } else {
                    contact.setSupervisory(0);
                }
                if (locWatcher != null && locWatcher == LOCWATCHER) {
                    contact.setLocWatcher(locWatcher);
                    locWatcherMember.add(mdn);
                    if(isMCXGroup&&dispatcher){
                        mcxDispatcherLocWatcherMember.add(mdn);
                    }
                } else {
                    contact.setLocWatcher(0);
                }
                if (clientType == GROUPMDN.value()) {
                    contact.setMemberType(SG_MDN_MEMBER_TYPE);
                } else if (clientType == SUBSCR_CLIENT_TYPE.SGMDNPATCH.value()) {
                    contact.setMemberType(SG_MDN_PATCH_MEMBER_TYPE);
                }
                //Modified for 8.1.1 changes
                if (addedMemberMdnsDTOLst != null) {
                    for (KnCorpContactDTO corpContact : addedMemberMdnsDTOLst) {
                        if (corpContact.getMdn().equalsIgnoreCase(mdn)) {
                            contact.setCallInitiatePermission(corpContact.getCallInitiatePermission());
                            contact.setCallReceivePermission(corpContact.getCallReceivePermission());
                            contact.setInCallPermission(corpContact.getInCallPermission());
                            contact.setVideoCallInitiatePermission(corpContact.getVideoCallInitiatePermission());
                            contact.setVideoCallReceivePermission(corpContact.getVideoCallReceivePermission());
                            contact.setVideoInCallPermission(corpContact.getVideoInCallPermission());
                            contact.setIsOSMAuthorize(corpContact.getIsOSMAuthorize());
                            if (extMdns.contains(mdn)) {
                                contact.setGroupModifyPerm(DISABLED);
                            } else {
                                contact.setGroupModifyPerm(corpContact.getGroupModifyPerm());
                            }

                            boolean subsFsAffiliation = KnGeneralUtil.getFeatureBitValue(corpSubsDto.getSubscriberFs2(), FEATURE_SET.AFFILIATIONFEATURE.value());
                            boolean bitEnabled = KnGeneralUtil.getFeatureBitValue(corpSubsDto.getSubsActiveFS2(), FEATURE_SET.AFFILIATIONFEATURE.value());
                            if ((isMCXGroup&&subsFsAffiliation)
                                    ||(corpSubsDto.getClientPVmajorVer() >= com.kodiak.xdms.server.common.resources.KnConstants.PROTOCOL_VERSION_18
                                    && bitEnabled && checkClientType(corpSubsDto.getClientType(),corpSubsDto.getMcpttCompliance())))
                            {
                                isAffiliation=ENABLED;
                            }else{
                                isAffiliation=DISABLED;
                            }
                            contact.setIsAffiliationEnabled(isAffiliation);

                            break;
                        }
                    }
                }
                if (groupSupervisors != null) {
                    for (KnCorpGroupMemberDTO memberDTO : groupSupervisors) {
                        if (memberDTO.getMdn().equalsIgnoreCase(mdn)) {
                            contact.setCallInitiatePermission(memberDTO.getCallInitiatePermission());
                            contact.setCallReceivePermission(memberDTO.getCallReceivePermission());
                            contact.setInCallPermission(memberDTO.getInCallPermission());
                            contact.setVideoCallInitiatePermission(memberDTO.getVideoCallInitiatePermission());
                            contact.setVideoCallReceivePermission(memberDTO.getVideoCallReceivePermission());
                            contact.setVideoInCallPermission(memberDTO.getVideoInCallPermission());
                            contact.setIsOSMAuthorize(memberDTO.getIsOSMAuthorize());

                            boolean subsFsAffiliation = KnGeneralUtil.getFeatureBitValue(corpSubsDto.getSubscriberFs2(), FEATURE_SET.AFFILIATIONFEATURE.value());
                            boolean bitEnabled = KnGeneralUtil.getFeatureBitValue(corpSubsDto.getSubsActiveFS2(), FEATURE_SET.AFFILIATIONFEATURE.value());

                            if ((isMCXGroup&&subsFsAffiliation)
                                    ||(corpSubsDto.getClientPVmajorVer() >= com.kodiak.xdms.server.common.resources.KnConstants.PROTOCOL_VERSION_18
                                    && bitEnabled && checkClientType(corpSubsDto.getClientType(),corpSubsDto.getMcpttCompliance())))
                            {
                                isAffiliation=ENABLED;
                            }else{
                                isAffiliation=DISABLED;
                            }
                            contact.setIsAffiliationEnabled(isAffiliation);

                            break;
                        }
                    }
                }

                memberListToBeAdded.add(contact);
            }
            Map<Integer, Collection<KnCorpContactDTO>> groupMemberList = new HashMap<Integer, Collection<KnCorpContactDTO>>();

            groupMemberList.put(groupId, memberListToBeAdded);


            groupInfoUtil.insertIntoCorpGroupMemberList(groupMemberList, xdmsHome, persisterTxn);

            if (groupInfoDTO.getGroupType() == STANDARD_GROUP) {
                if (isLargeGroup) {
                    sublistInfoUtil.updateSublistsSubscribersContactCount(addedSublistIds, MAX_LIMIT_VALIDATION_NOT_REQUIRED,
                            corpProfile.getMaxMemPerLrgGrp(), MAX_LIMIT_VALIDATION_NOT_REQUIRED, xdmsHome, persisterTxn, MAX_LIMIT_VALIDATION_NOT_REQUIRED);
                } else {
                    sublistInfoUtil.updateSublistsSubscribersContactCount(addedSublistIds, MAX_LIMIT_VALIDATION_NOT_REQUIRED,
                            corpProfile.getMaxMemPerCorpGroup(), MAX_LIMIT_VALIDATION_NOT_REQUIRED, xdmsHome, persisterTxn, MAX_LIMIT_VALIDATION_NOT_REQUIRED);
                }

            } else {
                if (isLargeGroup) {
                    sublistInfoUtil.updateSublistsSubscribersContactCount(addedSublistIds, MAX_LIMIT_VALIDATION_NOT_REQUIRED,
                            MAX_LIMIT_VALIDATION_NOT_REQUIRED, corpProfile.getMaxMemPerLrgGrp(), xdmsHome, persisterTxn, MAX_LIMIT_VALIDATION_NOT_REQUIRED);
                } else {
                    sublistInfoUtil.updateSublistsSubscribersContactCount(addedSublistIds, MAX_LIMIT_VALIDATION_NOT_REQUIRED,
                            MAX_LIMIT_VALIDATION_NOT_REQUIRED, corpProfile.getMaxMembersPerDispatchGroup(), xdmsHome, persisterTxn, MAX_LIMIT_VALIDATION_NOT_REQUIRED);
                }
            }

            Collection<String> completeMdnList = null;
            Collection<String> groupDistLocMember = new ArrayList<>();
            //If the contact pairing is enable we need to assign each member with the dispatcher and vice versa
            if (groupInfoDTO.getGroupType() == DISPATCH_GROUP) {
                Collection<String> nonDispInterOPMembers = new ArrayList<String>();
                if (membersToBeAddedInGroupDocument != null && !membersToBeAddedInGroupDocument.isEmpty()) {
                    for (KnCorpSubscriberDTO subsc : membersToBeAddedInGroupDocument) {
                        String mdn = subsc.getMdn();
                        if (!dispatcherSubscribers.contains(mdn) && !interOPSubsc.contains(mdn)) {
                            nonDispInterOPMembers.add(mdn);
                        }
                    }
                    Collection<String> dispatchGrpMembers = new ArrayList<String>();
                    dispatchGrpMembers.addAll(interOPSubsc);
                    dispatchGrpMembers.addAll(nonDispInterOPMembers);
                    if ( null != pocMdnPersistDto && null != pocMdnPersistDto.getGroupMdnList() ) {
                        dispatchGrpMembers.removeAll(pocMdnPersistDto.getGroupMdnList());
                    }
                    //set into the response
                    if (!groupPersistDTO.isLargeGroup()) {
                        respDto.setEnabledDispatchMemList(dispatchGrpMembers);
                    }
                }

                if (groupInfoDTO.isContactPairing()) {
                    //remove group mdn from going for assigment of the contact
                    Collection<String> memberToAdd = new ArrayList<String>(nonDispInterOPMembers);
                    if (pocMdnPersistDto != null) {
                        memberToAdd.removeAll(pocMdnPersistDto.getGroupMdnList());
                    }
                    assignContact(memberToAdd, dispatcherSubscribers, externalMemberList, null, corpId,
                            corpProfile.getMaxContactsPerSubsc(), etagMap, xdmsHome, persisterTxn);
                    completeMdnList = new ArrayList<String>();
                    completeMdnList.addAll(nonDispInterOPMembers);
                    completeMdnList.addAll(dispatcherSubscribers);
                }
            }

            //removing locWacther dipatcher client in mcxGroup from contact pairing
            locWatcherMap.keySet().removeAll(mcxDispatcherLocWatcherMember);
            //removing locWacther CRI client in mcxGroup from contact pairing
            locWatcherMap.keySet().removeAll(mcxCRIMember);

            if (locWatcherMap.containsValue(LOCWATCHER)) {
                for (KnCorpSubscriberDTO subs : membersToBeAddedInGroupDocument) {
                    groupDistLocMember.add(subs.getMdn());
                }
                //removing locWacther dipatcher client in mcxGroup from contact pairing
                locWatcherMember.removeAll(mcxDispatcherLocWatcherMember);
                //removing locWacther CRI client in mcxGroup from contact pairing
                locWatcherMember.removeAll(mcxCRIMember);

                // Now we will call contact assignement method.
                contactInfoUtil.contactForSupervisiorLocWatcher(locWatcherMember, totalMemMdn, corpId, corpProfile.getMaxContactsPerSubsc(),
                        etagMap, corpProfile.getXdmsHome(), persisterTxn);

                Collection<String> enabledMember = new HashSet<>();
                if (respDto.getEnabledDispatchMemList() != null) {
                    enabledMember.addAll(respDto.getEnabledDispatchMemList());
                }
                enabledMember.addAll(groupDistLocMember);
                respDto.setEnabledDispatchMemList(enabledMember);
                respDto.setAddedLocWatcherList(locWatcherMember);
            }

            Collection<String> groupDistMember = new ArrayList<>();
            for (KnCorpSubscriberDTO subs : membersToBeAddedInGroupDocument) {
                groupDistMember.add(subs.getMdn());
            }

            if(!isPreConfGroup){
                etagMap = contactInfoUtil.updateDistinctSubcribersDirectory(completeMdnList, groupEtagMap.keySet(), etagMap, xdmsHome, persisterTxn);
            }

            //setting the group id and name in response
            KnCorpGroupInfoDTO knCorpGroupInfoDTO = new KnCorpGroupInfoDTO();
            knCorpGroupInfoDTO.setGroupId(groupId);
            knCorpGroupInfoDTO.setGroupDisplayName(groupInfoDTO.getGroupDisplayName());
            knCorpGroupInfoDTO.setGroupMemberCount(memberCount);
            knCorpGroupInfoDTO.setGrpShared(groupInfoDTO.getGrpShared());
            if (memberCount == maxMemberPerCorpGroup) {
                knCorpGroupInfoDTO.setMaxGroupMemLimitFlag(EQUAL_TO_LIMIT);
            } else {
                knCorpGroupInfoDTO.setMaxGroupMemLimitFlag(LESS_THAN_LIMIT);
            }
            knCorpGroupInfoDTO.setGroupType(groupInfoDTO.getGroupType());

            if (groupInfoDTO.getAvatar() != null && groupInfoDTO.getAvatar() != AVATAR_NOT_MODIFIED) {
                knCorpGroupInfoDTO.setAvatar(groupInfoDTO.getAvatar());
            }
            knCorpGroupInfoDTO.setIsPreConfiguredGroup(groupInfoDTO.getIsPreConfiguredGroup());
            if(isUgwInterop) {
                knCorpGroupInfoDTO.setUgwInterop(groupInfoDTO.getUgwInterop());
            }
            // In case of group creation without any members pochome is set to null hence sipProxyUri as well is set to null.
            String sipProxyUri = null;
            if (pocHome != null) {
                final String finalPocHome = pocHome;
                sipProxyUri = sipProxySvcConfigInfoDTO.stream()
                        .filter(sipProxy -> sipProxy.getPttServerId().equals(finalPocHome))
                        .findFirst()
                        .map(KnSIPProxySvcConfigDTO::getSipProxyURI)
                        .orElse(null);
            }
            knCorpGroupInfoDTO.setGrpSIPUri(commonInfoUtil.mcpttGroupUri(groupId, corpId, sipProxyUri));
            if (null != knCorpGroupInfoDTO.getUgwInterop() && knCorpGroupInfoDTO.getUgwInterop().equals(7)) {
                knCorpGroupInfoDTO.setUgwInterop(UGWINTEROP_DBVALUE);
            } else {
                knCorpGroupInfoDTO.setUgwInterop(groupInfoPersistDTO.getUgwInterop());
            }
            knCorpGroupInfoDTO.setVideoPermission(videoPermission); // fix: use local int (defaults to 0 if input null)
            respDto.setGroupInfoDTO(knCorpGroupInfoDTO);
            //Remove the group mdn from the map as we should not send notifications to the client type 7 subscribers.
            if (pocMdnPersistDto != null) {
                List<String> groupMdns = pocMdnPersistDto.getGroupMdnList();
                for (String mdn : groupMdns) {
                    etagMap.remove(mdn);
                }
            }
            respDto.setChangeLogMap(etagMap);
            LinkedList<KnLIEventDTO> liEventList = populateAddGroupLIData(etagMap
                    , xdmsHome, membersToBeAddedInGroupDocument, groupInfoDTO, externalMdnList,persisterTxn);
            respDto.setLiEventList(liEventList);
            respDto.setEtag(String.valueOf(etag));
            respDto.setAddedGroupDistributionMember(groupDistMember);
            //Since in create group notification, xdm is notr setting diff data. Getting the name and other info and seting
            Map<String, KnSubscriberDTO> memDetails = contactInfoUtil.getSubscribersNameForCorp(new ArrayList<>(totalMemMdn), corpId, xdmsHome, persisterTxn);
            for (KnCorpContactDTO contactDTO : memberListToBeAdded) {
                KnSubscriberDTO subscriberDTO = memDetails.get(contactDTO.getMdn());
                if (null != subscriberDTO) {
                    contactDTO.setName(subscriberDTO.getNetworkName());
                    contactDTO.setClientType(subscriberDTO.getClientType());
                    contactDTO.setContact_type(subscriberDTO.getContact_type());
                    contactDTO.setMcpttCompliance(subscriberDTO.getMcpttCompliance());
                }
            }
            respDto.setAddedGroupMember(memberListToBeAdded);
            respDto.setGroupCreatedBy(groupInfoDTO.getGroupCreatedBy());
            respDto.setMdnCorpId(corpId);
            respDto.setVideoPermission(videoPermission);
            populate(respDto);
            if (responseDTO.getFailedDataList() != null && !responseDTO.getFailedDataList().isEmpty()) {
                respDto.setFailedDataList(responseDTO.getFailedDataList());
            }
            //If the corporate is already linked i.e linked gateway key is not null get the refernce id
            if (corpProfile.getLinkedGwKey() != null && pocMdnPersistDto != null && pocMdnPersistDto.isGrpMdnPresent()) {
                //get the refernce id from the account info table.
                KnCorpGWLinkedAccountInfoDTO accountInfo = commonInfoUtil.getCorporateLinkedAccountInfo(corpProfile.getLinkedGwKey(), xdmsHome, persisterTxn);
                //update etag in the account info table
                //update etag
                Map<String, String> asyncInput = new HashMap<>();
                asyncInput.put(KnDbSyncFwConstants.PTTSERVER_ID, xdmsHome);
                asyncInput.put(KnDbSyncFwConstants.NNI_REF_ID, accountInfo.getNniRefId());
                knLogger.debug(methodName, " Async inputs", asyncInput);
                KnSqlJobCollector collector = KnSqlJobCollector.getInstance();
                int serviceType = KnDbSyncFwConstants.EXECUTOR.ETAG_UPDATE_NNI.value();
                collector.collect(serviceType, asyncInput);

            }
            //populate GROUP_HIERARCHY_MAP
            if (groupInfoDTO.getHierarchyType() == HIERARCHY_TYPE.HIERARCHY) {
                String idType = (String) customParams.get(IDTYPE);
                List<String> ownerIdList = groupInfoDTO.getOwnerIdList();
                knLogger.info(methodName, "Enter into hierarchy path with groupId,ownerIdList ", groupId, ownerIdList);
                if (null != ownerIdList && !ownerIdList.isEmpty()) {
                    groupInfoUtil.insertGroupHiearchyMap(groupId, ownerIdList, idType, xdmsHome, persisterTxn);
                } else {
                    List<String> idListStr = (List<String>) customParams.get(com.kodiak.common.resources.KnConstants.IDLIST);
                    knLogger.info(methodName, "idListStr::", idListStr);
                    groupInfoUtil.insertGroupHiearchyMap(groupId, idListStr, idType, xdmsHome, persisterTxn);
                }
            }

            //Changes for PDMBB-12990
            //Assign Zones and Position
            //If new flag is not null and is enabled then only do below
            String autoAssignZoneChannelFlag = genInfoUtil.retrieveMSSvcsCommonConfig(clusterId, persisterTxn)
                    .get(AUTO_ASSIGN_ZONE_POSITION);
            knLogger.debug(methodName, "autoAssignZoneChannelFlag:", autoAssignZoneChannelFlag);
            // If auto-assign is disabled, return disabled status
            if (autoAssignZoneChannelFlag != null && autoAssignZoneChannelFlag.equals("1") && (memberListToBeAdded != null && !memberListToBeAdded.isEmpty()) && !isMCXGroup && groupInfoDTO.getGroupCreatedBy() != CREATED_BY.ABDG.value()) {
                Map<String, Object> assignmentResult = performAutoAssignZonesAndChannels(
                        Arrays.asList(groupId),
                        memberListToBeAdded,
                        corpProfile,
                        contactInfoUtil,
                        persisterTxn
                );
                String autoZonePositionStatus = (String) assignmentResult.get("status");
                // After performAutoAssignZonesAndChannels succeeds update notification with zone/channel data
                if (ZONE_ASSIGNMENT_STATUS.ASSIGNED.value().equals(autoZonePositionStatus) || ZONE_ASSIGNMENT_STATUS.PARTIAL.value().equals(autoZonePositionStatus)) {
                    etagMap = updateAddlTGNotification(groupId, etagMap, xdmsHome, persisterTxn);
                    respDto.setChangeLogMap(etagMap);
                }
                List<String> unassignedMdns = (List<String>) assignmentResult.get("unassignedMdns");
                respDto.setZonePositionAssignmentStatus(autoZonePositionStatus);
                if (unassignedMdns != null && !unassignedMdns.isEmpty()) {
                    respDto.setUnassignedMdns(unassignedMdns);
                }
                knLogger.debug(methodName, "respDto with zonePositionAssignmentStatus:", respDto.getZonePositionAssignmentStatus());
            }
            else{
                respDto.setZonePositionAssignmentStatus(ZONE_ASSIGNMENT_STATUS.DISABLED.value());
                knLogger.info(methodName, "Auto-assignment disabled. Status:", respDto.getZonePositionAssignmentStatus());
            }
        } catch (KnValidationException ve) {
            knLogger.error(methodName, "KnValidationException occured while create Group - ", ve);
            populate(respDto, ve);

        } catch (KnCorpBOException be) {
            knLogger.error(methodName, "KnCorpBOException occured while create Group - ", be);
            knLogger.debug(methodName, "Error Code recieved is  - ", be.getErrorCode());
            if (be.getErrorCode().equalsIgnoreCase(KnErrorCodes.DAO.ROW_ALREADY_EXISTS_GROUP_DOC)) {
                knLogger.debug(methodName, "Initiate the refresh of data as unique constraint error occurred in Db - ", be.getErrorCode());
                KnIdGeneratorImpl idGenerator = KnIdGeneratorImpl.getInstance();
                String tableName = "DG.XDM_CORP_GROUPDOC";
                tableName = tableName.toUpperCase();
                KnTableInfoBean tableInfoBean = new KnTableInfoBean();
                tableInfoBean.setColumnName("CORPGROUPDOCID");
                tableInfoBean.setTableName(tableName);
                tableInfoBean.setPttServerId(xdmsHome);
                List<KnTableInfoBean> tableList = new ArrayList<KnTableInfoBean>();
                tableList.add(tableInfoBean);
                knLogger.debug(methodName, "Before  call to the reInitialise of the ids");
                idGenerator.reInitialiseIds(tableList);
                knLogger.debug(methodName, "After  call to the reInitialise of the ids");
            }
            populate(respDto, be);

        } catch (Exception e) {
            knLogger.error(methodName, "KnValidationException occured while create Group - ",
                    new KnException(KnErrorCodes.BOEntity.INTERNAL_ERROR, e.getMessage(), e));
            populate(respDto, e);

        }
        knLogger.debug(methodName, "respDto with autoZonePositionStatus: ", respDto);
        return respDto;
    }

    private boolean checkClientType(Integer clientType,int mcsCompliance)
    {
        return clientType == SUBSCR_CLIENT_TYPE.PTTRADIOHANDSETCLIENT.value()
                || clientType == SUBSCR_CLIENT_TYPE.PTTRADIOCROSSCARRIERCLIENT.value()
                || clientType == SUBSCR_CLIENT_TYPE.PTTRADIOWIFIONLYCLIENT.value()
                || clientType == SUBSCR_CLIENT_TYPE.DISPATCH_CLIENT.value()
                || clientType == SUBSCR_CLIENT_TYPE.THIRDPARTYDISPATCHERCLIENT.value()
                || mcsCompliance == MCPTT_COMPLIANCE;
    }

    /**
     * Retrieving thespecific subscribers interOP and dispatchers from the list of Db subscribers List
     * based on the client type retieved from DB for the subscriber
     *
     * @param addedMdnDTO
     */
    private KnCorpGroupInfoPersistDTO populateDbSpecificSubscInList(Collection<KnCorpSubscriberDTO> addedMdnDTO) {
        String methodName = "populateDbSpecificSubscInList(Collection<KnCorpSubscriberDTO>)";
        knLogger.info(methodName, "ENTRY : ");
        KnCorpGroupInfoPersistDTO groupInfoDTO = new KnCorpGroupInfoPersistDTO();
        Set<String> dispatcherSubscribers = new HashSet<String>();
        Set<String> interOPSubsc = new HashSet<String>();
        Map<String, Integer> subscSupVal = new HashMap<String, Integer>();
        for (KnCorpSubscriberDTO subsc : addedMdnDTO) {
            int subscClientType = subsc.getClientType();
            if (subscClientType == DISPATCH_CLIENT.value()
                    || subscClientType == THIRDPARTYDISPATCHERCLIENT.value()) {
                dispatcherSubscribers.add(subsc.getMdn());
                subscSupVal.put(subsc.getMdn(), DISPATCHER);
            } else if (subscClientType == INTER_OP_CLIENT_TYPE) {
                interOPSubsc.add(subsc.getMdn());
                subscSupVal.put(subsc.getMdn(), INTER_OP);
            }
        }
        groupInfoDTO.setRequestDispatcherSubscribers(dispatcherSubscribers);
        groupInfoDTO.setReqInterOpSubs(interOPSubsc);
        groupInfoDTO.setSubscSupVals(subscSupVal);
        knLogger.debug(methodName, "Exit : ");
        return groupInfoDTO;
    }

    /**
     * This method is used to populate the dispatchers and interop
     *
     * @param addedMemberMdnsDTOLst
     * @return
     */

    private KnCorpGroupInfoPersistDTO populateSpecficSubscInList(Collection<KnCorpContactDTO> addedMemberMdnsDTOLst) {
        String methodName = "populateSpecficSubscInList(Collection<KnCorpContactDTO>)";
        knLogger.debug(methodName, "ENTRY : ");
        KnCorpGroupInfoPersistDTO subscPersistDTO = new KnCorpGroupInfoPersistDTO();
        Collection<KnCorpGroupMemberDTO> addedMemberSupervisor = new ArrayList<KnCorpGroupMemberDTO>();
        Collection<KnCorpGroupMemberDTO> locWatcherList = new ArrayList<KnCorpGroupMemberDTO>();
        Set<String> dispatcherSubscribers = new HashSet<String>();
        Set<String> interOPSubsc = new HashSet<String>();
        Collection<String> addedMemberMdns = new ArrayList<String>();
        Map<String, Integer> supervisorMembers = new HashMap<String, Integer>();
        Collection<KnCorpSubscriberDTO> corpSubscriberDTOList = new ArrayList<KnCorpSubscriberDTO>();
        for (KnCorpContactDTO contact : addedMemberMdnsDTOLst) {
            String mdn = contact.getMdn();
            addedMemberMdns.add(mdn);
            int supervisor = contact.getSupervisory();
            int locWatcher = contact.getLocWatcher();
            if (locWatcher == LOCWATCHER) {
                KnCorpGroupMemberDTO locWatcherDTO = new KnCorpGroupMemberDTO();
                locWatcherDTO.setMdn(mdn);
                locWatcherDTO.setLocWatcher(locWatcher);
                locWatcherList.add(locWatcherDTO);
            }
            if (supervisor == SUPERVISOR || supervisor == DISPATCHER || supervisor == INTER_OP) {
                supervisorMembers.put(mdn, supervisor);
                KnCorpGroupMemberDTO memberDTO = new KnCorpGroupMemberDTO();
                memberDTO.setMdn(mdn);
                memberDTO.setSupervisory(supervisor);
                memberDTO.setLocWatcher(locWatcher);
                KnCorpSubscriberDTO corpSubscriberDTO = new KnCorpSubscriberDTO();
                corpSubscriberDTO.setMdn(mdn);
                corpSubscriberDTOList.add(corpSubscriberDTO);
                addedMemberSupervisor.add(memberDTO);
                if (supervisor == DISPATCHER) {
                    dispatcherSubscribers.add(mdn);
                } else if (supervisor == INTER_OP) {
                    interOPSubsc.add(mdn);
                }
            }
        }
        subscPersistDTO.setRequestDispatcherSubscribers(dispatcherSubscribers);
        subscPersistDTO.setReqInterOpSubs(interOPSubsc);
        subscPersistDTO.setCompleteSupervisorList(addedMemberSupervisor);
        subscPersistDTO.setLocWatcherList(locWatcherList);
        subscPersistDTO.setAddedMdnList(addedMemberMdns);
        subscPersistDTO.setSubscSupVals(supervisorMembers);
        subscPersistDTO.setAddedMdnDTO(corpSubscriberDTOList);
        knLogger.info(methodName, "Exit : subscPersistDTO,",subscPersistDTO);
        return subscPersistDTO;
    }

    public KnCorpResponseDTO modifyGroup(KnIPCorpGroupInfoDTO groupInfoDTO, KnCorpGrpBasicInfoDTO grpBasicInfo, KnPersisterTxn persisterTxn) {

        String methodName = "modifyGroup(KnIPCorpGroupInfoDTO, KnPersisterTxn)";
        knLogger.info(methodName, "ENTRY : Input DTO Passed - ", groupInfoDTO, "grpBasicInfo ", grpBasicInfo);
        KnCorpGroupInfoRespDTO respDto = new KnCorpGroupInfoRespDTO();
        KnCorpInOutParamDTO corpInOutParamDTO = new KnCorpInOutParamDTO();
        String xdmsHome = "";
        String loggedInHierarchyId;
        try {
            int corpId = groupInfoDTO.getCorpId();
            int grpId = groupInfoDTO.getGroupId();
            boolean osmListChanged = false;
            boolean isHierarchyFlow = false;
            String idType = null;
            boolean upmCall = groupInfoDTO.isUpmCall();

            //Step:
            //get the Corp profile details from cache
            knLogger.debug(methodName, "Fetch the corpProfile profile if cached or fetch from the DB the details");
            KnCorpProfileDTO corpProfile = commonInfoUtil.getProfileDetails("" + corpId, CORP_PROFILE, false, persisterTxn);

            xdmsHome = corpProfile.getXdmsHome();
            String corpPocHome = corpProfile.getPocHome();
            int clusterId = Integer.parseInt(System.getenv(CLUSTERID_ENV_NAME));

            Map<String, String> rtxParamNameValueMap = genInfoUtil.retrieveRTXConfigValues(persisterTxn);
            //knLogger.debug(methodName, "param value of rtxParamName", rtxParamNameValueMap);
            String maxLocWatcherPerGroup = rtxParamNameValueMap.get(MAX_LOC_WATCHERS_PER_GRP);

            Map<String, String> paramNameValueMapCommon = genInfoUtil.retrieveMSSvcsCommonConfig(clusterId, persisterTxn);
            knLogger.debug(methodName, "param value of locWatcherConfig", paramNameValueMapCommon);
            String locWatcherConfigValue = paramNameValueMapCommon.get(KnConstants.GRPMEM_LOC_SVC_ENABLED);
            String maxGroupsPerCRIClient = paramNameValueMapCommon.get(MAX_GROUPS_PER_CRI_CLIENT);
            String pochomeAutoAssignValue = paramNameValueMapCommon.get(POCHOME_AUTOASSIGN_FLAG);
            boolean pochomeAutoAssignFlag = true;
            if(pochomeAutoAssignValue != null){
                pochomeAutoAssignFlag = ENABLED_STRING.equalsIgnoreCase(pochomeAutoAssignValue.trim());
            }
            knLogger.debug(methodName," pochomeAutoAssignFlag : ",pochomeAutoAssignFlag);
            Map<String, String> paramNameValueMapService = genInfoUtil.retrieveMSSvcsServiceConfig(clusterId, persisterTxn);
            // knLogger.debug(methodName, "param value of paramNameValueMapService", paramNameValueMapService);
            // Invoking custom hook
            List<String> groupIDList = new ArrayList<>();
            groupIDList.add(String.valueOf(grpId));
            commonInfoUtil.validateCorpAndGroupParams(groupIDList, String.valueOf(corpId), xdmsHome, persisterTxn);
            KnCorpHookRespDTO responseDTO = new KnCorpHookRespDTO();
            Map<String, Object> customParams = groupInfoDTO.getCustomParamMap();
            loggedInHierarchyId = KnCorpUtil.getLoggedInHierarchy(customParams);
            if (groupInfoDTO.getHierarchyType() == HIERARCHY_TYPE.HIERARCHY && null != customParams) {
                knLogger.debug(methodName, "before validating checking OwnerIdList :", groupInfoDTO.getAddedOwnerIdList());
                if (null != groupInfoDTO.getAddedOwnerIdList() && !groupInfoDTO.getAddedOwnerIdList().isEmpty()) {
                    groupInfoUtil.validateFanIds(corpId, groupInfoDTO.getAddedOwnerIdList(), xdmsHome, persisterTxn);
                }
                customParams.put(CURRENT_MASTER_LIST_ETAG, corpProfile.getCorpMasterListEtag());
                customParams.put(PERSISTER_TXN, persisterTxn);
                customParams.put(PTT_SERVER_ID, xdmsHome);
                groupInfoDTO.setCustomParamMap(customParams);
                KnCorpHookIPDTO hookIPDTO = new KnCorpHookIPDTO();
                hookIPDTO.setAction(KnActions.ACTIONS.MODIFY_GROUP);
                hookIPDTO.setData(groupInfoDTO);
                KnProcessInvokerImpl processInvoker = KnProcessInvokerImpl.getInstance();
                Object hookResp = processInvoker.invokeHook(CUSTOM_CORP_USER_HOOK, hookIPDTO);
                if (hookResp instanceof KnCorpHookRespDTO) {
                    responseDTO = (KnCorpHookRespDTO) hookResp;
                    if (com.kodiak.xdms.server.common.resources.KnConstants.RESPONSE_STATUS.FAILURE.value() == responseDTO.getStatus()) {
                        knLogger.error(methodName, "Returning Failure response");
                        populateXdmResponseFroomHook(responseDTO, respDto);
                        return respDto;
                    }
                    isHierarchyFlow = true;
                    idType = (String) groupInfoDTO.getCustomParamMap().get(IDTYPE);
                    groupInfoDTO.setAddedOwnerIdList(responseDTO.getAddedOwnerIdList());
                }
                Collection<String> idListStr = (Collection<String>) customParams.get(com.kodiak.common.resources.KnConstants.IDLIST);
                Object idTypeObj = customParams.get(IDTYPE);
                int idTypeValues;
                if (idTypeObj instanceof Integer) {
                    idTypeValues = (Integer) idTypeObj;
                } else if (idTypeObj instanceof String) {
                    idTypeValues = Integer.parseInt((String) idTypeObj);
                } else {
                    throw new IllegalArgumentException("Unsupported type for IDTYPE: " + idTypeObj.getClass().getName());
                }
                if (idListStr != null) {
                    List<Integer> idListInt = (List<Integer>) convertStrToIntColl(idListStr);
                    List<String> groupIdList = List.of(String.valueOf(groupInfoDTO.getGroupId()));
                    commonInfoUtil.validateGroupParams(groupIdList, String.valueOf(corpId), idListInt, xdmsHome, idTypeValues, persisterTxn);
                }
            }
            if (isHierarchyFlow) {
                List<Integer> idListValues = new ArrayList<>();
                ((List<String>) groupInfoDTO.getCustomParamMap().get(com.kodiak.common.resources.KnConstants.IDLIST)).forEach(
                        idValue -> idListValues.add(Integer.parseInt(idValue))
                );
                knLogger.debug(methodName, "List of idValues ", idListValues);
                Map<Integer, Integer> idValGroupidMap = new HashMap<>();
                groupInfoUtil.getOwnerAndSharedContextIdByGroupIds(List.of(grpId), idType, corpProfile.getXdmsHome(), false, persisterTxn)
                        .forEach((k, v) -> idValGroupidMap.put(Integer.parseInt(k), v));
                boolean isOwnerRequest = groupInfoUtil.isOwner(idValGroupidMap, idListValues);
                knLogger.debug(methodName, " owner req ", isOwnerRequest);
                groupInfoDTO.setOwnerCorpReq(isOwnerRequest);
            }

            if (groupInfoDTO.getCustomParamMap() != null) {
                Object idTypeObj = groupInfoDTO.getCustomParamMap().get(IDTYPE);
                if (idTypeObj != null && Integer.parseInt(String.valueOf(idTypeObj)) == Integer.parseInt(HIER_CTX_ID_TYPE)) {
                    List<String> idList = (List<String>) groupInfoDTO.getCustomParamMap().get(com.kodiak.common.resources.KnConstants.IDLIST);
                    if (idList != null && !idList.isEmpty()) {
                        groupInfoDTO.setRequestingHierarchyId(idList.get(0));
                    }
                }
            }
            //Step:
            //Populate the basic group information from request object
            boolean isUgwInterop = (null != groupInfoDTO.getUgwInterop() && groupInfoDTO.getUgwInterop().equals(7));
            knLogger.debug("isUgwInterop Modify: ", isUgwInterop);
            KnCorpGroupInfoPersistDTO groupPersistDTO = new KnCorpGroupInfoPersistDTO();//groupInfoUtil.getGroupBasicInfoDetails(groupInfoDTO, xdmsHome, persisterTxn);
            groupPersistDTO.setGroupId(grpBasicInfo.getGroupId());
            groupPersistDTO.setGroupDisplayName(grpBasicInfo.getGrpDisplayName());
            groupPersistDTO.setGroupType(grpBasicInfo.getGrpType());
            groupPersistDTO.setGroupMemberListId(grpBasicInfo.getGroupListId());
            groupPersistDTO.setCorpId(grpBasicInfo.getGroupCorpId());
            groupPersistDTO.setETag(grpBasicInfo.getGrpEtag());
            groupPersistDTO.setGroupProfileId(grpBasicInfo.getGroupProfileId());
            groupPersistDTO.setIsPreConfiguredGroup(groupInfoDTO.getIsPreConfiguredGroup());
            groupPersistDTO.setOwnerHierarchyId(grpBasicInfo.getHierarchyId());
            if(isUgwInterop){
                groupPersistDTO.setUgwInterop(groupInfoDTO.getUgwInterop());
                knLogger.debug("groupInfoDTO.getUgwInterop()", groupInfoDTO.getUgwInterop());
                String ugwInteropFlag = paramNameValueMapCommon.get(UGWINTEROP);
                knLogger.debug(methodName, "Retrieved ugwInterop flag from system config - ", ugwInteropFlag);
                groupPersistDTO.setUgwInteropSystemConfig(ugwInteropFlag);
            }
            Collection<KnRecordingTargetInfoDTO> recordingInfoList = null;
            Collection<String> disabledTarget = null;
            KnRecordingTargetInfoDTO recordInfo = new KnRecordingTargetInfoDTO();
            String recordingTarget = corpId + "_" + grpId;
            String recordFsValue = groupInfoDTO.getRecordingFs();
            if (null != recordFsValue) {
                recordingInfoList = new ArrayList<>();
                disabledTarget = new ArrayList<>();

                String priRecordingServerIP = paramNameValueMapCommon.get(MSI_PRIMARY_WAVE_RECORDING_SERVER_IP);
                String priRecordingServerPort = paramNameValueMapCommon.get(MSI_PRIMARY_WAVE_RECORDING_SERVER_PORT);
                String geoRecordingServerIP = paramNameValueMapCommon.get(MSI_GEO_WAVE_RECORDING_SERVER_IP);
                String geoRecordingServerPort = paramNameValueMapCommon.get(MSI_GEO_WAVE_RECORDING_SERVER_PORT);

                recordInfo.setPriRecIp(priRecordingServerIP);
                recordInfo.setPriRecPort(null != priRecordingServerPort ? Integer.parseInt(priRecordingServerPort) : null);
                recordInfo.setSecRecIp(geoRecordingServerIP);
                recordInfo.setSecRecPort(null != geoRecordingServerPort ? Integer.parseInt(geoRecordingServerPort) : null);
                recordInfo.setTarget(recordingTarget);

                String pttRecordingVal = paramNameValueMapCommon.get(PTT_RECORDING_FLAG);
                String dataRecordingVal = paramNameValueMapCommon.get(DATA_RECORDING_FLAG);
                String videoRecordingVal = paramNameValueMapCommon.get(VIDEO_RECORDING_FLAG);
                boolean pttRecordingFlag = ENABLED == Integer.parseInt(pttRecordingVal);
                boolean dataRecordingFlag = ENABLED == Integer.parseInt(dataRecordingVal);
                boolean videoRecordingFlag = ENABLED == Integer.parseInt(videoRecordingVal);
                knLogger.debug(methodName, "RecordingFs is ", recordFsValue);
                String recordingFsBitSetValue = KnGeneralUtil.getBitFromDecimalRecord(recordFsValue);
                knLogger.debug(methodName, "recordingFsBitSetValue is ", recordingFsBitSetValue);
                groupPersistDTO.setRecordingFs(recordingFsBitSetValue);
                groupPersistDTO.setPttRecordingFlag(pttRecordingFlag);
                groupPersistDTO.setDataRecordingFlag(dataRecordingFlag);
                groupPersistDTO.setVideoRecordingFlag(videoRecordingFlag);

                Integer recType = null;
                if (recordFsValue.equals(GROUP_RECORDING_MCPTT_MCVIDEO)
                        || recordFsValue.equals(GROUP_RECORDING_MCPTT_MCDATA_MCVIDEO)) {
                    recType = REC_TYPE.BOTH.value();
                }
                if (recordFsValue.equals(GROUP_RECORDING_MCVIDEO)
                        || recordFsValue.equals(GROUP_RECORDING_MCPDATA_MCVIDEO)) {
                    recType = REC_TYPE.VIDEO.value();
                }
                if (recordFsValue.equals(GROUP_RECORDING_MCPTT)
                        || recordFsValue.equals(GROUP_RECORDING_MCPTT_MCDATA)) {
                    recType = REC_TYPE.AUDIO.value();
                }
                if (recType != null) {
                    recordInfo.setRecType(recType);
                    recordingInfoList.add(recordInfo);
                }
                if (recordFsValue.equals(GROUP_RECORDING_DISABLED)
                        || recordFsValue.equals(GROUP_RECORDING_MCDATA)) {
                    disabledTarget.add(recordingTarget);
                }
            }
            knLogger.debug(methodName, "Retrieved Corp Group Info - ", groupPersistDTO);
            knLogger.debug(methodName, "groupInfoDTO.getIsPreConfiguredGroup() - ", groupInfoDTO.getIsPreConfiguredGroup());
            boolean groupTypeChanged;
            int currentGroupType = groupPersistDTO.getGroupType();
            int newGroupType = groupInfoDTO.getGroupType();
            //check if the group type has been changed.
            groupTypeChanged = checkIfGroupTypeChngd(newGroupType, currentGroupType);
            if (groupTypeChanged) {
                groupInfoDTO.setGroupTypeChanged(KnConstants.TRUE);
                groupInfoDTO.setGroupType(newGroupType);
            } else {
                groupInfoDTO.setGroupType(currentGroupType);
            }
            int privateListId = groupPersistDTO.getGroupMemberListId();
            groupInfoDTO.setGroupMemberListId(privateListId);

            KnCorpMdnListPersistDTO corpMdnListPersistDto = new KnCorpMdnListPersistDTO();
            corpMdnListPersistDto.setCorpId(corpId);
            Set<String> reqDispatcherSubscribers = new HashSet<String>();
            //This code is fetching the data for validation based on group type - like dispatcher group related
            //informations
            ICorpXdmDAO corpmgXdmDao = new KnCorpXdmDAO(xdmsHome);
            Map<String, KnCorpSubscriberDTO> extSubscribersMap = corpmgXdmDao.getCorpExternalSubscriber(corpProfile.getCorpId(), persisterTxn);
            groupInfoDTO.setCorpContactExternalMdns(new HashSet<>(extSubscribersMap.keySet()));
            KnCorpGroupInfoPersistDTO populatePersistDTO = populateDataForValidation(groupInfoDTO, xdmsHome, persisterTxn);
            knLogger.debug(methodName, "After populateDataForValidation");
            knLogger.debug(methodName, "groupInfoDTO.getGroupSupervisor() - ", groupInfoDTO.getGroupSupervisor());
            Set<Integer> sharedCorpIds = new HashSet<>();
            //if the requested group is shared or making newly shared then fetch if any shared corp infomration is present for the request corpId
            if((groupInfoDTO.getGrpShared()!=null && groupInfoDTO.getGrpShared() == GROUP_SHARING_ENABLE_INDICATOR)||
                    (grpBasicInfo.getGrpShared()!=null && grpBasicInfo.getGrpShared() == GROUP_SHARING_ENABLE_INDICATOR)) {
                List<KnCorpSharedCorpInfo> sharedCorpInfoList = groupInfoUtil.selectGroupSharedCorpInfo(corpId,grpId,xdmsHome,persisterTxn);
                if(sharedCorpInfoList!=null && !sharedCorpInfoList.isEmpty()) {
                    sharedCorpIds.addAll(sharedCorpInfoList.stream().map(KnCorpSharedCorpInfo::getCorpId).collect(Collectors.toSet()));
                    knLogger.info(methodName, "sharedCorpIds - ", sharedCorpIds," GroupId - ",grpId);

                }

            }
            //recovering the stale records
            List<String> staleMdns = sublistInfoUtil.getNonExisitingGroupMemberInPrivSublist(grpId, xdmsHome, persisterTxn);
            if(!staleMdns.isEmpty()){
                List<String> staleProfileMdnList = corpSubsProvInfoUtil.getProfileMdns(staleMdns, xdmsHome, persisterTxn);
                Collection<KnCorpSubscriberDTO> groupPrivateList = new ArrayList<>();
                for(String profileMdn:staleProfileMdnList){
                    groupPrivateList.add(new KnCorpSubscriberDTO(profileMdn, privateListId, corpId));
                }
                knLogger.info(methodName, "Adding stale profile mdn:", groupPrivateList != null ? groupPrivateList.size() : 0);
                contactInfoUtil.addPrivateContactList(groupPrivateList, xdmsHome, persisterTxn);
            }
            Collection<KnCorpGroupMemberDTO> completeSupervisorList = new ArrayList<KnCorpGroupMemberDTO>();
            Collection<KnCorpGroupMemberDTO> locWatcherList = new ArrayList<KnCorpGroupMemberDTO>();
            Map<String, Integer> locWatcherMap = populatePersistDTO.getLocWatcherMap();
            Map<String, Integer> supervisiorMap = populatePersistDTO.getSupervisiorMap();
            Map<String, Integer> groupModifyPermMap = populatePersistDTO.getGrpModifyPermMap();
            //complete Supervisor list is set to updating in DB with the new values passed in the request
            if (populatePersistDTO.getCompleteSupervisorList() != null) {
                completeSupervisorList.addAll(populatePersistDTO.getCompleteSupervisorList());
            }
            if (populatePersistDTO.getLocWatcherList() != null) {
                locWatcherList.addAll(populatePersistDTO.getLocWatcherList());
            }
            KnSublistDetailsPersistDTO removedSublistDetailsDTO = new KnSublistDetailsPersistDTO();
            removedSublistDetailsDTO.setSublistIds(groupInfoDTO.getRemovedSublistIds());
            //setting the added mdn list since the validations are based on the collection<String>
            if (populatePersistDTO.getAddedMdnList() != null) {
                corpMdnListPersistDto.setAddedMdnList(populatePersistDTO.getAddedMdnList());
            }
            //setting to input DTO since many places refering to collection<String> list
            groupInfoDTO.setAddedMdnsList(populatePersistDTO.getAddedMdnList());
            //setting of the superviosr list to the inputDTO
            if (populatePersistDTO.getCompleteSupervisorList() != null) {
                groupInfoDTO.setAddedMdnSupervisor(populatePersistDTO.getAddedMdnSupervisor());
            }
            //setting of the request dispatcher list to the requestDispatcherSubscriber list
            if (populatePersistDTO.getRequestDispatcherSubscribers() != null) {
                reqDispatcherSubscribers = new HashSet<String>(populatePersistDTO.getRequestDispatcherSubscribers());
            }
            if (populatePersistDTO.getDbDispatcherSubscribers() != null) {
                groupPersistDTO.setDbDispatcherSubscribers(populatePersistDTO.getDbDispatcherSubscribers());
            }
            if (populatePersistDTO.getDbLocWatcherSubscribers() != null) {
                groupPersistDTO.setDbLocWatcherSubscribers(populatePersistDTO.getDbLocWatcherSubscribers());
            }
            if (populatePersistDTO.getDbInterOpSubs() != null) {
                groupPersistDTO.setDbInterOpSubs(populatePersistDTO.getDbInterOpSubs());
            }
            Set<String> interOPSubsc = new HashSet<String>();
            //setting the input InterOp subscribers
            if (populatePersistDTO.getReqInterOpSubs() != null) {
                interOPSubsc = new HashSet<String>(populatePersistDTO.getReqInterOpSubs());
            }

            boolean locWatcherExists = false;
            if (!locWatcherList.isEmpty()) {
                locWatcherExists = true;
                Collection<String> locWatcherMdn = new ArrayList<>();
                for (KnCorpGroupMemberDTO subsDetails : locWatcherList) {
                    locWatcherMdn.add(subsDetails.getMdn());
                }
                locWatcherList = contactInfoUtil.getPoCSubsDetails(locWatcherList, locWatcherMdn, xdmsHome, persisterTxn);
                groupPersistDTO.setLocWatcherList(locWatcherList);
                groupPersistDTO.setLocWatcherConfigValue(locWatcherConfigValue.trim());

                knLogger.debug(methodName, "locWatcherMdn : ", KnGDPRTemplate.mdnList(locWatcherMdn));
                Map<Integer, KnExtProfileDetails> locWatcherMdnProfileMap = commonInfoUtil.getExtProfileDetails(locWatcherMdn, xdmsHome, corpId,sharedCorpIds,persisterTxn );
                knLogger.debug(methodName, "locWatcherMdnProfileMap : ", locWatcherMdnProfileMap);
                groupPersistDTO.setLocWatcherMdnProfileMap(locWatcherMdnProfileMap);
                groupPersistDTO.setRequestLocWatcherSubscribers(locWatcherMdn);
            }
            knLogger.debug(methodName, "locWatcherExists : ", locWatcherExists);
            groupPersistDTO.setLocWatcherExists(locWatcherExists);

            //set input dto
            groupPersistDTO.setInputDTO(groupInfoDTO);
            String groupName = null;
            if (grpBasicInfo.getGroupCreatedBy() == CREATED_BY.CAT_ADMIN.value()) {
                groupName = groupInfoDTO.getGroupDisplayName();
            } else {
                groupName = groupInfoDTO.getNewGroupDisplayName();
            }
            //get Group count by group name
            if (!isNullOrEmpty(groupName)) {
                int count = groupInfoUtil.getGroupCountByName(groupName, corpId, xdmsHome, persisterTxn);
                if (count > 0 && !groupName.equals(groupPersistDTO.getGroupDisplayName())) {
                    groupPersistDTO.setExistingGroupCount(count);
                } else if (groupName.equals(groupPersistDTO.getGroupDisplayName())) {
                    groupInfoDTO.setGroupDisplayName(null);
                }
            }else {
                groupName = grpBasicInfo.getGrpDisplayName();
            }
            if (groupInfoDTO.getNewGroupDisplayName() != null && !groupInfoDTO.getNewGroupDisplayName().equals(groupPersistDTO.getGroupDisplayName())) {
                groupInfoDTO.setGroupDisplayName(groupInfoDTO.getNewGroupDisplayName());
            }
            knLogger.debug(methodName, "Populating the current sublist for the group.");
            Collection<Integer> dbSublistList = sublistInfoUtil.getGroupsSublistListFromDB(grpId, xdmsHome, persisterTxn);

            groupPersistDTO.setMappedSublistIds(dbSublistList);

            //if the sublist passed actually exists in DB for the corporation
            knLogger.debug(methodName, "Before the added sublist check for corp in DB.");
            Collection<Integer> listCommonContactListRejectionIds = sublistInfoUtil.getCommonContactListRejectForGrp(groupInfoDTO.getAddedSublistIds(),corpId,xdmsHome,persisterTxn);
            knLogger.debug("CommonContactListRejectionList: ",listCommonContactListRejectionIds);
            groupPersistDTO.setCommonContactRejectList(listCommonContactListRejectionIds);
            KnSublistDetailsPersistDTO pocSublistIds = sublistInfoUtil.getPoCSublistIdInfo(groupInfoDTO.getAddedSublistIds(),
                    groupInfoDTO.getCorpId(), xdmsHome, persisterTxn);

            groupPersistDTO.setPoCSublistList(pocSublistIds.getSublistIds());

            Collection<String> removedMembers = groupInfoDTO.getRemovedMemberMdns();
            if (removedMembers != null) {
                corpMdnListPersistDto.setRemovedMdnList(removedMembers);
            }

            //Step:
            //get mdn details for added mdn list, also filters out the external contacts present if any
            knLogger.debug(methodName, "Before getting the added mdns from  for validation.");
            KnMdnDetailsPersistDTO pocMdnPersistDto = contactInfoUtil.getPoCSubscriberInfo(
                    corpMdnListPersistDto, xdmsHome, persisterTxn);

            boolean adedSGMDN = pocMdnPersistDto.isOnlyAddedGroupMember();

            Map<String, Integer> subscGrpCount = groupInfoUtil.getMembersGroupCount(pocMdnPersistDto.getGroupMdnList(), corpId, xdmsHome, persisterTxn);
            Collection<KnCorpSubscriberDTO> memberDTOList = pocMdnPersistDto.getAddedMdnDTO();
            Map<String, KnCorpSubsEntitiesDTO> subsEntitiesMap = new HashMap<>();
            KnCorpSubsEntitiesDTO subsEntitiesDTO = null;
            if (memberDTOList != null) {
                for (KnCorpSubscriberDTO memDto : memberDTOList) {
                    subsEntitiesDTO = new KnCorpSubsEntitiesDTO();
                    subsEntitiesDTO.setAliasMdn(memDto.getAliasMdn());
                    subsEntitiesDTO.setUserId(memDto.getUserId());
                    subsEntitiesMap.put(memDto.getMdn(), subsEntitiesDTO);
                }
            }
            knLogger.debug(methodName, "Filtering dispatchers from the added mdn list if not passed as 2 in request.");
            KnCorpGroupInfoPersistDTO subscSpecificList = populateSpecificSubscribersFromList(pocMdnPersistDto.getAddedMdnDTO(), currentGroupType);
            if (subscSpecificList.getRequestDispatcherSubscribers() != null) {
                reqDispatcherSubscribers.addAll(subscSpecificList.getRequestDispatcherSubscribers());
            }
            if (subscSpecificList.getCompleteSupervisorList() != null) {
                completeSupervisorList.removeAll(subscSpecificList.getCompleteSupervisorList());
                completeSupervisorList.addAll(subscSpecificList.getCompleteSupervisorList());
            }
            if (subscSpecificList.getReqInterOpSubs() != null) {
                interOPSubsc.addAll(subscSpecificList.getReqInterOpSubs());
            }

            //setting values in the persistDTO
            groupPersistDTO.setRequestDispatcherSubscribers(reqDispatcherSubscribers);
            groupPersistDTO.setAddedMdnDTO(memberDTOList);
            groupPersistDTO.setPoCSubscriberList(pocMdnPersistDto.getMdnList());
            groupPersistDTO.setReqInterOpSubs(interOPSubsc);

            /**
             * get the group supervisor member list from  populatePersistDTO and list on NNI subscribers from  pocMdnPersistDto
             * and get only external subscribers supervisor members in the request.
             * get the distinct profile ID in the ext subscr supervisor member list.
             */
            List<String> nniSupervisorList = new ArrayList<>();
            List<String> nniMdnList = pocMdnPersistDto.getNniSubscrList();
            List<String> grpSupervisorList = populatePersistDTO.getGrpSupervisorMemList();
            for (String nniMdn : nniMdnList) {
                if (grpSupervisorList.contains(nniMdn)) {
                    nniSupervisorList.add(nniMdn);
                }
            }
            List<Integer> superProfileIdList = contactInfoUtil.getExtSubsrProfilelist(nniSupervisorList, xdmsHome, persisterTxn);
            //Check if any of the external contact in request is supervisor
            boolean isExtContSupervisor = commonInfoUtil.isExtContSupervisor(grpSupervisorList, pocMdnPersistDto);
            if (isExtContSupervisor) {
                superProfileIdList.add(PROFILE_ID_KODIAK_EXTERNAL_CONTACT);
            }
            Map<Integer, KnExtProfileDetails> grpSupervisorProfileMap = commonInfoUtil.getExtProfileDetails(superProfileIdList, xdmsHome, persisterTxn);
            knLogger.debug(methodName, "Group Supervisor profile map - ", grpSupervisorProfileMap);
            //Setting the supervisor profile map for validation is external allowed as supervisor
            groupPersistDTO.setSupervisorProfileMap(grpSupervisorProfileMap);

            //If the group type is dispatcher and multiple dispatcher is disabled and some
            //dispatchers are sent in request we need to delete the exsisting dispatchers if the multiple dispatcher are not allowed
            populatePersistDTO.setMultipleDispatcherAllowed(Boolean.TRUE);
            populatePersistDTO.setRequestDispatcherSubscribers(reqDispatcherSubscribers);
            knLogger.debug(methodName, "reqDispatcherSubscribers before populating the dispatchers for delete- ", reqDispatcherSubscribers);
            KnCorpGroupInfoPersistDTO deletePersistDTO = populateDispatchersForDelete(populatePersistDTO, groupInfoDTO, groupTypeChanged);
            if (deletePersistDTO.getRemovedMemberList() != null && !deletePersistDTO.getRemovedMemberList().isEmpty()) {
                groupInfoDTO.setRemovedMemberMdns(deletePersistDTO.getRemovedMemberList());
                corpMdnListPersistDto.setRemovedMdnList(deletePersistDTO.getRemovedMemberList());
            }
            //Step:
            //setting the external contacts into input dto
            groupInfoDTO.setExternalContacts(corpMdnListPersistDto.getAddedExternalMdnList());
            knLogger.debug(methodName, "After determining the external data or input request .External Contacts to be added- ",
                    groupInfoDTO.getExternalContacts());

            //Step:
            // Getting External contacts are actually mapped as external contacts check
            KnMdnDetailsPersistDTO requestExtSubsDetails = contactInfoUtil.getExternalConatctsInfo(corpId,
                    corpMdnListPersistDto.getAddedExternalMdnList(), xdmsHome, persisterTxn);
            knLogger.debug(methodName, "External Contact Details  - ", requestExtSubsDetails);

            Collection<KnCorpSubscriberDTO> privateSublistDetails = contactInfoUtil.
                    getSubscPrivateMemberList(groupInfoDTO.getGroupMemberListId(), xdmsHome, persisterTxn);
            List<String> privtGrpmembers = new ArrayList<String>();
            for (KnCorpSubscriberDTO subsc : privateSublistDetails) {
                privtGrpmembers.add(subsc.getMdn());
                if (groupInfoDTO.getAddedMdnsList() != null && groupInfoDTO.getAddedMdnsList().contains(subsc.getMdn())) {
                    //In order to remove the already existing group mdn from getting calculate the group cound check.
                    //i.e the groupo mdn being added again
                    subscGrpCount.remove(subsc.getMdn());
                }
            }
            List<String> grpMdns = contactInfoUtil.getGroupMdns(privtGrpmembers, corpId, xdmsHome, persisterTxn);
            knLogger.debug(methodName, "grpMdns - ", KnGDPRTemplate.mdnList(grpMdns));

            //To check if the group already has SGMDN's then set the oldLmrInteropFlag to 7(Enable)
            if (null != grpBasicInfo.getUgwInterop()) {
                respDto.setOldLmrInteropFlag(grpBasicInfo.getUgwInterop());
            } else if (null == grpBasicInfo.getUgwInterop() && !grpMdns.isEmpty()) {
                respDto.setOldLmrInteropFlag(UGWINTEROP_DBVALUE);
            } else if (null == grpBasicInfo.getUgwInterop()) {
                respDto.setOldLmrInteropFlag(UGWINTEROP_DBVALUE_DISABLED);
            }

            //removing if the group mdn are getting removed from the list to allow the new group mdn to be added
            knLogger.debug(methodName, "groupInfoDTO.getRemovedMemberMdns()- ", KnGDPRTemplate.mdnList(groupInfoDTO.getRemovedMemberMdns()));
            if (groupInfoDTO.getRemovedMemberMdns() != null) {
                grpMdns.removeAll(groupInfoDTO.getRemovedMemberMdns());
                for (String mdn : groupInfoDTO.getRemovedMemberMdns()) {
                    subscGrpCount.remove(mdn);
                }
            }

            List<KnCorpSubscriberDTO> grpMdnsDTO = contactInfoUtil.getGroupMdnInListDTO(grpMdns, corpId, xdmsHome, persisterTxn);
            knLogger.debug(methodName, "grpMdnsDTO - ", grpMdnsDTO);
            groupPersistDTO.setExistingGrpMdnDto(grpMdnsDTO);
            groupPersistDTO.setGroupMdnGrpCnt(subscGrpCount);
            groupPersistDTO.setMaxSGPerGrp(corpProfile.getMaxSGPerGrp());
            groupPersistDTO.setMaxSGMdnPatchPerGroup(corpProfile.getMaxSGPatchPerGrp());
            knLogger.debug(methodName, "grpMdns after removal- ", KnGDPRTemplate.mdnList(grpMdns));
            groupPersistDTO.setExistingGrpmdns(grpMdns);
            Collection<KnCorpSubscriberDTO> privateSublistMembers = new ArrayList<KnCorpSubscriberDTO>(privateSublistDetails);
            groupPersistDTO.setGroupPrivateList(privateSublistMembers);
            KnSublistDetailsPersistDTO sublistPersistDto = new KnSublistDetailsPersistDTO();
            sublistPersistDto.setSublistIds(dbSublistList);

            Collection<Integer> finalSublistListInDB = filterOutFinalSublistList(sublistPersistDto,
                    pocSublistIds, removedSublistDetailsDTO);

            knLogger.debug(methodName, "final Group sublist - ", finalSublistListInDB);

            //Code to get the members from the final sublist members and the current private - removed members to
            //validate it against
            //the supervisor members passed in the request.
            Collection<Integer> sharedSublist = new ArrayList<Integer>(finalSublistListInDB);
//            sharedSublist.addAll(finalSublistListInDB);
            //remove private list since private members are added via the privateSublistMembers = current private list -
            //removed members
            sharedSublist.remove(privateListId);
            //Collection<KnCorpSubscriberDTO> finalGroupMemberListDetails =
            //        contactInfoUtil.getDistinctMembers(privateSublistMembers, sharedSublist, corpId, xdmsHome, persisterTxn);

            //Get the distinct members from added sublist Id list
            List<KnCorpSubscriberDTO> sublistDistinctMembers = sublistInfoUtil.getSublistDistinctMembers(sharedSublist, corpId, xdmsHome, persisterTxn);
            //Get the distinct added members among added sublist id list and added member list
            Collection<KnCorpSubscriberDTO> finalGroupMemberListDetails =
                    contactInfoUtil.getDistinctMembersList(privateSublistMembers, sublistDistinctMembers, corpId, xdmsHome, persisterTxn);

            knLogger.debug(methodName, "final Group members List - ", finalGroupMemberListDetails);

            groupPersistDTO.setSublistMembers(finalGroupMemberListDetails);

            //fetch exixtsing external group members for the group
            //Since the validation of the modified members being marked as supervisor should not be a external subscriber
            Collection<KnCorpSubscriberDTO> externalMemberForGroup = new ArrayList<KnCorpSubscriberDTO>();
            Collection<KnCorpSubscriberDTO> reqExtMemList = new ArrayList<KnCorpSubscriberDTO>();
            if (requestExtSubsDetails.getExternalMdnList() != null && !requestExtSubsDetails.getExternalMdnList().isEmpty()) {
                externalMemberForGroup.addAll(requestExtSubsDetails.getExternalMdnList());
                reqExtMemList.addAll(requestExtSubsDetails.getExternalMdnList());
            }
            ArrayList<String> groupInternalMembers = new ArrayList<String>();
            // ArrayList<String> finalGroupMembersinDB = new ArrayList<String>();
            if (finalGroupMemberListDetails != null && !finalGroupMemberListDetails.isEmpty()) {
                knLogger.debug(methodName, "Filtering internal external members in group.");
                for (KnCorpSubscriberDTO subsc : finalGroupMemberListDetails) {
                    if (subsc.getCorpId() != corpId && extSubscribersMap.containsKey(subsc.getMdn())) {
                        externalMemberForGroup.add(subsc);
                    } else {
                        groupInternalMembers.add(subsc.getMdn());
                    }
                }
                groupPersistDTO.setExternalContacts(externalMemberForGroup);
            }

            if (grpMdns != null && !grpMdns.isEmpty() && groupInfoDTO.getGroupDisplayName() != null) {
                pocMdnPersistDto.setGrpMdnPresent(Boolean.TRUE);
            }

            Collection<KnCorpSubscriberDTO> reqSubscList = new ArrayList<KnCorpSubscriberDTO>();
//            Collection<KnCorpSubscriberDTO> reqExtMemList = pocMdnPersistDto.getExternalMdnList();
            Collection<String> reqExteStrContList = new ArrayList<String>();
            for (KnCorpSubscriberDTO subsc : reqExtMemList) {
                reqExteStrContList.add(subsc.getMdn());
            }

            List<Integer> sharedCorpListId = new ArrayList<>();
            if(groupInfoDTO.getUseProfileId() != null){
                sharedCorpListId = corpUserProfileUtil.getSharedCorpIdFromUserProfielId(groupInfoDTO.getUseProfileId(), xdmsHome, persisterTxn);

            }


            if (memberDTOList != null) {
                for (KnCorpSubscriberDTO corpSubscriberDTO : memberDTOList) {
                    knLogger.debug(methodName, "Setting the corpId properly for the members by comparing with the exernal list.");
                    KnCorpSubscriberDTO subsc = new KnCorpSubscriberDTO();
                    subsc.setMdn(corpSubscriberDTO.getMdn());
                    subsc.setName(corpSubscriberDTO.getName());
                    subsc.setContact_type(corpSubscriberDTO.getContact_type());
                    subsc.setClientType(corpSubscriberDTO.getClientType());
                    subsc.setAliasMdn(corpSubscriberDTO.getAliasMdn());
                    subsc.setUserId(corpSubscriberDTO.getUserId());
                    subsc.setSubsActiveFS2(corpSubscriberDTO.getSubsActiveFS2());
                    subsc.setClientPVmajorVer(corpSubscriberDTO.getClientPVmajorVer());
                    subsc.setMcpttCompliance(corpSubscriberDTO.getMcpttCompliance());
                    subsc.setCorpId(corpSubscriberDTO.getCorpId());
                    if (reqExteStrContList.contains(corpSubscriberDTO.getMdn())) {
                        continue;
                    } else if(!sharedCorpListId.contains((corpSubscriberDTO.getCorpId()))){
                        subsc.setCorpId(corpId);
                    }
                    subsc.setClientType(corpSubscriberDTO.getClientType());
                    subsc.setUa(corpSubscriberDTO.getUa());
                    reqSubscList.add(subsc);
                }
            }
            if (reqExtMemList != null && !reqExtMemList.isEmpty()) {
                knLogger.debug(methodName, "Adding all the external guys to the list.");
                reqSubscList.addAll(reqExtMemList);
            }
            knLogger.debug(methodName, "reqExtMemList - .", reqExtMemList);

            Collection<KnCorpSubscriberDTO> mdnsToBeAddedToPrivateList = filterOutTheNewlyAddedMebers(privateSublistDetails, reqSubscList,
                    requestExtSubsDetails.getExternalMdnList());

            for (KnCorpSubscriberDTO subsDto : mdnsToBeAddedToPrivateList) {
                KnCorpSubsEntitiesDTO subsEntityDTO = subsEntitiesMap.get(subsDto.getMdn());
                subsDto.setAliasMdn(subsEntityDTO.getAliasMdn());
                subsDto.setUserId(subsEntityDTO.getUserId());
                subsDto.setSubsActiveFS2(subsEntityDTO.getActiveFs2());
            }

            //code not needed
            /* Collection<Integer> sublistMappedToGroup = new ArrayList<Integer>();
            sublistMappedToGroup.addAll(finalSublistListInDB);*/
            //added inorder to not call the final group member calculation when the request has only deleted
            //  members or sublist in request
            int allowedMaxGrpMemCount = corpProfile.getMaxMemPerCorpGroup();
            if (DISPATCH_GROUP == groupInfoDTO.getGroupType()) {
                allowedMaxGrpMemCount = corpProfile.getMaxMembersPerDispatchGroup();
            }
            int finalContactCount = allowedMaxGrpMemCount;
            Collection<String> finalGroupMembersinDB = new ArrayList<String>();
            KnMdnDetailsPersistDTO contactMdnPersistDto = new KnMdnDetailsPersistDTO();
            contactMdnPersistDto.setMdnList(groupInfoDTO.getRemovedMemberMdns());
            if ((removedMembers != null && !removedMembers.isEmpty()) &&
                    (groupInfoDTO.getRemovedSublistIds() != null && !groupInfoDTO.getRemovedSublistIds().isEmpty()) &&
                    (populatePersistDTO.getAddedMdnList() != null && populatePersistDTO.getAddedMdnList().isEmpty()) &&
                    (groupInfoDTO.getAddedSublistIds() != null && groupInfoDTO.getAddedSublistIds().isEmpty())) {
                knLogger.debug(methodName, "Determining all the subscrbers for the group if deleted is present to set count app.");
                finalGroupMembersinDB = contactInfoUtil.getFinalMemberGroupContactCount(sharedSublist,
                        privateSublistDetails, mdnsToBeAddedToPrivateList, contactMdnPersistDto,
                        xdmsHome, persisterTxn);
                // get the unique mcpttids in order to filter out the profile mdns from the list
                Set<String> uniqueMcpttIds = groupInfoUtil.getUniqueMcpttIds(finalGroupMembersinDB, xdmsHome, persisterTxn);
                finalContactCount = uniqueMcpttIds.size();
                if (finalContactCount > allowedMaxGrpMemCount) {
                    finalContactCount = allowedMaxGrpMemCount;
                }
            } else {
                knLogger.debug(methodName, "Determining all the subscrbers for the group If added is present.");
                finalGroupMembersinDB = contactInfoUtil.getFinalMemberGroupContactCount(sharedSublist,
                        privateSublistDetails, mdnsToBeAddedToPrivateList, contactMdnPersistDto,
                        xdmsHome, persisterTxn);
                Set<String> uniqueMcpttIds = groupInfoUtil.getUniqueMcpttIds(finalGroupMembersinDB, xdmsHome, persisterTxn);
                finalContactCount = uniqueMcpttIds.size();
            }
            groupPersistDTO.setMaxNumberOfMembers(allowedMaxGrpMemCount);
            groupPersistDTO.setGroupMemberCount(finalContactCount);
            //Get the distinct members from added sublist Id list
            List<KnCorpSubscriberDTO> distAddedSublistMemLst = sublistInfoUtil.getSublistDistinctMembers(groupInfoDTO.getAddedSublistIds(), corpId, xdmsHome, persisterTxn);
            //Get the distinct added members among added sublist id list and added member list
            Collection<KnCorpSubscriberDTO> memberList =
                    contactInfoUtil.getDistinctMembersList(mdnsToBeAddedToPrivateList, distAddedSublistMemLst, corpId, xdmsHome, persisterTxn);
            List<String> criClientList = new ArrayList<>(); //Variable to hold the cri clients from group members
            for(KnCorpSubscriberDTO member : memberList){
                if(member.getMcpttCompliance() == MCPTT_COMPLIANCE) {
                    criClientList.add(member.getMdn());
                }
            }
            knLogger.debug(methodName, "criClientList - ", KnGDPRTemplate.mdnList(criClientList));
            //Setting data for validation - max groups per CRI client.
            groupPersistDTO.setCriClientList(criClientList);
            if(null != maxGroupsPerCRIClient){
                groupPersistDTO.setMaxGroupsPerCRIClient(Integer.parseInt(maxGroupsPerCRIClient));
            }

            /**
             * Get the distinct ext profile ID for all added external contact and subscribers in the request
             * This is for validating the preArranged or dispatch group members
             */
            List<Integer> allProfileIdList = contactInfoUtil.getExtSubsrProfilelist(memberList, xdmsHome, persisterTxn);
            Map<Integer, KnExtProfileDetails> allExternalProfileMap = commonInfoUtil.getExtProfileDetails(allProfileIdList, xdmsHome, persisterTxn);
            knLogger.debug(methodName, "All external members profile map - ", allExternalProfileMap);
            //Setting the all profile map for validation is external allowed in prearranged or dispatch groups
            groupPersistDTO.setConfiguredProfileMap(allExternalProfileMap);
            Collection<String> requestMembers = new ArrayList<String>();  // will contains all the memebrs internal+external (all members in memberList)
            Collection<String> exterrnalMembers = new ArrayList<String>();  // Will contains only external members MDN.
            Collection<KnCorpSubscriberDTO> externalMembersDTOList = new ArrayList<KnCorpSubscriberDTO>(); // Will contains only external members DTO.
            Collection<String> intReqMems = new ArrayList<String>(); //  Will hold the internal members to be added.
            if (memberList != null && !memberList.isEmpty()) {
                for (KnCorpSubscriberDTO subsc : memberList) {
                    requestMembers.add(subsc.getMdn());
                    if (subsc.getCorpId() != corpId) {
                        exterrnalMembers.add(subsc.getMdn());
                        externalMembersDTOList.add(subsc);
                    } else {
                        intReqMems.add(subsc.getMdn());
                    }
                }
            }
            //Get the actual members to be added in the group member list table.
            Collection<String> actualMembersAddedToGroup = groupInfoUtil.getNewlyAddedMembersForGroup(requestMembers,
                    grpId, xdmsHome, persisterTxn);
            if (actualMembersAddedToGroup != null && !actualMembersAddedToGroup.isEmpty()) {
                // Getting subscribers group count for each added internal members for validation.
                Map<String, Integer> memberGroupCnt = groupInfoUtil.getMembersGroupCount(intReqMems,
                        xdmsHome, persisterTxn);
                if (exterrnalMembers != null && !exterrnalMembers.isEmpty()) {
                    //Getting subscribers group count for external added members for this corp.
                    // this will be replaced in  memberGroupCnt variable.
                    Map<String, Integer> externalMemberGrpCount =
                            groupInfoUtil.getExternalSubscriberGroupCount(exterrnalMembers, corpId, xdmsHome, persisterTxn);
                    memberGroupCnt.putAll(externalMemberGrpCount);
                }
                knLogger.debug(methodName, "memberGroupCnt - ", KnGDPRTemplate.mapKeyMdn(memberGroupCnt));
                groupPersistDTO.setSubsGroupsCount(memberGroupCnt);
                groupPersistDTO.setMaxGroupsPerMemberCount(corpProfile.getMaxGroupsPerSubsc());
            }
            Map<String, KnCorpGroupMemberDTO> grpMemberMap = groupInfoUtil.getGroupMembersList(groupInfoDTO.getGroupId(), xdmsHome, persisterTxn);
            knLogger.debug("grpMemberMap--- ", KnGDPRTemplate.mapKeyMdn(grpMemberMap));
            Map<String, Integer> existingGroupModifyPermMap = grpMemberMap.values().stream().collect(Collectors.toMap(KnCorpGroupMemberDTO::getMdn,
                    KnCorpGroupMemberDTO::getGroupModifyPerm));
            knLogger.debug("existingGroupModifyPermMap--- ", KnGDPRTemplate.mapKeyMdn(existingGroupModifyPermMap));
            if (grpBasicInfo.getGroupCreatedBy() == CREATED_BY.DYNAMIC_CGMT_INTF.value()) {
                List<String> tpMdnList = new ArrayList<>();
                groupPersistDTO.setExistingGroupModifyPermMap(existingGroupModifyPermMap);
                groupPersistDTO.setTpGroupOwner(grpBasicInfo.getGrpOwner());
                groupPersistDTO.setTpRequestMdn(groupInfoDTO.getTpRequestMdn());
                groupPersistDTO.setGroupCreatedBy(grpBasicInfo.getGroupCreatedBy());
                groupPersistDTO.setTpVendorID(groupInfoDTO.getTpVendorID());
                Map<String, KnCorpSubscriberDTO> tpDBSubMap = null;
                if (groupInfoDTO.getTpRequestMdn() != null) {
                    tpMdnList.add(groupInfoDTO.getTpRequestMdn());
                    tpDBSubMap = contactInfoUtil.getPoCSubscriberCorporateDetails(tpMdnList, xdmsHome, persisterTxn);
                    groupPersistDTO.setTpRequestMDNMap(tpDBSubMap);
                }
                if (grpBasicInfo.getGrpOwner() != null) {
                    tpMdnList.add(grpBasicInfo.getGrpOwner());
                } else {
                    String mdnHavingGrpModifyPerm = null;
                    Collection<String> existingMdnList = existingGroupModifyPermMap.keySet();
                    Map<String, Integer> subsClientTypeMap = groupInfoUtil.getGroupMembersClientTypeMap(existingMdnList, corpId, xdmsHome, persisterTxn);
                    Optional<Entry<String, Integer>> filteredSubsMap = subsClientTypeMap.entrySet().stream().filter(isThirdPartClientMap()).findFirst();
                    if (filteredSubsMap.isPresent()) {
                        mdnHavingGrpModifyPerm = filteredSubsMap.get().getKey();
                    } else {
                        Optional<KnCorpSubscriberDTO> filteredSubsList = memberList.stream().filter(isThirdPartClient(groupInfoDTO.getCorpId())).findFirst();
                        if (filteredSubsList.isPresent()) {
                            mdnHavingGrpModifyPerm = filteredSubsList.get().getMdn();
                        }
                    }
                    groupPersistDTO.setTpGroupOwner(mdnHavingGrpModifyPerm);
                    tpMdnList.add(mdnHavingGrpModifyPerm);
                }
                tpMdnList.addAll(requestMembers);
                Map<String, Integer> subsClientTypeMap = groupInfoUtil.getGroupMembersClientType(tpMdnList, xdmsHome, persisterTxn);
                List<String> actualTpMdnList = subsClientTypeMap.entrySet().stream().filter(isThirdPartClientMap()).map(Entry::getKey).collect(Collectors.toList());
                Map<String, String> vendorMdnMap = commonInfoUtil.getVendorID(actualTpMdnList, xdmsHome, persisterTxn);
                knLogger.debug("vendorMdnMap--- ", KnGDPRTemplate.mdnMap(vendorMdnMap));
                KnTPVendorDetailsPersistDTO dbVendorDetails = commonInfoUtil.getVendorDetails(groupInfoDTO.getTpVendorID(), xdmsHome, persisterTxn);
                groupPersistDTO.setVendorMdnMap(vendorMdnMap);
                groupPersistDTO.setTpDbMDNList(actualTpMdnList);
                groupPersistDTO.setTpVendorPersistDTO(dbVendorDetails);
            }
            // ABDG Enhancement:
            if (AREA_BASED_DYNAMIC_GROUP == groupInfoDTO.getClientType() && DISPATCH_GROUP == groupInfoDTO.getGroupType()) {
                List<String> grpOwnerList = new ArrayList<>();
                grpOwnerList.add(groupInfoDTO.getTpRequestMdn());
                Map<String, KnCorpSubscriberDTO> groupOwnerMap = contactInfoUtil.getPoCSubscriberCorporateDetails(grpOwnerList, xdmsHome, persisterTxn);
                int maxAbdgCountSystem = Integer.valueOf(paramNameValueMapService.get(MAX_ABDG_COUNT_SYSTEM).trim());
                int maxAbdgPerGrpOwnerSystem = Integer.valueOf(paramNameValueMapService.get(MAX_ABDG_PER_GRPOWNER).trim());
                int maxAbdgPerGrpMemStstem = Integer.valueOf(paramNameValueMapService.get(MAX_ABDG_PER_GRPMEMBER).trim());
                int maxAbdgLrgGrpPerCorp = Integer.valueOf(paramNameValueMapService.get(MAX_LRGABDG_TALKGRP_PER_CORP).trim());
                int maxAbdgLrgGrpMems = Integer.valueOf(paramNameValueMapService.get(MAX_USR_PER_LRGABDG_TALKGRP).trim());
                knLogger.debug(methodName, "maxAbdgCountSystem : ", maxAbdgCountSystem, "maxAbdgPerGrpOwnerSystem : ", maxAbdgPerGrpOwnerSystem,
                        "maxAbdgPerGrpMemStstem : ", maxAbdgPerGrpMemStstem, "corpProfile.getMaxAbdgTalkGrp() : ", corpProfile.getMaxAbdgTalkGrp(),
                        "maxAbdgLrgGrpPerCorp: ", maxAbdgLrgGrpPerCorp, "maxAbdgLrgGrpMems: ", maxAbdgLrgGrpMems);
                //Setting min of corp and System - MaxAbdgTalkGrp
                if (corpProfile.getMaxAbdgTalkGrp() == 0 || corpProfile.getMaxAbdgTalkGrp() > maxAbdgCountSystem) {
                    groupPersistDTO.setMaxAbdgCountSystem(maxAbdgCountSystem);
                } else {
                    groupPersistDTO.setMaxAbdgCountSystem(corpProfile.getMaxAbdgTalkGrp());
                }
                //Setting min of corp and System - MaxAbdgPerGrpOwner
                if (corpProfile.getMaxAbdgPerGrpOwner() == 0 || corpProfile.getMaxAbdgPerGrpOwner() > maxAbdgPerGrpOwnerSystem) {
                    groupPersistDTO.setMaxAbdgPerGrpOwner(maxAbdgPerGrpOwnerSystem);
                } else {
                    groupPersistDTO.setMaxAbdgPerGrpOwner(corpProfile.getMaxAbdgPerGrpOwner());
                }
                //Setting min of corp and System - MaxAbdgPerGrpMem
                if (corpProfile.getMaxAbdgPerGrpMember() == 0 || corpProfile.getMaxAbdgPerGrpMember() > maxAbdgPerGrpMemStstem) {
                    groupPersistDTO.setMaxAbdgPerGrpMem(maxAbdgPerGrpMemStstem);
                } else {
                    groupPersistDTO.setMaxAbdgPerGrpMem(corpProfile.getMaxAbdgPerGrpMember());
                }
                Collection<Integer> abdgGroupIds = groupInfoUtil.getCorpGroupCountIntf(corpId, groupInfoDTO.getGroupCreatedBy(),
                        xdmsHome, persisterTxn);
                int abdgGrpCountPerOwner = groupInfoUtil.getCorpGroupCountIntfPerOwner(corpId, groupInfoDTO.getGroupCreatedBy(),
                        grpBasicInfo.getGrpOwner(), xdmsHome, persisterTxn);
                Map<String, Integer> subsAbdgGroupCountMap = groupInfoUtil.getMembersAbdgGroupCount(abdgGroupIds, xdmsHome, persisterTxn);
                knLogger.debug(methodName, "subsAbdgGroupCountMap.size : ", subsAbdgGroupCountMap.size());
                Map<String, Integer> filteredSubsAdbgCountMap = subsAbdgGroupCountMap.entrySet().stream()
                        .filter(map -> intReqMems.contains(map.getKey())).collect(Collectors.toMap(Entry::getKey, Entry::getValue));
                knLogger.debug(methodName, "filteredSubsAdbgCountMap : ", KnGDPRTemplate.mapKeyMdn(filteredSubsAdbgCountMap));
                Map<String, Integer> externalSubscAbdgGroupCountMap =
                        groupInfoUtil.getExternalSubscriberAbdgGroupCount(exterrnalMembers, corpId, xdmsHome, persisterTxn);
                filteredSubsAdbgCountMap.remove(grpBasicInfo.getGrpOwner());
                filteredSubsAdbgCountMap.putAll(externalSubscAbdgGroupCountMap);
                knLogger.debug(methodName, "abdgGroupIds.size() : ", abdgGroupIds.size(), "abdgGrpCountPerOwner : ", abdgGrpCountPerOwner,
                        "filteredSubsAdbgCountMap.size : ", filteredSubsAdbgCountMap.size());
                int lrgAbdgGroup = groupInfoUtil.getLrgAbdgGroupCount(corpId, xdmsHome, persisterTxn);
                groupPersistDTO.setCorpAbdgGroupCount(abdgGroupIds.size());
                groupPersistDTO.setAbdgGroupCountPerOwner(abdgGrpCountPerOwner);
                groupPersistDTO.setAbdgGroupCountPerMemberMap(filteredSubsAdbgCountMap);
                groupPersistDTO.setTpGroupOwner(groupInfoDTO.getTpRequestMdn());
                groupPersistDTO.setOwner(grpBasicInfo.getGrpOwner());
                groupPersistDTO.setGrpOwnerExistsInDB(!groupOwnerMap.isEmpty());
                groupPersistDTO.setGroupCreatedBy(grpBasicInfo.getGroupCreatedBy());
                groupPersistDTO.setTpRequestMDNMap(groupOwnerMap);
                groupPersistDTO.setMaxLrgAbdgGrpPerCorp(maxAbdgLrgGrpPerCorp);
                groupPersistDTO.setMaxMemsPerLrgAbdgGrp(maxAbdgLrgGrpMems);
                groupPersistDTO.setNumOfLrgAbdgGrp(lrgAbdgGroup);
            }
            groupPersistDTO.setMultipleDispatcherAllowed(KnConstants.TRUE);
            groupPersistDTO.setMaxDispatchGroup(corpProfile.getMaxDispatchGroup());
            groupPersistDTO.setMaxSubscriberPerDispatchGroup(corpProfile.getMaxMembersPerDispatchGroup());
            groupPersistDTO.setMaxDispatchMembersPerDispatchGroup(corpProfile.getMaxDispatchMembersPerDispatchGroup());
            groupPersistDTO.setDispatchEnabled(corpProfile.getDispatchEnabled());
            groupPersistDTO.setMaxLocWatcherPerGroup(Integer.parseInt(maxLocWatcherPerGroup));

            List<Integer> groupIdList = new ArrayList<>();
            if (STANDARD_GROUP == groupPersistDTO.getGroupType()) {
                groupIdList.add(STANDARD_GROUP);
                groupIdList.add(BROADCAST_GROUP);
            } else {
                groupIdList.add(DISPATCH_GROUP);
            }
            int groupCount = groupInfoUtil.getCorpGroupCount(corpId, groupIdList, xdmsHome, persisterTxn);

            groupPersistDTO.setCorpGroupCount(groupCount);

            Map<String, Integer> interOpSubscGrpCnt = groupInfoUtil.getExternalSubscriberGroupCount(groupPersistDTO.getReqInterOpSubs(), corpId,
                    xdmsHome, persisterTxn);
            groupPersistDTO.setInterOPSubscGrpCnt(interOpSubscGrpCnt);
            groupPersistDTO.setGroupDisplayName(groupInfoDTO.getGroupDisplayName());
            groupPersistDTO.setMaxGroups(corpProfile.getMaxCorpGroups());
            groupPersistDTO.setLargeGroup(grpBasicInfo.isLargeGroup());
            groupPersistDTO.setMaxMemPerLargeGroup(corpProfile.getMaxMemPerLrgGrp());
            groupPersistDTO.setLargeGroupSupported(corpProfile.getLargeGrpSupported());

            //osm modify group osm exists
            Map<Integer, Integer> osmListIdAndDefaultMap = corpOSMInfoUtil
                    .getOSMListIdAndDefaultMap(String.valueOf(groupInfoDTO.getCorpId()), xdmsHome, persisterTxn);
            knLogger.debug(methodName, "osmListIdAndDefaultMap :", osmListIdAndDefaultMap);
            groupPersistDTO.setOsmListIdAndDefultMap(osmListIdAndDefaultMap);
            List<KnCorpSubscriberDTO> pocSubslist = new ArrayList<>();
            //osm modify group osmlistid
            if (groupInfoDTO.getOSMListId() != null) {
                Set<Integer> groupIdsForOsmList = null;
                if (!groupInfoDTO.getOSMListId().isEmpty()) {
                    groupPersistDTO.setOSMListId(groupInfoDTO.getOSMListId());
                    groupIdsForOsmList = groupInfoUtil
                            .getCorpGroupIdByOsmListId(Integer.parseInt(groupInfoDTO.getOSMListId()), xdmsHome, persisterTxn);
                    knLogger.debug(methodName, "groupIdsForOsmList :", groupIdsForOsmList);
                }
                if ((groupIdsForOsmList != null && !groupIdsForOsmList.contains(groupInfoDTO.getGroupId())) || groupInfoDTO.getOSMListId().isEmpty()) {
                    osmListChanged = true;
                }
            }
            //Now osmlistId is empty or with value no default osm check.
            /*else{
                if(osmListIdAndDefaultMap!=null&&!osmListIdAndDefaultMap.isEmpty() && grpBasicInfo.getGroupCreatedBy() == CREATED_BY.CAT_ADMIN.value()){
                    Optional<Integer> osmPresent =osmListIdAndDefaultMap.entrySet().stream()
                            .filter(entry -> entry.getValue().equals(ENABLED)).map(Map.Entry::getKey).findFirst();
                    if(osmPresent.isPresent()) {
                        knLogger.debug(methodName,"osmPresent.get().toString() :",osmPresent.get().toString());
                        groupPersistDTO.setOSMListId(osmPresent.get().toString());
                        groupInfoDTO.setOSMListId(osmPresent.get().toString());
                        //making this true as osmlist is changed from null to default osm.
                        osmListChanged=true;
                    }
                }
            }*/
            //osm modify group osm auth added member
            if (groupInfoDTO.getAddedMdnsList() != null && groupInfoDTO.getAddedMemberDTOMdns() != null
                    && !groupInfoDTO.getAddedMdnsList().isEmpty()
                    && !groupInfoDTO.getAddedMemberDTOMdns().isEmpty()) {
                Collection<KnCorpSubscriberDTO> pocSubsInfo = contactInfoUtil.getSubscribersInfo(groupInfoDTO.getAddedMdnsList(), xdmsHome, persisterTxn);
                knLogger.debug(methodName, "added mdn pocSubsInfo - ", pocSubsInfo, KnGDPRTemplate.mdnList(groupInfoDTO.getAddedMdnsList()));
                pocSubslist.addAll(pocSubsInfo);
                //groupPersistDTO.setPocSubsInfo(pocSubsInfo);
                groupPersistDTO.setAddedMemberMdnsDTOLst(groupInfoDTO.getAddedMemberDTOMdns());
            }
            //osm modify group osm auth modified member
            if (groupInfoDTO.getModifiedMembers() != null && !groupInfoDTO.getModifiedMembers().isEmpty()) {
                Collection<String> modifiedMdnList = new ArrayList<>();
                for (KnCorpGroupMemberDTO mdnModified : groupInfoDTO.getModifiedMembers()) {
                    ((ArrayList<String>) modifiedMdnList).add(mdnModified.getMdn());
                }
                Collection<KnCorpSubscriberDTO> modifiedPocSubsInfo = contactInfoUtil.getSubscribersInfo(modifiedMdnList, xdmsHome, persisterTxn);
                knLogger.debug(methodName, "modified mdn pocSubsInfo - ", modifiedPocSubsInfo, KnGDPRTemplate.mdnList(modifiedMdnList));
                pocSubslist.addAll(modifiedPocSubsInfo);
                //groupPersistDTO.setPocSubsInfo(modifiedPocSubsInfo);
                groupPersistDTO.setModifiedMembersList(groupInfoDTO.getModifiedMembers());
            }
            groupPersistDTO.setPocSubsInfo(pocSubslist);
            groupPersistDTO.setOsmListChanged(osmListChanged);

            if(groupInfoDTO.getCorpSharedCorpInfoList() != null && !groupInfoDTO.getCorpSharedCorpInfoList().isEmpty()){
                List<KnCorpTrustMatrixDTO> trustMatrixDTOList = generalCacheUtil.getSharedCorpMatrix(corpProfile.getExtCorpId().trim());
                groupPersistDTO.setTrustMatrixDTOList(trustMatrixDTOList);
                groupPersistDTO.setCorpSharedCorpInfoList(groupInfoDTO.getCorpSharedCorpInfoList());
            }

            // P7-2: Trust matrix validation for explicitly added sharing entries (owner corp only)
            if (groupInfoDTO.getAddedCorpSharedCorpInfoList() != null && !groupInfoDTO.getAddedCorpSharedCorpInfoList().isEmpty()
                    && groupInfoDTO.isOwnerCorpReq()) {
                List<KnCorpTrustMatrixDTO> trustMatrixDTOList = generalCacheUtil.getSharedCorpMatrix(corpProfile.getExtCorpId().trim());
                enrichTrustMatrixWithHierarchyMappings(trustMatrixDTOList);
                groupPersistDTO.setTrustMatrixDTOList(trustMatrixDTOList);
                groupPersistDTO.setCorpSharedCorpInfoList(groupInfoDTO.getAddedCorpSharedCorpInfoList());
                injectSourceHierarchyId(groupInfoDTO.getAddedCorpSharedCorpInfoList(), groupInfoDTO.getHierarchyId());
            }

            if (groupInfoDTO.getGrpShared() != null || grpBasicInfo.getGrpShared() != null) {
                boolean grpSharedModified = groupInfoDTO.getGrpShared() != null && !groupInfoDTO.getGrpShared().equals(grpBasicInfo.getGrpShared());
                groupPersistDTO.setGrpSharedModified(grpSharedModified);
                groupPersistDTO.setGrpShared(grpBasicInfo.getGrpShared());
            }
            groupPersistDTO.setExistingGrpMemDetail(new ArrayList<>(grpMemberMap.values()));
            Map<Integer, KnCorpTrustMatrixDTO> trustMatrixMap = corpUserProfileUtil.getTrustMatrixMap(corpProfile.getExtCorpId(),
                    generalCacheUtil, commonInfoUtil, xdmsHome, persisterTxn);
            groupPersistDTO.setTrustMatrixMap(trustMatrixMap);
            // UCSPROVCONFIG-8560 fix: mark existing members as external contacts using UNION of
            // DB shared corp list + request shared corp list. We need both because:
            // - Un-share: request list is empty, DB has the current shared corps
            // - Re-share/first-time share: DB list is empty, request has the new shared corps
            // - Modify shared: both may have values, union covers all cases
            Set<Integer> markingCorpIds = new HashSet<>(sharedCorpIds); // from DB (line 1451)
            if (groupInfoDTO.getCorpSharedCorpInfoList() != null) {
                groupInfoDTO.getCorpSharedCorpInfoList().forEach(item -> markingCorpIds.add(item.getCorpId()));
            }

            knLogger.debug(methodName, "markingCorpIds (DB+Request union) -", markingCorpIds, ", ownerCorpId -", grpBasicInfo.getCorpId());
            if (!markingCorpIds.isEmpty()) {
                for (KnCorpGroupMemberDTO member : groupPersistDTO.getExistingGrpMemDetail()) {
                    if (member.getCorpId() != 0 && (!markingCorpIds.contains(member.getCorpId())) && (member.getCorpId() != grpBasicInfo.getCorpId())) {
                        knLogger.debug(methodName, "Marking external contact -", member.getMdn(), ", memberCorpId -", member.getCorpId());
                        member.setExternalContact(Boolean.TRUE);
                    }
                }
            }
            groupPersistDTO.setDbIsPreConfiguredGroup(grpBasicInfo.getIsPreConfiguredGroup());

            boolean sharedGroupRequest = grpBasicInfo.getGroupCorpId() != corpId;
            boolean isUgwInteropSharedCorpChange = sharedGroupRequest && isUgwInterop;
            groupPersistDTO.setUgwInteropSharedCorpChange(isUgwInteropSharedCorpChange);
            //groupPersistDTO.setExternalContacts(groupInfoDTO.getExternalContacts());
            //Logic to validate the members which are not part of shared corp or external subs info
            if(!pocSubslist.isEmpty()){
                List<KnCorpSubscriberDTO> extMdns = pocSubslist.stream().filter(subs -> !(subs.getCorpId() == corpId) && extSubscribersMap.containsKey(subs.getMdn())).collect(Collectors.toList());
                if(!extMdns.isEmpty()){
                    groupPersistDTO.setAddedExternalMembers(extMdns);
                    ICorpXdmDAO corpXdmDao = new KnCorpXdmDAO(xdmsHome);
                    Collection<KnCorpSubscriberDTO> externalGrpMemberDetails = corpXdmDao.getExternalPoCSubscriberInfo(
                            extMdns.stream().map(KnCorpSubscriberDTO::getMdn).collect(Collectors.toList()),
                            corpId, persisterTxn);
                    List<String> externalMdnsPresentInDB = externalGrpMemberDetails.stream().map(KnCorpSubscriberDTO::getMdn).collect(Collectors.toList());
                    groupPersistDTO.setMdnsPresentInExternalInfo(externalMdnsPresentInDB);
                    groupPersistDTO.setExternalContacts(externalGrpMemberDetails.stream().filter(x -> externalMdnsPresentInDB.contains(x.getMdn())).collect(Collectors.toList()));
                }
            }
            if (groupInfoDTO.getCustomParamMap() != null) {
                Object idTypeObj = groupInfoDTO.getCustomParamMap().get(IDTYPE);
                if (idTypeObj != null && Integer.parseInt(String.valueOf(idTypeObj)) == Integer.parseInt(HIER_CTX_ID_TYPE)) {
                    if(extSubscribersMap != null && !extSubscribersMap.isEmpty()) {
                        groupPersistDTO.setCorpContactExternalMdns(new ArrayList<>(extSubscribersMap.keySet()));
                    }
                }
            }

            //Validating the max large group counts
            KnLargeGrpCountDTO getAllLargeGroupSystem = groupInfoUtil.getLargeGroupCounts(corpId, persisterTxn, xdmsHome);
            Collection<KnCorpSubscriberDTO> removedMembersList = contactInfoUtil.getSubscribersInfo(corpMdnListPersistDto.getRemovedMdnList(), xdmsHome, persisterTxn);
            Collection<KnCorpSubscriberDTO> uniqueMdnToBeDeletedToGroup =
                    contactInfoUtil.getDistinctMembers(removedMembersList, groupInfoDTO.getRemovedSublistIds(), corpId, xdmsHome, persisterTxn);

            //Retrieving the current group members i.e internal members from dg.corpgroupdistinfo
            Collection<Integer> groupIdLst = new ArrayList<>();
            groupIdLst.add(grpId);
            //retrieval of members before group modification in group dist info
            Map<Integer, Collection<String>> groupDistList = groupInfoUtil.getGroupSubscriberDistList(groupIdLst, xdmsHome, persisterTxn);
            //Filter out the actually added members and deleted members as same member can be already present in the group via sublist etc
            Map<Integer, Map<String, Collection<String>>> memberDetailsList = commonInfoUtil.filterAddedRemovedMembersForAllSubscribers(groupDistList,
                    memberList, uniqueMdnToBeDeletedToGroup, corpId);

            Collection<String> addedMembers = new ArrayList<>();

            if (memberDetailsList.get(grpId) != null) {
                addedMembers = (memberDetailsList.get(grpId)).get(KnPersisterConstants.ADDED_MEMBERS);
            }
            Collection<String> removedFilterMembers = new ArrayList<>();
            if ((memberDetailsList.get(grpId) != null) && (memberDetailsList.get(grpId)).get(KnPersisterConstants.DELTED_MEMBERS) != null) {
                removedFilterMembers = (memberDetailsList.get(grpId)).get(KnPersisterConstants.DELTED_MEMBERS);
            }
            // Validate max groups per subscriber
            Collection<KnCorpSubscriberDTO> subsInfo = contactInfoUtil.getSubscribersInfo(addedMembers, xdmsHome, persisterTxn);
            Map<String, Integer> subsGroupCount = groupInfoUtil.getSubsScrGroupCountExceptABDG(
                    addedMembers.stream().collect(Collectors.toList()), xdmsHome, persisterTxn);

            boolean sysLargeAgencyDispatch = paramNameValueMapCommon.get(LARGE_AGENCY_DISPATCH_FEATURE).equalsIgnoreCase(ENABLED_STRING);
            boolean corpLargeAgencyDispatch = KnGeneralUtil.getFeatureBitValue(corpProfile.getCorpFS2(), FEATURE_SET.LARGE_AGENCY_DISPATCH.value());

            groupPersistDTO.setAddedMDNs(subsInfo);

            int memberCount = 0;
            Map<Integer, Integer> groupMemberCount = groupInfoUtil.getGroupMemCount(groupIdLst, xdmsHome, persisterTxn);
            if (!groupMemberCount.isEmpty()) {
                memberCount = groupMemberCount.get(grpId);
            }

            int totalMemberCount = (memberCount + addedMembers.size()-removedFilterMembers.size());

            boolean isLargeGroup = Boolean.FALSE;
            if (STANDARD_GROUP == groupInfoDTO.getGroupType()
                    && totalMemberCount > corpProfile.getMaxMemPerCorpGroup()&&!grpBasicInfo.isLargeGroup()) {
                isLargeGroup = Boolean.TRUE;
            } else if (DISPATCH_GROUP == groupInfoDTO.getGroupType()
                    && totalMemberCount > corpProfile.getMaxMembersPerDispatchGroup()&&!grpBasicInfo.isLargeGroup()) {
                isLargeGroup = Boolean.TRUE;
            }
            groupPersistDTO.setLargeGroup(isLargeGroup);
            groupPersistDTO.setMaxLargeGrpCorp(corpProfile.getMaxLrgGrpPerCorp());
            groupPersistDTO.setLargeGrpCountInCorp(getAllLargeGroupSystem.getLrgGrpCountCorp());

            groupPersistDTO.setLargeGrpCountInSystem(getAllLargeGroupSystem.getLrgGrpCountSystem());
            groupPersistDTO.setMaxLargeGrpSystem(Integer.parseInt(genInfoUtil.retrieveRTXConfigValues(persisterTxn).get(NUM_OF_LG_SUPPORTED)));
            groupPersistDTO.setMaxGroupsPerLargeDispatchMemberCount(corpProfile.getMaxGroupsPerLargeDispatch());
            groupPersistDTO.setIsSysLargeAgencyDispatchEnabled(sysLargeAgencyDispatch);
            groupPersistDTO.setIsCorpLargeAgencyDispatchEnabled(corpLargeAgencyDispatch);
            groupPersistDTO.setSubsGroupCount(subsGroupCount);

            boolean isGrpSharingEnabled = groupInfoDTO.getGrpShared() != null && groupInfoDTO.getGrpShared() == GROUP_SHARING_ENABLE_INDICATOR;
            knLogger.info(methodName, "isGrpSharingEnabled :", isGrpSharingEnabled, " isLargeGroup:", isLargeGroup);
            if (isGrpSharingEnabled && isLargeGroup) {
                Set<Integer> allInternalCorpIds = getAllInternalCorpIdsForSharedGroup(groupInfoDTO.getGroupId(), corpProfile.getCorpId(), xdmsHome, persisterTxn);
                knLogger.info(methodName, " allInternalCorpIds :", allInternalCorpIds, " corpProfile.getCorpId()", corpProfile.getCorpId());
                Map<Integer, Integer> CorpIdAndLargeGroupFlagMap = commonInfoUtil.getCorpIdAndLargeGroupFlagMap(allInternalCorpIds, persisterTxn);
                knLogger.info(methodName, " CorpIdAndLargeGroupFlagMap :", CorpIdAndLargeGroupFlagMap);
                groupPersistDTO.setCorpIdAndLargeGroupFlagMap(CorpIdAndLargeGroupFlagMap);
            }
            if (null != groupInfoDTO.getAuthorizedLargeTG()) {
                groupPersistDTO.setAuthorizedLargeTG(groupInfoDTO.getAuthorizedLargeTG());
            }else{
                groupPersistDTO.setAuthorizedLargeTG(grpBasicInfo.getAuthorizedLargeTG());
            }
            if (null != groupInfoDTO.getVideoPermission()) {
                groupPersistDTO.setVideoPermission(groupInfoDTO.getVideoPermission());
            }else{
                groupPersistDTO.setVideoPermission(grpBasicInfo.getVideoPermission());
            }
            // P6-4 Step A: pre-populate sourceHierarchyId and resolve targetHierarchyId before validation
            if (groupPersistDTO.getCorpSharedCorpInfoList() != null && groupInfoDTO.getHierarchyId() != null) {
                String srcHierarchyId = groupInfoDTO.getHierarchyId();
                Map<String, Integer> extCorpToIntIdCache = new HashMap<>();
                Map<String, Map<String, String>> extCorpToNameIdCache = new HashMap<>();
                for (KnCorpSharedCorpInfo info : groupPersistDTO.getCorpSharedCorpInfoList()) {
                    info.setSourceHierarchyId(srcHierarchyId);
                    String targetExtCorpId = info.getExtCorpId();
                    String targetHierName = info.getTargetHierarchyId();
                    if (targetHierName == null || targetExtCorpId == null) {
                        continue;
                    }
                    if (!extCorpToIntIdCache.containsKey(targetExtCorpId)) {
                        int targetCorpIntId = commonInfoUtil.getCorpId(targetExtCorpId, false, persisterTxn);
                        KnCorpProfileDTO targetCorpProfile = commonInfoUtil.getProfileDetails(
                                String.valueOf(targetCorpIntId), CORP_PROFILE, false, persisterTxn);
                        Map<String, String> nameToId = hierarchyInfoUtil.getHierarchyNameList(
                                targetCorpIntId, targetCorpProfile.getXdmsHome(), persisterTxn);
                        extCorpToIntIdCache.put(targetExtCorpId, targetCorpIntId);
                        extCorpToNameIdCache.put(targetExtCorpId, nameToId);
                    }
                    String resolvedHierId = extCorpToNameIdCache.get(targetExtCorpId).get(targetHierName);
                    if (resolvedHierId == null) {
                        throw new KnCorpBOException(KnErrorCodes.Validator.INVALID_INPUT,
                                "targetHierarchyId not found: " + targetHierName + " for corp: " + targetExtCorpId);
                    }
                    info.setCorpId(extCorpToIntIdCache.get(targetExtCorpId));
                    info.setTargetHierarchyId(resolvedHierId);
                }
            }
            List<int[]> sharedGroupHierarchyMappings = groupInfoUtil.getSharedGroupHierarchyMappings(groupInfoDTO.getGroupId(), xdmsHome, persisterTxn);
            groupPersistDTO.setGroupSharingMap(sharedGroupHierarchyMappings);
            groupPersistDTO.setHierarchyId(loggedInHierarchyId);
            //performs business validation
            knLogger.debug(methodName, "Invoking ValidationFW. DTO - ", groupPersistDTO);
            validatorFW.validate(groupPersistDTO);
            if (isHierarchyFlow) {
                List<String> addedOwnerIdList = groupInfoDTO.getAddedOwnerIdList();
                List<String> removedOwnerIdList = groupInfoDTO.getRemovedOwnerIdList();
                if (null != addedOwnerIdList && !addedOwnerIdList.isEmpty()) {
                    groupInfoUtil.insertGroupHiearchyMap(grpId, addedOwnerIdList, idType, xdmsHome, persisterTxn);
                }
                if (null != removedOwnerIdList && !removedOwnerIdList.isEmpty()) {
                    groupInfoUtil.removeGroupHiearchyMapByOwnerIds(grpId, removedOwnerIdList, idType, xdmsHome, persisterTxn);
                }
            }

            Set<String> allRemovedHierIds = new LinkedHashSet<>();

            // When grpShared is disabled via idType=3 flow, clean up GROUP_HIERARCHY_MAP (idType=4) and CORPGRP_SHAREDLIST
            if (null != customParams) {
                String idTypeStrCleanup = (String) customParams.get(IDTYPE);
                int idTypeIntCleanup = (idTypeStrCleanup != null && !idTypeStrCleanup.isEmpty()) ? Integer.parseInt(idTypeStrCleanup) : 0;
                if (Integer.parseInt(HIER_CTX_ID_TYPE) == idTypeIntCleanup
                        && groupInfoDTO.getGrpShared() != null && groupInfoDTO.getGrpShared() == 0
                        && grpBasicInfo.getGrpShared() != null && grpBasicInfo.getGrpShared() == 1) {
                    List<int[]> existingHierMappings = groupInfoUtil.getSharedGroupHierarchyMappings(groupInfoDTO.getGroupId(), xdmsHome, persisterTxn);
                    if (!existingHierMappings.isEmpty()) {
                        List<String> hierIdsToRemove = new ArrayList<>();
                        for (int[] row : existingHierMappings) {
                            hierIdsToRemove.add(String.format("%08d", row[0]));
                        }
                        Set<String> hierIdsToRemoveSet = new HashSet<>(hierIdsToRemove);
                        List<KnCorpGroupMemberDTO> existingMembers = groupPersistDTO.getExistingGrpMemDetail();
                        if (existingMembers != null) {
                            for (KnCorpGroupMemberDTO member : existingMembers) {
                                String memberHierarchyId = member.getHierarchyId();
                                if (memberHierarchyId != null && hierIdsToRemoveSet.contains(memberHierarchyId.trim())) {
                                    knLogger.error(methodName, "[Hierarchy] Cannot disable grpShared: shared member exists for hierarchyId=", memberHierarchyId.trim());
                                    throw new KnCorpBOException(KnErrorCodes.Validator.GROUP_SHARED_FLAG_MODIFY_NOT_ALLOWED,
                                            "Shared member exist cannot unshare");
                                }
                            }
                        }
                        knLogger.debug(methodName, "[Hierarchy] grpShared disabled: removing GROUP_HIERARCHY_MAP entries for groupId=", groupInfoDTO.getGroupId(), " count=", hierIdsToRemove.size());
                        groupInfoUtil.removeGroupHiearchyMapByOwnerIds(groupInfoDTO.getGroupId(), hierIdsToRemove, "4", xdmsHome, persisterTxn);
                        allRemovedHierIds.addAll(hierIdsToRemove);
                    }
                    List<Integer> groupsToClean = new ArrayList<>(1);
                    groupsToClean.add(groupInfoDTO.getGroupId());
                    knLogger.debug(methodName, "[Hierarchy] grpShared disabled: removing CORPGRP_SHAREDLIST for groupId=", groupInfoDTO.getGroupId());
                    groupInfoUtil.deleteSharedGroups(groupsToClean, xdmsHome, persisterTxn);
                }
            }
            /*if (KnConstants.MIN_GROUP_MEM > finalContactCount) {
                KnIPCorpGroupDTO groupDTO = new KnIPCorpGroupDTO();
                groupDTO.setGroupId(grpId);
                KnCorpResponseDTO corpResponseDTO = deleteGroupOperation(groupDTO, corpInOutParamDTO, corpProfile.getLinkedGwKey(), xdmsHome, persisterTxn);
                corpResponseDTO.setTgsModeChgMap(corpInOutParamDTO.getTgsModeChgMap());
                return corpResponseDTO;
            }*/
            if (isUgwInterop) {
                boolean isGroupProfileNotifyRequired = commonInfoUtil.isGroupProfileNotifyRequired(corpId, persisterTxn);
                if (isGroupProfileNotifyRequired) {
                    //Update the UGWINTEROP
                    commonInfoUtil.updateLmrInterOpInDB(corpId, ENABLED, persisterTxn);
                    respDto.setIntCorpId(corpProfile.getCorpId());
                    respDto.setExtCorpId(corpProfile.getExtCorpId());
                    respDto.setNetworkName(corpProfile.getNetworkName());
                    respDto.setCorpNotification(true);
                }
            }
            //If the Group is not empty proceed as follows
            KnSublistDetailsPersistDTO presentSublistIdList = new KnSublistDetailsPersistDTO();
            presentSublistIdList.setSublistIds(dbSublistList);
            //Since same sublist id can be present in request whic is already assigned to group, filtering out the duplicate ids.
            Collection<Integer> addedSublistIds = contactInfoUtil.filterFinalSublistToBeAddedInDb(finalSublistListInDB,
                    presentSublistIdList);
            groupInfoDTO.setAddedSublistIds(addedSublistIds);
            //Populating the private list members tobe added into group private list.
            Collection<KnCorpGroupMemberDTO> groupMembers = new ArrayList<KnCorpGroupMemberDTO>();
            for (KnCorpSubscriberDTO subsc : mdnsToBeAddedToPrivateList) {
                KnCorpGroupMemberDTO grpMem = new KnCorpGroupMemberDTO();
                grpMem.setMdn(subsc.getMdn());
                grpMem.setCorpId(subsc.getCorpId());
                groupMembers.add(grpMem);
            } //resetting the added members into input DTO.
            groupInfoDTO.setGroupMembers(groupMembers);


            /*Group is already having SG/SGPatch MDN 	: Means; LMR_INTEROP_CAPABLE in DG.CORPGROUPINFO is 1;
            Group do not have any SG/SGPatch MDN	: Means; LMR_INTEROP_CAPABLE in DG.CORPGROUPINFO is 0;

            grpMdns		: Means what is going to be happen after (Existing SG/SGPatch - Requested Removed SG/SGPatch)
            adedSGMDN	: Means what is going to happend after (Requested added SG/SGPatch)

            below are the chart, when to update LMR_INTEROP_CAPABLE column as of modifyGroup Call:

            DB	| grpMdns	    | adedSGMDN
             1	| Empty		    |	NA			: Update will take place		: If Loop
             1	| Empty		    |	Present		: Update will not take place	: If Loop : Exception Case
             0	| NA 		    |	Present		: Update will take place		: Else If Loop
             0	| NA 		    |	Empty		: Update will not take place	: Else If Loop

            DB	| Current
            1	| 0			: Update will take place
            1	| 1			: Update will not take place
            0	| 1 		: Update will take place
            0	| 0 		: Update will not take place*/


            knLogger.debug("pocMdnPersistDto.isGrpMdnPresent() & adedSGMDN", grpMdns.isEmpty(), adedSGMDN);
            if (grpBasicInfo.getLmrInteropCapable() == LMR_INTEROP_CAPABLE && grpMdns.isEmpty()) {
                groupInfoDTO.setLmrInteropCapable(LMR_INTEROP_NON_CAPABLE);
                groupInfoDTO.setLmrInteropFeatureChanged(true);
            } else if (grpBasicInfo.getLmrInteropCapable() == LMR_INTEROP_NON_CAPABLE && adedSGMDN) {
                groupInfoDTO.setLmrInteropCapable(LMR_INTEROP_CAPABLE);
                groupInfoDTO.setLmrInteropFeatureChanged(true);
            }
            //Exception Case: 1
            if (grpBasicInfo.getLmrInteropCapable() == LMR_INTEROP_CAPABLE && grpMdns.isEmpty() && adedSGMDN) {
                groupInfoDTO.setLmrInteropFeatureChanged(false);
            }

            //Exception Case: 2 for Backward campatability: Group exists with 3 sg mdn and only one sg got deleted then interopCapable = 1
            if (grpBasicInfo.getLmrInteropCapable() == LMR_INTEROP_NON_CAPABLE && !grpMdns.isEmpty()) {
                groupInfoDTO.setLmrInteropCapable(LMR_INTEROP_CAPABLE);
                groupInfoDTO.setLmrInteropFeatureChanged(true);
            }

            if (null != groupInfoDTO.getUgwInterop()) {
                groupPersistDTO.setUgwInterop(groupInfoDTO.getUgwInterop());
            } else if (null == groupInfoDTO.getUgwInterop() && adedSGMDN || !grpMdns.isEmpty()) {
                groupInfoDTO.setUgwInterop(UGWINTEROP_DBVALUE);
                groupPersistDTO.setUgwInterop(UGWINTEROP_DBVALUE);
            } else if (null == groupInfoDTO.getUgwInterop() && null != grpBasicInfo.getUgwInterop()) {
                //Empty group with ugwInteropEnabled or ugwInteropDisabled can exist
                groupInfoDTO.setUgwInterop(grpBasicInfo.getUgwInterop());
                groupPersistDTO.setUgwInterop(grpBasicInfo.getUgwInterop());
            } else if (null == groupInfoDTO.getUgwInterop()) {
                groupInfoDTO.setUgwInterop(UGWINTEROP_DBVALUE_DISABLED);
                groupPersistDTO.setUgwInterop(UGWINTEROP_DBVALUE_DISABLED);
            }
            knLogger.debug(methodName, "groupInfoDTO.getAvatar()", groupInfoDTO.getAvatar());

            if (groupInfoDTO.getAvatar() != null && groupInfoDTO.getAvatar() == AVATAR_NOT_MODIFIED)
                groupInfoDTO.setAvatar(null);


            if(groupInfoDTO.getCorpSharedCorpInfoList() != null){
                List<Integer> groups = new ArrayList<>(1);
                groups.add(groupInfoDTO.getGroupId());
                groupInfoUtil.deleteSharedGroups(groups, xdmsHome, persisterTxn);

                // P6-4 DELTA: compute added/removed hierarchy entries (TC-GRP-MOD-014/015)
                try {
                    List<int[]> existingHierMappings = groupInfoUtil.getSharedGroupHierarchyMappings(groupInfoDTO.getGroupId(), xdmsHome, persisterTxn);

                    // Build existing hierarchy->corpId map from DB rows (row[0]=hierachyId as int, row[1]=corpId)
                    // Pad to 8 digits to match the string format used in the request (e.g. 103 → "00000103")
                    Map<String, Integer> existingHierCorpMap = new LinkedHashMap<>();
                    for (int[] row : existingHierMappings) {
                        existingHierCorpMap.put(String.format("%08d", row[0]), row[1]);
                    }

                    // Build new hierarchy->corpId map from request hierarchyList
                    List<KnCorpSharedCorpInfo> sharedList = groupPersistDTO.getCorpSharedCorpInfoList();
                    Map<String, Integer> newHierCorpMap = new LinkedHashMap<>();
                    if (sharedList != null) {
                        for (KnCorpSharedCorpInfo info : sharedList) {
                            List<KnXDMHierarchyInfo> hierList = info.getHierarchyList();
                            if (hierList != null && info.getCorpId() != null) {
                                for (KnXDMHierarchyInfo hierInfo : hierList) {
                                    String sharedHierarchyId = hierInfo.getSharedHierarchyId();
                                    if (sharedHierarchyId != null && !sharedHierarchyId.isEmpty()) {
                                        newHierCorpMap.put(sharedHierarchyId, info.getCorpId());
                                    }
                                }
                            }
                        }
                    }

                    // Compute removed hierarchy entries
                    List<String> toRemoveHierIds = new ArrayList<>();
                    Set<Integer> toRemoveCorpIds = new HashSet<>();
                    for (Map.Entry<String, Integer> e : existingHierCorpMap.entrySet()) {
                        if (!newHierCorpMap.containsKey(e.getKey())) {
                            toRemoveHierIds.add(e.getKey());
                            toRemoveCorpIds.add(e.getValue());
                        }
                    }

                    // TC-GRP-MOD-008: block hierarchy removal if affected corp still has members in group
                    if (!toRemoveHierIds.isEmpty()) {
                        for (KnCorpGroupMemberDTO member : groupPersistDTO.getExistingGrpMemDetail()) {
                            if (member.getCorpId() != 0 && toRemoveCorpIds.contains(member.getCorpId())) {
                                knLogger.error(methodName, "TC-GRP-MOD-008: Cannot remove hierarchy scope; corp still has group members. corpId=", member.getCorpId());
                                throw new KnCorpBOException(KnErrorCodes.Validator.GROUP_SHARED_FLAG_MODIFY_NOT_ALLOWED,
                                        "Cannot remove hierarchy scope while members from the affected corp are still in the group");
                            }
                        }
                    }

                    // Compute added hierarchy entries
                    List<String> toAddHierIds = new ArrayList<>();
                    List<Integer> toAddCorpIds = new ArrayList<>();
                    for (Map.Entry<String, Integer> e : newHierCorpMap.entrySet()) {
                        if (!existingHierCorpMap.containsKey(e.getKey())) {
                            toAddHierIds.add(e.getKey());
                            toAddCorpIds.add(e.getValue());
                        }
                    }

                    // Apply delta: remove only removed entries, insert only new entries
                    if (!toRemoveHierIds.isEmpty()) {
                        knLogger.debug(methodName, "P6-4: Removing hierarchy map entries for groupId=", groupInfoDTO.getGroupId(), " count=", toRemoveHierIds.size());
                        groupInfoUtil.removeGroupHiearchyMapByOwnerIds(groupInfoDTO.getGroupId(), toRemoveHierIds, "4", xdmsHome, persisterTxn);
                    }
                    if (!toAddHierIds.isEmpty()) {
                        knLogger.debug(methodName, "P6-4: Inserting hierarchy map entries for groupId=", groupInfoDTO.getGroupId(), " count=", toAddHierIds.size());
                        groupInfoUtil.insertSharedGroupHierarchyMap(groupInfoDTO.getGroupId(), toAddHierIds, toAddCorpIds, xdmsHome, persisterTxn);
                    }
                } catch (KnCorpBOException e) {
                    throw e;
                } catch (Exception e) {
                    knLogger.warn(methodName, "P6-4: Error during hierarchy delta for groupId=", groupInfoDTO.getGroupId(), " - ", e.getMessage());
                }

                if(!groupInfoDTO.getCorpSharedCorpInfoList().isEmpty()){
                    List<KnCorpGroupInfoPersistDTO> groupInfoPersistDTOList= new ArrayList<>();
                    groupPersistDTO.setCorpId(corpId);
                    groupPersistDTO.setGroupId(groupInfoDTO.getGroupId());
                    groupInfoPersistDTOList.add(groupPersistDTO);
                    groupInfoUtil.createGroupSharedCorpInfo(groupInfoPersistDTOList,xdmsHome,persisterTxn);
                }
            }

            // P7-2: Handle explicit addedCorpSharedCorpInfoList / removedCorpSharedCorpInfoList (owner corp only)
            if (groupInfoDTO.isOwnerCorpReq()) {
                List<KnCorpSharedCorpInfo> addedSharedList = groupInfoDTO.getAddedCorpSharedCorpInfoList();
                List<KnCorpSharedCorpInfo> removedSharedList = groupInfoDTO.getRemovedCorpSharedCorpInfoList();

                if (removedSharedList != null && !removedSharedList.isEmpty()) {
                    // Split removedSharedList into two groups:
                    // - partialRemovals: entries with a specific hierarchyList → remove only those hierarchies, keep corp sharing
                    // - fullRemovals: entries without a hierarchyList → remove entire corp sharing + all its hierarchies
                    List<KnCorpSharedCorpInfo> partialRemovals = new ArrayList<>();
                    List<KnCorpSharedCorpInfo> fullRemovals = new ArrayList<>();
                    for (KnCorpSharedCorpInfo info : removedSharedList) {
                        if (info.getHierarchyList() != null && !info.getHierarchyList().isEmpty()) {
                            partialRemovals.add(info);
                        } else {
                            fullRemovals.add(info);
                        }
                    }

                    // Handle partial removals: remove only the specified hierarchy IDs,
                    // then clean up CORPGRP_SHAREDLIST for any corp that now has no remaining hierarchies.
                    if (!partialRemovals.isEmpty()) {
                        try {
                            // Track corpId -> hierarchy IDs being removed
                            Map<Integer, List<String>> corpToRemovedHierIds = new LinkedHashMap<>();
                            List<String> hierIdsToRemove = new ArrayList<>();
                            for (KnCorpSharedCorpInfo info : partialRemovals) {
                                if (info.getCorpId() == null) continue;
                                List<String> idsForCorp = new ArrayList<>();
                                for (KnXDMHierarchyInfo hierInfo : info.getHierarchyList()) {
                                    String sharedHierarchyId = hierInfo.getSharedHierarchyId();
                                    if (sharedHierarchyId != null && !sharedHierarchyId.isEmpty()) {
                                        hierIdsToRemove.add(sharedHierarchyId);
                                        idsForCorp.add(sharedHierarchyId);
                                    }
                                }
                                if (!idsForCorp.isEmpty()) {
                                    corpToRemovedHierIds.put(info.getCorpId(), idsForCorp);
                                }
                            }
                            if (!hierIdsToRemove.isEmpty()) {
                                Set<String> hierIdsToRemoveSet = new HashSet<>(hierIdsToRemove);
                                List<KnCorpGroupMemberDTO> existingMembersP72 = groupPersistDTO.getExistingGrpMemDetail();
                                if (existingMembersP72 != null) {
                                    for (KnCorpGroupMemberDTO member : existingMembersP72) {
                                        String memberHierarchyId = member.getHierarchyId();
                                        if (memberHierarchyId != null && hierIdsToRemoveSet.contains(memberHierarchyId.trim())) {
                                            knLogger.error(methodName, "[Hierarchy] P7-2: Cannot remove shared hierarchy: member exists with hierarchyId=", memberHierarchyId.trim());
                                            throw new KnCorpBOException(KnErrorCodes.Validator.GROUP_SHARED_FLAG_MODIFY_NOT_ALLOWED,
                                                    "Shared member exist cannot unshare");
                                        }
                                    }
                                }
                                knLogger.debug(methodName, "P7-2: Removing specific hierarchy map entries for groupId=", groupInfoDTO.getGroupId(), " count=", hierIdsToRemove.size());
                                groupInfoUtil.removeGroupHiearchyMapByOwnerIds(groupInfoDTO.getGroupId(), hierIdsToRemove, "4", xdmsHome, persisterTxn);
                                allRemovedHierIds.addAll(hierIdsToRemove);
                            }
                            // After removal, check if any corp now has no remaining hierarchy entries;
                            // if so, also remove it from CORPGRP_SHAREDLIST to avoid orphaned rows.
                            if (!corpToRemovedHierIds.isEmpty()) {
                                List<int[]> remainingMappings = groupInfoUtil.getSharedGroupHierarchyMappings(groupInfoDTO.getGroupId(), xdmsHome, persisterTxn);
                                Set<Integer> corpsWithRemainingHier = new HashSet<>();
                                for (int[] row : remainingMappings) {
                                    corpsWithRemainingHier.add(row[1]);
                                }
                                Set<Integer> corpsNowEmpty = new HashSet<>();
                                for (Integer sharedCorpId : corpToRemovedHierIds.keySet()) {
                                    if (!corpsWithRemainingHier.contains(sharedCorpId)) {
                                        corpsNowEmpty.add(sharedCorpId);
                                    }
                                }
                                if (!corpsNowEmpty.isEmpty()) {
                                    knLogger.debug(methodName, "P7-2: Removing CORPGRP_SHAREDLIST entries for corps with no remaining hierarchies, corpIds=", corpsNowEmpty);
                                    List<KnCorpSharedCorpInfo> existingShared = groupInfoUtil.selectGroupSharedCorpInfo(corpId, groupInfoDTO.getGroupId(), xdmsHome, persisterTxn);
                                    List<Integer> groupsToDelete = new ArrayList<>(1);
                                    groupsToDelete.add(groupInfoDTO.getGroupId());
                                    groupInfoUtil.deleteSharedGroups(groupsToDelete, xdmsHome, persisterTxn);
                                    List<KnCorpGroupInfoPersistDTO> reinsertList = new ArrayList<>();
                                    for (KnCorpSharedCorpInfo existing : existingShared) {
                                        if (!corpsNowEmpty.contains(existing.getCorpId()) && !Objects.equals(existing.getCorpId(), corpId)) {
                                            KnCorpGroupInfoPersistDTO dto = new KnCorpGroupInfoPersistDTO();
                                            dto.setCorpId(corpId);
                                            dto.setGroupId(groupInfoDTO.getGroupId());
                                            List<KnCorpSharedCorpInfo> singleList = new ArrayList<>(1);
                                            singleList.add(existing);
                                            dto.setCorpSharedCorpInfoList(singleList);
                                            reinsertList.add(dto);
                                        }
                                    }
                                    if (!reinsertList.isEmpty()) {
                                        groupInfoUtil.createGroupSharedCorpInfo(reinsertList, xdmsHome, persisterTxn);
                                    }
                                }
                            }
                        } catch (KnCorpBOException e) {
                            throw e;
                        } catch (Exception e) {
                            knLogger.warn(methodName, "P7-2: Error removing partial hierarchy entries - ", e.getMessage());
                        }
                    }

                    // Handle full corp removals: remove all hierarchy entries for the corp and drop from CORPGRP_SHAREDLIST
                    if (!fullRemovals.isEmpty()) {
                        Set<Integer> removedCorpIds = new HashSet<>();
                        for (KnCorpSharedCorpInfo info : fullRemovals) {
                            if (info.getCorpId() != null) removedCorpIds.add(info.getCorpId());
                        }
                        // TC-GRP-MOD-008: block removal if corp still has members in group
                        for (KnCorpGroupMemberDTO member : groupPersistDTO.getExistingGrpMemDetail()) {
                            if (member.getCorpId() != 0 && removedCorpIds.contains(member.getCorpId())) {
                                knLogger.error(methodName, "TC-GRP-MOD-008: Cannot remove sharing for corp with existing members. corpId=", member.getCorpId());
                                throw new KnCorpBOException(KnErrorCodes.Validator.GROUP_SHARED_FLAG_MODIFY_NOT_ALLOWED,
                                        "Cannot remove group sharing while members from the affected corp are still in the group");
                            }
                        }
                        // Remove all hierarchy map entries for the fully-removed corps
                        try {
                            List<int[]> existingHierMappings = groupInfoUtil.getSharedGroupHierarchyMappings(groupInfoDTO.getGroupId(), xdmsHome, persisterTxn);
                            List<String> hierIdsToRemove = new ArrayList<>();
                            for (int[] row : existingHierMappings) {
                                if (removedCorpIds.contains(row[1])) {
                                    hierIdsToRemove.add(String.format("%08d", row[0]));
                                }
                            }
                            if (!hierIdsToRemove.isEmpty()) {
                                knLogger.debug(methodName, "P7-2: Removing all hierarchy map entries for removed corps, groupId=", groupInfoDTO.getGroupId());
                                groupInfoUtil.removeGroupHiearchyMapByOwnerIds(groupInfoDTO.getGroupId(), hierIdsToRemove, "4", xdmsHome, persisterTxn);
                                allRemovedHierIds.addAll(hierIdsToRemove);
                            }
                        } catch (Exception e) {
                            knLogger.warn(methodName, "P7-2: Error removing hierarchy entries for removed corps - ", e.getMessage());
                        }
                        // Read existing CORPGRP_SHAREDLIST, delete all, reinsert only kept entries
                        List<KnCorpSharedCorpInfo> existingShared = groupInfoUtil.selectGroupSharedCorpInfo(corpId, groupInfoDTO.getGroupId(), xdmsHome, persisterTxn);
                        List<Integer> groups = new ArrayList<>(1);
                        groups.add(groupInfoDTO.getGroupId());
                        groupInfoUtil.deleteSharedGroups(groups, xdmsHome, persisterTxn);
                        List<KnCorpGroupInfoPersistDTO> reinsertList = new ArrayList<>();
                        for (KnCorpSharedCorpInfo existing : existingShared) {
                            if (!removedCorpIds.contains(existing.getCorpId()) && !Objects.equals(existing.getCorpId(), corpId)) {
                                KnCorpGroupInfoPersistDTO dto = new KnCorpGroupInfoPersistDTO();
                                dto.setCorpId(corpId);
                                dto.setGroupId(groupInfoDTO.getGroupId());
                                List<KnCorpSharedCorpInfo> singleList = new ArrayList<>(1);
                                singleList.add(existing);
                                dto.setCorpSharedCorpInfoList(singleList);
                                reinsertList.add(dto);
                            }
                        }
                        if (!reinsertList.isEmpty()) {
                            groupInfoUtil.createGroupSharedCorpInfo(reinsertList, xdmsHome, persisterTxn);
                        }
                    }
                }

                if (addedSharedList != null && !addedSharedList.isEmpty()) {
                    // Check which corps are already in CORPGRP_SHAREDLIST to avoid unique constraint violation.
                    // This handles the case where a corp is already shared but a new hierarchy is being added.
                    List<KnCorpSharedCorpInfo> existingSharedCorps = groupInfoUtil.selectGroupSharedCorpInfo(corpId, groupInfoDTO.getGroupId(), xdmsHome, persisterTxn);
                    Set<Integer> alreadySharedCorpIds = new HashSet<>();
                    for (KnCorpSharedCorpInfo existing : existingSharedCorps) {
                        if (existing.getCorpId() != null) alreadySharedCorpIds.add(existing.getCorpId());
                    }
                    // Only insert corps that are not already in CORPGRP_SHAREDLIST
                    List<KnCorpSharedCorpInfo> newCorpsToInsert = new ArrayList<>();
                    for (KnCorpSharedCorpInfo info : addedSharedList) {
                        if (!alreadySharedCorpIds.contains(info.getCorpId()) && !Objects.equals(info.getCorpId(), corpId)) {
                            newCorpsToInsert.add(info);
                        }
                    }
                    if (!newCorpsToInsert.isEmpty()) {
                        List<KnCorpGroupInfoPersistDTO> addPersistList = new ArrayList<>();
                        KnCorpGroupInfoPersistDTO addDto = new KnCorpGroupInfoPersistDTO();
                        addDto.setCorpId(corpId);
                        addDto.setGroupId(groupInfoDTO.getGroupId());
                        addDto.setCorpSharedCorpInfoList(newCorpsToInsert);
                        addPersistList.add(addDto);
                        groupInfoUtil.createGroupSharedCorpInfo(addPersistList, xdmsHome, persisterTxn);
                    }
                    // Insert hierarchy map entries for all added entries (whether corp is new or already shared)
                    List<String> hierIdsToAdd = new ArrayList<>();
                    List<Integer> corpIdsToAdd = new ArrayList<>();
                    for (KnCorpSharedCorpInfo info : addedSharedList) {
                        List<KnXDMHierarchyInfo> hierList = info.getHierarchyList();
                        if (hierList != null && info.getCorpId() != null) {
                            for (KnXDMHierarchyInfo hierInfo : hierList) {
                                String sharedHierarchyId = hierInfo.getSharedHierarchyId();
                                if (sharedHierarchyId != null && !sharedHierarchyId.isEmpty()) {
                                    hierIdsToAdd.add(sharedHierarchyId);
                                    corpIdsToAdd.add(info.getCorpId());
                                }
                            }
                        }
                    }
                    if (!hierIdsToAdd.isEmpty()) {
                        knLogger.debug(methodName, "P7-2: Inserting hierarchy map entries for added corps, groupId=", groupInfoDTO.getGroupId(), " count=", hierIdsToAdd.size());
                        groupInfoUtil.insertSharedGroupHierarchyMap(groupInfoDTO.getGroupId(), hierIdsToAdd, corpIdsToAdd, xdmsHome, persisterTxn);
                    }
                }
            }

            //insert to group memberlist
            if (addedMembers != null && !addedMembers.isEmpty()) {
                groupInfoUtil.insertIntoCorpGroupDistInfo(memberDetailsList, xdmsHome, persisterTxn);
            }

            //RECORDING_TARGET_INFO
            Map<String, String> microServicesParamNameValueMap = genInfoUtil.retrieveMSSvcsCommonConfig(clusterId, persisterTxn);
            String targetInfoOptimization = microServicesParamNameValueMap.get(com.kodiak.xdms.server.common.resources.KnConstants.TARGET_INFO_OPTIMIZATION);
            if (!com.kodiak.xdms.server.common.util.KnGeneralUtil.isTargetInfoOptimizationEnabled(targetInfoOptimization)) {
                knLogger.info(methodName, "Target Info Optimization is not enabled.--->");
                Collection<String> targetList = new ArrayList<>();
                targetList.add(recordingTarget);
                IXDMServerDAO commonXDMServerDAO = KnFactorySelector.getDAOFactory(KnFactorySelector.DB).createXDMServerDAO(xdmsHome);
                Collection<KnRecordingTargetInfoDTO> dbRecordingTargetList = commonXDMServerDAO
                        .getRecordingInfoTargetByTarget(targetList, persisterTxn);

                if (dbRecordingTargetList.isEmpty() && recordingInfoList != null) {
                    commonXDMServerDAO.createRecordingInfoForTarget(recordingInfoList, persisterTxn);

                }
                if (dbRecordingTargetList.size() > 0 && recordingInfoList != null) {
                    Map<String, Integer> updateRecordingInfo = recordingInfoList.stream().collect(Collectors.toMap(KnRecordingTargetInfoDTO::getTarget, KnRecordingTargetInfoDTO::getRecType));
                    commonXDMServerDAO.updateRecordingInfoTargetByTarget(updateRecordingInfo, persisterTxn);
                }

                if (disabledTarget != null && !disabledTarget.isEmpty()) {
                    commonXDMServerDAO.deleteRecordingInfoTargetByTarget(disabledTarget, persisterTxn);
                }
            }
            // Get the final members list in the group. This will be used to set DISPATCH_GROUP_MEMBER column in subscrinfo table.
            Set<String> completeList = getDisptachGrpMemmberToBeSetInResponse(groupInfoDTO, memberDetailsList);
            completeList.removeAll(pocMdnPersistDto.getGroupMdnList());

            respDto.setEnabledDispatchMemList(completeList);
            //updating etag
            Map<Integer, Integer> groupEtagMap = groupInfoUtil.updateGroupListEtag(groupIdLst, xdmsHome, persisterTxn);
            Map<String, KnOPDirChgDTO> etagMap = new HashMap<>();
            Collection<String> currentGroupMemberList = new ArrayList<>();  //Will contain the only members in the group currenly for which replace notification should be sent.
            Collection<String> addedGroupMemberList = new ArrayList<>(); //Will contain the added members in the group.
            Collection<String> deletedGroupMemberList = new HashSet<>(); //Will contain the deleted members in the group.
            currentGroupMemberList.addAll(groupDistList.get(grpId));
            if (memberDetailsList != null && !memberDetailsList.isEmpty()) {
                if ((memberDetailsList.get(grpId)).get(ADDED_MEMBERS) != null && !(memberDetailsList.get(grpId)).get(ADDED_MEMBERS).isEmpty()) {
                    addedGroupMemberList.addAll((memberDetailsList.get(grpId)).get(ADDED_MEMBERS));
                }
                if ((memberDetailsList.get(grpId)).get(DELTED_MEMBERS) != null && !(memberDetailsList.get(grpId)).get(DELTED_MEMBERS).isEmpty()) {
                    currentGroupMemberList.removeAll((memberDetailsList.get(grpId)).get(DELTED_MEMBERS));
                    addedGroupMemberList.removeAll((memberDetailsList.get(grpId)).get(DELTED_MEMBERS));
                    deletedGroupMemberList.addAll((memberDetailsList.get(grpId)).get(DELTED_MEMBERS));
                }

            }
            //setting external members
            Collection<String> allExternalMdnList=new ArrayList<>();
            if(!exterrnalMembers.isEmpty()){
                knLogger.debug(methodName," exterrnalMembers :",exterrnalMembers);
                addedGroupMemberList.addAll(exterrnalMembers);
                allExternalMdnList.addAll(exterrnalMembers);
            }
            Collection<KnCorpGroupMemberDTO> existigGrpMemberDetails = groupInfoUtil.getCorpGroupMembersList(groupIdLst, xdmsHome, persisterTxn);
            List<String> groupMembersList=existigGrpMemberDetails.stream().map(KnCorpGroupMemberDTO::getMdn).collect(Collectors.toList());
            ICorpXdmDAO corpXdmDao = new KnCorpXdmDAO(xdmsHome);
            Collection<KnCorpSubscriberDTO> externalGrpMemberDetails = corpXdmDao.getExternalPoCSubscriberInfo(groupMembersList,
                    corpId, persisterTxn);
            if(!externalGrpMemberDetails.isEmpty()){
                List<String> existingExternalGrpMdn = externalGrpMemberDetails.stream().map(KnCorpSubscriberDTO::getMdn).collect(Collectors.toList());
                knLogger.debug(methodName," existingExternalGrpMdn :",existingExternalGrpMdn);
                allExternalMdnList.addAll(existingExternalGrpMdn);
                currentGroupMemberList.addAll(existingExternalGrpMdn);
            }
            Collection<KnSIPProxySvcConfigDTO> sipProxySvcConfigInfoDTO = commonInfoUtil.getSipProxySvcConfig(xdmsHome, persisterTxn);
            String groupPocHome = groupInfoUtil.fetchGroupPocHome(grpId, xdmsHome, persisterTxn);
            String effectivePocHome = genInfoUtil.getEffectivePocHome(corpPocHome, groupPocHome);
            String groupSipUri = sipProxySvcConfigInfoDTO.stream()
                    .filter(sipProxy -> sipProxy.getPttServerId().equals(effectivePocHome)).findFirst()
                    .map(KnSIPProxySvcConfigDTO::getSipProxyURI).orElse(null);
            groupInfoDTO.setExternalMdnList(allExternalMdnList);
            groupInfoDTO.setIsPreConfiguredGroup(grpBasicInfo.getIsPreConfiguredGroup());
            if (isUgwInterop) {
                groupInfoDTO.setUgwInterop(UGWINTEROP_DBVALUE);
            }
            //Sending notify to to all the base mdns+ baseMdns profile mdns of the ABDG group
            Map<String, List<String>> addedMemProfileBaseMdnMap = new HashMap<>();
            if (AREA_BASED_DYNAMIC_GROUP == groupInfoDTO.getClientType() && !addedGroupMemberList.isEmpty()) {
                Map<String, List<String>> profileBaseMdnMap = corpSubsProvInfoUtil.getMapOfProfileMdnByBaseMdn(new ArrayList<>(addedGroupMemberList), xdmsHome, persisterTxn);
                addedMemProfileBaseMdnMap.putAll(profileBaseMdnMap);
                if (!profileBaseMdnMap.isEmpty()) {
                    ArrayList<String> profileMdns = new ArrayList<>();
                    profileBaseMdnMap.values().forEach(profileMdns::addAll);
                    knLogger.debug(methodName, " fetched all the profile mdns ", KnGDPRTemplate.mdnList(profileMdns));
                    addedGroupMemberList.addAll(profileMdns);
                }
            }

            Map<Integer, Collection<String>> addedGrpMemMap = new HashMap<>();
            Map<Integer, Collection<String>> currentGrpMemMap = new HashMap<>();
            Map<Integer, Collection<String>> deletedGrpMemMap = new HashMap<>();
            addedGrpMemMap.put(grpId, addedGroupMemberList);
            currentGrpMemMap.put(grpId, currentGroupMemberList);
            deletedGrpMemMap.put(grpId, deletedGroupMemberList);
            Map<Integer, KnCorpGroupDTO> groupDetailsMap = new HashMap<>();
            groupDetailsMap.put(grpId, groupInfoDTO);
            //Forming notification for added members only
            knLogger.debug(" mod addedGrpMemMap :",addedGrpMemMap);
            if (grpBasicInfo.getIsPreConfiguredGroup() != null && grpBasicInfo.getIsPreConfiguredGroup() == IS_PRECONFIG_GRP_ENABLE) {
                List<String> preConfGrpCorpMem = groupInfoUtil.getPreConfGrpCorpMem(groupInfoDTO.getGrpShared(), groupInfoDTO.getGroupId(),
                        corpId,xdmsHome, persisterTxn);
                addedGrpMemMap.put(grpId, preConfGrpCorpMem);
                // etagMap = commonInfoUtil.formSubscriberNotification(addedGrpMemMap, groupEtagMap,0, etagMap, groupDetailsMap, null);
            }
            etagMap = commonInfoUtil.formSubscriberNotification(addedGrpMemMap, groupEtagMap,
                    com.kodiak.xdms.server.common.resources.KnConstants.DOC_CHANGE_TYPE.REPLACE.value(), etagMap, groupDetailsMap, grpBasicInfo.getGroupCreatedBy());

            Map<Integer, Collection<String>> currentGroupMember = groupInfoUtil.selectGroupMemberListForGroupIds(groupIdLst, xdmsHome, persisterTxn); // current group member list entries

            Collection<String> completeDispatcherList = new ArrayList<String>();
            completeDispatcherList.addAll(reqDispatcherSubscribers);
            Map<Integer, Collection<KnCorpSubscriberDTO>> actualMdnToBeAddedToGroup = new HashMap<Integer, Collection<KnCorpSubscriberDTO>>();
            Map<Integer, Collection<KnCorpContactDTO>> groupMemberInsertList = new HashMap<Integer, Collection<KnCorpContactDTO>>();
            Set<String> groupMembersLIList = new HashSet<String>();
            if (memberList != null && !memberList.isEmpty()) {
                Collection<String> memberListToBeAdded = new ArrayList<String>();
                for (KnCorpSubscriberDTO corpSubsDto : memberList) {
                    memberListToBeAdded.add(corpSubsDto.getMdn());
                }
                Map<Integer, Collection<KnCorpSubscriberDTO>> actualMdnToBeAddedToGroupMap = new HashMap<Integer, Collection<KnCorpSubscriberDTO>>();
                List<String> allMdnList = new ArrayList<>();
                actualMdnToBeAddedToGroupMap.put(grpId, memberList);
                actualMdnToBeAddedToGroup = commonInfoUtil.filterGroupMembersTobeAdded(currentGroupMember, actualMdnToBeAddedToGroupMap);
                for (Entry<Integer, Collection<KnCorpSubscriberDTO>> entry : actualMdnToBeAddedToGroup.entrySet()) {
                    Collection<KnCorpContactDTO> grpMemberList = new ArrayList<KnCorpContactDTO>();
                    Collection<KnCorpSubscriberDTO> mdnList = entry.getValue();
                    Integer groupId = entry.getKey();
                    for (KnCorpSubscriberDTO subscriberDTO : mdnList) {
                        allMdnList.add(subscriberDTO.getMdn());
                        KnCorpContactDTO contact = new KnCorpContactDTO();
                        contact.setCorpId(subscriberDTO.getCorpId());
                        contact.setMdn(subscriberDTO.getMdn());
                        if (supervisiorMap.containsKey(subscriberDTO.getMdn())) {
                            contact.setSupervisory(supervisiorMap.get(subscriberDTO.getMdn()));
                        }
                        if (locWatcherMap.containsKey(subscriberDTO.getMdn())) {
                            contact.setLocWatcher(locWatcherMap.get(subscriberDTO.getMdn()));
                        }
                        contact.setName(subscriberDTO.getName());
                        contact.setContact_type(subscriberDTO.getContact_type());
                        contact.setClientType(subscriberDTO.getClientType());
                        if (subscriberDTO.getClientType() == GROUPMDN.value()) {
                            contact.setMemberType(SG_MDN_MEMBER_TYPE);
                            groupInfoDTO.setUgwInterop(UGWINTEROP_DBVALUE);
                            groupPersistDTO.setUgwInterop(UGWINTEROP_DBVALUE);
                        } else if (subscriberDTO.getClientType() == SUBSCR_CLIENT_TYPE.SGMDNPATCH.value()) {
                            contact.setMemberType(SG_MDN_PATCH_MEMBER_TYPE);
                            groupInfoDTO.setUgwInterop(UGWINTEROP_DBVALUE);
                            groupPersistDTO.setUgwInterop(UGWINTEROP_DBVALUE);
                        }
                        contact.setCallInitiatePermission(subscriberDTO.getCallInitiatePermission());
                        contact.setCallReceivePermission(subscriberDTO.getCallReceivePermission());
                        contact.setInCallPermission(subscriberDTO.getInCallPermission());
                        contact.setVideoCallInitiatePermission(subscriberDTO.getVideoCallInitiatePermission());
                        contact.setVideoInCallPermission(subscriberDTO.getVideoInCallPermission());
                        contact.setVideoCallReceivePermission(subscriberDTO.getVideoCallReceivePermission());

                        knLogger.debug(methodName, "subscriberDTO.getUa() - ", subscriberDTO.getUa());
                        contact.setUa(subscriberDTO.getUa());
                        contact.setAliasMdn(subscriberDTO.getAliasMdn());
                        contact.setUserId(subscriberDTO.getUserId());
                        contact.setSubsActiveFS2(subscriberDTO.getSubsActiveFS2());
                        contact.setIsOSMAuthorize(subscriberDTO.getIsOSMAuthorize());

                        if (exterrnalMembers.contains(subscriberDTO.getMdn())) {
                            contact.setGroupModifyPerm(DISABLED);
                        } else {
                            contact.setGroupModifyPerm(groupModifyPermMap.get(subscriberDTO.getMdn()));
                        }
                        boolean bitEnabled = KnGeneralUtil.getFeatureBitValue(subscriberDTO.getSubsActiveFS2(), FEATURE_SET.AFFILIATIONFEATURE.value());
                        knLogger.debug(methodName," Checking PV Version and bit enabled  and subscriberDTO.getClientType() ",subscriberDTO.getClientPVmajorVer(),bitEnabled,subscriberDTO.getClientType());
                        if (subscriberDTO.getClientPVmajorVer() >= com.kodiak.xdms.server.common.resources.KnConstants.PROTOCOL_VERSION_18
                                && bitEnabled && checkClientType(subscriberDTO.getClientType(), subscriberDTO.getMcpttCompliance()))
                        {
                            contact.setIsAffiliationEnabled(ENABLED);
                        } else {
                            contact.setIsAffiliationEnabled(DISABLED);
                        }
                        knLogger.debug(methodName," Contact###### ",contact);
                        grpMemberList.add(contact);
                        groupMembersLIList.add(subscriberDTO.getMdn());
                    }
                    groupMemberInsertList.put(groupId, grpMemberList);
                }
                if (!pochomeAutoAssignFlag) {
                    String pocHome = groupInfoUtil.fetchGroupPocHome(grpId, xdmsHome, persisterTxn);
                    if (pocHome == null) {
                        Map<String, Object> pochomeMap = groupInfoUtil.getPocHomeAndClusterIdForCorpGroup(allMdnList, xdmsHome, persisterTxn);
                        String selectedPocHome = null;
                        Integer selectedClusterId = null;
                        selectedClusterId = (Integer) pochomeMap.get(CLUSTERID);
                        selectedPocHome = (String) pochomeMap.get(POCHOME);
                        groupInfoUtil.updatePocHome(selectedPocHome, selectedClusterId, grpId, xdmsHome, persisterTxn);
                    }
                }
                if (groupMemberInsertList != null && !groupMemberInsertList.isEmpty()) {
                    groupInfoUtil.insertIntoCorpGroupMemberList(groupMemberInsertList, xdmsHome, persisterTxn);
                }

            }
            groupInfoUtil.modifyGroupDetails(groupInfoDTO, xdmsHome, persisterTxn);
            //DAO calls to insert and delete from the dg.corpgroupdistinfo table
            Collection<String> deletedMembers = (memberDetailsList.get(grpId)).get(KnPersisterConstants.DELTED_MEMBERS);
            if (deletedMembers != null && !deletedMembers.isEmpty()) {
                groupInfoUtil.deleteFrmCorpGroupDistInfo(memberDetailsList, xdmsHome, persisterTxn);
            }

            for (KnCorpGroupMemberDTO corpMem : completeSupervisorList) {
                if (corpMem.getGroupModifyPerm() == null && existingGroupModifyPermMap.containsKey(corpMem.getMdn())) {
                    corpMem.setGroupModifyPerm(existingGroupModifyPermMap.get(corpMem.getMdn()));
                } else if (exterrnalMembers.contains(corpMem.getMdn())) {
                    corpMem.setGroupModifyPerm(DISABLED);
                }
            }

            if (completeSupervisorList != null && !completeSupervisorList.isEmpty()) {
                groupInfoUtil.updateGroupMemberListSupervisorList(completeSupervisorList, grpId, xdmsHome, persisterTxn);
            }

            List<String> supervisiorMdn = new ArrayList<>();
            if (completeSupervisorList != null) {
                for (KnCorpGroupMemberDTO supervisiorList : completeSupervisorList) {
                    supervisiorMdn.add(supervisiorList.getMdn());
                }
            }
            //Setting the AliasId for External contact
            Map<String, KnCorpSubsEntitiesDTO> subsEntitiesDTOMap = contactInfoUtil.getSubsEntitiesDetails(supervisiorMdn, xdmsHome, persisterTxn);
            knLogger.debug(methodName, "subsEntitiesDTOMap: ", KnGDPRTemplate.mapKeyMdn(subsEntitiesDTOMap));

            for (KnCorpGroupMemberDTO subsc : completeSupervisorList) {
                if (subsEntitiesDTOMap.containsKey(subsc.getMdn())) {
                    subsc.setAliasMdn(subsEntitiesDTOMap.get(subsc.getMdn()).getAliasMdn());
                    subsc.setUserId(subsEntitiesDTOMap.get(subsc.getMdn()).getUserId());
                    subsc.setSubsActiveFS2(subsEntitiesDTOMap.get(subsc.getMdn()).getActiveFs2());
                }
            }

            LinkedHashMap<Integer, LinkedList<Integer>> delGroupMemStatus = new LinkedHashMap<Integer, LinkedList<Integer>>();
            Collection<String> deletedMemberList = new ArrayList<String>();
            LinkedHashMap<Integer, LinkedList<String>> actualMdnToBeDeletedFromGroupMap = new LinkedHashMap<Integer, LinkedList<String>>();
            //Collection<KnCorpGroupMemberDTO> deletedGrpMemSuperVisorList = new ArrayList<KnCorpGroupMemberDTO>();
            if (uniqueMdnToBeDeletedToGroup != null && !uniqueMdnToBeDeletedToGroup.isEmpty()) {
                LinkedList<String> memberListToBeDeleted = new LinkedList<String>();
                for (KnCorpSubscriberDTO corpSubsDto1 : uniqueMdnToBeDeletedToGroup) {
                    memberListToBeDeleted.add(corpSubsDto1.getMdn());
                   /* KnCorpGroupMemberDTO groupMemberDTO = new KnCorpGroupMemberDTO();
                    groupMemberDTO.setMdn(corpSubsDto1.getMdn());
                    deletedGrpMemSuperVisorList.add(groupMemberDTO);*/
                }
                actualMdnToBeDeletedFromGroupMap.put(grpId, memberListToBeDeleted);
                delGroupMemStatus = groupInfoUtil.deleteCorpGroupMemberList(actualMdnToBeDeletedFromGroupMap, xdmsHome, persisterTxn);
                //groupInfoUtil.updateGroupMemberListSupervisorList(deletedGrpMemSuperVisorList, grpId, xdmsHome, persisterTxn);
                //respDto.setDeletedDispatchGrpMemberList(memberListToBeDeleted);
                deletedMemberList.addAll(memberListToBeDeleted);
            }
            //Group:
            List<Integer> groupIds = new ArrayList<>();
            groupIds.add(grpId);
            Collection<String> addlTgDelMdnList = new ArrayList<>();
            Collection<KnCorpAddlTGInfoDTO> delAddlTGList = new ArrayList<>();
            Collection<KnCorpAddlTGInfoDTO> subsAddlTGList = groupInfoUtil.getSubsAddlDetails(groupIds, xdmsHome, persisterTxn);
            Map<String, Collection<String>> groupFailurePairingMap = new HashMap<>();
            Map<String, Collection<String>> actualDeletedGroupMemberMap = getDeletedMembers(actualMdnToBeDeletedFromGroupMap, delGroupMemStatus);
            if (actualDeletedGroupMemberMap != null && !actualDeletedGroupMemberMap.isEmpty()) {
                knLogger.debug(methodName, "actualDeletedGroupMemberMap-- ", KnGDPRTemplate.mapKeyValueListMdn(actualDeletedGroupMemberMap));
                Map<String, Collection<String>> emergDestUserMap = corpSubsProvInfoUtil.getEmergDestUserMap(actualDeletedGroupMemberMap.keySet(),
                        xdmsHome, persisterTxn);
                knLogger.debug(methodName, "emergDestUserMap-- ", KnGDPRTemplate.mapKeyValueListMdn(emergDestUserMap));
                if (emergDestUserMap != null && !emergDestUserMap.isEmpty()) {
                    emergDestUserMap.forEach((emergDest, emergUser) -> {
                        Collection<String> removedGroupMember = actualDeletedGroupMemberMap.get(emergDest);
                        Collection<String> mappedDestination = emergUser.stream().filter(removedGroupMember::contains).collect(Collectors.toList());
                        if (mappedDestination != null && !mappedDestination.isEmpty())
                            groupFailurePairingMap.put(emergDest, mappedDestination);
                    });
                }
                knLogger.debug(methodName, "groupFailurePairingMap-- ", groupFailurePairingMap);
                if (!groupFailurePairingMap.isEmpty()) {
                    knLogger.error(methodName, "Emergency Destination Mapping Exists - Group");
                    throw new KnCorpBOValidationException(KnErrorCodes.Validator.EMERGENCY_DESTINATION_MAPPING_EXISTS_FOR_GROUP,
                            "Emergency Destination Mapping Exists for Group--", CORP_GROUP_MANAGER,
                            MODIFY_GROUP, "", groupFailurePairingMap.keySet().toString(), "");
                }
                // Additional Talk Group:
                if (subsAddlTGList != null && !subsAddlTGList.isEmpty()) {
                    delAddlTGList.addAll(subsAddlTGList.stream().filter(addlMem -> (actualDeletedGroupMemberMap
                            .get(String.valueOf(addlMem.getGroupId())) != null) && actualDeletedGroupMemberMap
                            .get(String.valueOf(addlMem.getGroupId())).contains(addlMem.getMdn())).collect(Collectors.toList()));
                    knLogger.debug(methodName, "delAddlTGList-- ", delAddlTGList);
                    if (delAddlTGList != null) {
                        groupInfoUtil.deleteSubsAddlTGList(delAddlTGList, xdmsHome, persisterTxn);
                        addlTgDelMdnList.addAll(delAddlTGList.stream().map(KnCorpAddlTGInfoDTO::getMdn).collect(Collectors.toList()));
                    }
                }
            }
            Collection<String> deletedIntMembers = new ArrayList<String>();
            Collection<String> deletedExtMembers = new ArrayList<String>();
            Collection<String> notDeletedMembers = new ArrayList<String>();
            if (finalGroupMembersinDB != null && !finalGroupMembersinDB.isEmpty()) {
                if (!isObjectNull(uniqueMdnToBeDeletedToGroup)) {
                    for (KnCorpSubscriberDTO subsc : uniqueMdnToBeDeletedToGroup) {
                        if (!finalGroupMembersinDB.contains(subsc.getMdn())) {
                            //populating only internal guys for the notifications
                            if (subsc.getCorpId() == corpId) {
                                deletedIntMembers.add(subsc.getMdn());
                            } else {
                                deletedExtMembers.add(subsc.getMdn());
                            }
                        } else {
                            if (subsc.getCorpId() == corpId) {
                                notDeletedMembers.add(subsc.getMdn());
                            }
                        }
                    }
                }
            } else {
                if (!isObjectNull(uniqueMdnToBeDeletedToGroup)) {
                    for (KnCorpSubscriberDTO subsc : uniqueMdnToBeDeletedToGroup) {
                        //populating only internal guys for the notifications
                        if (subsc.getCorpId() == corpId) {
                            deletedIntMembers.add(subsc.getMdn());
                        } else {
                            deletedExtMembers.add(subsc.getMdn());
                        }
                    }
                }
            }
            //Get the external members of the group.
            LinkedList<String> currentExtMemList = groupInfoUtil.getExternalGrpMembers(grpId, xdmsHome, persisterTxn);
            Collection<String> delMems = new ArrayList<String>(deletedIntMembers);
            delMems.removeAll(pocMdnPersistDto.getGroupMdnList());


            //De-assigning the group Camped to deleted subscribers. As camped can only possible for internal members.
            //During deassing not considering the external contacts.

            Map<Integer, List<String>> grpMemLstMap = new HashMap<Integer, List<String>>(1);
            grpMemLstMap.put(grpId, new ArrayList<String>(deletedIntMembers));
            groupInfoUtil.cleanUpCampedGrp(grpMemLstMap, corpInOutParamDTO, xdmsHome, persisterTxn);
            knLogger.debug(methodName, "deletedIntMembers - ", KnGDPRTemplate.mdnList(deletedIntMembers));



            if (groupPersistDTO.getGroupType() == DISPATCH_GROUP) {
                respDto.setDisabledDispatchMemList(deletedIntMembers);
            }

            Collection<Integer> sublistIdList = new ArrayList<Integer>();
            sublistIdList.add(groupPersistDTO.getGroupMemberListId());
            if ((groupInfoDTO.getAddedMdnsList() == null || groupInfoDTO.getAddedMdnsList().isEmpty()) &&
                    (groupInfoDTO.getAddedSublistIds() == null || groupInfoDTO.getAddedSublistIds().isEmpty())) {
                sublistInfoUtil.updateSublistsSubscribersContactCount(sublistIdList, MAX_LIMIT_VALIDATION_NOT_REQUIRED,
                        MAX_LIMIT_VALIDATION_NOT_REQUIRED, MAX_LIMIT_VALIDATION_NOT_REQUIRED, xdmsHome, persisterTxn, MAX_LIMIT_VALIDATION_NOT_REQUIRED);
            } else if (groupInfoDTO.getGroupType() == STANDARD_GROUP) {
                if (corpProfile.getLargeGrpSupported() == 1) {
                    sublistInfoUtil.updateSublistsSubscribersContactCount(sublistIdList, MAX_LIMIT_VALIDATION_NOT_REQUIRED,
                            corpProfile.getMaxMemPerLrgGrp(), MAX_LIMIT_VALIDATION_NOT_REQUIRED, xdmsHome, persisterTxn, MAX_LIMIT_VALIDATION_NOT_REQUIRED);
                } else {
                    sublistInfoUtil.updateSublistsSubscribersContactCount(sublistIdList, MAX_LIMIT_VALIDATION_NOT_REQUIRED,
                            corpProfile.getMaxMemPerCorpGroup(), MAX_LIMIT_VALIDATION_NOT_REQUIRED, xdmsHome, persisterTxn, MAX_LIMIT_VALIDATION_NOT_REQUIRED);
                }

            } else {
                if (corpProfile.getLargeGrpSupported() == 1) {
                    if (grpBasicInfo.getGroupCreatedBy() == CREATED_BY.ABDG.value()) {
                        int maxAbdgLrgGrpMems = Integer.valueOf(paramNameValueMapService.get(MAX_USR_PER_LRGABDG_TALKGRP).trim());
                        sublistInfoUtil.updateSublistsSubscribersContactCount(sublistIdList, MAX_LIMIT_VALIDATION_NOT_REQUIRED,
                                MAX_LIMIT_VALIDATION_NOT_REQUIRED, maxAbdgLrgGrpMems, xdmsHome, persisterTxn, MAX_LIMIT_VALIDATION_NOT_REQUIRED);
                    } else {
                        sublistInfoUtil.updateSublistsSubscribersContactCount(sublistIdList, MAX_LIMIT_VALIDATION_NOT_REQUIRED,
                                MAX_LIMIT_VALIDATION_NOT_REQUIRED, corpProfile.getMaxMemPerLrgGrp(), xdmsHome, persisterTxn, MAX_LIMIT_VALIDATION_NOT_REQUIRED);
                    }

                } else {
                    sublistInfoUtil.updateSublistsSubscribersContactCount(sublistIdList, MAX_LIMIT_VALIDATION_NOT_REQUIRED,
                            MAX_LIMIT_VALIDATION_NOT_REQUIRED, corpProfile.getMaxMembersPerDispatchGroup(), xdmsHome, persisterTxn, MAX_LIMIT_VALIDATION_NOT_REQUIRED);
                }

            }


            Map<Integer, Collection<String>> groupDistMap = groupInfoUtil.getGroupSubscriberDistList(groupIdLst, xdmsHome, persisterTxn);
            boolean newLargeGroupFlag = false;
            //UCSPROVCONFIG-8968
            int newMemberCount = 0;
            Map<Integer, Integer> newGroupMemberCount = groupInfoUtil.getGroupMemCount(groupIdLst, xdmsHome, persisterTxn);
            if (newGroupMemberCount != null && !newGroupMemberCount.isEmpty() && newGroupMemberCount.containsKey(grpId)) {
                newMemberCount = newGroupMemberCount.getOrDefault(grpId, 0);
            }
            if (corpProfile.getLargeGrpSupported() == 1) {
                if (grpBasicInfo.getGrpType() == STANDARD_GROUP && newMemberCount > corpProfile.getMaxMemPerCorpGroup()) {
                    newLargeGroupFlag = true;
                }
                if (grpBasicInfo.getGrpType() == DISPATCH_GROUP && newMemberCount > corpProfile.getMaxMembersPerDispatchGroup()) {
                    newLargeGroupFlag = true;
                }
            }
            Collection<KnCorpGroupMemberDTO> grpMemberDetails = groupInfoUtil.getCorpGroupMembersList(groupIdLst, xdmsHome, persisterTxn);
            Map<String, KnCorpGroupMemberDTO> grpMemMap = grpMemberDetails.stream().collect(Collectors.toMap(KnCorpGroupMemberDTO::getMdn, exist -> exist));
            KnCorpGroupDTO groupBasicInfo = groupInfoUtil.getGroupBasicInfo(groupInfoDTO.getGroupId(), groupInfoDTO.getClientType(),
                    xdmsHome, persisterTxn);
            int groupCorpId = groupBasicInfo.getCorpId();

            Collection<String> locWatcherMember = new ArrayList<>();
            Collection<String> nonLocWatcherMember = new ArrayList<>();
            Collection<String> totalMemMdn = new ArrayList<>();
            Collection<String> locWatcherRemoved = new ArrayList<>();
            Collection<String> locWatcherMemberBaseMdns = new ArrayList<>();
            boolean locWatcherExist = false;
            if (!grpMemberDetails.isEmpty()) {
                for (KnCorpGroupMemberDTO groupMemberDTO : grpMemberDetails) {
                    if (groupMemberDTO.getLocWatcher() == LOCWATCHER) {
                        locWatcherMember.add(groupMemberDTO.getMdn());
                        locWatcherExist = true;
                    } else {
                        nonLocWatcherMember.add(groupMemberDTO.getMdn());
                    }
                }
                totalMemMdn.addAll(locWatcherMember);
                totalMemMdn.addAll(nonLocWatcherMember);
                Map<String, KnCorpSubscriberDTO> contDetailsMap = contactInfoUtil.getSubsribersCorporateDetails(totalMemMdn, xdmsHome, persisterTxn);
                if(groupCorpId==corpId){
                    Collection<String> sharedGroupMember=contDetailsMap.entrySet().stream().filter(e -> e.getValue()
                            .getCorpId()!=groupCorpId).map(k ->k.getKey()).collect(Collectors.toList());
                    knLogger.debug(methodName," sharedGroupMember :",sharedGroupMember);
                    //owned group request
                    totalMemMdn.removeAll(sharedGroupMember);
                    locWatcherMember.removeAll(sharedGroupMember);
                    nonLocWatcherMember.removeAll(sharedGroupMember);
                }else if (groupCorpId!=corpId){
                    Collection<String> ownedGroupMember=contDetailsMap.entrySet().stream().filter(e -> e.getValue()
                            .getCorpId()!=corpId).map(k ->k.getKey()).collect(Collectors.toList());
                    knLogger.debug(methodName," ownedGroupMember:",ownedGroupMember);
                    //shared group request
                    totalMemMdn.removeAll(ownedGroupMember);
                    locWatcherMember.removeAll(ownedGroupMember);
                    nonLocWatcherMember.removeAll(ownedGroupMember);
                }
                //Addition of private contact list is not allowed for profile mdn

                locWatcherMemberBaseMdns.addAll(locWatcherMember);
                locWatcherMemberBaseMdns.removeIf(mdn -> contDetailsMap.get(mdn).getUserProfileIndex() != null && contDetailsMap.get(mdn).getUserProfileIndex() != 0);
            }


            respDto.setRemovedLocWatcherList(grpMemberMap.entrySet().stream().filter(mdnDetailsBeforeModify
                            -> mdnDetailsBeforeModify.getValue().getLocWatcher() == ENABLED && (!grpMemMap.containsKey(mdnDetailsBeforeModify.getKey())
                            || (grpMemMap.containsKey(mdnDetailsBeforeModify.getKey()) && grpMemMap.get(mdnDetailsBeforeModify.getKey()).getLocWatcher() == DISABLED)))
                    .map(Entry::getKey).collect(Collectors.toList()));
            knLogger.info("newLargeGroupFlag - ", newLargeGroupFlag, ", grpBasicInfo.isLargeGroup() - ", grpBasicInfo.isLargeGroup());

            String locationFeatureFlagForLG = paramNameValueMapCommon.get(LOCATION_FEATURE_FOR_LG_FLAG) != null ? paramNameValueMapCommon.get(LOCATION_FEATURE_FOR_LG_FLAG) : "0";
            if (Objects.equals(Integer.parseInt(locationFeatureFlagForLG), DISABLE_LOCATION_FEATURE_FOR_LG_FLAG) && grpBasicInfo.getGrpType() == KnConstants.DISPATCH_GROUP && newLargeGroupFlag && !grpBasicInfo.isLargeGroup()) {
                // normal to large or large to large dispatch group
                knLogger.info("normal to large dispatch group", totalMemMdn.size());
            } else if (Objects.equals(Integer.parseInt(locationFeatureFlagForLG), DISABLE_LOCATION_FEATURE_FOR_LG_FLAG) && grpBasicInfo.getGrpType() == KnConstants.DISPATCH_GROUP && !newLargeGroupFlag && grpBasicInfo.isLargeGroup()) {
                // large to normal dispatch group
                knLogger.info("large to normal dispatch group", totalMemMdn.size());
                respDto.setEnabledDispatchMemList(totalMemMdn);
            } else {
                //If the group was not a large group and after update also not large group then prepare doc diff
                // notifications and contact assignment to the loc watcher supervisors.
                contactInfoUtil.contactForSupervisiorLocWatcher(locWatcherMemberBaseMdns, totalMemMdn, corpId, corpProfile.getMaxContactsPerSubsc(),
                        etagMap, corpProfile.getXdmsHome(), persisterTxn);

                if (locWatcherExist) {
                    Collection<String> enabledMember = new HashSet<>();
                    if (respDto.getEnabledDispatchMemList() != null) {
                        enabledMember.addAll(respDto.getEnabledDispatchMemList());
                    }
                    enabledMember.addAll(totalMemMdn);
                    respDto.setEnabledDispatchMemList(enabledMember);
                    respDto.setAddedLocWatcherList(locWatcherMember);
                }
                Collection<String> disabledMember = new HashSet<>();
                if (respDto.getDisabledDispatchMemList() != null) {
                    disabledMember.addAll(respDto.getDisabledDispatchMemList());
                }
                nonLocWatcherMember.addAll(deletedMemberList);
                disabledMember.addAll(nonLocWatcherMember);
                respDto.setDisabledDispatchMemList(disabledMember);
                //AddlTg Notify for Group Change.
                Collection<String> addlTgAllMdnList = subsAddlTGList.stream().map(KnCorpAddlTGInfoDTO::getMdn).collect(Collectors.toList());
                etagMap = groupInfoUtil.updateAddlTalkGroupImpactedTables(xdmsHome, addlTgAllMdnList, persisterTxn, etagMap, upmCall, false);
                /*Collection<KnCorpAddlTGInfoDTO> modifyAddlTGList = new ArrayList<>();
                addlTgAllMdnList.removeAll(addlTgDelMdnList);
                if (addlTgAllMdnList != null && !addlTgAllMdnList.isEmpty()) {
                    addlTgAllMdnList.forEach(modMdn -> {
                        KnCorpAddlTGInfoDTO corpAddlTGInfoDTO = new KnCorpAddlTGInfoDTO();
                        corpAddlTGInfoDTO.setAvatar(groupInfoDTO.getAvatar());
                        corpAddlTGInfoDTO.setGroupMemCount(grpMemberDetails.size());
                        corpAddlTGInfoDTO.setGroupType(NOT_MODIFIED);
                        corpAddlTGInfoDTO.setGroupCreatedBy(NOT_MODIFIED);
                        corpAddlTGInfoDTO.setGroupId(grpId);
                        corpAddlTGInfoDTO.setMdn(modMdn);
                        modifyAddlTGList.add(corpAddlTGInfoDTO);
                    });
                }
                knLogger.debug(methodName, "etagMap AddlTG -for modify- ", etagMap);
                etagMap = KnCorpCommonInfoUtil.formXcapAddlTGDiffNotification(etagMap, null,
                        modifyAddlTGList, delAddlTGList, corpId);*/
                //Map<String, HashMap<Integer, String>> groupListStatus = groupInfoUtil.getGroupListStatus(grpIds, xdmsHomePttId, persisterTxn);
                knLogger.debug(methodName, "etagMap AddlTG -diff -for modify- ", etagMap);
                //Forming notification for existing group members
                knLogger.debug(" mod currentGrpMemMap :", currentGrpMemMap);
                //Sending notify to to all the base mdns+ baseMdns profile mdns of the ABDG group
                if (AREA_BASED_DYNAMIC_GROUP == groupInfoDTO.getClientType() && !currentGrpMemMap.isEmpty()) {
                    ArrayList<String> currentMembers = new ArrayList<>(currentGrpMemMap.get(grpId));
                    Map<String, List<String>> profileBaseMdnMap = corpSubsProvInfoUtil.getMapOfProfileMdnByBaseMdn(currentMembers, xdmsHome, persisterTxn);
                    if (!profileBaseMdnMap.isEmpty()) {
                        ArrayList<String> profileMdns = new ArrayList<>();
                        profileBaseMdnMap.values().forEach(profileMdns::addAll);
                        knLogger.debug(methodName, " fetched all the profile mdns ", KnGDPRTemplate.mdnList(profileMdns));
                        currentGrpMemMap.get(grpId).addAll(profileMdns);
                    }
                }
                etagMap = commonInfoUtil.formSubscriberNotification(currentGrpMemMap, groupEtagMap,
                        com.kodiak.xdms.server.common.resources.KnConstants.DOC_CHANGE_TYPE.REPLACE.value(), etagMap, groupDetailsMap, grpBasicInfo.getGroupCreatedBy());
                if (null != deletedGrpMemMap && !deletedGrpMemMap.isEmpty() && null != currentGrpMemMap && !currentGrpMemMap.isEmpty()) {
                    Collection<String> currentMembers = currentGrpMemMap.get(groupEtagMap.keySet().iterator().next());
                    if (currentMembers.isEmpty()) {
                        etagMap = commonInfoUtil.formSubscriberNotification(deletedGrpMemMap, groupEtagMap,
                                com.kodiak.xdms.server.common.resources.KnConstants.DOC_CHANGE_TYPE.REPLACE.value(), etagMap,
                                groupDetailsMap, grpBasicInfo.getGroupCreatedBy());
                    }
                }

                //Updating the notification for the nopt deleted members in the group
                if (!isObjectNull(notDeletedMembers) && !notDeletedMembers.isEmpty()) {
                    Map<Integer, Collection<String>> notDeletedMemMap = new HashMap<Integer, Collection<String>>();
                    if (!exterrnalMembers.isEmpty()) {
                        notDeletedMembers.addAll(exterrnalMembers);
                    }
                    notDeletedMemMap.put(grpId, notDeletedMembers);
                    etagMap = commonInfoUtil.formSubscriberNotification(notDeletedMemMap, groupEtagMap,
                            com.kodiak.xdms.server.common.resources.KnConstants.DOC_CHANGE_TYPE.REPLACE.value(), etagMap, groupDetailsMap, grpBasicInfo.getGroupCreatedBy());
                }
                boolean isEmptyGroup = false;
                int reqGroupId = grpBasicInfo.getGroupId();
                Collection<String> groupInfos = currentGrpMemMap.get(reqGroupId);
                knLogger.debug(methodName, " reqGroupId :", reqGroupId, " groupInfos :", groupInfos);
                if (groupInfos == null || groupInfos.isEmpty()) {
                    isEmptyGroup = true;
                }

                etagMap = contactInfoUtil.updateDistinctSubcribersDirectory(null, groupIdLst, etagMap, xdmsHome, upmCall, persisterTxn);

                if (AREA_BASED_DYNAMIC_GROUP == groupInfoDTO.getClientType() && !currentGrpMemMap.isEmpty()) {
                    Map<Integer, Collection<KnCorpContactDTO>> addMem = new HashMap<>(groupMemberInsertList);
                    CopyOnWriteArrayList<KnCorpContactDTO> members = new CopyOnWriteArrayList<>();
                    if (null != addMem.get(grpId)) {
                        members.addAll(addMem.get(grpId));
                    }
                    List<String> profileMdnList = new ArrayList<>();
                    if (!members.isEmpty()) {
                        for (KnCorpContactDTO mem : members) {
                            if (null != addedMemProfileBaseMdnMap.get(mem.getMdn())) {
                                List<String> profileMdns = addedMemProfileBaseMdnMap.get(mem.getMdn());
                                profileMdnList.addAll(profileMdns);
                                for (String profilemdn : profileMdns) {
                                    KnCorpContactDTO profiledto = new KnCorpContactDTO();
                                    profiledto.setMdn(profilemdn);
                                    profiledto.setBroadcaster(mem.getBroadcaster());
                                    profiledto.setCallInitiatePermission(mem.getCallInitiatePermission());
                                    profiledto.setSupervisory(mem.getSupervisory());
                                    profiledto.setIsOSMAuthorize(mem.getIsOSMAuthorize());
                                    profiledto.setLocWatcher(mem.getLocWatcher());
                                    profiledto.setCorpId(mem.getCorpId());
                                    profiledto.setName(mem.getName());
                                    profiledto.setIsAffiliationEnabled(mem.getIsAffiliationEnabled());
                                    profiledto.setClientType(mem.getClientType());
                                    profiledto.setSubscriberFs2(mem.getSubscriberFs2());
                                    if (!members.contains(profiledto)) {
                                        members.add(profiledto);
                                    }
                                }
                            }
                        }
                        addMem.put(grpId, members);
                    }
                    knLogger.debug(methodName, " addMem :", addMem);
                    Map<Integer, Collection<String>> groupDist = new HashMap<>(groupDistMap);
                    CopyOnWriteArrayList<String> distList = new CopyOnWriteArrayList();
                    if (null != addMem.get(grpId)) {
                        distList.addAll(groupDist.get(grpId));
                    }
                    knLogger.debug(methodName, " groupDist are coming: ", groupDist, " distList :", distList);
                    if (!distList.isEmpty()) {
                        for (String mdn : distList) {
                            if (null != addedMemProfileBaseMdnMap.get(mdn)) {
                                List<String> profileMdns = addedMemProfileBaseMdnMap.get(mdn);
                                profileMdns.forEach(profileMdn -> {
                                    if (!distList.contains(profileMdn)) {
                                        distList.add(profileMdn);
                                    }
                                });
                            }
                        }
                        groupDist.put(grpId, distList);
                    }
                    knLogger.debug(methodName, "ABDG GROUP BLOCK", " addMem :", addMem, " groupDist :", groupDist, " distList :", distList);
                    etagMap = formXcapDiffNotification(etagMap, null, null,
                            null, addMem, actualMdnToBeDeletedFromGroupMap, groupInfoDTO.getGroupDisplayName(),
                            completeSupervisorList, groupDist, null, delGroupMemStatus, groupInfoDTO.getAvatar(),
                            osmListChanged, isEmptyGroup, currentGroupMemberList, profileMdnList);
                } else {
                    //Moving the doc diff notification inside islarge group flag false block.
                    etagMap = formXcapDiffNotification(etagMap, null, null,
                            null, groupMemberInsertList, actualMdnToBeDeletedFromGroupMap, groupInfoDTO.getGroupDisplayName(),
                            completeSupervisorList, groupDistMap, null, delGroupMemStatus, groupInfoDTO.getAvatar(),
                            osmListChanged, isEmptyGroup, currentGroupMemberList, null);
                }
            }
            Map<Integer, Integer> groupLrgGrpFlagMap = new HashMap<>(1);
            if (newLargeGroupFlag && !grpBasicInfo.isLargeGroup()) {
                groupLrgGrpFlagMap.put(grpId, 1);
            } else if (!newLargeGroupFlag && grpBasicInfo.isLargeGroup()) {
                groupLrgGrpFlagMap.put(grpId, 0);
            }
            groupInfoUtil.updateIsLargeGrpFlag(groupLrgGrpFlagMap, xdmsHome, persisterTxn);

            etagMap = commonInfoUtil.formTGSCDocumentNotification(corpInOutParamDTO, etagMap, xdmsHome, persisterTxn);

            //Contact assignment and de-assignment to the dispatchers are moved down

            knLogger.debug(methodName, "AssignindgContact - ", groupPersistDTO);
            assignContactsForDispatcher(groupInfoDTO, groupPersistDTO, corpProfile,
                    currentGroupMember, pocMdnPersistDto, groupDistList, memberList,
                    uniqueMdnToBeDeletedToGroup, externalMembersDTOList, memberDetailsList, finalGroupMembersinDB,
                    etagMap, persisterTxn);

            KnCorpGroupInfoRespDTO resp = deAssignContactForDipatchGroup(groupInfoDTO, groupPersistDTO,
                    corpProfile, corpMdnListPersistDto, delMems, deletedExtMembers, groupDistList,
                    groupInternalMembers, actualMdnToBeAddedToGroup.get(grpId), groupEtagMap, currentExtMemList, etagMap, persisterTxn);

            if (newLargeGroupFlag || grpBasicInfo.isLargeGroup()) {
                Set<String> mdnSet = new HashSet<>(etagMap.keySet());
                for (String mdn : mdnSet) {
                    KnOPDirChgDTO chgDTO = etagMap.get(mdn);
                    if (chgDTO.getDocChgDTO() == null || chgDTO.getDocChgDTO().isEmpty()) {
                        etagMap.remove(mdn);
                    }
                }
            }

            if (deletedMemberList != null && deletedMemberList.size() > 0) {
                knLogger.debug(methodName, "Check if any mdns are part of simultainous session");
                List<String> delMdnList = new ArrayList<String>();
                delMdnList.addAll(deletedMemberList);
                groupInfoUtil.cleanUpTGSSGrpMdn(grpId, delMdnList, corpInOutParamDTO, xdmsHome, persisterTxn);
                etagMap = commonInfoUtil.formTGSSDocumentNotification(corpInOutParamDTO, etagMap, xdmsHome, persisterTxn);
            }


            if (resp.getDisabledDispatchMemList() != null) {
                deletedMemberList.addAll(resp.getDisabledDispatchMemList());
            }

            //removing the newly added group mdns from the etagMap MDN=  8, 17
            /*While removing the last member from group the notification is not going so the below
            code is comemnted.*/
//            for (String grpMdn : pocMdnPersistDto.getGroupMdnList()) {
//                etagMap.remove(grpMdn);
//            }
            //remove the existing group mdn from the notification
            if (grpMdns != null && etagMap.size() > 2) {
                for (String mdn : grpMdns) {
                    etagMap.remove(mdn);
                }
            }
            if (AREA_BASED_DYNAMIC_GROUP == groupInfoDTO.getClientType()) {
                Set<String> existingMembers = grpMemberMap.keySet();
                LinkedList<String> finalDeletedMembers = actualMdnToBeDeletedFromGroupMap.get(grpId);
                String grpOwner = grpBasicInfo.getGrpOwner();
                if (isNullOrEmpty(groupName) || (!isNullOrEmpty(groupName) && groupName.equals(groupPersistDTO.getGroupDisplayName()))) {
                    for (String mdn : existingMembers) {
                        if (!mdn.equals(grpOwner) && (finalDeletedMembers != null && !finalDeletedMembers.contains(mdn))) {
                            etagMap.remove(mdn);
                        }
                    }
                }
            }
            if(!upmCall){
                //this block should be called for system profile,As user profile is handled seperatly
                Map<Integer, Integer> groupListMap = new HashMap<>();
                groupListMap.put(groupInfoDTO.getGroupId(), CB_MAPPING.ETAG_CHANGE.value());
                Map<String, Collection<KnDocChangeListDTO>> profileMdnEtagMap = corpUserProfileUtil.updateImpactedCBDocuments(String.valueOf(corpId), null,
                        groupListMap, null, xdmsHome, null, allRemovedHierIds.isEmpty() ? null : new ArrayList<>(allRemovedHierIds), persisterTxn);
                respDto.setProfileMdnEtagMap(profileMdnEtagMap);
                if(profileMdnEtagMap != null && profileMdnEtagMap.isEmpty()){
                    respDto.setMcsXcapRootUriMap(genInfoUtil.getXCAPRootURI(new ArrayList<>(profileMdnEtagMap.keySet()), persisterTxn, true));
                }
            }

            if(upmCall){
                knLogger.info(methodName, "upm call set group sharing from grpbasicInfo");
                isGrpSharingEnabled = grpBasicInfo.getGrpShared()!=null && grpBasicInfo.getGrpShared() == GROUP_SHARING_ENABLE_INDICATOR;
            }

            List<KnCorpGroupMemberDTO> delMembersdetails = existigGrpMemberDetails.stream()
                    .filter(member -> deletedGroupMemberList.contains(member.getMdn()))
                    .collect(Collectors.toList());
            grpMemberDetails.addAll(delMembersdetails);

            if(isGrpSharingEnabled) {
                knLogger.info(methodName, "Entering into groupsharing flow");
                if (groupInfoDTO.isOwnerCorpReq()) {
                    knLogger.debug(methodName, "Request from owner corp");
                    resetNotiCapabilityOnwedCorp(etagMap);
                } else {
                    knLogger.debug(methodName, "Request from shared corp - ", groupInfoDTO.getCorpId(), " Group Corp - ", grpBasicInfo.getGroupCorpId());
                    List<String> sharedReqCorpMemList = new ArrayList<>();
                    if (grpMemberDetails != null && !grpMemberDetails.isEmpty()) {
                        knLogger.debug(methodName, "grpMemberDetails:- ", grpMemberDetails, "delMembersdetails:-", delMembersdetails);
                        for (KnCorpGroupMemberDTO grpMember : grpMemberDetails) {
                            if (grpMember.getCorpId() == groupInfoDTO.getCorpId()) {
                                sharedReqCorpMemList.add(grpMember.getMdn());
                            }
                        }
                    }
                    removeOtherCorpMembers(etagMap, sharedReqCorpMemList);
                }
            }
            respDto.setChangeLogMap(etagMap);

            if (null != groupPersistDTO.getUgwInterop()) {
                respDto.setLmrInteropFlag(groupPersistDTO.getUgwInterop());
            }
            respDto.setGrpSIPUri(groupSipUri);

            if (null == recordFsValue && null != grpBasicInfo.getRecordingFs()) {
                recordFsValue = grpBasicInfo.getRecordingFs();
            }
            respDto.setRecordingFs(recordFsValue);

            knLogger.debug(methodName, "Populate the liEventList Data");
            Map<Integer, String> groupNameMap = new HashMap<Integer, String>();
            groupNameMap.put(grpId, corpId +LINE_SAPERATOR+ groupName);
            Map<Integer, Collection<String>> actualGroupMembers = new HashMap<Integer, Collection<String>>();
            if (groupDistList != null && groupDistList.get(grpId) != null) {
                groupMembersLIList.addAll(groupDistList.get(grpId));
            }

            Set<String> externalSubsc = new HashSet<String>();
            if (currentExtMemList != null && !currentExtMemList.isEmpty()) {
                externalSubsc.addAll(currentExtMemList);
                if (deletedExtMembers != null && !deletedExtMembers.isEmpty()) {
                    externalSubsc.removeAll(deletedExtMembers);
                }
                groupMembersLIList.addAll(externalSubsc);
            }
            actualGroupMembers.put(grpId, groupMembersLIList);
            LinkedList<KnLIEventDTO> liEventList=null;
            if(!upmCall){
                liEventList = populateLIData(etagMap, xdmsHome
                        , groupNameMap, actualGroupMembers, groupDistList,persisterTxn);
            }else{
                liEventList = upmPopulateLIData(etagMap, xdmsHome
                        , groupNameMap, actualGroupMembers, groupDistList,groupMemberInsertList,actualMdnToBeDeletedFromGroupMap,persisterTxn);
            }
            knLogger.debug(methodName," LiEvent List-", liEventList.size());
            respDto.setLiEventList(liEventList);
            respDto.setEtag(String.valueOf(groupEtagMap.get(grpId)));
            respDto.setTgsModeChgMap(corpInOutParamDTO.getTgsModeChgMap());
            respDto.setMdnCorpId(grpBasicInfo.getGroupCorpId()); // Provides the CorpId of the Group owner.
            respDto.setGroupCreatedBy(grpBasicInfo.getGroupCreatedBy());
            respDto.setNewGroupDisplayName(groupPersistDTO.getGroupDisplayName());
            populate(respDto);
            if (responseDTO.getFailedDataList() != null && !responseDTO.getFailedDataList().isEmpty()) {
                respDto.setFailedDataList(responseDTO.getFailedDataList());
            }
            //If the corporate is already linked i.e linked gateway key is not null get the refernce id
            if (corpProfile.getLinkedGwKey() != null && pocMdnPersistDto.isGrpMdnPresent()) {
                //get the refernce id from the account info table.
                KnCorpGWLinkedAccountInfoDTO accountInfo = commonInfoUtil.getCorporateLinkedAccountInfo(corpProfile.getLinkedGwKey(), xdmsHome, persisterTxn);
                //update etag in the account info table
                //update etag
                Map<String, String> asyncInput = new HashMap<>();
                asyncInput.put(KnDbSyncFwConstants.PTTSERVER_ID, xdmsHome);
                asyncInput.put(KnDbSyncFwConstants.NNI_REF_ID, accountInfo.getNniRefId());
                knLogger.debug(methodName, " Async inputs", asyncInput);
                KnSqlJobCollector collector = KnSqlJobCollector.getInstance();
                int serviceType = KnDbSyncFwConstants.EXECUTOR.ETAG_UPDATE_NNI.value();
                collector.collect(serviceType, asyncInput);

            }

            //Changes for PDMBB-12990
            //Assign Zones and Position
            //If new flag is not null and is enabled then only do below

            String autoAssignZoneChannelFlag = genInfoUtil.retrieveMSSvcsCommonConfig(clusterId, persisterTxn)
                    .get(AUTO_ASSIGN_ZONE_POSITION);
            knLogger.debug(methodName, "autoAssignZoneChannelFlag:", autoAssignZoneChannelFlag);
            // If auto-assign is disabled, return disabled status
            if (autoAssignZoneChannelFlag != null && autoAssignZoneChannelFlag.equals("1") && ((memberDTOList != null && !memberDTOList.isEmpty()) || (groupMemberInsertList != null && !groupMemberInsertList.isEmpty()))  && groupInfoDTO.getGroupCreatedBy() != CREATED_BY.ABDG.value()) {
                Collection<KnCorpSubscriberDTO> memberDTOListCopy = memberDTOList;
                if((memberDTOListCopy == null || memberDTOListCopy.isEmpty()) && (groupMemberInsertList != null && !groupMemberInsertList.isEmpty())){
                    Collection<KnCorpContactDTO> contactDTOList = groupMemberInsertList.get(groupInfoDTO.getGroupId());
                    if(contactDTOList != null && !contactDTOList.isEmpty()){
                        memberDTOListCopy = contactDTOList.stream()
                                .map(contact -> {
                                    KnCorpSubscriberDTO subscriber = new KnCorpSubscriberDTO();
                                    subscriber.setMdn(contact.getMdn());
                                    subscriber.setCorpId(contact.getCorpId());
                                    subscriber.setName(contact.getName());
                                    subscriber.setContact_type(contact.getContact_type());
                                    subscriber.setClientType(contact.getClientType());
                                    return subscriber;
                                })
                                .collect(Collectors.toList());
                    }
                }
                else{
                    var tempMDNs = memberDTOListCopy.stream().map(member -> member.getMdn().trim()).toList();
                    if((groupMemberInsertList != null && !groupMemberInsertList.isEmpty())){
                        var allAddedMembers = groupMemberInsertList.get(groupInfoDTO.getGroupId());
                        for (KnCorpContactDTO member : allAddedMembers) {
                            if(!tempMDNs.contains(member.getMdn().trim())){
                                memberDTOListCopy.add(member);
                            }
                        }
                    }
                }
                Map<String, Object> assignmentResult = performAutoAssignZonesAndChannels(
                        Arrays.asList(grpId),
                        memberDTOListCopy,
                        corpProfile,
                        contactInfoUtil,
                        persisterTxn
                );
                String autoZonePositionStatus = (String) assignmentResult.get("status");
                // After performAutoAssignZonesAndChannels succeeds update notification with zone/channel data
                if (ZONE_ASSIGNMENT_STATUS.ASSIGNED.value().equals(autoZonePositionStatus) || ZONE_ASSIGNMENT_STATUS.PARTIAL.value().equals(autoZonePositionStatus)) {
                    etagMap = updateAddlTGNotification(grpId, etagMap, xdmsHome, persisterTxn);
                    respDto.setChangeLogMap(etagMap);
                }
                List<String> unassignedMdns = (List<String>) assignmentResult.get("unassignedMdns");
                respDto.setZonePositionAssignmentStatus(autoZonePositionStatus);
                if (unassignedMdns != null && !unassignedMdns.isEmpty()) {
                    respDto.setUnassignedMdns(unassignedMdns);
                }
                knLogger.debug(methodName, "respDto with zonePositionAssignmentStatus:", respDto.getZonePositionAssignmentStatus());
            }
            else{
                respDto.setZonePositionAssignmentStatus(ZONE_ASSIGNMENT_STATUS.DISABLED.value());
                knLogger.info(methodName, "Auto-assignment disabled. Status:", respDto.getZonePositionAssignmentStatus());
            }
        } catch (KnValidationException ve) {
            knLogger.error(methodName, "KnValidationException occured while modifying Group - ", ve);
            populate(respDto, ve);

        } catch (KnCorpBOException be) {
            //corp profile does not exists
            knLogger.error(methodName, "KnCorpBOException occured while modifying Group - ", be);
            populate(respDto, be);

        } catch (Exception e) {
            knLogger.error(methodName, "Unexpected exception occured while modifying Group - ",
                    new KnException(KnErrorCodes.BOEntity.INTERNAL_ERROR, e.getMessage(), e));
            populate(respDto, e);

        }
        return respDto;
    }

    private boolean removeMdnOrSublistOnly(KnIPCorpGroupInfoDTO groupInfoDTO) {
        String methodName = "removeMdnOrSublistOnly(KnIPCorpGroupInfoDTO)";
        boolean removeMdnOnlyFlag = false;
        boolean removedSublistIdsFlag = false;
        if (groupInfoDTO.getRemovedMemberMdns() != null && !groupInfoDTO.getRemovedMemberMdns().isEmpty()) {
            removeMdnOnlyFlag = true;
        }
        if (groupInfoDTO.getRemovedSublistIds() != null && !groupInfoDTO.getRemovedSublistIds().isEmpty()) {
            removedSublistIdsFlag = true;
        }
        if (removeMdnOnlyFlag || removedSublistIdsFlag) {
            boolean addedMemberDTOMdnsFlag = true;
            boolean addedMemberMdnsFlag = true;
            boolean addedSublistIdsFlag = true;
            if (groupInfoDTO.getAddedMemberDTOMdns() == null || groupInfoDTO.getAddedMemberDTOMdns().isEmpty()) {
                addedMemberDTOMdnsFlag = false;
            }
            if (groupInfoDTO.getAddedMemberMdns() == null || groupInfoDTO.getAddedMemberMdns().isEmpty()) {
                addedMemberMdnsFlag = false;
            }
            if (groupInfoDTO.getAddedSublistIds() == null || groupInfoDTO.getAddedSublistIds().isEmpty()) {
                addedSublistIdsFlag = false;
            }

            if (addedMemberDTOMdnsFlag || addedMemberMdnsFlag || addedSublistIdsFlag) {
                removeMdnOnlyFlag = false;
                removedSublistIdsFlag = false;
            }
            knLogger.debug(methodName, " addedMemberDTOMdnsFlag- ", addedMemberDTOMdnsFlag, " addedMemberMdnsFlag- ", addedMemberMdnsFlag,
                    " addedSublistIdsFlag- ", addedSublistIdsFlag);
        }
        return removeMdnOnlyFlag || removedSublistIdsFlag;
    }

    private KnCorpGroupInfoRespDTO deAssignContactForDipatchGroup(KnIPCorpGroupInfoDTO groupInfoDTO,
                                                                  KnCorpGroupInfoPersistDTO groupPersistDTO
            , KnCorpProfileDTO corpProfile, KnCorpMdnListPersistDTO corpMdnListPersistDto,
                                                                  Collection<String> deletedIntMembers,
                                                                  Collection<String> deletedExtMembers,
                                                                  Map<Integer, Collection<String>> groupDistList,
                                                                  ArrayList<String> groupInternalMembers,
                                                                  Collection<KnCorpSubscriberDTO> actualAddedMembers,
                                                                  Map<Integer, Integer> groupEtagMap,
                                                                  LinkedList<String> currentExtMemList,
                                                                  Map<String, KnOPDirChgDTO> etagMap,
                                                                  KnPersisterTxn persisterTxn) throws Exception {
        String methodName = "deAssignContactForDipatchGroup()";
        knLogger.debug(methodName, "groupInfoDTO - ", groupInfoDTO);
        knLogger.debug(methodName, "groupPersistDTO - ", groupPersistDTO);
        knLogger.debug(methodName, "corpProfile - ", corpProfile);
        knLogger.debug(methodName, "corpMdnListPersistDto - ", corpMdnListPersistDto);
        knLogger.debug(methodName, "deletedIntMembers - ", KnGDPRTemplate.mdnList(deletedIntMembers));
        knLogger.debug(methodName, "groupDistList - ", groupDistList);
        knLogger.debug(methodName, "deletedExtMembers - ", KnGDPRTemplate.mdnList(deletedExtMembers));
        knLogger.debug(methodName, "groupInternalMembers - ", KnGDPRTemplate.mdnList(groupInternalMembers) );
        knLogger.debug(methodName, "actualAddedMembers - ", actualAddedMembers);
        knLogger.debug(methodName, "groupEtagMap - ", groupEtagMap);
        knLogger.debug(methodName, "currentExtMemList - ", KnGDPRTemplate.mdnList(currentExtMemList));
        knLogger.debug(methodName, "etagMap - ", KnGDPRTemplate.mapKeyMdn(etagMap));
        KnCorpGroupInfoRespDTO respDto = new KnCorpGroupInfoRespDTO();
        if (groupInfoDTO.isGroupTypeChanged() && STANDARD_GROUP == groupInfoDTO.getGroupType()) {
            //deassign the contacts from the dispatcher and the members
            LinkedList<String> internalMembers = new LinkedList<String>(groupInternalMembers);
            Collection<String> validPocSubscList = corpMdnListPersistDto.getMdnList();
            Collection<KnCorpSubscriberDTO> externalMemList = corpMdnListPersistDto.getAddedExternalMdnList();
            if (validPocSubscList != null) {
                for (String mdn : validPocSubscList) {
                    KnCorpSubscriberDTO subsc = new KnCorpSubscriberDTO();
                    subsc.setMdn(mdn);
                    if (!groupPersistDTO.getRequestDispatcherSubscribers().contains(mdn)
                            && (externalMemList != null && !externalMemList.contains(subsc))) {
                        internalMembers.add(mdn);
                    }
                }
            }
            //removing the newly added members from the list since we dont want the deassignment to happen
            if (actualAddedMembers != null) {
                internalMembers.removeAll(actualAddedMembers);
            }
            respDto.setDisabledDispatchMemList(internalMembers);

            if (groupInfoDTO.isContactPairing()) {
                //deAssignContact(internalMembers, groupPersistDTO.getDbDispatcherSubscribers(), currentExtMemList, etagMap, corpProfile.getXdmsHome(), persisterTxn);
                deAssignContact(internalMembers, groupPersistDTO.getDbDispatcherSubscribers(), groupPersistDTO.getGroupPrivateList(),
                        currentExtMemList, etagMap, corpProfile.getXdmsHome(), corpProfile.getCorpId(), persisterTxn);
            }
        }
        if (
                ((!isObjectNull(deletedIntMembers) && !deletedIntMembers.isEmpty())
                        ||
                        (!isObjectNull(deletedExtMembers) && !deletedExtMembers.isEmpty()))
        ) {
            if (groupInfoDTO.isContactPairing() == KnConstants.TRUE &&
                    (groupInfoDTO.getGroupType() == DISPATCH_GROUP
                            ||
                            groupInfoDTO.getGroupType() == DISPATCH_GROUP)) {
                //code to   the contacts when its a dispatch group with the contact paiing as true
                Set<String> delMemList = new HashSet<String>();
                if (!isObjectNull(deletedIntMembers)) {
                    delMemList.addAll(deletedIntMembers);
                }
                /*if (!KnCorpUtil.isObjectNull(deletedExtMembers)) {
                    delMemList.addAll(deletedExtMembers);
                }*/
                //If any new Dispatcher is added in the request we need to remove the group members from the contact of the old dipatcher and
                //vice versa
                LinkedList<String> dispMembers = new LinkedList<String>();
                if (!isObjectNull(groupPersistDTO.getDbDispatcherSubscribers())) {
                    dispMembers.addAll(groupPersistDTO.getDbDispatcherSubscribers());
                }

                if (groupPersistDTO.getRequestDispatcherSubscribers() != null && !groupPersistDTO.getRequestDispatcherSubscribers().isEmpty()) {
                    if (!groupPersistDTO.isMultipleDispatcherAllowed()) {
                        if (!groupInfoDTO.isGroupTypeChanged()) {
                            //When the group type is not changed and a new dispatcher is added we want to delete
                            //existing members from the old dispatcher
                            if (!isObjectNull(groupDistList.get(groupInfoDTO.getGroupId()))) {
                                delMemList.addAll(groupDistList.get(groupInfoDTO.getGroupId()));
                            }
                            if (!isObjectNull(groupPersistDTO.getDbDispatcherSubscribers())) {
                                delMemList.removeAll(groupPersistDTO.getDbDispatcherSubscribers());
                            }
                            if (!isObjectNull(currentExtMemList)) {
                                deletedExtMembers.addAll(currentExtMemList);
                            }
                        } else {
                            //when the group type changes and reqeust consist ew disptacher with deleted members
                            //we need to remove association with new dispatcher as wellwith deleted members.
                            dispMembers.addAll(groupPersistDTO.getRequestDispatcherSubscribers());
                        }
                    }

                }
                LinkedList<String> delMemberList = new LinkedList<String>(delMemList);
                LinkedList<String> deletedExtMembersList = new LinkedList<String>(deletedExtMembers);
                //deAssignContact(delMemberList, dispMembers, groupPersistDTO.getGroupPrivateList(), deletedExtMembersList, etagMap, corpProfile.getXdmsHome(), persisterTxn);
                deAssignContact(delMemberList, dispMembers, groupPersistDTO.getGroupPrivateList(), deletedExtMembersList,
                        etagMap, corpProfile.getXdmsHome(), corpProfile.getCorpId(), persisterTxn);

            }
            if (AREA_BASED_DYNAMIC_GROUP == groupInfoDTO.getClientType() && !deletedIntMembers.isEmpty()) {
                Map<String, List<String>> profileBaseMdnMap = corpSubsProvInfoUtil.getMapOfProfileMdnByBaseMdn(new ArrayList<>(deletedIntMembers), corpProfile.getXdmsHome(), persisterTxn);
                if (!profileBaseMdnMap.isEmpty()) {
                    ArrayList<String> profileMdns = new ArrayList<>();
                    profileBaseMdnMap.values().forEach(profileMdns::addAll);
                    knLogger.debug(methodName, " fetched all the profile mdns ", KnGDPRTemplate.mdnList(profileMdns));
                    deletedIntMembers.addAll(profileMdns);
                }
            }
            Map<Integer, Collection<String>> deleteMemberMap = new HashMap<Integer, Collection<String>>();
            deleteMemberMap.put(groupInfoDTO.getGroupId(), deletedIntMembers);
            // Added external/shared members to the deletedIntMembers as the xcapRootUri and directoryUri is coming null for them
            deletedIntMembers.addAll(deletedExtMembers);
            contactInfoUtil.updateDistinctSubcribersDirectory(deletedIntMembers, null, etagMap, corpProfile.getXdmsHome(), persisterTxn);
            /*
              Get the group member count and group type for the groupIds and set these values into etag Map
            */
            Map<Integer, KnCorpGroupDTO> groupDetailsMap = groupInfoUtil.getGroupBasicDetailsMap(groupEtagMap.keySet(), corpProfile.getXdmsHome(), persisterTxn);

            commonInfoUtil.formSubscriberNotification(deleteMemberMap, groupEtagMap,
                    com.kodiak.xdms.server.common.resources.KnConstants.DOC_CHANGE_TYPE.REMOVE.value(), etagMap, groupDetailsMap, null);
        }
        return respDto;
    }

    private void assignContactsForDispatcher(KnIPCorpGroupInfoDTO groupInfoDTO,
                                             KnCorpGroupInfoPersistDTO groupPersistDTO,
                                             KnCorpProfileDTO corpProfile,
                                             Map<Integer, Collection<String>> currentGroupMember,
                                             KnMdnDetailsPersistDTO pocMdnPersistDto, Map<Integer, Collection<String>> groupDistList,
                                             Collection<KnCorpSubscriberDTO> memberList,
                                             Collection<KnCorpSubscriberDTO> uniqueMdnToBeDeletedToGroup,
                                             Collection<KnCorpSubscriberDTO> externalMembersDTOList,
                                             Map<Integer, Map<String, Collection<String>>> memberDetailsList,
                                             Collection<String> finalGroupMembersinDB,
                                             Map<String, KnOPDirChgDTO> etagMap,
                                             KnPersisterTxn persisterTxn) throws Exception {
        String methodName = "assignContactsForDispatcher()";
        knLogger.debug(methodName, "groupInfoDTO - ", groupInfoDTO);
        knLogger.debug(methodName, "groupPersistDTO - ", groupPersistDTO);
        knLogger.debug(methodName, "corpProfile - ", corpProfile);
        knLogger.debug(methodName, "currentGroupMember - ", currentGroupMember);
        knLogger.debug(methodName, "pocMdnPersistDto - ", pocMdnPersistDto);
        knLogger.debug(methodName, "groupDistList - ", groupDistList);
        knLogger.debug(methodName, "memberList - ", memberList);
        knLogger.debug(methodName, "uniqueMdnToBeDeletedToGroup - ", uniqueMdnToBeDeletedToGroup);
        knLogger.debug(methodName, "externalMembersDTOList - ", externalMembersDTOList);
        knLogger.debug(methodName, "memberDetailsList - ", memberDetailsList);
        knLogger.debug(methodName, "etagMap - ", KnGDPRTemplate.mapKeyMdn(etagMap));
        Collection<String> reqDispatcherSubscribers = groupPersistDTO.getRequestDispatcherSubscribers();
        knLogger.debug(methodName, "reqDispatcherSubscribers - ", KnGDPRTemplate.mdnList(reqDispatcherSubscribers));
        Collection<String> completeDispatcherList = new ArrayList<String>();
        completeDispatcherList.addAll(reqDispatcherSubscribers);
        knLogger.debug(methodName, "reqDispatcherSubscribers - ", KnGDPRTemplate.mdnList(reqDispatcherSubscribers));
        Collection<String> currentExtMemList = new ArrayList<String>();
        knLogger.debug(methodName, "finalGroupMembersinDB - ", KnGDPRTemplate.mdnList(finalGroupMembersinDB));
        //code to assign the contacts when its a dispatch group with the contact pairing as true
        Set<KnCorpSubscriberDTO> extMemList = new HashSet<KnCorpSubscriberDTO>();
        if (DISPATCH_GROUP == groupInfoDTO.getGroupType() &&
                groupInfoDTO.isContactPairing() == KnConstants.TRUE && !groupInfoDTO.isGroupTypeChanged()) {
            knLogger.debug(methodName, "group changes Loop1- ");
            Set<String> internalMembers = new HashSet<String>();
            Collection<String> validPocSubscList = pocMdnPersistDto.getMdnList();
            Collection<KnCorpSubscriberDTO> externalMemList = pocMdnPersistDto.getExternalMdnList();
            knLogger.debug(methodName, "validPocSubscList- ", KnGDPRTemplate.mdnList(validPocSubscList));
            if (validPocSubscList != null) {
                for (String mdn : validPocSubscList) {
                    KnCorpSubscriberDTO subsc = new KnCorpSubscriberDTO();
                    subsc.setMdn(mdn);
                    if (!reqDispatcherSubscribers.contains(mdn) &&
                            (groupPersistDTO.getReqInterOpSubs() != null && !groupPersistDTO.getReqInterOpSubs().contains(mdn)) &&
                            (externalMemList == null || !externalMemList.contains(subsc))) {
                        internalMembers.add(mdn);
                    }
                }
            }
            Collection<String> memberDetails = memberDetailsList.get(groupInfoDTO.getGroupId()).get(ADDED_MEMBERS);
            if (memberDetails != null && !memberDetails.isEmpty()) {
                for (String member : memberDetails) {
                    if ((reqDispatcherSubscribers != null && !reqDispatcherSubscribers.contains(member)) &&
                            (groupPersistDTO.getReqInterOpSubs() != null && !groupPersistDTO.getReqInterOpSubs().contains(member))) {
                        internalMembers.add(member);
                    }
                }
            }
            knLogger.debug(methodName, "internalMembers- ", KnGDPRTemplate.mdnSet(internalMembers));
            knLogger.debug(methodName, "externalMemList- ",externalMemList);
            if (externalMembersDTOList != null) {
                extMemList.addAll(externalMembersDTOList);
            }
            Collection<String> dispatcherMemberList = new ArrayList<String>();
            if (reqDispatcherSubscribers != null && !reqDispatcherSubscribers.isEmpty()) {
                knLogger.debug(methodName, "reqDispatcherSubscribers- ", KnGDPRTemplate.mdnList(reqDispatcherSubscribers));
                dispatcherMemberList.addAll(reqDispatcherSubscribers);
                if (groupPersistDTO.isMultipleDispatcherAllowed()) {
                    if (groupPersistDTO.getDbDispatcherSubscribers() != null) {
                        dispatcherMemberList.addAll(groupPersistDTO.getDbDispatcherSubscribers());
                    }
                }
                knLogger.debug(methodName, "dispatcherMemberList- ", KnGDPRTemplate.mdnList(dispatcherMemberList));
                Collection<String> validCurrSubscList = groupDistList.get(groupInfoDTO.getGroupId());
                knLogger.debug(methodName, "validCurrSubscList- ", KnGDPRTemplate.mdnList(validCurrSubscList));
                Set<String> groupInternalMemberList = new HashSet<String>();
                Collection<KnCorpSubscriberDTO> exteMemList = new ArrayList<KnCorpSubscriberDTO>();
                groupInternalMemberList.addAll(groupDistList.get(groupInfoDTO.getGroupId()));
                if (currentGroupMember.get(groupInfoDTO.getGroupId()) != null) {
                    knLogger.info(methodName, "currentGroupMember.get(groupInfoDTO.getGroupId())- ", currentGroupMember.get(groupInfoDTO.getGroupId()));
                    for (String mdn : currentGroupMember.get(groupInfoDTO.getGroupId())) {
                        if (!groupInternalMemberList.contains(mdn)) {
                            exteMemList.add(new KnCorpSubscriberDTO(mdn, ""));
                            currentExtMemList.add(mdn);
                        }
                    }
                }
                knLogger.debug(methodName, "Looping1- ");
                Collection<KnCorpSubscriberDTO> extSubMemList =
                        contactInfoUtil.getExternalPoCSubscriberDetails(exteMemList,
                                corpProfile.getCorpId(), corpProfile.getXdmsHome(), persisterTxn);
                knLogger.debug(methodName, "extSubMemList- ", extSubMemList);
                if (extSubMemList != null) {
                    for (KnCorpSubscriberDTO subs : extSubMemList) {
                        if (finalGroupMembersinDB.contains(subs.getMdn())) {
                            extMemList.add(subs);
                        }
                    }
                }
                if (validCurrSubscList != null) {
                    for (String mdn : validCurrSubscList) {
                        KnCorpSubscriberDTO subsc = new KnCorpSubscriberDTO();
                        subsc.setMdn(mdn);
                        if ((!reqDispatcherSubscribers.contains(mdn)) &&
                                (groupPersistDTO.getReqInterOpSubs() != null && !groupPersistDTO.getReqInterOpSubs().contains(mdn)) &&
                                (extSubMemList == null || (!extSubMemList.contains(subsc))) &&
                                (finalGroupMembersinDB.contains(mdn))) {
                            internalMembers.add(mdn);
                        }
                    }
                }
                knLogger.debug(methodName, "internalMembers- ", KnGDPRTemplate.mdnSet(internalMembers));
            } else {
                knLogger.debug(methodName, "groupPersistDTO.getDbDispatcherSubscribers()- ", groupPersistDTO.getDbDispatcherSubscribers());
                if (groupPersistDTO.getDbDispatcherSubscribers() != null) {
                    dispatcherMemberList.addAll(groupPersistDTO.getDbDispatcherSubscribers());
                }
                knLogger.debug(methodName, "dispatcherMemberList- ", KnGDPRTemplate.mdnList(dispatcherMemberList));
            }
            if (groupPersistDTO.getDbDispatcherSubscribers() != null) {
                internalMembers.removeAll(groupPersistDTO.getDbDispatcherSubscribers());
            }
            if (groupPersistDTO.getReqInterOpSubs() != null) {
                internalMembers.removeAll(groupPersistDTO.getReqInterOpSubs());
            }
            if (groupPersistDTO.getDbInterOpSubs() != null) {
                internalMembers.removeAll(groupPersistDTO.getDbInterOpSubs());
            }
            knLogger.debug(methodName, "Before assignContact ");
            //remove group mdns from the list
            internalMembers.removeAll(pocMdnPersistDto.getGroupMdnList());
            Collection<String> removedMdnsList = groupInfoDTO.getRemovedMemberMdns();
            assignContact(internalMembers, dispatcherMemberList, extMemList, removedMdnsList, corpProfile.getCorpId(),
                    corpProfile.getMaxContactsPerSubsc(), etagMap, corpProfile.getXdmsHome(), persisterTxn);
            knLogger.debug(methodName, "After assignContact ");
        } else if ((groupInfoDTO.getGroupType() == DISPATCH_GROUP &&
                groupInfoDTO.isContactPairing() == KnConstants.TRUE) && groupInfoDTO.isGroupTypeChanged() /*||
                        (currentGroupType == KnConstants.DISPATCH_GROUP && groupInfoDTO.isContactPairing() == KnConstants.TRUE)*/) {
            Collection<String> mdnList = new ArrayList<String>();
            knLogger.debug(methodName, "memberList - ", memberList);
            for (KnCorpSubscriberDTO subsc : memberList) {
                mdnList.add(subsc.getMdn());
            }
            knLogger.debug(methodName, "mdnList - ", KnGDPRTemplate.mdnList(mdnList));
            if (groupPersistDTO.isMultipleDispatcherAllowed()) {
                knLogger.debug(methodName, "isMultipleDispatcherAllowed - ", true);
                Collection<String> memberMdnList = groupPersistDTO.getDbDispatcherSubscribers();
                if (memberMdnList != null && !memberMdnList.isEmpty()) {
                    completeDispatcherList.addAll(groupPersistDTO.getDbDispatcherSubscribers());
                }
            } else {
                knLogger.debug(methodName, "isMultipleDispatcherAllowed - ", false);
                if (completeDispatcherList == null || completeDispatcherList.isEmpty()) {
                    Collection<String> memberMdnList = groupPersistDTO.getDbDispatcherSubscribers();
                    if (memberMdnList != null && !memberMdnList.isEmpty()) {
                        completeDispatcherList.addAll(groupPersistDTO.getDbDispatcherSubscribers());
                    }
                }
            }
            knLogger.debug(methodName, "completeDispatcherList - ", KnGDPRTemplate.mdnList(completeDispatcherList));
            Set<String> groupInternalMemberList = new HashSet<String>();
            groupInternalMemberList.addAll(groupDistList.get(groupInfoDTO.getGroupId()));
            Collection<KnCorpSubscriberDTO> exteMemList = new ArrayList<KnCorpSubscriberDTO>();
            knLogger.debug(methodName, "groupInternalMemberList - ", groupInternalMemberList);
            for (String mdn : currentGroupMember.get(groupInfoDTO.getGroupId())) {
                if (!groupInternalMemberList.contains(mdn)) {
                    exteMemList.add(new KnCorpSubscriberDTO(mdn, ""));
                    currentExtMemList.add(mdn);
                }
            }
            knLogger.debug(methodName, "currentExtMemList - ", KnGDPRTemplate.mdnList(currentExtMemList));
            knLogger.debug(methodName, "exteMemList - ", exteMemList);
            externalMembersDTOList.addAll(contactInfoUtil.getExternalPoCSubscriberDetails(exteMemList, corpProfile.getCorpId(), corpProfile.getXdmsHome(), persisterTxn));
            if (reqDispatcherSubscribers != null && !reqDispatcherSubscribers.isEmpty() && !groupPersistDTO.isMultipleDispatcherAllowed()) {
                Collection<String> currentDispatchMembers = groupPersistDTO.getDbDispatcherSubscribers();
                if (currentDispatchMembers != null && !currentDispatchMembers.isEmpty()) {
                    groupInternalMemberList.removeAll(currentDispatchMembers);
                }
            }
            knLogger.debug(methodName, "groupInternalMemberList - ", KnGDPRTemplate.mdnList(groupInternalMemberList));
            //remove the removed members in request
            if (uniqueMdnToBeDeletedToGroup != null && !uniqueMdnToBeDeletedToGroup.isEmpty()) {
                groupInternalMemberList.removeAll(groupInfoDTO.getRemovedMemberMdns());
            }
            knLogger.debug(methodName, "groupInternalMemberList - ", KnGDPRTemplate.mdnSet(groupInternalMemberList));

            //newly added members
            if ((memberDetailsList.get(groupInfoDTO.getGroupId())).get(ADDED_MEMBERS) != null && !(memberDetailsList.get(groupInfoDTO.getGroupId())).get(ADDED_MEMBERS).isEmpty()) {
                groupInternalMemberList.addAll((memberDetailsList.get(groupInfoDTO.getGroupId())).get(ADDED_MEMBERS));
            }
            knLogger.debug(methodName, "completeDispatcherList - ", KnGDPRTemplate.mdnList(completeDispatcherList));
            //removing all the dispatchers from th list
            groupInternalMemberList.removeAll(completeDispatcherList);
            knLogger.debug(methodName, "groupInternalMemberList for assignment- ", KnGDPRTemplate.mdnSet(groupInternalMemberList));

            if (groupPersistDTO.getReqInterOpSubs() != null) {
                groupInternalMemberList.removeAll(groupPersistDTO.getReqInterOpSubs());
            }
            if (groupPersistDTO.getDbInterOpSubs() != null) {
                groupInternalMemberList.removeAll(groupPersistDTO.getDbInterOpSubs());
            }
            //remove the group mdns from the lsit
            groupInternalMemberList.removeAll(pocMdnPersistDto.getGroupMdnList());
            Collection<String> removedMdnsList = groupInfoDTO.getRemovedMemberMdns();
            assignContact(groupInternalMemberList, completeDispatcherList, extMemList,
                    removedMdnsList, corpProfile.getCorpId(), corpProfile.getMaxContactsPerSubsc(), etagMap, corpProfile.getXdmsHome(), persisterTxn);
        }
    }

    private Set<String> getDisptachGrpMemmberToBeSetInResponse(KnIPCorpGroupInfoDTO groupInfoDTO, Map<Integer, Map<String, Collection<String>>> memberDetailsList) {
        Set<String> completeList = new HashSet<String>();
        if (DISPATCH_GROUP == groupInfoDTO.getGroupType()) {
            //update the subscribers DISPATCH_GROUP_MEMBER Attribute to 1
            Map<String, Collection<String>> membersMap = memberDetailsList.get(groupInfoDTO.getGroupId());
            if (membersMap != null && !membersMap.isEmpty()) {
                Collection<String> newGrpmembers = membersMap.get(ADDED_MEMBERS);
                if (newGrpmembers != null && !newGrpmembers.isEmpty()) {
                    for (String mdn : newGrpmembers) {
                        completeList.add(mdn);
                    }
                }
            }
        }
        return completeList;
    }

    /**
     * @param populatePersistDTO
     * @param groupInfoDTO
     * @param groupTypeChanged
     * @return
     */
    private KnCorpGroupInfoPersistDTO populateDispatchersForDelete(KnCorpGroupInfoPersistDTO populatePersistDTO, KnIPCorpGroupInfoDTO groupInfoDTO, boolean groupTypeChanged) {
        knLogger.debug("populateDispatchersForDelete", "populatePersistDTO -.", populatePersistDTO, " , groupInfoDTO - ",
                groupInfoDTO + " , groupTypeChanged - " + groupTypeChanged);
        KnCorpGroupInfoPersistDTO deletePersistDTO = new KnCorpGroupInfoPersistDTO();
        if (DISPATCH_GROUP == groupInfoDTO.getGroupType() &&
                !populatePersistDTO.isMultipleDispatcherAllowed()) {
            knLogger.debug("populateDispatchersForDelete", "Putting the current dispatchers in the deleted member list since",
                    " multiple dispacthers are not allowed.");
            if (!isObjectNullOrEmpty(populatePersistDTO.getRequestDispatcherSubscribers()) &&
                    !isObjectNullOrEmpty(populatePersistDTO.getRequestDispatcherSubscribers())) {
                Collection<String> dispatchMemberList = populatePersistDTO.getDbDispatcherSubscribers();
                //if (dispatchMemberList != null) {
                LinkedList<String> mdnList = groupInfoDTO.getRemovedMemberMdns();
                if (mdnList == null) {
                    mdnList = new LinkedList<String>();
                }
                if (dispatchMemberList != null) {
                    for (String mdn : dispatchMemberList) {
                        //If dispatcher is already existing in the group we need not remove him from the tale
                        if (!groupInfoDTO.getAddedMdnsList().contains(mdn)) {
                            mdnList.add(mdn);
                        }
                    }
                }
                deletePersistDTO.setRemovedMemberList(mdnList);
                //}
            }

        }
        //If groupType changes from Dispatch to Standard then we need to removed all the dispatchers implicitly
        if (groupTypeChanged && STANDARD_GROUP == groupInfoDTO.getGroupType()) {
            knLogger.debug("populateDispatchersForDelete", "If there is group type change from dipatch to standard delete all the current dispatchers");
            LinkedList<String> mdnList = deletePersistDTO.getRemovedMemberList();
            if (mdnList == null) {
                mdnList = new LinkedList<String>();
            }
            if (populatePersistDTO.getDbDispatcherSubscribers() != null && !populatePersistDTO.getDbDispatcherSubscribers().isEmpty()) {
                Collection<String> dispatchMemberList = populatePersistDTO.getDbDispatcherSubscribers();
                //if (dispatchMemberList != null) {
                for (String mdn : dispatchMemberList) {
                    mdnList.add(mdn);
                }
                //}
            }
            deletePersistDTO.setRemovedMemberList(mdnList);
        }
        knLogger.debug("populateDispatchersForDelete", "return value - .", deletePersistDTO);
        return deletePersistDTO;
    }

    private KnCorpGroupInfoPersistDTO populateSpecificSubscribersFromList(Collection<KnCorpSubscriberDTO> addedMdnDTO, int groupType) {
        KnCorpGroupInfoPersistDTO dispatcherPersistDTO = new KnCorpGroupInfoPersistDTO();
        Collection<String> reqDispatcherSubscribers = new ArrayList<String>();
        Collection<KnCorpGroupMemberDTO> completeSupervisorList = new ArrayList<KnCorpGroupMemberDTO>();
        Set<String> interOPSubsc = new HashSet<String>();
        if (!isObjectNull(addedMdnDTO)) {
            for (KnCorpSubscriberDTO subsc : addedMdnDTO) {
                if (DISPATCH_CLIENT.value() == subsc.getClientType()
                        || THIRDPARTYDISPATCHERCLIENT.value() == subsc.getClientType()) {
                    //remove the dispatcher and again as it may come with 0 or 1 in request  set the value as DISPATCHER
                    completeSupervisorList.remove(subsc);
                    KnCorpGroupMemberDTO member = new KnCorpGroupMemberDTO();
                    member.setMdn(subsc.getMdn());
                    member.setSupervisory(GROUP_DISPATCHER);
                    member.setContact_type(subsc.getContact_type());
                    member.setClientType(subsc.getClientType());
                    member.setAliasMdn(subsc.getAliasMdn());
                    member.setSubsActiveFS2(subsc.getSubsActiveFS2());
                    member.setUserId(subsc.getUserId());
                    completeSupervisorList.add(member);
                    reqDispatcherSubscribers.add(subsc.getMdn());
                } else if (INTER_OP_CLIENT_TYPE == subsc.getClientType()) {
                    KnCorpGroupMemberDTO member = new KnCorpGroupMemberDTO();
                    member.setMdn(subsc.getMdn());
                    member.setSupervisory(INTER_OP);
                    member.setContact_type(subsc.getContact_type());
                    member.setClientType(subsc.getClientType());
                    member.setAliasMdn(subsc.getAliasMdn());
                    member.setSubsActiveFS2(subsc.getSubsActiveFS2());
                    member.setUserId(subsc.getUserId());
                    completeSupervisorList.add(member);
                    interOPSubsc.add(subsc.getMdn());
                }
            }
        }
        dispatcherPersistDTO.setRequestDispatcherSubscribers(reqDispatcherSubscribers);
        dispatcherPersistDTO.setCompleteSupervisorList(completeSupervisorList);
        dispatcherPersistDTO.setReqInterOpSubs(interOPSubsc);
        return dispatcherPersistDTO;
    }

    public KnCorpResponseDTO deleteGroup(KnIPCorpGroupDTO groupInfoDTO, KnPersisterTxn persisterTxn) {

        String methodName = "deleteGroup(KnIPCorpGroupDTO, KnPersisterTxn)";
        knLogger.info(methodName, "ENTRY : Input DTO Passed - ", groupInfoDTO.getGroupId(), groupInfoDTO.getCorpId());
        KnCorpResponseDTO respDto = new KnCorpResponseDTO();
        KnCorpInOutParamDTO corpInOutParamDTO = new KnCorpInOutParamDTO();
//        Map<String, KnOPDirChgDTO> etagMap = new HashMap<String, KnOPDirChgDTO>();
        try {
            int corpId = groupInfoDTO.getCorpId();
            String xdmsHome = null;
            KnCorpProfileDTO corpProfile = null;
            //Step:
            //get the Corp profile details from cache
            if (CLIENT_TYPE_SOAP == groupInfoDTO.getClientType()) {
                knLogger.debug(methodName, "Fetch the corpProfile profile if cached or fetch from the DB the details");
                corpProfile = commonInfoUtil.getProfileDetails(String.valueOf(corpId), CORP_PROFILE, false, persisterTxn);
                knLogger.debug(methodName, "Retrieved Corp Profile details - ", corpProfile);
            } else {
                KnSubsProfileDTO subscProfile = commonInfoUtil.getProfileDetails(groupInfoDTO.getTpGroupOwner(), PUBLIC_PROFILE, false, persisterTxn);
                corpId = subscProfile.getCorpId();
                corpProfile = commonInfoUtil.getProfileDetails(String.valueOf(corpId), CORP_PROFILE, false, persisterTxn);
                KnCorpGroupDTO corpGroupDTO = groupInfoUtil.getGroupIdByName(groupInfoDTO.getGroupDisplayName(), groupInfoDTO.getClientType(),
                        groupInfoDTO.getTpGroupOwner(), corpProfile.getXdmsHome(), persisterTxn);
                groupInfoDTO.setCorpId(corpId);
                groupInfoDTO.setGroupId(corpGroupDTO.getGroupId());
            }
            xdmsHome = corpProfile.getXdmsHome();
            String corpPocHome=corpProfile.getPocHome();
            //retrieve group info
            boolean hiearchyCall = groupInfoDTO.getHierarchyType() == HIERARCHY_TYPE.HIERARCHY;
            KnCorpGroupInfoPersistDTO groupPersistDTO = groupInfoUtil.getGroupDetails(groupInfoDTO, xdmsHome, persisterTxn,hiearchyCall);
            knLogger.debug(methodName, "Retrieved Corp Group Info - ", groupPersistDTO);
            Integer mcxIndicator = groupPersistDTO.getMcxGrpInd();
            groupInfoDTO.setMcxGrpInd(mcxIndicator);
            groupInfoDTO.setIsPreConfiguredGroup(groupPersistDTO.getIsPreConfiguredGroup());
            groupInfoDTO.setGrpShared(groupPersistDTO.getGrpShared());

            int groupID = groupInfoDTO.getGroupId();
            List<String> groupIDList = new ArrayList<>();
            groupIDList.add(String.valueOf(groupID));
            commonInfoUtil.validateCorpAndGroupParams(groupIDList, String.valueOf(corpId), xdmsHome, persisterTxn);

            //Invoking custom hook
            KnCorpHookRespDTO responseDTO = new KnCorpHookRespDTO();
            Map<String, Object> customParams = groupInfoDTO.getCustomParamMap();
            if (groupInfoDTO.getHierarchyType() == HIERARCHY_TYPE.HIERARCHY) {
                customParams.put(CURRENT_MASTER_LIST_ETAG, corpProfile.getCorpMasterListEtag());
                customParams.put(PERSISTER_TXN, persisterTxn);
                customParams.put(PTT_SERVER_ID, xdmsHome);
                groupInfoDTO.setCustomParamMap(customParams);
                KnCorpHookIPDTO hookIPDTO = new KnCorpHookIPDTO();
                hookIPDTO.setAction(KnActions.ACTIONS.DELETE_GROUP);
                hookIPDTO.setData(groupInfoDTO);
                KnProcessInvokerImpl processInvoker = KnProcessInvokerImpl.getInstance();
                Object hookResp = processInvoker.invokeHook(CUSTOM_CORP_USER_HOOK, hookIPDTO);
                if (hookResp instanceof KnCorpHookRespDTO) {
                    responseDTO = (KnCorpHookRespDTO) hookResp;
                    if (com.kodiak.xdms.server.common.resources.KnConstants.RESPONSE_STATUS.FAILURE.value() == responseDTO.getStatus()) {
                        knLogger.error(methodName, "Returning Failure response");
                        populateXdmResponseFroomHook(responseDTO, respDto);
                        return respDto;
                    }
                }
                Collection<String> idListStr = (Collection<String>) customParams.get(com.kodiak.common.resources.KnConstants.IDLIST);
                Object idTypeObj = customParams.get(IDTYPE);
                int idTypeValues;
                if (idTypeObj instanceof Integer) {
                    idTypeValues = (Integer) idTypeObj;
                } else if (idTypeObj instanceof String) {
                    idTypeValues = Integer.parseInt((String) idTypeObj);
                } else {
                    throw new IllegalArgumentException("Unsupported type for IDTYPE: " + idTypeObj.getClass().getName());
                }
                if (idListStr != null) {
                    List<Integer> idListInt = (List<Integer>) convertStrToIntColl(idListStr);
                    List<String> groupIdList = List.of(String.valueOf(groupInfoDTO.getGroupId()));
                    commonInfoUtil.validateGroupParams(groupIdList, String.valueOf(corpId), idListInt, xdmsHome, idTypeValues, persisterTxn);
                }
            }
            //Step:
            //retrieve group info
            //   KnCorpGroupInfoPersistDTO groupPersistDTO = groupInfoUtil.getGroupDetails(groupInfoDTO, xdmsHome, persisterTxn);
            //knLogger.debug(methodName, "Retrieved Corp Group Info - ", groupPersistDTO);

            groupPersistDTO.setInputDTO(groupInfoDTO);
            Collection<String> groupIdAsDestination = new ArrayList<>();
            groupIdAsDestination.add(String.valueOf(groupInfoDTO.getGroupId()));
            Map<String, Collection<String>> groupFailurePairingMap = corpSubsProvInfoUtil.getEmergDestUserMap(groupIdAsDestination,
                    xdmsHome, persisterTxn);
            if (!groupFailurePairingMap.isEmpty()) {
                knLogger.error(methodName, "Emergency Destination Mapping Exists - Group");
                throw new KnCorpBOValidationException(KnErrorCodes.Validator.EMERGENCY_DESTINATION_MAPPING_EXISTS_FOR_GROUP,
                        "Emergency Destination Mapping Exists for Group--", CORP_GROUP_MANAGER,
                        DELETE_GROUP, "", groupFailurePairingMap.keySet().toString(), "");
            }
            knLogger.info(methodName, "Invoking ValidationFW. DTO - ", groupPersistDTO);
            //Step:
            //validate
            validatorFW.validate(groupPersistDTO);
            knLogger.debug(methodName, "Validation completed Successfully.", groupPersistDTO);

            groupInfoDTO.setGroupType(groupPersistDTO.getGroupType());
            Map<Integer, Integer> groupListMap = new HashMap<>();
            //in hierarcy flow find all user profileids from PROFILE_GROUP_INFO table by using groupid
            //delete group from all user profiles
            //form profie notification and send to all members who are part of that group

            Set<String> userProfileIds = new HashSet<>();
            if(groupPersistDTO.getMcxGrpInd() == MCX_GROUP_INDICATOR && groupInfoDTO.getHierarchyType() == HIERARCHY_TYPE.HIERARCHY) {
                int groupId = groupInfoDTO.getGroupId();
                knLogger.info(methodName, "enter into hierarchy path -", groupId);

                Map<String, KnCorpGroupListInfoDTO> mcxGroupList = corpUserProfileUtil.retriveGroupProfileInfoByGroupId(groupId, xdmsHome, persisterTxn);
                if (mcxGroupList != null && !mcxGroupList.isEmpty()) {
                    userProfileIds.addAll(mcxGroupList.keySet());
                }
                knLogger.debug(methodName, "userProfileIds - ", userProfileIds);

            }

            groupListMap.put(groupInfoDTO.getGroupId(), CB_MAPPING.NEED_TO_REMOVE.value());
            Map<String, Collection<KnDocChangeListDTO>> profileMdnEtagMap = corpUserProfileUtil.updateImpactedCBDocuments(String.valueOf(corpId), null,
                    groupListMap,null,new ArrayList(userProfileIds), xdmsHome, persisterTxn);

            //clenaup GROUP_HIERARCHY_MAP
            if(groupPersistDTO.getMcxGrpInd() == MCX_GROUP_INDICATOR && groupInfoDTO.getHierarchyType() == HIERARCHY_TYPE.HIERARCHY) {
                int groupId = groupInfoDTO.getGroupId();
                knLogger.info(methodName, "enter into hierarchy path -", groupId);
                groupInfoUtil.removeGroupHiearchyMapByGroupId(groupId, xdmsHome, persisterTxn);
            }
            //Constructing target by concatinating <corpId>_<groupId>,
            //This target is checked in DB, if present, we are deleting the record
            IXDMServerDAO commonXDMServerDAO = KnFactorySelector.getDAOFactory(KnFactorySelector.DB).createXDMServerDAO(xdmsHome);
            String target = String.valueOf(corpId).concat("_").concat(String.valueOf(groupInfoDTO.getGroupId()));
            knLogger.debug(methodName, "target to be deleted is : ", target);
            Collection<KnRecordingTargetInfoDTO> recordingTargetList = commonXDMServerDAO
                    .getRecordingInfoTargetByTarget(new ArrayList<>(Arrays.asList(target)), persisterTxn);
            if (null != recordingTargetList && !recordingTargetList.isEmpty()) {
                for (KnRecordingTargetInfoDTO recordingTarget : recordingTargetList) {
                    commonXDMServerDAO.deleteRecordingInfoTargetByTarget(new ArrayList<>(Arrays.asList(recordingTarget.getTarget()))
                            , persisterTxn);
                }
            }
            KnIPCorpGroupInfoDTO ipCorpGroupInfoDTO = new KnIPCorpGroupInfoDTO();
            Boolean isUgwInteropEnabledInDB = Boolean.FALSE;
            ipCorpGroupInfoDTO.setGroupId(groupInfoDTO.getGroupId());
            ipCorpGroupInfoDTO.setCorpId(groupInfoDTO.getCorpId());
            KnCorpGrpBasicInfoRespDto grpBasicInfoDto = corpClientIntf.getBasicGrpInfo(ipCorpGroupInfoDTO, persisterTxn);
            if (null != grpBasicInfoDto.getUgwInterop()) {
                isUgwInteropEnabledInDB = grpBasicInfoDto.getUgwInterop().equals(7);
            }

            respDto = deleteGroupOperation(groupInfoDTO, corpInOutParamDTO, corpProfile.getLinkedGwKey(), xdmsHome, corpId, persisterTxn);
            Collection<KnSIPProxySvcConfigDTO> sipProxySvcConfigInfoDTO = commonInfoUtil.getSipProxySvcConfig(xdmsHome, persisterTxn);
            String groupPocHome = groupInfoUtil.fetchGroupPocHome(groupInfoDTO.getGroupId(), xdmsHome, persisterTxn);
            String effectivePocHome = genInfoUtil.getEffectivePocHome(corpPocHome, groupPocHome);
            String groupSipUri = commonInfoUtil.mcpttGroupUri(groupInfoDTO.getGroupId(), corpId, sipProxySvcConfigInfoDTO.stream()
                    .filter(sipProxy -> sipProxy.getPttServerId().equals(effectivePocHome)).findFirst()
                    .map(KnSIPProxySvcConfigDTO::getSipProxyURI).orElse(null));
            respDto.setProfileMdnEtagMap(profileMdnEtagMap);
            if(profileMdnEtagMap != null && profileMdnEtagMap.isEmpty()){
                respDto.setMcsXcapRootUriMap(genInfoUtil.getXCAPRootURI(new ArrayList<>(profileMdnEtagMap.keySet()), persisterTxn, true));
            }
            respDto.setTgsModeChgMap(corpInOutParamDTO.getTgsModeChgMap());
            LinkedList<KnLIEventDTO> liEventList = populateDeleteGroupLIData(respDto.getChangeLogMap()
                    , xdmsHome, groupPersistDTO,persisterTxn);
            respDto.setLiEventList(liEventList);
            respDto.setMdnCorpId(corpId);
            respDto.setDeletedGroupId(groupInfoDTO.getGroupId());
            respDto.setGroupCreatedBy(groupPersistDTO.getGroupCreatedBy());
            respDto.setGrpSIPUri(groupSipUri);
            if(isUgwInteropEnabledInDB) {
                respDto.setLmrIntropCapable(ENABLED);
            }
            respDto.setGrpUri("kn-corp-groups=" + corpId + "_" + groupInfoDTO.getGroupId());
            //Added by DTXJ47 MCSJAVALIB-1507
            respDto.setPocHome(groupPersistDTO.getPocHome());
            if (null != groupPersistDTO.getClusterId()) {
                respDto.setClusterId(String.valueOf(groupPersistDTO.getClusterId()));
            }

            populate(respDto);
            if (responseDTO.getFailedDataList() != null && !responseDTO.getFailedDataList().isEmpty()) {
                respDto.setFailedDataList(responseDTO.getFailedDataList());
            }
        } catch (KnValidationException ve) {
            knLogger.error(methodName, "KnValidationException occured while modifying Group - ", ve);
            populate(respDto, ve);

        } catch (KnCorpBOException e) {
            knLogger.error(methodName, "KnCorpBOException occured while deleting Group - ", e);
            populate(respDto, e);

        } catch (Exception e) {
            knLogger.error(methodName, "Unexpected Exception occured while deleting Group - ",
                    new KnException(KnErrorCodes.BOEntity.INTERNAL_ERROR, e.getMessage(), e));
            populate(respDto, e);

        }
        knLogger.info(methodName, "EXIT : delete Group Response - ", respDto);
        return respDto;
    }

    @SuppressWarnings("unchecked")
    public KnCorpGroupInfoRespDTO getGroupDetails(KnIPCorpGroupDTO groupInfoDTO, KnPersisterTxn persisterTxn) {

        String methodName = "getGroupDetails(KnIPCorpGroupDTO, KnPersisterTxn)";
        knLogger.info(methodName, "ENTRY : Input DTO Passed - ", groupInfoDTO.getCorpId(), groupInfoDTO.getGroupId());
        KnCorpGroupInfoRespDTO respDTO = new KnCorpGroupInfoRespDTO();
        try {
            int corpId = groupInfoDTO.getCorpId();
            //Step:
            //get the Corp profile details from cache
            knLogger.debug(methodName, "Fetch the corpProfile profile if cached or fetch from the DB the details");
            KnCorpProfileDTO corpProfile = commonInfoUtil.getProfileDetails(String.valueOf(corpId),
                    CORP_PROFILE, false, persisterTxn);
            knLogger.debug(methodName, "Retrieved Corp Profile details - ", corpProfile);
            String xdmsHome = corpProfile.getXdmsHome();
            String corpPocHome = corpProfile.getPocHome();
            //retrieve group info
            KnCorpGroupInfoPersistDTO groupPersistDTO = groupInfoUtil.getGroupDetailsByGroupId(groupInfoDTO,
                    xdmsHome, true, persisterTxn);
            knLogger.debug(methodName, "Retrieved Corp Group Info - ", groupPersistDTO);
            Integer isMcxGrp = groupPersistDTO.getMcxGrpInd();
            groupInfoDTO.setMcxGrpInd(isMcxGrp);
            int groupID = groupInfoDTO.getGroupId();
            List<String> groupIDList = new ArrayList<>();
            groupIDList.add(String.valueOf(groupID));
            commonInfoUtil.validateCorpAndGroupParams(groupIDList, String.valueOf(corpId), xdmsHome, persisterTxn);

            //Invoking custom hook
            KnCorpHookRespDTO responseDTO = new KnCorpHookRespDTO();
            Map<String, Object> customParams = groupInfoDTO.getCustomParamMap();
            boolean hiearchyCall = groupInfoDTO.getHierarchyType() == HIERARCHY_TYPE.HIERARCHY;
            if (hiearchyCall) {
                customParams.put(CURRENT_MASTER_LIST_ETAG, corpProfile.getCorpMasterListEtag());
                customParams.put(PERSISTER_TXN, persisterTxn);
                customParams.put(PTT_SERVER_ID, xdmsHome);
                groupInfoDTO.setCustomParamMap(customParams);
                KnCorpHookIPDTO hookIPDTO = new KnCorpHookIPDTO();
                hookIPDTO.setAction(KnActions.ACTIONS.GET_GROUP_DETAILS);
                hookIPDTO.setData(groupInfoDTO);
                KnProcessInvokerImpl processInvoker = KnProcessInvokerImpl.getInstance();
                Object hookResp = processInvoker.invokeHook(CUSTOM_CORP_USER_HOOK, hookIPDTO);
                if (hookResp instanceof KnCorpHookRespDTO) {
                    responseDTO = (KnCorpHookRespDTO) hookResp;
                    if (com.kodiak.xdms.server.common.resources.KnConstants.RESPONSE_STATUS.FAILURE.value() == responseDTO.getStatus()) {
                        knLogger.error(methodName, "Returning Failure response");
                        populateXdmResponseFroomHook(responseDTO, respDTO);
                        return respDTO;
                    }
                }
                Map<String, Object> customMap = groupInfoDTO.getCustomParamMap();
                Collection<String> idListStr = (Collection<String>) customMap.get(com.kodiak.common.resources.KnConstants.IDLIST);
                Object idTypeObj = customMap.get(IDTYPE);
                int idType;
                List<String> groupIdList = new ArrayList<>();
                groupIdList.add(String.valueOf(groupInfoDTO.getGroupId()));
                if (idTypeObj instanceof Integer) {
                    idType = (Integer) idTypeObj;
                } else if (idTypeObj instanceof String) {
                    idType = Integer.parseInt((String) idTypeObj);
                } else {
                    throw new IllegalArgumentException("Unsupported type for IDTYPE: " + idTypeObj.getClass().getName());
                }
                if (idListStr != null) {
                    List<Integer> idListInt = (List<Integer>) convertStrToIntColl(idListStr);
                    commonInfoUtil.validateGroupParams(groupIdList, String.valueOf(corpId), idListInt, xdmsHome, idType, persisterTxn);
                }
            }
            //retrieve group info
            groupPersistDTO.setInputDTO(groupInfoDTO);
            //Step:
            //check if current etag is matching with the etag passed by client - do via validation
            validatorFW.validate(groupPersistDTO);
            //Gettting osm list if assigned to the group.
            if (groupPersistDTO.getOSMListId() != null && !groupPersistDTO.getOSMListId().isEmpty()) {
                KnCorpOSMInfoListDetailsRespDTO osmListDetails = corpOSMInfoUtil.getOSMListDetailsByListId(String.valueOf(groupPersistDTO.getCorpId()), groupPersistDTO.getOSMListId(), xdmsHome, true, persisterTxn);
                knLogger.debug(methodName, "Retrieved osmListDetails - ", osmListDetails);
                respDTO.setOSMListDetails(osmListDetails.getOSMListDetails());
            }
            boolean isOwner = groupPersistDTO.getCorpId() == corpId;

            /* Get the corporate where the group is shared */
            List<Integer> sharedIntCorpList = new ArrayList<>();
            List<Integer> groupListFromReq = new ArrayList<>(1);
            groupListFromReq.add(groupInfoDTO.getGroupId());
            List<KnCorpSharedCorpInfo> sharedCorpList = groupInfoUtil.selectGroupSharedCorpInfoByGroupId(groupListFromReq, xdmsHome, true,
                    persisterTxn).get(groupInfoDTO.getGroupId());
            if (sharedCorpList != null) {
                for (KnCorpSharedCorpInfo item : sharedCorpList) {
                    sharedIntCorpList.add(item.getCorpId());
                }
            }

            knLogger.debug(methodName, "sharedIntCorpList - ", sharedIntCorpList);
            int groupId = groupInfoDTO.getGroupId();
            Map<String, Integer> grpPrivtMemMap = groupInfoUtil.getGroupPrivtMemLst(groupInfoDTO, xdmsHome, true, persisterTxn);
            List<String> internalMemLst = new ArrayList<String>();
            List<String> extMemLst = new ArrayList<String>();
            if (!grpPrivtMemMap.isEmpty()) {
                for (Entry<String, Integer> entry : grpPrivtMemMap.entrySet()) {
                    if (isOwner && !sharedIntCorpList.contains(entry.getValue()) && entry.getValue() != corpId) {
                        //external subscribers of owner limitation : external subcribers from the shared corp
                        extMemLst.add(entry.getKey());
                    } else if (isOwner) {//owner will get all the members
                        internalMemLst.add(entry.getKey());
                    } else if (entry.getValue() == corpId) {//shared group will get self members
                        internalMemLst.add(entry.getKey());
                    }
                }
                grpPrivtMemMap.clear();
            }
            knLogger.debug(methodName, "internalMemLst - ", KnGDPRTemplate.mdnList(internalMemLst));
            knLogger.debug(methodName, "extMemLst - ", KnGDPRTemplate.mdnList(extMemLst));
            boolean isOwnerCorpReq = true;
            if (hiearchyCall) {
                /**
                 * is requestByOwner (using idList, idType and hierarcyMap)
                 * if (owner)
                 *  - No filter logic apply return all the members of the group
                 *  if(not owner)
                 *  - Based on incontextList, filter out the group members
                 */
                List<Integer> idListValues = new ArrayList<>();
                List<String> idListValuesString = (List<String>) groupInfoDTO.getCustomParamMap().get(com.kodiak.common.resources.KnConstants.IDLIST);
                idListValuesString.forEach(idValue -> idListValues.add(Integer.parseInt(idValue)));
                int idType = Integer.parseInt((String) groupInfoDTO.getCustomParamMap().get(IDTYPE));
                ArrayList<Integer> groups = new ArrayList<>();
                groups.add(groupId);
                Map<Integer, Integer> groupHierarchyMap = groupInfoUtil.getGroupHierarchyMap(groups, corpProfile.getXdmsHome(), persisterTxn);
                if(!internalMemLst.isEmpty()) {
                    if (Integer.parseInt(HIER_CTX_ID_TYPE) == idType) {
                        // Hierarchy ID type (idType=3): owner = requesting hierarchyId matches group's CORPGROUPINFO.HIERARCHY_ID
                        // Shared = filter members to only those whose subscriber HIERARCHY_ID matches the requesting hierarchyId
                        String groupOwnerHierarchyId = groupPersistDTO.getHierarchyId();
                        String formattedOwnerHierarchyId = (groupOwnerHierarchyId != null && !groupOwnerHierarchyId.trim().isEmpty())
                                ? String.format("%08d", Integer.parseInt(groupOwnerHierarchyId.trim()))
                                : "";
                        isOwnerCorpReq = idListValuesString.stream()
                                .anyMatch(reqHier -> reqHier.trim().equals(formattedOwnerHierarchyId));
                        knLogger.debug(methodName, " [Hierarchy] isOwnerCorpReq=", isOwnerCorpReq,
                                " groupOwnerHierarchyId=", formattedOwnerHierarchyId);
                        if (!isOwnerCorpReq) {
                            Map<String, String> mdnHierarchyInfo = corpSubsProvInfoUtil.getMdnsHierarchyInfo(internalMemLst, xdmsHome, true, persisterTxn);
                            List<String> incontextMemlist = groupInfoUtil.getIncontextMemListByHierarchy(mdnHierarchyInfo, idListValuesString);
                            internalMemLst.retainAll(incontextMemlist);
                            knLogger.debug(methodName, " [Hierarchy] final mdns after hierarchy filteration ", KnGDPRTemplate.mdnList(internalMemLst));
                        }
                    } else {
                        isOwnerCorpReq = groupInfoUtil.isOwnerRequest(idListValues, idType, groupHierarchyMap, corpProfile.getXdmsHome(), persisterTxn);
                        knLogger.debug(methodName, " isOwnerCorpReq  ", isOwnerCorpReq);
                        if (!isOwnerCorpReq) {
                            Map<String, Map<String, Integer>> mdnFanBanInfo = corpSubsProvInfoUtil.getMdnsFanBanInfo(internalMemLst, xdmsHome, true, persisterTxn);
                            List<String> incontextMemlist = groupInfoUtil.getIncontextMemList(mdnFanBanInfo, idListValues, idType);
                            internalMemLst.retainAll(incontextMemlist);
                            knLogger.debug(methodName, " final mdns after filteration ", KnGDPRTemplate.mdnList(internalMemLst));
                        }
                    }
                }

                //Update Group Hierarchy Map with missing idValues
                Map<Integer, Integer> idValGroupidMap = new HashMap<>();
                for (Entry<Integer, Integer> entry : groupHierarchyMap.entrySet()) {
                    if ((Integer.parseInt(BAN_TYPE) == idType) && Integer.parseInt(OWNER_BAN_TYPE) == entry.getValue()) {
                        idValGroupidMap.put(entry.getKey(), entry.getValue());
                    } else if (Integer.parseInt(FAN_TYPE) == idType) {
                        idValGroupidMap.put(entry.getKey(), entry.getValue());
                    }
                }
                knLogger.debug(methodName, " Hierarchy Ban Info ", idValGroupidMap);
                List<Integer> fansNotPresentInHierarchy = idListValues.stream().filter(fanId -> !(idValGroupidMap.containsKey(fanId))).collect(Collectors.toList());
                knLogger.debug(methodName, " fans not present in hierrachy ", fansNotPresentInHierarchy);
                List<String> allGrpMemList = sublistInfoUtil.selectGroupMemberList(groupId, xdmsHome, true, persisterTxn);
                if (!fansNotPresentInHierarchy.isEmpty()) {
                    List<Integer> distFanBanInfo;
                    Map<Integer,String> ownerFanBanIdList;
                    if (Integer.parseInt(FAN_TYPE) == idType) {
                        ownerFanBanIdList = corpSubsProvInfoUtil.getFanDetailsByCorporateId(groupPersistDTO.getCorpId(), xdmsHome, persisterTxn, true);
                        distFanBanInfo = corpSubsProvInfoUtil.getDistinctFanInfo(allGrpMemList, xdmsHome, persisterTxn, true);
                    } else {
                        ownerFanBanIdList = corpSubsProvInfoUtil.getBanDetailsByCorporateId(groupPersistDTO.getCorpId(), xdmsHome, persisterTxn, true);
                        distFanBanInfo = corpSubsProvInfoUtil.getDistinctBanInfo(allGrpMemList, xdmsHome, persisterTxn, true);
                    }
                    List<String> fansToBeInserted = distFanBanInfo.stream().filter(dbFanId -> !(idValGroupidMap.containsKey(dbFanId)) && ownerFanBanIdList.containsKey(dbFanId)).map(Object::toString).collect(Collectors.toList());
                    groupInfoUtil.insertGroupHiearchyMap(groupId, fansToBeInserted, String.valueOf(idType), xdmsHome, persisterTxn);
                }
            }

            String idTypeStr = (String) groupInfoDTO.getCustomParamMap().get(IDTYPE);
            int idType = (idTypeStr != null && !idTypeStr.isEmpty()) ? Integer.parseInt(idTypeStr) : 0;

            Map<String, Integer> intMemContCntMap = groupInfoUtil.getSubsContactCount(internalMemLst, xdmsHome, true, persisterTxn);
            Collection<KnCorpGroupMemPersistDTO> grpMemberList = groupInfoUtil.getGrpMemDetails(internalMemLst,
                    intMemContCntMap, corpId, corpProfile.getMaxContactsPerSubsc(), xdmsHome, true, persisterTxn);
            knLogger.info(methodName,"grpMemberList::",grpMemberList);
            //If request is from shared, do not add external subscribers to the group member.
            if(isOwnerCorpReq){
                Collection<KnCorpGroupMemPersistDTO> extGrpMemberList = groupInfoUtil.getExtGrpMemDetails(extMemLst,
                        corpId, xdmsHome, true, persisterTxn);
                knLogger.debug(methodName, "Before removing extMemberList ", extMemLst +"from - grpMemberList",grpMemberList);
                grpMemberList.removeAll(extGrpMemberList);
                grpMemberList.addAll(extGrpMemberList);
                knLogger.debug(methodName, "After removing extMemberList ", extMemLst +"from - grpMemberList",grpMemberList);
            }
            if (Integer.parseInt(HIER_CTX_ID_TYPE) == idType) {
                // Hierarchy ID type (idType=3): owner = requesting hierarchyId matches group's CORPGROUPINFO.HIERARCHY_ID
                // Shared = filter members to only those whose subscriber HIERARCHY_ID matches the requesting hierarchyId
                String groupOwnerHierarchyId = groupPersistDTO.getHierarchyId();
                String formattedOwnerHierarchyId = (groupOwnerHierarchyId != null && !groupOwnerHierarchyId.trim().isEmpty())
                        ? String.format("%08d", Integer.parseInt(groupOwnerHierarchyId.trim()))
                        : "";
                List<String> idListValuesString = (List<String>) groupInfoDTO.getCustomParamMap().get(com.kodiak.common.resources.KnConstants.IDLIST);
                isOwnerCorpReq = idListValuesString.stream()
                        .anyMatch(reqHier -> reqHier.trim().equals(formattedOwnerHierarchyId));
                knLogger.debug(methodName, " [Hierarchy] isOwnerCorpReq=", isOwnerCorpReq,
                        " groupOwnerHierarchyId=", formattedOwnerHierarchyId);
                List<String> mdnList = grpMemberList.stream().map(KnCorpGroupMemPersistDTO::getMdn).collect(Collectors.toList());
                knLogger.debug(methodName, "RequestedMDN list::", mdnList);
                if (!isOwnerCorpReq) {
                    Map<String, String> mdnHierarchyInfo = corpSubsProvInfoUtil.getMdnsHierarchyInfo(mdnList, xdmsHome, true, persisterTxn);
                    knLogger.debug(methodName, "mdnHierarchyInfo is :: ", mdnHierarchyInfo);
                    List<String> incontextMemlist = groupInfoUtil.getIncontextMemListByHierarchy(mdnHierarchyInfo, idListValuesString);
                    knLogger.debug(methodName, "incontextMemlist is :: ", incontextMemlist);
                    mdnList.retainAll(incontextMemlist);
                    knLogger.debug(methodName, " [Hierarchy] final mdns after hierarchy filteration ", KnGDPRTemplate.mdnList(mdnList));
                    grpMemberList = grpMemberList.stream().filter(dto -> mdnList.contains(dto.getMdn())).collect(Collectors.toList());
                    knLogger.debug(methodName, "Filtered MDN list::", grpMemberList);
                }
            }

            //Step: Filter Sublist id based on hierarchyId
            String loggedInHierarchyId = null;
            // If owner is not fetching then filtering hierarchyId's based on IDList
            if (!isOwnerCorpReq) {
                List<String> idListStr = (List<String>) customParams.get(com.kodiak.common.resources.KnConstants.IDLIST);
                if(null != idListStr && !idListStr.isEmpty()){
                   loggedInHierarchyId = idListStr.getFirst();
                }
            }
            List<KnCorpSublistDTO> sublistList = sublistInfoUtil.getGroupsSublistList(groupId, xdmsHome, true, persisterTxn);
            // Filter based on requested HierarchyId if requested person not Owner
            if (Integer.parseInt(HIER_CTX_ID_TYPE) == idType && null != sublistList
                    && !sublistList.isEmpty() && null !=loggedInHierarchyId) {
                final String finalLoggedInHierarchyId = loggedInHierarchyId;
                sublistList.removeIf(dto -> dto == null ||
                                !Objects.equals(dto.getHierarchyId(), finalLoggedInHierarchyId));
            }

            // Map<String, KnCorpGroupMemberDTO> grpMemberMap = groupInfoUtil.getGroupMembersList(groupInfoDTO.getGroupId(), xdmsHome, persisterTxn);
            Map<String, KnCorpGroupMemberDTO> grpMemberMap = groupInfoUtil.getGroupMembersListForWcsrOrCatUi(groupInfoDTO.getGroupId(), xdmsHome, true,
                    persisterTxn);
            knLogger.debug(methodName,"grpMemberMap :",KnGDPRTemplate.mapKeyMdn(grpMemberMap));
            knLogger.debug(methodName,"grpMemberList :",grpMemberList);
            List<KnCorpGroupMemberDTO> membersToBeRemoved = new ArrayList<KnCorpGroupMemberDTO>();
            Integer groupShared = groupPersistDTO.getGrpShared();
            for (KnCorpGroupMemberDTO memberDTO : grpMemberList) {
                String mdn = memberDTO.getMdn();
                KnCorpGroupMemberDTO groupMember = grpMemberMap.get(mdn);
                if((groupShared != null && groupShared == 1) && groupPersistDTO.getCorpId() != corpId && memberDTO.isExternalContact ()){
                    membersToBeRemoved.add(memberDTO);
                }
                if (groupMember == null) {
                    membersToBeRemoved.add(memberDTO);
                }else if(groupMember.getServiceAuthStatus()==com.kodiak.xdms.server.common.resources.KnConstants.SERVICE_AUTH_STATUS.MARKED_FOR_ASYNC_DELETION.value()){
                    membersToBeRemoved.add(memberDTO); // removing the pending async record from the list
                }else {
                    memberDTO.setSupervisory(groupMember.getSupervisory());
                    memberDTO.setLocWatcher(groupMember.getLocWatcher());
                    memberDTO.setBroadcaster(groupMember.getBroadcaster());
                    memberDTO.setCallInitiatePermission(groupMember.getCallInitiatePermission());
                    memberDTO.setCallReceivePermission(groupMember.getCallReceivePermission());
                    memberDTO.setInCallPermission(groupMember.getInCallPermission());
                    memberDTO.setVideoCallInitiatePermission(groupMember.getVideoCallInitiatePermission());
                    memberDTO.setVideoCallReceivePermission(groupMember.getVideoCallReceivePermission());
                    memberDTO.setVideoInCallPermission(groupMember.getVideoInCallPermission());
                    memberDTO.setIsOSMAuthorize(groupMember.getIsOSMAuthorize());
                    memberDTO.setIsAffiliationEnabled(groupMember.getIsAffiliationEnabled());
                }
            }
            if (!membersToBeRemoved.isEmpty()) {
                grpMemberList.removeAll(membersToBeRemoved);
            }

            //Added method call to get the Group supervisor.It will fetch the subscribers with supervisor at 1 or 2
            Map<String, KnCorpGroupMemberDTO> groupSupervisorMemberList = groupInfoUtil.getGroupSupervisorMembers(groupId, xdmsHome, true, persisterTxn);
            // Filter based on requested HierarchyId if requested person not Owner
            if (Integer.parseInt(HIER_CTX_ID_TYPE) == idType && null != groupSupervisorMemberList
                    && !groupSupervisorMemberList.isEmpty() && null !=loggedInHierarchyId){
                final String finalLoggedInHierarchyId = loggedInHierarchyId;
                groupSupervisorMemberList.entrySet().removeIf(entry ->
                        entry.getValue() == null ||
                                !Objects.equals(entry.getValue().getHierarchyId(), finalLoggedInHierarchyId));
            }
            //set the private list supervisor
            for (KnCorpGroupMemberDTO memberDTO : grpMemberList) {
                String mdn = memberDTO.getMdn();
                KnCorpGroupMemberDTO groupMember = groupSupervisorMemberList.get(mdn);
                if (groupMember != null) {
                    memberDTO.setSupervisory(groupMember.getSupervisory());
                    memberDTO.setLocWatcher(groupMember.getLocWatcher());
                    memberDTO.setBroadcaster(groupMember.getBroadcaster());
                    //Modified For 8.1.1 Release
                    memberDTO.setCallInitiatePermission(groupMember.getCallInitiatePermission());
                    memberDTO.setCallReceivePermission(groupMember.getCallReceivePermission());
                    memberDTO.setInCallPermission(groupMember.getInCallPermission());
                    memberDTO.setVideoCallInitiatePermission(groupMember.getVideoCallInitiatePermission());
                    memberDTO.setVideoCallReceivePermission(groupMember.getVideoCallReceivePermission());
                    memberDTO.setVideoInCallPermission(groupMember.getVideoInCallPermission());

                }
                groupSupervisorMemberList.remove(mdn);
            }
            // For group Sharing if request corpid is not owner corp id of the group then filtering supervisor to get only shared corp data
            if(groupPersistDTO.getCorpId()!= corpId){
                groupSupervisorMemberList = groupSupervisorMemberList.entrySet().stream().filter(e->e.getValue().getCorpId() == corpId).collect(Collectors.toMap(Entry::getKey, Entry::getValue));
            }

            //get the names of the supervisory rom the sublist
            Set<String> sublistSupervisory = groupSupervisorMemberList.keySet();
            Map<String, String> subscNamesList = contactInfoUtil.getSubscribersName(sublistSupervisory, xdmsHome, true, persisterTxn);
            Collection<KnCorpGroupMemPersistDTO> supervisorDetails = groupInfoUtil.getGrpMemDetails(new ArrayList<>(sublistSupervisory),
                    intMemContCntMap, corpId, corpProfile.getMaxContactsPerSubsc(), xdmsHome, true, persisterTxn);
            knLogger.debug(methodName,"supervisorDetails :",supervisorDetails);
            knLogger.debug(methodName,"subscNamesList :",KnGDPRTemplate.mdnMap(subscNamesList));
            for (String mdn : subscNamesList.keySet()) {
                KnCorpGroupMemberDTO groupMember = groupSupervisorMemberList.get(mdn);
                groupMember.setName(subscNamesList.get(mdn));
                KnCorpGroupMemPersistDTO corpGroupMemDetails = supervisorDetails.stream()
                        .filter(e -> e.getMdn().equals(mdn)).findAny().orElse(null);
                if(corpGroupMemDetails!=null){
                    groupMember.setClientType(corpGroupMemDetails.getClientType());
                }
                groupSupervisorMemberList.put(mdn, groupMember);
            }
            boolean emergDestExists = corpSubsProvInfoUtil.isEmergencyDestExists(String.valueOf(groupInfoDTO.getGroupId()), xdmsHome, true, persisterTxn);

            Collection<KnSIPProxySvcConfigDTO> sipProxySvcConfigInfoDTO = commonInfoUtil.getSipProxySvcConfig(xdmsHome, true, persisterTxn);
            //Step:
            //prepare Group Details respone
            Collection<KnCorpGroupMemberDTO> groupMembers = new ArrayList<KnCorpGroupMemberDTO>();
            groupMembers.addAll(grpMemberList);
            groupPersistDTO.setGroupMembers(groupMembers);
            groupPersistDTO.setGroupSupervisor(groupSupervisorMemberList.values());
            groupPersistDTO.setSublistList(sublistList);
            groupPersistDTO.setEmergGrp(emergDestExists);
            String groupPocHome = groupInfoUtil.fetchGroupPocHome(groupInfoDTO.getGroupId(), xdmsHome, persisterTxn);
            String effectivePocHome = genInfoUtil.getEffectivePocHome(corpPocHome, groupPocHome);
            groupPersistDTO.setGroupUri(commonInfoUtil.mcpttGroupUri(groupId, groupPersistDTO.getCorpId(), sipProxySvcConfigInfoDTO.stream()
                    .filter(sipProxy -> sipProxy.getPttServerId().equals(effectivePocHome)).findFirst()
                    .map(KnSIPProxySvcConfigDTO::getSipProxyURI).orElse(null)));
            if((isMcxGrp!=null && isMcxGrp==1)) {
                groupPersistDTO.setGroupMemberCount(0);
            }else {
                groupPersistDTO.setGroupMemberCount(grpMemberList.size());
            }
            //For Group Sharing Feature
            if (groupShared != null && groupShared == GROUP_SHARING_ENABLE_INDICATOR) {
                Set<Integer> groupIds = new HashSet<>();
                groupIds.add(groupId);
                Map<Integer,List<KnCorpSharedCorpInfo>> corpSharedCorpInfoMap = groupInfoUtil.selectGroupSharedCorpInfoByGroupId(groupIds, xdmsHome, true, persisterTxn);
                List<KnCorpSharedCorpInfo> corpSharedCorpInfos = new ArrayList<>(1);
                if(corpSharedCorpInfoMap.containsKey(groupId)) {
                    corpSharedCorpInfos =  corpSharedCorpInfoMap.get(groupId);
                }
                List<KnCorpSharedCorpInfo> shrdCrpInfosFilteredByOwnerCorpId = corpSharedCorpInfos.stream().
                        filter(info -> info.getOwnerCorpId() == corpId).
                        collect(Collectors.toList());
                List<KnCorpSharedCorpInfo> shrdCrpInfosFilteredBySharedCorpId = corpSharedCorpInfos.stream().
                        filter(info -> info.getCorpId() == corpId).
                        collect(Collectors.toList());
                if (!shrdCrpInfosFilteredByOwnerCorpId.isEmpty()) {
                    corpSharedCorpInfos = shrdCrpInfosFilteredByOwnerCorpId;
                } else {
                    corpSharedCorpInfos = shrdCrpInfosFilteredBySharedCorpId;
                }
                if (!corpSharedCorpInfos.isEmpty()) {
                    Set<Integer> sharedIntCorpIds = corpSharedCorpInfos.stream().map(KnCorpSharedCorpInfo::getCorpId).collect(Collectors.toSet());
                    Integer ownerCorpId = corpSharedCorpInfos.stream().map(KnCorpSharedCorpInfo::getOwnerCorpId).findFirst().get();
                    sharedIntCorpIds.add(ownerCorpId);
                    knLogger.info(methodName, "Shared and Owner CorpIds = ", sharedIntCorpIds);
                    Map<String, Integer> extIntCorpIDMap = commonInfoUtil.getCorpIdMap(null, sharedIntCorpIds, true, persisterTxn);
                    corpSharedCorpInfos.forEach(info -> {
                        Optional<String> sharedExtCorpId = extIntCorpIDMap.entrySet().stream().filter(e -> e.getValue().intValue() == info.getCorpId()).map(Entry::getKey).findFirst();
                        sharedExtCorpId.ifPresent(info::setExtCorpId);
                    });
                    String ownerExtCorpId = extIntCorpIDMap.entrySet().stream().filter(e -> e.getValue().intValue() == ownerCorpId).map(Entry::getKey).findFirst().get();
                    groupInfoUtil.populateGroupMemProperties(corpSharedCorpInfos, generalCacheUtil, ownerExtCorpId.trim(), true);
                    knLogger.info(methodName, "Populated Group members in corpSharedCorpInfos ", corpSharedCorpInfos);
                    groupPersistDTO.setCorpSharedCorpInfoList(corpSharedCorpInfos);
                    groupPersistDTO.setGrpOwnerCorpId(String.valueOf(ownerCorpId));
                    groupPersistDTO.setGrpOwnerExtCorpId(ownerExtCorpId.trim());
                }
            }

            if (hiearchyCall) {
                List<Integer> groupList = new ArrayList<>();
                groupList.add(groupId);
                Map<Integer, List<String>> groupContextMap = groupInfoUtil.getGroupOwnerList(groupList, String.valueOf(idType), xdmsHome, true, persisterTxn);
                Map<Integer, List<String>> groupSharedIdMap = groupInfoUtil.getGroupSharedIdList(groupList, String.valueOf(idType), xdmsHome, true, persisterTxn);
                groupPersistDTO.setOwnerIdList(groupContextMap.get(groupId));
                groupPersistDTO.setSharedIdList(groupSharedIdMap.get(groupId));
            }
            // For hierarchy ID type (idType=3), always return the group's owner hierarchy ID in ownerIdList
            Object idTypeObj = groupInfoDTO.getCustomParamMap().get(IDTYPE);
            if (HIER_CTX_ID_TYPE.equals(String.valueOf(idTypeObj))) {
                String rawOwnerHierarchyId = groupPersistDTO.getHierarchyId();
                if (rawOwnerHierarchyId != null && !rawOwnerHierarchyId.trim().isEmpty()) {
                    groupPersistDTO.setOwnerIdList(Collections.singletonList(
                            String.format("%08d", Integer.parseInt(rawOwnerHierarchyId.trim()))));
                }
            }
            //recordingFs
            int clusterId = Integer.parseInt(System.getenv(CLUSTERID_ENV_NAME));
            Map<String, String> microServicesParamNameValueMap = genInfoUtil.retrieveMSSvcsCommonConfig(clusterId, persisterTxn);
            String pttRecordingFlag = microServicesParamNameValueMap.get(PTT_RECORDING_FLAG);
            String dataRecordingFlag = microServicesParamNameValueMap.get(DATA_RECORDING_FLAG);
            String videoRecordingFlag = microServicesParamNameValueMap.get(VIDEO_RECORDING_FLAG);
            boolean responsePttRecordingFlag = ENABLED == Integer.parseInt(pttRecordingFlag);
            boolean responseDataRecordingFlag = ENABLED == Integer.parseInt(dataRecordingFlag);
            boolean responseVideoRecordingFlag = ENABLED == Integer.parseInt(videoRecordingFlag);
            String dbRecordingFs = groupPersistDTO.getRecordingFs();
            knLogger.debug(methodName, "dbRecordingFs: ", dbRecordingFs);
            if (null != dbRecordingFs) {
                Integer recordingFs = KnGeneralUtil.getRecordDataForGroup(dbRecordingFs, responsePttRecordingFlag,
                        responseDataRecordingFlag, responseVideoRecordingFlag);
                knLogger.debug(methodName, "recordingFs", recordingFs);
                if (null != recordingFs) {
                    groupPersistDTO.setRecordingFs(String.valueOf(recordingFs));
                }
                knLogger.debug(methodName, "grpPersistDTO after setting recordingFs: ", groupPersistDTO);
            }

            respDTO.setGroupInfoDTO(groupPersistDTO);

            // Fetch GROUP_HIERARCHY_MAP rows once for this group.
            // Used to: (1) filter cross-corp hierarchyList to only group-assigned hierarchies,
            //          (2) synthesize the self-corp entry for within-corp sharing.
            List<int[]> allHierMappings = new ArrayList<>();
            if (groupShared != null && groupShared == GROUP_SHARING_ENABLE_INDICATOR) {
                try {
                    allHierMappings = groupInfoUtil.getSharedGroupHierarchyMappings(groupId, xdmsHome, persisterTxn);
                } catch (Exception e) {
                    knLogger.warn(methodName, "Could not load GROUP_HIERARCHY_MAP for groupId=", groupId, " - ", e.getMessage());
                }
            }
            // Build map: sharedCorpId (CORPID) → Set of formatted hierarchy IDs actually assigned to this group
            Map<Integer, Set<String>> corpIdToActiveHierIds = new HashMap<>();
            for (int[] mapping : allHierMappings) {
                corpIdToActiveHierIds.computeIfAbsent(mapping[1], k -> new HashSet<>())
                        .add(String.format("%08d", mapping[0]));
            }

            // UCSPROVCONFIG-3162: Populate hierarchyList on each shared corp entry.
            // ownerHierarchyId is always the group's owner hierarchy from CORPGROUPINFO.HIERARCHY_ID.
            // sharedHierarchyId values come from GROUP_HIERARCHY_MAP (per CORPID) — trust matrix not needed at read time.
            if (groupShared != null && groupShared == GROUP_SHARING_ENABLE_INDICATOR
                    && groupPersistDTO.getCorpSharedCorpInfoList() != null
                    && !groupPersistDTO.getCorpSharedCorpInfoList().isEmpty()) {
                try {
                    String rawOwnerHierarchyId = groupPersistDTO.getHierarchyId();
                    String formattedOwnerHierarchyId = (rawOwnerHierarchyId != null && !rawOwnerHierarchyId.trim().isEmpty())
                            ? String.format("%08d", Integer.parseInt(rawOwnerHierarchyId.trim()))
                            : "";
                    for (KnCorpSharedCorpInfo sharedCorpInfo : groupPersistDTO.getCorpSharedCorpInfoList()) {
                        Set<String> activeHierIds = corpIdToActiveHierIds.getOrDefault(
                                sharedCorpInfo.getCorpId(), Collections.emptySet());
                        List<KnXDMHierarchyInfo> hierList = new ArrayList<>();
                        for (String sharedHierId : activeHierIds) {
                            KnXDMHierarchyInfo hierInfo = new KnXDMHierarchyInfo();
                            hierInfo.setOwnerHierarchyId(formattedOwnerHierarchyId);
                            hierInfo.setSharedHierarchyId(sharedHierId);
                            hierInfo.setSharedHierarchyName("");
                            hierList.add(hierInfo);
                        }
                        sharedCorpInfo.setHierarchyList(hierList);
                        knLogger.debug(methodName, "UCSPROVCONFIG-3162: Set hierarchyList for sharedCorp=",
                                sharedCorpInfo.getExtCorpId(), " size=", hierList.size());
                    }
                } catch (Exception e) {
                    knLogger.warn(methodName, "UCSPROVCONFIG-3162: Could not build hierarchy list for groupId=", groupId, " - ", e.getMessage());
                }
            }

            // Synthesize self-corp (owner-corp) entry from GROUP_HIERARCHY_MAP for within-corp sharing.
            // Since CORPGRP_SHAREDLIST only stores cross-corp rows, we must read GROUP_HIERARCHY_MAP
            // filtered by CORPID=ownerCorpId to build the owner corp's own hierarchy entry.
            if (groupShared != null && groupShared == GROUP_SHARING_ENABLE_INDICATOR) {
                try {
                    int ownerCorpId = groupPersistDTO.getCorpId();
                    String rawOwnerHierarchyId = groupPersistDTO.getHierarchyId();
                    String formattedOwnerHierarchyId = (rawOwnerHierarchyId != null && !rawOwnerHierarchyId.trim().isEmpty())
                            ? String.format("%08d", Integer.parseInt(rawOwnerHierarchyId.trim()))
                            : "";
                    List<KnXDMHierarchyInfo> selfHierList = new ArrayList<>();
                    for (int[] mapping : allHierMappings) {
                        if (mapping[1] == ownerCorpId) {
                            KnXDMHierarchyInfo h = new KnXDMHierarchyInfo();
                            h.setOwnerHierarchyId(formattedOwnerHierarchyId);
                            h.setSharedHierarchyId(String.format("%08d", mapping[0]));
                            h.setSharedHierarchyName("");
                            selfHierList.add(h);
                        }
                    }
                    if (!selfHierList.isEmpty()) {
                        List<KnCorpSharedCorpInfo> currentList = groupPersistDTO.getCorpSharedCorpInfoList();
                        boolean selfAlreadyPresent = currentList != null && currentList.stream()
                                .anyMatch(info -> info.getCorpId() != null && info.getCorpId().intValue() == ownerCorpId);
                        if (!selfAlreadyPresent) {
                            String ownerExtCorpId = groupPersistDTO.getGrpOwnerExtCorpId();
                            if (ownerExtCorpId == null || ownerExtCorpId.isEmpty()) {
                                Set<Integer> ownerSet = new HashSet<>();
                                ownerSet.add(ownerCorpId);
                                Map<String, Integer> corpIdMap = commonInfoUtil.getCorpIdMap(null, ownerSet, true, persisterTxn);
                                ownerExtCorpId = corpIdMap.entrySet().stream()
                                        .filter(e -> e.getValue().intValue() == ownerCorpId)
                                        .map(Entry::getKey)
                                        .findFirst().orElse("");
                            }
                            KnCorpSharedCorpInfo selfEntry = new KnCorpSharedCorpInfo();
                            selfEntry.setCorpId(ownerCorpId);
                            selfEntry.setExtCorpId(ownerExtCorpId.trim());
                            selfEntry.setOwnerCorpId(ownerCorpId);
                            selfEntry.setHierarchyList(selfHierList);
                            if (currentList == null) {
                                currentList = new ArrayList<>();
                                groupPersistDTO.setCorpSharedCorpInfoList(currentList);
                            }
                            currentList.add(selfEntry);
                            if (groupPersistDTO.getGrpOwnerCorpId() == null) {
                                groupPersistDTO.setGrpOwnerCorpId(String.valueOf(ownerCorpId));
                                groupPersistDTO.setGrpOwnerExtCorpId(ownerExtCorpId.trim());
                            }
                            knLogger.debug(methodName, "Synthesized self-corp entry for ownerCorpId=", ownerCorpId, " hierarchyCount=", selfHierList.size());
                        }
                    }
                } catch (Exception e) {
                    knLogger.warn(methodName, "Failed to synthesize self-corp entry for getGroupDetails groupId=", groupId, " - ", e.getMessage());
                }
            }

            populate(respDTO);
            if (responseDTO.getFailedDataList() != null && !responseDTO.getFailedDataList().isEmpty()) {
                respDTO.setFailedDataList(responseDTO.getFailedDataList());
            }
        } catch (KnValidationException e) {
            knLogger.error(methodName, "KnCorpBOValidationException occured while retrieving Group Details - ", e);
            populate(respDTO, e);
        } catch (KnCorpBOException e) {
            knLogger.error(methodName, "KnCorpBOException occured while retrieving Group Details - ", e);
            populate(respDTO, e);
        } catch (Exception e) {
            knLogger.error(methodName, "Unexpected Exception occured while retrieving Group Details - ",
                    new KnException(KnErrorCodes.BOEntity.INTERNAL_ERROR, e.getMessage(), e));
            populate(respDTO, e);
        }
        knLogger.debug(methodName, "EXIT : GroupDetails Response - ", respDTO);
        return respDTO;
    }

    public KnCorpGroupInfoRespDTO getSubsGroupDetails(KnIPCorpGroupDTO groupInfoDTO, KnPersisterTxn persisterTxn) {
        String methodName = "getSubsGroupDetails(KnIPCorpGroupDTO, KnPersisterTxn)";
        knLogger.info(methodName, "ENTRY : Input DTO Passed - ", groupInfoDTO.getOwner(), " groupId", groupInfoDTO.getGroupId());
        KnCorpGroupInfoRespDTO respDTO = new KnCorpGroupInfoRespDTO();
        try {
            knLogger.debug(methodName, "Fetch the subscribers profile if cached or fetch from the DB the details");
            String mdn = groupInfoDTO.getOwner();
            KnSubsProfileDTO subscProfile = commonInfoUtil.getProfileDetails(mdn, PUBLIC_PROFILE,
                    false, persisterTxn);
            String xdmsHome = subscProfile.getXdmsHome();
            int subscCorpId = subscProfile.getCorpId();
            if (subscCorpId <= 0) {
                knLogger.error(methodName, "Invalid Corporate Subscriber passed. MDN - ", KnGDPRTemplate.mdn(mdn));
                populate(respDTO, KnErrorCodes.BOEntity.INVALID_SUBSCRIPTION_TYPE, "Invalid Corp Subscriber");
            } else {
                KnCorpGroupDTO groupBasicInfo = groupInfoUtil.getGroupBasicInfo(groupInfoDTO.getGroupId(), groupInfoDTO.getClientType(),
                        xdmsHome, true, persisterTxn);
                int corpId = groupBasicInfo.getCorpId();
                knLogger.debug(methodName, "Fetch the corpProfile profile if cached or fetch from the DB the details");
                KnCorpProfileDTO corpProfile = commonInfoUtil.getProfileDetails(String.valueOf(subscCorpId), CORP_PROFILE, false, persisterTxn);
                knLogger.debug(methodName, "Retrieved Corp Profile details - ", corpProfile);
                if (groupInfoDTO.getClientType() != CLIENT_TYPE_CAT_UI) {
                    groupInfoDTO.setCorpId(corpId);
                }
                int etag = groupBasicInfo.getETag();
                KnCorpGroupInfoPersistDTO groupPersistDto = new KnCorpGroupInfoPersistDTO();
                groupPersistDto.setInputDTO(groupInfoDTO);
                groupPersistDto.setETag(etag);
                int maxGroupMembers = corpProfile.getMaxMemPerCorpGroup();
                if (groupBasicInfo.isLargeGroup()) {
                    maxGroupMembers = corpProfile.getMaxMemPerLrgGrp();
                }
                if (groupBasicInfo.getGroupType() == DISPATCH_GROUP) {
                    if (groupBasicInfo.isLargeGroup()) {
                        maxGroupMembers = corpProfile.getMaxMemPerLrgGrp();
                    } else {
                        maxGroupMembers = corpProfile.getMaxMembersPerDispatchGroup();
                    }
                } else if (groupBasicInfo.getGroupType() == BROADCAST_GROUP) {
                    if (groupBasicInfo.isLargeGroup()) {
                        maxGroupMembers = corpProfile.getMaxMemPerLrgBGrp();
                    } else {
                        maxGroupMembers = corpProfile.getMaxMemPerBCGrp();
                    }
                }
                List<String> trucMemberList = groupInfoUtil.getTruncatedGroupMems(groupInfoDTO.getGroupId(),
                        maxGroupMembers, xdmsHome, true, persisterTxn);

                Map<String, KnCorpGroupMemberDTO> grpMemberMap = groupInfoUtil.getGroupMembersList(groupInfoDTO.getGroupId(), xdmsHome, true, persisterTxn);
                List<String> allMemberList = new ArrayList<String>(grpMemberMap.keySet());
                boolean subscPartOfGrp = allMemberList.contains(mdn);
                knLogger.debug(methodName, "subscPartOfGrp ", subscPartOfGrp);
                groupPersistDto.setGroupMember(subscPartOfGrp);
                KnCorpGroupMemPersistDTO performer = new KnCorpGroupMemPersistDTO();
                performer.setInputDTO(groupInfoDTO);
                performer.setMdn(mdn);
                groupPersistDto.setPerformerDetails(performer);
                Map<String, KnSubscriberDTO> groupMemberNameMap = contactInfoUtil.getSubscribersNameForCorp(allMemberList, corpId, xdmsHome, true, persisterTxn);
                List<String> extMdnList = contactInfoUtil.filterInternalExternalContactsForSubc(groupMemberNameMap.keySet(), allMemberList);
                Collection<KnCorpSubscriberDTO> extContList = new ArrayList<KnCorpSubscriberDTO>();
                for (String extMdn : extMdnList) {
                    KnCorpSubscriberDTO subscriberDTO = new KnCorpSubscriberDTO();
                    subscriberDTO.setMdn(extMdn);
                    extContList.add(subscriberDTO);
                }
                groupPersistDto.setExternalContacts(extContList);
                groupPersistDto.setCorpId(subscCorpId);
                knLogger.debug(methodName, "Before Authorization DTO passed - ", groupPersistDto);
                authorizationFwk.authorize(groupPersistDto);
                knLogger.debug(methodName, "After Authorization ");
                int groupID = groupInfoDTO.getGroupId();
                List<String> groupIDList = new ArrayList<>();
                groupIDList.add(String.valueOf(groupID));
                commonInfoUtil.validateCorpAndGroupParams(groupIDList, String.valueOf(corpId), xdmsHome, persisterTxn);

                //Invoking custom hook
                KnCorpHookRespDTO responseDTO = new KnCorpHookRespDTO();
                if (groupInfoDTO.getClientType() == CLIENT_TYPE_CAT_UI) {
                    Map<String, Object> customParams = groupInfoDTO.getCustomParamMap();
                    if (groupInfoDTO.getHierarchyType() == HIERARCHY_TYPE.HIERARCHY) {
                        customParams.put(CURRENT_MASTER_LIST_ETAG, corpProfile.getCorpMasterListEtag());
                        customParams.put(PERSISTER_TXN, persisterTxn);
                        customParams.put(PTT_SERVER_ID, xdmsHome);
                        groupInfoDTO.setCustomParamMap(customParams);
                        KnCorpHookIPDTO hookIPDTO = new KnCorpHookIPDTO();
                        hookIPDTO.setAction(KnActions.ACTIONS.GET_SUBSC_SPEC_DETAILS);
                        hookIPDTO.setData(groupInfoDTO);
                        KnProcessInvokerImpl processInvoker = KnProcessInvokerImpl.getInstance();
                        Object hookResp = processInvoker.invokeHook(CUSTOM_CORP_USER_HOOK, hookIPDTO);
                        if (hookResp instanceof KnCorpHookRespDTO) {
                            responseDTO = (KnCorpHookRespDTO) hookResp;
                            if (com.kodiak.xdms.server.common.resources.KnConstants.RESPONSE_STATUS.FAILURE.value() == responseDTO.getStatus()) {
                                knLogger.error(methodName, "Returning Failure response");
                                populateXdmResponseFroomHook(responseDTO, respDTO);
                                return respDTO;
                            }
                        }
                    }
                }
                boolean hiearchyCall = groupInfoDTO.getHierarchyType() == HIERARCHY_TYPE.HIERARCHY;
                if (hiearchyCall) {
                    Map<String, Object> customMap = groupInfoDTO.getCustomParamMap();
                    Collection<String> idListStr = (Collection<String>) customMap.get(com.kodiak.common.resources.KnConstants.IDLIST);
                    Object idTypeObj = customMap.get(IDTYPE);
                    int idType;
                    List<String> groupIdList = new ArrayList<>();
                    groupIdList.add(String.valueOf(groupInfoDTO.getGroupId()));
                    if (idTypeObj instanceof Integer) {
                        idType = (Integer) idTypeObj;
                    } else if (idTypeObj instanceof String) {
                        idType = Integer.parseInt((String) idTypeObj);
                    } else {
                        throw new IllegalArgumentException("Unsupported type for IDTYPE: " + idTypeObj.getClass().getName());
                    }
                    if (idListStr != null) {
                        List<Integer> idListInt = (List<Integer>) convertStrToIntColl(idListStr);
                        commonInfoUtil.validateGroupParams(groupIdList, String.valueOf(corpId), idListInt, xdmsHome, idType, persisterTxn);
                    }
                }
                knLogger.debug(methodName, "Before Validation DTO passed - ", groupPersistDto);
                validatorFW.validate(groupPersistDto);
                knLogger.debug(methodName, "After Validation ");
                Collection<KnCorpGroupMemberDTO> groupMembers = new ArrayList<KnCorpGroupMemberDTO>();
                int memberCount = trucMemberList.size();
                //In case if the request sent from XCAP and the group is of Broadcast group type. Member details is
                // not required the send back.
                if ((BROADCAST_GROUP != groupBasicInfo.getGroupType())
                        || (groupInfoDTO.getClientType() != CLIENT_TYPE_XCAP)) {
                    Map<String, KnSubscriberDTO> extContNameMap = contactInfoUtil.getExtContName(extMdnList, corpId, xdmsHome, true, persisterTxn);
                    for (String memMdn : trucMemberList) {
                        KnCorpGroupMemberDTO member = grpMemberMap.get(memMdn);
                        member.setMdn(memMdn);
                        String memName = null;
                        int clientType = 0;
                        int contactType = 0;
                        if (groupMemberNameMap.get(memMdn) != null) {
                            memName = groupMemberNameMap.get(memMdn).getNetworkName();
                            clientType = groupMemberNameMap.get(memMdn).getClientType();
                            contactType = groupMemberNameMap.get(memMdn).getContact_type();
                        }
                        if (null == memName) {
                            memName = extContNameMap.get(memMdn).getNetworkName();
                            contactType = extContNameMap.get(memMdn).getContact_type();
                        }
                        member.setContact_type(contactType);
                        member.setClientType(clientType);
                        member.setName(memName);
                        groupMembers.add(member);
                    }
                }
                boolean emergDestExists = corpSubsProvInfoUtil.isEmergencyDestExists(String.valueOf(groupInfoDTO.getGroupId()), xdmsHome, true, persisterTxn);
                knLogger.debug(methodName, "Final Group Data Population ");
                KnCorpGroupInfoDTO groupResponseDTO = new KnCorpGroupInfoDTO();
                groupResponseDTO.setGroupDisplayName(groupBasicInfo.getGroupDisplayName());
                groupResponseDTO.setETag(etag);
                groupResponseDTO.setGroupId(groupBasicInfo.getGroupId());
                groupResponseDTO.setGroupType(groupBasicInfo.getGroupType());
                groupResponseDTO.setOverrideDnd(groupBasicInfo.getOverrideDnd());
                groupResponseDTO.setAvatar(groupBasicInfo.getAvatar());
                groupResponseDTO.setCorpId(corpId);
                groupResponseDTO.setMaxNumberOfMembers(corpProfile.getMaxMemPerCorpGroup());
                groupResponseDTO.setGroupMembers(groupMembers);
                groupResponseDTO.setGroupMemCount(memberCount);
                groupResponseDTO.setSubscrProtocolversion(subscProfile.getProtocolVersion());
                groupResponseDTO.setEmergAutoFloorTimer(groupBasicInfo.getEmergAutoFloorTimer());
                groupResponseDTO.setEmergHangTimeAddOn(groupBasicInfo.getEmergHangTimeAddOn());
                groupResponseDTO.setEmergOverrideDND(groupBasicInfo.getEmergOverrideDND());
                groupResponseDTO.setHangTimeOut(groupBasicInfo.getHangTimeOut());
                groupResponseDTO.setEmergGrp(emergDestExists);
                groupResponseDTO.setLargeGroup(groupBasicInfo.isLargeGroup());
                groupResponseDTO.setPocHome(groupBasicInfo.getPocHome());
                groupResponseDTO.setGroupProfileId(groupBasicInfo.getGroupProfileId());
                groupResponseDTO.setIsPreConfiguredGroup(groupBasicInfo.getIsPreConfiguredGroup());
                groupResponseDTO.setUgwInterop(groupBasicInfo.getUgwInterop());
                groupResponseDTO.setAuthorizedLargeTG(groupBasicInfo.getAuthorizedLargeTG());
                groupResponseDTO.setVideoPermission(groupBasicInfo.getVideoPermission()); // fix: null-safe;
                respDTO.setGroupInfoDTO(groupResponseDTO);
                populate(respDTO);
                if (responseDTO.getFailedDataList() != null && !responseDTO.getFailedDataList().isEmpty()) {
                    respDTO.setFailedDataList(responseDTO.getFailedDataList());
                }
            }
        } catch (KnAuthorizationException e) {
            knLogger.error(methodName, "KnAuthorizationException occured while retrieving Group Details - ", e);
            populate(respDTO, e);

        } catch (KnValidationException e) {
            knLogger.error(methodName, "KnValidationException occured while retrieving Group Details - ", e);
            populate(respDTO, e);

        } catch (KnCorpBOException e) {
            knLogger.error(methodName, "KnCorpBOException occured while retrieving Group Details - ", e);
            populate(respDTO, e);

        } catch (Exception e) {
            knLogger.error(methodName, "Unexpected Exception occured while retrieving Group Details - ",
                    new KnException(KnErrorCodes.BOEntity.INTERNAL_ERROR, e.getMessage(), e));
            populate(respDTO, e);

        }
        knLogger.debug(methodName, "EXIT: GroupDetails Response - ", respDTO);
        return respDTO;
    }


    public KnCorpGroupInfoRespDTO getSubsCorpGroupDetails(KnIPCorpGroupDTO groupInfoDTO, KnPersisterTxn persisterTxn) {
        String methodName = "getSubsCorpGroupDetails(KnIPCorpGroupDTO, KnPersisterTxn)";
        knLogger.info(methodName, "ENTRY : Input DTO Passed - ", groupInfoDTO.getOwner(), " groupId:", groupInfoDTO.getGroupId());
        KnCorpGroupInfoRespDTO respDTO = new KnCorpGroupInfoRespDTO();
        try {
            knLogger.debug(methodName, "The mcptt_id", KnGDPRTemplate.mcpttId(groupInfoDTO.getMcPttId()));
            String reqestingMdn = groupInfoDTO.getOwner();
            KnSubsProfileDTO subscProfile = null;
            KnCorpGroupInfoPersistDTO groupPersistDto = new KnCorpGroupInfoPersistDTO();
            groupPersistDto.setInputDTO(groupInfoDTO);
            int requestingCorpId = 0;
            String userProfileId = null;
            int clientMajorVersion =0;
            String activeFS2 = null;
            KnSubscriberPersistDTO originator = new KnSubscriberPersistDTO();
            KnCorpmgmtTokenvalidation validate = new KnCorpmgmtTokenvalidation();
            if (reqestingMdn != null) {
                subscProfile = commonInfoUtil.getProfileDetails(reqestingMdn, PUBLIC_PROFILE, false, persisterTxn);
                userProfileId = subscProfile.getUserProfileId();
                requestingCorpId = subscProfile.getCorpId();
                clientMajorVersion = subscProfile.getClientMajorVersion();
                activeFS2 = subscProfile.getActiveFS2();
                originator.setInputDTO(groupInfoDTO);
                originator.setMcpttCompliance(subscProfile.getMcpttCompliance());
                originator.setMcpttID(subscProfile.getMcpttId());
                validate.validateToken(originator);

                knLogger.debug(methodName, "groupBasicInfo.getMcptt_id()", KnGDPRTemplate.mcpttId(subscProfile.getMcpttId()));
            }

            String xdmsHome = genInfoUtil.retrieveLocalXDMPttServerId();
            KnCorpGroupDTO groupBasicInfo = groupInfoUtil.getGroupDetails(groupInfoDTO.getGroupId(), groupInfoDTO.getClientType(), xdmsHome, true, persisterTxn);
            if (groupBasicInfo !=null && groupBasicInfo.getGroupId() != groupInfoDTO.getGroupId()) {
                knLogger.error(methodName, "Group not found for groupId - ", groupInfoDTO.getGroupId());
                throw new KnCorpBOException(KnErrorCodes.Validator.GROUP_NOT_EXIST_CORP, "Group is not exist in the corporation");
            }
            Integer memberCount = groupInfoUtil.getMemberCountFromMemberList(groupInfoDTO.getGroupId(),xdmsHome, true, persisterTxn);
            boolean newRegroupActiveFs = false;
            if(activeFS2 != null && !activeFS2.isEmpty())
                newRegroupActiveFs = featureSetUtil.getFeatureBitValue(activeFS2, FEATURE_SET.MCX_GROUP_REGROUP_FLAG_BIT.value());
            int corpId = groupBasicInfo.getCorpId();
            Boolean externalCorpGroup = Boolean.FALSE;
            knLogger.info(methodName, " externalCorpGroupExt :", subscProfile);
            if (subscProfile != null) {
                externalCorpGroup = groupInfoUtil.validateExtCorpGroup(subscProfile.getUserProfileId(), subscProfile.getCorpId(), corpId, groupBasicInfo.getGroupId(), xdmsHome, true, persisterTxn);
            }
            knLogger.debug(methodName, "Fetch the corpProfile profile if cached or fetch from the DB the details");
            KnCorpProfileDTO corpProfile = commonInfoUtil.getProfileDetails(String.valueOf(corpId), CORP_PROFILE, false, persisterTxn);
            knLogger.debug(methodName, "Retrieved Corp Profile details - ", corpProfile);
            int etag = groupBasicInfo.getETag();
            if (groupBasicInfo.getOSMListId() != null && !groupBasicInfo.getOSMListId().isEmpty()) {
                KnCorpOSMInfoListDetailsRespDTO osmListDetails = null;
                //client type set in mcs req
                if (groupInfoDTO.getClientType() == CLIENT_TYPE_XCAP
                        && clientMajorVersion >= PROTOCOL_VERSION_16) {
                    osmListDetails = corpOSMInfoUtil.getOSMListDetailsByListIdReadonly
                            (String.valueOf(groupBasicInfo.getCorpId()), groupBasicInfo.getOSMListId(), xdmsHome, true, persisterTxn);
                    knLogger.debug(methodName, "Retrieved osmListDetails - ", osmListDetails);
                    respDTO.setOSMListDetails(osmListDetails.getOSMListDetails());
                } else if (groupInfoDTO.getClientType() == PTX_XDMDATA_INTF) {
                    osmListDetails = corpOSMInfoUtil.getOSMListDetailsByListIdReadonly
                            (String.valueOf(groupBasicInfo.getCorpId()), groupBasicInfo.getOSMListId(), xdmsHome, true, persisterTxn);
                    knLogger.debug(methodName, "Retrieved osmListDetails - ", osmListDetails);
                    respDTO.setOSMListDetails(osmListDetails.getOSMListDetails());
                }
            }
            Map<String, KnCorpGroupMemberDTO> grpMemberMap = null;
            List<String> baseMdnWithProfileMdnInGroup=new ArrayList<>();
            String baseForProfileMdn=null;
            if (groupInfoDTO.getClientType() == CLIENT_TYPE_WCSR) {
                grpMemberMap = groupInfoUtil.getGroupMembersListForWcsrOrCatUi(groupInfoDTO.getGroupId(), xdmsHome, true,
                        persisterTxn);
            }else if (groupInfoDTO.getClientType() == CLIENT_TYPE_XCAP) {
                grpMemberMap = groupInfoUtil.getGroupMembersList(groupInfoDTO.getGroupId(), xdmsHome, true, persisterTxn);
                if ((null != groupBasicInfo.getGrpShared()) && (GROUP_SHARED_ENABLED.equals(groupBasicInfo.getGrpShared()))){
                    //Group is shared group, filter out other corporate members.
                    groupInfoUtil.filterGroupMembers(grpMemberMap, requestingCorpId, corpId);
                }
                Set<String> keySet = grpMemberMap.keySet();
                //getting req mdn member properties
                KnCorpGroupMemberDTO reqMdn = grpMemberMap.get(reqestingMdn);
                List<String> mdns = new ArrayList<>(keySet);
                //Find the Real Mdns for the profile Mdns
                List<String> realMdns = groupInfoUtil.getRealMdns(mdns, xdmsHome, true, persisterTxn);
                //getting map of profile to base mdn.
                Map<String, List<String>> profileMdnOfBaseMap = corpSubsProvInfoUtil.getMapOfProfileMdnByBaseMdn(realMdns, xdmsHome, true, persisterTxn);
                //getting base mdn for profile mdn
                for(Entry<String, List<String>> baseMap:profileMdnOfBaseMap.entrySet()){
                    //revisit to get from list.contains and cut down 2nd itr
                    for(String profileMdn:baseMap.getValue()){
                        if(profileMdn.equals(reqestingMdn)){
                            baseForProfileMdn=baseMap.getKey();
                        }
                    }
                }
                //Remove the profile Mdns from the map
                knLogger.debug(methodName, "realMdns - ", KnGDPRTemplate.mdnList(realMdns));
                knLogger.debug(methodName, "grpMemberMap - ", KnGDPRTemplate.mapKeyMdn(grpMemberMap));
                knLogger.debug(methodName, "profileMdnOfBaseMap - ", KnGDPRTemplate.mapKeyMdn(profileMdnOfBaseMap));
                List<String> profileMdnLists=new ArrayList<>();
                //getting all profile mdns
                Iterator<Entry<String, KnCorpGroupMemberDTO>> iterator = grpMemberMap.entrySet().iterator();
                while (iterator.hasNext()) {
                    Entry<String, KnCorpGroupMemberDTO> entry = iterator.next();
                    if (!realMdns.contains(entry.getKey())) {
                        profileMdnLists.add(entry.getKey());
                    }
                }
                knLogger.debug(methodName,"profileMdnLists :", KnGDPRTemplate.mdnList(profileMdnLists));

                //Adding base mdn having profile mdn also as group member
                for(Entry<String, List<String>> result:profileMdnOfBaseMap.entrySet()) {
                    final AtomicLong counter = new AtomicLong();
                    for(String profileMdn:result.getValue()) {
                        //more than one profile mdn for same base in memberlist
                        if(profileMdnLists.contains(profileMdn)){
                            counter.incrementAndGet();
                        }
                        if(profileMdnLists.contains(profileMdn)
                                &&grpMemberMap.keySet().contains(result.getKey())){
                            knLogger.debug(methodName,"profileMdn of base in db:",result.getKey());
                            baseMdnWithProfileMdnInGroup.add(result.getKey());
                        }
                    }
                    //more than one profile mdn for same base in memberlist
                    if(counter.intValue()>1) {
                        knLogger.debug(methodName,"more than one profileMdn in db for base mdn:",result.getKey());
                        baseMdnWithProfileMdnInGroup.add(result.getKey());
                    }
                }
                baseMdnWithProfileMdnInGroup.remove(reqestingMdn);
                knLogger.debug(methodName, "baseMdnWithProfileMdnInGroup - ",  KnGDPRTemplate.mdnList(baseMdnWithProfileMdnInGroup));
                //getting all non requesting profile mdn.
                profileMdnLists.remove(reqestingMdn);
                for(Entry<String, List<String>> result:profileMdnOfBaseMap.entrySet()) {
                    for(String profileMdn:result.getValue()) {
                        if(profileMdnLists.contains(profileMdn)){
                            KnCorpGroupMemberDTO memProp = grpMemberMap.get(profileMdn);
                            grpMemberMap.put(result.getKey(),memProp);
                        }
                    }
                }
                knLogger.debug(methodName,"After adding base of profile mdn grpMemberMap-",KnGDPRTemplate.mapKeyMdn(grpMemberMap));                //removing profile mdn
                grpMemberMap.keySet().removeAll(profileMdnLists);
                knLogger.debug(methodName,"After removing profile mdns grpMemberMap :",KnGDPRTemplate.mdnList(profileMdnLists));
                //removing base mdn with profile mdn, member props and reintializing with empty member property.
                grpMemberMap.keySet().removeAll(baseMdnWithProfileMdnInGroup);
                knLogger.debug(methodName,"After removing baseMdnWithProfileMdnInGroup from grpMemberMap- ",KnGDPRTemplate.mapKeyMdn(grpMemberMap));
                for(String baseMdn:baseMdnWithProfileMdnInGroup){
                    grpMemberMap.put(baseMdn,new KnCorpGroupMemberDTO());
                }
                knLogger.debug(methodName, "grpMemberMap after adding base mdn with profile - ",  KnGDPRTemplate.mapKeyMdn(grpMemberMap));
                //adding req mdn to response,removing basemdn of profile mdn.
                grpMemberMap.remove(baseForProfileMdn);
                knLogger.debug(methodName,"baseForProfileMdn :",KnGDPRTemplate.mdn(baseForProfileMdn));
                if (userProfileId != null && (groupBasicInfo.getMcxGrpInd() != null && groupBasicInfo.getMcxGrpInd() == 1)) {
                    knLogger.debug(methodName, "hitting mcx path");
                    //List<String> ProfileMdns = new ArrayList<String>();
                    //ProfileMdns.add(mdn);
                    //List McxGrpRealMdns = groupInfoUtil.getRealMdns(ProfileMdns, xdmsHome, persisterTxn);
                    //String mcxrealMdn = (String) McxGrpRealMdns.get(0);
                    //knLogger.debug(methodName, "Got real self MDN-", mcxrealMdn);
                    //if (mdn != null) {
                    KnCorpGroupMemberDTO knCorpGroupMemDTO = new KnCorpGroupMemberDTO(reqestingMdn);

                    //KnCorpUserProfileDTO userProfile = corpUserProfileUtil.getUserProfile(String.valueOf(corpId),
                    //	userProfileId, xdmsHome, persisterTxn);

                    Set<KnCorpGroupListInfoDTO> mcxGroupList=corpUserProfileUtil.retriveGroupProfileInfoByProfileId(userProfileId, xdmsHome, true, persisterTxn);
                    knLogger.debug(methodName, "userProfile ", mcxGroupList);
                    if (mcxGroupList != null && mcxGroupList.size() > 0) {
                        for (KnCorpGroupListInfoDTO grpInfo : mcxGroupList) {
                            if (grpInfo.getGroupID() == groupInfoDTO.getGroupId()) {
                                KnCorpGroupContactDTO corpGroupContactDTO = grpInfo.getGrpMemProps();
                                if (corpGroupContactDTO != null) {
                                    knCorpGroupMemDTO.setCallInitiatePermission(corpGroupContactDTO.getCallInitiateAllowed());
                                    knCorpGroupMemDTO.setCallReceivePermission(corpGroupContactDTO.getCallTerminateAllowed());
                                    knCorpGroupMemDTO.setInCallPermission(corpGroupContactDTO.getIncallAllowed());
                                    knCorpGroupMemDTO.setSupervisory(corpGroupContactDTO.getIsSupervisor());
                                    knCorpGroupMemDTO.setBroadcaster(corpGroupContactDTO.getIsBroadcaster());
                                    knCorpGroupMemDTO.setLocWatcher(corpGroupContactDTO.getIsLocSupervisor());
                                    knCorpGroupMemDTO.setIsOSMAuthorize(corpGroupContactDTO.getIsOSMAuthorized());
                                }
                            }

                        }
                    }
                    grpMemberMap.put(reqestingMdn, knCorpGroupMemDTO);
                    reqMdn = grpMemberMap.get(reqestingMdn);
                    //}
                }
                if(reqMdn!=null){
                    grpMemberMap.put(reqestingMdn,reqMdn);
                }
                knLogger.debug(methodName,"reqMdn :",reqMdn," mdn ",KnGDPRTemplate.mdn(reqestingMdn));
                knLogger.debug(methodName, "grpMemberMap after adding request mdn - ",  KnGDPRTemplate.mapKeyMdn(grpMemberMap));
            }else {
                grpMemberMap = groupInfoUtil.getGroupMembersListReadOnly(groupInfoDTO.getGroupId(), xdmsHome, true, persisterTxn);
            }
            List<String> allMemberList = new ArrayList<String>(grpMemberMap.keySet());
            Map<String, KnSubscriberDTO> groupMemberNameMap = contactInfoUtil.getSubscribersNameForCorpReadOnly(allMemberList, corpId, xdmsHome, true, persisterTxn);

            if ((groupInfoDTO.getClientType() == CLIENT_TYPE_XCAP)
                    && (groupBasicInfo.isLargeGroup()) && (BROADCAST_GROUP != groupBasicInfo.getGroupType())) {
                grpMemberMap = commonInfoUtil.trancateMembers(grpMemberMap, groupMemberNameMap, corpProfile.getMaxMemPerCorpGroup(), groupInfoDTO.getOwner());
            }

            List<String> extMdnList = contactInfoUtil.filterInternalExternalContactsForSubc(groupMemberNameMap.keySet(), allMemberList);
            Collection<KnCorpGroupMemberDTO> groupMembers = new ArrayList<KnCorpGroupMemberDTO>();

            //setting member properties for broadcaster group non-broadcaster or broadcaster requesting mdn
            //for Broadcast Groups by non-broadcasters or broadcaster call, only self group member details must be provided.
            boolean requestingBroadcastMember = (BROADCAST_GROUP == groupBasicInfo.getGroupType()
                    && clientMajorVersion>= PROTOCOL_VERSION_20);
            if(requestingBroadcastMember){
                grpMemberMap.keySet().removeIf(key -> !key.equals(reqestingMdn));
                knLogger.debug(methodName,"After removing all member mdn except requesting mdn:",KnGDPRTemplate.mapKeyMdn(grpMemberMap));
            }

            //In case if the request sent from XCAP and the group is of Broadcast group type. Member details is
            // not required the send back.(This is not valid for pv >=20)
            if( requestingBroadcastMember
                    ||((BROADCAST_GROUP != groupBasicInfo.getGroupType())
                    || (groupInfoDTO.getClientType() != CLIENT_TYPE_XCAP))) {
                Map<String, KnSubscriberDTO> extContNameMap = contactInfoUtil.getExtContNameReadonly(extMdnList, corpId, xdmsHome, true, persisterTxn);
                for (String memMdn : grpMemberMap.keySet()) {
                    KnCorpGroupMemberDTO member = grpMemberMap.get(memMdn);
                    member.setMdn(memMdn);
                    String memName = null;
                    int clientType = 0;
                    int contactType = 0;
                    int licenseType =0;
                    int clientPvMajorVersion = 0;
                    String activeFs = null;
                    String userAgent = null;
                    if (groupMemberNameMap.get(memMdn) != null) {
                        memName = groupMemberNameMap.get(memMdn).getNetworkName();
                        clientType = groupMemberNameMap.get(memMdn).getClientType();
                        contactType = groupMemberNameMap.get(memMdn).getContact_type();
                        clientPvMajorVersion = groupMemberNameMap.get(memMdn).getClientPVMajorVersion();
                        userAgent = groupMemberNameMap.get(memMdn).getUserAgent();
                        activeFs = groupMemberNameMap.get(memMdn).getActiveFS2();
                        licenseType = groupMemberNameMap.get(memMdn).getLicenseType();
                    }
                    if (null == memName) {
                        if(extContNameMap.get(memMdn) != null) {
                            memName = extContNameMap.get(memMdn).getNetworkName();
                            knLogger.debug("memName Received :",memName);
                        }
                        contactType = extContNameMap.get(memMdn).getContact_type();
                        knLogger.debug("contactType Received :",contactType);
                    }
                    member.setName(memName);
                    member.setClientType(clientType);
                    member.setClientPVmajorVer(clientPvMajorVersion);
                    member.setUserAgent(userAgent);
                    if(!baseMdnWithProfileMdnInGroup.contains(memMdn)) {
                        member.setContact_type(contactType);
                        member.setSubsActiveFS2(activeFs);
                        member.setLicenseType(licenseType);
                    }
                    groupMembers.add(member);
                }
            }
            knLogger.debug(methodName, "groupMembers : ", groupMembers);
            List<String> mdnList = new ArrayList<>();
            for (KnCorpGroupMemberDTO mdnListDto : groupMembers) {
                mdnList.add(mdnListDto.getMdn());
            }
            final int reqMdnPv=clientMajorVersion;
            Map<String, KnCorpSubsEntitiesDTO> subsEntitiesDTOMap = contactInfoUtil.getSubsEntitiesDetails(mdnList, xdmsHome,true, persisterTxn);
            knLogger.debug(methodName, "subsEntitiesDTOMap  ", KnGDPRTemplate.mapKeyMdn(subsEntitiesDTOMap)," reqMdnPv:",reqMdnPv);
            if (!groupMembers.isEmpty()) {
                groupMembers.forEach(contact -> {
                    contact.setUa(KnGeneralUtil.getUA(contact.getUserAgent(), contact.getClientPVmajorVer()));
                    if(reqMdnPv < PROTOCOL_VERSION_16) {
                        //BitSet activeFs2 = KnGeneralUtil.convertHexStringToBitSet(subsEntitiesDTOMap.get(contact.getMdn()).getActiveFs2());
                        //String activefs1 = subsEntitiesDTOMap.get(contact.getMdn()).getActiveFs1();
                        String activefs1 =KnGeneralUtil.convertActiveFs2toHexActiveFs1(subsEntitiesDTOMap.get(contact.getMdn()).getActiveFs2());
                        contact.setSubsActiveFS2(activefs1);
                    }else{
                        contact.setSubsActiveFS2(KnGeneralUtil.calculateActiveFeatureSetBasedOnPv(subsEntitiesDTOMap.get(contact.getMdn()).getActiveFs2(), reqMdnPv));
                    }
                    if (subsEntitiesDTOMap.get(contact.getMdn()) != null&&!baseMdnWithProfileMdnInGroup.contains(contact.getMdn())) {
                        contact.setAliasMdn(subsEntitiesDTOMap.get(contact.getMdn()).getAliasMdn());
                        contact.setUserId(subsEntitiesDTOMap.get(contact.getMdn()).getUserId());
                    }
                });
            }

            if(groupInfoDTO.getClientType() == CLIENT_TYPE_XCAP && groupBasicInfo.getMcxGrpInd() != null && groupBasicInfo.getMcxGrpInd() == 1) {
                knLogger.debug(methodName, "removing CRI members from MCX group" );
                groupMembers.removeIf(x -> subsEntitiesDTOMap.get(x.getMdn()) != null && subsEntitiesDTOMap.get(x.getMdn()).getMcpttCompliance() == 1);
            }
            KnCorpGroupInfoDTO groupResponseDTO = new KnCorpGroupInfoDTO();
            groupResponseDTO.setGroupDisplayName(groupBasicInfo.getGroupDisplayName());
            groupResponseDTO.setETag(etag);
            groupResponseDTO.setGroupId(groupBasicInfo.getGroupId());
            groupResponseDTO.setGroupType(groupBasicInfo.getGroupType());
            groupResponseDTO.setOverrideDnd(groupBasicInfo.getOverrideDnd());
            groupResponseDTO.setCorpId(corpId);
            groupResponseDTO.setMaxNumberOfMembers(corpProfile.getMaxMemPerCorpGroup());
            groupResponseDTO.setGroupMembers(groupMembers);
            groupResponseDTO.setGroupMemCount(memberCount);
            groupResponseDTO.setAvatar(groupBasicInfo.getAvatar());
            groupResponseDTO.setGroupCreatedBy(groupBasicInfo.getGroupCreatedBy());
            groupResponseDTO.setTpGroupOwner(groupBasicInfo.getTpGroupOwner());
            groupResponseDTO.setLmrInteropCapable(groupBasicInfo.getLmrInteropCapable());
            groupResponseDTO.setPocHome(groupBasicInfo.getPocHome());
            groupResponseDTO.setGrpShared(groupBasicInfo.getGrpShared());
            groupResponseDTO.setLargeGroup(groupBasicInfo.isLargeGroup());
            groupResponseDTO.setMcPttId(groupBasicInfo.getMcPttId());
            groupResponseDTO.setUgwInterop(groupBasicInfo.getUgwInterop());
            //groupResponseDTO.setIsPreConfiguredGroup(groupBasicInfo.getIsPreConfiguredGroup());
            if (externalCorpGroup && (clientMajorVersion >= PROTOCOL_VERSION_23)) {
                groupResponseDTO.setExternalCorpGroup(EXTERNAL_CORP_GROUP);
            }

            if (subscProfile != null) {
                groupResponseDTO.setSubscrProtocolversion(subscProfile.getProtocolVersion());
            }
            if (groupBasicInfo.getMcxGrpInd() != null) {
                groupResponseDTO.setMcxGrpInd(groupBasicInfo.getMcxGrpInd());
            }
            if (groupInfoDTO.getClientType() == CLIENT_TYPE_XCAP && clientMajorVersion >= PROTOCOL_VERSION_27) {
                if (groupBasicInfo.isLargeGroup()) {
                    groupResponseDTO.setMemberListCount(MEMBER_LIST_COUNT_FOR_LARGEGROUP);
                }else if(groupBasicInfo.getMcxGrpInd() != null && groupBasicInfo.getMcxGrpInd() == MCX_GROUP_INDICATOR) {
                    groupResponseDTO.setMemberListCount(memberCount);
                } else {
                    groupResponseDTO.setMemberListCount(memberCount);
                }
            }
            if (newRegroupActiveFs){
                knLogger.debug (methodName, "newRegroupfs: "+newRegroupActiveFs);
                if (groupBasicInfo.getIsPreConfiguredGroup() !=null && groupBasicInfo.getIsPreConfiguredGroup() == IS_PRECONFIG_GRP_ENABLE)
                {
                    knLogger.debug(methodName, "getIsPreConfiguredGroup: " +groupBasicInfo.getIsPreConfiguredGroup());
                    groupResponseDTO.setIsPreConfiguredGroup(IS_PRECONFIG_GRP_ENABLE);
                }
            }
            if (groupInfoDTO.getClientType() == CLIENT_TYPE_XCAP)
            {
                String ugwConf = groupInfoUtil.getUgwConfig(corpId, groupInfoDTO.getGroupId(), activeFS2, featureSetUtil, generalCacheUtil);
                groupResponseDTO.setUgwConfig(ugwConf);
            }
            if(groupBasicInfo.getRecordingFs()!=null){
                groupResponseDTO.setRecordingFs(groupBasicInfo.getRecordingFs());
            }
            if (groupBasicInfo.getAuthorizedLargeTG() != null) {
                groupResponseDTO.setAuthorizedLargeTG(groupBasicInfo.getAuthorizedLargeTG());
            }  if (groupBasicInfo.getVideoPermission() != null) {
                groupResponseDTO.setVideoPermission(groupBasicInfo.getVideoPermission());
            }

            respDTO.setGroupInfoDTO(groupResponseDTO);
            populate(respDTO);
        } catch (KnCorpBOException e) {
            knLogger.error(methodName, "KnCorpBOException occured while retrieving Group Details - ", e);
            populate(respDTO, e);

        } catch (Exception e) {
            knLogger.error(methodName, "Exception occured while retrieving Group Details - ", e);
            knLogger.error(methodName, "Unexpected Exception occured while retrieving Group Details - ",
                    new KnException(KnErrorCodes.BOEntity.INTERNAL_ERROR, e.getMessage(), e));
            populate(respDTO, e);

        }

        knLogger.info(methodName, "EXIT: GroupDetails Response - ", respDTO);
        return respDTO;
    }


    public KnCorpGroupListRespDTO getGroupList(KnIPCorpInfoDTO corpInfoDTO, KnPersisterTxn persisterTxn) {

        String methodName = "getGroupList(KnIPCorpInfoDTO, KnPersisterTxn)";
        knLogger.info(methodName, "ENTRY : Input DTO Passed with corpId- ", corpInfoDTO.getCorpId());
        KnCorpGroupListRespDTO respDTO = new KnCorpGroupListRespDTO();

        try {
            int corpId = corpInfoDTO.getCorpId();
            //Step:
            //get the Corp profile details from cache
            knLogger.debug(methodName, "Fetch the corpProfile profile if cached or fetch from the DB the details");
            KnCorpProfileDTO corpProfile = commonInfoUtil.getProfileDetails(String.valueOf(corpId),
                    CORP_PROFILE, false, persisterTxn);
            knLogger.debug(methodName, "Retrieved Corp Profile details - ", corpProfile);
            String xdmsHome = corpProfile.getXdmsHome();
            Collection<KnCorpGroupInfoPersistDTO> filteredGroupList = null;
            Map<Integer, List<KnCorpSharedCorpInfo>> sharedCorpGrpInfoMap = groupInfoUtil.selectGroupSharedCorpInfoBySharedCorpId(corpId, xdmsHome, true, persisterTxn);
            Set<Integer> groupIdList = new HashSet<>();
            if (null != corpInfoDTO.getNextToken() && 0 <= corpInfoDTO.getNextToken() &&
                    null != corpInfoDTO.getFetchSize() && 0 < corpInfoDTO.getFetchSize()) {
                groupIdList = groupInfoUtil.getGroupListCount(corpId,corpInfoDTO.getHierarchyId() ,xdmsHome, true, persisterTxn);
                filteredGroupList = groupInfoUtil.getGroupListPaginated(corpInfoDTO, corpProfile.getMaxMemPerCorpGroup(),
                        corpInfoDTO.getNextToken(), corpInfoDTO.getFetchSize(), xdmsHome, true, persisterTxn);
            } else {
                //fetch any shared GroupInfo is available with input shared corpid
                List<KnCorpGroupInfoPersistDTO> sharedGroupList = groupInfoUtil.getSharedGroupDetails(sharedCorpGrpInfoMap, xdmsHome, true, persisterTxn);
                //Step:
                //retrieve group list
                Collection<KnCorpGroupInfoPersistDTO> groupList =
                        groupInfoUtil.getGroupList(corpInfoDTO, corpProfile.getMaxMemPerCorpGroup(), xdmsHome, true, persisterTxn);
                groupList.addAll(sharedGroupList);

                filteredGroupList = groupList.stream()
                        .filter(grpDto -> grpDto.getGroupCreatedBy() != CREATED_BY.ABDG.value()).collect(Collectors.toList());
            }
            Collection<KnSIPProxySvcConfigDTO> sipProxySvcConfigInfoDTO = commonInfoUtil.getSipProxySvcConfig(xdmsHome, true, persisterTxn);

            if (null != filteredGroupList && !filteredGroupList.isEmpty()) {
                Collection<Integer> supervisorList = new ArrayList<>();
                supervisorList.add(INTER_OP);
                supervisorList.add(DISPATCHER);
                supervisorList.add(SUPERVISOR);
                Map<Integer, Collection<KnCorpGroupMemberDTO>> groupSupervisorList = groupInfoUtil.getCoporateGrpSpecificSubsc(supervisorList, corpId, xdmsHome, true, persisterTxn);
                Set<String> mdnList = new HashSet<>();
                if (groupSupervisorList != null && !groupSupervisorList.isEmpty()) {
                    for (Entry<Integer, Collection<KnCorpGroupMemberDTO>> entry : groupSupervisorList.entrySet()) {
                        Collection<KnCorpGroupMemberDTO> groupMemberDTO = entry.getValue();
                        for (KnCorpGroupMemberDTO memberDTO : groupMemberDTO) {
                            mdnList.add(memberDTO.getMdn());
                        }
                    }
                }
                Map<String, String> subscNameList = contactInfoUtil.getSubscribersName(mdnList, xdmsHome, true, persisterTxn);
                for (KnCorpGroupInfoPersistDTO grpPersistDTO : filteredGroupList) {
                    List<String> ownerList = new ArrayList<>();
                    if (groupSupervisorList != null) {
                        Collection<KnCorpGroupMemberDTO> supervisorMemberList = groupSupervisorList.get(grpPersistDTO.getGroupId());
                        if (supervisorMemberList != null) {
                            for (KnCorpGroupMemberDTO contactDTO : supervisorMemberList) {
                                String mdn = contactDTO.getMdn();
                                if (subscNameList.containsKey(mdn)) {
                                    contactDTO.setName(subscNameList.get(mdn));
                                }
                            }
                        }
                        grpPersistDTO.setGroupSupervisor(supervisorMemberList);
                        //GET group poc home for shared corpid
                        grpPersistDTO.setGroupUri(commonInfoUtil.mcpttGroupUri(grpPersistDTO.getGroupId(), grpPersistDTO.getCorpId(), sipProxySvcConfigInfoDTO.stream()
                                .filter(sipProxy -> sipProxy.getPttServerId().equals(grpPersistDTO.getPocHome())).findFirst()
                                .map(KnSIPProxySvcConfigDTO::getSipProxyURI).orElse(null)));
                    }
                    //For Group Sharing Feature
                    Integer groupShared = grpPersistDTO.getGrpShared();
                    boolean isOwnedCorp = false;
                    if (groupShared != null && groupShared == GROUP_SHARING_ENABLE_INDICATOR && sharedCorpGrpInfoMap != null) {

                        List<KnCorpSharedCorpInfo> corpSharedCorpInfos = sharedCorpGrpInfoMap.get(grpPersistDTO.getGroupId());

                        //if the group in groupInfoList not shared by other corp check for the group  in self corporate and see whether it is shared with some other corp
                        // or not
                        if (corpSharedCorpInfos == null || corpSharedCorpInfos.isEmpty()) {
                            //Check incase if the group is for the owner corp and it got shared with any other corp or not
                            corpSharedCorpInfos =
                                    groupInfoUtil.selectGroupSharedCorpInfo(corpId, grpPersistDTO.getGroupId(), xdmsHome, true, persisterTxn);
                            isOwnedCorp = true;
                        }
                        if (corpSharedCorpInfos != null && !corpSharedCorpInfos.isEmpty()) {

                            //knLogger.info(methodName, "sharedCorpInfoList - ", corpSharedCorpInfos);
                            Set<Integer> sharedIntCorpIds = corpSharedCorpInfos.stream().map(KnCorpSharedCorpInfo::getCorpId).collect(Collectors.toSet());
                            Set<Integer> ownerCorpIds = corpSharedCorpInfos.stream().map(KnCorpSharedCorpInfo::getOwnerCorpId).collect(Collectors.toSet());
                            Set<Integer> allCorpIds = new HashSet<>();
                            allCorpIds.addAll(sharedIntCorpIds);
                            allCorpIds.addAll(ownerCorpIds);

                            knLogger.info(methodName, "fetching corpId details", sharedIntCorpIds, "ownerCorpIds", ownerCorpIds);
                            Map<String, Integer> extIntCorpIDMap = commonInfoUtil.getCorpIdMap(null, allCorpIds, true, persisterTxn);
                            Map<Integer, String> intExtCorpIdMap = new HashMap<>();
                            knLogger.info(methodName, "converting shared int corpids to external corpids", allCorpIds);
                            if (extIntCorpIDMap != null && !extIntCorpIDMap.isEmpty()) {
                                intExtCorpIdMap.putAll(extIntCorpIDMap.entrySet().stream().collect(Collectors.toMap(Entry::getValue, Entry::getKey)));
                            }

                            knLogger.debug(methodName, "after converting shared int corpids to external corpids", intExtCorpIdMap);
                            corpSharedCorpInfos.forEach(info -> {
                                info.setExtCorpId(intExtCorpIdMap.get(info.getCorpId()));
                            });
                            groupInfoUtil.populateGroupMemProperties(corpSharedCorpInfos, generalCacheUtil, intExtCorpIdMap.get(corpId), isOwnedCorp);
                            knLogger.debug(methodName, "after converting shared int corpids to external corpids", corpSharedCorpInfos);
                            grpPersistDTO.setCorpSharedCorpInfoList(corpSharedCorpInfos);
                            if (null != ownerCorpIds && !ownerCorpIds.isEmpty()) {
                                int ownerCorpId = ownerCorpIds.stream().findAny().get();
                                grpPersistDTO.setGrpOwnerCorpId(String.valueOf(ownerCorpId));

                                if (null != intExtCorpIdMap && !intExtCorpIdMap.isEmpty() && intExtCorpIdMap.containsKey(ownerCorpId)) {
                                    grpPersistDTO.setGrpOwnerExtCorpId(intExtCorpIdMap.get(ownerCorpId));
                                }
                            }
                            knLogger.debug(methodName, "ownerCorpId: ", grpPersistDTO.getGrpOwnerCorpId(), "ownerExtCorpid: ", grpPersistDTO.getGrpOwnerExtCorpId());
                        }
                    }
                    //Common Api grpPersistDTO.getRecordingFs();
                    //KnGeneralUtil.getRecordDataForGroup
                    //KnCorpGroupInfoPersistDTO groupPersistDTO = new KnCorpGroupInfoPersistDTO();
                    int clusterId = Integer.parseInt(System.getenv(CLUSTERID_ENV_NAME));
                    Map<String, String> paramNameValueMapCommon = genInfoUtil.retrieveMSSvcsCommonConfig(clusterId, persisterTxn);
                    String pttRecordingVal = paramNameValueMapCommon.get(PTT_RECORDING_FLAG);
                    String dataRecordingVal = paramNameValueMapCommon.get(DATA_RECORDING_FLAG);
                    String videoRecordingVal = paramNameValueMapCommon.get(VIDEO_RECORDING_FLAG);
                    knLogger.debug(methodName, "pttRecordingVal DB: ", pttRecordingVal,
                            "dataRecordingVal DB: ", dataRecordingVal, "videoRecordingVal DB: ", videoRecordingVal);

                    boolean pttRecordingFlag = ENABLED == Integer.parseInt(pttRecordingVal);
                    boolean dataRecordingFlag = ENABLED == Integer.parseInt(dataRecordingVal);
                    boolean videoRecordingFlag = ENABLED == Integer.parseInt(videoRecordingVal);
                    knLogger.debug(methodName, "pttRecordingFlag Boolean: ", pttRecordingFlag,
                            "dataRecordingFlag Boolean: ", dataRecordingFlag, "videoRecordingFlag Boolean: ", videoRecordingFlag);

                    String recordFSValue = grpPersistDTO.getRecordingFs();
                    knLogger.debug(methodName, "recordFSValue: ", recordFSValue);
                    if (recordFSValue != null) {
                        Integer recFS = KnGeneralUtil.getRecordDataForGroup(recordFSValue, pttRecordingFlag, dataRecordingFlag, videoRecordingFlag);
                        knLogger.debug(methodName, "recFS", recFS);
                        if (recFS != null) {
                            grpPersistDTO.setRecordingFs(String.valueOf(recFS));
                        }
                        knLogger.debug(methodName, "recFS after setting in grpPersistDTO", grpPersistDTO);
                    }
                    String hierarchyId = grpPersistDTO.getHierarchyId();
                    ownerList.add(hierarchyId);
                    grpPersistDTO.setOwnerIdList(ownerList);
                }
                Collection<KnCorpGroupInfoDTO> groupInfoList = new HashSet<>(filteredGroupList.size());
                groupInfoList.addAll(new HashSet<>(filteredGroupList));
                respDTO.setGroupList(groupInfoList);
                respDTO.setCount(String.valueOf(groupIdList.size()));
            }
            populate(respDTO);

        } catch (KnCorpBOException e) {
            knLogger.error(methodName, "KnCorpBOException occured while retrieving Group List - ", e);
            populate(respDTO, e);

        } catch (Exception e) {
            knLogger.error(methodName, "KnPersistenceException occured while retrieving Group List - ",
                    new KnException(KnErrorCodes.BOEntity.INTERNAL_ERROR, e.getMessage(), e));
            populate(respDTO, e);

        }
        knLogger.debug(methodName, "EXIT : GroupDetails Response - ", respDTO);
        return respDTO;
    }

    public KnCorpGroupListRespDTO getSubscriberGroupList(KnIPCorpContactDTO corpContactDTO, KnPersisterTxn persisterTxn) {

        String methodName = "getSubscriberGroupList(KnIPCorpContactDTO, KnPersisterTxn)";
        knLogger.info(methodName, "ENTRY : Input DTO Passed with corpId and mdn - ", corpContactDTO.getCorpId(), corpContactDTO.getMdn());
        KnCorpGroupListRespDTO respDto = new KnCorpGroupListRespDTO();

        try {

            if (PTX_XDMDATA_INTF == corpContactDTO.getClientType()
                    ||CLIENT_TYPE_WCSR==corpContactDTO.getClientType()) {
                String mdn = corpContactDTO.getMdn();
                knLogger.debug(methodName, "Fetch the SubsProfile profile if cached or fetch from the DB the details");
                KnSubsProfileDTO subscProfile = commonInfoUtil.getProfileDetails(mdn, PUBLIC_PROFILE, false,
                        persisterTxn);
                knLogger.debug(methodName, "Retrieved Subs Profile details - ", subscProfile);
                int corpId = subscProfile.getCorpId();
                corpContactDTO.setCorpId(corpId);
            }
            int corpId = corpContactDTO.getCorpId();
            //Step:
            //get the Corp profile details from cache
            knLogger.debug(methodName, "Fetch the corpProfile profile if cached or fetch from the DB the details");
            KnCorpProfileDTO corpProfile = commonInfoUtil.getProfileDetails(String.valueOf(corpId),
                    CORP_PROFILE, false, persisterTxn);
            knLogger.debug(methodName, "Retrieved Corp Profile details - ", corpProfile);
            String xdmsHome = corpProfile.getXdmsHome();

            //Invoking custom hook
            KnCorpHookRespDTO responseDTO = new KnCorpHookRespDTO();
            if (CLIENT_TYPE_WCSR != corpContactDTO.getClientType()) {
                Map<String, Object> customParams = corpContactDTO.getCustomParamMap();
                if (corpContactDTO.getHierarchyType() == HIERARCHY_TYPE.HIERARCHY) {
                    contactInfoUtil.checkValidHierarchySubs(Collections.singletonList(corpContactDTO.getMdn()), customParams, xdmsHome, persisterTxn);
                    customParams.put(CURRENT_MASTER_LIST_ETAG, corpProfile.getCorpMasterListEtag());
                    customParams.put(PERSISTER_TXN, persisterTxn);
                    customParams.put(PTT_SERVER_ID, xdmsHome);
                    corpContactDTO.setCustomParamMap(customParams);
                    KnCorpHookIPDTO hookIPDTO = new KnCorpHookIPDTO();
                    hookIPDTO.setAction(KnActions.ACTIONS.GET_SUBSC_GROUP_LIST);
                    hookIPDTO.setData(corpContactDTO);
                    KnProcessInvokerImpl processInvoker = KnProcessInvokerImpl.getInstance();
                    Object hookResp = processInvoker.invokeHook(CUSTOM_CORP_USER_HOOK, hookIPDTO);
                    if (hookResp instanceof KnCorpHookRespDTO) {
                        responseDTO = (KnCorpHookRespDTO) hookResp;
                        if (com.kodiak.xdms.server.common.resources.KnConstants.RESPONSE_STATUS.FAILURE.value() == responseDTO.getStatus()) {
                            knLogger.error(methodName, "Returning Failure response");
                            populateXdmResponseFroomHook(responseDTO, respDto);
                            return respDto;
                        }
                    }
                }
            }

            /*Collection<String> mdnList = new ArrayList<String>();
            mdnList.add(corpContactDTO.getMdn());*/
            KnReverseContactPersistDto contactPersistDto = new KnReverseContactPersistDto();
            int subscribersCount = contactInfoUtil.getSubscribersCount(corpContactDTO.getMdn(), corpId, true, xdmsHome, persisterTxn);
            boolean isSubscrExternalCont = false;
            if (subscribersCount < 1) {
                isSubscrExternalCont = contactInfoUtil.isExternalContExist(corpContactDTO.getMdn(), corpId, xdmsHome, true, persisterTxn);
            }
            contactPersistDto.setInputDTO(corpContactDTO);
            contactPersistDto.setSubscriberCount(subscribersCount);
            contactPersistDto.setExternalContact(isSubscrExternalCont);
            knLogger.debug(methodName, "Before Validation DTO passed - ", contactPersistDto);
            validatorFW.validate(contactPersistDto);
            knLogger.debug(methodName, "After Validation ");

            //Step:
            //retrieve group info
            Integer subsGroupCount = 0;
            Collection<KnCorpGroupInfoPersistDTO> subsGroupList = new ArrayList<>();
            if (null != corpContactDTO.getNextToken() && 0 <= corpContactDTO.getNextToken() &&
                    null != corpContactDTO.getFetchSize() && 0 < corpContactDTO.getFetchSize()) {
                //Fetch number of corp groups for this subscriber
                subsGroupCount = groupInfoUtil.getSubsScrGroupCountExceptABDG(Arrays.asList(corpContactDTO.getMdn()),
                        xdmsHome, persisterTxn, corpId).getOrDefault(corpContactDTO.getMdn(), 0);
                respDto.setCount(String.valueOf(subsGroupCount));

                //Fetch subscriber group list
                subsGroupList = groupInfoUtil.getSubsGroupListPaginated(corpContactDTO.getMdn(),
                        corpProfile.getMaxMemPerCorpGroup(), corpContactDTO.getFetchSize(), corpContactDTO.getNextToken(),
                        xdmsHome, true, persisterTxn);
            } else {
                subsGroupList = groupInfoUtil.getSubsGroupList(corpContactDTO.getMdn(),
                        corpProfile.getMaxMemPerCorpGroup(), xdmsHome, true, persisterTxn);
            }
            Collection<KnCorpGroupInfoPersistDTO> filteredGroupList = new ArrayList<>();
            if (corpContactDTO.getClientType() != CLIENT_TYPE_WCSR) {
                filteredGroupList = subsGroupList.stream()
                        .filter(grpDto -> grpDto.getGroupCreatedBy() != CREATED_BY.ABDG.value()).collect(Collectors.toList());
                //removing all group where mdn exists as external user
                knLogger.debug(methodName," subsGroupList:",subsGroupList);
                List<KnCorpGroupInfoPersistDTO> externalUserGroupList = subsGroupList.stream()
                        .filter(grpDto -> ((grpDto.getGrpShared()==null||!grpDto.getGrpShared().equals(GROUP_SHARED_ENABLED))
                                && grpDto.getCorpId() != corpId)).collect(Collectors.toList());
                filteredGroupList.removeAll(externalUserGroupList);
                //remove the group not shared with corp
                List<Integer> dbGroupIds = filteredGroupList.stream().map(KnCorpGroupInfoPersistDTO::getGroupId).collect(Collectors.toList());
                Map<Integer, List<KnCorpSharedCorpInfo>> sharedCorpGroupInfo = groupInfoUtil.selectGroupSharedCorpInfoByGroupId(dbGroupIds, xdmsHome, true, persisterTxn);
                Map<Integer, List<Integer>> sharedMapGroupIds=new HashMap<>();
                Map<Integer, Integer> ownerMapGroupIds=new HashMap<>();
                if(sharedCorpGroupInfo!=null){
                    for(Integer grpId : sharedCorpGroupInfo.keySet()){
                        //shared corpIds for the group
                        List<Integer> shareCorpListIds = new ArrayList<>();
                        sharedCorpGroupInfo.get(grpId).forEach(item -> shareCorpListIds.add(item.getCorpId()));
                        sharedMapGroupIds.put(grpId, shareCorpListIds);
                        //own corpId for the group
                        ownerMapGroupIds.put(grpId,sharedCorpGroupInfo.get(grpId).get(0).getOwnerCorpId());
                    }
                }
                List<Integer> nonsharedGroupWithCorpId=new ArrayList<>();
                for(Integer groupIds:dbGroupIds){
                    List<Integer> SharedCorpIdList = sharedMapGroupIds.get(groupIds);
                    Integer OwnCorpIdList = ownerMapGroupIds.get(groupIds);
                    if(OwnCorpIdList!=null&&SharedCorpIdList!=null&&!(OwnCorpIdList.equals(corpId)|SharedCorpIdList.contains(corpId))){
                        //owner or shared group corp should not be added to this,if corp is same as requesting mdn{
                        nonsharedGroupWithCorpId.add(groupIds);
                    }
                }
                knLogger.debug(methodName," nonsharedGroupWithCorpId :",nonsharedGroupWithCorpId);
                for(Integer dbCorp:nonsharedGroupWithCorpId) {
                    filteredGroupList.removeIf(group->group.getGroupId()==dbCorp);
                }
                knLogger.debug(methodName," after removal filteredGroupList :",filteredGroupList);
            } else {
                filteredGroupList = subsGroupList;
            }

            Collection<Integer> groupIds = new ArrayList<>();
            if (!filteredGroupList.isEmpty()) {
                for (KnCorpGroupInfoPersistDTO groupInfo : filteredGroupList) {
                    groupIds.add(groupInfo.getGroupId());
                }
            }

            if (!groupIds.isEmpty()) {
                if (corpContactDTO.getClientType() != CLIENT_TYPE_WCSR) {
                    Collection<Integer> supervisorList = new ArrayList<Integer>();
                    supervisorList.add(INTER_OP);
                    supervisorList.add(DISPATCHER);
                    supervisorList.add(SUPERVISOR);
                    Map<Integer, Collection<KnCorpGroupMemberDTO>> groupSupervisorList = groupInfoUtil.getGrpSpecificSubsc(supervisorList, groupIds, xdmsHome, true, persisterTxn);
                    Set<String> mdnLists = new HashSet<String>();
                    if (groupSupervisorList != null && !groupSupervisorList.isEmpty()) {


                        for (Entry<Integer, Collection<KnCorpGroupMemberDTO>> entry : groupSupervisorList.entrySet()) {
                            Collection<KnCorpGroupMemberDTO> groupMemberDTO = entry.getValue();
                            for (KnCorpGroupMemberDTO memberDTO : groupMemberDTO) {
                                mdnLists.add(memberDTO.getMdn());
                            }
                        }
                    }
                    Map<String, String> subscNameList = contactInfoUtil.getSubscribersName(mdnLists, xdmsHome, true, persisterTxn);
                    for (KnCorpGroupInfoPersistDTO grpPersistDTO : filteredGroupList) {
                        if (groupSupervisorList != null) {
                            Collection<KnCorpGroupMemberDTO> supervisorMemberList = groupSupervisorList.get(grpPersistDTO.getGroupId());
                            if (supervisorMemberList != null) {
                                for (KnCorpGroupMemberDTO contactDTO : supervisorMemberList) {
                                    String mdn = contactDTO.getMdn();
                                    if (subscNameList.containsKey(mdn)) {
                                        contactDTO.setName(subscNameList.get(mdn));
                                    }
                                }
                            }
                            grpPersistDTO.setGroupSupervisor(supervisorMemberList);
                        }
                        //For Group Sharing Feature
                        Integer groupShared = grpPersistDTO.getGrpShared();
                        if (groupShared != null && groupShared == GROUP_SHARING_ENABLE_INDICATOR) {
                            List<KnCorpSharedCorpInfo> corpSharedCorpInfos = groupInfoUtil.selectGroupSharedCorpInfo(corpId, grpPersistDTO.getGroupId(), xdmsHome, true, persisterTxn);
                            if (corpSharedCorpInfos != null && !corpSharedCorpInfos.isEmpty()) {
                                //groupInfoUtil.populateGroupMemProperties(corpSharedCorpInfos);
                                //   knLogger.info(methodName, "sharedCorpInfoList - ", corpSharedCorpInfos);
                                Set<Integer> sharedIntCorpIds = corpSharedCorpInfos.stream().map(KnCorpSharedCorpInfo::getCorpId).collect(Collectors.toSet());
                                knLogger.info(methodName, "converting shared int corpids to external corpids", sharedIntCorpIds);
                                Map<String, Integer> extIntCorpIDMap = commonInfoUtil.getCorpIdMap(null, sharedIntCorpIds, true, persisterTxn);
                                corpSharedCorpInfos.forEach(info -> {
                                    String sharedExtCorpId = extIntCorpIDMap.entrySet().stream().
                                            filter(e -> e.getValue().intValue() == info.getCorpId()).
                                            map(Entry::getKey).
                                            findFirst().
                                            get();
                                    info.setExtCorpId(sharedExtCorpId);
                                });
                                knLogger.debug(methodName, "after converting shared int corpids to external corpids", corpSharedCorpInfos);
                                grpPersistDTO.setCorpSharedCorpInfoList(corpSharedCorpInfos);
                                grpPersistDTO.setGrpOwnerCorpId(String.valueOf(corpId));
                                grpPersistDTO.setGrpOwnerExtCorpId(corpProfile.getExtCorpId().trim());
                            }
                        }
                    }
                } else {
                    for (KnCorpGroupInfoPersistDTO grpPersistDTO : filteredGroupList) {
                        //For Group Sharing Feature
                        Integer groupShared = grpPersistDTO.getGrpShared();
                        if(groupShared != null && groupShared == GROUP_SHARING_ENABLE_INDICATOR){
                            List<KnCorpSharedCorpInfo> corpSharedCorpInfos = groupInfoUtil.selectGroupSharedCorpInfo(corpId, grpPersistDTO.getGroupId(), xdmsHome, true, persisterTxn);
                            if(corpSharedCorpInfos != null && !corpSharedCorpInfos.isEmpty()){
                                //groupInfoUtil.populateGroupMemProperties(corpSharedCorpInfos);
                                //   knLogger.info(methodName, "sharedCorpInfoList - ", corpSharedCorpInfos);
                                Set<Integer> sharedIntCorpIds = corpSharedCorpInfos.stream().map(KnCorpSharedCorpInfo::getCorpId).collect(Collectors.toSet());
                                knLogger.info(methodName, "converting shared int corpids to external corpids", sharedIntCorpIds);
                                Map<String, Integer> extIntCorpIDMap = commonInfoUtil.getCorpIdMap(null, sharedIntCorpIds, true, persisterTxn);
                                corpSharedCorpInfos.forEach(info -> {
                                    String sharedExtCorpId = extIntCorpIDMap.entrySet().stream().
                                            filter(e -> e.getValue().intValue() == info.getCorpId()).
                                            map(Entry::getKey).
                                            findFirst().
                                            get();
                                    info.setExtCorpId(sharedExtCorpId);
                                });
                                knLogger.debug(methodName, "after converting shared int corpids to external corpids", corpSharedCorpInfos);
                                grpPersistDTO.setCorpSharedCorpInfoList(corpSharedCorpInfos);
                                grpPersistDTO.setGrpOwnerCorpId(String.valueOf(corpId));
                                grpPersistDTO.setGrpOwnerExtCorpId(corpProfile.getExtCorpId().trim());
                            }
                        }
                    }
                }
            }

            Collection<KnCorpGroupInfoDTO> groupInfoList = new ArrayList<KnCorpGroupInfoDTO>(filteredGroupList.size());
            groupInfoList.addAll(filteredGroupList);
            respDto.setGroupList(groupInfoList);
            populate(respDto);
            if (responseDTO.getFailedDataList() != null && !responseDTO.getFailedDataList().isEmpty()) {
                respDto.setFailedDataList(responseDTO.getFailedDataList());
            }

        } catch (KnCorpBOException e) {
            knLogger.error(methodName, "KnCorpBOException occured while retrieving Group List - ", e);
            populate(respDto, e);

        } catch (Exception e) {
            knLogger.error(methodName, "Unexpected exception occured while retrieving Group List - ",
                    new KnException(KnErrorCodes.BOEntity.INTERNAL_ERROR, e.getMessage(), e));
            populate(respDto, e);

        }
        knLogger.debug(methodName, "EXIT : GroupList Response - ", respDto);
        knLogger.debug(methodName, "EXIT : GroupList Response - ", respDto.getGroupList());
        return respDto;
    }

    public KnCorpGroupListRespDTO getSubscriberLocWatcherGroupList(KnIPCorpContactDTO corpContactDTO, KnPersisterTxn persisterTxn) {
        String methodName = "getSubscriberLocWatcherGroupList(KnIPCorpContactDTO, KnPersisterTxn)";
        knLogger.info(methodName, "ENTRY : Input DTO Passed - ", corpContactDTO);
        KnCorpGroupListRespDTO respDto = new KnCorpGroupListRespDTO();
        try {

            String mdn = corpContactDTO.getMdn();
            knLogger.debug(methodName, "Fetch the SubsProfile profile if cached or fetch from the DB the details");
            KnSubsProfileDTO subscProfile = commonInfoUtil.getProfileDetails(mdn, PUBLIC_PROFILE,
                    false, persisterTxn);
            knLogger.debug(methodName, "Retrieved Subs Profile details - ", subscProfile);
            String xdmsHome = subscProfile.getXdmsHome();
            int corpId = subscProfile.getCorpId();
            corpContactDTO.setCorpId(corpId);
            Collection<KnCorpGroupInfoPersistDTO> subsGroupList = groupInfoUtil.getSubsGroupList(corpContactDTO, xdmsHome, true, persisterTxn);
            Collection<KnCorpGroupInfoDTO> groupInfoList = new ArrayList<KnCorpGroupInfoDTO>(subsGroupList.size());
            groupInfoList.addAll(subsGroupList);
            respDto.setGroupList(groupInfoList);
            populate(respDto);
        } catch (KnCorpBOException e) {
            knLogger.error(methodName, "KnCorpBOException occured while retrieving Group List - ", e);
            populate(respDto, e);
        } catch (Exception e) {
            knLogger.error(methodName, "Unexpected exception occured while retrieving Group List - ",
                    new KnException(KnErrorCodes.BOEntity.INTERNAL_ERROR, e.getMessage(), e));
            populate(respDto, e);
        }
        knLogger.debug(methodName, "EXIT : GroupList Response - ", respDto);
        knLogger.debug(methodName, "EXIT : GroupList Response - ", respDto.getGroupList());
        return respDto;
    }

    private KnCorpResponseDTO deleteGroupOperation(KnIPCorpGroupDTO groupInfoDTO, KnCorpInOutParamDTO corpInOutParamDTO,
                                                   String refId, String xdmsHome, int corpId, KnPersisterTxn persisterTxn) throws Exception {
        String methodName = "deleteGroupOperation(KnIPCorpGroupDTO ,String , KnPersisterTxn )";
        knLogger.info(methodName, "ENTRY : Input DTO Passed - ", groupInfoDTO);
        KnCorpResponseDTO respDto = new KnCorpResponseDTO();
        Map<String, KnOPDirChgDTO> etagMap = new HashMap<String, KnOPDirChgDTO>();
        int groupId = groupInfoDTO.getGroupId();
        LinkedList<String> groupMembers = groupInfoUtil.getGroupMemberList(groupId, xdmsHome, persisterTxn);
        //get the groupMdn from the memberList
        List<String> grpMdnList = contactInfoUtil.getGroupMdns(groupMembers, groupInfoDTO.getCorpId(), xdmsHome, persisterTxn);
        Collection<Integer> groupIdLst = new ArrayList<Integer>();
        groupIdLst.add(groupId);
        Map<Integer, Collection<String>> currentGroupMember = groupInfoUtil.selectGroupMemberListForGroupIds(groupIdLst, xdmsHome, persisterTxn);
        LinkedList<String> extGroupMemList = new LinkedList<String>();
        Collection<String> members = new ArrayList<String>();
        if (AREA_BASED_DYNAMIC_GROUP == groupInfoDTO.getClientType() && !groupMembers.isEmpty()) {
            Map<String, List<String>> profileBaseMdnMap = corpSubsProvInfoUtil.getMapOfProfileMdnByBaseMdn(new ArrayList<>(groupMembers), xdmsHome, persisterTxn);
            if (!profileBaseMdnMap.isEmpty()) {
                ArrayList<String> profileMdns = new ArrayList<>();
                profileBaseMdnMap.values().forEach(profileMdns::addAll);
                knLogger.debug(methodName, " fetched all the profile mdns ", KnGDPRTemplate.mdnList(profileMdns));
                members.addAll(profileMdns);
            }
        }
        if (currentGroupMember != null && !currentGroupMember.isEmpty()) {
            extGroupMemList.addAll(currentGroupMember.get(groupId));
            knLogger.debug(methodName, "Retrieved groupMemberdistList - ", KnGDPRTemplate.mdnList(groupMembers));

            if (groupMembers != null && !groupMembers.isEmpty()) {
                for (String mdn : groupMembers) {
                    extGroupMemList.remove(mdn);
                    members.add(mdn);
                }
//            etagMap = contactInfoUtil.updateSubscribersDirectory(members, etagMap, xdmsHome, persisterTxn);
            }
        }
        knLogger.debug(methodName," extGroupMemList :",KnGDPRTemplate.mdnList(extGroupMemList));
        if(!extGroupMemList.isEmpty()){
            groupMembers.addAll(extGroupMemList);
            members.addAll(extGroupMemList);
        }

        //checking for the MCX group type for disabling 27it of profileMDNs
        if (groupInfoDTO.getMcxGrpInd() == MCX_GROUP_INDICATOR) {
            Collection<Integer> groupIdList = new ArrayList<Integer>();
            groupIdList.add(groupId);
            int upmIdCount = commonInfoUtil.getUserPfofileIdCount(groupId, persisterTxn, xdmsHome);
            LinkedHashMap<Integer, LinkedList<String>> groupDiaptacherMap = groupInfoUtil.getGroupDispatcherSubscriber(groupIdList, DISPATCHER, xdmsHome, persisterTxn);
            if ((null != groupDiaptacherMap && !groupDiaptacherMap.isEmpty() && groupDiaptacherMap.size() != 0 && upmIdCount != 0)
                    || (null != groupDiaptacherMap && !groupDiaptacherMap.isEmpty() && groupDiaptacherMap.size() != 0)
                    || upmIdCount != 0) {
                //Getting profile mdn which are part of group.
                Set<String> profileMdnSet = commonInfoUtil.getProfileMdnList(groupId, persisterTxn, xdmsHome);
                if (null != profileMdnSet) {
                    groupMembers.addAll(profileMdnSet);
                }
            }
        }

        respDto.setDisabledDispatchMemList(groupMembers);
        if (groupInfoDTO.getGroupType() == DISPATCH_GROUP && groupInfoDTO.isContactPairing()) {
            Collection<Integer> groupIdList = new ArrayList<Integer>();
            groupIdList.add(groupId);
            LinkedHashMap<Integer, LinkedList<String>> groupDiaptacherMap = groupInfoUtil.getGroupDispatcherSubscriber(groupIdList, DISPATCHER, xdmsHome, persisterTxn);
            deAssignContact(groupMembers, groupDiaptacherMap.get(groupId), null, extGroupMemList, etagMap, xdmsHome, corpId, persisterTxn);
        }
        Map<Integer, Collection<String>> locWatcherSubscriberMap = getGroupLocWatcherSubscriber(groupIdLst, xdmsHome, persisterTxn);
        respDto.setRemovedLocWatcherList(locWatcherSubscriberMap.get(groupId));
        boolean isPreConfigGroup = groupInfoDTO.getIsPreConfiguredGroup() != null && groupInfoDTO.getIsPreConfiguredGroup() == ENABLED;
        if(isPreConfigGroup){
            knLogger.debug(methodName, "Retrieving mdnList in owned corp and shared corp if group is shared, " +
                    "whose activefs2 Preconfigured bit is enabled");
            List<String> preConfigGroupMdns = groupInfoUtil.getPreConfGrpCorpMem(groupInfoDTO.getGrpShared(), groupInfoDTO.getGroupId(),
                    corpId, xdmsHome, persisterTxn);
            members.addAll(preConfigGroupMdns);
            groupMembers.addAll(preConfigGroupMdns);
        }
        if (groupMembers != null && !groupMembers.isEmpty()) {
            etagMap = contactInfoUtil.updateSubscribersDirectory(members, etagMap, xdmsHome, persisterTxn);
        }
        etagMap = addDeletedMemberGroupDoc(etagMap, members, groupId, groupInfoDTO.getETag(),extGroupMemList,isPreConfigGroup);
        if (refId != null && grpMdnList != null) {
            for (String mdn : grpMdnList) {
                etagMap.remove(mdn);
            }
            //get the refernce id from the account info table.
            KnCorpGWLinkedAccountInfoDTO accountInfo = commonInfoUtil.getCorporateLinkedAccountInfo(refId, xdmsHome, persisterTxn);
            //update etag in the account info table
            //update etag
            Map<String, String> asyncInput = new HashMap<>();
            asyncInput.put(KnDbSyncFwConstants.PTTSERVER_ID, xdmsHome);
            asyncInput.put(KnDbSyncFwConstants.NNI_REF_ID, accountInfo.getNniRefId());
            knLogger.debug(methodName, " Async inputs", asyncInput);
            KnSqlJobCollector collector = KnSqlJobCollector.getInstance();
            int serviceType = KnDbSyncFwConstants.EXECUTOR.ETAG_UPDATE_NNI.value();
            collector.collect(serviceType, asyncInput);
        }
        List<Integer> grupIdLst = new ArrayList<Integer>(1);
        grupIdLst.add(groupInfoDTO.getGroupId());

        Collection<KnCorpAddlTGInfoDTO> subsAddlTGList = groupInfoUtil.getSubsAddlDetails(grupIdLst, xdmsHome, persisterTxn);
        if (subsAddlTGList != null && !subsAddlTGList.isEmpty()) {
            Collection<String> mdnList = subsAddlTGList.stream().map(KnCorpAddlTGInfoDTO::getMdn).distinct().collect(Collectors.toList());
            groupInfoUtil.deleteSubsAddlTGList(subsAddlTGList, xdmsHome, persisterTxn);
            /*groupInfoUtil.deleteSubsAddlTalkGroupDoc(mdnList, xdmsHome, persisterTxn);
            for(String mdn : mdnList){
                etagMap = commonInfoUtil.formMdnAddlTGListDeleteNotification(mdn, etagMap);
            }*/
            etagMap = groupInfoUtil.updateAddlTalkGroupImpactedTables(xdmsHome, mdnList, persisterTxn, etagMap);
            knLogger.debug(methodName, "etagMap AddlTG - ", KnGDPRTemplate.mapKeyMdn(etagMap));
            Map<Integer, Integer> groupCorpIdMap = new HashMap<>();
            if (subsAddlTGList != null && !subsAddlTGList.isEmpty()) {
                groupCorpIdMap = groupInfoUtil.getGroupCorpIdMap((List<KnCorpAddlTGInfoDTO>) subsAddlTGList, xdmsHome, persisterTxn);
            }
            knLogger.debug(methodName, "groupCorpId - ", groupCorpIdMap);
            if (null != groupCorpIdMap && !groupCorpIdMap.isEmpty()) {
                etagMap = formXcapAddlTGDiffNotification(etagMap, null, null,
                        subsAddlTGList, groupCorpIdMap);
                knLogger.debug(methodName, "etagMap AddlTG -diff - ", KnGDPRTemplate.mapKeyMdn(etagMap));
            }
        }
        groupInfoUtil.cleanUpCampedGrp(grupIdLst, corpInOutParamDTO, xdmsHome, persisterTxn);
        corpUserProfileUtil.deleteProfileGroupInfoByGroupId(groupInfoDTO.getGroupId(),xdmsHome, persisterTxn);
        groupInfoUtil.deleteGroup(groupInfoDTO.getGroupId(), xdmsHome, persisterTxn);
        etagMap = commonInfoUtil.formTGSCDocumentNotification(corpInOutParamDTO, etagMap, xdmsHome, persisterTxn);
        if (etagMap != null && !etagMap.isEmpty()) {
            respDto.setChangeLogMap(etagMap);
        }
        groupInfoUtil.cleanUpTGSSGrp(grupIdLst, corpInOutParamDTO, xdmsHome, persisterTxn);
        etagMap = commonInfoUtil.formTGSSDocumentNotification(corpInOutParamDTO, etagMap, xdmsHome, persisterTxn);
        populate(respDto);
        return respDto;
    }

    private void assignContact(Collection<String> nonDispatcherSubscriber, Collection<String> dispatcherSubscriber,
                               Collection<KnCorpSubscriberDTO> externalContact, Collection<String> removedMdnsList,
                               int corpId, int maxContactPerSubsc, Map<String, KnOPDirChgDTO> etagMap, String xdmHome,
                               KnPersisterTxn persisterTxn) throws KnException {
        String methodName = "assignContact(Collection<String>,Collection<String>,int,int,Map<String, KnOPDirChgDTO> ,String, KnPersisterTxn)";
        knLogger.debug(methodName, "ENTRY : nonDispatcherSubscriber - ", nonDispatcherSubscriber == null ? nonDispatcherSubscriber : KnGDPRTemplate.mdnList(nonDispatcherSubscriber),
                " , dispatcherSubscriber - ", dispatcherSubscriber == null ? dispatcherSubscriber : KnGDPRTemplate.mdnList(dispatcherSubscriber), " , externalContact - ", externalContact);
//        KnPersisterTxn persisterTxn = null;
        try {
            /*persisterTxn = KnPersisterTxn.getPersisterTxn();
            persisterTxn.open();*/

            /*here if dispatcher will come as a added list and in remove list, then contact pairing will happen for the deleting dispatcher with the existing dispatcher.
            so this if else will restrict unnecessary contact pairing.*/

            if (removedMdnsList != null && !removedMdnsList.isEmpty()) {
                for (String mdn : removedMdnsList) {
                    dispatcherSubscriber.remove(mdn);
                }
            } /*else {
                removedMdnsList = new ArrayList<>();
            }*/
            knLogger.debug(methodName, "dispatcherSubscriber :", KnGDPRTemplate.mdnList(dispatcherSubscriber));
            Collection<String> completeMdnList = new ArrayList<String>();
            completeMdnList.addAll(nonDispatcherSubscriber);
            completeMdnList.addAll(dispatcherSubscriber);
            knLogger.debug(methodName, "completeMdnList :", KnGDPRTemplate.mdnList(completeMdnList));
            Map<String, KnCorpSubscriberDTO> contDetailsMap = contactInfoUtil.getSubsribersCorporateDetails(completeMdnList, xdmHome, persisterTxn);
            List<String> ownedCorpGroupmembers = contDetailsMap.entrySet().stream()
                    .filter(e -> e.getValue().getCorpId() == corpId).map(m -> m.getKey()).collect(Collectors.toList());
            List<String> sharedCorpGroupmembers = completeMdnList.stream()
                    .filter(element -> !ownedCorpGroupmembers.contains(element))
                    .collect(Collectors.toList());
            knLogger.debug(methodName," ownedCorpGroupmembers :",KnGDPRTemplate.mdnList(ownedCorpGroupmembers) ," sharedCorpGroupmembers :",KnGDPRTemplate.mdnList(sharedCorpGroupmembers));
            if(!ownedCorpGroupmembers.isEmpty()){
                //owned group request
                completeMdnList.removeAll(sharedCorpGroupmembers);
                nonDispatcherSubscriber.removeAll(sharedCorpGroupmembers);
                dispatcherSubscriber.removeAll(sharedCorpGroupmembers);
            }else if(!sharedCorpGroupmembers.isEmpty()){
                //shared group request
                completeMdnList.removeAll(ownedCorpGroupmembers);
                nonDispatcherSubscriber.removeAll(ownedCorpGroupmembers);
                dispatcherSubscriber.removeAll(ownedCorpGroupmembers);
            }

            for (Entry<String, KnCorpSubscriberDTO> entry : contDetailsMap.entrySet()){
                if(entry.getValue().getUserProfileIndex() != null &&
                        entry.getValue().getUserProfileIndex() != 0){
                    completeMdnList.remove(entry.getKey());
                }

            }


            for (Entry<String, KnCorpSubscriberDTO> entry : contDetailsMap.entrySet()){
                if(entry.getValue().getUserProfileIndex() != null &&
                        entry.getValue().getUserProfileIndex() != 0){
                    completeMdnList.remove(entry.getKey());
                }

            }

            knLogger.debug(methodName," completeMdnList :",KnGDPRTemplate.mdnList(completeMdnList)
                    ," nonDispatcherSubscriber :",KnGDPRTemplate.mdnList(nonDispatcherSubscriber)
                    ," dispatcherSubscriber :",KnGDPRTemplate.mdnList(dispatcherSubscriber));

            //the non dispatcher members(other member) list will be the contacts for the dispatcher
            Collection<KnCorpSubscriberDTO> subscriberInfo = contactInfoUtil.getSubscribersInfo(completeMdnList, xdmHome, persisterTxn);
            Map<String, KnCorpSubscriberDTO> subsMap = subscriberInfo.stream().collect(Collectors.toMap(KnCorpSubscriberDTO::getMdn, exist -> exist));
            Collection<KnCorpSubscriberDTO> dispatcherContactMdnList = new ArrayList<KnCorpSubscriberDTO>();
            Map<String, KnCorpSubscriberDTO> subscDetails = contactInfoUtil.getPoCSubscriberExistMap(nonDispatcherSubscriber, xdmHome, persisterTxn);
            for (String mdn : nonDispatcherSubscriber) {
                KnCorpSubscriberDTO subscDTO = new KnCorpSubscriberDTO();
                subscDTO.setMdn(mdn);
                subscDTO.setCorpId(corpId);
                if (subscDetails.get(mdn) != null) {
                    subscDTO.setName(subscDetails.get(mdn).getName());
                    subscDTO.setClientType(subscDetails.get(mdn).getClientType());
                    subscDTO.setContact_type(INTERNAL_SUBSC_CLIENT_TYPE);
                    subscDTO.setUa(KnGeneralUtil.getUA(subscDetails.get(mdn).getUserAgent(), subscDetails.get(mdn).getClientPVmajorVer()));
                    subscDTO.setSubsActiveFS2(subscDetails.get(mdn).getSubsActiveFS2());
                }
                dispatcherContactMdnList.add(subscDTO);
            }
            Collection<KnCorpSubscriberDTO> dispatcherDTOList = new ArrayList<KnCorpSubscriberDTO>();
            for (String dispatcher : dispatcherSubscriber) {
                KnCorpSubscriberDTO subsc = new KnCorpSubscriberDTO();
                subsc.setMdn(dispatcher);
                subsc.setCorpId(corpId);
                subsc.setClientType(KnConstants.DISPATCH_CLIENT);
                subsc.setContact_type(INTERNAL_SUBSC_CLIENT_TYPE);
                if (subsMap != null && subsMap.get(dispatcher) != null) {
                    subsc.setSubsActiveFS2(subsMap.get(dispatcher).getSubsActiveFS2());
                }
                dispatcherDTOList.add(subsc);
            }
            //dispatcherContactMdnList.addAll(nonDispatcherSubscriber);
            // for (KnCorpSubscriberDTO subsc : externalContact) {
            dispatcherContactMdnList.addAll(externalContact);
            dispatcherContactMdnList.addAll(dispatcherDTOList);
            knLogger.debug(methodName, "dispatcherContactMdnList :", dispatcherContactMdnList);
            //}
            //Retrieve all the private List for the subscribers
            Map<String, Integer> subscPvtListIdMap = contactInfoUtil.getSubscribersPrivateListId(completeMdnList, xdmHome, persisterTxn);
            Map<String, Collection<KnCorpSubscriberDTO>> membersNewContactList = new HashMap<String, Collection<KnCorpSubscriberDTO>>();
            Collection<String> noPrivateContactList = new ArrayList<String>();
            for (Entry<String, Integer> entry : subscPvtListIdMap.entrySet()) {
                Integer subscPvtListId = entry.getValue();
                String mdn = entry.getKey();
                if (subscPvtListId == NO_PRIVATE_LIST_ID) {
                    noPrivateContactList.add(mdn);
                }
                //Here we are creating members contact list.
                if (!dispatcherSubscriber.contains(mdn)) {
                    membersNewContactList.put(mdn, dispatcherDTOList);
                }
            }
            knLogger.debug(methodName, "membersNewContactList :", KnGDPRTemplate.mapKeyMdn(membersNewContactList));
            //get the subscribers private list members
            Map<String, Collection<KnCorpSubscriberDTO>> subscPvtContactList = contactInfoUtil.getSubscribersPrivateList(subscPvtListIdMap, xdmHome, persisterTxn);
            Map<String, Collection<KnCorpSubscriberDTO>> dispatcherPvtContactList = new HashMap<String, Collection<KnCorpSubscriberDTO>>();
            //removing the dispatcher into another map
            for (String dispatcher : dispatcherSubscriber) {
                Collection<KnCorpSubscriberDTO> subscList = subscPvtContactList.get(dispatcher);
                if (subscList == null) {
                    subscList = new ArrayList<KnCorpSubscriberDTO>();
                }
                dispatcherPvtContactList.put(dispatcher, subscList);
                subscPvtContactList.remove(dispatcher);
            }
            //knLogger.debug(methodName, "dispatcherPvtContactList :", dispatcherPvtContactList);
            //knLogger.debug(methodName, "subscPvtContactList :", subscPvtContactList);
            //get the members to be added in the corplistmember for the dispatcher
            Map<String, Collection<KnCorpSubscriberDTO>> memberOfDispatcherList = commonInfoUtil.filterMemberToBeAddedToPrivateList(dispatcherPvtContactList, dispatcherContactMdnList);
            knLogger.debug(methodName, "memberOfDispatcherList :", KnGDPRTemplate.mapKeyMdn(memberOfDispatcherList));
            //get the dispatcher to be added to subscriber
            Map<String, Collection<KnCorpSubscriberDTO>> memberOfPrivateList = commonInfoUtil.filterMemberToBeAddedToPrivateList(subscPvtContactList, dispatcherDTOList);
            knLogger.debug(methodName, "memberOfPrivateList :", KnGDPRTemplate.mapKeyMdn(memberOfPrivateList));
            //gt the dispatcher contact list
            Map<String, Collection<KnCorpSubscriberDTO>> subscContactList = contactInfoUtil.getSubscribersContactDeatilsList(completeMdnList, xdmHome, persisterTxn);
            Map<String, Collection<KnCorpSubscriberDTO>> dispatcherContactList = new HashMap<String, Collection<KnCorpSubscriberDTO>>();
            for (String dispatcher : dispatcherSubscriber) {
                Collection<KnCorpSubscriberDTO> mdnList = subscContactList.get(dispatcher);
                if (mdnList == null) {
                    mdnList = new ArrayList<KnCorpSubscriberDTO>();
                }
                dispatcherContactList.put(dispatcher, mdnList);
                subscContactList.remove(dispatcher);
            }
            knLogger.debug(methodName, "dispatcherContactList :", KnGDPRTemplate.mapKeyMdn(dispatcherContactList));
            knLogger.debug(methodName, "subscContactList :", KnGDPRTemplate.mapKeyMdn(subscContactList));
            //get the members to be added to the corpcontactlist table
            Map<String, Collection<KnCorpSubscriberDTO>> memberOfDispatcherContactList = commonInfoUtil.filterMemberToBeAddedToPrivateList(dispatcherContactList, dispatcherContactMdnList);
            knLogger.debug(methodName, "memberOfDispatcherContactList :", KnGDPRTemplate.mapKeyMdn(memberOfDispatcherContactList));
            Map<String, Collection<KnCorpSubscriberDTO>> memberOfNonDispatcherContactList = commonInfoUtil.filterMemberForSubscriber(subscContactList, membersNewContactList);
            knLogger.debug(methodName, "memberOfNonDispatcherContactList :", KnGDPRTemplate.mapKeyMdn(memberOfNonDispatcherContactList));
            //retrieve the contact counts for the subscriber
            Map<String, String> susbcriberContactCountMap = contactInfoUtil.getAllSubscriberContactCount(completeMdnList, xdmHome, false, persisterTxn);
            knLogger.debug(methodName, "susbcriberContactCountMap :", KnGDPRTemplate.mdnMap(susbcriberContactCountMap));
            /* KnIPCorpContactDTO inputDTO = new KnIPCorpContactDTO();
           inputDTO.setEntityId(KnEntityTypes.CORP_GROUP_MANAGER);
           inputDTO.setOperationType(KnOperationTypes.ASSIGN_CONTACT);
           inputDTO.setProfile(KnProfileTypes.CORP_PROFILE);
           KnContactDetailsPersistDTO contactDetailsPersistDTO = new KnContactDetailsPersistDTO();
           contactDetailsPersistDTO.setInputDTO(inputDTO); */
            Map<String, Integer> susbcAddContactCountMap = new HashMap<String, Integer>();
            for (String mdn : completeMdnList) {
                int count = 0;
                String subscCount = susbcriberContactCountMap.get(mdn);
                if (subscCount == null || subscCount.isEmpty()) {
                    susbcriberContactCountMap.put(mdn, "0");
                }
                Collection<KnCorpSubscriberDTO> mdnList = memberOfDispatcherContactList.get(mdn);
                if (mdnList != null && !mdnList.isEmpty()) {
                    count = mdnList.size();
                } else {
                    Collection<KnCorpSubscriberDTO> memberMdns = memberOfNonDispatcherContactList.get(mdn);
                    if (memberMdns != null && !memberMdns.isEmpty()) {
                        count = memberMdns.size();
                    }
                }
                susbcAddContactCountMap.put(mdn, count);
            }
            knLogger.debug(methodName, "susbcAddContactCountMap :", KnGDPRTemplate.mapKeyMdn(susbcAddContactCountMap));
            for (Entry<String, String> entry : susbcriberContactCountMap.entrySet()) {
                String susbcriberContactCount = entry.getValue();
                String mdn = entry.getKey();
                int currentCount = Integer.valueOf(susbcriberContactCount);
                int addCount = susbcAddContactCountMap.get(mdn);
                if ((addCount + currentCount) > maxContactPerSubsc) {
                    susbcAddContactCountMap.remove(mdn);
                    noPrivateContactList.remove(mdn);
                    subscPvtContactList.remove(mdn);
                    dispatcherContactList.remove(mdn);
                    memberOfPrivateList.remove(mdn);
                    memberOfDispatcherContactList.remove(mdn);
                    memberOfDispatcherList.remove(mdn);
                    memberOfNonDispatcherContactList.remove(mdn);
                }
            }
            for (String mdn : noPrivateContactList) {
                int privateListId = 0;
                KnCorpSublistDTO corpSublist = new KnCorpSublistDTO();
                //insert into the DG.CorpListInfo table and DG.POCSubscribers table
                corpSublist.setCorpId(corpId);
                corpSublist.setSublistName((PRIVATE_LIST_NAME) + mdn);
                corpSublist.setSublistType(SUBLIST_TYPE_PRIVATE_CONTACTLIST);
                corpSublist.setDistributionPolicy(DIST_POLICY_PRIVATE_CONTACTLIST);
                //create corpList entry
                //KnGenInfoUtil genInfoUtil = KnGenInfoUtil.getInstance();
                privateListId = genInfoUtil.retrieveIdForTable(CORP_LIST_TABLE, xdmHome, CORP_LIST_TABLE_PK, false, DUAL_DATA_STORE);
                corpSublist.setSublistId(privateListId);
                sublistInfoUtil.createSubListDetails(null, corpSublist, xdmHome, persisterTxn);
                KnIPCorpSublistSubscDistDTO distDto = new KnIPCorpSublistSubscDistDTO();
                Collection<String> mdnList = new ArrayList<String>();
                Collection<Integer> subliListIds = new ArrayList<Integer>();
                mdnList.add(mdn);
                subliListIds.add(privateListId);
                distDto.setMdnList(mdnList);
                distDto.setSublistIds(subliListIds);
                contactInfoUtil.pushSublistListToSubscriberList(distDto, xdmHome, persisterTxn);
                contactInfoUtil.updateSubscrinberCorpListId(mdn, corpSublist, xdmHome, persisterTxn);
                subscPvtListIdMap.put(mdn, privateListId);
            }
            Map<Integer, Collection<KnCorpSubscriberDTO>> listMemberMap = new HashMap<Integer, Collection<KnCorpSubscriberDTO>>();
            for (String mdn : subscPvtContactList.keySet()) {
                Collection<KnCorpSubscriberDTO> memList = memberOfPrivateList.get(mdn);
                if (memList != null && !memList.isEmpty()) {
                    listMemberMap.put(subscPvtListIdMap.get(mdn), memList);
                }
            }
            for (String mdn : dispatcherContactList.keySet()) {
                Collection<KnCorpSubscriberDTO> memberList = memberOfDispatcherList.get(mdn);
                if (memberList != null && !memberList.isEmpty()) {
                    listMemberMap.put(subscPvtListIdMap.get(mdn), memberList);
                }
            }
            //disptcaher private list also updated with other mememembers
            sublistInfoUtil.insertCorplistMembers(listMemberMap, xdmHome, persisterTxn);
            //update the corpcontactlist table
            Map<String, Collection<KnCorpSubscriberDTO>> completeContactListMap = new HashMap<String, Collection<KnCorpSubscriberDTO>>();
            completeContactListMap.putAll(memberOfNonDispatcherContactList);
            completeContactListMap.putAll(memberOfDispatcherContactList);
            contactInfoUtil.insertCorpContactListMembers(completeContactListMap, xdmHome, persisterTxn);
            contactInfoUtil.updateSubscribersContactCount(completeContactListMap.keySet(), maxContactPerSubsc, xdmHome, persisterTxn);
            Map<String, KnOPDirChgDTO> etagMapData = contactInfoUtil.updateSubcribersResourceListIndexDoc(completeContactListMap.keySet(), xdmHome, null, persisterTxn);
            if (etagMapData != null && !etagMapData.isEmpty()) {
                for (String mdn : etagMapData.keySet()) {
                    KnOPDirChgDTO dirChgDto = etagMap.get(mdn);
                    if (dirChgDto != null) {
                        Collection<KnOPDocChgDTO> documents = dirChgDto.getDocChgDTO();
//                        KnOPDocChgDTO doc = new KnOPDocChgDTO();
                        Collection<KnOPDocChgDTO> docs = etagMapData.get(mdn).getDocChgDTO();
                        if (docs != null && !docs.isEmpty()) {
                            documents.addAll(etagMapData.get(mdn).getDocChgDTO());
                        }
                        dirChgDto.setDocChgDTO(documents);
                        etagMap.put(mdn, dirChgDto);
                    }
                }
            }

            completeContactListMap.forEach((MDN, contactListDTO) -> {
                contactListDTO.forEach(subsc -> {
                    subscriberInfo.forEach(corpSubs -> {
                        if (subsc.getMdn().equals(corpSubs.getMdn())) {
                            subsc.setName(corpSubs.getName());
                            subsc.setUa(KnGeneralUtil.getUA(corpSubs.getUserAgent(), corpSubs.getClientPVmajorVer()));
                        }
                    });
                });
            });
            knLogger.info(methodName, "ENTRY : completeContactListMap0000 - ", KnGDPRTemplate.mapKeyMdn(completeContactListMap));
            formXcapDiffNotification(etagMap, completeContactListMap, null, null, null, null, null, null, null, null, null, null);
        } catch (KnCorpBOException e) {
            knLogger.error(methodName, "KnCorpBOException occured while assignContact - ", e);
            throw e;

        } catch (Exception e) {
            knLogger.error(methodName, "Unexpected exception occured while assignContact - ",
                    new KnException(KnErrorCodes.BOEntity.INTERNAL_ERROR, e.getMessage(), e));
            throw new KnException(KnErrorCodes.BOEntity.INTERNAL_ERROR, e.getMessage(), e);

        }
        knLogger.debug(methodName, "EXIT :");
    }

    private void deAssignContact(LinkedList<String> requestMDN, LinkedList<String> dispatcherSubscriber,
                                 Collection<KnCorpSubscriberDTO> groupPrivateList, LinkedList<String> extMemList,
                                 Map<String, KnOPDirChgDTO> etagMap, String xdmHome, int corpId, KnPersisterTxn persisterTxn) throws KnException {
        String methodName = "deAssignContact(Collection<String>,Collection<String>, Map<String, KnOPDirChgDTO>,String ,KnPersisterTxn)";
        knLogger.info(methodName, "ENTRY : requestMDN - ",requestMDN == null ? requestMDN : KnGDPRTemplate.mdnList(requestMDN),
                " , dispatcherSubscriber - ", dispatcherSubscriber == null ? dispatcherSubscriber :KnGDPRTemplate.mdnList(dispatcherSubscriber),
                " , extMemList ", extMemList == null ? extMemList : KnGDPRTemplate.mdnList(extMemList) , " , groupPrivateList ", groupPrivateList);
        //KnPersisterTxn persisterTxn = null;
        Collection<String> finalFailedRemovedContacts = new ArrayList<>();
        try {
            /* persisterTxn = KnPersisterTxn.getPersisterTxn();
            persisterTxn.open();*/

            if (dispatcherSubscriber == null) {
                dispatcherSubscriber = new LinkedList<>();
            }
            // Here we are differentiating dispatch and non-dispatch member as per request.
            LinkedList<String> dispatchMdnListAsPerRequest = new LinkedList<String>();
            LinkedList<String> nonDispatchMdnListPerRequest = new LinkedList<String>();
            for (String mdn : requestMDN) {
                if (dispatcherSubscriber.contains(mdn)) {
                    dispatchMdnListAsPerRequest.add(mdn);
                } else {
                    nonDispatchMdnListPerRequest.add(mdn);
                }
            }
            knLogger.debug(methodName, "dispatchMdnListAsPerRequest :", KnGDPRTemplate.mdnList(dispatchMdnListAsPerRequest));
            knLogger.debug(methodName, "nonDispatchMdnListAsPerRequest :", KnGDPRTemplate.mdnList(nonDispatchMdnListPerRequest));

            /*if groupPrivateList == null then it will be a deleteGroup call else modifyGroup call.
             in else path we are creating a nonDispatchMdnListInDB that will not include the nonDispatchMember coming as per Request.
             and existingGroupMemberInDB contains all the groupPrivateList Member.
            here we are putting existing db member to existingGroupMemberInDB list for removal of contact pairing for multiple dispatcher changes.*/

            LinkedList<String> existingGroupMemberInDB = new LinkedList<>();
            LinkedList<String> nonDispatchMdnListInDB = new LinkedList<String>();
            if (groupPrivateList == null || groupPrivateList.isEmpty()) {
                existingGroupMemberInDB.addAll(requestMDN);
                existingGroupMemberInDB.addAll(extMemList);
            } else {
                for (KnCorpSubscriberDTO dbMDN : groupPrivateList) {
                    existingGroupMemberInDB.add(dbMDN.getMdn());
                    if (!dispatcherSubscriber.contains(dbMDN.getMdn()) && !nonDispatchMdnListPerRequest.contains(dbMDN.getMdn())) {
                        nonDispatchMdnListInDB.add(dbMDN.getMdn());
                    }
                }
            }
            knLogger.debug(methodName, "nonDispatchMdnListInDB :", KnGDPRTemplate.mdnList(nonDispatchMdnListInDB));
            knLogger.debug(methodName, "existingGroupMemberInDB :", KnGDPRTemplate.mdnList(existingGroupMemberInDB));

            Set<String> completeMdnList = new HashSet<String>();
            // completeMdnList contains all the existing group Members.
            completeMdnList.addAll(dispatchMdnListAsPerRequest);
            completeMdnList.addAll(nonDispatchMdnListPerRequest);
            completeMdnList.addAll(dispatcherSubscriber);
            completeMdnList.addAll(existingGroupMemberInDB);
            knLogger.debug(methodName, "completeMdnList :",KnGDPRTemplate.mdnSet(completeMdnList));
            //Retrieve all the private List for the subscribers
            Map<String, Integer> subscPvtListIdMap = contactInfoUtil.getSubscribersPrivateListId(completeMdnList, xdmHome, persisterTxn);
            knLogger.debug(methodName, "subscPvtListIdMap :", KnGDPRTemplate.mapKeyMdn(subscPvtListIdMap));
            Map<Integer, Collection<String>> deletedMemberMap = new HashMap<Integer, Collection<String>>();
            LinkedHashMap<String, LinkedList<String>> deletedContactListMap = new LinkedHashMap<String, LinkedList<String>>();
            LinkedList<String> groupMembers = new LinkedList<String>();
            groupMembers.addAll(requestMDN);
            if (extMemList != null) {
                groupMembers.addAll(extMemList);
            }
            /*here in this 1st iteration, first we are creating a deletedContactListMap for dispatcherSubscriber by putting requestMDN.
            So that all the requestMDN will get deleted from the dispatchers contact list.*/
            for (String mdn : dispatcherSubscriber) {
                int privateListId = subscPvtListIdMap.get(mdn);
                if (privateListId != 0) {
                    deletedMemberMap.put(privateListId, groupMembers);
                }
                deletedContactListMap.put(mdn, groupMembers);
            }
            knLogger.debug(methodName, "deletedMemberMap1 :", KnGDPRTemplate.mapMdnAsValue(deletedMemberMap));
            knLogger.debug(methodName, "deletedContactListMap1 :", KnGDPRTemplate.mapKeyMdn(deletedContactListMap));
            /*here in 2nd iteration, we are creating a deletedContactListMap for  requestMDN by putting existingGroupMemberInDB mdn.
                    if same will appear for existing map the it will override with new key-value pair.*/
            for (String mdn : requestMDN) {
                int privateListId = subscPvtListIdMap.get(mdn);
                if (dispatchMdnListAsPerRequest.contains(mdn)) {
                    if (privateListId != 0) {
                        deletedMemberMap.put(privateListId, existingGroupMemberInDB);
                    }
                    deletedContactListMap.put(mdn, existingGroupMemberInDB);
                } else {
                    if (privateListId != 0) {
                        deletedMemberMap.put(privateListId, dispatcherSubscriber);
                    }
                    deletedContactListMap.put(mdn, dispatcherSubscriber);
                }
            }
            knLogger.debug(methodName, "deletedMemberMap2 :", KnGDPRTemplate.mapMdnAsValue(deletedMemberMap));
            knLogger.debug(methodName, "deletedContactListMap2 :", KnGDPRTemplate.mapKeyMdn(deletedContactListMap));

            /*here in 3rd iteration, we are creating a deletedContactListMap for nonDispatchMdnListInDB by putting dispatchMdnListAsPerRequest mdn.
                    if same will appear for existing map the it will override with new key-value pair.*/
            for (String mdn : nonDispatchMdnListInDB) {
                int privateListId = subscPvtListIdMap.get(mdn);
                if (privateListId != 0) {
                    deletedMemberMap.put(privateListId, dispatchMdnListAsPerRequest);
                }
                deletedContactListMap.put(mdn, dispatchMdnListAsPerRequest);
            }

            knLogger.debug(methodName, "deletedMemberMap3 :", KnGDPRTemplate.mapMdnAsValue(deletedMemberMap));
            knLogger.debug(methodName, "deletedContactListMap3 :", KnGDPRTemplate.mapKeyMdn(deletedContactListMap));
            sublistInfoUtil.deleteMembersFromAllSublist(deletedMemberMap, xdmHome, persisterTxn);
            LinkedHashMap<String, LinkedList<Integer>> delContactStatus = contactInfoUtil.deleteMembersFromCorpContactList(deletedContactListMap, xdmHome, persisterTxn);
            contactInfoUtil.updateSubscribersContactCount(completeMdnList, MAX_LIMIT_VALIDATION_NOT_REQUIRED, xdmHome, persisterTxn);
            Map<String, KnOPDirChgDTO> etagMapData = contactInfoUtil.updateSubcribersResourceListIndexDoc(completeMdnList, xdmHome, null, persisterTxn);
            if (etagMapData != null && !etagMapData.isEmpty()) {
                for (Entry<String, KnOPDirChgDTO> entry : etagMapData.entrySet()) {
                    String mdn = entry.getKey();
                    KnOPDirChgDTO dirChangeDTO = entry.getValue();
                    KnOPDirChgDTO dirChgDto = null;
                    if (etagMap == null) {
                        etagMap = new HashMap<String, KnOPDirChgDTO>();
                    }
                    dirChgDto = etagMap.get(mdn);
                    if (dirChgDto != null) {
                        Collection<KnOPDocChgDTO> documents = dirChgDto.getDocChgDTO();
                        Collection<KnOPDocChgDTO> docs = dirChangeDTO.getDocChgDTO();
                        if (docs != null && !docs.isEmpty()) {
                            if (documents == null) {
                                documents = new ArrayList<KnOPDocChgDTO>();
                            }
                            documents.addAll(dirChangeDTO.getDocChgDTO());
                        }
                        dirChgDto.setDocChgDTO(documents);
                        etagMap.put(mdn, dirChgDto);
                    } else {
                        etagMap.put(mdn, dirChangeDTO);
                    }
                }
            }
            formXcapDiffNotification(etagMap, null, deletedContactListMap,
                    null, null, null, null, null,
                    null, delContactStatus, null, null);
            Map<String, Collection<String>> actualDeletedContactMap = getActualDeletedContacts(deletedContactListMap, delContactStatus);
            if (actualDeletedContactMap != null && !actualDeletedContactMap.isEmpty()) {
                Map<String, Collection<String>> emergUserDestMap = corpSubsProvInfoUtil.getEmergUserDestMap(actualDeletedContactMap.keySet(),
                        xdmHome, persisterTxn);
                knLogger.debug(methodName, "emergUserDestMap-- ", KnGDPRTemplate.mapKeyValueListMdn(emergUserDestMap));
                Map<String, Collection<String>> failurePairingMap = new HashMap<>();
                if (emergUserDestMap != null && !emergUserDestMap.isEmpty()) {
                    emergUserDestMap.forEach((emergUser, emergDestinations) -> {
                        Collection<String> mappedDestination = new ArrayList<>();
                        Collection<String> removedContacts = actualDeletedContactMap.get(emergUser);
                        mappedDestination.addAll(emergDestinations.stream().filter(removedContacts::contains).collect(Collectors.toList()));
                        finalFailedRemovedContacts.addAll(mappedDestination);
                        if (!mappedDestination.isEmpty()) failurePairingMap.put(emergUser, mappedDestination);
                    });
                }
                knLogger.debug(methodName, "failurePairingMap-- ", KnGDPRTemplate.mapKeyValueListMdn(failurePairingMap));
                if (!failurePairingMap.isEmpty()) {
                    knLogger.error(methodName, "Emergency Destination Mapping Exists ");
                    throw new KnCorpBOValidationException(KnErrorCodes.Validator.EMERGENCY_DESTINATION_MAPPING_EXISTS_FOR_CONTACT,
                            "Emergency Destination Mapping Exists --", CORP_GROUP_MANAGER,
                            MODIFY_GROUP, "", Arrays.asList(finalFailedRemovedContacts).toString(), "");
                }
            }
            knLogger.debug(methodName, "etagMap ", KnGDPRTemplate.mapKeyMdn(etagMap));
            etagMap = corpSubsProvInfoUtil.updateAuthImpactedTablesForRemovedContact(xdmHome, corpId, persisterTxn, etagMap);
            knLogger.debug(methodName, "etagMap after auth mapping modification- ", KnGDPRTemplate.mapKeyMdn(etagMap));
            //persisterTxn.save();
        } catch (KnValidationException e) {
            knLogger.error(methodName, "KnValidationException occured while removing subscribers All Sublists - ", e);
            throw new KnCorpBOValidationException(KnErrorCodes.Validator.EMERGENCY_DESTINATION_MAPPING_EXISTS_FOR_CONTACT,
                    "Emergency Destination Mapping Exists --", CORP_GROUP_MANAGER,
                    MODIFY_GROUP, "", Arrays.asList(finalFailedRemovedContacts).toString(), "");
        } catch (KnCorpBOException e) {
            //rollback(persisterTxn);
            knLogger.error(methodName, "KnCorpBOException occured while deAssignContact - ", e);
            throw e;

        } catch (Exception e) {
            // rollback(persisterTxn);
            knLogger.error(methodName, "Unexpected exception occured while deAssignContact - ",
                    new KnException(KnErrorCodes.BOEntity.INTERNAL_ERROR, e.getMessage(), e));
            throw new KnException(KnErrorCodes.BOEntity.INTERNAL_ERROR, e.getMessage(), e);

        }
        knLogger.debug(methodName, "EXIT :");
    }

    public KnCorpDispatchGrpMemInfoRespDTO getSubscDetailsToUpdateIsDispatchMem(KnIPCorpDispatchGrpMemInfoDto groupInfoDTO, KnPersisterTxn persisterTxn) {
        String methodName = "getSubscDetailsToUpdateIsDispatchMem(KnIPCorpDispatchGrpMemInfoDto,KnPersisterTxn)";
        knLogger.info(methodName, "ENTRY : Input DTO Passed with corpId- ", groupInfoDTO.getCorpId());
        KnCorpDispatchGrpMemInfoRespDTO respDto = new KnCorpDispatchGrpMemInfoRespDTO();

        try {

            int corpId = groupInfoDTO.getCorpId();
            //Step:
            //get the Corp profile details from cache
            knLogger.debug(methodName, "Fetch the corpProfile profile if cached or fetch from the DB the details");
            KnCorpProfileDTO corpProfile = commonInfoUtil.getProfileDetails(String.valueOf(corpId),
                    CORP_PROFILE, false, persisterTxn);
            knLogger.debug(methodName, "Retrieved Corp Profile details - ", corpProfile);
            String xdmsHome = corpProfile.getXdmsHome();
            Collection<KnXDMCorpContactDTO> groupMemberListToChk = groupInfoDTO.getGroupMemberListToChk();
            List<KnXDMSubsProvInfoDTO> subscListToUpdate = new ArrayList<KnXDMSubsProvInfoDTO>();
            //call to check if the featureisenabled to set the location dispatch fleet members
            Collection<String> mdnList = new ArrayList<String>();
            if (groupMemberListToChk != null && groupMemberListToChk.size() > 0) {
                for (KnXDMCorpContactDTO contactDTO : groupMemberListToChk) {
                    mdnList.add(contactDTO.getMdn());
                }
            }
            //get the mdn that are internal and are not dispatcher type
            ArrayList<String> intNonDispMembers = contactInfoUtil.getInternalNonDispatchMember(mdnList, corpId, xdmsHome, persisterTxn);
            //This variable will be not null only in case update subscribers .Added since the updated mdn was missed in the internal subscriber fetch.
            if (groupInfoDTO.getUpdatedMdn() != null && !groupInfoDTO.getUpdatedMdn().isEmpty()) {
                intNonDispMembers.add(groupInfoDTO.getUpdatedMdn());
            }
            Map<String, KnCorpSubscriberDTO> subscBasicDetails = contactInfoUtil.getSubscIsMemOfDispGrpDetails(intNonDispMembers, xdmsHome, persisterTxn);
            ArrayList<String> pocHomes = new ArrayList<String>();
            for (Entry<String, KnCorpSubscriberDTO> entry : subscBasicDetails.entrySet()) {
                if (entry.getValue() != null) {
                    pocHomes.add(entry.getValue().getPocHome());
                }
            }
            Map<String, Boolean> locationPubEnabled = contactInfoUtil.getLocationPubFeaturebit(pocHomes, xdmsHome, persisterTxn);
            knLogger.debug(methodName, "subscBasicDetails - ", KnGDPRTemplate.mapKeyMdn(subscBasicDetails));
            knLogger.debug(methodName, "groupInfoDTO.getAddedGroupMembers() - ", groupInfoDTO.getAddedGroupMembers());
            if (groupInfoDTO.getAddedGroupMembers() != null && groupInfoDTO.getAddedGroupMembers().size() > 0) {
                for (KnXDMCorpContactDTO subsc : groupInfoDTO.getAddedGroupMembers()) {
                    knLogger.debug(methodName, "subsc - ", subsc);
                    if (subscBasicDetails != null && subscBasicDetails.get(subsc.getMdn()) != null &&
                            locationPubEnabled != null && locationPubEnabled.get(subscBasicDetails.get(subsc.getMdn()).getPocHome())) {
                        Integer dispMemInd = subscBasicDetails.get(subsc.getMdn()).getDispatchGrpmember();
                        if (dispMemInd == 0) {
                            KnXDMSubsProvInfoDTO subsProvInfoDTO = new KnXDMSubsProvInfoDTO();
                            subsProvInfoDTO.setMdn(subsc.getMdn());
                            subsProvInfoDTO.setDispatchGroupMember(1);
                            subsProvInfoDTO.setPublicSubscriptionType(-1);
                            subsProvInfoDTO.setCorporateSubscriptionType(-1);
                            subscListToUpdate.add(subsProvInfoDTO);
                        }
                    }
                }
            }
            //For the deleted guy check if its part of any other dispatch grp or the dispatch contact
            if (groupInfoDTO.getDeletedGroupMembers() != null && groupInfoDTO.getDeletedGroupMembers().size() > 0) {
                ArrayList<String> deletedMemList = new ArrayList<String>();
                for (KnXDMCorpContactDTO subsc : groupInfoDTO.getDeletedGroupMembers()) {
                    if (subscBasicDetails != null && subscBasicDetails.get(subsc.getMdn()) != null) {
                        deletedMemList.add(subsc.getMdn());
                    }
                }
                //This variable will be not null only in case update subscribers
                if (groupInfoDTO.getUpdatedMdn() != null && !groupInfoDTO.getUpdatedMdn().isEmpty()) {
                    deletedMemList.add(groupInfoDTO.getUpdatedMdn());
                }

                int clusterId = Integer.parseInt(System.getenv(CLUSTERID_ENV_NAME));
                Map<String, String> microServicesParamNameValueMap = genInfoUtil.retrieveMSSvcsCommonConfig(clusterId, persisterTxn);
                String locationFeatureFlagForLG = microServicesParamNameValueMap.get(LOCATION_FEATURE_FOR_LG_FLAG) != null ? microServicesParamNameValueMap.get(LOCATION_FEATURE_FOR_LG_FLAG) : "0";
                Collection<String> nonDispGrpMember;
                if(Objects.equals(locationFeatureFlagForLG, "1")) {
                    //Checking if any deleted is part of a dispatch group
                    nonDispGrpMember = groupInfoUtil.getSubsNotInDispatchGroupFromMDNList(deletedMemList, corpId, xdmsHome, persisterTxn);
                } else {
                    nonDispGrpMember = groupInfoUtil.getSubsNotInNormalDispatchGroupFromMDNList(deletedMemList, corpId, xdmsHome, persisterTxn);

                }
                knLogger.debug(methodName, "nonDispGrpMember --", KnGDPRTemplate.mdnList(nonDispGrpMember));
                //Checking if the delete subscriber belongs to  a dispatcher contactList
                Collection<String> nonDispContact = contactInfoUtil.getDispContacts(nonDispGrpMember, corpId, xdmsHome, persisterTxn);
                knLogger.debug(methodName, "nonDispContact -- ", KnGDPRTemplate.mdnList(nonDispContact));
                // checking if the deleted members belong to any locWatcher.
                Collection<String> nonLocWatcherMember = groupInfoUtil.getLocWatcherMdn(nonDispGrpMember, corpId, xdmsHome, persisterTxn);
                knLogger.debug(methodName, "nonLocWatcherMember -- ", KnGDPRTemplate.mdnList(nonLocWatcherMember));
                nonLocWatcherMember.addAll(nonDispContact);
                // nonDispGrpMember == null; means all the deletedMemList are part of other dispatchGroupList. so no need to disable the locationBit.
                // nonDispContact; this variable will return the mdn which is a contacts of dispatcher in the corporate by providing the residue input nonDispGrpMember.
                // nonLocWatcherMember; this variable will return mdnList, where ever locWatcher is available along with the mdnList.
                if (nonDispGrpMember != null) {
                    for (String mdn : nonDispGrpMember) {
                        if (subscBasicDetails != null && subscBasicDetails.get(mdn) != null) {
                            Integer dispMemInd = subscBasicDetails.get(mdn).getDispatchGrpmember();
                            if (dispMemInd != null && dispMemInd == 1) {
                                if (!nonLocWatcherMember.contains(mdn)) {
                                    KnXDMSubsProvInfoDTO subsProvInfoDTO = new KnXDMSubsProvInfoDTO();
                                    subsProvInfoDTO.setMdn(mdn);
                                    subsProvInfoDTO.setDispatchGroupMember(0);
                                    subsProvInfoDTO.setPublicSubscriptionType(-1);
                                    subsProvInfoDTO.setCorporateSubscriptionType(-1);
                                    subscListToUpdate.add(subsProvInfoDTO);
                                }
                            }
                        }
                    }
                }
            }
            respDto.setSubscIsDispMemDetailsList(subscListToUpdate);
            /*List<String> mdnListForEtagUpdate = new ArrayList<>();
            mdnListForEtagUpdate = subscListToUpdate.stream().map(KnXDMSubsProvInfoDTO::getMdn).collect(Collectors.toList());
            contactInfoUtil.subsEtagUpdateUtil(mdnListForEtagUpdate, corpId, xdmsHome, true, persisterTxn);*/
            populate(respDto);
        } catch (KnCorpBOException e) {
            knLogger.error(methodName, "KnCorpBOException occured while retrieving non dispatch group members - ", e);
            populate(respDto, e);

        } catch (Exception e) {
            knLogger.error(methodName, "Unexpected exception occured while retrieving non dispatch group memberst - ",
                    new KnException(KnErrorCodes.BOEntity.INTERNAL_ERROR, e.getMessage(), e));
            populate(respDto, e);

        }
        knLogger.debug(methodName, "non dispatch group members Response - ", respDto);
        knLogger.debug(methodName, "EXIT :");
        return respDto;
    }

    private KnCorpGroupInfoRespDTO invokeModifyGroupCustom(KnIPCorpGroupInfoDTO groupInfoDTO, KnCorpProfileDTO
            corpProfile, KnPersisterTxn persisterTxn, String xdmsHome) throws Exception {

        String methodName = "invokeModifyGroupCustom(KnIPCorpGroupInfoDTO, KnCorpProfileDTO, KnPersisterTxn)";
        KnCorpGroupInfoRespDTO respDto = new KnCorpGroupInfoRespDTO();
        //Invoking custom hook
        Map<String, Object> customParams = groupInfoDTO.getCustomParamMap();
        if (groupInfoDTO.getHierarchyType() == HIERARCHY_TYPE.HIERARCHY) {
            if (customParams != null) {
                customParams.put(CURRENT_MASTER_LIST_ETAG, corpProfile.getCorpMasterListEtag());
                customParams.put(PERSISTER_TXN, persisterTxn);
                customParams.put(PTT_SERVER_ID, xdmsHome);
                groupInfoDTO.setCustomParamMap(customParams);
                KnCorpHookIPDTO hookIPDTO = new KnCorpHookIPDTO();
                hookIPDTO.setAction(KnActions.ACTIONS.MODIFY_GROUP);
                hookIPDTO.setData(groupInfoDTO);
                knLogger.error(methodName, "Invoking hook with vales - ", hookIPDTO);
                KnProcessInvokerImpl processInvoker = KnProcessInvokerImpl.getInstance();
                Object hookResp = processInvoker.invokeHook(CUSTOM_CORP_USER_HOOK, hookIPDTO);
                if (hookResp instanceof KnCorpHookRespDTO) {
                    KnCorpHookRespDTO responseDTO = (KnCorpHookRespDTO) hookResp;
                    if (com.kodiak.xdms.server.common.resources.KnConstants.RESPONSE_STATUS.FAILURE.value() == responseDTO.getStatus()) {
                        knLogger.error(methodName, "Returning Failure response");
                        populateXdmResponseFroomHook(responseDTO, respDto);
                        return respDto;
                    } else {
                        if (responseDTO.getFailedDataList() != null && !responseDTO.getFailedDataList().isEmpty()) {
                            respDto.setFailedDataList(responseDTO.getFailedDataList());
                        }
                    }
                }
            }
        }
        return respDto;
    }

    /**
     * This method will validate if the group type has been changed for the group
     * based on the old and current group type passed
     *
     * @param newGroupType
     * @param currentGroupType
     * @return
     */
    private boolean checkIfGroupTypeChngd(int newGroupType, int currentGroupType) {
        if (newGroupType != 0 && (currentGroupType != newGroupType)) {
            return Boolean.TRUE;
        } else {
            return Boolean.FALSE;
        }
    }

