    /**
     * This method is used to fetch the data for validations for the dispatch group - group type based
     *
     * @param groupInfoDTO
     * @param xdmsHome
     * @param persisterTxn
     * @return
     * @throws Exception
     */
    private KnCorpGroupInfoPersistDTO populateDataForValidation(KnIPCorpGroupInfoDTO groupInfoDTO, String xdmsHome,
                                                                KnPersisterTxn persisterTxn) throws Exception {

        String methodName = "populateDataForValidation(KnIPCorpGroupInfoDTO, KnCorpGroupInfoPersistDTO, String, KnPersisterTxn)";
        KnCorpGroupInfoPersistDTO persisterDTO = new KnCorpGroupInfoPersistDTO();
        knLogger.debug(methodName," Entry groupInfoDTO:",groupInfoDTO);
        int grpId = groupInfoDTO.getGroupId();
        Collection<Integer> groupIds = new ArrayList<Integer>();
        groupIds.add(grpId);
        // if (KnConstants.DISPATCH_GROUP == groupInfoDTO.getGroupType()) {
        //If the group type is dispatch get the current dispatchers of the group
        LinkedHashMap<Integer, LinkedList<String>> dispatcherSubscriberMap = getGroupDispatchers(groupIds,
                xdmsHome, persisterTxn);
        if (dispatcherSubscriberMap.get(grpId) != null) {
            persisterDTO.setDbDispatcherSubscribers(dispatcherSubscriberMap.get(grpId));
        }
        persisterDTO.setMultipleDispatcherAllowed(KnConstants.TRUE); //get the value from profile
        // }
        Map<Integer, Collection<String>> locWatcherSubscriberMap = getGroupLocWatcherSubscriber(groupIds,
                xdmsHome, persisterTxn);
        if (locWatcherSubscriberMap.get(grpId) != null) {
            persisterDTO.setDbLocWatcherSubscribers(locWatcherSubscriberMap.get(grpId));
        }
        knLogger.debug(methodName, "Filtering dispatchers and supervisors from the added mdn list.");
        Collection<String> addedMdnList = new ArrayList<String>();
        //to hold the request dispatchers in the request
        Set<String> reqDispatcherSubscribers = new HashSet<String>();
        //to hold the request dispatchers in the request
        Set<String> interOPSubscribers = new HashSet<String>();
        Set<String> supervisorMemList = new HashSet<String>();
        //having both supervisors and the dispatchers
        Collection<KnCorpGroupMemberDTO> completeSupervisorList = new ArrayList<KnCorpGroupMemberDTO>();
        Collection<KnCorpGroupMemberDTO> locWatcherList = new ArrayList<>();
        Map<String, Integer> locWatcherMap = new HashMap<>();
        Map<String, Integer> supervisiorMap = new HashMap<>();
        Map<String, Integer> groupModifyPermMap = new HashMap<>();
        Map<String, Integer> osmAuthMap = new HashMap<>();
        groupInfoDTO.getAddedMemberDTOMdns().stream().collect(Collectors.toList());
        List<String> subsList = new ArrayList<>();
        groupInfoDTO.getAddedMemberDTOMdns().stream().forEach(x -> subsList.add(x.getMdn()));
        Collection<KnCorpSubscriberDTO> pocSubsInfo = contactInfoUtil.getSubscribersInfo(subsList, xdmsHome, persisterTxn);
        //If there are added members in the request we need to filter out the supervisors and the dispatchers from the list for
        //validations and updating in db with the supervisor values
        if (!isObjectNullOrEmpty(groupInfoDTO.getAddedMemberDTOMdns())) {
            //added members supervisor and dispatcher list all together is put into this list
            Collection<KnCorpGroupMemberDTO> addedMdnSupervisorList = new ArrayList<KnCorpGroupMemberDTO>();
            for (KnCorpContactDTO contact : groupInfoDTO.getAddedMemberDTOMdns()) {
                String mdn = contact.getMdn();
                addedMdnList.add(mdn);
                KnCorpGroupMemberDTO member = new KnCorpGroupMemberDTO();
                member.setMdn(mdn);
                int supervisoryFlag = contact.getSupervisory();
                int locWatcher = contact.getLocWatcher();
                Integer groupModifyPerm = contact.getGroupModifyPerm();
                locWatcherMap.put(mdn, locWatcher);
                osmAuthMap.put(mdn,contact.getIsOSMAuthorize());
                groupModifyPermMap.put(mdn, groupModifyPerm);
                if (locWatcher == LOCWATCHER) {
                    KnCorpGroupMemberDTO locDto = new KnCorpGroupMemberDTO();
                    locDto.setMdn(mdn);
                    locDto.setLocWatcher(locWatcher);
                    locWatcherList.add(locDto);
                }
                member.setSupervisory(supervisoryFlag);
                member.setLocWatcher(locWatcher);
                member.setCallInitiatePermission(contact.getCallInitiatePermission());
                member.setCallReceivePermission(contact.getCallReceivePermission());
                member.setInCallPermission(contact.getInCallPermission());
                member.setGroupModifyPerm(groupModifyPerm);
                member.setIsOSMAuthorize(contact.getIsOSMAuthorize());

                completeSupervisorList.add(member);
                //not adding the members with 0 as the supervisor since its use to validate against the external subsc check
                if (NORMAL_MEMBER != supervisoryFlag) {
                    addedMdnSupervisorList.add(member);
                    if (DISPATCHER == supervisoryFlag) {
                        reqDispatcherSubscribers.add(mdn);
                    } else if (INTER_OP == supervisoryFlag) {
                        interOPSubscribers.add(mdn);
                    } else if (SUPERVISOR == supervisoryFlag) {
                        supervisorMemList.add(mdn);
                    }
                }
                supervisiorMap.put(mdn, supervisoryFlag);
            }
            persisterDTO.setAddedMdnList(addedMdnList);
            persisterDTO.setAddedMdnSupervisor(addedMdnSupervisorList);
            persisterDTO.setRequestDispatcherSubscribers(reqDispatcherSubscribers);
            persisterDTO.setReqInterOpSubs(interOPSubscribers);
        }

        Collection<KnCorpGroupMemberDTO> modifiedMembers = groupInfoDTO.getModifiedMembers();
        knLogger.debug(methodName, "Populating supervisors from the modified members list.");
        //populating the supervisors from the modified members list in the request
        if (!isObjectNullOrEmpty(modifiedMembers)) {
            Collection<KnCorpGroupMemberDTO> supervisorMemForValidation = new ArrayList<KnCorpGroupMemberDTO>();
            Set<String> corpContactExternalMdns = groupInfoDTO.getCorpContactExternalMdns();
            for (KnCorpGroupMemberDTO memberDTO : modifiedMembers) {
                locWatcherMap.put(memberDTO.getMdn(), memberDTO.getLocWatcher());
                osmAuthMap.put(memberDTO.getMdn(), memberDTO.getIsOSMAuthorize());
                groupModifyPermMap.put(memberDTO.getMdn(), memberDTO.getGroupModifyPerm());
                if (memberDTO.getLocWatcher() == LOCWATCHER) {
                    KnCorpGroupMemberDTO locDto = new KnCorpGroupMemberDTO();
                    locDto.setMdn(memberDTO.getMdn());
                    locDto.setLocWatcher(memberDTO.getLocWatcher());
                    locWatcherList.add(locDto);
                }
                completeSupervisorList.add(memberDTO);
                int supervisor = memberDTO.getSupervisory();
                boolean isExternalMember = corpContactExternalMdns != null && corpContactExternalMdns.contains(memberDTO.getMdn());
                // Keep external members in validation only when they are assigned a non-normal role.
                if (NORMAL_MEMBER != supervisor || !isExternalMember) {
                    supervisorMemForValidation.add(memberDTO);
                }
                if (SUPERVISOR == supervisor) {
                    supervisorMemList.add(memberDTO.getMdn());
                }
                supervisiorMap.put(memberDTO.getMdn(), supervisor);
            }
            groupInfoDTO.setGroupSupervisor(supervisorMemForValidation);
        }
        knLogger.debug(methodName, "groupInfoDTO.getGroupSupervisor() - ", groupInfoDTO.getGroupSupervisor());
        knLogger.debug(methodName, "After Populating supervisors from the modified members list.");
        persisterDTO.setLocWatcherMap(locWatcherMap);
        persisterDTO.setSupervisiorMap(supervisiorMap);
        persisterDTO.setOsmAuthorizeMap(osmAuthMap);
        persisterDTO.setCompleteSupervisorList(completeSupervisorList);
        persisterDTO.setLocWatcherList(locWatcherList);
        persisterDTO.setGrpSupervisorMemList(new ArrayList<>(supervisorMemList));
        persisterDTO.setGrpModifyPermMap(groupModifyPermMap);
        Map<Integer, Collection<String>> grpInterOpSubsc = groupInfoUtil.getGroupSpecificSubsc(groupIds, INTER_OP, xdmsHome, persisterTxn);
        persisterDTO.setDbInterOpSubs(grpInterOpSubsc.get(grpId));
        knLogger.debug(methodName, "return persisterDTO - ", persisterDTO);
        return persisterDTO;
    }

    /**
     * modifySubscriberScanList is a API for adding, removing and modifying scan
     * list of a subscriber
     * Validation:
     * 1)	Validate if System level scanning bit is enable, i .e. Column: ENABLE_TALKGROUP_SELECT Table: DG.XDMS_SVC_CONFIG
     * 2)	Etag Validation, Etag in request and Etag in DB must be same
     * 3)	Subscriber ActiveFS 20 bit must be enable for CAT operation and Subscriber ActiveFS 31 bit must be enable for XCAP operation
     * 4)	Validate if subscriber is not an external contact to the corporate.
     * 5)	Validate if MDN's Client Type is not Inter-op Or Dispatch
     * 6)	Subscriber should be part of the CorpID
     * 7)	Verify if Max TGSc size limit is not reached
     * 8)	Verify that only one group is allowed to be set for each of the priority range. No Two groups shall have same priority other than 0
     * 9)	Verify the max priority limit Column: MAXCAMPEDGROUPS Table:DG.XDMS_SVC_CONFIG
     * 10)	Validate all the groups in added list belongs to passed corporate
     * 11)	Validate if MDN is group member in the provided Groups list.
     * 12)	Added List Must not present in DG.CAMPEDGROUPINFO, Modified and Removed Must present in DG.CAMPEDGROUPINFO
     */
    @Override
    public KnCorpResponseDTO modifySubscriberScanList(KnIPTalkGroupDTO ipTalkGroupDTO, KnPersisterTxn persisterTxn) {

        String methodName = "modifySubscriberScanList(KnIPTalkGroupDTO ipTalkGroupDTO, KnPersisterTxn persisterTxn)";
        KnCorpResponseDTO respDTO = new KnCorpResponseDTO();
        KnCorpmgmtTokenvalidation tokenValidation = new KnCorpmgmtTokenvalidation();
        KnSubscriberPersistDTO originator = new KnSubscriberPersistDTO();
        Set<Integer> mcxGroups = new HashSet<>();
        try {
            knLogger.debug(methodName, "Entry :-", ipTalkGroupDTO);
            KnCorpTGSPersistDTO tgsPersistDTO = new KnCorpTGSPersistDTO();

            // Validate if System level scanning bit is enable, i.e. Column: ENABLE_TALKGROUP_SELECT Table: DG.XDMS_SVC_CONFIG
            KnCorpProfileDTO corpProfile = commonInfoUtil.getProfileDetails(String.valueOf(ipTalkGroupDTO.getCorpId()), CORP_PROFILE, false,
                    persisterTxn);
            knLogger.debug(methodName, "Retrieved Corp Profile details - ", corpProfile);
            if (corpProfile.getSystemTGSBit() == 1) {
                tgsPersistDTO.setSysTGSBitEanble(true);
            }
            if (corpProfile.getTgscanningClient() == 1) {
                tgsPersistDTO.setSystemTgscanningClientBitEanble(true);
            }

            String xdmsHome = corpProfile.getXdmsHome();

            //Invoking custom hook
            KnCorpHookRespDTO responseDTO;
            Map<String, Object> customParams = ipTalkGroupDTO.getCustomParamMap();
            List<String> combinedList = new ArrayList<>();
            if (ipTalkGroupDTO.getHierarchyType() == HIERARCHY_TYPE.HIERARCHY && customParams != null) {
                contactInfoUtil.checkValidHierarchySubs(Collections.singletonList(ipTalkGroupDTO.getMdn()), customParams, xdmsHome, persisterTxn);
                //TODO check if group is part of same fan ban
                customParams.put(CURRENT_MASTER_LIST_ETAG, corpProfile.getCorpMasterListEtag());
                customParams.put(PERSISTER_TXN, persisterTxn);
                customParams.put(PTT_SERVER_ID, xdmsHome);
                ipTalkGroupDTO.setCustomParamMap(customParams);
                KnCorpHookIPDTO hookIPDTO = new KnCorpHookIPDTO();
                hookIPDTO.setAction(KnActions.ACTIONS.MODIFY_SCAN_LIST);
                hookIPDTO.setData(ipTalkGroupDTO);
                KnProcessInvokerImpl processInvoker = KnProcessInvokerImpl.getInstance();
                Object hookResp = processInvoker.invokeHook(CUSTOM_CORP_USER_HOOK, hookIPDTO);
                if (hookResp instanceof KnCorpHookRespDTO) {
                    responseDTO = (KnCorpHookRespDTO) hookResp;
                    if (com.kodiak.xdms.server.common.resources.KnConstants.RESPONSE_STATUS.FAILURE.value() == responseDTO.getStatus()) {
                        knLogger.error(methodName, "Returning Failure response");
                        populateXdmResponseFroomHook(responseDTO, respDTO);
                        return respDTO;
                    } else {
                        if (responseDTO.getFailedDataList() != null && !responseDTO.getFailedDataList().isEmpty()) {
                            respDTO.setFailedDataList(responseDTO.getFailedDataList());
                        }
                    }
                }
                // Combine Added, Modified, and Deleted group IDs into a single set
                Set<Integer> combinedGroupIds = Stream.of(ipTalkGroupDTO.getAddedAddlTgList(), ipTalkGroupDTO.getModifiedAddlTgList(), ipTalkGroupDTO.getRemovedAddlTgList())
                        .filter(Objects::nonNull)
                        .flatMap(Collection::stream)
                        .map(KnCorpGroupDTO::getGroupId)
                        .collect(Collectors.toSet());

                knLogger.debug(methodName, "Combined Group IDs: ", combinedGroupIds);

                // Proceed if there are any group IDs to process
                if (!combinedGroupIds.isEmpty()) {
                    Collection<String> idListStr = (Collection<String>) customParams.get(com.kodiak.common.resources.KnConstants.IDLIST);
                    Object idTypeObj = customParams.get(IDTYPE);
                    int idTypeValues = idTypeObj instanceof Integer ? (Integer) idTypeObj : Integer.parseInt((String) idTypeObj);

                    if (idListStr != null) {
                        List<Integer> idListInt = (List<Integer>) convertStrToIntColl(idListStr);
                        KnCorpCommonInfoUtil knCorpCommonInfoUtil = new KnCorpCommonInfoUtil();

                        // Convert combinedGroupIds to String list for validation
                        combinedList = combinedGroupIds.stream()
                                .map(Object::toString)
                                .collect(Collectors.toList());

                        commonInfoUtil.validateGroupParams(combinedList, String.valueOf(ipTalkGroupDTO.getCorpId()), idListInt, xdmsHome, idTypeValues, persisterTxn);
                    }
                }
            }
            commonInfoUtil.validateCorpAndGroupParams(combinedList, String.valueOf(ipTalkGroupDTO.getCorpId()), xdmsHome, persisterTxn);
            List<KnXDMTalkGroupInfoDTO> addedCampGrpList = ipTalkGroupDTO.getAddedCampGrpList();
            List<KnXDMTalkGroupInfoDTO> modifiedCampGrpList = ipTalkGroupDTO.getModifiedCampGrpList();
            List<KnXDMTalkGroupInfoDTO> removedCampGrpList = ipTalkGroupDTO.getRemovedCammpGrpList();
            // Etag Validation, Etag in request and Etag in DB must be same
            KnTalkGrpScanMode talkGrpScanMode = groupInfoUtil.getSubsTalkGrpScanMode(ipTalkGroupDTO.getMdn(), xdmsHome, persisterTxn);
            if (talkGrpScanMode != null) {
                tgsPersistDTO.setEtag(String.valueOf(talkGrpScanMode.getEtag()));
            } else {
                // If Document doesn't exist then setting the request request etag value to null
                tgsPersistDTO.setEtag(null);
            }

            // Subscriber ActiveFS 20 bit must be enable for CAT operation and Subscriber ActiveFS 31 bit must be enable for XCAP operation
            KnCorpSubscriberDTO subscriberDTO = contactInfoUtil.selectPocSubscriberInfo(ipTalkGroupDTO.getMdn(), xdmsHome, persisterTxn);
            tgsPersistDTO.setActiveFS2(subscriberDTO.getSubsActiveFS2());

            //validating mcpttid

            originator.setInputDTO(ipTalkGroupDTO);
            originator.setMcpttID(subscriberDTO.getMcpttId());
            originator.setMcpttCompliance(subscriberDTO.getMcpttCompliance());
            tokenValidation.validateToken(originator);

            // Validate if subscriber is not an external contact to the corporate.
            boolean extCnt = contactInfoUtil.isExternalSubscriber(ipTalkGroupDTO.getMdn(), Integer.parseInt(ipTalkGroupDTO.getCorpId()), xdmsHome, persisterTxn);
            tgsPersistDTO.setSubsExternalCont(extCnt);

            // Validate if MDN's Client Type is not Inter-op Or Dispatch
            tgsPersistDTO.setSubsClientType(subscriberDTO.getClientType());

            // Subscriber should be part of the CorpID
            tgsPersistDTO.setSubsCorpId(subscriberDTO.getCorpId());

            // Verify if Max TGSc size limit is not reached
            tgsPersistDTO.setMaxCampedGrpLmt(corpProfile.getMaxCampedGrp());

            // Verify that only one group is allowed to be set for each of the priority range. No Two groups shall have same priority other than 0
            // Verify the max priority limit Column: MAXCAMPEDGROUPS Table:DG.XDMS_SVC_CONFIG
            tgsPersistDTO.setMaxPriority(corpProfile.getMaxPriority());

            // Validate all the groups in added list belongs to passed corporate
            List<Integer> addedCampedGrpIdList = new ArrayList<Integer>();
            for (KnXDMTalkGroupInfoDTO addedCampGrp : addedCampGrpList) {
                addedCampedGrpIdList.add(addedCampGrp.getGroupId());
            }
            String userProfileId = subscriberDTO.getUserProfileId();
            knLogger.debug(methodName," userProfileId:",userProfileId);
            ArrayList<String> upmId = new ArrayList<>();
            upmId.add(userProfileId);
            Map<String, Integer> upmOwnerList = corpUserProfileUtil.getUserProfileOwnerinfo(upmId, xdmsHome, persisterTxn);
            Integer groupOwnerCorpId=Integer.parseInt(ipTalkGroupDTO.getCorpId());
            Map<Integer, Integer> groupIdTypesMap = null;
            if(!upmOwnerList.isEmpty()){
                groupOwnerCorpId=upmOwnerList.get(userProfileId);
                groupIdTypesMap = groupInfoUtil.getValidGrp(addedCampedGrpIdList,
                        xdmsHome, persisterTxn);
            }
            knLogger.debug(methodName,"ownerCorpId :",groupOwnerCorpId);
            if(groupIdTypesMap == null)
                groupIdTypesMap = groupInfoUtil.getValidGrpInCorp(addedCampedGrpIdList, groupOwnerCorpId,
                        xdmsHome, persisterTxn);
            //changes for group sharing
            //check whether for the given corpId any shared groups are avilable or not
            //if any shared groups are avilable then add shared group info to dbGroupList to avoid rules
            Set<Integer> sharedCorpGrpIds  = new HashSet<>(1);
            Map<Integer,List<KnCorpSharedCorpInfo>> sharedCorpGrpInfoMap = groupInfoUtil.selectGroupSharedCorpInfoBySharedCorpId(groupOwnerCorpId,xdmsHome,persisterTxn);

            if(sharedCorpGrpInfoMap!=null && !sharedCorpGrpInfoMap.isEmpty()) {
                sharedCorpGrpIds = sharedCorpGrpInfoMap.keySet();
                knLogger.debug(methodName, "sharedCorpGrpIds", sharedCorpGrpIds);
            }
            //requested groupId should be validated in add/modify
            List<Integer> grpIdListInCorp = new ArrayList<>(groupIdTypesMap.keySet());
            if (addedCampGrpList != null) {
                List<Integer> addedGroupIds = addedCampGrpList.stream().map(KnXDMTalkGroupInfoDTO::getGroupId).collect(Collectors.toList());
                grpIdListInCorp.addAll(addedGroupIds);
            }

            if (modifiedCampGrpList != null) {
                List<Integer> modifiedGroupIds = modifiedCampGrpList.stream().map(KnXDMTalkGroupInfoDTO::getGroupId).collect(Collectors.toList());
                grpIdListInCorp.addAll(modifiedGroupIds);
            }
            if (removedCampGrpList != null) {
                List<Integer> removedGroupIds = removedCampGrpList.stream().map(KnXDMTalkGroupInfoDTO::getGroupId).collect(Collectors.toList());
                grpIdListInCorp.removeAll(removedGroupIds);
            }
            tgsPersistDTO.setGrpListInCorp(grpIdListInCorp);
            //To validate the allowed group types
            Set<Integer> grpTypeSet = new HashSet<>(groupIdTypesMap.values());
            tgsPersistDTO.setReqGroupTypes(grpTypeSet);
            tgsPersistDTO.setGrpIdTypeMap(groupIdTypesMap);
            boolean pttRadioClients = subscriberDTO.getClientType() == PTTRADIOHANDSETCLIENT || subscriberDTO.getClientType() == PTTRADIOCROSSCARRIERCLIENT
                    || subscriberDTO.getClientType() == PTTRADIOWIFIONLYCLIENT;

            // Validate if MDN is group member in the provided Groups list.
            List<Integer> subsGrpList = groupInfoUtil.getSubsGroupIdList(grpIdListInCorp, ipTalkGroupDTO.getMdn(), xdmsHome, persisterTxn);
            knLogger.debug(methodName, "subsGrpList from GroupMembership table ", subsGrpList);

            List<KnCorpAddlTGInfoDTO> mcxTgList = new ArrayList<>();
            if(userProfileId != null){
                //  KnCorpUserProfileDTO userProfile = corpUserProfileUtil.getUserProfile(String.valueOf(ipTalkGroupDTO.getCorpId()), userProfileId, xdmsHome, persisterTxn);
                Set<KnCorpGroupListInfoDTO> mcxGroupList =corpUserProfileUtil.retriveGroupProfileInfoByProfileId(userProfileId, xdmsHome, persisterTxn);
                knLogger.debug(methodName, "mcxGroupList ", mcxGroupList);
                List<Integer> groupIdListFromProfile = new ArrayList<>();
                if (mcxGroupList != null && mcxGroupList.size() > 0) {
                    groupIdListFromProfile = mcxGroupList.stream().map(KnCorpGroupListInfoDTO::getGroupID).collect(Collectors.toList());
                    knLogger.debug(methodName, "groupIdListFromProfile  ", groupIdListFromProfile);
                }
                Collection<Integer> groupIds = new HashSet<>();
                groupIds.addAll(addedCampedGrpIdList);
                groupIds.addAll(groupIdListFromProfile);
                knLogger.debug(methodName, "Combined input groupIds & profile ", groupIds);
                List<KnCorpGroupDTO> groupInfoList = groupInfoUtil.getGroupBasicInfoList(groupIds, xdmsHome, persisterTxn);
                mcxGroups.addAll(groupInfoList.stream()
                        .filter(groupDetails -> groupDetails.getMcxGrpInd().intValue() == GROUP_SIZE_TYPE.VLARGE_GROUP.value())
                        .map(KnCorpGroupDTO::getGroupId).collect(Collectors.toSet()));
                knLogger.debug(methodName, "mcx groups ", mcxGroups);
                subsGrpList.removeAll(mcxGroups);
                subsGrpList.addAll(mcxGroups);
                knLogger.debug(methodName, "subsGrpList from after merging MCX groups", subsGrpList);
                knLogger.debug(methodName, "mcx groups ", mcxGroups);
                for(KnCorpGroupListInfoDTO info : mcxGroupList){
                    if(mcxGroups.contains(info.getGroupID())) {
                        KnCorpAddlTGInfoDTO tgInfoDTO = new KnCorpAddlTGInfoDTO();
                        tgInfoDTO.setMdn(ipTalkGroupDTO.getMdn());
                        tgInfoDTO.setChannelId(info.getGroupChannel());
                        tgInfoDTO.setZoneId(info.getGroupZone());
                        tgInfoDTO.setGroupId(info.getGroupID());
                        mcxTgList.add(tgInfoDTO);
                    }
                }
                knLogger.debug(methodName, "mcx groups tglist ", mcxTgList);
                //ModifyUPM by adding new group camp info
                List<Integer> finalGroupIdListFromProfile = groupIdListFromProfile;
                List<Integer> newGroupsAddedToProfile = addedCampedGrpIdList.stream().filter(group -> (!(finalGroupIdListFromProfile.contains(group)) && mcxGroups.contains(group))).collect(Collectors.toList());
                knLogger.debug(methodName, "mcx group in addedcampgroup  which not present in CB user profile", newGroupsAddedToProfile);

                if(!newGroupsAddedToProfile.isEmpty()){
                    Map<Integer, KnXDMTalkGroupInfoDTO> tempTalkGroupMap = ipTalkGroupDTO.getAddedCampGrpList().stream()
                            .collect(Collectors.toMap(KnXDMTalkGroupInfoDTO::getGroupId, exist -> exist));
                    for(Integer groupId: newGroupsAddedToProfile){
                        KnCorpAddlTGInfoDTO tgInfoDTO = new KnCorpAddlTGInfoDTO();
                        KnXDMTalkGroupInfoDTO temp = tempTalkGroupMap.get(groupId);
                        tgInfoDTO.setMdn(ipTalkGroupDTO.getMdn());
                        tgInfoDTO.setChannelId(temp.getChannel());
                        tgInfoDTO.setZoneId(temp.getZone());
                        tgInfoDTO.setGroupId(temp.getGroupId());
                        mcxTgList.add(tgInfoDTO);
                    }
                }
            }
            knLogger.debug(methodName, "mcx groups tglist ", mcxTgList);

            tgsPersistDTO.setSubsGroupList(subsGrpList);

            List<Integer> brdstGrpIds = groupInfoUtil.getBroadcstGroupList(ipTalkGroupDTO.getMdn(), xdmsHome, persisterTxn);
            tgsPersistDTO.setBroadcastGrpIds(new HashSet<Integer>(brdstGrpIds));

            // Added List Must not present in DG.CAMPEDGROUPINFO, Modified and Removed Must present in DG.CAMPEDGROUPINFO
            List<KnCorpTGSPersistDTO> corpTGSPersistDTOs = groupInfoUtil.getSubsCampedGrp(ipTalkGroupDTO, xdmsHome, persisterTxn);
            knLogger.debug(methodName, "corpTGSPersistDTOs :", corpTGSPersistDTOs);
            List<KnXDMTalkGroupInfoDTO> dbCampGrpList = new ArrayList<KnXDMTalkGroupInfoDTO>();
            List<KnXDMTalkGroupInfoDTO> dbOnlyCampGrpList = new ArrayList<KnXDMTalkGroupInfoDTO>();
            Collection<KnCorpAddlTGInfoDTO> existingSubsAddlTGList = new ArrayList<>();
            Collection<KnXDMTalkGroupInfoDTO> uniqueGroupIdsNPriority = null;

            if (pttRadioClients) {
                //List<KnCorpTGSPersistDTO> corpChannelPersistDTOs = groupInfoUtil.getSubsChannelGrp(ipTalkGroupDTO, xdmsHome, persisterTxn);
                existingSubsAddlTGList = groupInfoUtil.getSubsAddlTGList(ipTalkGroupDTO.getMdn(), xdmsHome, persisterTxn);
                if(!mcxTgList.isEmpty()){
                    existingSubsAddlTGList.addAll(mcxTgList);
                }
                for (KnCorpAddlTGInfoDTO corpChannelpersistDTO : existingSubsAddlTGList) {
                    KnXDMTalkGroupInfoDTO xdmTalkGroupInfoDTO = new KnXDMTalkGroupInfoDTO();
                    xdmTalkGroupInfoDTO.setGroupId(corpChannelpersistDTO.getGroupId());
                    xdmTalkGroupInfoDTO.setChannel(corpChannelpersistDTO.getChannelId());
                    for (KnCorpTGSPersistDTO corpTGSPersistDTO : corpTGSPersistDTOs) {
                        if (corpTGSPersistDTO.getGroupId().equals(corpChannelpersistDTO.getGroupId())) {
                            xdmTalkGroupInfoDTO.setPriority(corpTGSPersistDTO.getPriority());
                        }
                    }
                    dbCampGrpList.add(xdmTalkGroupInfoDTO);
                }

                for (KnCorpTGSPersistDTO corpTGSPersistDTO : corpTGSPersistDTOs) {
                    KnXDMTalkGroupInfoDTO xdmTalkGroupInfoDTO = new KnXDMTalkGroupInfoDTO();
                    xdmTalkGroupInfoDTO.setGroupName(corpTGSPersistDTO.getGroupName());
                    xdmTalkGroupInfoDTO.setGroupId(corpTGSPersistDTO.getGroupId());
                    xdmTalkGroupInfoDTO.setPriority(corpTGSPersistDTO.getPriority());
                    for (KnCorpAddlTGInfoDTO corpChannelpersistDTO : existingSubsAddlTGList) {
                        if (corpTGSPersistDTO.getGroupId().equals(corpChannelpersistDTO.getGroupId())) {
                            xdmTalkGroupInfoDTO.setChannel(corpChannelpersistDTO.getChannelId());
                        }
                    }
                    dbOnlyCampGrpList.add(xdmTalkGroupInfoDTO);
                }
                knLogger.debug(methodName, "dbCampGrpList: ", dbCampGrpList);
                //removing duplicate entry in dbCampGrpList,due to multizone across group,for pv>=16,0,null
                uniqueGroupIdsNPriority = dbCampGrpList.stream()
                        .<Map<Integer, KnXDMTalkGroupInfoDTO>>collect(HashMap::new, (m, e) -> m.put(e.getGroupId(), e), Map::putAll)
                        .values();
                knLogger.debug(methodName, "uniqueGroupIdsNPriority: ", uniqueGroupIdsNPriority);
                knLogger.debug(methodName, "dbOnlyCampGrpList: ", dbOnlyCampGrpList);
                tgsPersistDTO.setDbCampedGroups(dbOnlyCampGrpList);
                tgsPersistDTO.setDbChannelGroups(new ArrayList<>(uniqueGroupIdsNPriority));

            } else {
                for (KnCorpTGSPersistDTO corpTGSPersistDTO : corpTGSPersistDTOs) {
                    KnXDMTalkGroupInfoDTO xdmTalkGroupInfoDTO = new KnXDMTalkGroupInfoDTO();
                    xdmTalkGroupInfoDTO.setGroupName(corpTGSPersistDTO.getGroupName());
                    xdmTalkGroupInfoDTO.setGroupId(corpTGSPersistDTO.getGroupId());
                    xdmTalkGroupInfoDTO.setPriority(corpTGSPersistDTO.getPriority());
                    dbCampGrpList.add(xdmTalkGroupInfoDTO);
                }
                knLogger.debug(methodName, "dbCampGrpList: for CT not radio: ", dbCampGrpList);

                //removing duplicate entry in dbCampGrpList,due to multizone across group,for pv>=16,0,null
                //seems duplicate check, is not required in this case.
                uniqueGroupIdsNPriority = dbCampGrpList.stream()
                        .<Map<Integer, KnXDMTalkGroupInfoDTO>>collect(HashMap::new, (m, e) -> m.put(e.getGroupId(), e), Map::putAll)
                        .values();
                knLogger.debug(methodName, "uniqueGroupIdsNPriority: ", uniqueGroupIdsNPriority);
                tgsPersistDTO.setDbCampedGroups(new ArrayList<>(uniqueGroupIdsNPriority));
                tgsPersistDTO.setDbChannelGroups(new ArrayList<>(uniqueGroupIdsNPriority));
            }

            knLogger.debug(methodName, "uniqueGroupIdsNPriority size: ", uniqueGroupIdsNPriority.size());
            knLogger.debug(methodName, "dbOnlyCampGrpList size: ", dbOnlyCampGrpList.size());

            //     tgsPersistDTO.setDbCampedGroups(dbCampGrpList);
            //Start of  7.6 and 7.7 client
            //Code for backward compatibility, Only one group can be camped by 7.6 and 7.7 client, Hence adding dbCampGrpList into remove list.
            if (uniqueGroupIdsNPriority.size() > 0 && ipTalkGroupDTO.getClientType() == CLIENT_TYPE_XCAP) {
                removedCampGrpList.addAll(uniqueGroupIdsNPriority);
            }
            //End of  7.6 and 7.7 client

            List<KnXDMTalkGroupInfoDTO> newCampGrpList = new ArrayList<KnXDMTalkGroupInfoDTO>();

            // Adding all the camped group retrieved from DG.CAMPEDGROUPINFO
            newCampGrpList.addAll(uniqueGroupIdsNPriority);

            // Removing the remove list from request
            newCampGrpList.removeAll(removedCampGrpList);

            // Remove the Modified group with old priority
            newCampGrpList.removeAll(modifiedCampGrpList);

            // Modified Group with new priority
            newCampGrpList.addAll(modifiedCampGrpList);

            // Adding the added list from request
            newCampGrpList.addAll(addedCampGrpList);

            tgsPersistDTO.setNewCampedGroups(newCampGrpList);

            // Calling Validation Framework for DTO validation
            if (pttRadioClients&&!ipTalkGroupDTO.isUpmCall()) {
                List<KnXDMTalkGroupInfoDTO> newOnlyCampGrpList = new ArrayList<KnXDMTalkGroupInfoDTO>();
                newOnlyCampGrpList.addAll(dbOnlyCampGrpList);
                newOnlyCampGrpList.removeAll(removedCampGrpList);
                newOnlyCampGrpList.removeAll(modifiedCampGrpList);
                newOnlyCampGrpList.addAll(modifiedCampGrpList);
                newOnlyCampGrpList.addAll(addedCampGrpList);
                List<KnXDMTalkGroupInfoDTO> newOnlyCampGrpListTemp = new ArrayList<KnXDMTalkGroupInfoDTO>();

                for (KnXDMTalkGroupInfoDTO xdmTalkGroupInfoDTO : newOnlyCampGrpList) {
                    if (xdmTalkGroupInfoDTO.getPriority() != null) {
                        newOnlyCampGrpListTemp.add(xdmTalkGroupInfoDTO);
                    }
                }
                tgsPersistDTO.setNewOnlyCampedGroups(newOnlyCampGrpListTemp);


                knLogger.debug(methodName, "pttRadioClients ...");
                tgsPersistDTO.setMaxPttRadioScanGrpLmt(corpProfile.getMaxPttRadioScanSize());
                tgsPersistDTO.setMaxPttRadioChannelGrpLmt(corpProfile.getMaxPttRadioChannelSize());

                ipTalkGroupDTO.setEntityId(CORP_GROUP_MANAGER);
                ipTalkGroupDTO.setOperationType(MODIFY_SUBSCRIBER_SCAN_AND_CHANNEL_LIST);
                ipTalkGroupDTO.setProfile(CORP_PROFILE);
            }
            tgsPersistDTO.setInputDTO(ipTalkGroupDTO);

            List<KnUserprofileSharedlistDTO> upmSharedList = corpUserProfileUtil.getUserProfileSharedListByUpmId(userProfileId, xdmsHome, persisterTxn);
            boolean isUPMSharingEnabled = false;
            if(upmSharedList != null) {
                // sharedCorpList should contains ownerCorpId and sharedCorpId then isUPMSharingEnabled is made true.
                for (KnUserprofileSharedlistDTO getUPMSharedDetails : upmSharedList) {
                    if (Objects.equals(getUPMSharedDetails.getOwnerCorpId(), Integer.valueOf(ipTalkGroupDTO.getCorpId())) && getUPMSharedDetails.getSharedCorpId() == subscriberDTO.getCorpId()) {
                        isUPMSharingEnabled = true;
                        break;
                    }
                }
            }
            knLogger.debug(methodName,"isUPMSharingEnabled :",isUPMSharingEnabled);

            knLogger.debug(methodName, "Before Validation", tgsPersistDTO);
            knLogger.debug(methodName, "newCampGrpList ::", newCampGrpList);
            //Collection<KnCorpAddlTGInfoDTO> subsAddlTGList = groupInfoUtil.getSubsAddlTGList(ipTalkGroupDTO.getMdn(), xdmsHome, persisterTxn);
            tgsPersistDTO.setDbAddlTGList(existingSubsAddlTGList);
            tgsPersistDTO.setClientMajorVersion(subscriberDTO.getClientPVmajorVer());
            tgsPersistDTO.setMcPttId(subscriberDTO.getMcpttId());
            tgsPersistDTO.setMcpttCompliance(subscriberDTO.getMcpttCompliance());
            tgsPersistDTO.setUPMSharingEnabled(isUPMSharingEnabled);
            validatorFW.validate(tgsPersistDTO);
            knLogger.debug(methodName, "Validation Successfull");

            List<KnCorpTalkGrpInfoDTO> newGrpList = new ArrayList<KnCorpTalkGrpInfoDTO>();
            List<KnCorpTalkGrpInfoDTO> newGrpChannelList = new CopyOnWriteArrayList<KnCorpTalkGrpInfoDTO>();


            for (KnXDMTalkGroupInfoDTO talkGroupInfoDTO : newCampGrpList) {
                KnCorpTalkGrpInfoDTO corpTalkGrpInfoDTO = new KnCorpTalkGrpInfoDTO();
                corpTalkGrpInfoDTO.setGroupId(talkGroupInfoDTO.getGroupId());
                if (talkGroupInfoDTO.getPriority() != null) {
                    corpTalkGrpInfoDTO.setPriority(talkGroupInfoDTO.getPriority());
                    newGrpList.add(corpTalkGrpInfoDTO);
                }
                if (talkGroupInfoDTO.getChannel() != null) {
                    corpTalkGrpInfoDTO.setChannel(talkGroupInfoDTO.getChannel());
                }
                newGrpChannelList.add(corpTalkGrpInfoDTO);
               /* if (talkGroupInfoDTO.getChannel() != null) {
                    corpTalkGrpInfoDTO.setChannel(talkGroupInfoDTO.getChannel());
                    newGrpChannelList.add(corpTalkGrpInfoDTO);
                }*/
            }

            Map<String, KnCorpTalkGrpInfoDTO> map = new HashMap<>();
            for (KnCorpTalkGrpInfoDTO t : newGrpChannelList) {
                map.put(t.getGroupId() + ":" + t.getChannel(), t);
            }
            newGrpChannelList.clear();
            newGrpChannelList.addAll(map.values());
            knLogger.debug(methodName, "Unique list ::", newGrpChannelList);
            knLogger.info(methodName, "Unique list ::");

            KnTalkGrpScanMode grpScanMode = groupInfoUtil.getSubsTalkGrpScanMode(ipTalkGroupDTO.getMdn(), xdmsHome, persisterTxn);
            knLogger.debug(methodName, "newGrpChannelList ::", newGrpChannelList);
            knLogger.debug(methodName, "newGrpList ::", newGrpList);
            Map<String, KnOPDirChgDTO> etagMap = new HashMap<String, KnOPDirChgDTO>();

            knLogger.debug(methodName,"grpScanMode: ",grpScanMode);
            if ((grpScanMode == null) && (newGrpChannelList.size() > 0 || newGrpList.size() > 0)) {
                // Preparing Map<String, KnTGSModeChgDTO> for sending SEH
                // Notification, This Map will be use to send notification
                // once transaction is successful
                Integer mode = ipTalkGroupDTO.getMode();
                if (mode == null) {
                    mode = 0;
                }
                groupInfoUtil.createSubsTalkGrpScanMode(ipTalkGroupDTO.getMdn(), mode, xdmsHome, persisterTxn);
                Map<String, KnTGSModeChgDTO> tgsModeChgMap = new HashMap<String, KnTGSModeChgDTO>();
                KnTGSModeChgDTO value = new KnTGSModeChgDTO();
                value.setPocHome(subscriberDTO.getPocHome());
                value.setPresenceHome(subscriberDTO.getPresenceHome());
                value.setTgsMode(mode);
                tgsModeChgMap.put(ipTalkGroupDTO.getMdn(), value);
                respDTO.setTgsModeChgMap(tgsModeChgMap);
                //set Etag for xcap reaponse for new tgsc list
                respDTO.setEtag("1");
                etagMap = commonInfoUtil.formMdnTGSCReplaceNotification(ipTalkGroupDTO.getMdn(), etagMap, xdmsHome, persisterTxn);
                respDTO.setChangeLogMap(etagMap);

            } else if (grpScanMode != null) {
                Integer etag = grpScanMode.getEtag();
                groupInfoUtil.updateSubsTalkGrpScanEtag(ipTalkGroupDTO.getMdn(), ++etag, xdmsHome, persisterTxn);
                respDTO.setEtag(String.valueOf(etag));
            } else if(grpScanMode == null && ipTalkGroupDTO.getMode() == null)
            {
                knLogger.debug("Setting the default val for the scan mode");
                int clusterId = Integer.parseInt(System.getenv(CLUSTERID_ENV_NAME));
                String defaultScanModeValue = genInfoUtil.retrieveMSSvcsCommonConfig(clusterId, persisterTxn).get(DEF_TGSC_MODE);
                Integer mode;
                if(defaultScanModeValue == null)
                {
                    knLogger.debug(methodName,"DEF_TGCS_MODE is not configured");
                    mode = 1;
                }else{
                    mode=Integer.parseInt(defaultScanModeValue);
                }
                groupInfoUtil.createSubsTalkGrpScanMode(ipTalkGroupDTO.getMdn(), mode, xdmsHome, persisterTxn);
                Map<String, KnTGSModeChgDTO> tgsModeChgMap = new HashMap<String, KnTGSModeChgDTO>();
                KnTGSModeChgDTO value = new KnTGSModeChgDTO();
                value.setPocHome(subscriberDTO.getPocHome());
                value.setPresenceHome(subscriberDTO.getPresenceHome());
                value.setTgsMode(mode);
                tgsModeChgMap.put(ipTalkGroupDTO.getMdn(), value);
                respDTO.setTgsModeChgMap(tgsModeChgMap);
                //set Etag for xcap reaponse for new tgsc list
                respDTO.setEtag("1");
                etagMap = commonInfoUtil.formMdnTGSCReplaceNotification(ipTalkGroupDTO.getMdn(), etagMap, xdmsHome, persisterTxn);
                respDTO.setChangeLogMap(etagMap);
            }
            if (pttRadioClients) {
                knLogger.debug(methodName, "existingSubsAddlTGList - ", existingSubsAddlTGList);
                Map<Integer, KnCorpAddlTGInfoDTO> existingAddlTGMap = new HashMap<>();
                for (KnCorpAddlTGInfoDTO dbRecords : existingSubsAddlTGList) {
                    existingAddlTGMap.put(dbRecords.getGroupId(), dbRecords);
                }
                knLogger.debug(methodName, "existingAddlTGMap - ", existingAddlTGMap);
                if (subscriberDTO.getClientPVmajorVer() > 0 && subscriberDTO.getClientPVmajorVer() < PROTOCOL_VERSION_13) {
                    Collection<KnCorpAddlTGInfoDTO> insertAddlGrpLst = new ArrayList<>();
                    Collection<KnCorpAddlTGInfoDTO> modifyAddlGrpLst = new ArrayList<>();
                    Collection<KnCorpAddlTGInfoDTO> deleteAddlGrpLst = new ArrayList<>();
                    for (KnCorpTalkGrpInfoDTO tlkGrp : newGrpChannelList) {
                        KnCorpAddlTGInfoDTO addlTGInfoDTO = new KnCorpAddlTGInfoDTO();
                        KnCorpAddlTGInfoDTO removingAddlTGInfoDTO = new KnCorpAddlTGInfoDTO();
                        if (!existingAddlTGMap.containsKey(tlkGrp.getGroupId())) {
                            addlTGInfoDTO.setMdn(ipTalkGroupDTO.getMdn());
                            addlTGInfoDTO.setGroupId(tlkGrp.getGroupId());
                            addlTGInfoDTO.setZoneId(DEFAULT_ZONE);
                            addlTGInfoDTO.setChannelId(tlkGrp.getChannel());
                            if (tlkGrp.getChannel() != 0) insertAddlGrpLst.add(addlTGInfoDTO);
                        } else {
                            KnCorpAddlTGInfoDTO existAddlGroupDto = existingAddlTGMap.get(tlkGrp.getGroupId());
                            addlTGInfoDTO.setMdn(ipTalkGroupDTO.getMdn());
                            addlTGInfoDTO.setGroupId(tlkGrp.getGroupId());
                            addlTGInfoDTO.setZoneId(existAddlGroupDto.getZoneId());
                            addlTGInfoDTO.setChannelId(tlkGrp.getChannel());
                            if (tlkGrp.getChannel() != 0) {
                                modifyAddlGrpLst.add(addlTGInfoDTO);
                                removingAddlTGInfoDTO.setMdn(ipTalkGroupDTO.getMdn());
                                removingAddlTGInfoDTO.setGroupId(existAddlGroupDto.getGroupId());
                                removingAddlTGInfoDTO.setZoneId(existAddlGroupDto.getZoneId());
                                removingAddlTGInfoDTO.setChannelId(existAddlGroupDto.getChannelId());
                                deleteAddlGrpLst.add(removingAddlTGInfoDTO);
                            }
                        }
                    }
                    for (KnXDMTalkGroupInfoDTO removed : removedCampGrpList) {
                        if (existingAddlTGMap.containsKey(removed.getGroupId())) {
                            deleteAddlGrpLst.add(existingAddlTGMap.get(removed.getGroupId()));
                        }
                    }
                    if (!deleteAddlGrpLst.isEmpty()) {
                        groupInfoUtil.deleteSubsAddlTGList(deleteAddlGrpLst, xdmsHome, persisterTxn);
                    }
                    insertAddlGrpLst.addAll(modifyAddlGrpLst);
                    if (!insertAddlGrpLst.isEmpty()) {
                        groupInfoUtil.insertSubsAddlTGList(insertAddlGrpLst, xdmsHome, persisterTxn);
                    }
                    List<String> mdnList = new ArrayList<>();
                    mdnList.add(ipTalkGroupDTO.getMdn());
                    Map<String, Long> addlEtagmap = groupInfoUtil.getSubsAddlEtagMap(mdnList, xdmsHome, persisterTxn);
                    if (!addlEtagmap.containsKey(ipTalkGroupDTO.getMdn())) {
                        Map<String, Long> subsEtagMap = new HashMap<>();
                        subsEtagMap.put(ipTalkGroupDTO.getMdn(), (long) 1);
                        if (existingAddlTGMap.isEmpty())
                            groupInfoUtil.insertSubsAddlTGDoc(subsEtagMap, xdmsHome, persisterTxn);
                    }
                } else if (subscriberDTO.getClientPVmajorVer() == 0) {
                    Map<Integer, KnCorpAddlTGInfoDTO> zone1AddlTGMap;
                    zone1AddlTGMap = existingSubsAddlTGList.stream().filter(tg -> tg.getZoneId() == DEFAULT_ZONE)
                            .collect(Collectors.toMap(KnCorpAddlTGInfoDTO::getGroupId, exist -> exist));
                    knLogger.debug(methodName, "zone1AddlTGMap - ", zone1AddlTGMap);
                    knLogger.debug(methodName, "mcxGroups - ", mcxGroups);
                    if(!mcxGroups.isEmpty() && zone1AddlTGMap!=null){
                        mcxGroups.forEach(groupId -> zone1AddlTGMap.remove(groupId) );
                    }
                    knLogger.debug(methodName, "zone1AddlTGMap after removing mcx groups - ", zone1AddlTGMap);

                    if (existingAddlTGMap.size() == 0 && zone1AddlTGMap.size() == 0) {
                        //8.3 Client: Assign channel
                        Collection<KnCorpAddlTGInfoDTO> insertAddlGrpLst = new ArrayList<>();
                        for (KnCorpTalkGrpInfoDTO tlkGrp : newGrpChannelList) {
                            KnCorpAddlTGInfoDTO addlTGInfoDTO = new KnCorpAddlTGInfoDTO();
                            addlTGInfoDTO.setMdn(ipTalkGroupDTO.getMdn());
                            addlTGInfoDTO.setGroupId(tlkGrp.getGroupId());
                            addlTGInfoDTO.setZoneId(DEFAULT_ZONE);
                            addlTGInfoDTO.setChannelId(tlkGrp.getChannel());
                            if (tlkGrp.getChannel() != 0) insertAddlGrpLst.add(addlTGInfoDTO);
                        }
                        if (!insertAddlGrpLst.isEmpty()) {
                            groupInfoUtil.insertSubsAddlTGList(insertAddlGrpLst, xdmsHome, persisterTxn);
                        }
                    } else if (existingAddlTGMap.size() == zone1AddlTGMap.size()) {
                        //8.3 Client: Modify Channel
                        Collection<KnCorpAddlTGInfoDTO> insertAddlGrpLst = new ArrayList<>();
                        Collection<KnCorpAddlTGInfoDTO> modifyAddlGrpLst = new ArrayList<>();
                        Collection<KnCorpAddlTGInfoDTO> deleteAddlGrpLst = new ArrayList<>();
                        for (KnCorpTalkGrpInfoDTO tlkGrp : newGrpChannelList) {
                            KnCorpAddlTGInfoDTO addlTGInfoDTO = new KnCorpAddlTGInfoDTO();
                            KnCorpAddlTGInfoDTO removingAddlTGInfoDTO = new KnCorpAddlTGInfoDTO();
                            if (!existingAddlTGMap.containsKey(tlkGrp.getGroupId())) {
                                addlTGInfoDTO.setMdn(ipTalkGroupDTO.getMdn());
                                addlTGInfoDTO.setGroupId(tlkGrp.getGroupId());
                                addlTGInfoDTO.setZoneId(DEFAULT_ZONE);
                                addlTGInfoDTO.setChannelId(tlkGrp.getChannel());
                                if (tlkGrp.getChannel() != 0) insertAddlGrpLst.add(addlTGInfoDTO);
                            } else {
                                KnCorpAddlTGInfoDTO existAddlGroupDto = existingAddlTGMap.get(tlkGrp.getGroupId());
                                addlTGInfoDTO.setMdn(ipTalkGroupDTO.getMdn());
                                addlTGInfoDTO.setGroupId(tlkGrp.getGroupId());
                                addlTGInfoDTO.setZoneId(existAddlGroupDto.getZoneId());
                                addlTGInfoDTO.setChannelId(tlkGrp.getChannel());
                                if (tlkGrp.getChannel() != 0) {
                                    modifyAddlGrpLst.add(addlTGInfoDTO);
                                    removingAddlTGInfoDTO.setMdn(ipTalkGroupDTO.getMdn());
                                    removingAddlTGInfoDTO.setGroupId(existAddlGroupDto.getGroupId());
                                    removingAddlTGInfoDTO.setZoneId(existAddlGroupDto.getZoneId());
                                    removingAddlTGInfoDTO.setChannelId(existAddlGroupDto.getChannelId());
                                    deleteAddlGrpLst.add(removingAddlTGInfoDTO);
                                }
                            }
                        }
                        for (KnXDMTalkGroupInfoDTO removed : removedCampGrpList) {
                            if (existingAddlTGMap.containsKey(removed.getGroupId())) {
                                deleteAddlGrpLst.add(existingAddlTGMap.get(removed.getGroupId()));
                            }
                        }
                        if (!deleteAddlGrpLst.isEmpty() && !modifyAddlGrpLst.isEmpty()) {
                            groupInfoUtil.deleteSubsAddlTGList(deleteAddlGrpLst, xdmsHome, persisterTxn);
                        }
                        insertAddlGrpLst.addAll(modifyAddlGrpLst);
                        if (!insertAddlGrpLst.isEmpty()) {
                            groupInfoUtil.insertSubsAddlTGList(insertAddlGrpLst, xdmsHome, persisterTxn);
                        }
                    }
                    List<String> mdnList = new ArrayList<>();
                    mdnList.add(ipTalkGroupDTO.getMdn());
                    Map<String, Long> addlEtagmap = groupInfoUtil.getSubsAddlEtagMap(mdnList, xdmsHome, persisterTxn);
                    if (!addlEtagmap.containsKey(ipTalkGroupDTO.getMdn())) {
                        Map<String, Long> subsEtagMap = new HashMap<>();
                        subsEtagMap.put(ipTalkGroupDTO.getMdn(), (long) 1);
                        if (existingAddlTGMap.isEmpty())
                            groupInfoUtil.insertSubsAddlTGDoc(subsEtagMap, xdmsHome, persisterTxn);
                    }
                }
            }
            //delete all entries from camped group and insert all.
            groupInfoUtil.deleteSubsCampedGrps(ipTalkGroupDTO.getMdn(), xdmsHome, persisterTxn);
            if (!newGrpList.isEmpty()) {
                groupInfoUtil.createSubsCampedGrps(ipTalkGroupDTO.getMdn(), newGrpList, CAMPED_BY_CORPORATE_ADMIN, xdmsHome, persisterTxn);
            }
            // Update Talk Group Scan Mode
            if (grpScanMode != null && ipTalkGroupDTO.getMode() != null) {
                groupInfoUtil.updateSubsTalkGrpScanMode(ipTalkGroupDTO.getMdn(), ipTalkGroupDTO.getMode(), xdmsHome, persisterTxn);
                if (!grpScanMode.getMode().equals(ipTalkGroupDTO.getMode())) {

                    // Whenever there is change in Mode, Need to send SEH Notification

                    // Preparing Map<String, KnTGSModeChgDTO> for sending SEH
                    // Notification, This Map will be use to send notification
                    // once transaction is successful
                    Map<String, KnTGSModeChgDTO> tgsModeChgMap = new HashMap<String, KnTGSModeChgDTO>();
                    KnTGSModeChgDTO value = new KnTGSModeChgDTO();
                    value.setPocHome(subscriberDTO.getPocHome());
                    value.setPresenceHome(subscriberDTO.getPresenceHome());
                    value.setTgsMode(ipTalkGroupDTO.getMode());
                    tgsModeChgMap.put(ipTalkGroupDTO.getMdn(), value);
                    respDTO.setTgsModeChgMap(tgsModeChgMap);
                }
            }

            // Delete Talk Group Scan Mode
            if ((!pttRadioClients && newGrpList.size() == 0) || (pttRadioClients && newGrpChannelList.size() == 0)) {
                //   if (newGrpList.size() == 0) {
                groupInfoUtil.deleteSubsTalkGrpScanMode(ipTalkGroupDTO.getMdn(), xdmsHome, persisterTxn);
                etagMap = commonInfoUtil.formMdnTGSCDeleteNotification(ipTalkGroupDTO.getMdn(), etagMap, xdmsHome, persisterTxn);
                respDTO.setChangeLogMap(etagMap);
                // Preparing Map<String, KnTGSModeChgDTO> for sending SEH
                // Notification, This Map will be use to send notification
                // once transaction is successful
                Map<String, KnTGSModeChgDTO> tgsModeChgMap = new HashMap<String, KnTGSModeChgDTO>();
                KnTGSModeChgDTO value = new KnTGSModeChgDTO();
                value.setPocHome(subscriberDTO.getPocHome());
                value.setPresenceHome(subscriberDTO.getPresenceHome());
                value.setTgsMode(0);
                tgsModeChgMap.put(ipTalkGroupDTO.getMdn(), value);
                respDTO.setTgsModeChgMap(tgsModeChgMap);
            } else {
                etagMap = commonInfoUtil.formMdnTGSCReplaceNotification(ipTalkGroupDTO.getMdn(), etagMap, xdmsHome, persisterTxn);
                respDTO.setChangeLogMap(etagMap);
            }
            //}
            List<String> mdns = new ArrayList<String>();
            mdns.add(ipTalkGroupDTO.getMdn());
            contactInfoUtil.updateSubscribersDirectory(mdns, etagMap, xdmsHome, persisterTxn);

            populate(respDTO);
        } catch (KnCorpBOException e) {
            knLogger.error(methodName, "KnCorpBOException occured while modify Subscriber ScanList - ", e);
            populate(respDTO, e);
        } catch (KnValidationException e) {
            knLogger.error(methodName, "KnValidationException occured modify Subscriber ScanList - ", e);
            populate(respDTO, e);
        } catch (Exception e) {
            knLogger.error(methodName, "Unexpected Exception occured modify Subscriber ScanList - ", new KnException(KnErrorCodes.BOEntity.INTERNAL_ERROR,
                    e.getMessage(), e));
            populate(respDTO, e);

        }
        return respDTO;
    }

    @Override
    public KnCorpResponseDTO modifyBulkSubscriberScanList(KnIPTalkGroupDTO ipTalkGroupDTO, KnPersisterTxn persisterTxn) {

        String methodName = "modifyBulkSubscriberScanList(KnIPTalkGroupDTO ipTalkGroupDTO, KnPersisterTxn persisterTxn)";
        KnCorpResponseDTO respDTO = new KnCorpResponseDTO();
        KnCorpmgmtTokenvalidation tokenValidation = new KnCorpmgmtTokenvalidation();
        KnSubscriberPersistDTO originator = new KnSubscriberPersistDTO();
        Set<Integer> mcxGroups = new HashSet<>();
        try {
            knLogger.debug(methodName, "Entry :-", ipTalkGroupDTO);

            // Validate if System level scanning bit is enable, i.e. Column: ENABLE_TALKGROUP_SELECT Table: DG.XDMS_SVC_CONFIG
            KnCorpProfileDTO corpProfile = commonInfoUtil.getProfileDetails(String.valueOf(ipTalkGroupDTO.getCorpId()), CORP_PROFILE, false,
                    persisterTxn);
            knLogger.debug(methodName, "Retrieved Corp Profile details - ", corpProfile);

            String xdmsHome = corpProfile.getXdmsHome();

            //Invoking custom hook
            KnCorpHookRespDTO responseDTO;
            Map<String, Object> customParams = ipTalkGroupDTO.getCustomParamMap();
            if (ipTalkGroupDTO.getHierarchyType() == HIERARCHY_TYPE.HIERARCHY && customParams != null) {
                customParams.put(CURRENT_MASTER_LIST_ETAG, corpProfile.getCorpMasterListEtag());
                customParams.put(PERSISTER_TXN, persisterTxn);
                customParams.put(PTT_SERVER_ID, xdmsHome);
                ipTalkGroupDTO.setCustomParamMap(customParams);
                KnCorpHookIPDTO hookIPDTO = new KnCorpHookIPDTO();
                hookIPDTO.setAction(KnActions.ACTIONS.MODIFY_SCAN_LIST);
                hookIPDTO.setData(ipTalkGroupDTO);
                KnProcessInvokerImpl processInvoker = KnProcessInvokerImpl.getInstance();
                Object hookResp = processInvoker.invokeHook(CUSTOM_CORP_USER_HOOK, hookIPDTO);
                if (hookResp instanceof KnCorpHookRespDTO) {
                    responseDTO = (KnCorpHookRespDTO) hookResp;
                    if (com.kodiak.xdms.server.common.resources.KnConstants.RESPONSE_STATUS.FAILURE.value() == responseDTO.getStatus()) {
                        knLogger.error(methodName, "Returning Failure response");
                        populateXdmResponseFroomHook(responseDTO, respDTO);
                        return respDTO;
                    } else {
                        if (responseDTO.getFailedDataList() != null && !responseDTO.getFailedDataList().isEmpty()) {
                            respDTO.setFailedDataList(responseDTO.getFailedDataList());
                        }
                    }
                }
            }
            List<KnXDMTalkGroupInfoDTO> addedCampGrpList = ipTalkGroupDTO.getAddedCampGrpList();
            List<KnXDMTalkGroupInfoDTO> modifiedCampGrpList = ipTalkGroupDTO.getModifiedCampGrpList();
            List<KnXDMTalkGroupInfoDTO> removedCampGrpList = ipTalkGroupDTO.getRemovedCammpGrpList();
            // Etag Validation, Etag in request and Etag in DB must be same
            KnTalkGrpScanMode talkGrpScanMode = groupInfoUtil.getSubsTalkGrpScanMode(ipTalkGroupDTO.getMdn(), xdmsHome, persisterTxn);

            // Subscriber ActiveFS 20 bit must be enable for CAT operation and Subscriber ActiveFS 31 bit must be enable for XCAP operation
            KnCorpSubscriberDTO subscriberDTO = contactInfoUtil.selectPocSubscriberInfo(ipTalkGroupDTO.getMdn(), xdmsHome, persisterTxn);

            //validating mcpttid

            originator.setInputDTO(ipTalkGroupDTO);
            originator.setMcpttID(subscriberDTO.getMcpttId());
            originator.setMcpttCompliance(subscriberDTO.getMcpttCompliance());
            tokenValidation.validateToken(originator);

            // Validate if subscriber is not an external contact to the corporate.
            boolean extCnt = contactInfoUtil.isExternalSubscriber(ipTalkGroupDTO.getMdn(), Integer.parseInt(ipTalkGroupDTO.getCorpId()), xdmsHome, persisterTxn);

            // Validate all the groups in added list belongs to passed corporate
            List<Integer> addedCampedGrpIdList = new ArrayList<Integer>();
            for (KnXDMTalkGroupInfoDTO addedCampGrp : addedCampGrpList) {
                addedCampedGrpIdList.add(addedCampGrp.getGroupId());
            }
            String userProfileId = subscriberDTO.getUserProfileId();
            knLogger.debug(methodName," userProfileId:",userProfileId);
            ArrayList<String> upmId = new ArrayList<>();
            upmId.add(userProfileId);
            Map<String, Integer> upmOwnerList = corpUserProfileUtil.getUserProfileOwnerinfo(upmId, xdmsHome, persisterTxn);
            Integer groupOwnerCorpId=Integer.parseInt(ipTalkGroupDTO.getCorpId());
            Map<Integer, Integer> groupIdTypesMap = null;
            if(!upmOwnerList.isEmpty()){
                groupOwnerCorpId=upmOwnerList.get(userProfileId);
                groupIdTypesMap = groupInfoUtil.getValidGrp(addedCampedGrpIdList,
                        xdmsHome, persisterTxn);
            }
            knLogger.debug(methodName,"ownerCorpId :",groupOwnerCorpId);
            if(groupIdTypesMap == null)
                groupIdTypesMap = groupInfoUtil.getValidGrpInCorp(addedCampedGrpIdList, groupOwnerCorpId,
                        xdmsHome, persisterTxn);
            //changes for group sharing
            //check whether for the given corpId any shared groups are avilable or not
            //if any shared groups are avilable then add shared group info to dbGroupList to avoid rules
            Set<Integer> sharedCorpGrpIds  = new HashSet<>(1);
            Map<Integer,List<KnCorpSharedCorpInfo>> sharedCorpGrpInfoMap = groupInfoUtil.selectGroupSharedCorpInfoBySharedCorpId(groupOwnerCorpId,xdmsHome,persisterTxn);

            if(sharedCorpGrpInfoMap!=null && !sharedCorpGrpInfoMap.isEmpty()) {
                sharedCorpGrpIds = sharedCorpGrpInfoMap.keySet();
                knLogger.debug(methodName, "sharedCorpGrpIds", sharedCorpGrpIds);
            }
            //requested groupId should be validated in add/modify
            List<Integer> grpIdListInCorp = new ArrayList<>(groupIdTypesMap.keySet());
            if (addedCampGrpList != null) {
                List<Integer> addedGroupIds = addedCampGrpList.stream().map(KnXDMTalkGroupInfoDTO::getGroupId).collect(Collectors.toList());
                grpIdListInCorp.addAll(addedGroupIds);
            }

            if (modifiedCampGrpList != null) {
                List<Integer> modifiedGroupIds = modifiedCampGrpList.stream().map(KnXDMTalkGroupInfoDTO::getGroupId).collect(Collectors.toList());
                grpIdListInCorp.addAll(modifiedGroupIds);
            }
            if (removedCampGrpList != null) {
                List<Integer> removedGroupIds = removedCampGrpList.stream().map(KnXDMTalkGroupInfoDTO::getGroupId).collect(Collectors.toList());
                grpIdListInCorp.removeAll(removedGroupIds);
            }
//            tgsPersistDTO.setGrpListInCorp(grpIdListInCorp);
            //To validate the allowed group types
            Set<Integer> grpTypeSet = new HashSet<>(groupIdTypesMap.values());
            boolean pttRadioClients = subscriberDTO.getClientType() == PTTRADIOHANDSETCLIENT || subscriberDTO.getClientType() == PTTRADIOCROSSCARRIERCLIENT
                    || subscriberDTO.getClientType() == PTTRADIOWIFIONLYCLIENT;

            // Validate if MDN is group member in the provided Groups list.
            List<Integer> subsGrpList = groupInfoUtil.getSubsGroupIdList(grpIdListInCorp, ipTalkGroupDTO.getMdn(), xdmsHome, persisterTxn);
            knLogger.debug(methodName, "subsGrpList from GroupMembership table ", subsGrpList);

            List<KnCorpAddlTGInfoDTO> mcxTgList = new ArrayList<>();
            if(userProfileId != null){
                //  KnCorpUserProfileDTO userProfile = corpUserProfileUtil.getUserProfile(String.valueOf(ipTalkGroupDTO.getCorpId()), userProfileId, xdmsHome, persisterTxn);
                Set<KnCorpGroupListInfoDTO> mcxGroupList =corpUserProfileUtil.retriveGroupProfileInfoByProfileId(userProfileId, xdmsHome, persisterTxn);
                knLogger.debug(methodName, "mcxGroupList ", mcxGroupList);
                List<Integer> groupIdListFromProfile = new ArrayList<>();
                if (mcxGroupList != null && mcxGroupList.size() > 0) {
                    groupIdListFromProfile = mcxGroupList.stream().map(KnCorpGroupListInfoDTO::getGroupID).collect(Collectors.toList());
                    knLogger.debug(methodName, "groupIdListFromProfile  ", groupIdListFromProfile);
                }
                Collection<Integer> groupIds = new HashSet<>();
                groupIds.addAll(addedCampedGrpIdList);
                groupIds.addAll(groupIdListFromProfile);
                knLogger.debug(methodName, "Combined input groupIds & profile ", groupIds);
                List<KnCorpGroupDTO> groupInfoList = groupInfoUtil.getGroupBasicInfoList(groupIds, xdmsHome, persisterTxn);
                mcxGroups.addAll(groupInfoList.stream()
                        .filter(groupDetails -> groupDetails.getMcxGrpInd().intValue() == GROUP_SIZE_TYPE.VLARGE_GROUP.value())
                        .map(KnCorpGroupDTO::getGroupId).collect(Collectors.toSet()));
                knLogger.debug(methodName, "mcx groups ", mcxGroups);
                subsGrpList.removeAll(mcxGroups);
                subsGrpList.addAll(mcxGroups);
                knLogger.debug(methodName, "subsGrpList from after merging MCX groups", subsGrpList);
                knLogger.debug(methodName, "mcx groups ", mcxGroups);
                for(KnCorpGroupListInfoDTO info : mcxGroupList){
                    if(mcxGroups.contains(info.getGroupID())) {
                        KnCorpAddlTGInfoDTO tgInfoDTO = new KnCorpAddlTGInfoDTO();
                        tgInfoDTO.setMdn(ipTalkGroupDTO.getMdn());
                        tgInfoDTO.setChannelId(info.getGroupChannel());
                        tgInfoDTO.setZoneId(info.getGroupZone());
                        tgInfoDTO.setGroupId(info.getGroupID());
                        mcxTgList.add(tgInfoDTO);
                    }
                }
                knLogger.debug(methodName, "mcx groups tglist ", mcxTgList);
                //ModifyUPM by adding new group camp info
                List<Integer> finalGroupIdListFromProfile = groupIdListFromProfile;
                List<Integer> newGroupsAddedToProfile = addedCampedGrpIdList.stream().filter(group -> (!(finalGroupIdListFromProfile.contains(group)) && mcxGroups.contains(group))).collect(Collectors.toList());
                knLogger.debug(methodName, "mcx group in addedcampgroup  which not present in CB user profile", newGroupsAddedToProfile);

                if(!newGroupsAddedToProfile.isEmpty()){
                    Map<Integer, KnXDMTalkGroupInfoDTO> tempTalkGroupMap = ipTalkGroupDTO.getAddedCampGrpList().stream()
                            .collect(Collectors.toMap(KnXDMTalkGroupInfoDTO::getGroupId, exist -> exist));
                    for(Integer groupId: newGroupsAddedToProfile){
                        KnCorpAddlTGInfoDTO tgInfoDTO = new KnCorpAddlTGInfoDTO();
                        KnXDMTalkGroupInfoDTO temp = tempTalkGroupMap.get(groupId);
                        tgInfoDTO.setMdn(ipTalkGroupDTO.getMdn());
                        tgInfoDTO.setChannelId(temp.getChannel());
                        tgInfoDTO.setZoneId(temp.getZone());
                        tgInfoDTO.setGroupId(temp.getGroupId());
                        mcxTgList.add(tgInfoDTO);
                    }
                }
            }
            knLogger.debug(methodName, "mcx groups tglist ", mcxTgList);

            List<Integer> brdstGrpIds = groupInfoUtil.getBroadcstGroupList(ipTalkGroupDTO.getMdn(), xdmsHome, persisterTxn);

            // Added List Must not present in DG.CAMPEDGROUPINFO, Modified and Removed Must present in DG.CAMPEDGROUPINFO
            List<KnCorpTGSPersistDTO> corpTGSPersistDTOs = groupInfoUtil.getSubsCampedGrp(ipTalkGroupDTO, xdmsHome, persisterTxn);
            knLogger.debug(methodName, "corpTGSPersistDTOs :", corpTGSPersistDTOs);
            List<KnXDMTalkGroupInfoDTO> dbCampGrpList = new ArrayList<KnXDMTalkGroupInfoDTO>();
            List<KnXDMTalkGroupInfoDTO> dbOnlyCampGrpList = new ArrayList<KnXDMTalkGroupInfoDTO>();
            Collection<KnCorpAddlTGInfoDTO> existingSubsAddlTGList = new ArrayList<>();
            Collection<KnXDMTalkGroupInfoDTO> uniqueGroupIdsNPriority = null;

            if (pttRadioClients) {
                existingSubsAddlTGList = groupInfoUtil.getSubsAddlTGList(ipTalkGroupDTO.getMdn(), xdmsHome, persisterTxn);
                if(!mcxTgList.isEmpty()){
                    existingSubsAddlTGList.addAll(mcxTgList);
                }
                for (KnCorpAddlTGInfoDTO corpChannelpersistDTO : existingSubsAddlTGList) {
                    KnXDMTalkGroupInfoDTO xdmTalkGroupInfoDTO = new KnXDMTalkGroupInfoDTO();
                    xdmTalkGroupInfoDTO.setGroupId(corpChannelpersistDTO.getGroupId());
                    xdmTalkGroupInfoDTO.setChannel(corpChannelpersistDTO.getChannelId());
                    for (KnCorpTGSPersistDTO corpTGSPersistDTO : corpTGSPersistDTOs) {
                        if (corpTGSPersistDTO.getGroupId().equals(corpChannelpersistDTO.getGroupId())) {
                            xdmTalkGroupInfoDTO.setPriority(corpTGSPersistDTO.getPriority());
                        }
                    }
                    dbCampGrpList.add(xdmTalkGroupInfoDTO);
                }

                for (KnCorpTGSPersistDTO corpTGSPersistDTO : corpTGSPersistDTOs) {
                    KnXDMTalkGroupInfoDTO xdmTalkGroupInfoDTO = new KnXDMTalkGroupInfoDTO();
                    xdmTalkGroupInfoDTO.setGroupName(corpTGSPersistDTO.getGroupName());
                    xdmTalkGroupInfoDTO.setGroupId(corpTGSPersistDTO.getGroupId());
                    xdmTalkGroupInfoDTO.setPriority(corpTGSPersistDTO.getPriority());
                    for (KnCorpAddlTGInfoDTO corpChannelpersistDTO : existingSubsAddlTGList) {
                        if (corpTGSPersistDTO.getGroupId().equals(corpChannelpersistDTO.getGroupId())) {
                            xdmTalkGroupInfoDTO.setChannel(corpChannelpersistDTO.getChannelId());
                        }
                    }
                    dbOnlyCampGrpList.add(xdmTalkGroupInfoDTO);
                }
                knLogger.debug(methodName, "dbCampGrpList: ", dbCampGrpList);
                //removing duplicate entry in dbCampGrpList,due to multizone across group,for pv>=16,0,null
                uniqueGroupIdsNPriority = dbCampGrpList.stream()
                        .<Map<Integer, KnXDMTalkGroupInfoDTO>>collect(HashMap::new, (m, e) -> m.put(e.getGroupId(), e), Map::putAll)
                        .values();
                knLogger.debug(methodName, "uniqueGroupIdsNPriority: ", uniqueGroupIdsNPriority);
                knLogger.debug(methodName, "dbOnlyCampGrpList: ", dbOnlyCampGrpList);

            } else {
                for (KnCorpTGSPersistDTO corpTGSPersistDTO : corpTGSPersistDTOs) {
                    KnXDMTalkGroupInfoDTO xdmTalkGroupInfoDTO = new KnXDMTalkGroupInfoDTO();
                    xdmTalkGroupInfoDTO.setGroupName(corpTGSPersistDTO.getGroupName());
                    xdmTalkGroupInfoDTO.setGroupId(corpTGSPersistDTO.getGroupId());
                    xdmTalkGroupInfoDTO.setPriority(corpTGSPersistDTO.getPriority());
                    dbCampGrpList.add(xdmTalkGroupInfoDTO);
                }
                knLogger.debug(methodName, "dbCampGrpList: for CT not radio: ", dbCampGrpList);

                //removing duplicate entry in dbCampGrpList,due to multizone across group,for pv>=16,0,null
                //seems duplicate check, is not required in this case.
                uniqueGroupIdsNPriority = dbCampGrpList.stream()
                        .<Map<Integer, KnXDMTalkGroupInfoDTO>>collect(HashMap::new, (m, e) -> m.put(e.getGroupId(), e), Map::putAll)
                        .values();
                knLogger.debug(methodName, "uniqueGroupIdsNPriority: ", uniqueGroupIdsNPriority);
            }

            knLogger.debug(methodName, "uniqueGroupIdsNPriority size: ", uniqueGroupIdsNPriority.size());
            knLogger.debug(methodName, "dbOnlyCampGrpList size: ", dbOnlyCampGrpList.size());

            //     tgsPersistDTO.setDbCampedGroups(dbCampGrpList);
            //Start of  7.6 and 7.7 client
            //Code for backward compatibility, Only one group can be camped by 7.6 and 7.7 client, Hence adding dbCampGrpList into remove list.
            if (uniqueGroupIdsNPriority.size() > 0 && ipTalkGroupDTO.getClientType() == CLIENT_TYPE_XCAP) {
                removedCampGrpList.addAll(uniqueGroupIdsNPriority);
            }
            //End of  7.6 and 7.7 client

            List<KnXDMTalkGroupInfoDTO> newCampGrpList = new ArrayList<KnXDMTalkGroupInfoDTO>();

            // Adding all the camped group retrieved from DG.CAMPEDGROUPINFO
            newCampGrpList.addAll(uniqueGroupIdsNPriority);

            // Removing the remove list from request
            newCampGrpList.removeAll(removedCampGrpList);

            // Remove the Modified group with old priority
            newCampGrpList.removeAll(modifiedCampGrpList);

            // Modified Group with new priority
            newCampGrpList.addAll(modifiedCampGrpList);

            // Adding the added list from request
            newCampGrpList.addAll(addedCampGrpList);

//            tgsPersistDTO.setNewCampedGroups(newCampGrpList);

            // Calling Validation Framework for DTO validation
            if (pttRadioClients&&!ipTalkGroupDTO.isUpmCall()) {
                List<KnXDMTalkGroupInfoDTO> newOnlyCampGrpList = new ArrayList<KnXDMTalkGroupInfoDTO>();
                newOnlyCampGrpList.addAll(dbOnlyCampGrpList);
                newOnlyCampGrpList.removeAll(removedCampGrpList);
                newOnlyCampGrpList.removeAll(modifiedCampGrpList);
                newOnlyCampGrpList.addAll(modifiedCampGrpList);
                newOnlyCampGrpList.addAll(addedCampGrpList);
                List<KnXDMTalkGroupInfoDTO> newOnlyCampGrpListTemp = new ArrayList<KnXDMTalkGroupInfoDTO>();

                for (KnXDMTalkGroupInfoDTO xdmTalkGroupInfoDTO : newOnlyCampGrpList) {
                    if (xdmTalkGroupInfoDTO.getPriority() != null) {
                        newOnlyCampGrpListTemp.add(xdmTalkGroupInfoDTO);
                    }
                }
//                tgsPersistDTO.setNewOnlyCampedGroups(newOnlyCampGrpListTemp);


                knLogger.debug(methodName, "pttRadioClients ...");

                ipTalkGroupDTO.setEntityId(CORP_GROUP_MANAGER);
                //ipTalkGroupDTO.setOperationType(MODIFY_SUBSCRIBER_SCAN_AND_CHANNEL_LIST);
                ipTalkGroupDTO.setProfile(CORP_PROFILE);
            }

            List<KnUserprofileSharedlistDTO> upmSharedList = corpUserProfileUtil.getUserProfileSharedListByUpmId(userProfileId, xdmsHome, persisterTxn);
            boolean isUPMSharingEnabled = false;
            if(upmSharedList != null) {
                // sharedCorpList should contains ownerCorpId and sharedCorpId then isUPMSharingEnabled is made true.
                for (KnUserprofileSharedlistDTO getUPMSharedDetails : upmSharedList) {
                    if (Objects.equals(getUPMSharedDetails.getOwnerCorpId(), Integer.valueOf(ipTalkGroupDTO.getCorpId())) && getUPMSharedDetails.getSharedCorpId() == subscriberDTO.getCorpId()) {
                        isUPMSharingEnabled = true;
                        break;
                    }
                }
            }
            knLogger.debug(methodName,"isUPMSharingEnabled :",isUPMSharingEnabled);

            knLogger.debug(methodName, "newCampGrpList ::", newCampGrpList);
            knLogger.debug(methodName, "Validation Successfull");

            List<KnCorpTalkGrpInfoDTO> newGrpList = new ArrayList<KnCorpTalkGrpInfoDTO>();
            List<KnCorpTalkGrpInfoDTO> newGrpChannelList = new CopyOnWriteArrayList<KnCorpTalkGrpInfoDTO>();


            for (KnXDMTalkGroupInfoDTO talkGroupInfoDTO : newCampGrpList) {
                KnCorpTalkGrpInfoDTO corpTalkGrpInfoDTO = new KnCorpTalkGrpInfoDTO();
                corpTalkGrpInfoDTO.setGroupId(talkGroupInfoDTO.getGroupId());
                if (talkGroupInfoDTO.getPriority() != null) {
                    corpTalkGrpInfoDTO.setPriority(talkGroupInfoDTO.getPriority());
                    newGrpList.add(corpTalkGrpInfoDTO);
                }
                if (talkGroupInfoDTO.getChannel() != null) {
                    corpTalkGrpInfoDTO.setChannel(talkGroupInfoDTO.getChannel());
                }
                newGrpChannelList.add(corpTalkGrpInfoDTO);
            }

            Map<String, KnCorpTalkGrpInfoDTO> map = new HashMap<>();
            for (KnCorpTalkGrpInfoDTO t : newGrpChannelList) {
                map.put(t.getGroupId() + ":" + t.getChannel(), t);
            }
            newGrpChannelList.clear();
            newGrpChannelList.addAll(map.values());
            knLogger.debug(methodName, "Unique list ::", newGrpChannelList);
            knLogger.info(methodName, "Unique list ::");

            KnTalkGrpScanMode grpScanMode = groupInfoUtil.getSubsTalkGrpScanMode(ipTalkGroupDTO.getMdn(), xdmsHome, persisterTxn);
            knLogger.debug(methodName, "newGrpChannelList ::", newGrpChannelList);
            knLogger.debug(methodName, "newGrpList ::", newGrpList);
            //Map<String, KnOPDirChgDTO> etagMap = new HashMap<String, KnOPDirChgDTO>();

            knLogger.debug(methodName, "grpScanMode: ", grpScanMode, "ipTalkGroupDTO.getOperationType() :", ipTalkGroupDTO.getOperationType());
            if ((grpScanMode == null) && (newGrpChannelList.size() > 0 || newGrpList.size() > 0)) {
                // Preparing Map<String, KnTGSModeChgDTO> for sending SEH
                // Notification, This Map will be use to send notification
                // once transaction is successful
                Integer mode = ipTalkGroupDTO.getMode();
                if (mode == null) {
                    mode = 0;
                }

                if (KnOperationTypes.CLONE_CONTACTS_GROUP_FEATURES_VALIDATION.equalsIgnoreCase(ipTalkGroupDTO.getOperationType())) {
                    groupInfoUtil.createSubsTalkGrpScanMode(ipTalkGroupDTO.getMdn(), mode, xdmsHome, persisterTxn);
                }
                Map<String, KnTGSModeChgDTO> tgsModeChgMap = new HashMap<String, KnTGSModeChgDTO>();
                KnTGSModeChgDTO value = new KnTGSModeChgDTO();
                value.setPocHome(subscriberDTO.getPocHome());
                value.setPresenceHome(subscriberDTO.getPresenceHome());
                value.setTgsMode(mode);
                tgsModeChgMap.put(ipTalkGroupDTO.getMdn(), value);
                respDTO.setTgsModeChgMap(tgsModeChgMap);

            } else if(grpScanMode == null && ipTalkGroupDTO.getMode() == null)
            {
                knLogger.debug("Setting the default val for the scan mode");
                int clusterId = Integer.parseInt(System.getenv(CLUSTERID_ENV_NAME));
                String defaultScanModeValue = genInfoUtil.retrieveMSSvcsCommonConfig(clusterId, persisterTxn).get(DEF_TGSC_MODE);
                Integer mode;
                if(defaultScanModeValue == null)
                {
                    knLogger.debug(methodName,"DEF_TGCS_MODE is not configured");
                    mode = 1;
                }else{
                    mode=Integer.parseInt(defaultScanModeValue);
                }

                if (KnOperationTypes.CLONE_CONTACTS_GROUP_FEATURES_VALIDATION.equalsIgnoreCase(ipTalkGroupDTO.getOperationType())) {
                    groupInfoUtil.createSubsTalkGrpScanMode(ipTalkGroupDTO.getMdn(), mode, xdmsHome, persisterTxn);
                }
                Map<String, KnTGSModeChgDTO> tgsModeChgMap = new HashMap<>();
                KnTGSModeChgDTO value = new KnTGSModeChgDTO();
                value.setPocHome(subscriberDTO.getPocHome());
                value.setPresenceHome(subscriberDTO.getPresenceHome());
                value.setTgsMode(mode);
                tgsModeChgMap.put(ipTalkGroupDTO.getMdn(), value);
                respDTO.setTgsModeChgMap(tgsModeChgMap);
            }
            if (pttRadioClients) {
                knLogger.debug(methodName, "existingSubsAddlTGList - ", existingSubsAddlTGList);
                Map<Integer, KnCorpAddlTGInfoDTO> existingAddlTGMap = new HashMap<>();
                for (KnCorpAddlTGInfoDTO dbRecords : existingSubsAddlTGList) {
                    existingAddlTGMap.put(dbRecords.getGroupId(), dbRecords);
                }
                knLogger.debug(methodName, "existingAddlTGMap - ", existingAddlTGMap);
                if (subscriberDTO.getClientPVmajorVer() > 0 && subscriberDTO.getClientPVmajorVer() < PROTOCOL_VERSION_13) {
                    Collection<KnCorpAddlTGInfoDTO> insertAddlGrpLst = new ArrayList<>();
                    Collection<KnCorpAddlTGInfoDTO> modifyAddlGrpLst = new ArrayList<>();
                    Collection<KnCorpAddlTGInfoDTO> deleteAddlGrpLst = new ArrayList<>();
                    for (KnCorpTalkGrpInfoDTO tlkGrp : newGrpChannelList) {
                        KnCorpAddlTGInfoDTO addlTGInfoDTO = new KnCorpAddlTGInfoDTO();
                        KnCorpAddlTGInfoDTO removingAddlTGInfoDTO = new KnCorpAddlTGInfoDTO();
                        if (!existingAddlTGMap.containsKey(tlkGrp.getGroupId())) {
                            addlTGInfoDTO.setMdn(ipTalkGroupDTO.getMdn());
                            addlTGInfoDTO.setGroupId(tlkGrp.getGroupId());
                            addlTGInfoDTO.setZoneId(DEFAULT_ZONE);
                            addlTGInfoDTO.setChannelId(tlkGrp.getChannel());
                            if (tlkGrp.getChannel() != 0) insertAddlGrpLst.add(addlTGInfoDTO);
                        } else {
                            KnCorpAddlTGInfoDTO existAddlGroupDto = existingAddlTGMap.get(tlkGrp.getGroupId());
                            addlTGInfoDTO.setMdn(ipTalkGroupDTO.getMdn());
                            addlTGInfoDTO.setGroupId(tlkGrp.getGroupId());
                            addlTGInfoDTO.setZoneId(existAddlGroupDto.getZoneId());
                            addlTGInfoDTO.setChannelId(tlkGrp.getChannel());
                            if (tlkGrp.getChannel() != 0) {
                                modifyAddlGrpLst.add(addlTGInfoDTO);
                                removingAddlTGInfoDTO.setMdn(ipTalkGroupDTO.getMdn());
                                removingAddlTGInfoDTO.setGroupId(existAddlGroupDto.getGroupId());
                                removingAddlTGInfoDTO.setZoneId(existAddlGroupDto.getZoneId());
                                removingAddlTGInfoDTO.setChannelId(existAddlGroupDto.getChannelId());
                                deleteAddlGrpLst.add(removingAddlTGInfoDTO);
                            }
                        }
                    }
                    for (KnXDMTalkGroupInfoDTO removed : removedCampGrpList) {
                        if (existingAddlTGMap.containsKey(removed.getGroupId())) {
                            deleteAddlGrpLst.add(existingAddlTGMap.get(removed.getGroupId()));
                        }
                    }
                    if (!deleteAddlGrpLst.isEmpty()) {
                        groupInfoUtil.deleteSubsAddlTGList(deleteAddlGrpLst, xdmsHome, persisterTxn);
                    }
                    insertAddlGrpLst.addAll(modifyAddlGrpLst);
                    if (!insertAddlGrpLst.isEmpty()) {
                        groupInfoUtil.insertSubsAddlTGList(insertAddlGrpLst, xdmsHome, persisterTxn);
                    }
                    List<String> mdnList = new ArrayList<>();
                    mdnList.add(ipTalkGroupDTO.getMdn());
                } else if (subscriberDTO.getClientPVmajorVer() == 0) {
                    Map<Integer, KnCorpAddlTGInfoDTO> zone1AddlTGMap;
                    zone1AddlTGMap = existingSubsAddlTGList.stream().filter(tg -> tg.getZoneId() == DEFAULT_ZONE)
                            .collect(Collectors.toMap(KnCorpAddlTGInfoDTO::getGroupId, exist -> exist));
                    knLogger.debug(methodName, "zone1AddlTGMap - ", zone1AddlTGMap);
                    knLogger.debug(methodName, "mcxGroups - ", mcxGroups);
                    if(!mcxGroups.isEmpty() && zone1AddlTGMap!=null){
                        mcxGroups.forEach(groupId -> zone1AddlTGMap.remove(groupId) );
                    }
                    knLogger.debug(methodName, "zone1AddlTGMap after removing mcx groups - ", zone1AddlTGMap);

                    if (existingAddlTGMap.size() == 0 && zone1AddlTGMap.size() == 0) {
                        //8.3 Client: Assign channel
                        Collection<KnCorpAddlTGInfoDTO> insertAddlGrpLst = new ArrayList<>();
                        for (KnCorpTalkGrpInfoDTO tlkGrp : newGrpChannelList) {
                            KnCorpAddlTGInfoDTO addlTGInfoDTO = new KnCorpAddlTGInfoDTO();
                            addlTGInfoDTO.setMdn(ipTalkGroupDTO.getMdn());
                            addlTGInfoDTO.setGroupId(tlkGrp.getGroupId());
                            addlTGInfoDTO.setZoneId(DEFAULT_ZONE);
                            addlTGInfoDTO.setChannelId(tlkGrp.getChannel());
                            if (tlkGrp.getChannel() != 0) insertAddlGrpLst.add(addlTGInfoDTO);
                        }
                        if (!insertAddlGrpLst.isEmpty()) {
                            groupInfoUtil.insertSubsAddlTGList(insertAddlGrpLst, xdmsHome, persisterTxn);
                        }
                    } else if (existingAddlTGMap.size() == zone1AddlTGMap.size()) {
                        //8.3 Client: Modify Channel
                        Collection<KnCorpAddlTGInfoDTO> insertAddlGrpLst = new ArrayList<>();
                        Collection<KnCorpAddlTGInfoDTO> modifyAddlGrpLst = new ArrayList<>();
                        Collection<KnCorpAddlTGInfoDTO> deleteAddlGrpLst = new ArrayList<>();
                        for (KnCorpTalkGrpInfoDTO tlkGrp : newGrpChannelList) {
                            KnCorpAddlTGInfoDTO addlTGInfoDTO = new KnCorpAddlTGInfoDTO();
                            KnCorpAddlTGInfoDTO removingAddlTGInfoDTO = new KnCorpAddlTGInfoDTO();
                            if (!existingAddlTGMap.containsKey(tlkGrp.getGroupId())) {
                                addlTGInfoDTO.setMdn(ipTalkGroupDTO.getMdn());
                                addlTGInfoDTO.setGroupId(tlkGrp.getGroupId());
                                addlTGInfoDTO.setZoneId(DEFAULT_ZONE);
                                addlTGInfoDTO.setChannelId(tlkGrp.getChannel());
                                if (tlkGrp.getChannel() != 0) insertAddlGrpLst.add(addlTGInfoDTO);
                            } else {
                                KnCorpAddlTGInfoDTO existAddlGroupDto = existingAddlTGMap.get(tlkGrp.getGroupId());
                                addlTGInfoDTO.setMdn(ipTalkGroupDTO.getMdn());
                                addlTGInfoDTO.setGroupId(tlkGrp.getGroupId());
                                addlTGInfoDTO.setZoneId(existAddlGroupDto.getZoneId());
                                addlTGInfoDTO.setChannelId(tlkGrp.getChannel());
                                if (tlkGrp.getChannel() != 0) {
                                    modifyAddlGrpLst.add(addlTGInfoDTO);
                                    removingAddlTGInfoDTO.setMdn(ipTalkGroupDTO.getMdn());
                                    removingAddlTGInfoDTO.setGroupId(existAddlGroupDto.getGroupId());
                                    removingAddlTGInfoDTO.setZoneId(existAddlGroupDto.getZoneId());
                                    removingAddlTGInfoDTO.setChannelId(existAddlGroupDto.getChannelId());
                                    deleteAddlGrpLst.add(removingAddlTGInfoDTO);
                                }
                            }
                        }
                        for (KnXDMTalkGroupInfoDTO removed : removedCampGrpList) {
                            if (existingAddlTGMap.containsKey(removed.getGroupId())) {
                                deleteAddlGrpLst.add(existingAddlTGMap.get(removed.getGroupId()));
                            }
                        }
                        if (!deleteAddlGrpLst.isEmpty()) {
                            groupInfoUtil.deleteSubsAddlTGList(deleteAddlGrpLst, xdmsHome, persisterTxn);
                        }
                        insertAddlGrpLst.addAll(modifyAddlGrpLst);
                        if (!insertAddlGrpLst.isEmpty()) {
                            groupInfoUtil.insertSubsAddlTGList(insertAddlGrpLst, xdmsHome, persisterTxn);
                        }
                    }
                    List<String> mdnList = new ArrayList<>();
                    mdnList.add(ipTalkGroupDTO.getMdn());
                }
            }
            //delete all entries from camped group and insert all.
            groupInfoUtil.deleteSubsCampedGrps(ipTalkGroupDTO.getMdn(), xdmsHome, persisterTxn);
            if (!newGrpList.isEmpty()) {
                groupInfoUtil.createSubsCampedGrps(ipTalkGroupDTO.getMdn(), newGrpList, CAMPED_BY_CORPORATE_ADMIN, xdmsHome, persisterTxn);
            }
            // Update Talk Group Scan Mode
            if (grpScanMode != null && ipTalkGroupDTO.getMode() != null) {
                groupInfoUtil.updateSubsTalkGrpScanMode(ipTalkGroupDTO.getMdn(), ipTalkGroupDTO.getMode(), xdmsHome, persisterTxn);
                if (!grpScanMode.getMode().equals(ipTalkGroupDTO.getMode())) {

                    // Whenever there is change in Mode, Need to send SEH Notification

                    // Preparing Map<String, KnTGSModeChgDTO> for sending SEH
                    // Notification, This Map will be use to send notification
                    // once transaction is successful
                    Map<String, KnTGSModeChgDTO> tgsModeChgMap = new HashMap<String, KnTGSModeChgDTO>();
                    KnTGSModeChgDTO value = new KnTGSModeChgDTO();
                    value.setPocHome(subscriberDTO.getPocHome());
                    value.setPresenceHome(subscriberDTO.getPresenceHome());
                    value.setTgsMode(ipTalkGroupDTO.getMode());
                    tgsModeChgMap.put(ipTalkGroupDTO.getMdn(), value);
                    respDTO.setTgsModeChgMap(tgsModeChgMap);
                }
            }

            // Delete Talk Group Scan Mode
            if ((!pttRadioClients && newGrpList.size() == 0) || (pttRadioClients && newGrpChannelList.size() == 0)) {
                //   if (newGrpList.size() == 0) {
                groupInfoUtil.deleteSubsTalkGrpScanMode(ipTalkGroupDTO.getMdn(), xdmsHome, persisterTxn);
                //etagMap = commonInfoUtil.formMdnTGSCDeleteNotification(ipTalkGroupDTO.getMdn(), etagMap, xdmsHome, persisterTxn);
                //respDTO.setChangeLogMap(etagMap);
                // Preparing Map<String, KnTGSModeChgDTO> for sending SEH
                // Notification, This Map will be use to send notification
                // once transaction is successful
                Map<String, KnTGSModeChgDTO> tgsModeChgMap = new HashMap<String, KnTGSModeChgDTO>();
                KnTGSModeChgDTO value = new KnTGSModeChgDTO();
                value.setPocHome(subscriberDTO.getPocHome());
                value.setPresenceHome(subscriberDTO.getPresenceHome());
                value.setTgsMode(0);
                tgsModeChgMap.put(ipTalkGroupDTO.getMdn(), value);
                respDTO.setTgsModeChgMap(tgsModeChgMap);
            } else {
                //etagMap = commonInfoUtil.formMdnTGSCReplaceNotification(ipTalkGroupDTO.getMdn(), etagMap, xdmsHome, persisterTxn);
                //respDTO.setChangeLogMap(etagMap);
            }
            //}
            List<String> mdns = new ArrayList<String>();
            mdns.add(ipTalkGroupDTO.getMdn());
            //contactInfoUtil.updateSubscribersDirectory(mdns, etagMap, xdmsHome, persisterTxn);

            populate(respDTO);
        } catch (KnCorpBOException e) {
            knLogger.error(methodName, "KnCorpBOException occured while modify Subscriber ScanList - ", e);
            populate(respDTO, e);
        } catch (KnValidationException e) {
            knLogger.error(methodName, "KnValidationException occured modify Subscriber ScanList - ", e);
            populate(respDTO, e);
        } catch (Exception e) {
            knLogger.error(methodName, "Unexpected Exception occured modify Subscriber ScanList - ", new KnException(KnErrorCodes.BOEntity.INTERNAL_ERROR,
                    e.getMessage(), e));
            populate(respDTO, e);

        }
        return respDTO;
    }

    /**
     * getSubscriberScanList is a API for reteriving scan list of a subscriber
     * Validation:
     * 1)	Etag Validation, Etag in request and Etag in DB must not be same
     * 2)	Subscriber ActiveFS 20 bit must be enable
     * 3)	Validate if MDN's Client Type is not Inter-op Or Dispatch
     * 4)	Subscriber should be part of the CorpID
     */
    @Override
    public KnXDMTalkGroupServerRespDTO getSubscriberScanList(KnIPTalkGroupDTO ipTalkGroupDTO, KnPersisterTxn persisterTxn) {
        String methodName = "getSubscriberScanList(KnIPTalkGroupDTO ipTalkGroupDTO, KnPersisterTxn persisterTxn)";
        KnXDMTalkGroupServerRespDTO xdmTalkGroupRespDTO = new KnXDMTalkGroupServerRespDTO();
        KnSubscriberPersistDTO originator = new KnSubscriberPersistDTO();
        KnCorpmgmtTokenvalidation validateToken = new KnCorpmgmtTokenvalidation();
        try {
            KnCorpProfileDTO corpProfile = commonInfoUtil.getProfileDetails(String.valueOf(ipTalkGroupDTO.getCorpId()), CORP_PROFILE, false,
                    persisterTxn);
            knLogger.debug(methodName, "Retrieved Corp Profile details - ", corpProfile);
            String xdmsHome = corpProfile.getXdmsHome();
            KnSubsProfileDTO subscProfile = commonInfoUtil.getProfileDetails(ipTalkGroupDTO.getMdn(), KnProfileTypes.PUBLIC_PROFILE,
                    false, persisterTxn);
            if (null != ipTalkGroupDTO.getCorpId() && Integer.parseInt(ipTalkGroupDTO.getCorpId()) > 0 && subscProfile.getCorpId() != Integer.parseInt(ipTalkGroupDTO.getCorpId())) {
                throw new KnCorpBOException(KnErrorCodes.BOEntity.SUBSCRIBER_DOES_NOT_BELONG_TO_CORP,
                        "Subscribers Does not belong to the corporation.");
            }
            //Invoking custom hook
            KnCorpHookRespDTO responseDTO = new KnCorpHookRespDTO();
            Map<String, Object> customParams = ipTalkGroupDTO.getCustomParamMap();
            if (ipTalkGroupDTO.getHierarchyType() == HIERARCHY_TYPE.HIERARCHY) {
                if (customParams != null) {
                    contactInfoUtil.checkValidHierarchySubs(Collections.singletonList(ipTalkGroupDTO.getMdn()), customParams, xdmsHome, persisterTxn);
                    customParams.put(CURRENT_MASTER_LIST_ETAG, corpProfile.getCorpMasterListEtag());
                    customParams.put(PERSISTER_TXN, persisterTxn);
                    customParams.put(PTT_SERVER_ID, xdmsHome);
                    ipTalkGroupDTO.setCustomParamMap(customParams);
                    KnCorpHookIPDTO hookIPDTO = new KnCorpHookIPDTO();
                    hookIPDTO.setAction(KnActions.ACTIONS.GET_SCAN_LIST);
                    hookIPDTO.setData(ipTalkGroupDTO);
                    KnProcessInvokerImpl processInvoker = KnProcessInvokerImpl.getInstance();
                    Object hookResp = processInvoker.invokeHook(CUSTOM_CORP_USER_HOOK, hookIPDTO);
                    if (hookResp instanceof KnCorpHookRespDTO) {
                        responseDTO = (KnCorpHookRespDTO) hookResp;
                        if (com.kodiak.xdms.server.common.resources.KnConstants.RESPONSE_STATUS.FAILURE.value() == responseDTO.getStatus()) {
                            knLogger.error(methodName, "Returning Failure response");
                            populateXdmResponseFroomHook(responseDTO, xdmTalkGroupRespDTO);
                            return xdmTalkGroupRespDTO;
                        } else {
                            if (responseDTO.getFailedDataList() != null && !responseDTO.getFailedDataList().isEmpty()) {
                                xdmTalkGroupRespDTO.setFailedDataList(responseDTO.getFailedDataList());
                            }
                        }
                    }
                }
            }

            KnCorpTGSPersistDTO corpTGSPersistDTO1 = new KnCorpTGSPersistDTO();
            if (corpProfile.getTgscanningClient() == 1) {
                corpTGSPersistDTO1.setSystemTgscanningClientBitEanble(true);
            }

            // Subscriber ActiveFS 20 bit must be enable
            KnCorpSubscriberDTO subscriberDTO = contactInfoUtil.selectPocSubscriberInfo(ipTalkGroupDTO.getMdn(), xdmsHome, true, persisterTxn);
            boolean tgsServerBit = KnGeneralUtil.getFeatureBitValue(subscriberDTO.getSubsActiveFS2(), com.kodiak.xdms.server.common.resources.KnConstants.SUBS_TGS_SERVER_BIT);
            //boolean pttRadioClients = KnGeneralUtil.getFeatureBitValue(subscriberDTO.getSubsActiveFS(), com.kodiak.xdms.server.common.resources.KnConstants.SUBS_PTTRADIOCLIENT_SERVER_BIT);

            boolean pttRadioClients = subscriberDTO.getClientType() == PTTRADIOHANDSETCLIENT || subscriberDTO.getClientType() == PTTRADIOCROSSCARRIERCLIENT
                    || subscriberDTO.getClientType() == PTTRADIOWIFIONLYCLIENT;

            corpTGSPersistDTO1.setTGSSerBitEanble(tgsServerBit);
            corpTGSPersistDTO1.setInputDTO(ipTalkGroupDTO);
            corpTGSPersistDTO1.setMcPttId(subscriberDTO.getMcpttId());
            corpTGSPersistDTO1.setMcpttCompliance(subscriberDTO.getMcpttCompliance());
            corpTGSPersistDTO1.setActiveFS2(subscriberDTO.getSubsActiveFS2());
            // Subscriber should be part of the CorpID
            corpTGSPersistDTO1.setSubsCorpId(subscriberDTO.getCorpId());
            KnTalkGrpScanMode talkGrpScanMode = groupInfoUtil.getSubsTalkGrpScanMode(ipTalkGroupDTO.getMdn(), xdmsHome, true, persisterTxn);
            corpTGSPersistDTO1.setActiveFS2(subscriberDTO.getSubsActiveFS2());
            // Etag Validation, Etag in request and Etag in DB must not be same
            if (talkGrpScanMode != null) {
                corpTGSPersistDTO1.setEtag(String.valueOf(talkGrpScanMode.getEtag()));
            }
            // Validate if MDN's Client Type is not Inter-op Or Dispatch
            corpTGSPersistDTO1.setSubsClientType(subscriberDTO.getClientType());

            //validate mcPttId from token

            originator.setInputDTO(ipTalkGroupDTO);
            originator.setMcpttID(subscriberDTO.getMcpttId());
            originator.setMcpttCompliance(subscriberDTO.getMcpttCompliance());
            validateToken.validateToken(originator);


            knLogger.debug(methodName, "Before Validation", corpTGSPersistDTO1);
            validatorFW.validate(corpTGSPersistDTO1);
            knLogger.debug(methodName, "Validation Successfull");
            List<KnCorpTGSPersistDTO> corpTGSPersistDTOs;
            Map<Integer, Integer> priorityGroupIdMap = new HashMap<>();
            Collection<KnCorpAddlTGInfoDTO> subsAddlTGList = new ArrayList<>();
            corpTGSPersistDTOs = groupInfoUtil.getSubsCampedGrp(ipTalkGroupDTO, xdmsHome, true, persisterTxn);
            //List<KnCorpTGSPersistDTO> corpChannelPersistDTOs = new ArrayList<>();
            List<Integer> groupIDList = new ArrayList<>();
// for pttRadio clients, channel will bigger list than scan list. Hence get all groups fron channel
            if (pttRadioClients) {
                //corpChannelPersistDTOs = groupInfoUtil.getSubsChannelGrp(ipTalkGroupDTO, xdmsHome, persisterTxn);
                subsAddlTGList = groupInfoUtil.getSubsAddlTGList(ipTalkGroupDTO.getMdn(), xdmsHome, true, persisterTxn);
                String userProfileId = subscriberDTO.getUserProfileId();
                knLogger.debug(methodName, " userprofileId - ", userProfileId);
                if(userProfileId!=null){
                    // KnCorpUserProfileDTO userProfile = corpUserProfileUtil.getUserProfile(String.valueOf(ipTalkGroupDTO.getCorpId()), userProfileId, xdmsHome, persisterTxn);

                    Set<KnCorpGroupListInfoDTO> mcxGroupList = corpUserProfileUtil.retriveGroupProfileInfoByProfileId(userProfileId, xdmsHome, true, persisterTxn);
                    knLogger.debug(methodName, "mcxGroupList ", mcxGroupList);
                    if (mcxGroupList != null && mcxGroupList.size() > 0) {
                        List<Integer> groupIdListFromProfile = mcxGroupList.stream().map(KnCorpGroupListInfoDTO::getGroupID).collect(Collectors.toList());
                        knLogger.debug(methodName, "groupIdListFromProfile  ", groupIdListFromProfile);
                        List<KnCorpGroupDTO> groupInfoList = groupInfoUtil.getGroupBasicInfoList(groupIdListFromProfile, xdmsHome, true, persisterTxn);

                        for(KnCorpGroupListInfoDTO info : mcxGroupList){

                            KnCorpAddlTGInfoDTO tgInfoDTO = new KnCorpAddlTGInfoDTO();
                            tgInfoDTO.setMdn(ipTalkGroupDTO.getMdn());
                            tgInfoDTO.setChannelId(info.getGroupChannel());
                            tgInfoDTO.setZoneId(info.getGroupZone());
                            tgInfoDTO.setGroupId(info.getGroupID());
                            subsAddlTGList.add(tgInfoDTO);

                        }

                    }
                    knLogger.debug(methodName, "subsGrpList from GroupMembership table ", subsAddlTGList);
                }
                knLogger.debug(methodName, "subsAddlTGList from db - ", subsAddlTGList, "camped group list - ", corpTGSPersistDTOs);
                if (subscriberDTO.getClientPVmajorVer() > 0 && subscriberDTO.getClientPVmajorVer() < PROTOCOL_VERSION_13
                        && ipTalkGroupDTO.getOperationType().equals(GET_SUBSCRIBER_SCAN_LIST_XCAP)) {
                    for (KnCorpTGSPersistDTO corpTGSPersistDTO : corpTGSPersistDTOs) {
                        priorityGroupIdMap.put(corpTGSPersistDTO.getGroupId(), corpTGSPersistDTO.getPriority());
                        groupIDList.add(corpTGSPersistDTO.getGroupId());
                    }
                    for (KnCorpAddlTGInfoDTO subsAddlTalkgroup : subsAddlTGList) {
                        groupIDList.add(subsAddlTalkgroup.getGroupId());
                    }
                } else {
                    for (KnCorpAddlTGInfoDTO corpTGSPersistDTO : subsAddlTGList) {
                        groupIDList.add(corpTGSPersistDTO.getGroupId());
                    }
                }
            } else {
                for (KnCorpTGSPersistDTO corpTGSPersistDTO : corpTGSPersistDTOs) {
                    groupIDList.add(corpTGSPersistDTO.getGroupId());
                }
            }

            List<KnXDMTalkGroupInfoDTO> campGrpList = new ArrayList<KnXDMTalkGroupInfoDTO>();

            knLogger.debug(methodName, "GroupIDList", groupIDList);
            Map<Integer, KnCorpGroupInfoPersistDTO> groupInfoMap = groupInfoUtil.getGroupDisplayNameCorpIdMapInfo(groupIDList, xdmsHome, true, persisterTxn);
            knLogger.debug(methodName, "GroupIDMAPName", groupInfoMap);

            if (pttRadioClients) {
                if (subscriberDTO.getClientPVmajorVer() > 0 && subscriberDTO.getClientPVmajorVer() < PROTOCOL_VERSION_13
                        && ipTalkGroupDTO.getOperationType().equals(GET_SUBSCRIBER_SCAN_LIST_XCAP)) {
                    for (KnCorpAddlTGInfoDTO corpTGSPersistDTO : subsAddlTGList) {
                        KnXDMTalkGroupInfoDTO xdmTalkGroupInfoDTO = new KnXDMTalkGroupInfoDTO();
                        if (corpTGSPersistDTO.getZoneId() == 1) {
                            int groupId = corpTGSPersistDTO.getGroupId();
                            xdmTalkGroupInfoDTO.setGroupId(groupId);
                            Integer priority = priorityGroupIdMap.get(groupId);
                            xdmTalkGroupInfoDTO.setPriority(com.kodiak.xdms.server.common.resources.KnConstants.NO_PRIORITY);
                            if (priority != null) {
                                xdmTalkGroupInfoDTO.setPriority(priorityGroupIdMap.get(groupId));
                            }
                            xdmTalkGroupInfoDTO.setChannel(corpTGSPersistDTO.getChannelId());
                            if (groupInfoMap.get(groupId) != null) {
                                xdmTalkGroupInfoDTO.setGroupName(groupInfoMap.get(groupId).getGroupDisplayName());
                                xdmTalkGroupInfoDTO.setCorpId(groupInfoMap.get(groupId).getCorpId());
                            }
                            campGrpList.add(xdmTalkGroupInfoDTO);
                        }
                    }
                    knLogger.debug(methodName, "campGrpList1", campGrpList);
                } else {
                    for (KnCorpAddlTGInfoDTO corpTGSPersistDTO : subsAddlTGList) {
                        KnXDMTalkGroupInfoDTO xdmTalkGroupInfoDTO = new KnXDMTalkGroupInfoDTO();
                        int groupId = corpTGSPersistDTO.getGroupId();
                        xdmTalkGroupInfoDTO.setGroupId(groupId);
                        xdmTalkGroupInfoDTO.setChannel(corpTGSPersistDTO.getChannelId());
                        xdmTalkGroupInfoDTO.setGroupName(groupInfoMap.get(groupId).getGroupDisplayName());
                        xdmTalkGroupInfoDTO.setCorpId(groupInfoMap.get(groupId).getCorpId());
                        xdmTalkGroupInfoDTO.setPriority(com.kodiak.xdms.server.common.resources.KnConstants.NO_PRIORITY);
                        for (KnCorpTGSPersistDTO corpTGSPersistDTO2 : corpTGSPersistDTOs) {
                            if (corpTGSPersistDTO2.getGroupId().equals(corpTGSPersistDTO.getGroupId())) {
                                xdmTalkGroupInfoDTO.setPriority(corpTGSPersistDTO2.getPriority());
                            }
                        }
                        if ((subscriberDTO.getClientPVmajorVer() > 0 && subscriberDTO.getClientPVmajorVer() < PROTOCOL_VERSION_13) && corpTGSPersistDTO.getZoneId() == 1) {
                            campGrpList.add(xdmTalkGroupInfoDTO);
                        }
                        if (subscriberDTO.getClientPVmajorVer() == 0 || subscriberDTO.getClientPVmajorVer() >= PROTOCOL_VERSION_13) {
                            campGrpList.add(xdmTalkGroupInfoDTO);
                        }
                        knLogger.debug(methodName, "campGrpList2", campGrpList);
                    }
                }
            } else {
                for (KnCorpTGSPersistDTO corpTGSPersistDTO : corpTGSPersistDTOs) {
                    KnXDMTalkGroupInfoDTO xdmTalkGroupInfoDTO = new KnXDMTalkGroupInfoDTO();
                    int groupId = corpTGSPersistDTO.getGroupId();
                    xdmTalkGroupInfoDTO.setGroupId(groupId);
                    xdmTalkGroupInfoDTO.setPriority(corpTGSPersistDTO.getPriority());
                    xdmTalkGroupInfoDTO.setGroupName(groupInfoMap.get(groupId).getGroupDisplayName());
                    xdmTalkGroupInfoDTO.setCorpId(groupInfoMap.get(groupId).getCorpId());
                    campGrpList.add(xdmTalkGroupInfoDTO);
                    knLogger.debug(methodName, "campGrpList3", campGrpList);
                }
            }
            knLogger.debug(methodName, "Scan List size", campGrpList.size());
            if (tgsServerBit) {
                xdmTalkGroupRespDTO.setScanningEnabled(1);
            } else {
                xdmTalkGroupRespDTO.setScanningEnabled(2);
            }
            knLogger.debug(methodName," campGrpList :- ",campGrpList);
            Collection<KnXDMTalkGroupInfoDTO> uniqueCampedGrpList=new ArrayList<>();
            if(campGrpList!=null&&!campGrpList.isEmpty()){
                uniqueCampedGrpList = campGrpList.stream()
                        .<Map<Integer, KnXDMTalkGroupInfoDTO>> collect(HashMap::new,(m,e)->m.put(e.getGroupId(), e), Map::putAll)
                        .values();
            }
            knLogger.debug(methodName,"uniqueCampedGrpList :",uniqueCampedGrpList);
            xdmTalkGroupRespDTO.setCampGrpList(new ArrayList<>(uniqueCampedGrpList));
            if (talkGrpScanMode != null) {
                if (talkGrpScanMode.getMode() != null) {
                    xdmTalkGroupRespDTO.setMode(talkGrpScanMode.getMode());
                    xdmTalkGroupRespDTO.setEtag(String.valueOf(talkGrpScanMode.getEtag()));
                    if (pttRadioClients) {
                        xdmTalkGroupRespDTO.setCampModeCap(talkGrpScanMode.getMode());
                    }

                }
            }

            populate(xdmTalkGroupRespDTO);
        } catch (KnValidationException e) {
            populate(xdmTalkGroupRespDTO, e);
            knLogger.error(methodName, "KnValidationException occured while getSubscriberScanList", e);
        } catch (KnCorpBOException e) {
            populate(xdmTalkGroupRespDTO, e);
            knLogger.error(methodName, "KnCorpBOException occured while getSubscriberScanList", e);
        } catch (Exception e) {
            knLogger.error(methodName, "Unexpected exception occured while getSubscriberScanList ", new KnException(
                    KnErrorCodes.BOEntity.INTERNAL_ERROR, e.getMessage(), e));
        }
        return xdmTalkGroupRespDTO;
    }

    /**
     * This method will be used to clean up camped groups and scan mode for a
     * particular subscriber, isModeChange attribute is KnCorpTalkGroupRespDTO,
     * can be used to send the SEH notofication, if its true need to send the
     * notification
     */
    @Override
    public KnCorpTalkGroupRespDTO deleteSubsCampedGrps(KnIPSubsDTO ipSubsDTO, KnPersisterTxn persisterTxn) {
        String methodName = "deleteSubsCampedGrps(mdn, persisterTxn)";
        KnCorpTalkGroupRespDTO respDTO = new KnCorpTalkGroupRespDTO();
        Map<String, KnOPDirChgDTO> etagMap = new HashMap<String, KnOPDirChgDTO>();
        try {
            KnSubsProfileDTO subsProfile = commonInfoUtil.getProfileDetails(ipSubsDTO.getMdn(), PUBLIC_PROFILE, false,
                    persisterTxn);
            boolean isModeChange = groupInfoUtil.cleanUpSubsCampedGrps(ipSubsDTO.getMdn(), subsProfile.getXdmsHome(),
                    persisterTxn);
            etagMap = commonInfoUtil.formMdnTGSCDeleteNotification(ipSubsDTO.getMdn(), etagMap, subsProfile.getXdmsHome(),
                    persisterTxn);
            respDTO.setChangeLogMap(etagMap);
            populate(respDTO);
            respDTO.setModeChange(isModeChange);
        } catch (KnCorpBOException e) {
            knLogger.error(methodName, "KnCorpBOException occured while deleteSubsCampedGrps - ", e);
            populate(respDTO, e);
        } catch (Exception e) {
            knLogger.error(methodName, "Unexpected Exception occured deleteSubsCampedGrps - ", new KnException(KnErrorCodes.BOEntity.INTERNAL_ERROR,
                    e.getMessage(), e));
            populate(respDTO, e);
        }
        return respDTO;
    }

    @Override
    public KnCorpResponseDTO deleteSubscriberScanList(KnIPTalkGroupDTO ipSubsDTO, KnPersisterTxn persisterTxn) {
        String methodName = "deleteSubscriberScanList(KnIPTalkGroupDTO ipTalkGroupDTO, KnPersisterTxn persisterTxn)";
        KnCorpTalkGroupRespDTO respDTO = new KnCorpTalkGroupRespDTO();
        Map<String, KnOPDirChgDTO> etagMap = new HashMap<String, KnOPDirChgDTO>();
        try {
            KnCorpTGSPersistDTO tgsPersistDTO = new KnCorpTGSPersistDTO();
            KnCorpmgmtTokenvalidation validator = new KnCorpmgmtTokenvalidation();
            // Validate if Subscriber exists
            KnSubsProfileDTO subsProfile = commonInfoUtil.getProfileDetails(ipSubsDTO.getMdn(), PUBLIC_PROFILE, false, persisterTxn);
            KnSubscriberPersistDTO originator = new KnSubscriberPersistDTO();
            tgsPersistDTO.setServiceAuthStatus(subsProfile.getServiceAuthStatus());
            // Validate if System level scanning bit is enable, i.e. Column:
            // ENABLE_TGSCANNING_CLIENT Table: DG.XDMS_SVC_CONFIG
            KnCorpProfileDTO corpProfile = commonInfoUtil.getProfileDetails(String.valueOf(ipSubsDTO.getCorpId()), CORP_PROFILE, false, persisterTxn);
            knLogger.debug(methodName, "Retrieved Corp Profile details - ", corpProfile);
            if (corpProfile.getTgscanningClient() == 1) {
                tgsPersistDTO.setSystemTgscanningClientBitEanble(true);
            }

            String xdmsHome = corpProfile.getXdmsHome();

            // Verify Scanlist document exists for the Subscriber TODO if required we will add

            // Subscriber ActiveFS 28 bit must be enable for XCAP operation
            KnCorpSubscriberDTO subscriberDTO = contactInfoUtil.selectPocSubscriberInfo(ipSubsDTO.getMdn(), xdmsHome, persisterTxn);
            tgsPersistDTO.setActiveFS2(subscriberDTO.getSubsActiveFS2());

            // Etag Validation, Etag in request and Etag in DB must be same
            KnTalkGrpScanMode talkGrpScanMode = groupInfoUtil.getSubsTalkGrpScanMode(ipSubsDTO.getMdn(), xdmsHome, persisterTxn);
            if (talkGrpScanMode != null) {
                tgsPersistDTO.setEtag(String.valueOf(talkGrpScanMode.getEtag()));
            } else {
                // If Document doesn't exist then setting the request request, set etag value to null
                tgsPersistDTO.setEtag(null);
            }

            // Validate if scan mode is set to 1.
            if (talkGrpScanMode != null) {
                tgsPersistDTO.setScanMode(talkGrpScanMode.getMode());
            } else {
                tgsPersistDTO.setScanMode(1);
            }

            // Validate if MDN's Client Type is not Inter-op Or Dispatch
            tgsPersistDTO.setSubsClientType(subscriberDTO.getClientType());

            tgsPersistDTO.setInputDTO(ipSubsDTO);
            // Calling Validation Framework for DTO validation
            knLogger.debug(methodName, "Before Validation", tgsPersistDTO);
            originator.setInputDTO(ipSubsDTO);
            originator.setMcpttCompliance(subsProfile.getMcpttCompliance());
            originator.setMcpttID(subsProfile.getMcpttId());
            validator.validateToken(originator);
            validatorFW.validate(tgsPersistDTO);
            knLogger.debug(methodName, "Validation Successfull");

            boolean isModeChange = groupInfoUtil.cleanUpSubsCampedGrps(ipSubsDTO.getMdn(), subsProfile.getXdmsHome(), persisterTxn);
            etagMap = commonInfoUtil.formMdnTGSCDeleteNotification(ipSubsDTO.getMdn(), etagMap, subsProfile.getXdmsHome(), persisterTxn);
            respDTO.setChangeLogMap(etagMap);
            respDTO.setModeChange(isModeChange);
            populate(respDTO);
        } catch (KnCorpBOException e) {
            knLogger.error(methodName, "KnCorpBOException occured while deleteS Subscriber ScanList - ", e);
            populate(respDTO, e);
        } catch (KnValidationException e) {
            knLogger.error(methodName, "KnValidationException occured deleteS Subscriber ScanList - ", e);
            populate(respDTO, e);
        } catch (Exception e) {
            knLogger.error(methodName, "Unexpected Exception occured deleteS Subscriber ScanList - ", new KnException(KnErrorCodes.BOEntity.INTERNAL_ERROR, e.getMessage(), e));
            populate(respDTO, e);
        }
        return respDTO;
    }

    /**
     * This method is to create Broadcast Group
     *
     * @param groupInfoDTO
     * @param persisterTxn
     * @return
     */
    public KnCorpGroupInfoRespDTO createBCGroup(KnIPCorpGroupInfoDTO groupInfoDTO, KnPersisterTxn persisterTxn) {

        String methodName = "createBCGroup(KnIPCorpGroupInfoDTO, KnPersisterTxn)";
        knLogger.info(methodName, "ENTRY : Input DTO Passed - ", groupInfoDTO);
        KnCorpGroupInfoRespDTO respDto = new KnCorpGroupInfoRespDTO();
        String xdmsHome = "";
        try {
            int corpId = groupInfoDTO.getCorpId();

            int clusterId = Integer.parseInt(System.getenv(CLUSTERID_ENV_NAME));
            Map<String, String> paramNameValueMapCommon = genInfoUtil.retrieveMSSvcsCommonConfig(clusterId, persisterTxn);
            String pochomeAutoAssignValue = paramNameValueMapCommon.get(POCHOME_AUTOASSIGN_FLAG);
            boolean pochomeAutoAssignFlag = true;
            if (pochomeAutoAssignValue != null) {
                try {
                    pochomeAutoAssignFlag = Integer.parseInt(pochomeAutoAssignValue) == ENABLED;
                } catch (NumberFormatException e) {
                    knLogger.warn(methodName, "Invalid pochomeAutoAssignValue: ", pochomeAutoAssignValue);
                }
            }
            knLogger.debug(methodName," pochomeAutoAssignFlag : ",pochomeAutoAssignFlag);

            // TP Dynamic group changes
            List<String> tpMdnList = null;
            Map<String, KnCorpSubscriberDTO> tpDBSubMap = null;
            if (groupInfoDTO.getClientType() == DYNAMIC_CGMT_INTF) {
                tpMdnList = new ArrayList<>();
                String tpRequestMDN = groupInfoDTO.getTpRequestMdn();
                String tpGroupOwner = groupInfoDTO.getTpGroupOwner();
                tpMdnList.add(tpRequestMDN);
                tpMdnList.add(tpGroupOwner);

                String pttServerID = genInfoUtil.retrieveLocalXDMPttServerId();
                tpDBSubMap = contactInfoUtil.getPoCSubscriberCorporateDetails(tpMdnList, pttServerID, persisterTxn);
                if (tpDBSubMap.get(tpRequestMDN) != null) {
                    corpId = tpDBSubMap.get(tpRequestMDN).getCorpId();
                    groupInfoDTO.setCorpId(corpId);
                }
            }

            //Step:
            //get the Corp profile details from cache
            knLogger.debug(methodName, "Fetch the corpProfile profile if cached or fetch from the DB the details");
            KnCorpProfileDTO corpProfile = commonInfoUtil.getProfileDetails("" + corpId, CORP_PROFILE, true, persisterTxn);
            xdmsHome = corpProfile.getXdmsHome();
            String pocHome = corpProfile.getPocHome();
            int intCorpId = corpProfile.getCorpId();
            String extCorpId = corpProfile.getExtCorpId();
            String networkName = corpProfile.getNetworkName();


            Collection<KnSIPProxySvcConfigDTO> sipProxySvcConfigInfoDTO = commonInfoUtil.getSipProxySvcConfig(xdmsHome, persisterTxn);
            //Invoking custom hook
            KnCorpHookRespDTO responseDTO = new KnCorpHookRespDTO();
            Map<String, Object> customParams = groupInfoDTO.getCustomParamMap();
            if (groupInfoDTO.getHierarchyType() == HIERARCHY_TYPE.HIERARCHY && null != customParams) {
                knLogger.debug(methodName, "before validating checking OwnerIdList :", groupInfoDTO.getOwnerIdList());
                if (null != groupInfoDTO.getOwnerIdList() && !groupInfoDTO.getOwnerIdList().isEmpty()) {
                    groupInfoUtil.validateFanIds(corpId, groupInfoDTO.getOwnerIdList(), xdmsHome, persisterTxn);
                }
                customParams.put(CURRENT_MASTER_LIST_ETAG, corpProfile.getCorpMasterListEtag());
                customParams.put(PERSISTER_TXN, persisterTxn);
                customParams.put(PTT_SERVER_ID, xdmsHome);
                groupInfoDTO.setCustomParamMap(customParams);
                KnCorpHookIPDTO hookIPDTO = new KnCorpHookIPDTO();
                hookIPDTO.setAction(KnActions.ACTIONS.CREATE_GROUP);
                hookIPDTO.setData(groupInfoDTO);
                KnProcessInvokerImpl processInvoker = KnProcessInvokerImpl.getInstance();
                Object hookResp = processInvoker.invokeHook(CUSTOM_CORP_USER_HOOK, hookIPDTO);
                if (hookResp instanceof KnCorpHookRespDTO) {
                    responseDTO = (KnCorpHookRespDTO) hookResp;
                }
            }
            if (com.kodiak.xdms.server.common.resources.KnConstants.RESPONSE_STATUS.FAILURE.value() == responseDTO.getStatus()) {
                knLogger.error(methodName, "Returning Failure response");
                populateXdmResponseFroomHook(responseDTO, respDto);
            } else {

                //Broadcast group persistDTO will be used for validation
                KnCorpBCGrpPersistDTO bcGrpPersistDTO = new KnCorpBCGrpPersistDTO();
                //Get the total corp group count and group display name count if exist.
                KnCorpGroupInfoPersistDTO groupPersistDTO = groupInfoUtil.getGroupInfo(groupInfoDTO, xdmsHome, persisterTxn);
                //Setting input DTO
                if ( groupInfoDTO.getMcxGrpInd() != null && groupInfoDTO.getMcxGrpInd() == MCX_GROUP_INDICATOR) {
                    groupInfoDTO.setOperationType("createVLGBCGroup");
                }
                bcGrpPersistDTO.setInputDTO(groupInfoDTO);
                //Setting the total group count in the corporation
                bcGrpPersistDTO.setCorpGroupCount(groupPersistDTO.getCorpGroupCount());
                //Setting the existing group count with request group name
                bcGrpPersistDTO.setGroupNameCount(groupPersistDTO.getExistingGroupCount());
                //Set the system level Broadcast Group feature bit
                if (DB_ENABLED_VALUE == corpProfile.getEnableBCGrpFeature()) {
                    bcGrpPersistDTO.setSysBCGFeatue(Boolean.TRUE);
                }
                //Addeed Group members
                Collection<KnCorpContactDTO> addedMemberDTOLst = groupInfoDTO.getAddedMemberDTOMdns();
                //Added sublist Ids
                Collection<Integer> addedSublistIds = groupInfoDTO.getAddedSublistIds();
                //Added sublist members as broadcaster
                Collection<KnCorpGroupMemberDTO> sublistMemBrdstr = groupInfoDTO.getGroupSupervisor();
                // Validate max groups per subscriber
                Collection<String> addedMemberMdns = new ArrayList<>();
                for (KnCorpContactDTO contact : addedMemberDTOLst) {
                    String mdn = contact.getMdn();
                    addedMemberMdns.add(mdn);
                }

                Collection<KnCorpSubscriberDTO> subsInfo = contactInfoUtil.getSubscribersInfo(addedMemberMdns, xdmsHome, persisterTxn);
                Map<String, Integer> subsGroupCount = groupInfoUtil.getSubsScrGroupCountExceptABDG(
                        addedMemberMdns.stream().collect(Collectors.toList()), xdmsHome, persisterTxn);

                boolean sysLargeAgencyDispatch = paramNameValueMapCommon.get(LARGE_AGENCY_DISPATCH_FEATURE).equalsIgnoreCase(ENABLED_STRING);
                boolean corpLargeAgencyDispatch = KnGeneralUtil.getFeatureBitValue(corpProfile.getCorpFS2(), FEATURE_SET.LARGE_AGENCY_DISPATCH.value());

                bcGrpPersistDTO.setAddedMDNs(subsInfo);

                //Get the broadcasters in the group.
                populateBCGData(addedMemberDTOLst, sublistMemBrdstr, groupPersistDTO);
                //Setting the group broadcasters
                bcGrpPersistDTO.setGrpBroadcasters(groupPersistDTO.getGrpBroadcasters());
                //Get and separate the internal and external contacts for the corporation from request added mdn data
                KnCorpBCGrpPersistDTO persistDto = contactInfoUtil.getCorpSubscrDetails(groupPersistDTO.getAddedMdnList(), corpId, xdmsHome, persisterTxn);
                Map<String, Integer> subscGrpCount = groupInfoUtil.getMembersGroupCount(persistDto.getGroupMdnList(), corpId, xdmsHome, persisterTxn);
                bcGrpPersistDTO.setGroupMdnGrpCnt(subscGrpCount);

                bcGrpPersistDTO.setValidExtContacts(persistDto.getValidExtContacts());
                bcGrpPersistDTO.setValidInternalCont(persistDto.getValidInternalCont());
                bcGrpPersistDTO.setMaxAllowedMemPerBCG(corpProfile.getMaxMemPerBCGrp());
                bcGrpPersistDTO.setInterOpMembers(persistDto.getInterOpMembers());
                bcGrpPersistDTO.setGroupMdnList(persistDto.getGroupMdnList());

                //Modified for 8.1.1 Release
                bcGrpPersistDTO.setMaxSGPerGrp(corpProfile.getMaxSGPerGrp());
                bcGrpPersistDTO.setMaxSGMdnPatchPerGroup(corpProfile.getMaxSGPatchPerGrp());


                //get The InterOp Subscriber Group Count
                Map<String, Integer> interGrpCount = groupInfoUtil.getExternalSubscriberGroupCount(persistDto.getInterOpMembers(), corpId, xdmsHome, persisterTxn);
                bcGrpPersistDTO.setInterOpGrpCount(interGrpCount);

                Collection<Integer> listCommonContactListRejectionIds = sublistInfoUtil.getCommonContactListRejectForGrp(addedSublistIds,corpId,xdmsHome,persisterTxn);
                knLogger.debug("CommonContactListRejectionList: ",listCommonContactListRejectionIds);
                bcGrpPersistDTO.setCommonContactRejectList(listCommonContactListRejectionIds);

                List<Integer> validSublistIds = sublistInfoUtil.getValidSublistIdInfo(addedSublistIds, corpId, xdmsHome, persisterTxn);
                knLogger.debug(methodName, "persistDtoalidSublistIds - ", validSublistIds);
                bcGrpPersistDTO.setValidSublistIds(validSublistIds);
                List<KnCorpSubscriberDTO> distinctSublistMems = sublistInfoUtil.getSublistDistinctMembers(validSublistIds, corpId, xdmsHome, persisterTxn);
                knLogger.info(methodName, "distinctSublistMems - ", distinctSublistMems);
                // Variable to hold all internal members (added member list + sublist members)
                List<String> allIntMemberList = new ArrayList<>();
                // Variable to hold all external members (added member list + sublist members)
                List<String> allExtMemberList = new ArrayList<>();
                //Loop through distinct sublist member list and add add to internal or external variables.
                for (KnCorpSubscriberDTO corpSubscriberDTO : distinctSublistMems) {
                    if (corpSubscriberDTO.isExternalContact()) {
                        allExtMemberList.add(corpSubscriberDTO.getMdn());
                    } else {
                        allIntMemberList.add(corpSubscriberDTO.getMdn());
                    }
                }

                List<String> sgMdnList = new ArrayList<>();
                List<String> sgMdnPatchList = new ArrayList<>();
                //Loop through the added valid internal member list and add to internal variable
                for (KnCorpSubscriberDTO corpSubscriberDTO : persistDto.getValidInternalCont()) {
                    allIntMemberList.add(corpSubscriberDTO.getMdn());
                    if (corpSubscriberDTO.getClientType() == GROUPMDN.value()) {
                        sgMdnList.add(corpSubscriberDTO.getMdn());
                        bcGrpPersistDTO.setUgwInterop(UGWINTEROP_DBVALUE);
                        groupInfoDTO.setUgwInterop(UGWINTEROP_DBVALUE);
                    } else if (corpSubscriberDTO.getClientType() == SUBSCR_CLIENT_TYPE.SGMDNPATCH.value()) {
                        sgMdnPatchList.add(corpSubscriberDTO.getMdn());
                        bcGrpPersistDTO.setUgwInterop(UGWINTEROP_DBVALUE);
                        groupInfoDTO.setUgwInterop(UGWINTEROP_DBVALUE);
                    }
                }
                //Loop through the added valid external member list and add to external variable
                for (KnCorpSubscriberDTO corpSubscriberDTO : persistDto.getValidExtContacts()) {
                    allExtMemberList.add(corpSubscriberDTO.getMdn());
                }
                knLogger.debug(methodName, "allExtMemberList - ", KnGDPRTemplate.mdnList(allExtMemberList));
                knLogger.debug(methodName, "allIntMemberList - ", KnGDPRTemplate.mdnList(allIntMemberList));

                Map<String, KnCorpSubscriberDTO> corpSubscriberMap = new HashMap<>();
                Collection<KnCorpSubscriberDTO> pocSubscriberInfo = contactInfoUtil.getSubscribersInfo(allIntMemberList, xdmsHome, persisterTxn);
                knLogger.debug(methodName, "pocSubscriberInfo - ", pocSubscriberInfo, KnGDPRTemplate.mdnList(allIntMemberList));
                List<String> criClientList = new ArrayList<>(); // Verifiable to host the cri clients in group members
                for (KnCorpSubscriberDTO pocSubsInfoDetails : pocSubscriberInfo) {
                    corpSubscriberMap.put(pocSubsInfoDetails.getMdn(), pocSubsInfoDetails);
                    if(pocSubsInfoDetails.getMcpttCompliance() == MCPTT_COMPLIANCE){
                        criClientList.add(pocSubsInfoDetails.getMdn());
                    }
                }
                knLogger.debug(methodName, "criClientList - ", KnGDPRTemplate.mdnList(criClientList));
                String maxGroupsPerCRIClient = paramNameValueMapCommon.get(MAX_GROUPS_PER_CRI_CLIENT);
                String maxPreConfigGroup = paramNameValueMapCommon.get(MAX_PRECONFIG_GROUPS);
                bcGrpPersistDTO.setCriClientList(criClientList);
                if(null != maxGroupsPerCRIClient){
                    bcGrpPersistDTO.setMaxGroupsPerCRIClient(Integer.parseInt(maxGroupsPerCRIClient));
                }


                //Get the group count of all internal members.
                Map<String, Integer> subsGroupCountMap = groupInfoUtil.getMembersGroupCount(allIntMemberList,
                        xdmsHome, persisterTxn);
                //Distict all members
                Set<String> allDistinceMembers = new HashSet<>(allIntMemberList);
                bcGrpPersistDTO.setAllDistinctMemebrs(allDistinceMembers);
                allDistinceMembers.addAll(allExtMemberList);

                boolean isLargeGroup = Boolean.FALSE;
                if (allDistinceMembers.size() > corpProfile.getMaxMemPerBCGrp()) {
                    bcGrpPersistDTO.setLargeGroup(Boolean.TRUE);
                    isLargeGroup = Boolean.TRUE;
                }

                //Get the group count of all external members
                Map<String, Integer> externalSubscGroupCountMap =
                        groupInfoUtil.getExternalSubscriberGroupCount(allExtMemberList, corpId, xdmsHome, persisterTxn);
                subsGroupCountMap.putAll(externalSubscGroupCountMap);
                knLogger.debug(methodName, "subsGroupCountMap - ", KnGDPRTemplate.mapKeyMdn(subsGroupCountMap));
                bcGrpPersistDTO.setSubsGroupCountMap(subsGroupCountMap);
                bcGrpPersistDTO.setGroupDisplayName(groupInfoDTO.getGroupDisplayName());
                bcGrpPersistDTO.setMaxGroupsPerMemberCount(corpProfile.getMaxGroupsPerSubsc());
                //Setting the max contact per request value
                bcGrpPersistDTO.setMaxContactsPerRequest(corpProfile.getMaxContactsPerRequest());
                //Setting max group allowed per corporation
                bcGrpPersistDTO.setMaxGroups(corpProfile.getMaxCorpGroups());
                //Get the external profile maps for validation PreArranged and Broadcaster bits.
                Map<String, Map<Integer, KnExtProfileDetails>> extProfileMaps = commonInfoUtil.getExtProfileMaps(allExtMemberList, xdmsHome, corpId, persisterTxn, bcGrpPersistDTO,new ArrayList<>());
                bcGrpPersistDTO.setConfiguredProfileMap(extProfileMaps.get(CONFIGUREDPROFILEMAP));
                bcGrpPersistDTO.setExtBroadcasterFeatureMap(extProfileMaps.get(EXTBROADCASTERFEATUREMAP));

                //Get the internal Broadcasters in the group.
                List<String> intBroadcasters = new ArrayList<>(bcGrpPersistDTO.getGrpBroadcasters());
                intBroadcasters.removeAll(allExtMemberList);
                //Get the internal Broadcasters Broadcast Group server bit.
                Map<String, Boolean> interBrdstrFeatureBitMap = contactInfoUtil.getSubscrBCGrpBit(intBroadcasters, corpId, xdmsHome, persisterTxn);
                bcGrpPersistDTO.setInterBroadcasterBitMap(interBrdstrFeatureBitMap);

                // TP Dynamic group changes
                if (groupInfoDTO.getClientType() == DYNAMIC_CGMT_INTF) {
                    //added mdn DB thired party mdn list
                    List<String> tpDbMDNList = persistDto.getTpMdnList();
                    tpDbMDNList.addAll(tpMdnList);

                    KnTPVendorDetailsPersistDTO dbVendorDetails = commonInfoUtil.getVendorDetails(groupInfoDTO.getTpVendorID(), xdmsHome, persisterTxn);
                    Map<String, String> vendorMdnMap = commonInfoUtil.getVendorID(tpDbMDNList, xdmsHome, persisterTxn);

                    bcGrpPersistDTO.setTpVendorPersistDTO(dbVendorDetails);
                    bcGrpPersistDTO.setTpRequestMDNMap(tpDBSubMap);
                    bcGrpPersistDTO.setVendorMdnMap(vendorMdnMap);
                    bcGrpPersistDTO.setTpDbMDNList(tpDbMDNList);
                    bcGrpPersistDTO.setTpVendorID(groupInfoDTO.getTpVendorID());
                }
                bcGrpPersistDTO.setMaxLargeBCGrpCorp(corpProfile.getMaxLrgBGrpPerCorp());
                bcGrpPersistDTO.setMaxLargeGrpSystem(Integer.parseInt(genInfoUtil.retrieveRTXConfigValues(persisterTxn).get(NUM_OF_LG_SUPPORTED)));
                bcGrpPersistDTO.setLargeBCGrpCountInCorp(groupInfoUtil.getLargeGroupCounts(corpId, persisterTxn, xdmsHome).getLargeBCGrpCountCorp());
                bcGrpPersistDTO.setLargeGrpCountInSystem(groupInfoUtil.getLargeGroupCounts(corpId, persisterTxn, xdmsHome).getLrgGrpCountSystem());
                bcGrpPersistDTO.setMaxMemPerLargeBCGroup(corpProfile.getMaxMemPerLrgBGrp());
                bcGrpPersistDTO.setLargeGroupSupported(corpProfile.getLargeGrpSupported());
                //OSM create broadcast group osm list exists
                Map<Integer, Integer> osmListIdAndDefaultMap = corpOSMInfoUtil
                        .getOSMListIdAndDefaultMap(String.valueOf(groupInfoDTO.getCorpId()), xdmsHome, persisterTxn);
                /*if(groupInfoDTO.getOSMListId()!=null&&!groupInfoDTO.getOSMListId().isEmpty()){
                    bcGrpPersistDTO.setOSMListId(groupInfoDTO.getOSMListId());
                }else{
                    if(osmListIdAndDefaultMap!=null&&!osmListIdAndDefaultMap.isEmpty()){
                        Optional<Integer> osmPresent =osmListIdAndDefaultMap.entrySet().stream()
                                .filter(entry -> entry.getValue().equals(ENABLED)).map(Map.Entry::getKey).findFirst();
                        if(osmPresent.isPresent()) {
                            bcGrpPersistDTO.setOSMListId(osmPresent.get().toString());
                        }
                    }
                }*/
                if (groupInfoDTO.getOSMListId() != null)
                    bcGrpPersistDTO.setOSMListId(groupInfoDTO.getOSMListId());

                bcGrpPersistDTO.setOsmListIdAndDefultMap(osmListIdAndDefaultMap);
                List<String> externalMdnList=new ArrayList<>();
                //OSM create broadcast group member mdn osm auth check
                if (groupPersistDTO.getAddedMdnList() != null && !groupPersistDTO.getAddedMdnList().isEmpty()
                        && addedMemberDTOLst != null && !addedMemberDTOLst.isEmpty()) {
                    Collection<KnCorpSubscriberDTO> pocSubsInfo = contactInfoUtil.getSubscribersInfo(groupPersistDTO.getAddedMdnList(), xdmsHome, persisterTxn);
                    knLogger.debug(methodName, "pocSubsInfo - ", pocSubsInfo, KnGDPRTemplate.mdnList(groupPersistDTO.getAddedMdnList()));
                    bcGrpPersistDTO.setPocSubsInfo(pocSubsInfo);
                    bcGrpPersistDTO.setAddedMemberMdnsDTOLst(addedMemberDTOLst);
                    for (KnCorpSubscriberDTO pocSubsInfoDetails : pocSubsInfo) {
                        corpSubscriberMap.put(pocSubsInfoDetails.getMdn(), pocSubsInfoDetails);
                        if(pocSubsInfoDetails.getCorpId()!=corpId){
                            externalMdnList.add(pocSubsInfoDetails.getMdn());
                        }
                    }
                }
                // ABDG: hierarchyId — derive from group owner's subscriber profile
                if (groupInfoDTO.getGroupCreatedBy() == CREATED_BY.ABDG.value()
                        && groupInfoDTO.getHierarchyId() == null
                        && groupInfoDTO.getTpGroupOwner() != null) {
                    try {
                        String ownerHierarchyId = groupInfoUtil.getSubscriberHierarchyId(
                                groupInfoDTO.getTpGroupOwner(), xdmsHome, persisterTxn);
                        if (ownerHierarchyId != null && !ownerHierarchyId.isEmpty()) {
                            groupInfoDTO.setHierarchyId(ownerHierarchyId);
                            knLogger.info(methodName, "ABDG createBCGroup: derived hierarchyId from group owner: ", ownerHierarchyId);
                        }
                    } catch (KnDAOException e) {
                        knLogger.warn(methodName, "ABDG createBCGroup: failed to retrieve hierarchyId from group owner, proceeding with null - ", e);
                    }
                }
                KnCorpGroupInfoPersistDTO groupInfoPersistDTO = new KnCorpGroupInfoPersistDTO();
                String hierachyRoot=null;
                String hierarchyId=groupInfoDTO.getHierarchyId();
                String pttServerID = genInfoUtil.retrieveLocalXDMPttServerId();
                if(hierarchyId != null) {
                    hierachyRoot= KnCorpCommonInfoUtil.getHierachyRoot(corpId, hierarchyId, persisterTxn,pttServerID);
                }
                knLogger.info(methodName, "==>hierachyRoot : ", hierachyRoot);
                boolean isUgwInterop = (null != groupInfoDTO.getUgwInterop() && groupInfoDTO.getUgwInterop().equals(7));
                bcGrpPersistDTO.setGrpShared(groupInfoDTO.getGrpShared());
                bcGrpPersistDTO.setIsPreConfiguredGroup(groupInfoDTO.getIsPreConfiguredGroup());
                if(isUgwInterop) {
                    bcGrpPersistDTO.setUgwInterop(groupInfoDTO.getUgwInterop());
                    String ugwInteropFlag = paramNameValueMapCommon.get(UGWINTEROP);
                    knLogger.debug(methodName, "Retrieved ugwInterop flag from system config - ", ugwInteropFlag);
                    bcGrpPersistDTO.setUgwInteropSystemConfig(ugwInteropFlag);
                }
                List<KnCorpSharedCorpInfo> sharedCorpInfoList = new ArrayList<>();
                if(groupInfoDTO.getCorpSharedCorpInfoList() !=null && groupInfoDTO.getCorpSharedCorpInfoList().size() !=0 &&
                        groupInfoDTO.getGrpShared()!=null && groupInfoDTO.getGrpShared() == GROUP_SHARING_ENABLE_INDICATOR &&
                        groupInfoDTO.getGroupProfileId()!=null) {
                    bcGrpPersistDTO.setCorpSharedCorpInfoList(groupInfoDTO.getCorpSharedCorpInfoList());
                    groupInfoPersistDTO.setCorpSharedCorpInfoList(groupInfoDTO.getCorpSharedCorpInfoList());
                    injectSourceHierarchyId(groupInfoDTO.getCorpSharedCorpInfoList(), groupInfoDTO.getHierarchyId());
                    Set<String> extCorpIds = sharedCorpInfoList.stream().map(KnCorpSharedCorpInfo::getExtCorpId).collect(Collectors.toSet());
                    Set<Integer> intCorpIds = sharedCorpInfoList.stream().map(KnCorpSharedCorpInfo::getCorpId).collect(Collectors.toSet());
                    knLogger.debug(methodName,"Fetching shared corp information - ",extCorpIds," intCorpIds - ",intCorpIds);
                    Map<String,Integer> extIntCorpIDMap = commonInfoUtil.getCorpIdMap(extCorpIds,intCorpIds,persisterTxn);
                    knLogger.debug(methodName,"extIntCorpIDMap - ",KnGDPRTemplate.mapKeyMdn(extIntCorpIDMap));
                    bcGrpPersistDTO.setExtIntCorpIdMap(extIntCorpIDMap);
                    List<KnCorpTrustMatrixDTO> trustMatrixDTOList = generalCacheUtil.getSharedCorpMatrix(corpProfile.getExtCorpId().trim());
                    enrichTrustMatrixWithHierarchyMappings(trustMatrixDTOList);
                    bcGrpPersistDTO.setTrustMatrixDTOList(trustMatrixDTOList);
                }
                else{
                    knLogger.debug(methodName, "Proceeding create group ..as regular flow");
                    if(groupInfoDTO.getCorpSharedCorpInfoList() !=null && groupInfoDTO.getCorpSharedCorpInfoList().size() !=0 && groupInfoDTO.getGrpShared() == GROUP_SHARING_ENABLE_INDICATOR ){
                        List<KnCorpSharedCorpInfo> corpSharedCorpInfos = groupInfoDTO.getCorpSharedCorpInfoList();
                        bcGrpPersistDTO.setCorpSharedCorpInfoList(corpSharedCorpInfos);
                        groupInfoPersistDTO.setCorpSharedCorpInfoList(corpSharedCorpInfos);
                        injectSourceHierarchyId(corpSharedCorpInfos, groupInfoDTO.getHierarchyId());
                        Set<String> extCorpIds = corpSharedCorpInfos.stream().map(KnCorpSharedCorpInfo::getExtCorpId).collect(Collectors.toSet());
                        Set<Integer> intCorpIds = corpSharedCorpInfos.stream().map(KnCorpSharedCorpInfo::getCorpId).collect(Collectors.toSet());
                        knLogger.debug(methodName,"Fetching shared corp information - ",extCorpIds," intCorpIds - ",intCorpIds);
                        Map<String,Integer> extIntCorpIDMap = commonInfoUtil.getCorpIdMap(extCorpIds,intCorpIds,persisterTxn);
                        knLogger.debug(methodName,"extIntCorpIDMap - ",KnGDPRTemplate.mapKeyMdn(extIntCorpIDMap));
                        bcGrpPersistDTO.setExtIntCorpIdMap(extIntCorpIDMap);
                        List<KnCorpTrustMatrixDTO> trustMatrixDTOList = generalCacheUtil.getSharedCorpMatrix(corpProfile.getExtCorpId().trim());
                        enrichTrustMatrixWithHierarchyMappings(trustMatrixDTOList);
                        bcGrpPersistDTO.setTrustMatrixDTOList(trustMatrixDTOList);
                    }
                }
                bcGrpPersistDTO.setParamNameValueMapCommon(paramNameValueMapCommon);
                bcGrpPersistDTO.setCorpProfile(corpProfile);
                bcGrpPersistDTO.setMcxGrpInd(groupInfoDTO.getMcxGrpInd());

                bcGrpPersistDTO.setGrpShared(groupInfoDTO.getGrpShared());

                if(groupInfoDTO.getCorpSharedCorpInfoList() !=null && groupInfoDTO.getCorpSharedCorpInfoList().size() !=0 &&
                        groupInfoDTO.getGrpShared()!=null && groupInfoDTO.getGrpShared() == GROUP_SHARING_ENABLE_INDICATOR &&
                        groupInfoDTO.getGroupProfileId()!=null) {
                    bcGrpPersistDTO.setCorpSharedCorpInfoList(groupInfoDTO.getCorpSharedCorpInfoList());
                    groupInfoPersistDTO.setCorpSharedCorpInfoList(groupInfoDTO.getCorpSharedCorpInfoList());
                    injectSourceHierarchyId(groupInfoDTO.getCorpSharedCorpInfoList(), groupInfoDTO.getHierarchyId());
                    Set<String> extCorpIds = sharedCorpInfoList.stream().map(KnCorpSharedCorpInfo::getExtCorpId).collect(Collectors.toSet());
                    Set<Integer> intCorpIds = sharedCorpInfoList.stream().map(KnCorpSharedCorpInfo::getCorpId).collect(Collectors.toSet());
                    knLogger.debug(methodName,"Fetching shared corp information - ",extCorpIds," intCorpIds - ",intCorpIds);
                    Map<String,Integer> extIntCorpIDMap = commonInfoUtil.getCorpIdMap(extCorpIds,intCorpIds,persisterTxn);
                    knLogger.debug(methodName,"extIntCorpIDMap - ",KnGDPRTemplate.mapKeyMdn(extIntCorpIDMap));
                    bcGrpPersistDTO.setExtIntCorpIdMap(extIntCorpIDMap);
                    List<KnCorpTrustMatrixDTO> trustMatrixDTOList = generalCacheUtil.getSharedCorpMatrix(corpProfile.getExtCorpId().trim());
                    enrichTrustMatrixWithHierarchyMappings(trustMatrixDTOList);
                    bcGrpPersistDTO.setTrustMatrixDTOList(trustMatrixDTOList);
                }
                else{
                    knLogger.debug(methodName, "Proceeding create group ..as regular flow");
                    if(groupInfoDTO.getCorpSharedCorpInfoList() !=null && groupInfoDTO.getCorpSharedCorpInfoList().size() !=0 && groupInfoDTO.getGrpShared() == GROUP_SHARING_ENABLE_INDICATOR ){
                        List<KnCorpSharedCorpInfo> corpSharedCorpInfos = groupInfoDTO.getCorpSharedCorpInfoList();
                        bcGrpPersistDTO.setCorpSharedCorpInfoList(corpSharedCorpInfos);
                        groupInfoPersistDTO.setCorpSharedCorpInfoList(corpSharedCorpInfos);
                        injectSourceHierarchyId(corpSharedCorpInfos, groupInfoDTO.getHierarchyId());
                        Set<String> extCorpIds = corpSharedCorpInfos.stream().map(KnCorpSharedCorpInfo::getExtCorpId).collect(Collectors.toSet());
                        Set<Integer> intCorpIds = corpSharedCorpInfos.stream().map(KnCorpSharedCorpInfo::getCorpId).collect(Collectors.toSet());
                        knLogger.debug(methodName,"Fetching shared corp information - ",extCorpIds," intCorpIds - ",intCorpIds);
                        Map<String,Integer> extIntCorpIDMap = commonInfoUtil.getCorpIdMap(extCorpIds,intCorpIds,persisterTxn);
                        knLogger.debug(methodName,"extIntCorpIDMap - ",KnGDPRTemplate.mapKeyMdn(extIntCorpIDMap));
                        bcGrpPersistDTO.setExtIntCorpIdMap(extIntCorpIDMap);
                        List<KnCorpTrustMatrixDTO> trustMatrixDTOList = generalCacheUtil.getSharedCorpMatrix(corpProfile.getExtCorpId().trim());
                        enrichTrustMatrixWithHierarchyMappings(trustMatrixDTOList);
                        bcGrpPersistDTO.setTrustMatrixDTOList(trustMatrixDTOList);
                    }
                }

                bcGrpPersistDTO.setParamNameValueMapCommon(paramNameValueMapCommon);
                bcGrpPersistDTO.setCorpProfile(corpProfile);
                bcGrpPersistDTO.setMcxGrpInd(groupInfoDTO.getMcxGrpInd());
                bcGrpPersistDTO.setMaxGroupsPerLargeDispatchMemberCount(corpProfile.getMaxGroupsPerLargeDispatch());
                bcGrpPersistDTO.setIsSysLargeAgencyDispatchEnabled(sysLargeAgencyDispatch);
                bcGrpPersistDTO.setIsCorpLargeAgencyDispatchEnabled(corpLargeAgencyDispatch);
                bcGrpPersistDTO.setSubsGroupCount(subsGroupCount);
                knLogger.debug(methodName, "Invoking ValidationFW. DTO - ", bcGrpPersistDTO);
                //performs business validation

                boolean criFlag=false;
                criFlag=genInfoUtil.retrieveCriLocFlag(clusterId, persisterTxn);
                bcGrpPersistDTO.setCriLocFlag(criFlag);
                int maxDbPreConfigGroupCount = groupInfoUtil.getSystemPreConfigGroupCont(xdmsHome,persisterTxn);
                bcGrpPersistDTO.setSystemMaxAllowedPreConfigGroup(maxPreConfigGroup);
                bcGrpPersistDTO.setDbPreConfiguredGroupCount(maxDbPreConfigGroupCount);

                bcGrpPersistDTO.setIsPreConfiguredGroup(groupInfoDTO.getIsPreConfiguredGroup());
                if(isUgwInterop) {
                    bcGrpPersistDTO.setUgwInterop(groupInfoDTO.getUgwInterop());
                }

                // Fetch broadcast group count per subscriber
                if (addedMemberMdns != null && !addedMemberMdns.isEmpty()) {
                    Map<String, Integer> subsBroadcastGroupCount = groupInfoUtil.getSubscriberBroadcastGroupCount(addedMemberMdns.stream().toList(), xdmsHome, persisterTxn);
                    bcGrpPersistDTO.setSubscriberBroadcastGroupCount(subsBroadcastGroupCount);
                    int maxBroadcastGroupCountPerSubscriber = MAX_BROADCAST_GROUP_PER_SUBSCRIBER;
                    if (paramNameValueMapCommon.get(MAX_BCG_PER_DISP) != null) {
                        maxBroadcastGroupCountPerSubscriber = Integer.parseInt(paramNameValueMapCommon.get(MAX_BCG_PER_DISP));
                    }
                    bcGrpPersistDTO.setMaxBroadcastGroupCountPerSubscriber(maxBroadcastGroupCountPerSubscriber);
                }

                bcGrpPersistDTO.setCorpId(corpId);
                validatorFW.validate(bcGrpPersistDTO);
                knLogger.debug(methodName, "Validation completed Successfully - ");

                if (isUgwInterop) {
                    boolean isGroupProfileNotifyRequired = commonInfoUtil.isGroupProfileNotifyRequired(corpId, persisterTxn);
                    if (isGroupProfileNotifyRequired) {
                        //Update the UGWINTEROP
                        commonInfoUtil.updateLmrInterOpInDB(corpId, ENABLED, persisterTxn);
                        respDto.setIntCorpId(intCorpId);
                        respDto.setExtCorpId(extCorpId);
                        respDto.setNetworkName(networkName);
                        respDto.setCorpNotification(true);
                    }
                }

                String groupName = groupInfoDTO.getGroupDisplayName();
                KnGenInfoUtil genInfoUtil = KnGenInfoUtil.getInstance();
                //retrieve the group ID from IDgen
                int groupId = genInfoUtil.retrieveIdForTable(CORP_GROUP_INFO_TABLE, xdmsHome,
                        CORP_GROUP_INFO_TABLE_PK, false, DUAL_DATA_STORE);
                groupInfoDTO.setGroupId(groupId);
                //retrieve the private sublist ID from IDgen
                int privateGroupListId = genInfoUtil.retrieveIdForTable(CORP_LIST_TABLE, xdmsHome,
                        CORP_LIST_TABLE_PK, false, DUAL_DATA_STORE);
                KnCorpSublistDTO sublistDTO = new KnCorpSublistDTO();
                sublistDTO.setSublistId(privateGroupListId);
                sublistDTO.setCorpId(corpId);
                sublistDTO.setSublistName(PRIVATE_GROUP_LIST_NAME + groupId);
                sublistDTO.setDistributionPolicy(LIST_DIST_POLICY_NO_DIST);
                sublistDTO.setSublistType(LIST_TYPE_PRIVATE_GRPMEMLIST);
                List<KnCorpSubscriberDTO> privateMemberList = new ArrayList<>();
                if (null != bcGrpPersistDTO.getValidExtContacts()) {
                    privateMemberList.addAll(bcGrpPersistDTO.getValidExtContacts());
                }
                if (null != bcGrpPersistDTO.getValidInternalCont()) {
                    privateMemberList.addAll(bcGrpPersistDTO.getValidInternalCont());
                }
                sublistInfoUtil.createSubListDetails(privateMemberList, sublistDTO, xdmsHome, persisterTxn);


                groupInfoPersistDTO.setGroupMemberListId(privateGroupListId);
                addedSublistIds.add(privateGroupListId); //adding private list as well

                //Step:
                //create the group details
                int etag = INITIAL_ETAG;
                groupInfoPersistDTO.setGroupId(groupId);
                groupInfoPersistDTO.setGroupDisplayName(groupName);
                groupInfoPersistDTO.setCorpId(corpId);
                groupInfoPersistDTO.setETag(etag);
                groupInfoPersistDTO.setGroupType(groupInfoDTO.getGroupType());
                groupInfoPersistDTO.setOverrideDnd(groupInfoDTO.getOverrideDnd());
                groupInfoPersistDTO.setGroupDistPolicy(DIST_POLICY_BROADCAST_GROUP);
                int localClusterId = Integer.parseInt(System.getenv(CLUSTERID_ENV_NAME));
                boolean validCorpPocHome = pocHome != null && !pocHome.trim().isEmpty() && !pocHome.trim().equals("0");
                knLogger.debug(methodName, "createBCGroup: corpPocHome=", pocHome, " validCorpPocHome=", validCorpPocHome, " allDistinceMembersSize=", allDistinceMembers.size(), " pochomeAutoAssignFlag=", pochomeAutoAssignFlag);
                if(!pochomeAutoAssignFlag){
                    if (groupInfoDTO.getGroupCreatedBy() == CREATED_BY.ABDG.value()) {
                        List<String> groupOwner = new ArrayList<>();
                        if(groupInfoDTO.getTpGroupOwner() != null)groupOwner.add(groupInfoDTO.getTpGroupOwner());
                        Map<String,Object> pocHomeMap = groupInfoUtil.getPocHomeAndClusterIdForCorpGroup(groupOwner,xdmsHome,persisterTxn);
                        pocHome = (String) pocHomeMap.get(POCHOME);
                        groupInfoPersistDTO.setPocHome(pocHome);
                        groupInfoPersistDTO.setClusterId((Integer) pocHomeMap.get(CLUSTERID));
                    }else if(groupInfoDTO.getIsPreConfiguredGroup() != null && groupInfoDTO.getIsPreConfiguredGroup() == 1){
                        if(validCorpPocHome){
                            String clusterIdValue = groupInfoUtil.fetchClusterId(pocHome, String.valueOf(localClusterId));
                            groupInfoPersistDTO.setPocHome(pocHome);
                            if (clusterIdValue != null) {
                                groupInfoPersistDTO.setClusterId(Integer.valueOf(clusterIdValue));
                            }
                        }else{
                            pocHome = groupInfoUtil.getPocHomeByHierarchyId(corpId,hierarchyId,xdmsHome,persisterTxn);
                            groupInfoPersistDTO.setPocHome(pocHome);
                            String clusterIdValue = null;
                            if(pocHome!=null)clusterIdValue = groupInfoUtil.fetchClusterId(pocHome, String.valueOf(localClusterId));
                            if (clusterIdValue != null) {
                                groupInfoPersistDTO.setClusterId(Integer.valueOf(clusterIdValue));
                            }
                        }
                    }else{
                        if(allDistinceMembers.size() == 0){
                            if (validCorpPocHome) {
                                String clusterIdValue = groupInfoUtil.fetchClusterId(pocHome, String.valueOf(localClusterId));
                                groupInfoPersistDTO.setPocHome(pocHome);
                                if (clusterIdValue != null) {
                                    groupInfoPersistDTO.setClusterId(Integer.valueOf(clusterIdValue));
                                }
                                knLogger.debug(methodName, "createBCGroup 0-member validPocHome branch: setting pocHome=", pocHome, " clusterId=", clusterIdValue);
                            } else {
                                groupInfoPersistDTO.setPocHome(null);
                                groupInfoPersistDTO.setClusterId(null);
                                knLogger.debug(methodName, "[POCHOME-DEBUG] createBCGroup 0-member invalidPocHome branch: setting pocHome=null clusterId=null");
                            }
                        }else{
                            knLogger.debug(methodName," allDistinceMembers for deciding POCHOME :",allDistinceMembers);
                            Map<String, Object> pochomeMap = groupInfoUtil.getPocHomeAndClusterIdForCorpGroup(allDistinceMembers.stream().toList(),xdmsHome,persisterTxn);
                            pocHome = (String) pochomeMap.get(POCHOME);
                            groupInfoPersistDTO.setPocHome(pocHome);
                            groupInfoPersistDTO.setClusterId((Integer) pochomeMap.get(CLUSTERID));
                        }
                    }
                }else{
                    if (validCorpPocHome) {
                        String clusterIdValue = groupInfoUtil.fetchClusterId(pocHome, String.valueOf(localClusterId));
                        groupInfoPersistDTO.setPocHome(pocHome);
                        if (clusterIdValue != null) {
                            groupInfoPersistDTO.setClusterId(Integer.valueOf(clusterIdValue));
                        }
                        knLogger.debug(methodName, "createBCGroup autoAssign validPocHome branch: setting pocHome=", pocHome, " clusterId=", clusterIdValue);
                    } else {
                        groupInfoPersistDTO.setPocHome(null);
                        groupInfoPersistDTO.setClusterId(null);
                        knLogger.debug(methodName, "createBCGroup autoAssign invalidPocHome branch: setting pocHome=null clusterId=null");
                    }
                }
                groupInfoPersistDTO.setGrpShared(groupInfoDTO.getGrpShared());
                groupInfoPersistDTO.setIsPreConfiguredGroup(groupInfoDTO.getIsPreConfiguredGroup());
                if (null != groupInfoDTO.getUgwInterop()) {
                    groupInfoPersistDTO.setUgwInterop(groupInfoDTO.getUgwInterop());
                }
                if (groupInfoDTO.getAvatar() != null && groupInfoDTO.getAvatar() != AVATAR_NOT_MODIFIED) {
                    groupInfoPersistDTO.setAvatar(groupInfoDTO.getAvatar());
                }
                //


                    groupInfoPersistDTO.setVideoPermission(DEFAULT_VIDEO_PERMISSION_VALUE_FOR_BCG_GROUP);

//                groupInfoPersistDTO.setVideoPermission(groupInfoDTO.getVideoPermission());


                for (String mdn : bcGrpPersistDTO.getAllDistinctMemebrs()) {
                    if (bcGrpPersistDTO.getGroupMdnList() != null && bcGrpPersistDTO.getGroupMdnList().contains(mdn)) {
                        groupInfoPersistDTO.setLmrInteropCapable(LMR_INTEROP_CAPABLE);
                        break;
                    }
                }
                groupInfoPersistDTO.setTpGroupOwner(groupInfoDTO.getTpGroupOwner());
                groupInfoPersistDTO.setGroupCreatedBy(groupInfoDTO.getGroupCreatedBy());
                groupInfoPersistDTO.setHangTimeOut(groupInfoDTO.getHangTimeOut());
                groupInfoPersistDTO.setEmergHangTimeAddOn(groupInfoDTO.getEmergHangTimeAddOn());
                groupInfoPersistDTO.setEmergOverrideDND(groupInfoDTO.getEmergOverrideDND());
                groupInfoPersistDTO.setEmergAutoFloorTimer(groupInfoDTO.getEmergAutoFloorTimer());
                groupInfoPersistDTO.setLargeGroup(isLargeGroup);
                groupInfoPersistDTO.setOSMListId(bcGrpPersistDTO.getOSMListId());
                groupInfoPersistDTO.setMcxGrpInd(groupInfoDTO.getMcxGrpInd());
                groupInfoPersistDTO.setGroupProfileId(groupInfoDTO.getGroupProfileId());
                groupInfoPersistDTO.setGroupServiceType(groupInfoDTO.getGroupServiceType());
                groupInfoPersistDTO.setFeatureAllowed(groupInfoDTO.getFeatureAllowed());
                groupInfoPersistDTO.setAudioCutIn(groupInfoDTO.getAudioCutIn());
                groupInfoPersistDTO.setHierarchyId(groupInfoDTO.getHierarchyId());
                groupInfoPersistDTO.setHierarchyRoot(hierachyRoot);
                knLogger.debug(methodName, "[POCHOME-DEBUG] createBCGroup persisting groupId=", groupId, " pocHome=", groupInfoPersistDTO.getPocHome(), " clusterId=", groupInfoPersistDTO.getClusterId());
                groupInfoUtil.createGroupInfoDetails(groupInfoPersistDTO, xdmsHome, persisterTxn);

                //associate sublistIds to group
                groupInfoUtil.addSublistsToGroup(groupId, addedSublistIds, xdmsHome, persisterTxn);
                //Add group distribution table
                knLogger.info(methodName, "GrpBroadcasters - ", KnGDPRTemplate.mdnList(bcGrpPersistDTO.getGrpBroadcasters()));
                groupInfoUtil.addToCorpGroupDistInfo(bcGrpPersistDTO.getGrpBroadcasters(), groupId, xdmsHome, persisterTxn);

                if(groupInfoDTO.getGrpShared()!= null && groupInfoDTO.getGrpShared() == GROUP_SHARING_ENABLE_INDICATOR){
                    // Insert into CORPGRP_SHAREDLIST — exclude self-corp entries (same corp cannot be both owner and shared;
                    // hierarchy associations are tracked separately in GROUP_HIERARCHY_MAP)
                    List<KnCorpSharedCorpInfo> nonSelfSharedList = new ArrayList<>();
                    if (groupInfoPersistDTO.getCorpSharedCorpInfoList() != null) {
                        for (KnCorpSharedCorpInfo info : groupInfoPersistDTO.getCorpSharedCorpInfoList()) {
                            if (!Objects.equals(info.getCorpId(), corpId)) {
                                nonSelfSharedList.add(info);
                            }
                        }
                    }
                    if (!nonSelfSharedList.isEmpty()) {
                        KnCorpGroupInfoPersistDTO sharedCorpDto = new KnCorpGroupInfoPersistDTO();
                        sharedCorpDto.setCorpId(corpId);
                        sharedCorpDto.setGroupId(groupId);
                        sharedCorpDto.setCorpSharedCorpInfoList(nonSelfSharedList);
                        List<KnCorpGroupInfoPersistDTO> groupInfoPersistDTOList = new ArrayList<>();
                        groupInfoPersistDTOList.add(sharedCorpDto);
                        groupInfoUtil.createGroupSharedCorpInfo(groupInfoPersistDTOList, xdmsHome, persisterTxn);
                    }

                    // P6-3 Step C: insert GROUP_HIERARCHY_MAP rows from hierarchyList
                    List<KnCorpSharedCorpInfo> sharedHierList = bcGrpPersistDTO.getCorpSharedCorpInfoList();
                    if (sharedHierList != null) {
                        List<String> hierarchyIds = new ArrayList<>();
                        List<Integer> hierCorpIds = new ArrayList<>();
                        for (KnCorpSharedCorpInfo info : sharedHierList) {
                            List<KnXDMHierarchyInfo> hierList = info.getHierarchyList();
                            if (hierList != null && !hierList.isEmpty() && info.getCorpId() != null) {
                                for (KnXDMHierarchyInfo hierInfo : hierList) {
                                    String sharedHierarchyId = hierInfo.getSharedHierarchyId();
                                    if (sharedHierarchyId != null && !sharedHierarchyId.isEmpty()) {
                                        hierarchyIds.add(sharedHierarchyId);
                                        hierCorpIds.add(info.getCorpId());
                                    }
                                }
                            }
                        }
                        if (!hierarchyIds.isEmpty()) {
                            knLogger.debug(methodName, "P6-3: Inserting shared group hierarchy map for BC groupId=", groupId, " count=", hierarchyIds.size());
                            groupInfoUtil.insertSharedGroupHierarchyMap(groupId, hierarchyIds, hierCorpIds, xdmsHome, persisterTxn);
                        }
                    }
                }

                //Loop the allDistinctMember and prepare the member DTO to be insert into group member list.
                List<KnCorpContactDTO> memList = new ArrayList<>();
                knLogger.debug(methodName, "bcGrpPersistDTO.getAllDistinctMemebrs() - ", KnGDPRTemplate.mdnSet(bcGrpPersistDTO.getAllDistinctMemebrs()));
                List<String> allMemList = new ArrayList<>();
                Map<String, Integer> grpModifyPermMap = groupPersistDTO.getGrpModifyPermMap();
                Map<String, Integer> osmAuthorizeMap = groupPersistDTO.getOsmAuthorizeMap();
                for (String mdn : bcGrpPersistDTO.getAllDistinctMemebrs()) {
                    KnCorpContactDTO corpContactDTO = new KnCorpContactDTO();
                    KnSubscriberDTO subscriberDTO = new KnSubscriberDTO();
                    corpContactDTO.setMdn(mdn);

                    if (bcGrpPersistDTO.getGrpBroadcasters().contains(mdn)) {
                        corpContactDTO.setBroadcaster(1);
                    }
                    if (bcGrpPersistDTO.getInterOpMembers().contains(mdn)) {
                        corpContactDTO.setSupervisory(INTER_OP);
                    }
                    if (sgMdnList.contains(mdn)) {
                        corpContactDTO.setMemberType(SG_MDN_MEMBER_TYPE);
                    } else if (sgMdnPatchList.contains(mdn)) {
                        corpContactDTO.setMemberType(SG_MDN_PATCH_MEMBER_TYPE);
                    }
                    if (allExtMemberList.contains(mdn)) {
                        corpContactDTO.setGroupModifyPerm(DISABLED);
                    } else {
                        corpContactDTO.setGroupModifyPerm(grpModifyPermMap.get(mdn));
                    }
                    if (osmAuthorizeMap.get(mdn) == null) {
                        corpContactDTO.setIsOSMAuthorize(DISABLED);
                        subscriberDTO.setIsOSMAuthorize(DISABLED);
                    } else {
                        corpContactDTO.setIsOSMAuthorize(osmAuthorizeMap.get(mdn));
                        subscriberDTO.setIsOSMAuthorize(osmAuthorizeMap.get(mdn));
                    }
                    if (corpSubscriberMap != null && corpSubscriberMap.get(mdn) != null) {
                        boolean bitEnabled = KnGeneralUtil.getFeatureBitValue(corpSubscriberMap.get(mdn).getSubsActiveFS2(), FEATURE_SET.AFFILIATIONFEATURE.value());
                        if (corpSubscriberMap.get(mdn).getClientPVmajorVer() >= com.kodiak.xdms.server.common.resources.KnConstants.PROTOCOL_VERSION_18 &&
                                bitEnabled && checkClientType(corpSubscriberMap.get(mdn).getClientType(), corpSubscriberMap.get(mdn).getMcpttCompliance())) {
                            corpContactDTO.setIsAffiliationEnabled(ENABLED);
                        } else {
                            corpContactDTO.setIsAffiliationEnabled(DISABLED);
                        }

                        int pv = corpSubscriberMap.get(mdn).getClientPVmajorVer();
                        if (pv >= com.kodiak.xdms.server.common.resources.KnConstants.PROTOCOL_VERSION_20 ) {
                            allMemList.add(mdn);
                        }
                    }
                    memList.add(corpContactDTO);
                }
                Map<Integer, Collection<KnCorpContactDTO>> groupMemberList = new HashMap<>(memList.size());
                groupMemberList.put(groupInfoDTO.getGroupId(), memList);
                groupInfoUtil.insertIntoCorpGroupMemberList(groupMemberList, xdmsHome, persisterTxn);
                if (isLargeGroup) {
                    sublistInfoUtil.updateSublistsSubscribersContactCount(addedSublistIds, MAX_LIMIT_VALIDATION_NOT_REQUIRED,
                            MAX_LIMIT_VALIDATION_NOT_REQUIRED, MAX_LIMIT_VALIDATION_NOT_REQUIRED, xdmsHome, persisterTxn, corpProfile.getMaxMemPerLrgBGrp());
                } else {
                    sublistInfoUtil.updateSublistsSubscribersContactCount(addedSublistIds, MAX_LIMIT_VALIDATION_NOT_REQUIRED,
                            MAX_LIMIT_VALIDATION_NOT_REQUIRED, MAX_LIMIT_VALIDATION_NOT_REQUIRED, xdmsHome, persisterTxn, corpProfile.getMaxMemPerBCGrp());
                }

                Collection<Integer> groupIdLst = new ArrayList<>();
                groupIdLst.add(groupId);
                int memberCount = groupInfoUtil.getGroupMemCount(groupIdLst, xdmsHome, persisterTxn).get(groupId);
                if (memberCount > corpProfile.getMaxMemPerBCGrp()) {
                    Map<Integer, Integer> groupLrgGrpFlagMap = new HashMap<>(1);
                    groupLrgGrpFlagMap.put(groupId, 1);
                    groupInfoUtil.updateIsLargeGrpFlag(groupLrgGrpFlagMap, xdmsHome, persisterTxn);
                }

                //setting external members
                if(!externalMdnList.isEmpty()){
                    knLogger.debug(methodName," externalMdnList :",externalMdnList);
                    allMemList.addAll(externalMdnList);
                    groupInfoDTO.setExternalMdnList(externalMdnList);
                }
                Integer preConfGroup=groupInfoDTO.getIsPreConfiguredGroup();
                groupInfoDTO.setIsPreConfiguredGroup(preConfGroup);
                if(isUgwInterop) {
                    groupInfoDTO.setUgwInterop(groupInfoDTO.getUgwInterop());
                }
                //update etags
                Map<Integer, Integer> groupEtagMap = new HashMap<Integer, Integer>();
                groupEtagMap.put(groupId, etag);
                Map<Integer, Collection<String>> grpMemMap = new HashMap<Integer, Collection<String>>();
                allMemList.addAll(bcGrpPersistDTO.getGrpBroadcasters());
                grpMemMap.put(groupId, allMemList);
                knLogger.debug(methodName,"after grpMemMap - ",KnGDPRTemplate.mapMdnAsValue(grpMemMap));
                Map<Integer, KnCorpGroupDTO> groupDetailsMap = new HashMap<Integer, KnCorpGroupDTO>();
                groupDetailsMap.put(groupId, groupInfoDTO);


                List<String> preConfigGroupMdns=new ArrayList<>();
                boolean isPreConfGroup=preConfGroup!=null&&preConfGroup.equals(ENABLED);
                Integer grpShared = groupInfoDTO.getGrpShared();
                if(isPreConfGroup){
                    List<Integer> intSharedCorpIds =new ArrayList<>();
                    if(grpShared!=null&&grpShared.equals(ENABLED)){
                        List<KnCorpSharedCorpInfo> corpSharedCorpInfos = groupInfoDTO.getCorpSharedCorpInfoList();
                        intSharedCorpIds = corpSharedCorpInfos.stream().map(KnCorpSharedCorpInfo::getCorpId).collect(Collectors.toList());
                    }
                    preConfigGroupMdns=commonInfoUtil.getAllPreConfigGroupMdns(corpId,grpShared,intSharedCorpIds,xdmsHome, persisterTxn);
                    grpMemMap.put(groupId, preConfigGroupMdns);
                }

                Map<String, KnOPDirChgDTO> etagMap = commonInfoUtil.formSubscriberNotification(grpMemMap, groupEtagMap,
                        com.kodiak.xdms.server.common.resources.KnConstants.DOC_CHANGE_TYPE.ADD.value(), null, groupDetailsMap, null);
                etagMap = contactInfoUtil.updateDistinctSubcribersDirectory(allMemList,
                        groupEtagMap.keySet(), etagMap, xdmsHome, persisterTxn);

                if(!groupInfoDTO.isUpmCall()) {
                    Map<String, Collection<KnDocChangeListDTO>> profileMdnEtagMap = corpUserProfileUtil.profileMdnEtagUpdateForCreateGroup(
                            null
                            , String.valueOf(corpId),allMemList
                            ,"1", xdmsHome, persisterTxn);
                    respDto.setProfileMdnEtagMap(profileMdnEtagMap);
                    if (profileMdnEtagMap != null && !profileMdnEtagMap.isEmpty()) {
                        respDto.setMcsXcapRootUriMap(genInfoUtil.getXCAPRootURI(new ArrayList<>(profileMdnEtagMap.keySet()), persisterTxn, true));
                    }
                }

                //setting the group id and name in response
                KnCorpGroupInfoDTO knCorpGroupInfoDTO = new KnCorpGroupInfoDTO();
                knCorpGroupInfoDTO.setGroupId(groupId);
                knCorpGroupInfoDTO.setGroupDisplayName(groupInfoDTO.getGroupDisplayName());
                knCorpGroupInfoDTO.setGroupMemberCount(memberCount);
                knCorpGroupInfoDTO.setGrpShared(groupInfoDTO.getGrpShared());
                if (memberCount == corpProfile.getMaxMemPerBCGrp()) {
                    knCorpGroupInfoDTO.setMaxGroupMemLimitFlag(EQUAL_TO_LIMIT);
                } else {
                    knCorpGroupInfoDTO.setMaxGroupMemLimitFlag(LESS_THAN_LIMIT);
                }
                knCorpGroupInfoDTO.setGroupType(groupInfoDTO.getGroupType());
                if (groupInfoDTO.getAvatar() != null && groupInfoDTO.getAvatar() != AVATAR_NOT_MODIFIED) {
                    knCorpGroupInfoDTO.setAvatar(groupInfoDTO.getAvatar());
                }
                knCorpGroupInfoDTO.setIsPreConfiguredGroup(groupInfoDTO.getIsPreConfiguredGroup());
                if(isUgwInterop){
                    knCorpGroupInfoDTO.setUgwInterop(groupInfoDTO.getUgwInterop());
                }
                //In case of group creation without any members pochome is set to null hence sipProxyUri as well is set to null.
                String sipProxyUri = null;
                if (pocHome != null) {
                    final String finalPocHome = pocHome;
                    sipProxyUri = sipProxySvcConfigInfoDTO.stream()
                            .filter(sipProxy -> sipProxy.getPttServerId().equals(finalPocHome))
                            .findFirst()
                            .map(KnSIPProxySvcConfigDTO::getSipProxyURI)
                            .orElse(null);
                }
                knCorpGroupInfoDTO.setGrpSIPUri(commonInfoUtil.mcpttGroupUri(groupId, corpId, sipProxyUri));

                if (null != knCorpGroupInfoDTO.getUgwInterop() && knCorpGroupInfoDTO.getUgwInterop().equals(7)) {
                    knCorpGroupInfoDTO.setUgwInterop(UGWINTEROP_DBVALUE);
                } else {
                    knCorpGroupInfoDTO.setUgwInterop(groupInfoPersistDTO.getUgwInterop());
                }
                knCorpGroupInfoDTO.setVideoPermission(groupInfoDTO.getVideoPermission() != null ? groupInfoDTO.getVideoPermission() : 0); // fix: null-safe
                respDto.setGroupInfoDTO(knCorpGroupInfoDTO);
                knLogger.info(methodName, "etagMap - ", KnGDPRTemplate.mapKeyMdn(etagMap));
                if (persistDto != null && persistDto.getGroupMdnList() != null && !persistDto.getGroupMdnList().isEmpty()) {
                    for (String grpMdn : persistDto.getGroupMdnList()) {
                        etagMap.remove(grpMdn);
                    }
                }
                respDto.setChangeLogMap(etagMap);
                //Populating the LI Data
                LinkedList<KnLIEventDTO> liEventList = populateAddGroupLIData(etagMap, xdmsHome,
                        groupInfoDTO, bcGrpPersistDTO.getAllDistinctMemebrs(),persisterTxn);
                respDto.setLiEventList(liEventList);
                respDto.setEtag(String.valueOf(etag));
                respDto.setAddedGroupDistributionMember(bcGrpPersistDTO.getGrpBroadcasters());

                //Since in create group notification, xdm is notr setting diff data. Getting the name and other info and seting
                Map<String, KnSubscriberDTO> memDetails = contactInfoUtil.getSubscribersNameForCorp(new ArrayList<>(allDistinceMembers), corpId, xdmsHome, persisterTxn);
                for (KnCorpContactDTO contactDTO : memList) {
                    KnSubscriberDTO subscriberDTO = memDetails.get(contactDTO.getMdn());
                    if (null != subscriberDTO) {
                        contactDTO.setName(subscriberDTO.getNetworkName());
                        contactDTO.setClientType(subscriberDTO.getClientType());
                        contactDTO.setContact_type(subscriberDTO.getContact_type());
                        contactDTO.setMcpttCompliance(subscriberDTO.getMcpttCompliance());
                    }
                }

                respDto.setMdnCorpId(corpId);
                respDto.setAddedGroupMember(memList);
                respDto.setGroupCreatedBy(groupInfoDTO.getGroupCreatedBy());
                respDto.setVideoPermission(groupInfoDTO.getVideoPermission() != null ? groupInfoDTO.getVideoPermission() : 0); // fix: null-safe
                populate(respDto);
                if (responseDTO.getFailedDataList() != null && !responseDTO.getFailedDataList().isEmpty()) {
                    respDto.setFailedDataList(responseDTO.getFailedDataList());
                }
                //If the corporate is already linked i.e linked gateway key is not null get the refernce id
                if (corpProfile.getLinkedGwKey() != null && persistDto.isGrpMdnPresent()) {
                    //get the refernce id from the account info table.
                    KnCorpGWLinkedAccountInfoDTO accountInfo = commonInfoUtil.getCorporateLinkedAccountInfo(corpProfile.getLinkedGwKey(), xdmsHome, persisterTxn);
                    //update etag in the account info table
                    //update etag
                    Map<String, String> asyncInput = new HashMap<>();
                    asyncInput.put(KnDbSyncFwConstants.PTTSERVER_ID, xdmsHome);
                    asyncInput.put(KnDbSyncFwConstants.NNI_REF_ID, accountInfo.getNniRefId());
                    knLogger.debug(methodName, " Async inputs", asyncInput);
                    KnSqlJobCollector collector = KnSqlJobCollector.getInstance();
                    int serviceType = KnDbSyncFwConstants.EXECUTOR.ETAG_UPDATE_NNI.value();
                    collector.collect(serviceType, asyncInput);

                }
            }
            if (groupInfoDTO.getHierarchyType() == HIERARCHY_TYPE.HIERARCHY) {
                String idType = (String) customParams.get(IDTYPE);
                List<String> ownerIdList = groupInfoDTO.getOwnerIdList();
                knLogger.info(methodName, "Enter into hierarchy path with groupId,ownerIdList ", groupInfoDTO.getGroupId(), ownerIdList);
                if (null != ownerIdList && !ownerIdList.isEmpty()) {
                    groupInfoUtil.insertGroupHiearchyMap(groupInfoDTO.getGroupId(), ownerIdList, idType, xdmsHome, persisterTxn);
                } else {
                    List<String> idListStr = (List<String>) customParams.get(com.kodiak.common.resources.KnConstants.IDLIST);
                    knLogger.info(methodName, "idListStr::", idListStr);
                    groupInfoUtil.insertGroupHiearchyMap(groupInfoDTO.getGroupId(), idListStr, idType, xdmsHome, persisterTxn);
                }
            }

            //Changes for PDMBB-12990
            //Assign Zones and Position
            //If new flag is not null and is enabled then only do below
            //int clusterId = Integer.parseInt(System.getenv(CLUSTERID_ENV_NAME));
            String autoAssignZoneChannelFlag = genInfoUtil.retrieveMSSvcsCommonConfig(clusterId, persisterTxn)
                    .get(AUTO_ASSIGN_ZONE_POSITION);
            knLogger.debug(methodName, "autoAssignZoneChannelFlag:", autoAssignZoneChannelFlag);
            // If auto-assign is disabled, return disabled status
            Collection<KnCorpContactDTO> memberListToBeAdded = groupInfoDTO.getAddedMemberDTOMdns();
            if (autoAssignZoneChannelFlag != null && autoAssignZoneChannelFlag.equals("1") && (memberListToBeAdded != null && !memberListToBeAdded.isEmpty())) {
                Map<String, Object> assignmentResult = performAutoAssignZonesAndChannels(
                        Arrays.asList(groupInfoDTO.getGroupId()),
                        memberListToBeAdded,
                        corpProfile,
                        contactInfoUtil,
                        persisterTxn
                );
                String autoZonePositionStatus = (String) assignmentResult.get("status");
                // After performAutoAssignZonesAndChannels succeeds update notification with zone/channel data
                if (ZONE_ASSIGNMENT_STATUS.ASSIGNED.value().equals(autoZonePositionStatus) || ZONE_ASSIGNMENT_STATUS.PARTIAL.value().equals(autoZonePositionStatus)) {
                    Map<String, KnOPDirChgDTO> changeLogMap = updateAddlTGNotification(
                            groupInfoDTO.getGroupId(), respDto.getChangeLogMap(), xdmsHome, persisterTxn);
                    respDto.setChangeLogMap(changeLogMap);
                }
                List<String> unassignedMdns = (List<String>) assignmentResult.get("unassignedMdns");
                respDto.setZonePositionAssignmentStatus(autoZonePositionStatus);
                if (unassignedMdns != null && !unassignedMdns.isEmpty()) {
                    respDto.setUnassignedMdns(unassignedMdns);
                }
                knLogger.debug(methodName, "respDto with zonePositionAssignmentStatus:", respDto.getZonePositionAssignmentStatus());
            }
            else{
                respDto.setZonePositionAssignmentStatus(ZONE_ASSIGNMENT_STATUS.DISABLED.value());
                knLogger.info(methodName, "Auto-assignment disabled. Status:", respDto.getZonePositionAssignmentStatus());
            }
        } catch (KnValidationException ve) {
            knLogger.error(methodName, "KnValidationException occured while create Group - ", ve);
            populate(respDto, ve);
        } catch (KnCorpBOException be) {
            knLogger.error(methodName, "KnCorpBOException occured while create Group - ", be);
            populate(respDto, be);
        } catch (Exception e) {
            knLogger.error(methodName, "KnValidationException occured while create Group - ",
                    new KnException(KnErrorCodes.BOEntity.INTERNAL_ERROR, e.getMessage(), e));
            populate(respDto, e);
        }
        return respDto;
    }


    private void populateBCGData(Collection<KnCorpContactDTO> addedMemberMdnsDTOLst,
                                 Collection<KnCorpGroupMemberDTO> sublistMemBrdstr,
                                 KnCorpGroupInfoPersistDTO subscPersistDTO) {
        String methodName = "populateBCGData(Collection<KnCorpContactDTO>, Collection<KnCorpGroupMemberDTO>)";
        knLogger.debug(methodName, "ENTRY : ", addedMemberMdnsDTOLst, sublistMemBrdstr, subscPersistDTO);
        Collection<String> addedMemberMdns = new ArrayList<>();
        Collection<KnCorpSubscriberDTO> corpSubscriberDTOList = new ArrayList<KnCorpSubscriberDTO>();
        List<String> broadcasterList = new ArrayList<>();
        Map<String, Integer> groupModifyPermission = new HashMap<>();
        Map<String, Integer> osmAuthorize = new HashMap<>();
        for (KnCorpContactDTO contact : addedMemberMdnsDTOLst) {
            String mdn = contact.getMdn();
            addedMemberMdns.add(mdn);
            KnCorpSubscriberDTO corpSubscriberDTO = new KnCorpSubscriberDTO();
            corpSubscriberDTO.setMdn(mdn);
            corpSubscriberDTOList.add(corpSubscriberDTO);
            int broadcaster = contact.getBroadcaster();
            if (BROADCAST_BROUP_BROADCASTER == broadcaster) {
                broadcasterList.add(mdn);
            }
            groupModifyPermission.put(mdn, contact.getGroupModifyPerm());
            osmAuthorize.put(contact.getMdn(), contact.getIsOSMAuthorize());
        }
        for (KnCorpGroupMemberDTO memberDTO : sublistMemBrdstr) {
            int broadcaster = memberDTO.getBroadcaster();
            if (BROADCAST_BROUP_BROADCASTER == broadcaster) {
                broadcasterList.add(memberDTO.getMdn());
            }
            groupModifyPermission.put(memberDTO.getMdn(), memberDTO.getGroupModifyPerm());
        }
        subscPersistDTO.setAddedMdnList(addedMemberMdns);
        subscPersistDTO.setAddedMdnDTO(corpSubscriberDTOList);
        subscPersistDTO.setGrpBroadcasters(broadcasterList);
        subscPersistDTO.setGrpModifyPermMap(groupModifyPermission);
        subscPersistDTO.setOsmAuthorizeMap(osmAuthorize);
        knLogger.debug(methodName, "Exit : ", subscPersistDTO);
    }

    public KnCorpGrpBasicInfoRespDto getBasicGrpInfo(KnIPCorpGroupInfoDTO groupInfoDTO, KnPersisterTxn persisterTxn) {
        String methodName = "getBasicGrpInfo(KnIPCorpGroupInfoDTO, KnPersisterTxn)";
        KnCorpGrpBasicInfoRespDto respDTO = new KnCorpGrpBasicInfoRespDto();
        try {
            String xdmsHome = KnGeneralUtil.getXDMServerPttServerId();
            int requestCorpid = groupInfoDTO.getCorpId();
            respDTO.setOwnerCorpReq(Boolean.TRUE);
            //retrieve group details information

            //changes for group sharing
            //check whether for the given corpId any shared groups are avilable or not
            //if any shared groups are avilable then add shared group info to dbGroupList to avoid rules


            //  if(groupPersistDTO.getGrpShared()!=null && groupPersistDTO.getGrpShared() == GROUP_SHARING_ENABLE_INDICATOR) {
            Map<Integer,List<KnCorpSharedCorpInfo>> sharedCorpInfoMap =
                    groupInfoUtil.selectGroupSharedCorpInfoBySharedCorpId(requestCorpid, xdmsHome, persisterTxn);

            if (sharedCorpInfoMap != null && !sharedCorpInfoMap.isEmpty()) {
                List<KnCorpSharedCorpInfo> sharedCorpInfoList = sharedCorpInfoMap.get(groupInfoDTO.getGroupId());
                if(sharedCorpInfoList!=null && !sharedCorpInfoList.isEmpty()) {
                    Optional<Integer> sharedGroupOwenerCorpId = sharedCorpInfoList.stream().
                            filter(knCorpSharedCorpInfo -> knCorpSharedCorpInfo.getCorpId() == groupInfoDTO.getCorpId()).
                            map(KnCorpSharedCorpInfo::getOwnerCorpId).
                            findFirst();
                    knLogger.debug(methodName, "sharedGroupOwenerCorpId", sharedGroupOwenerCorpId);
                    //Set owner corpid if the request group is shared group

                    if(sharedGroupOwenerCorpId.isPresent()) {
                        groupInfoDTO.setCorpId(sharedGroupOwenerCorpId.get());
                        respDTO.setOwnerCorpReq(Boolean.FALSE);
                    }else {
                        groupInfoDTO.setCorpId(requestCorpid);
                    }
                }
            }
            knLogger.debug(methodName, "groupInfoDTO", groupInfoDTO);
            // }
            boolean hiearchyCall = groupInfoDTO.getHierarchyType() == HIERARCHY_TYPE.HIERARCHY;
            String userProfileId = groupInfoDTO.getUseProfileId();
            knLogger.debug(methodName," userProfileId1:",userProfileId);
            KnCorpGroupInfoPersistDTO groupPersistDTO = null;
            if(userProfileId!=null){
                ArrayList<String> upmId = new ArrayList<>();
                upmId.add(userProfileId);
                Map<String, Integer> upmOwnerList = corpUserProfileUtil.getUserProfileOwnerinfo(upmId, xdmsHome, persisterTxn);
                if(!upmOwnerList.isEmpty()){
                    groupInfoDTO.setCorpId(upmOwnerList.get(userProfileId));
                    groupPersistDTO = groupInfoUtil.getGroupBasicInfoDetailsWithoutCorpId(groupInfoDTO, xdmsHome, persisterTxn,hiearchyCall);
                }
            }
            if (groupPersistDTO == null) {
                groupPersistDTO = groupInfoUtil.getGroupBasicInfoDetails(groupInfoDTO, xdmsHome, persisterTxn, hiearchyCall);
            }
            knLogger.debug(methodName, "Retrieved Corp Group Info - ", groupPersistDTO);


            //setting back the request corpId in request
            groupInfoDTO.setCorpId(requestCorpid);
            respDTO.setGroupId(groupPersistDTO.getGroupId());
            respDTO.setGroupListId(groupPersistDTO.getGroupMemberListId());
            respDTO.setGrpDisplayName(groupPersistDTO.getGroupDisplayName());
            respDTO.setGrpType(groupPersistDTO.getGroupType());
            respDTO.setGrpEtag(groupPersistDTO.getETag());
            //fetching corpId from groupInfoDTO due to group sharing owner group id can be diffrent than input requet corpId
            respDTO.setCorpId(requestCorpid);
            respDTO.setLmrInteropCapable(groupPersistDTO.getLmrInteropCapable());
            respDTO.setGrpOwner(groupPersistDTO.getTpGroupOwner());
            respDTO.setGroupCreateBy(groupPersistDTO.getGroupCreatedBy());
            respDTO.setLargeGroup(groupPersistDTO.isLargeGroup());
            respDTO.setMcxGrpInd(groupPersistDTO.getMcxGrpInd());
            respDTO.setGroupProfileId(groupPersistDTO.getGroupProfileId());
            respDTO.setGrpShared(groupPersistDTO.getGrpShared());
            respDTO.setGroupCorpId(Integer.parseInt(groupPersistDTO.getGrpOwnerCorpId()));
            respDTO.setOverrideDnd(groupPersistDTO.getOverrideDnd());
            respDTO.setIsPreConfiguredGroup(groupPersistDTO.getIsPreConfiguredGroup());
            respDTO.setUgwInterop(groupPersistDTO.getUgwInterop());
            respDTO.setRecordingFs(groupPersistDTO.getRecordingFs());
            respDTO.setAuthorizedLargeTG(groupPersistDTO.getAuthorizedLargeTG());
            respDTO.setHierarchyId(groupPersistDTO.getHierarchyId());
            populate(respDTO);
        } catch (KnCorpBOException e) {
            knLogger.error(methodName, "KnCorpBOException occured while retrieving group basic info - ", e);
            populate(respDTO, e);
        } catch (Exception e) {
            knLogger.error(methodName, "Unexpected Exception occured while retrieving group basic info  - ", new KnException(KnErrorCodes.BOEntity.INTERNAL_ERROR, e.getMessage(), e));
            populate(respDTO, e);
        }
        knLogger.debug(methodName, "Exit - ", respDTO);
        return respDTO;
    }

    @Override
    public KnCorpResponseDTO modifyBCGroup(KnIPCorpGroupInfoDTO groupInfoDTO, KnCorpGrpBasicInfoDTO grpBasicInfo, KnPersisterTxn persisterTxn) {
        String methodName = "modifyBCGroup(KnIPCorpGroupInfoDTO, KnCorpGrpBasicInfoDTO, KnPersisterTxn)";
        knLogger.info(methodName, "ENTRY : Input DTO Passed - ", groupInfoDTO, ", grpBasicInfo - ", grpBasicInfo);
        KnCorpGroupInfoRespDTO respDto = new KnCorpGroupInfoRespDTO();
        String loggedInHierarchyId;
        try {
            int corpId = groupInfoDTO.getCorpId();
            int grpId = groupInfoDTO.getGroupId();
            boolean upmCall = groupInfoDTO.isUpmCall();
            boolean isHierarchyFlow = false;
            String idType = null;
            //boolean osmListChanged=false;
            //Step:
            //get the Corp profile details from cache
            knLogger.debug(methodName, "Fetch the corpProfile profile if cached or fetch from the DB the details");
            KnCorpProfileDTO corpProfile = commonInfoUtil.getProfileDetails("" + corpId, CORP_PROFILE, false, persisterTxn);

            int intCorpId = corpProfile.getCorpId();
            String extCorpId = corpProfile.getExtCorpId();
            String networkName = corpProfile.getNetworkName();

            String xdmsHome = corpProfile.getXdmsHome();
            String corpPocHome=corpProfile.getPocHome();
            int groupID = groupInfoDTO.getGroupId();
            List<String> groupIDList = new ArrayList<>();
            groupIDList.add(String.valueOf(groupID));
            commonInfoUtil.validateCorpAndGroupParams(groupIDList, String.valueOf(corpId), xdmsHome, persisterTxn);
            //custom call to the Custom Hook
            //Invoking custom hook
            KnCorpHookRespDTO responseDTO = new KnCorpHookRespDTO();
            Map<String, Object> customParams = groupInfoDTO.getCustomParamMap();
            loggedInHierarchyId = KnCorpUtil.getLoggedInHierarchy(customParams);
            if (groupInfoDTO.getHierarchyType() == HIERARCHY_TYPE.HIERARCHY && null != customParams) {
                knLogger.debug(methodName, "before validating checking OwnerIdList :", groupInfoDTO.getAddedOwnerIdList());
                if (null != groupInfoDTO.getAddedOwnerIdList() && !groupInfoDTO.getAddedOwnerIdList().isEmpty()) {
                    groupInfoUtil.validateFanIds(corpId, groupInfoDTO.getAddedOwnerIdList(), xdmsHome, persisterTxn);
                }
                customParams.put(CURRENT_MASTER_LIST_ETAG, corpProfile.getCorpMasterListEtag());
                customParams.put(PERSISTER_TXN, persisterTxn);
                customParams.put(PTT_SERVER_ID, xdmsHome);
                groupInfoDTO.setCustomParamMap(customParams);
                KnCorpHookIPDTO hookIPDTO = new KnCorpHookIPDTO();
                hookIPDTO.setAction(KnActions.ACTIONS.MODIFY_GROUP);
                hookIPDTO.setData(groupInfoDTO);
                KnProcessInvokerImpl processInvoker = KnProcessInvokerImpl.getInstance();
                Object hookResp = processInvoker.invokeHook(CUSTOM_CORP_USER_HOOK, hookIPDTO);
                if (hookResp instanceof KnCorpHookRespDTO) {
                    responseDTO = (KnCorpHookRespDTO) hookResp;
                    if (com.kodiak.xdms.server.common.resources.KnConstants.RESPONSE_STATUS.FAILURE.value() == responseDTO.getStatus()) {
                        knLogger.error(methodName, "Returning Failure response");
                        populateXdmResponseFroomHook(responseDTO, respDto);
                        return respDto;
                    }
                    isHierarchyFlow = true;
                    idType = (String) groupInfoDTO.getCustomParamMap().get(IDTYPE);
                    groupInfoDTO.setAddedOwnerIdList(responseDTO.getAddedOwnerIdList());
                }
                Collection<String> idListStr = (Collection<String>) customParams.get(com.kodiak.common.resources.KnConstants.IDLIST);
                Object idTypeObj = customParams.get(IDTYPE);
                int idTypeValues;
                if (idTypeObj instanceof Integer) {
                    idTypeValues = (Integer) idTypeObj;
                } else if (idTypeObj instanceof String) {
                    idTypeValues = Integer.parseInt((String) idTypeObj);
                } else {
                    throw new IllegalArgumentException("Unsupported type for IDTYPE: " + idTypeObj.getClass().getName());
                }
                if (idListStr != null) {
                    List<Integer> idListInt = (List<Integer>) convertStrToIntColl(idListStr);
                    List<String> groupIdList = List.of(String.valueOf(groupInfoDTO.getGroupId()));
                    commonInfoUtil.validateGroupParams(groupIdList, String.valueOf(corpId), idListInt, xdmsHome, idTypeValues, persisterTxn);
                }
            }
            if (isHierarchyFlow) {
                List<Integer> idListValues = new ArrayList<>();
                ((List<String>) groupInfoDTO.getCustomParamMap().get(com.kodiak.common.resources.KnConstants.IDLIST)).forEach(
                        idValue -> idListValues.add(Integer.parseInt(idValue))
                );
                Map<Integer, Integer> idValGroupidMap = new HashMap<>();
                groupInfoUtil.getOwnerAndSharedContextIdByGroupIds(List.of(grpId), idType, corpProfile.getXdmsHome(), true, persisterTxn)
                        .forEach((k, v) -> idValGroupidMap.put(Integer.parseInt(k), v));
                boolean isOwnerRequest = groupInfoUtil.isOwner(idValGroupidMap, idListValues);
                knLogger.debug(methodName, " owner req ", isOwnerRequest);
                groupInfoDTO.setOwnerCorpReq(isOwnerRequest);
            }
            if (groupInfoDTO.getCustomParamMap() != null) {
                Object idTypeObj = groupInfoDTO.getCustomParamMap().get(IDTYPE);
                if (idTypeObj != null && Integer.parseInt(String.valueOf(idTypeObj)) == Integer.parseInt(HIER_CTX_ID_TYPE)) {
                    List<String> idList = (List<String>) groupInfoDTO.getCustomParamMap().get(com.kodiak.common.resources.KnConstants.IDLIST);
                    if (idList != null && !idList.isEmpty()) {
                        groupInfoDTO.setRequestingHierarchyId(idList.get(0));
                    }
                }
            }

            //Step:
            //Populate the basic group information from request object
            boolean isUgwInterop = (null != groupInfoDTO.getUgwInterop() && groupInfoDTO.getUgwInterop().equals(7));
            knLogger.debug("isUgwInterop Modify: ",isUgwInterop);
            KnCorpGroupInfoPersistDTO groupPersistDTO = new KnCorpGroupInfoPersistDTO();
            groupPersistDTO.setGroupId(grpBasicInfo.getGroupId());
            groupPersistDTO.setGroupDisplayName(grpBasicInfo.getGrpDisplayName());
            groupPersistDTO.setGroupType(grpBasicInfo.getGrpType());
            groupPersistDTO.setGroupMemberListId(grpBasicInfo.getGroupListId());
            groupPersistDTO.setCorpId(grpBasicInfo.getCorpId());
            groupPersistDTO.setETag(grpBasicInfo.getGrpEtag());
            groupPersistDTO.setGroupProfileId(grpBasicInfo.getGroupProfileId());
            knLogger.debug(methodName, "Retrieved Corp Group Info - ", groupPersistDTO);
            groupInfoDTO.setGroupMemberListId(grpBasicInfo.getGroupListId());
            //Broadcast group persist DTO for validation.
            KnCorpBCGrpPersistDTO bcGrpPersistDTO = new KnCorpBCGrpPersistDTO();
            bcGrpPersistDTO.setInputDTO(groupInfoDTO);
            bcGrpPersistDTO.setCorpId(grpBasicInfo.getGroupCorpId());
            bcGrpPersistDTO.setOwnerHierarchyId(grpBasicInfo.getHierarchyId());
            //Setting the system level Broadcast group feature
            if (DB_ENABLED_VALUE == corpProfile.getEnableBCGrpFeature()) {
                bcGrpPersistDTO.setSysBCGFeatue(Boolean.TRUE);
            }

            String groupName = null;
            if (grpBasicInfo.getGroupCreatedBy() == CREATED_BY.CAT_ADMIN.value()) {
                groupName = groupInfoDTO.getGroupDisplayName();
            } else {
                groupName = groupInfoDTO.getNewGroupDisplayName();
            }
            //get Group count by group name
            if (!isNullOrEmpty(groupName)) {
                int count = groupInfoUtil.getGroupCountByName(groupName, corpId, xdmsHome, persisterTxn);
                if (count > 0 && !groupName.equals(groupPersistDTO.getGroupDisplayName())) {
                    bcGrpPersistDTO.setGroupNameCount(count);
                } else if (groupName.equals(groupPersistDTO.getGroupDisplayName())) {
                    groupInfoDTO.setGroupDisplayName(null);
                }
            } else {
                groupName = grpBasicInfo.getGrpDisplayName();
            }
            if (groupInfoDTO.getNewGroupDisplayName() != null && !groupInfoDTO.getNewGroupDisplayName().equals(groupPersistDTO.getGroupDisplayName())) {
                groupInfoDTO.setGroupDisplayName(groupInfoDTO.getNewGroupDisplayName());
            }
            if (null != groupInfoDTO.getVideoPermission()) {
                groupPersistDTO.setVideoPermission(groupInfoDTO.getVideoPermission());
            }else{
                groupPersistDTO.setVideoPermission(grpBasicInfo.getVideoPermission());
            }
            Integer avatar = null;
            if (groupInfoDTO.getAvatar() != null && groupInfoDTO.getAvatar() != AVATAR_NOT_MODIFIED)
                avatar = groupInfoDTO.getAvatar();


            //Addeed Group members
            Collection<KnCorpContactDTO> addedMemberDTOLst = groupInfoDTO.getAddedMemberDTOMdns();
            //Added sublist Ids
            Collection<Integer> addedSublistIds = groupInfoDTO.getAddedSublistIds();
            //Removed Group members
            List<String> removedMemberList = groupInfoDTO.getRemovedMemberMdns();
            //Removed sublist Ids
            Collection<Integer> removedSublistIds = groupInfoDTO.getRemovedSublistIds();
            //Modified mmembers
            Collection<KnCorpGroupMemberDTO> modifiedMembers = groupInfoDTO.getModifiedMembers();

            // Validate max groups per subscriber
            Collection<String> addedMemberMdns = new ArrayList<>();
            for (KnCorpContactDTO contact : addedMemberDTOLst) {
                String mdn = contact.getMdn();
                addedMemberMdns.add(mdn);
            }
            Collection<KnCorpSubscriberDTO> subsInfo = contactInfoUtil.getSubscribersInfo(addedMemberMdns, xdmsHome, persisterTxn);
            Map<String, Integer> subsGroupCount = groupInfoUtil.getSubsScrGroupCountExceptABDG(
                    addedMemberMdns.stream().collect(Collectors.toList()), xdmsHome, persisterTxn);

            int clusterId = Integer.parseInt(System.getenv(CLUSTERID_ENV_NAME));
            Map<String, String> paramNameValueMapCommon = genInfoUtil.retrieveMSSvcsCommonConfig(clusterId, persisterTxn);

            boolean sysLargeAgencyDispatch = paramNameValueMapCommon.get(LARGE_AGENCY_DISPATCH_FEATURE).equalsIgnoreCase(ENABLED_STRING);
            boolean corpLargeAgencyDispatch = KnGeneralUtil.getFeatureBitValue(corpProfile.getCorpFS2(), FEATURE_SET.LARGE_AGENCY_DISPATCH.value());
            String pochomeAutoAssignValue = paramNameValueMapCommon.get(POCHOME_AUTOASSIGN_FLAG);
            boolean pochomeAutoAssignFlag = true;
            if(pochomeAutoAssignValue != null){
                pochomeAutoAssignFlag = ENABLED_STRING.equalsIgnoreCase(pochomeAutoAssignValue.trim());
            }
            knLogger.debug(methodName," pochomeAutoAssignFlag : ",pochomeAutoAssignFlag);

            bcGrpPersistDTO.setAddedMDNs(subsInfo);

            //Get the broadcasters in the group and set into groupPersistDTO.
            populateBCGData(addedMemberDTOLst, modifiedMembers, groupPersistDTO);

            //Get and separate the internal and external contacts for the corporation from request added mdn data
            KnCorpBCGrpPersistDTO persistDto = contactInfoUtil.getCorpSubscrDetails(groupPersistDTO.getAddedMdnList(), corpId, xdmsHome, persisterTxn);
            knLogger.debug(methodName, "persistDto - ", persistDto);
            boolean addedSGMdn = persistDto.isOnlyAddedGroupMdn();
            Map<String, Integer> groupModifyPermMap = groupPersistDTO.getGrpModifyPermMap();
            knLogger.debug(methodName, "groupModifyPermMap - ", KnGDPRTemplate.mapKeyMdn(groupModifyPermMap));
            Map<String, Integer> subscGrpCount = groupInfoUtil.getMembersGroupCount(persistDto.getGroupMdnList(), corpId, xdmsHome, persisterTxn);
            //get the group mdn from the removed mdn List
            List<String> removedGroupMdnList = new ArrayList<String>();
            if (groupPersistDTO.getRemovedMemberList() != null && !groupPersistDTO.getRemovedMemberList().isEmpty()) {
                removedGroupMdnList = contactInfoUtil.getGroupMdns(groupPersistDTO.getRemovedMemberList(), corpId, xdmsHome, persisterTxn);
                if (removedGroupMdnList != null && !removedGroupMdnList.isEmpty()) {
                    persistDto.setGrpMdnPresent(Boolean.TRUE);
                }
            }
            //Setting the group broadcasters
            bcGrpPersistDTO.setGrpBroadcasters(groupPersistDTO.getGrpBroadcasters());
            //Setting the valid internal and external subscribers and max allowed members per broadcast group.
            bcGrpPersistDTO.setValidExtContacts(persistDto.getValidExtContacts());
            bcGrpPersistDTO.setValidInternalCont(persistDto.getValidInternalCont());
            bcGrpPersistDTO.setMaxAllowedMemPerBCG(corpProfile.getMaxMemPerBCGrp());
            //Get the valid sublist ids in the corporation
            Collection<Integer> listCommonContactListRejectionIds = sublistInfoUtil.getCommonContactListRejectForGrp(addedSublistIds,corpId,xdmsHome,persisterTxn);
            knLogger.debug("CommonContactListRejectionList: ",listCommonContactListRejectionIds);
            bcGrpPersistDTO.setCommonContactRejectList(listCommonContactListRejectionIds);
            List<Integer> validAddedSublistIds = sublistInfoUtil.getValidSublistIdInfo(addedSublistIds, corpId, xdmsHome, persisterTxn);
            knLogger.debug(methodName, "validAddedSublistIds - ", validAddedSublistIds);
            bcGrpPersistDTO.setValidSublistIds(validAddedSublistIds);
            //Get the distinct added sublist members
            List<KnCorpSubscriberDTO> distinctAddedSublistMems = sublistInfoUtil.getSublistDistinctMembers(validAddedSublistIds, corpId, xdmsHome, persisterTxn);

            //Get sublist mapped to the group
            List<Integer> existSublist = groupInfoUtil.getGroupSublistIds(grpId, xdmsHome, persisterTxn);
            existSublist.remove(Integer.valueOf(groupPersistDTO.getGroupMemberListId()));
            bcGrpPersistDTO.setExistingSublistIds(existSublist);
            int privateSublistId = groupPersistDTO.getGroupMemberListId();
            List<Integer> privateListId = new ArrayList<>(1);
            privateListId.add(privateSublistId);
            List<KnCorpSubscriberDTO> privateMemDTOList = sublistInfoUtil.getSublistDistinctMembers(privateListId, corpId, xdmsHome, persisterTxn);
            knLogger.debug(methodName, "privateMemDTOList - ", privateMemDTOList);
            bcGrpPersistDTO.setPrivateMemList(privateMemDTOList);
            //Final member list to be there in private contact list
            List<KnCorpSubscriberDTO> finalPriMemList = new ArrayList<>();

            //Looping privateMemDTOList and adding into a list of String - privateMemList
            List<String> privateMemList = new ArrayList<>(privateMemDTOList.size());
            for (KnCorpSubscriberDTO subscriberDTO : privateMemDTOList) {
                privateMemList.add(subscriberDTO.getMdn());
                if (!removedMemberList.contains(subscriberDTO.getMdn())) {
                    finalPriMemList.add(subscriberDTO);
                }
            }
            KnCorpBCGrpPersistDTO bcGrpPerDTO = contactInfoUtil.getCorpSubscrDetails(privateMemList, corpId, xdmsHome, persisterTxn);
            //Loop through the added InterOp members check if its already part of the group via private list
            //its part of ignore else add to the List for which we need to detremine the Inter group Count.
            //persistDto -contains the newly added member details bcGrpPerDTO has the private members existing information
            List<String> newInterOp = new ArrayList<String>();
            if (persistDto != null && persistDto.getInterOpMembers() != null) {
                for (String mdn : persistDto.getInterOpMembers()) {
                    if (bcGrpPerDTO != null && bcGrpPerDTO.getInterOpMembers() != null && !bcGrpPerDTO.getInterOpMembers().contains(mdn)) {
                        newInterOp.add(mdn);
                    }/*else{
                            //newInterOp.add(mdn);
                             commenting this else because this block is empty. As per PMD Report.
                        }*/

                }
            }

            //oldLmrInteropFlag parameter is set as part of XDM-5959
            if (null != grpBasicInfo.getUgwInterop()) {
                respDto.setOldLmrInteropFlag(grpBasicInfo.getUgwInterop());
            } else if (null == grpBasicInfo.getUgwInterop() && !removedGroupMdnList.isEmpty()) {
                respDto.setOldLmrInteropFlag(UGWINTEROP_DBVALUE);
            } else if (null == grpBasicInfo.getUgwInterop()) {
                respDto.setOldLmrInteropFlag(UGWINTEROP_DBVALUE_DISABLED);
            }

            Map<String, KnCorpGroupMemberDTO> grpMemberMap = groupInfoUtil.getGroupMembersList(groupInfoDTO.getGroupId(), xdmsHome, persisterTxn);
            knLogger.debug("grpMemberMap--- ", KnGDPRTemplate.mapKeyMdn(grpMemberMap));
            bcGrpPersistDTO.setExistingGrpMemDetail(new ArrayList<>(grpMemberMap.values()));
            Map<String, Integer> existingGroupModifyPermMap = grpMemberMap.values().stream().collect(Collectors.toMap(KnCorpGroupMemberDTO::getMdn, KnCorpGroupMemberDTO::getGroupModifyPerm));
            //get The InterOp Subscriber Group Count
            Map<String, Integer> interGrpCount = groupInfoUtil.getExternalSubscriberGroupCount(newInterOp, corpId, xdmsHome, persisterTxn);
            bcGrpPersistDTO.setInterOpGrpCount(interGrpCount);
            //check if the existing interOP is getting deleted
            List<String> finalInterOps = new ArrayList<String>();
            if (bcGrpPerDTO != null && bcGrpPerDTO.getInterOpMembers() != null) {
                for (String mdn : bcGrpPerDTO.getInterOpMembers()) {
                    if (!groupInfoDTO.getRemovedMemberMdns().contains(mdn)) {
                        finalInterOps.add(mdn);
                    }
                }
            }
            finalInterOps.addAll(newInterOp);
            bcGrpPersistDTO.setInterOpMembers(finalInterOps);
            //Added private members for the validations to aviod Groupo mdn to be added again
            List<String> curreGrpMdns = bcGrpPerDTO.getGroupMdnList();
            knLogger.debug(methodName, "curreGrpMdns- ", KnGDPRTemplate.mdnList(curreGrpMdns));
            //removing if the group mdn are getting removed from the list to allow the new group mdn to be added
            knLogger.debug(methodName, "removedMemberList - ", KnGDPRTemplate.mdnList(removedMemberList));
            if (removedMemberList != null && curreGrpMdns != null) {
                curreGrpMdns.removeAll(removedMemberList);
            }

            List<KnCorpSubscriberDTO> grpMdnsDTO = contactInfoUtil.getGroupMdnInListDTO(curreGrpMdns, corpId, xdmsHome, persisterTxn);
            knLogger.debug(methodName, "grpMdnsDTO - ", grpMdnsDTO);
            bcGrpPersistDTO.setExistingGrpMdnDto(grpMdnsDTO);

            //Removing thr subscriber who is already part of group from the group count map
            if (curreGrpMdns != null) {
                for (String mdn : curreGrpMdns) {
                    subscGrpCount.remove(mdn);
                }
            }
            bcGrpPersistDTO.setGroupMdnGrpCnt(subscGrpCount);

            bcGrpPersistDTO.setMaxSGPerGrp(corpProfile.getMaxSGPerGrp());
            bcGrpPersistDTO.setMaxSGMdnPatchPerGroup(corpProfile.getMaxSGPatchPerGrp());

            knLogger.debug(methodName, "curreGrpMdns after the removal ofremovemdn list - ", KnGDPRTemplate.mdnList(curreGrpMdns));
            bcGrpPersistDTO.setGroupMdnList(curreGrpMdns);
            //Get the group existing member list
            List<String> existingMemList = sublistInfoUtil.selectGroupMemberList(grpId, xdmsHome, persisterTxn);
            bcGrpPersistDTO.setExistingGrpMembers(existingMemList);

            //Get the final private group members to be added into private group list.
            List<KnCorpSubscriberDTO> privtLstMemToBeAdded = new ArrayList<>();
            if (addedMemberDTOLst != null && !addedMemberDTOLst.isEmpty()) {
                for (KnCorpSubscriberDTO subscriberDTO : addedMemberDTOLst) {
                    String mdn = subscriberDTO.getMdn();
                    if (!privateMemList.contains(mdn)) {
                        privtLstMemToBeAdded.add(subscriberDTO);
                        finalPriMemList.add(subscriberDTO);
                    }
                }
            }

            knLogger.debug(methodName, "finalPriMemList - ", finalPriMemList);
            knLogger.debug(methodName, "privtLstMemToBeAdded - ", privtLstMemToBeAdded);
            //Added Sublist Ids
            List<Integer> finalSublistIdsToBeMapped = new ArrayList<>(existSublist);
            finalSublistIdsToBeMapped.removeAll(removedSublistIds);

            finalSublistIdsToBeMapped.addAll(addedSublistIds);

            //Get the distinct sublist members from  finalSublistIdsToBeMapped
            List<KnCorpSubscriberDTO> finalSublistDistMember = sublistInfoUtil.getSublistDistinctMembers(finalSublistIdsToBeMapped, corpId, xdmsHome, persisterTxn);
            //Get the final member List from finalSublistDistMember and privtLstMemToBeAdded
            List<KnCorpSubscriberDTO> finalGroupMemList = groupInfoUtil.getFinalBCGrpMemList(finalSublistDistMember, finalPriMemList);
            knLogger.debug(methodName, "finalGroupMemList - ", finalGroupMemList);
            Set<String> uniqueMcpttIds = new HashSet<String>();
            if (finalGroupMemList != null && !finalGroupMemList.isEmpty()) {
                List<String> mdns = finalGroupMemList.stream().map(knCorpSubscriberDTO -> knCorpSubscriberDTO.getMdn()).collect(Collectors.toList());
                // get the unique mcpttids in order to filter out the profile mdns from the list
                uniqueMcpttIds = groupInfoUtil.getUniqueMcpttIds(mdns, xdmsHome, persisterTxn);
            }
            bcGrpPersistDTO.setGroupMemberCount(uniqueMcpttIds.size());
            bcGrpPersistDTO.setFinalGroupMemList(finalGroupMemList);

            //Get the group existing distribution List
            List<Integer> grpIdList = new ArrayList<>(1);
            grpIdList.add(grpId);
            Map<Integer, Collection<String>> grpDistMap = groupInfoUtil.getGroupSubscriberDistList(grpIdList, xdmsHome, persisterTxn);
            knLogger.debug(methodName, "grpDistMap - ", KnGDPRTemplate.mapMdnAsValue(grpDistMap));
            //Existing broadcaster in the Group
            List<String> existingBroadcasters = new ArrayList<>(grpDistMap.get(grpId));
            bcGrpPersistDTO.setExistingBroadcasters(existingBroadcasters);
            //Existing members in Group
            Map<Integer, Collection<String>> existingMembersGroup = groupInfoUtil.selectGroupMemberListForGroupIds(grpIdList, xdmsHome, persisterTxn);
            List<String> existingMembers = new ArrayList<>() ;
            for (Entry<Integer, Collection<String>> ent : existingMembersGroup.entrySet()) {
                for (String member : ent.getValue()) {
                    existingMembers.add(member);
                }
            }
            //Iterate through the modifying member list and find the modifying broadcaster to non broadcaster member list
            //Modifying Non_broadcaster member list
            List<String> modifyingNonBrdstrMem = new ArrayList<>();
            for (KnCorpGroupMemberDTO groupMemberDTO : modifiedMembers) {
                if (groupMemberDTO.getBroadcaster() == BROADCAST_BROUP_NON_BROADCASTER) {
                    if (existingBroadcasters.contains(groupMemberDTO.getMdn())) {
                        modifyingNonBrdstrMem.add(groupMemberDTO.getMdn());
                    }
                }
                if (groupMemberDTO.getGroupModifyPerm() == null && existingGroupModifyPermMap.containsKey(groupMemberDTO.getMdn())) {
                    groupMemberDTO.setGroupModifyPerm(existingGroupModifyPermMap.get(groupMemberDTO.getMdn()));
                }
            }
            knLogger.debug(methodName, "modifyingNonBrdstrMem - ", KnGDPRTemplate.mdnList(modifyingNonBrdstrMem));
            //Get the final broadcasters in the group
            List<String> finalBroadcasters = new ArrayList<>(existingBroadcasters);
            finalBroadcasters.addAll(groupPersistDTO.getGrpBroadcasters());
            finalBroadcasters.removeAll(modifyingNonBrdstrMem);
            //Actually deleted group broadcasters .finalGroupMemList=CORPLISTMEMBER,finalBroadcasters=CORPGROUPDISTINFO
            //actualDeletedBrdstr=if not present in CORPLISTMEMBER but present in CORPGROUPDISTINFO
            List<String> actualDeletedBrdstr = getDeletedBroadcasters(finalGroupMemList, finalBroadcasters);
            actualDeletedBrdstr.addAll(modifyingNonBrdstrMem);
            knLogger.debug(methodName, "finalBroadcasters - ", KnGDPRTemplate.mdnList(finalBroadcasters));
            //Setting the group broadcasters
            bcGrpPersistDTO.setFinalBrdstrList(finalBroadcasters);
            //removing all profile mdn from the actualDeletedBrdstr, As we profile mdn impact is handled in upm path
            List<String> profileMdnList = corpSubsProvInfoUtil.getProfileMdns(actualDeletedBrdstr, xdmsHome, persisterTxn);
            actualDeletedBrdstr.removeAll(profileMdnList);
            knLogger.info(methodName,"after removing profileMdn actualDeletedBrdstr:",actualDeletedBrdstr);
            if(upmCall){
                actualDeletedBrdstr.clear();
                actualDeletedBrdstr.addAll(modifyingNonBrdstrMem);
                actualDeletedBrdstr.addAll(removedMemberList);
            }
            //recovering the stale records
            List<String> staleMdns = sublistInfoUtil.getNonExisitingGroupMemberInPrivSublist(grpId, xdmsHome, persisterTxn);
            if (!staleMdns.isEmpty()) {
                List<String> staleProfileMdnList = corpSubsProvInfoUtil.getProfileMdns(staleMdns, xdmsHome, persisterTxn);
                Collection<KnCorpSubscriberDTO> groupPrivateList = new ArrayList<>();
                for (String profileMdn : staleProfileMdnList) {
                    groupPrivateList.add(new KnCorpSubscriberDTO(profileMdn, privateSublistId, corpId));
                }
                knLogger.info(methodName, "Adding stale profile mdn:", groupPrivateList);
                contactInfoUtil.addPrivateContactList(groupPrivateList, xdmsHome, persisterTxn);
            }


            // Variable to hold all internal members (added member list + sublist members)
            List<String> allIntMemberList = new ArrayList<>();
            // Variable to hold all external members (added member list + sublist members)
            List<String> allExtMemberList = new ArrayList<>();
            //Loop through distinct sublist member list and add add to internal or external variables.
            for (KnCorpSubscriberDTO corpSubscriberDTO : distinctAddedSublistMems) {
                if (corpSubscriberDTO.isExternalContact()) {
                    allExtMemberList.add(corpSubscriberDTO.getMdn());
                } else {
                    allIntMemberList.add(corpSubscriberDTO.getMdn());
                }
            }

            List<String> sgMdnList = new ArrayList<>();
            List<String> sgMdnPatchList = new ArrayList<>();
            //Loop through the added valid internal member list and add to internal variable
            for (KnCorpSubscriberDTO corpSubscriberDTO : persistDto.getValidInternalCont()) {
                allIntMemberList.add(corpSubscriberDTO.getMdn());
                if (corpSubscriberDTO.getClientType() == GROUPMDN.value()) {
                    sgMdnList.add(corpSubscriberDTO.getMdn());
                    groupInfoDTO.setUgwInterop(UGWINTEROP_DBVALUE);
                    groupPersistDTO.setUgwInterop(UGWINTEROP_DBVALUE);
                } else if (corpSubscriberDTO.getClientType() == SUBSCR_CLIENT_TYPE.SGMDNPATCH.value()) {
                    sgMdnPatchList.add(corpSubscriberDTO.getMdn());
                    groupInfoDTO.setUgwInterop(UGWINTEROP_DBVALUE);
                    groupPersistDTO.setUgwInterop(UGWINTEROP_DBVALUE);
                }
            }

            //Loop through the added valid external member list and add to external variable
            for (KnCorpSubscriberDTO corpSubscriberDTO : persistDto.getValidExtContacts()) {
                allExtMemberList.add(corpSubscriberDTO.getMdn());
            }
            knLogger.debug(methodName, "allIntMemberList - ", KnGDPRTemplate.mdnList(allIntMemberList));
            knLogger.debug(methodName, "allExtMemberList - ", KnGDPRTemplate.mdnList(allExtMemberList));
            //Get the group count of all internal members.
            Map<String, Integer> subsGroupCountMap = groupInfoUtil.getMembersGroupCount(allIntMemberList,
                    xdmsHome, persisterTxn);
            knLogger.debug(methodName, "subsGroupCountMap - ", KnGDPRTemplate.mapKeyMdn(subsGroupCountMap));
            //Distict all members
            Set<String> allDistinceMembers = new HashSet<>(allIntMemberList);
            allDistinceMembers.addAll(allExtMemberList);
            bcGrpPersistDTO.setAllDistinctMemebrs(allDistinceMembers);

            //Get the group count of all external members
            Map<String, Integer> externalSubscGroupCountMap =
                    groupInfoUtil.getExternalSubscriberGroupCount(allExtMemberList, corpId, xdmsHome, persisterTxn);
            knLogger.debug(methodName, "externalSubscGroupCountMap - ", KnGDPRTemplate.mapKeyMdn(externalSubscGroupCountMap));
            subsGroupCountMap.putAll(externalSubscGroupCountMap);
            bcGrpPersistDTO.setSubsGroupCountMap(subsGroupCountMap);
            bcGrpPersistDTO.setMaxGroupsPerMemberCount(corpProfile.getMaxGroupsPerSubsc());
            List<Integer> sharedCorpListId = new ArrayList<>();
            if(groupInfoDTO.getUseProfileId() != null){
                sharedCorpListId = corpUserProfileUtil.getSharedCorpIdFromUserProfielId(groupInfoDTO.getUseProfileId(), xdmsHome, persisterTxn);
            }
            //Get the external profile maps for validation PreArranged and Broadcaster bits.
            Map<String, Map<Integer, KnExtProfileDetails>> extProfileMaps = commonInfoUtil.getExtProfileMaps(allExtMemberList, xdmsHome, corpId, persisterTxn, bcGrpPersistDTO,sharedCorpListId);
            bcGrpPersistDTO.setConfiguredProfileMap(extProfileMaps.get(CONFIGUREDPROFILEMAP));
            bcGrpPersistDTO.setExtBroadcasterFeatureMap(extProfileMaps.get(EXTBROADCASTERFEATUREMAP));
            //Get the internal Broadcasters in the group.
            List<String> intBroadcasters = new ArrayList<>(bcGrpPersistDTO.getGrpBroadcasters());
            intBroadcasters.removeAll(allExtMemberList);
            //Get the internal Broadcasters Broadcast Group server bit.
            Map<String, Boolean> interBrdstrFeatureBitMap = contactInfoUtil.getSubscrBCGrpBit(intBroadcasters, corpId, xdmsHome, persisterTxn);
            bcGrpPersistDTO.setInterBroadcasterBitMap(interBrdstrFeatureBitMap);
            bcGrpPersistDTO.setGroupDisplayName(grpBasicInfo.getGrpDisplayName());
            //Setting the max contact per request value
            bcGrpPersistDTO.setMaxContactsPerRequest(corpProfile.getMaxContactsPerRequest());

            //Setting DB etag
            bcGrpPersistDTO.setETag(groupPersistDTO.getETag());
            if (grpBasicInfo.getGroupCreatedBy() == CREATED_BY.DYNAMIC_CGMT_INTF.value()) {
                List<String> tpMdnList = new ArrayList<>();
                bcGrpPersistDTO.setExistingGroupModifyPermMap(existingGroupModifyPermMap);
                bcGrpPersistDTO.setTpGroupOwner(grpBasicInfo.getGrpOwner());
                bcGrpPersistDTO.setTpRequestMdn(groupInfoDTO.getTpRequestMdn());
                bcGrpPersistDTO.setGroupCreatedBy(grpBasicInfo.getGroupCreatedBy());
                bcGrpPersistDTO.setTpVendorID(groupInfoDTO.getTpVendorID());
                Map<String, KnCorpSubscriberDTO> tpDBSubMap = null;
                if (groupInfoDTO.getTpRequestMdn() != null) {
                    tpMdnList.add(groupInfoDTO.getTpRequestMdn());
                    tpDBSubMap = contactInfoUtil.getPoCSubscriberCorporateDetails(tpMdnList, xdmsHome, persisterTxn);
                    bcGrpPersistDTO.setTpRequestMDNMap(tpDBSubMap);
                }
                if (grpBasicInfo.getGrpOwner() != null) tpMdnList.add(grpBasicInfo.getGrpOwner());
                if (groupInfoDTO.getTpRequestMdn() == null && grpBasicInfo.getGrpOwner() == null) {
                    String mdnHavingGrpModifyPerm = null;
                    Collection<String> existingMdnList = existingGroupModifyPermMap.keySet();
                    Map<String, Integer> subsClientTypeMap = groupInfoUtil.getGroupMembersClientTypeMap(existingMdnList, corpId, xdmsHome, persisterTxn);
                    Optional<Entry<String, Integer>> filteredSubsMap = subsClientTypeMap.entrySet().stream().filter(isThirdPartClientMap()).findFirst();
                    if (filteredSubsMap.isPresent()) {
                        mdnHavingGrpModifyPerm = filteredSubsMap.get().getKey();
                    } else {
                        Optional<KnCorpSubscriberDTO> filteredSubsList = persistDto.getValidInternalCont().stream().filter(isThirdPartClient(groupInfoDTO.getCorpId())).findFirst();
                        if (filteredSubsList.isPresent()) {
                            mdnHavingGrpModifyPerm = filteredSubsList.get().getMdn();
                        }
                    }
                    bcGrpPersistDTO.setTpGroupOwner(mdnHavingGrpModifyPerm);
                    tpMdnList.add(mdnHavingGrpModifyPerm);
                }
                tpMdnList.addAll(allDistinceMembers);
                Map<String, Integer> subsClientTypeMap = groupInfoUtil.getGroupMembersClientType(tpMdnList, xdmsHome, persisterTxn);
                List<String> actualTpMdnList = subsClientTypeMap.entrySet().stream().filter(isThirdPartClientMap()).map(Entry::getKey).collect(Collectors.toList());
                Map<String, String> vendorMdnMap = commonInfoUtil.getVendorID(actualTpMdnList, xdmsHome, persisterTxn);
                knLogger.debug("vendorMdnMap--- ", KnGDPRTemplate.mdnMap(vendorMdnMap));
                KnTPVendorDetailsPersistDTO dbVendorDetails = commonInfoUtil.getVendorDetails(groupInfoDTO.getTpVendorID(), xdmsHome, persisterTxn);
                bcGrpPersistDTO.setVendorMdnMap(vendorMdnMap);
                bcGrpPersistDTO.setTpDbMDNList(actualTpMdnList);
                bcGrpPersistDTO.setTpVendorPersistDTO(dbVendorDetails);
            }
            //osm modify BC group osm exists
            Map<Integer, Integer> osmListIdAndDefaultMap = corpOSMInfoUtil
                    .getOSMListIdAndDefaultMap(String.valueOf(groupInfoDTO.getCorpId()), xdmsHome, persisterTxn);
            bcGrpPersistDTO.setOsmListIdAndDefultMap(osmListIdAndDefaultMap);
            knLogger.debug("osmListIdAndDefaultMap- : ", osmListIdAndDefaultMap);
            //osm modify BC group osmlistid
            if (groupInfoDTO.getOSMListId() != null) {
                if (!groupInfoDTO.getOSMListId().isEmpty()) {
                    bcGrpPersistDTO.setOSMListId(groupInfoDTO.getOSMListId());
                }
                //In case of modify BC group, only member count is sent in the notification.
            }
            //Now osmlistId is empty or with value no default osm check.
            /*else{
                if(osmListIdAndDefaultMap!=null&&!osmListIdAndDefaultMap.isEmpty()){
                    Optional<Integer> osmPresent =osmListIdAndDefaultMap.entrySet().stream()
                            .filter(entry -> entry.getValue().equals(ENABLED)).map(Map.Entry::getKey).findFirst();
                    if(osmPresent.isPresent()) {
                        knLogger.debug(methodName,"osmPresent.get().toString() :",osmPresent.get().toString());
                        bcGrpPersistDTO.setOSMListId(osmPresent.get().toString());
                        groupInfoDTO.setOSMListId(osmPresent.get().toString());
                    }
                }
            }*/


            List<KnCorpSubscriberDTO> pocSubslist = new ArrayList<>();
            List<String> addedSubsList = new ArrayList<>();
            groupInfoDTO.getAddedMemberDTOMdns().stream().forEach(x -> addedSubsList.add(x.getMdn()));
            knLogger.debug(methodName, "added mdn", KnGDPRTemplate.mdnList(groupInfoDTO.getAddedMdnsList()), groupInfoDTO.getAddedMemberDTOMdns());
            //osm modify BC group osm auth added member
            Map<String, KnCorpSubscriberDTO> corpSubscriberMap = new HashMap<>();
            Collection<KnCorpSubscriberDTO> pocSubscriberInfo = contactInfoUtil.getSubscribersInfo(allIntMemberList, xdmsHome, persisterTxn);
            knLogger.debug(methodName, "pocSubscriberInfo - ", pocSubscriberInfo);
            List<String> criClientList = new ArrayList<>();
            for(KnCorpSubscriberDTO pocSubsInfoDetails : pocSubscriberInfo) {
                corpSubscriberMap.put(pocSubsInfoDetails.getMdn(),pocSubsInfoDetails);
                if(pocSubsInfoDetails.getMcpttCompliance() == MCPTT_COMPLIANCE){
                    criClientList.add(pocSubsInfoDetails.getMdn());
                }
            }
            knLogger.debug(methodName, "criClientList -", KnGDPRTemplate.mdnList(criClientList));
            String maxGroupsPerCRIClient = paramNameValueMapCommon.get(MAX_GROUPS_PER_CRI_CLIENT);
            bcGrpPersistDTO.setCriClientList(criClientList);
            if(null != maxGroupsPerCRIClient){
                bcGrpPersistDTO.setMaxGroupsPerCRIClient(Integer.parseInt(maxGroupsPerCRIClient));
            }
            bcGrpPersistDTO.setParamNameValueMapCommon(paramNameValueMapCommon);
            bcGrpPersistDTO.setGrpShared(grpBasicInfo.getGrpShared());
            bcGrpPersistDTO.setCorpProfile(corpProfile);
            List<String> externalMdnList=new ArrayList<>();
            if (groupInfoDTO.getAddedMemberDTOMdns() != null
                    && !groupInfoDTO.getAddedMemberDTOMdns().isEmpty()) {
                Collection<KnCorpSubscriberDTO> pocSubsInfo = contactInfoUtil.getSubscribersInfo(addedSubsList, xdmsHome, persisterTxn);
                knLogger.debug(methodName, "added pocSubsInfo - ", pocSubsInfo, KnGDPRTemplate.mdnList(addedSubsList));
                pocSubslist.addAll(pocSubsInfo);
                bcGrpPersistDTO.setAddedMemberMdnsDTOLst(groupInfoDTO.getAddedMemberDTOMdns());
                for (KnCorpSubscriberDTO pocSubsInfoDetails : pocSubsInfo) {
                    corpSubscriberMap.put(pocSubsInfoDetails.getMdn(), pocSubsInfoDetails);
                    if(pocSubsInfoDetails.getCorpId()!=corpId){
                        externalMdnList.add(pocSubsInfoDetails.getMdn());
                    }
                    knLogger.debug(methodName, "pocSubsInfoDetails.getClientPVmajorVer() ", pocSubsInfoDetails.getClientType(), pocSubsInfoDetails.getClientPVmajorVer());
                }
            }
            knLogger.debug(methodName, "groupInfoDTO.getModifiedMembers() ", groupInfoDTO.getModifiedMembers());
            //osm modify BC group osm auth modified member
            Collection<String> modifyMemList = new ArrayList<>();
            if (groupInfoDTO.getModifiedMembers() != null && !groupInfoDTO.getModifiedMembers().isEmpty()) {
                Collection<String> modifiedMdnList = new ArrayList<>();
                for (KnCorpGroupMemberDTO mdnModified : groupInfoDTO.getModifiedMembers()) {
                    ((ArrayList<String>) modifiedMdnList).add(mdnModified.getMdn());
                }
                modifyMemList.addAll(modifiedMdnList);
                Collection<KnCorpSubscriberDTO> modifiedPocSubsInfo = contactInfoUtil.getSubscribersInfo(modifiedMdnList, xdmsHome, persisterTxn);
                knLogger.debug(methodName, "modified pocSubsInfo - ", modifiedPocSubsInfo, KnGDPRTemplate.mdnList(modifiedMdnList));
                pocSubslist.addAll(modifiedPocSubsInfo);
                bcGrpPersistDTO.setModifiedMembersList(groupInfoDTO.getModifiedMembers());
                for (KnCorpSubscriberDTO pocSubsInfoDetails : modifiedPocSubsInfo) {
                    corpSubscriberMap.put(pocSubsInfoDetails.getMdn(), pocSubsInfoDetails);
                    knLogger.debug(methodName, "pocSubsInfoDetails.getClientPVmajorVer() ", pocSubsInfoDetails.getClientType(), pocSubsInfoDetails.getClientPVmajorVer());
                }
            }
            bcGrpPersistDTO.setPocSubsInfo(pocSubslist);

            if(groupInfoDTO.getCorpSharedCorpInfoList() != null && !groupInfoDTO.getCorpSharedCorpInfoList().isEmpty()){
                List<KnCorpTrustMatrixDTO> trustMatrixDTOList = generalCacheUtil.getSharedCorpMatrix(corpProfile.getExtCorpId().trim());
                groupPersistDTO.setTrustMatrixDTOList(trustMatrixDTOList);
                groupPersistDTO.setCorpSharedCorpInfoList(groupInfoDTO.getCorpSharedCorpInfoList());
                bcGrpPersistDTO.setTrustMatrixDTOList(trustMatrixDTOList);
                bcGrpPersistDTO.setCorpSharedCorpInfoList(groupInfoDTO.getCorpSharedCorpInfoList());
            }

            // P7-2: Trust matrix validation for explicitly added sharing entries (owner corp only)
            if (groupInfoDTO.getAddedCorpSharedCorpInfoList() != null && !groupInfoDTO.getAddedCorpSharedCorpInfoList().isEmpty()
                    && groupInfoDTO.isOwnerCorpReq()) {
                List<KnCorpTrustMatrixDTO> trustMatrixDTOList = generalCacheUtil.getSharedCorpMatrix(corpProfile.getExtCorpId().trim());
                enrichTrustMatrixWithHierarchyMappings(trustMatrixDTOList);
                groupPersistDTO.setTrustMatrixDTOList(trustMatrixDTOList);
                groupPersistDTO.setCorpSharedCorpInfoList(groupInfoDTO.getAddedCorpSharedCorpInfoList());
                bcGrpPersistDTO.setTrustMatrixDTOList(trustMatrixDTOList);
                bcGrpPersistDTO.setCorpSharedCorpInfoList(groupInfoDTO.getAddedCorpSharedCorpInfoList());
                injectSourceHierarchyId(groupInfoDTO.getAddedCorpSharedCorpInfoList(), groupInfoDTO.getHierarchyId());
            }

            bcGrpPersistDTO.setParamNameValueMapCommon(paramNameValueMapCommon);
            bcGrpPersistDTO.setGrpShared(grpBasicInfo.getGrpShared());
            bcGrpPersistDTO.setCorpProfile(corpProfile);

            boolean sharedGroupRequest = grpBasicInfo.getGroupCorpId() != corpId;
            boolean isUgwInteropSharedCorpChange = sharedGroupRequest && isUgwInterop;
            groupPersistDTO.setUgwInteropSharedCorpChange(isUgwInteropSharedCorpChange);

            //performs business validation
            bcGrpPersistDTO.setLargeGroupSupported(corpProfile.getLargeGrpSupported());
            bcGrpPersistDTO.setMaxMemPerLargeBCGroup(corpProfile.getMaxMemPerLrgBGrp());
            bcGrpPersistDTO.setGroupProfileId(grpBasicInfo.getGroupProfileId());
            bcGrpPersistDTO.setOverrideDnd(groupInfoDTO.getOverrideDnd());

            Collection<KnRecordingTargetInfoDTO> recordingInfoList = null;
            Collection<String> disabledTarget = null;
            KnRecordingTargetInfoDTO recordInfo = new KnRecordingTargetInfoDTO();
            String recordingTarget = corpId + "_" + grpId;
            String recordFsValue = groupInfoDTO.getRecordingFs();

            if (null != recordFsValue) {
                recordingInfoList = new ArrayList<>();
                disabledTarget = new ArrayList<>();

                String priRecordingServerIP = paramNameValueMapCommon.get(MSI_PRIMARY_WAVE_RECORDING_SERVER_IP);
                String priRecordingServerPort = paramNameValueMapCommon.get(MSI_PRIMARY_WAVE_RECORDING_SERVER_PORT);
                String geoRecordingServerIP = paramNameValueMapCommon.get(MSI_GEO_WAVE_RECORDING_SERVER_IP);
                String geoRecordingServerPort = paramNameValueMapCommon.get(MSI_GEO_WAVE_RECORDING_SERVER_PORT);

                recordInfo.setPriRecIp(priRecordingServerIP);
                recordInfo.setPriRecPort(null != priRecordingServerPort ? Integer.parseInt(priRecordingServerPort) : null);
                recordInfo.setSecRecIp(geoRecordingServerIP);
                recordInfo.setSecRecPort(null != geoRecordingServerPort ? Integer.parseInt(geoRecordingServerPort) : null);
                recordInfo.setTarget(recordingTarget);

                String pttRecordingVal = paramNameValueMapCommon.get(PTT_RECORDING_FLAG);
                String dataRecordingVal = paramNameValueMapCommon.get(DATA_RECORDING_FLAG);
                String videoRecordingVal = paramNameValueMapCommon.get(VIDEO_RECORDING_FLAG);
                boolean pttRecordingFlag = ENABLED == Integer.parseInt(pttRecordingVal);
                boolean dataRecordingFlag = ENABLED == Integer.parseInt(dataRecordingVal);
                boolean videoRecordingFlag = ENABLED == Integer.parseInt(videoRecordingVal);
                knLogger.debug(methodName, "RecordingFs is ", recordFsValue);
                String recordingFsBitSetValue = KnGeneralUtil.getBitFromDecimalRecord(recordFsValue);
                knLogger.debug(methodName, "recordingFsBitSetValue is ", recordingFsBitSetValue);
                bcGrpPersistDTO.setRecordingFs(recordingFsBitSetValue);
                bcGrpPersistDTO.setPttRecordingFlag(pttRecordingFlag);
                bcGrpPersistDTO.setDataRecordingFlag(dataRecordingFlag);
                bcGrpPersistDTO.setVideoRecordingFlag(videoRecordingFlag);

                Integer recType = null;
                if (recordFsValue.equals(GROUP_RECORDING_MCPTT_MCVIDEO)
                        || recordFsValue.equals(GROUP_RECORDING_MCPTT_MCDATA_MCVIDEO)) {
                    recType = REC_TYPE.BOTH.value();
                }
                if (recordFsValue.equals(GROUP_RECORDING_MCVIDEO)
                        || recordFsValue.equals(GROUP_RECORDING_MCPDATA_MCVIDEO)) {
                    recType = REC_TYPE.VIDEO.value();
                }
                if (recordFsValue.equals(GROUP_RECORDING_MCPTT)
                        || recordFsValue.equals(GROUP_RECORDING_MCPTT_MCDATA)) {
                    recType = REC_TYPE.AUDIO.value();
                }
                if (recType != null) {
                    recordInfo.setRecType(recType);
                    recordingInfoList.add(recordInfo);
                }
                if (recordFsValue.equals(GROUP_RECORDING_DISABLED)
                        || recordFsValue.equals(GROUP_RECORDING_MCDATA)) {
                    disabledTarget.add(recordingTarget);
                }
            }

            //boolean isUgwInterop = (null != groupInfoDTO.getUgwInterop() && groupInfoDTO.getUgwInterop().equals(7));
            if(isUgwInterop){
                bcGrpPersistDTO.setUgwInterop(groupInfoDTO.getUgwInterop());
                groupPersistDTO.setUgwInterop(groupInfoDTO.getUgwInterop());
                String ugwInteropFlag = paramNameValueMapCommon.get(UGWINTEROP);
                knLogger.debug(methodName, "Retrieved ugwInterop flag from system config - ", ugwInteropFlag);
                bcGrpPersistDTO.setUgwInteropSystemConfig(ugwInteropFlag);
            }

            Map<Integer, KnCorpTrustMatrixDTO> trustMatrixMap = corpUserProfileUtil.getTrustMatrixMap(corpProfile.getExtCorpId(),
                    generalCacheUtil, commonInfoUtil, xdmsHome, persisterTxn);
            bcGrpPersistDTO.setTrustMatrixMap(trustMatrixMap);

            if(groupInfoDTO.getGrpShared() != null){
                bcGrpPersistDTO.setGrpSharedModified(!groupInfoDTO.getGrpShared().equals(grpBasicInfo.getGrpShared()));
            }

            bcGrpPersistDTO.setOverrideDnd(grpBasicInfo.getOverrideDnd());
            bcGrpPersistDTO.setGroupType(grpBasicInfo.getGrpType());
            if(persistDto.getValidExtContacts()!= null && bcGrpPersistDTO.getAddedMemberMdnsDTOLst() != null){
                for(KnCorpSubscriberDTO externalDTO : persistDto.getValidExtContacts())
                {
                    for(KnCorpContactDTO addedMDNs : bcGrpPersistDTO.getAddedMemberMdnsDTOLst()){
                        if(Objects.equals(externalDTO.getMdn(), addedMDNs.getMdn()))
                            addedMDNs.setExternalContact(Boolean.TRUE);
                    }
                }}
            // UCSPROVCONFIG-8560 fix: mark existing members as external using UNION of DB + request
            // shared corp list. Covers un-share (DB has values), re-share (request has values),
            // and modify-shared (both may have values).
            Set<Integer> bcMarkingCorpIds = new HashSet<>();
            if ((groupInfoDTO.getGrpShared() != null && groupInfoDTO.getGrpShared() == GROUP_SHARING_ENABLE_INDICATOR) ||
                    (grpBasicInfo.getGrpShared() != null && grpBasicInfo.getGrpShared() == GROUP_SHARING_ENABLE_INDICATOR)) {
                List<KnCorpSharedCorpInfo> bcSharedCorpInfoList = groupInfoUtil.selectGroupSharedCorpInfo(corpId, grpId, xdmsHome, persisterTxn);
                if (bcSharedCorpInfoList != null && !bcSharedCorpInfoList.isEmpty()) {
                    bcMarkingCorpIds.addAll(bcSharedCorpInfoList.stream().map(KnCorpSharedCorpInfo::getCorpId).collect(Collectors.toSet()));
                }
            }
            if (groupInfoDTO.getCorpSharedCorpInfoList() != null) {
                groupInfoDTO.getCorpSharedCorpInfoList().forEach(item -> bcMarkingCorpIds.add(item.getCorpId()));
            }
            knLogger.debug(methodName, "bcMarkingCorpIds (DB+Request union) -", bcMarkingCorpIds, ", ownerCorpId -", grpBasicInfo.getCorpId());
            if (!bcMarkingCorpIds.isEmpty()) {
                for (KnCorpGroupMemberDTO member : bcGrpPersistDTO.getExistingGrpMemDetail()) {
                    if (member.getCorpId() != 0 && (!bcMarkingCorpIds.contains(member.getCorpId())) && (member.getCorpId() != grpBasicInfo.getCorpId())) {
                        member.setExternalContact(Boolean.TRUE);
                    }
                }
            }

            bcGrpPersistDTO.setIsPreConfiguredGroup(groupInfoDTO.getIsPreConfiguredGroup());
            bcGrpPersistDTO.setDbIsPreConfiguredGroup(grpBasicInfo.getIsPreConfiguredGroup());
            //Logic to validate the members which are not part of shared corp or external subs info
            if(!pocSubslist.isEmpty()){
                List<KnCorpSubscriberDTO> extMdns = pocSubslist.stream().filter(subs -> !(subs.getCorpId() == corpId)).collect(Collectors.toList());
                if(!extMdns.isEmpty()){
                    bcGrpPersistDTO.setAddedExternalMembers(extMdns);
                    ICorpXdmDAO corpXdmDao = new KnCorpXdmDAO(xdmsHome);
                    Collection<KnCorpSubscriberDTO> externalGrpMemberDetails = corpXdmDao.getExternalPoCSubscriberInfo(
                            extMdns.stream().map(KnCorpSubscriberDTO::getMdn).collect(Collectors.toList()),
                            corpId, persisterTxn);
                    List<String> externalMdnsPresentInDB = externalGrpMemberDetails.stream().map(KnCorpSubscriberDTO::getMdn).collect(Collectors.toList());
                    bcGrpPersistDTO.setMdnsPresentInExternalInfo(externalMdnsPresentInDB);
                }
            }
            //Validating the max large group counts
            KnLargeGrpCountDTO getAllLargeGroupSystem = groupInfoUtil.getLargeGroupCounts(corpId, persisterTxn, xdmsHome);
            //Get the distinct removed sublist members
            List<KnCorpSubscriberDTO> distinctRemovedSublistMems = sublistInfoUtil.getSublistDistinctMembers(removedSublistIds, corpId, xdmsHome, persisterTxn);
            knLogger.debug(methodName, "distinctRemovedSublistMems - ", distinctRemovedSublistMems);

            //Get the final member List to be romeved from removed sublist ids and removed member list.
            LinkedList<String> removedMembersList = new LinkedList<>();
            for (KnCorpSubscriberDTO subscriberDTO : distinctRemovedSublistMems) {
                removedMembersList.add(subscriberDTO.getMdn());
            }
            for (String mdn : removedMemberList) {
                if (!removedMembersList.contains(mdn)) {
                    removedMembersList.add(mdn);
                }
            }

            Collection<Integer> groupList = new ArrayList<>();
            groupList.add(grpId);
            int memberCount = 0;
            Map<Integer, Integer> groupMemberCount = groupInfoUtil.getGroupMemCount(groupList, xdmsHome, persisterTxn);
            if (!groupMemberCount.isEmpty()) {
                memberCount = groupMemberCount.get(grpId);
            }
            int totalMemberCount = (memberCount + allDistinceMembers.size()-removedMembersList.size());
            knLogger.debug(methodName, " allDistinceMembers:", allDistinceMembers
                    , " corpProfile.getMaxMemPerBCGrp() :", corpProfile.getMaxMemPerBCGrp()
                    ," totalMemberCount :",totalMemberCount," memberCount:",memberCount," removedMembersList:",removedMembersList);
            boolean isLargeGroup = Boolean.FALSE;
            if (!grpBasicInfo.isLargeGroup()&&totalMemberCount > corpProfile.getMaxMemPerBCGrp()) {
                isLargeGroup = Boolean.TRUE;
            }
            bcGrpPersistDTO.setLargeGroup(isLargeGroup);
            bcGrpPersistDTO.setLargeBCGrpCountInCorp(getAllLargeGroupSystem.getLargeBCGrpCountCorp());
            bcGrpPersistDTO.setMaxLargeBCGrpCorp(corpProfile.getMaxLrgBGrpPerCorp());

            bcGrpPersistDTO.setLargeGrpCountInSystem(getAllLargeGroupSystem.getLrgGrpCountSystem());
            bcGrpPersistDTO.setMaxLargeGrpSystem(Integer.parseInt(genInfoUtil.retrieveRTXConfigValues(persisterTxn).get(NUM_OF_LG_SUPPORTED)));
            bcGrpPersistDTO.setMaxGroupsPerLargeDispatchMemberCount(corpProfile.getMaxGroupsPerLargeDispatch());
            bcGrpPersistDTO.setIsSysLargeAgencyDispatchEnabled(sysLargeAgencyDispatch);
            bcGrpPersistDTO.setIsCorpLargeAgencyDispatchEnabled(corpLargeAgencyDispatch);
            bcGrpPersistDTO.setSubsGroupCount(subsGroupCount);

            boolean isGrpSharingEnabled = groupInfoDTO.getGrpShared() != null && groupInfoDTO.getGrpShared() == GROUP_SHARING_ENABLE_INDICATOR;
            knLogger.info(methodName, "isGrpSharingEnabled :", isGrpSharingEnabled, " isLargeGroup:", isLargeGroup);
            if (isGrpSharingEnabled && isLargeGroup) {
                Set<Integer> allInternalCorpIds = getAllInternalCorpIdsForSharedGroup(groupInfoDTO.getGroupId(),
                        corpProfile.getCorpId(), xdmsHome, persisterTxn);
                knLogger.info(methodName, " allInternalCorpIds :", allInternalCorpIds, " corpProfile.getCorpId()", corpProfile.getCorpId());
                Map<Integer, Integer> CorpIdAndLargeGroupFlagMap = commonInfoUtil.getCorpIdAndLargeGroupFlagMap(allInternalCorpIds, persisterTxn);
                knLogger.info(methodName, " CorpIdAndLargeGroupFlagMap :", CorpIdAndLargeGroupFlagMap);
                groupPersistDTO.setCorpIdAndLargeGroupFlagMap(CorpIdAndLargeGroupFlagMap);
            }

            // Fetch broadcast group count per subscriber
            if (addedMemberMdns != null && !addedMemberMdns.isEmpty()) {
                Map<String, Integer> subsBroadcastGroupCount = groupInfoUtil.getSubscriberBroadcastGroupCount(addedMemberMdns.stream().toList(), xdmsHome, persisterTxn);
                bcGrpPersistDTO.setSubscriberBroadcastGroupCount(subsBroadcastGroupCount);
                int maxBroadcastGroupCountPerSubscriber = MAX_BROADCAST_GROUP_PER_SUBSCRIBER;
                if (paramNameValueMapCommon.get(MAX_BCG_PER_DISP) != null) {
                    maxBroadcastGroupCountPerSubscriber = Integer.parseInt(paramNameValueMapCommon.get(MAX_BCG_PER_DISP));
                }
                bcGrpPersistDTO.setMaxBroadcastGroupCountPerSubscriber(maxBroadcastGroupCountPerSubscriber);
            }

            if (groupInfoDTO.getCustomParamMap() != null) {
                Object idTypeObj = groupInfoDTO.getCustomParamMap().get(IDTYPE);
                if (idTypeObj != null && Integer.parseInt(String.valueOf(idTypeObj)) == Integer.parseInt(HIER_CTX_ID_TYPE)) {
                    ICorpXdmDAO corpXdmDao = new KnCorpXdmDAO(xdmsHome);
                    Map<String, KnCorpSubscriberDTO> extSubscribersMap = corpXdmDao.getCorpExternalSubscriber(corpProfile.getCorpId(), persisterTxn);
                    if(extSubscribersMap != null && !extSubscribersMap.isEmpty()) {
                        bcGrpPersistDTO.setCorpContactExternalMdns(new ArrayList<>(extSubscribersMap.keySet()));
                    }
                }
            }

            List<int[]> groupSharingMap = groupInfoUtil.getSharedGroupHierarchyMappings(groupInfoDTO.getGroupId(), xdmsHome, persisterTxn);
            bcGrpPersistDTO.setHierarchyId(loggedInHierarchyId);
            bcGrpPersistDTO.setGroupSharingMap(groupSharingMap);
            bcGrpPersistDTO.setGroupId(grpId);
            knLogger.debug(methodName, "Invoking ValidationFW. DTO - ", bcGrpPersistDTO);
            validatorFW.validate(bcGrpPersistDTO);
            knLogger.debug(methodName, "Validation completed Successfully.");

            if (isHierarchyFlow) {
                List<String> addedOwnerIdList = groupInfoDTO.getAddedOwnerIdList();
                List<String> removedOwnerIdList = groupInfoDTO.getRemovedOwnerIdList();
                if (null != addedOwnerIdList && !addedOwnerIdList.isEmpty()) {
                    groupInfoUtil.insertGroupHiearchyMap(grpId, addedOwnerIdList, idType, xdmsHome, persisterTxn);
                }
                if (null != removedOwnerIdList && !removedOwnerIdList.isEmpty()) {
                    groupInfoUtil.removeGroupHiearchyMapByOwnerIds(grpId, removedOwnerIdList, idType, xdmsHome, persisterTxn);
                }
            }

            // When grpShared is disabled via idType=3 flow, clean up GROUP_HIERARCHY_MAP (idType=4) and CORPGRP_SHAREDLIST

            Set<String> allRemovedHierIds = new LinkedHashSet<>();
            if (null != customParams) {
                String idTypeStrCleanup = (String) customParams.get(IDTYPE);
                int idTypeIntCleanup = (idTypeStrCleanup != null && !idTypeStrCleanup.isEmpty()) ? Integer.parseInt(idTypeStrCleanup) : 0;
                if (Integer.parseInt(HIER_CTX_ID_TYPE) == idTypeIntCleanup
                        && groupInfoDTO.getGrpShared() != null && groupInfoDTO.getGrpShared() == 0
                        && grpBasicInfo.getGrpShared() != null && grpBasicInfo.getGrpShared() == 1) {
                    List<int[]> existingHierMappings = groupInfoUtil.getSharedGroupHierarchyMappings(groupInfoDTO.getGroupId(), xdmsHome, persisterTxn);
                    if (!existingHierMappings.isEmpty()) {
                        List<String> hierIdsToRemove = new ArrayList<>();
                        for (int[] row : existingHierMappings) {
                            hierIdsToRemove.add(String.format("%08d", row[0]));
                        }
                        Set<String> hierIdsToRemoveSet = new HashSet<>(hierIdsToRemove);
                        List<KnCorpGroupMemberDTO> existingMembersList = bcGrpPersistDTO.getExistingGrpMemDetail();
                        if (existingMembersList != null) {
                            for (KnCorpGroupMemberDTO member : existingMembersList) {
                                String memberHierarchyId = member.getHierarchyId();
                                if (memberHierarchyId != null && hierIdsToRemoveSet.contains(memberHierarchyId.trim())) {
                                    knLogger.error(methodName, "[Hierarchy] Cannot disable grpShared: shared member exists for hierarchyId=", memberHierarchyId.trim());
                                    throw new KnCorpBOException(KnErrorCodes.Validator.GROUP_SHARED_FLAG_MODIFY_NOT_ALLOWED,
                                            "Shared member exist cannot unshare");
                                }
                            }
                        }
                        knLogger.debug(methodName, "[Hierarchy] grpShared disabled: removing GROUP_HIERARCHY_MAP entries for groupId=", groupInfoDTO.getGroupId(), " count=", hierIdsToRemove.size());
                        groupInfoUtil.removeGroupHiearchyMapByOwnerIds(groupInfoDTO.getGroupId(), hierIdsToRemove, "4", xdmsHome, persisterTxn);
                        allRemovedHierIds.addAll(hierIdsToRemove);
                    }
                    List<Integer> groupsToClean = new ArrayList<>(1);
                    groupsToClean.add(groupInfoDTO.getGroupId());
                    knLogger.debug(methodName, "[Hierarchy] grpShared disabled: removing CORPGRP_SHAREDLIST for groupId=", groupInfoDTO.getGroupId());
                    groupInfoUtil.deleteSharedGroups(groupsToClean, xdmsHome, persisterTxn);
                }
            }

            if (isUgwInterop) {
                boolean isGroupProfileNotifyRequired = commonInfoUtil.isGroupProfileNotifyRequired(corpId, persisterTxn);
                if (isGroupProfileNotifyRequired) {
                    //Update the UGWINTEROP
                    commonInfoUtil.updateLmrInterOpInDB(corpId, ENABLED, persisterTxn);
                    respDto.setIntCorpId(intCorpId);
                    respDto.setExtCorpId(extCorpId);
                    respDto.setNetworkName(networkName);
                    respDto.setCorpNotification(true);
                }
            }

            //Final sublist Ids to be added into group.
            List<Integer> sublistToBeAdded = new ArrayList<>(addedSublistIds);
            sublistToBeAdded.removeAll(existSublist);
            groupInfoDTO.setAddedSublistIds(sublistToBeAdded);
            //Populating the private list members tobe added into group private list.
            Collection<KnCorpGroupMemberDTO> groupMembers = new ArrayList<>();
            for (KnCorpSubscriberDTO subsc : persistDto.getValidExtContacts()) {
                if (privtLstMemToBeAdded.contains(subsc)) {
                    KnCorpGroupMemberDTO grpMem = new KnCorpGroupMemberDTO();
                    grpMem.setMdn(subsc.getMdn());
                    grpMem.setCorpId(subsc.getCorpId());
                    groupMembers.add(grpMem);
                }
            }
            for (KnCorpSubscriberDTO subsc : persistDto.getValidInternalCont()) {
                if (privtLstMemToBeAdded.contains(subsc)) {
                    KnCorpGroupMemberDTO grpMem = new KnCorpGroupMemberDTO();
                    grpMem.setMdn(subsc.getMdn());
                    grpMem.setCorpId(subsc.getCorpId());
                    groupMembers.add(grpMem);
                }
            }
            //resetting the added members into input DTO.
            groupInfoDTO.setGroupMembers(groupMembers);


                /*Group is already having SG/SGPatch MDN 	: Means; LMR_INTEROP_CAPABLE in DG.CORPGROUPINFO is 1;
                Group do not have any SG/SGPatch MDN	    : Means; LMR_INTEROP_CAPABLE in DG.CORPGROUPINFO is 0;

                curreGrpMdns		: Means what is going to be happen after (Existing SG/SGPatch - Requested Removed SG/SGPatch)
                adedSGMDN	        : Means what is going to happend after (Requested added SG/SGPatch)

                below are the chart, when to update LMR_INTEROP_CAPABLE column as of modifyGroup Call:

                DB	| curreGrpMdns	| adedSGMDN
                1	| Empty		    |	NA			: Update will take place		: If Loop
                1	| Empty		    |	Present		: Update will not take place	: If Loop : Exception Case
                0	| NA 		    |	Present		: Update will take place		: Else If Loop
                0	| NA 		    |	Empty		: Update will not take place	: Else If Loop

                DB	| Current
                1	| 0			: Update will take place
                1	| 1			: Update will not take place
                0	| 1 		: Update will take place
                0	| 0 		: Update will not take place*/


            knLogger.debug("curreGrpMdns.isEmpty() & addedSGMdn ", curreGrpMdns.isEmpty(), addedSGMdn);
            if (grpBasicInfo.getLmrInteropCapable() == LMR_INTEROP_CAPABLE && curreGrpMdns.isEmpty()) {
                groupInfoDTO.setLmrInteropCapable(LMR_INTEROP_NON_CAPABLE);
                groupInfoDTO.setLmrInteropFeatureChanged(true);
            } else if (grpBasicInfo.getLmrInteropCapable() == LMR_INTEROP_NON_CAPABLE && addedSGMdn) {
                groupInfoDTO.setLmrInteropCapable(LMR_INTEROP_CAPABLE);
                groupInfoDTO.setLmrInteropFeatureChanged(true);
            }

            //Exception Case:
            if (grpBasicInfo.getLmrInteropCapable() == LMR_INTEROP_CAPABLE && curreGrpMdns.isEmpty() && addedSGMdn) {
                groupInfoDTO.setLmrInteropFeatureChanged(false);
            }

            //Exception Case: 2 for Backward campatability: Group exists with 3 sg mdn and only one sg got deleted then interopCapable = 1
            if (grpBasicInfo.getLmrInteropCapable() == LMR_INTEROP_NON_CAPABLE && !curreGrpMdns.isEmpty()) {
                groupInfoDTO.setLmrInteropCapable(LMR_INTEROP_CAPABLE);
                groupInfoDTO.setLmrInteropFeatureChanged(true);
            }

            //lmrInteropFlag parameter is set as part of XDM-5959
            if (null != groupInfoDTO.getUgwInterop()) {
                groupPersistDTO.setUgwInterop(groupInfoDTO.getUgwInterop());
            } else if (null == groupInfoDTO.getUgwInterop() && addedSGMdn || !curreGrpMdns.isEmpty()) {
                groupInfoDTO.setUgwInterop(UGWINTEROP_DBVALUE);
                groupPersistDTO.setUgwInterop(UGWINTEROP_DBVALUE);
            } else if (null == groupInfoDTO.getUgwInterop() && null != grpBasicInfo.getUgwInterop()) {
                //Empty group with ugwInteropEnabled or ugwInteropDisabled can exist
                groupInfoDTO.setUgwInterop(grpBasicInfo.getUgwInterop());
                groupPersistDTO.setUgwInterop(grpBasicInfo.getUgwInterop());
            } else if (null == groupInfoDTO.getUgwInterop()) {
                groupInfoDTO.setUgwInterop(UGWINTEROP_DBVALUE_DISABLED);
                groupPersistDTO.setUgwInterop(UGWINTEROP_DBVALUE_DISABLED);
            }

            //Call to update the private contact list members and group_listfer tables
            groupInfoUtil.modifyGroupDetails(groupInfoDTO, xdmsHome, persisterTxn);
            //Call to delte the distribution list
            knLogger.info(methodName, "actualDeletedBrdstr - ", KnGDPRTemplate.mdnList(actualDeletedBrdstr));
            List<Integer> groupIdLst = new ArrayList<>(1);
            List<String> addedBroadcasters = bcGrpPersistDTO.getGrpBroadcasters();
            groupIdLst.add(grpId);
            Map<Integer, Integer> groupEtagMap = groupInfoUtil.updateGroupListEtag(groupIdLst, xdmsHome, persisterTxn);
            Map<Integer, Collection<String>> addedBroadMap = new HashMap<>(1);
            addedBroadMap.put(grpId, addedBroadcasters);
            //Get the Added Broadcasters - distribution list
            //List<String> addedBroadcasters = bcGrpPersistDTO.getGrpBroadcasters();
            addedBroadcasters.removeAll(existingBroadcasters);
            knLogger.debug(methodName, "addedBroadcasters - ", KnGDPRTemplate.mdnList(addedBroadcasters));
            if (!addedBroadcasters.isEmpty()) {
                groupInfoUtil.addToCorpGroupDistInfo(addedBroadcasters, grpId, xdmsHome, persisterTxn);
            }

            if(groupInfoDTO.getCorpSharedCorpInfoList() != null){
                List<Integer> groups = new ArrayList<>(1);
                groups.add(groupInfoDTO.getGroupId());
                groupInfoUtil.deleteSharedGroups(groups, xdmsHome, persisterTxn);
                if(!groupInfoDTO.getCorpSharedCorpInfoList().isEmpty()){
                    List<KnCorpGroupInfoPersistDTO> groupInfoPersistDTOList= new ArrayList<>();
                    groupPersistDTO.setCorpId(corpId);
                    groupPersistDTO.setGroupId(groupInfoDTO.getGroupId());
                    groupInfoPersistDTOList.add(groupPersistDTO);
                    groupInfoUtil.createGroupSharedCorpInfo(groupInfoPersistDTOList,xdmsHome,persisterTxn);
                }
            }

            // P7-2: Handle explicit addedCorpSharedCorpInfoList / removedCorpSharedCorpInfoList (modifyBCGroup, owner corp only)
            if (groupInfoDTO.isOwnerCorpReq()) {
                List<KnCorpSharedCorpInfo> addedSharedList = groupInfoDTO.getAddedCorpSharedCorpInfoList();
                List<KnCorpSharedCorpInfo> removedSharedList = groupInfoDTO.getRemovedCorpSharedCorpInfoList();

                if (removedSharedList != null && !removedSharedList.isEmpty()) {
                    // Split removedSharedList into two groups:
                    // - partialRemovals: entries with a specific hierarchyList → remove only those hierarchies, keep corp sharing
                    // - fullRemovals: entries without a hierarchyList → remove entire corp sharing + all its hierarchies
                    List<KnCorpSharedCorpInfo> partialRemovals = new ArrayList<>();
                    List<KnCorpSharedCorpInfo> fullRemovals = new ArrayList<>();
                    for (KnCorpSharedCorpInfo info : removedSharedList) {
                        if (info.getHierarchyList() != null && !info.getHierarchyList().isEmpty()) {
                            partialRemovals.add(info);
                        } else {
                            fullRemovals.add(info);
                        }
                    }

                    // Handle partial removals: remove only the specified hierarchy IDs,
                    // then clean up CORPGRP_SHAREDLIST for any corp that now has no remaining hierarchies.
                    if (!partialRemovals.isEmpty()) {
                        try {
                            // Track corpId -> hierarchy IDs being removed
                            Map<Integer, List<String>> corpToRemovedHierIds = new LinkedHashMap<>();
                            List<String> hierIdsToRemove = new ArrayList<>();
                            for (KnCorpSharedCorpInfo info : partialRemovals) {
                                if (info.getCorpId() == null) continue;
                                List<String> idsForCorp = new ArrayList<>();
                                for (KnXDMHierarchyInfo hierInfo : info.getHierarchyList()) {
                                    String sharedHierarchyId = hierInfo.getSharedHierarchyId();
                                    if (sharedHierarchyId != null && !sharedHierarchyId.isEmpty()) {
                                        hierIdsToRemove.add(sharedHierarchyId);
                                        idsForCorp.add(sharedHierarchyId);
                                    }
                                }
                                if (!idsForCorp.isEmpty()) {
                                    corpToRemovedHierIds.put(info.getCorpId(), idsForCorp);
                                }
                            }
                            if (!hierIdsToRemove.isEmpty()) {
                                Set<String> hierIdsToRemoveSet = new HashSet<>(hierIdsToRemove);
                                List<KnCorpGroupMemberDTO> existingMembersP72 = bcGrpPersistDTO.getExistingGrpMemDetail();
                                if (existingMembersP72 != null) {
                                    for (KnCorpGroupMemberDTO member : existingMembersP72) {
                                        String memberHierarchyId = member.getHierarchyId();
                                        if (memberHierarchyId != null && hierIdsToRemoveSet.contains(memberHierarchyId.trim())) {
                                            knLogger.error(methodName, "[Hierarchy] P7-2: Cannot remove shared hierarchy: member exists with hierarchyId=", memberHierarchyId.trim());
                                            throw new KnCorpBOException(KnErrorCodes.Validator.GROUP_SHARED_FLAG_MODIFY_NOT_ALLOWED,
                                                    "Shared member exist cannot unshare");
                                        }
                                    }
                                }
                                knLogger.debug(methodName, "P7-2: Removing specific hierarchy map entries for groupId=", groupInfoDTO.getGroupId(), " count=", hierIdsToRemove.size());
                                groupInfoUtil.removeGroupHiearchyMapByOwnerIds(groupInfoDTO.getGroupId(), hierIdsToRemove, "4", xdmsHome, persisterTxn);
                                allRemovedHierIds.addAll(hierIdsToRemove);
                            }
                            // After removal, check if any corp now has no remaining hierarchy entries;
                            // if so, also remove it from CORPGRP_SHAREDLIST to avoid orphaned rows.
                            if (!corpToRemovedHierIds.isEmpty()) {
                                List<int[]> remainingMappings = groupInfoUtil.getSharedGroupHierarchyMappings(groupInfoDTO.getGroupId(), xdmsHome, persisterTxn);
                                Set<Integer> corpsWithRemainingHier = new HashSet<>();
                                for (int[] row : remainingMappings) {
                                    corpsWithRemainingHier.add(row[1]);
                                }
                                Set<Integer> corpsNowEmpty = new HashSet<>();
                                for (Integer sharedCorpId : corpToRemovedHierIds.keySet()) {
                                    if (!corpsWithRemainingHier.contains(sharedCorpId)) {
                                        corpsNowEmpty.add(sharedCorpId);
                                    }
                                }
                                if (!corpsNowEmpty.isEmpty()) {
                                    knLogger.debug(methodName, "P7-2: Removing CORPGRP_SHAREDLIST entries for corps with no remaining hierarchies, corpIds=", corpsNowEmpty);
                                    List<KnCorpSharedCorpInfo> existingShared = groupInfoUtil.selectGroupSharedCorpInfo(corpId, groupInfoDTO.getGroupId(), xdmsHome, persisterTxn);
                                    List<Integer> groupsToDelete = new ArrayList<>(1);
                                    groupsToDelete.add(groupInfoDTO.getGroupId());
                                    groupInfoUtil.deleteSharedGroups(groupsToDelete, xdmsHome, persisterTxn);
                                    List<KnCorpGroupInfoPersistDTO> reinsertList = new ArrayList<>();
                                    for (KnCorpSharedCorpInfo existing : existingShared) {
                                        if (!corpsNowEmpty.contains(existing.getCorpId()) && !Objects.equals(existing.getCorpId(), corpId)) {
                                            KnCorpGroupInfoPersistDTO dto = new KnCorpGroupInfoPersistDTO();
                                            dto.setCorpId(corpId);
                                            dto.setGroupId(groupInfoDTO.getGroupId());
                                            List<KnCorpSharedCorpInfo> singleList = new ArrayList<>(1);
                                            singleList.add(existing);
                                            dto.setCorpSharedCorpInfoList(singleList);
                                            reinsertList.add(dto);
                                        }
                                    }
                                    if (!reinsertList.isEmpty()) {
                                        groupInfoUtil.createGroupSharedCorpInfo(reinsertList, xdmsHome, persisterTxn);
                                    }
                                }
                            }
                        } catch (KnCorpBOException e) {
                            throw e;
                        } catch (Exception e) {
                            knLogger.warn(methodName, "P7-2: Error removing partial hierarchy entries - ", e.getMessage());
                        }
                    }

                    // Handle full corp removals: remove all hierarchy entries for the corp and drop from CORPGRP_SHAREDLIST
                    if (!fullRemovals.isEmpty()) {
                        Set<Integer> removedCorpIds = new HashSet<>();
                        for (KnCorpSharedCorpInfo info : fullRemovals) {
                            if (info.getCorpId() != null) removedCorpIds.add(info.getCorpId());
                        }
                        // TC-GRP-MOD-008: block removal if corp still has members in group
                        for (KnCorpGroupMemberDTO member : bcGrpPersistDTO.getExistingGrpMemDetail()) {
                            if (member.getCorpId() != 0 && removedCorpIds.contains(member.getCorpId())) {
                                knLogger.error(methodName, "TC-GRP-MOD-008: Cannot remove sharing for corp with existing members. corpId=", member.getCorpId());
                                throw new KnCorpBOException(KnErrorCodes.Validator.GROUP_SHARED_FLAG_MODIFY_NOT_ALLOWED,
                                        "Cannot remove group sharing while members from the affected corp are still in the group");
                            }
                        }
                        // Remove all hierarchy map entries for the fully-removed corps (P6-4)
                        try {
                            List<int[]> existingHierMappings = groupInfoUtil.getSharedGroupHierarchyMappings(groupInfoDTO.getGroupId(), xdmsHome, persisterTxn);
                            List<String> hierIdsToRemove = new ArrayList<>();
                            for (int[] row : existingHierMappings) {
                                if (removedCorpIds.contains(row[1])) {
                                    hierIdsToRemove.add(String.format("%08d", row[0]));
                                }
                            }
                            if (!hierIdsToRemove.isEmpty()) {
                                knLogger.debug(methodName, "P7-2: Removing hierarchy map entries for removed corps, groupId=", groupInfoDTO.getGroupId());
                                groupInfoUtil.removeGroupHiearchyMapByOwnerIds(groupInfoDTO.getGroupId(), hierIdsToRemove, "4", xdmsHome, persisterTxn);
                                allRemovedHierIds.addAll(hierIdsToRemove);
                            }
                        } catch (Exception e) {
                            knLogger.warn(methodName, "P7-2: Error removing hierarchy entries for removed corps - ", e.getMessage());
                        }
                        // Read existing CORPGRP_SHAREDLIST, delete all, reinsert only kept entries
                        List<KnCorpSharedCorpInfo> existingShared = groupInfoUtil.selectGroupSharedCorpInfo(corpId, groupInfoDTO.getGroupId(), xdmsHome, persisterTxn);
                        List<Integer> groups = new ArrayList<>(1);
                        groups.add(groupInfoDTO.getGroupId());
                        groupInfoUtil.deleteSharedGroups(groups, xdmsHome, persisterTxn);
                        List<KnCorpGroupInfoPersistDTO> reinsertList = new ArrayList<>();
                        for (KnCorpSharedCorpInfo existing : existingShared) {
                            if (!removedCorpIds.contains(existing.getCorpId()) && !Objects.equals(existing.getCorpId(), corpId)) {
                                KnCorpGroupInfoPersistDTO dto = new KnCorpGroupInfoPersistDTO();
                                dto.setCorpId(corpId);
                                dto.setGroupId(groupInfoDTO.getGroupId());
                                List<KnCorpSharedCorpInfo> singleList = new ArrayList<>(1);
                                singleList.add(existing);
                                dto.setCorpSharedCorpInfoList(singleList);
                                reinsertList.add(dto);
                            }
                        }
                        if (!reinsertList.isEmpty()) {
                            groupInfoUtil.createGroupSharedCorpInfo(reinsertList, xdmsHome, persisterTxn);
                        }
                    }
                }

                if (addedSharedList != null && !addedSharedList.isEmpty()) {
                    // Check which corps are already in CORPGRP_SHAREDLIST to avoid unique constraint violation.
                    // This handles the case where a corp is already shared but a new hierarchy is being added.
                    List<KnCorpSharedCorpInfo> existingSharedCorps = groupInfoUtil.selectGroupSharedCorpInfo(corpId, groupInfoDTO.getGroupId(), xdmsHome, persisterTxn);
                    Set<Integer> alreadySharedCorpIds = new HashSet<>();
                    for (KnCorpSharedCorpInfo existing : existingSharedCorps) {
                        if (existing.getCorpId() != null) alreadySharedCorpIds.add(existing.getCorpId());
                    }
                    // Only insert corps that are not already in CORPGRP_SHAREDLIST
                    List<KnCorpSharedCorpInfo> newCorpsToInsert = new ArrayList<>();
                    for (KnCorpSharedCorpInfo info : addedSharedList) {
                        if (!alreadySharedCorpIds.contains(info.getCorpId()) && !Objects.equals(info.getCorpId(), corpId)) {
                            newCorpsToInsert.add(info);
                        }
                    }
                    if (!newCorpsToInsert.isEmpty()) {
                        List<KnCorpGroupInfoPersistDTO> addPersistList = new ArrayList<>();
                        KnCorpGroupInfoPersistDTO addDto = new KnCorpGroupInfoPersistDTO();
                        addDto.setCorpId(corpId);
                        addDto.setGroupId(groupInfoDTO.getGroupId());
                        addDto.setCorpSharedCorpInfoList(newCorpsToInsert);
                        addPersistList.add(addDto);
                        groupInfoUtil.createGroupSharedCorpInfo(addPersistList, xdmsHome, persisterTxn);
                    }
                    // Insert hierarchy map entries (P6-4) for all added entries (whether corp is new or already shared)
                    List<String> hierIdsToAdd = new ArrayList<>();
                    List<Integer> corpIdsToAdd = new ArrayList<>();
                    for (KnCorpSharedCorpInfo info : addedSharedList) {
                        List<KnXDMHierarchyInfo> hierList = info.getHierarchyList();
                        if (hierList != null && info.getCorpId() != null) {
                            for (KnXDMHierarchyInfo hierInfo : hierList) {
                                String sharedHierarchyId = hierInfo.getSharedHierarchyId();
                                if (sharedHierarchyId != null && !sharedHierarchyId.isEmpty()) {
                                    hierIdsToAdd.add(sharedHierarchyId);
                                    corpIdsToAdd.add(info.getCorpId());
                                }
                            }
                        }
                    }
                    if (!hierIdsToAdd.isEmpty()) {
                        knLogger.debug(methodName, "P7-2: Inserting hierarchy map entries for added corps, groupId=", groupInfoDTO.getGroupId(), " count=", hierIdsToAdd.size());
                        groupInfoUtil.insertSharedGroupHierarchyMap(groupInfoDTO.getGroupId(), hierIdsToAdd, corpIdsToAdd, xdmsHome, persisterTxn);
                    }
                }
            }

            //Get the Added group member list MDNs
            knLogger.debug(methodName," allDistinceMembers :",allDistinceMembers," existingMemList :",existingMemList);
            List<String> addedGrpMemList = new ArrayList<>(allDistinceMembers);
            addedGrpMemList.removeAll(existingMemList);

            //Loop the allDistinctMember and prepare the member DTO to be insert into group member list.
            List<KnCorpContactDTO> addedGrpMemDtoList = new ArrayList<>();
            List<KnSubscriberDTO> addedMembers_MSNorify = null;
            List<KnCorpGroupMemberDTO> addedMembers_GrpMembers = new ArrayList<>();
            Map<String, Integer> osmAuthorizeMap = groupPersistDTO.getOsmAuthorizeMap();
            knLogger.debug(methodName,"addedGrpMemList :",KnGDPRTemplate.mdnList(addedGrpMemList));
            knLogger.debug(methodName,"corpSubscriberMap :",KnGDPRTemplate.mapKeyMdn(corpSubscriberMap));

            List<String> allMemList = new ArrayList<>();
            if(addedGrpMemList!=null&&!addedGrpMemList.isEmpty()) {
                addedMembers_MSNorify = new ArrayList<>();

                for (String mdn : addedGrpMemList) {
                    KnCorpContactDTO corpContactDTO = new KnCorpContactDTO();
                    KnSubscriberDTO subscriberDTO = new KnSubscriberDTO();
                    KnCorpGroupMemberDTO groupMemberDTO = new KnCorpGroupMemberDTO();
                    corpContactDTO.setMdn(mdn);
                    subscriberDTO.setMdn(mdn);
                    groupMemberDTO.setMdn(mdn);
                    if (addedBroadcasters.contains(mdn)) {
                        corpContactDTO.setBroadcaster(1);
                        subscriberDTO.setBroadcaster(1);
                        groupMemberDTO.setBroadcaster(1);
                    }
                    if (persistDto.getInterOpMembers().contains(mdn)) {
                        corpContactDTO.setSupervisory(INTER_OP);
                        subscriberDTO.setSupervisory(INTER_OP);
                        groupMemberDTO.setSupervisory(INTER_OP);
                    }
                    if (allExtMemberList.contains(mdn)) {
                        corpContactDTO.setGroupModifyPerm(DISABLED);
                    } else {
                        corpContactDTO.setGroupModifyPerm(groupModifyPermMap.get(mdn));
                    }
                    if (sgMdnList.contains(mdn)) {
                        corpContactDTO.setMemberType(SG_MDN_MEMBER_TYPE);
                    } else if (sgMdnPatchList.contains(mdn)) {
                        corpContactDTO.setMemberType(SG_MDN_PATCH_MEMBER_TYPE);
                    }
                    if (osmAuthorizeMap.get(mdn) == null) {
                        corpContactDTO.setIsOSMAuthorize(DISABLED);
                        subscriberDTO.setIsOSMAuthorize(DISABLED);
                        groupMemberDTO.setIsOSMAuthorize(DISABLED);
                    } else {
                        corpContactDTO.setIsOSMAuthorize(osmAuthorizeMap.get(mdn));
                        subscriberDTO.setIsOSMAuthorize(osmAuthorizeMap.get(mdn));
                        groupMemberDTO.setIsOSMAuthorize(osmAuthorizeMap.get(mdn));
                    }
                    if (corpSubscriberMap != null && corpSubscriberMap.get(mdn) != null) {
                        boolean bitEnabled = KnGeneralUtil.getFeatureBitValue(corpSubscriberMap.get(mdn).getSubsActiveFS2(), FEATURE_SET.AFFILIATIONFEATURE.value());
                        if (corpSubscriberMap.get(mdn).getClientPVmajorVer() >= com.kodiak.xdms.server.common.resources.KnConstants.PROTOCOL_VERSION_18
                                && bitEnabled && checkClientType(corpSubscriberMap.get(mdn).getClientType(), corpSubscriberMap.get(mdn).getMcpttCompliance())) {
                            corpContactDTO.setIsAffiliationEnabled(ENABLED);
                            subscriberDTO.setIsAffiliationEnabled(ENABLED);
                            groupMemberDTO.setIsAffiliationEnabled(ENABLED);
                        } else {
                            corpContactDTO.setIsAffiliationEnabled(DISABLED);
                            subscriberDTO.setIsAffiliationEnabled(DISABLED);
                            groupMemberDTO.setIsAffiliationEnabled(DISABLED);
                        }
                        corpContactDTO.setCorpId(corpSubscriberMap.get(mdn).getCorpId());
                        groupMemberDTO.setCorpId(corpSubscriberMap.get(mdn).getCorpId());
                        //add only PV20 or above memebers to allMemList for sending notifications
                        int pv = corpSubscriberMap.get(mdn).getClientPVmajorVer();
                        if (pv >= com.kodiak.xdms.server.common.resources.KnConstants.PROTOCOL_VERSION_20 ) {
                            allMemList.add(mdn);
                        }
                    }

                    addedGrpMemDtoList.add(corpContactDTO);
                    addedMembers_MSNorify.add(subscriberDTO);
                    addedMembers_GrpMembers.add(groupMemberDTO);
                }
            }
            knLogger.debug(methodName, "addedGrpMemDtoList - ", addedGrpMemDtoList);
            if (!pochomeAutoAssignFlag) {
                String pocHome = groupInfoUtil.fetchGroupPocHome(grpId, xdmsHome, persisterTxn);
                if (pocHome == null && addedGrpMemList != null && !addedGrpMemList.isEmpty()) {
                    Map<String, Object> pochomeMap = groupInfoUtil.getPocHomeAndClusterIdForCorpGroup(addedGrpMemList, xdmsHome, persisterTxn);
                    String selectedPocHome = null;
                    Integer selectedClusterId = null;
                    selectedClusterId = (Integer) pochomeMap.get(CLUSTERID);
                    selectedPocHome = (String) pochomeMap.get(POCHOME);
                    groupInfoUtil.updatePocHome(selectedPocHome, selectedClusterId, grpId, xdmsHome, persisterTxn);
                }
            }
            Map<Integer, Collection<KnCorpContactDTO>> groupMemberList = new HashMap<>(addedGrpMemDtoList.size());
            groupMemberList.put(groupInfoDTO.getGroupId(), addedGrpMemDtoList);
            groupInfoUtil.insertIntoCorpGroupMemberList(groupMemberList, xdmsHome, persisterTxn);
            knLogger.info(methodName, "---Target---");

            //RECORDING_TARGET_INFO
            Map<String, String> microServicesParamNameValueMap = genInfoUtil.retrieveMSSvcsCommonConfig(clusterId, persisterTxn);
            String targetInfoOptimization = microServicesParamNameValueMap.get(com.kodiak.xdms.server.common.resources.KnConstants.TARGET_INFO_OPTIMIZATION);
            if (!com.kodiak.xdms.server.common.util.KnGeneralUtil.isTargetInfoOptimizationEnabled(targetInfoOptimization)) {
                knLogger.info(methodName, "Target Info Optimization is not enabled.--->");
                Collection<String> targetList = new ArrayList<>();
                targetList.add(corpId + "_" + grpId);
                IXDMServerDAO commonXDMServerDAO = KnFactorySelector.getDAOFactory(KnFactorySelector.DB).createXDMServerDAO(xdmsHome);
                Collection<KnRecordingTargetInfoDTO> dbRecordingTargetList = commonXDMServerDAO
                        .getRecordingInfoTargetByTarget(targetList, persisterTxn);

                if (dbRecordingTargetList.isEmpty() && recordingInfoList != null) {
                    commonXDMServerDAO.createRecordingInfoForTarget(recordingInfoList, persisterTxn);

                } else if (dbRecordingTargetList.size() > 0 && recordingInfoList != null) {
                    Map<String, Integer> updateRecordingInfo = recordingInfoList.stream().collect(Collectors.toMap(KnRecordingTargetInfoDTO::getTarget, KnRecordingTargetInfoDTO::getRecType));
                    commonXDMServerDAO.updateRecordingInfoTargetByTarget(updateRecordingInfo, persisterTxn);
                }

                if (disabledTarget != null && !disabledTarget.isEmpty()) {
                    commonXDMServerDAO.deleteRecordingInfoTargetByTarget(disabledTarget, persisterTxn);
                }
            }
            //setting external members
            List<String> replacememB = new ArrayList<>(existingMembers);
            Collection<String> allExternalMdnList=new ArrayList<>();
            if(!externalMdnList.isEmpty()){
                knLogger.debug(methodName," externalMdnList :",externalMdnList);
                allMemList.addAll(externalMdnList);
                allExternalMdnList.addAll(externalMdnList);
            }
            Collection<KnCorpGroupMemberDTO> existigGrpMemberDetails = groupInfoUtil.getCorpGroupMembersList(groupList, xdmsHome, persisterTxn);
            List<String> groupMembersList=existigGrpMemberDetails.stream().map(KnCorpGroupMemberDTO::getMdn).collect(Collectors.toList());
            ICorpXdmDAO corpXdmDao = new KnCorpXdmDAO(xdmsHome);
            Collection<KnCorpSubscriberDTO> externalGrpMemberDetails = corpXdmDao.getExternalPoCSubscriberInfo(groupMembersList,
                    corpId, persisterTxn);
            if(!externalGrpMemberDetails.isEmpty()){
                List<String> existingExternalGrpMdn = externalGrpMemberDetails.stream().map(KnCorpSubscriberDTO::getMdn).collect(Collectors.toList());
                knLogger.debug(methodName," existingExternalGrpMdn :",existingExternalGrpMdn);
                allExternalMdnList.addAll(existingExternalGrpMdn);
                replacememB.addAll(existingExternalGrpMdn);
                //MINT-22706
                //If the group is shared(GROUP_SHARED=1) then don't add external broadcaster group members to list for deletion.
                if (null == grpBasicInfo.getGrpShared() || grpBasicInfo.getGrpShared() == 0) {
                    actualDeletedBrdstr.addAll(existingExternalGrpMdn);
                }
            }
            groupInfoDTO.setExternalMdnList(allExternalMdnList);
            knLogger.debug(methodName, "allMemList - ", KnGDPRTemplate.mdnList(allMemList));
            if(addedBroadMap.get(grpId)!=null){
                addedBroadMap.get(grpId).addAll(allMemList);
            }
            Map<Integer, Collection<String>> liAddedBroadMap = new HashMap<>(1);
            liAddedBroadMap.put(grpId,addedGrpMemList);

            Collection<KnSIPProxySvcConfigDTO> sipProxySvcConfigInfoDTO = commonInfoUtil.getSipProxySvcConfig(xdmsHome, persisterTxn);
            String groupPocHome = groupInfoUtil.fetchGroupPocHome(grpId, xdmsHome, persisterTxn);
            String effectivePocHome = genInfoUtil.getEffectivePocHome(corpPocHome, groupPocHome);
            String groupSipUri = sipProxySvcConfigInfoDTO.stream()
                    .filter(sipProxy -> sipProxy.getPttServerId().equals(effectivePocHome)).findFirst()
                    .map(KnSIPProxySvcConfigDTO::getSipProxyURI).orElse(null);

            //send notify to all the members in broadcat group
            Map<String, KnOPDirChgDTO> etagMap = commonInfoUtil.formSubscriberNotification(addedBroadMap, groupEtagMap,
                    com.kodiak.xdms.server.common.resources.KnConstants.DOC_CHANGE_TYPE.ADD.value(), null, null, null);
            etagMap = contactInfoUtil.updateDistinctSubcribersDirectory(null, groupIdLst, etagMap, xdmsHome, persisterTxn);

            Map<String, KnOPDirChgDTO> liEtagMap = commonInfoUtil.formSubscriberNotification(liAddedBroadMap, groupEtagMap,
                    com.kodiak.xdms.server.common.resources.KnConstants.DOC_CHANGE_TYPE.ADD.value(), null, null, null);
            liEtagMap = contactInfoUtil.updateDistinctSubcribersDirectoryBCG(null, groupIdLst, liEtagMap, xdmsHome, persisterTxn);
            //profile mdn zone,channel and priority deletion happens by async task
            if (!actualDeletedBrdstr.isEmpty()) {
                Map<Integer, List<String>> grpMemMap = new HashMap<>();
                grpMemMap.put(grpId, actualDeletedBrdstr);
                groupInfoUtil.deleteGroupDistInfo(grpMemMap, xdmsHome, persisterTxn);

                //Modified for 8.1.2 release
                //Deleting Channel Group
                KnCorpInOutParamDTO corpInOutParamDTO = new KnCorpInOutParamDTO();
                groupInfoUtil.cleanUpCampedGrp(grpMemMap, corpInOutParamDTO, xdmsHome, persisterTxn);
                knLogger.debug(methodName, "groupMemMap: - ", KnGDPRTemplate.mapMdnAsListValue(grpMemMap));
                etagMap = commonInfoUtil.formTGSCDocumentNotification(corpInOutParamDTO, etagMap, xdmsHome, persisterTxn);
            }

            LinkedHashMap<Integer, LinkedList<String>> actualMdnToBeDeletedFromGroupMap = new LinkedHashMap<>();
            actualMdnToBeDeletedFromGroupMap.put(grpId, removedMembersList);
            knLogger.debug(methodName, "actualMdnToBeDeletedFromGroupMap - ", KnGDPRTemplate.mapMdnAsLinkedValue(actualMdnToBeDeletedFromGroupMap));
            LinkedHashMap<Integer, LinkedList<Integer>> delGroupMemStatus = groupInfoUtil.deleteCorpGroupMemberList(actualMdnToBeDeletedFromGroupMap, xdmsHome, persisterTxn);
            //Get the actual deleted members
            Map<Integer, List<String>> actualDeletedMems = groupInfoUtil.getActualDeletedGrpMembers(actualMdnToBeDeletedFromGroupMap, delGroupMemStatus);
            // Group:
            Map<String, Collection<String>> groupFailurePairingMap = new HashMap<>();
            Map<String, Collection<String>> actualDeletedGroupMemberMap = actualDeletedMems.entrySet().stream()
                    .collect(Collectors.toMap(actualMap -> String.valueOf(actualMap.getKey()), Entry::getValue));
            if (actualDeletedGroupMemberMap != null && !actualDeletedGroupMemberMap.isEmpty()) {
                Map<String, Collection<String>> emergDestUserMap = corpSubsProvInfoUtil.getEmergDestUserMap(actualDeletedGroupMemberMap.keySet(),
                        xdmsHome, persisterTxn);
                knLogger.debug(methodName, "emergDestUserMap-- ", emergDestUserMap);
                if (emergDestUserMap != null && !emergDestUserMap.isEmpty()) {
                    emergDestUserMap.forEach((emergDest, emergUser) -> {
                        Collection<String> removedGroupMember = actualDeletedGroupMemberMap.get(emergDest);
                        Collection<String> mappedDestination = emergUser.stream().filter(removedGroupMember::contains).collect(Collectors.toList());
                        if (mappedDestination != null && !mappedDestination.isEmpty())
                            groupFailurePairingMap.put(emergDest, mappedDestination);
                    });
                }
                knLogger.debug(methodName, "groupFailurePairingMap-- ", groupFailurePairingMap);
                Map<Integer, Collection<String>> intActualDeletedGroupMemberMap = new HashMap<>();
                for (Entry<String, Collection<String>> entry : actualDeletedGroupMemberMap.entrySet()) {
                    try {
                        Integer key = Integer.parseInt(entry.getKey());
                        intActualDeletedGroupMemberMap.put(key, entry.getValue());
                    } catch (NumberFormatException e) {
                        knLogger.debug("Skipping entry with key due to NumberFormatException- ", entry.getKey());
                    }
                }
                knLogger.debug(methodName, "intActualDeletedGroupMemberMap", intActualDeletedGroupMemberMap);
                etagMap = commonInfoUtil.formSubscriberNotification(intActualDeletedGroupMemberMap, groupEtagMap,
                        com.kodiak.xdms.server.common.resources.KnConstants.DOC_CHANGE_TYPE.REPLACE.value(), etagMap, null, grpBasicInfo.getGroupCreatedBy());
                if (!groupFailurePairingMap.isEmpty()) {
                    knLogger.error(methodName, "Emergency Destination Mapping Exists - Group");
                    throw new KnCorpBOValidationException(KnErrorCodes.Validator.EMERGENCY_DESTINATION_MAPPING_EXISTS_FOR_GROUP,
                            "Emergency Destination Mapping Exists for Group--", CORP_GROUP_MANAGER,
                            MODIFY_GROUP, "", groupFailurePairingMap.keySet().toString(), "");
                }
            }
            //Call to update the broadcasters flag in group member list table for modified members
            //Map to hold the broadcster values for modified member list
            //Modified members with broadcaster flag and groupModifyPermission:
            List<KnSubscriberDTO> modifyMembers_MSNorify = new ArrayList<>();
            for (KnCorpGroupMemberDTO groupMemberDTO : modifiedMembers) {
                if (groupMemberDTO.getGroupModifyPerm() == null && existingGroupModifyPermMap.containsKey(groupMemberDTO.getMdn())) {
                    groupMemberDTO.setGroupModifyPerm(existingGroupModifyPermMap.get(groupMemberDTO.getMdn()));
                } else if (allExtMemberList.contains(groupMemberDTO.getMdn())) {
                    groupMemberDTO.setGroupModifyPerm(DISABLED);
                }

                //populate broadcaster flag for modified members
                KnSubscriberDTO subscriberDTO = new KnSubscriberDTO();
                String mdn = groupMemberDTO.getMdn();
                subscriberDTO.setMdn(mdn);
                if(modifyingNonBrdstrMem.contains(mdn)){
                    knLogger.debug(methodName,"modifyingNonBrdstrMem -",KnGDPRTemplate.mdnList(modifyingNonBrdstrMem)," member mdn -",KnGDPRTemplate.mdn(mdn));
                    subscriberDTO.setBroadcaster(0);
                }else if(finalBroadcasters.contains(mdn)){
                    knLogger.debug(methodName,"finalBroadcasters -",KnGDPRTemplate.mdnList(finalBroadcasters)," member mdn -",KnGDPRTemplate.mdn(mdn));
                    subscriberDTO.setBroadcaster(1);
                }

                subscriberDTO.setCallPermission(groupMemberDTO.getCallInitiatePermission()+","+groupMemberDTO.getCallReceivePermission()+","+groupMemberDTO.getInCallPermission());
                subscriberDTO.setVideoCallPermission(groupMemberDTO.getVideoCallInitiatePermission()+","+groupMemberDTO.getVideoCallReceivePermission()+","+groupMemberDTO.getVideoInCallPermission());
                subscriberDTO.setSupervisory(groupMemberDTO.getSupervisory());
                subscriberDTO.setLocWatcher(groupMemberDTO.getLocWatcher());
                subscriberDTO.setIsOSMAuthorize(groupMemberDTO.getIsOSMAuthorize());
                knLogger.debug(methodName, "[VIDEO-PERM] modifyMembers_MSNorify - mdn:", subscriberDTO.getMdn(),
                        ", callPermission:", subscriberDTO.getCallPermission(),
                        ", videoCallPermission:", subscriberDTO.getVideoCallPermission());
                modifyMembers_MSNorify.add(subscriberDTO);
            }
            knLogger.debug(methodName,"modifyMembers_MSNorify -",modifyMembers_MSNorify);

            List<Integer> groupIds = new ArrayList<>();
            groupIds.add(grpId);
            Map<Integer, Map<String, KnCorpGroupMemberDTO>> groupMemberMap = groupInfoUtil.getBulkGroupMembersList(groupIds,
                    xdmsHome, persisterTxn);
            groupInfoUtil.updateGrpMemListProperties(modifiedMembers, grpId, xdmsHome, persisterTxn);

            Map<String, KnCorpGroupMemberDTO> memberDetails = groupMemberMap.get(grpId);
            List<String> nonBrdMembers = new ArrayList<>();
            for (KnCorpGroupMemberDTO groupMember : modifiedMembers) {
                knLogger.info(methodName, "groupMember.getMdn() -", groupMember.getMdn());
                if (memberDetails.containsKey(groupMember.getMdn())) {
                    KnCorpGroupMemberDTO mem = memberDetails.get(groupMember.getMdn());
                    knLogger.info(methodName, "DB mem-", mem.getBroadcaster(), "Req Mem: ", groupMember.getBroadcaster());
                    if (mem.getBroadcaster() != groupMember.getBroadcaster()) {
                        nonBrdMembers.add(groupMember.getMdn());
                    }
                }
            }
            knLogger.info(methodName, "nonBrdMembers -", nonBrdMembers);

            //Update the group member count
            List<Integer> sublistIds = new ArrayList<>(1);
            sublistIds.add(groupPersistDTO.getGroupMemberListId());
            //todo need to change as per new SP
            if (corpProfile.getLargeGrpSupported() == 1) {
                sublistInfoUtil.updateSublistsSubscribersContactCount(sublistIds, MAX_LIMIT_VALIDATION_NOT_REQUIRED,
                        MAX_LIMIT_VALIDATION_NOT_REQUIRED, MAX_LIMIT_VALIDATION_NOT_REQUIRED, xdmsHome, persisterTxn, corpProfile.getMaxMemPerLrgBGrp());
            } else {
                sublistInfoUtil.updateSublistsSubscribersContactCount(sublistIds, MAX_LIMIT_VALIDATION_NOT_REQUIRED,
                        MAX_LIMIT_VALIDATION_NOT_REQUIRED, MAX_LIMIT_VALIDATION_NOT_REQUIRED, xdmsHome, persisterTxn, corpProfile.getMaxMemPerBCGrp());
            }


            boolean currentLargeGrpFlag = false;
            //UCSPROVCONFIG-8968
            int newMemberCount = 0;
            Map<Integer, Integer> newGroupMemberCount = groupInfoUtil.getGroupMemCount(groupIdLst, xdmsHome, persisterTxn);
            if (newGroupMemberCount != null && !newGroupMemberCount.isEmpty() && newGroupMemberCount.containsKey(grpId)) {
                newMemberCount = newGroupMemberCount.getOrDefault(grpId, 0);
            }

            if (newMemberCount > corpProfile.getMaxMemPerBCGrp()) {
                currentLargeGrpFlag = true;
            }

            Collection<KnCorpAddlTGInfoDTO> delAddlTGList = new ArrayList<>();
            Collection<KnCorpAddlTGInfoDTO> subsAddlTGList = groupInfoUtil.getSubsAddlDetails(groupIdLst, xdmsHome, persisterTxn);
            Collection<String> addlTgDelMdnList = new ArrayList<>();
            if (!actualDeletedBrdstr.isEmpty()) {
                if (subsAddlTGList != null && !subsAddlTGList.isEmpty()) {
                    delAddlTGList.addAll(subsAddlTGList.stream().filter(addlMem -> actualDeletedBrdstr.contains(addlMem.getMdn())).collect(Collectors.toList()));
                    if (delAddlTGList != null) {
                        groupInfoUtil.deleteSubsAddlTGList(delAddlTGList, xdmsHome, persisterTxn);
                        addlTgDelMdnList.addAll(delAddlTGList.stream().map(KnCorpAddlTGInfoDTO::getMdn).collect(Collectors.toList()));
                    }
                }
            }
            Collection<String> addlTgAllMdnList = subsAddlTGList.stream().map(KnCorpAddlTGInfoDTO::getMdn).distinct().collect(Collectors.toList());
            etagMap = groupInfoUtil.updateAddlTalkGroupImpactedTables(xdmsHome, addlTgAllMdnList, persisterTxn, etagMap);
           /* Collection<KnCorpAddlTGInfoDTO> modifyAddlTGList = new ArrayList<>();
            addlTgAllMdnList.removeAll(addlTgDelMdnList);
            if (addlTgAllMdnList != null && !addlTgAllMdnList.isEmpty()) {
                addlTgAllMdnList.forEach(modMdn -> {
                    KnCorpAddlTGInfoDTO corpAddlTGInfoDTO = new KnCorpAddlTGInfoDTO();
                    corpAddlTGInfoDTO.setAvatar(groupInfoDTO.getAvatar());
                    corpAddlTGInfoDTO.setGroupMemCount(memberCount);
                    corpAddlTGInfoDTO.setGroupType(NOT_MODIFIED);
                    corpAddlTGInfoDTO.setGroupCreatedBy(NOT_MODIFIED);
                    corpAddlTGInfoDTO.setGroupId(grpId);
                    corpAddlTGInfoDTO.setMdn(modMdn);
                    modifyAddlTGList.add(corpAddlTGInfoDTO);
                });
            }
            knLogger.debug(methodName, "etagMap AddlTG -for modify- ", etagMap);
            etagMap = KnCorpCommonInfoUtil.formXcapAddlTGDiffNotification(etagMap, null,
                    modifyAddlTGList, delAddlTGList, corpId);*/
            knLogger.debug(methodName, "etagMap AddlTG -diff -for modify- ", KnGDPRTemplate.mapKeyMdn(etagMap));
            //Preparing for notification data
            Map<Integer, String> grpNameMap = new HashMap<>(1);
            grpNameMap.put(grpId, groupName);
            Map<Integer, Integer> grpMemCountMap = new HashMap<>(1);
            grpMemCountMap.put(grpId, bcGrpPersistDTO.getGroupMemberCount());
            Map<Integer, Integer> avatarMap = new HashMap<>(1);
            avatarMap.put(grpId, avatar);

            //Creating notification for existing broadcaster
            List<String> replaceBrdstr = new ArrayList<>(existingBroadcasters);
            replaceBrdstr.removeAll(actualDeletedBrdstr);
            Map<Integer, List<String>> replaceBroadMap = new HashMap<>(1);
            replaceBroadMap.put(grpId, replaceBrdstr);
            Map<Integer, List<String>> liReplaceBroadMap = new HashMap<>(1);

            replacememB.removeAll(actualDeletedMems.get(grpId));
            if((addedBroadcasters.isEmpty() && actualDeletedBrdstr.isEmpty()) || (!addedMemberDTOLst.isEmpty() || !removedMemberList.isEmpty())){
                liReplaceBroadMap.put(grpId, replacememB);
            }

            if (!currentLargeGrpFlag && !grpBasicInfo.isLargeGroup()) {
                commonInfoUtil.formSubscriberNotification(replaceBroadMap, groupEtagMap,
                        grpNameMap, com.kodiak.xdms.server.common.resources.KnConstants.DOC_CHANGE_TYPE.REPLACE.value(), etagMap, grpMemCountMap, avatarMap);
                commonInfoUtil.formSubscriberNotification(liReplaceBroadMap, groupEtagMap,
                        grpNameMap, com.kodiak.xdms.server.common.resources.KnConstants.DOC_CHANGE_TYPE.REPLACE.value(), liEtagMap, grpMemCountMap, avatarMap);
            } else {
                for (String extstMdn : existingBroadcasters) {
                    etagMap.remove(extstMdn);
                }
            }
            Map<Integer, Integer> groupLrgGrpFlagMap = new HashMap<>(1);
            if (currentLargeGrpFlag) {
                groupLrgGrpFlagMap.put(grpId, 1);
            } else {
                groupLrgGrpFlagMap.put(grpId, 0);
            }
            groupInfoUtil.updateIsLargeGrpFlag(groupLrgGrpFlagMap, xdmsHome, persisterTxn);
            //Creating notification for deleted broadcaster
            Map<Integer, List<String>> removedBroadMap = new HashMap<>(1);
            List<String> nonMatchingMembers = new ArrayList<>();
            if (actualDeletedBrdstr != null) {
                nonMatchingMembers.addAll(actualDeletedBrdstr);
                nonMatchingMembers.removeAll(nonBrdMembers);
                knLogger.info(methodName, "before sending notify", nonMatchingMembers.size());
            }
            removedBroadMap.put(grpId, nonMatchingMembers);
            Map<Integer, List<String>> liRemovedBroadMap = new HashMap<>(1);
            liRemovedBroadMap.put(grpId, actualDeletedMems.get(grpId));
            commonInfoUtil.formSubscriberNotification(removedBroadMap, groupEtagMap,
                    null, com.kodiak.xdms.server.common.resources.KnConstants.DOC_CHANGE_TYPE.REMOVE.value(), etagMap, null, null);
            commonInfoUtil.formSubscriberNotification(liRemovedBroadMap, groupEtagMap,
                    null, com.kodiak.xdms.server.common.resources.KnConstants.DOC_CHANGE_TYPE.REMOVE.value(), liEtagMap, null, null);

            if(groupInfoDTO.isUpmCall()){
                knLogger.info(methodName, "upm call set group sharing from grpbasicInfo");
                isGrpSharingEnabled = grpBasicInfo.getGrpShared()!=null && grpBasicInfo.getGrpShared() == GROUP_SHARING_ENABLE_INDICATOR;
            }

            Collection<KnCorpGroupMemberDTO> grpMemberDetails = groupInfoUtil.getCorpGroupMembersList(groupList, xdmsHome, persisterTxn);
            List<KnCorpGroupMemberDTO> delMembers = existigGrpMemberDetails.stream()
                    .filter(member -> removedMembersList.contains(member.getMdn()))
                    .collect(Collectors.toList());
            knLogger.debug(methodName, "Adding delMembers to grpMemberDetails:", delMembers);
            grpMemberDetails.addAll(delMembers);

            if(isGrpSharingEnabled) {
                knLogger.info(methodName, "Entering into group sharing flow");
                //notification changes for owned/shared corporate
                if (groupInfoDTO.isOwnerCorpReq()) {
                    knLogger.debug(methodName, "Request from owner corp");
                    resetNotiCapabilityOnwedCorp(etagMap);

                } else {
                    knLogger.debug(methodName, "Request from shared corp - ", groupInfoDTO.getCorpId(), " Group Corp - ", grpBasicInfo.getGroupCorpId());
                    List<String> sharedReqCorpMemList = new ArrayList<>();
                    List<KnCorpGroupMemberDTO> allMembers = new ArrayList<>(grpMemberDetails);
                    allMembers.addAll(addedMembers_GrpMembers);
                    if (allMembers != null && !allMembers.isEmpty()) {
                        for (KnCorpGroupMemberDTO member : allMembers) {
                            if (member.getCorpId() == groupInfoDTO.getCorpId()) {
                                sharedReqCorpMemList.add(member.getMdn());
                            }
                        }
                    }
                    removeOtherCorpMembers(etagMap, sharedReqCorpMemList);
                }
            }

            //get the LI Data
            grpNameMap.put(grpId, corpId + "_" + groupName);
            //All the member list after modification
            List<String> allMemberList = new ArrayList<>(finalGroupMemList.size());
            for (KnCorpSubscriberDTO subscriberDTO : finalGroupMemList) {
                allMemberList.add(subscriberDTO.getMdn());
            }
            LinkedList<KnLIEventDTO> liEventList =null;
            if(!upmCall){
                liEventList = populateLIData(liEtagMap
                        , xdmsHome, grpNameMap, allMemberList, addedGrpMemDtoList,actualDeletedMems.get(grpId),persisterTxn);
            }else{
                liEventList = upmBGCPopulateLIData(liEtagMap
                        , xdmsHome, grpNameMap, allMemberList, addedGrpMemDtoList,actualDeletedMems.get(grpId),persisterTxn);
            }

            //Remove the subscriber of type 8 from the notification
            if (removedGroupMdnList != null && !removedGroupMdnList.isEmpty()) {
                for (String grpMdn : removedGroupMdnList) {
                    etagMap.remove(grpMdn);
                }
            }
            //Remove the added mdn from etag Map
            if (persistDto.getGroupMdnList() != null && !persistDto.getGroupMdnList().isEmpty()) {
                for (String grpMdn : persistDto.getGroupMdnList()) {
                    etagMap.remove(grpMdn);
                }
            }
            if (corpProfile.getLinkedGwKey() != null && persistDto.isGrpMdnPresent()) {
                //get the refernce id from the account info table.
                KnCorpGWLinkedAccountInfoDTO accountInfo = commonInfoUtil.getCorporateLinkedAccountInfo(corpProfile.getLinkedGwKey(), xdmsHome, persisterTxn);
                //update etag in the account info table
                //update etag
                Map<String, String> asyncInput = new HashMap<>();
                asyncInput.put(KnDbSyncFwConstants.PTTSERVER_ID, xdmsHome);
                asyncInput.put(KnDbSyncFwConstants.NNI_REF_ID, accountInfo.getNniRefId());
                knLogger.debug(methodName, " Async inputs", asyncInput);
                KnSqlJobCollector collector = KnSqlJobCollector.getInstance();
                int serviceType = KnDbSyncFwConstants.EXECUTOR.ETAG_UPDATE_NNI.value();
                collector.collect(serviceType, asyncInput);

            }
            for (Entry<String, KnOPDirChgDTO> entry : etagMap.entrySet()) {
                KnOPDirChgDTO values = entry.getValue();
                if (null != values) {
                    Collection<KnOPDocChgDTO> doclist = values.getDocChgDTO();
                    if (doclist != null) {
                        for (KnOPDocChgDTO changeDoc : doclist) {
                            changeDoc.setGroupType(grpBasicInfo.getGrpType());
                            changeDoc.setAddedGroupMembers(addedMembers_MSNorify);
                            changeDoc.setRemovedGroupMembers(actualDeletedMems.get(grpId));
                            changeDoc.setModifiedGrpMembers(modifyMembers_MSNorify);
                        }
                    }
                }
            }
            if(!groupInfoDTO.isUpmCall()) {
                //this block should be called for system profile,As user profile is handled seperatly
                Map<String, String> mcsXcapRootUriMap = new HashMap<>();
                Map<Integer, Integer> groupListMap = new HashMap<>();
                groupListMap.put(groupInfoDTO.getGroupId(), CB_MAPPING.ETAG_CHANGE.value());
                Map<String, Collection<KnDocChangeListDTO>> profileMdnEtagMap = new HashMap<>();
                //MINT-25739 : below changes .
                if (!modifyMemList.isEmpty() && null != modifyMemList) {
                    addedGrpMemList.addAll(modifyMemList);
                }
                List<String> dispMdnList = new ArrayList<>(genInfoUtil.selectSubDetails(addedGrpMemList, persisterTxn));
                profileMdnEtagMap.putAll(corpUserProfileUtil.updateImpactedCBDocuments(String.valueOf(corpId), null, groupListMap, null, xdmsHome, null, allRemovedHierIds.isEmpty() ? null : new ArrayList<>(allRemovedHierIds), persisterTxn));
                //MINT-25738 mcsxcap notification for wds
                profileMdnEtagMap.putAll(corpUserProfileUtil.profileMdnEtagUpdateForCreateGroup(null, String.valueOf(corpId), dispMdnList, "1", xdmsHome, persisterTxn));

                respDto.setProfileMdnEtagMap(profileMdnEtagMap);

                if (!profileMdnEtagMap.isEmpty()) {
                    mcsXcapRootUriMap.putAll(genInfoUtil.getXCAPRootURI(new ArrayList<>(profileMdnEtagMap.keySet()), persisterTxn, true));
                }
                respDto.setMcsXcapRootUriMap(mcsXcapRootUriMap);
            }
            //MINT-22713 fix
            Map<Integer, KnCorpGroupDTO> groupDetailsMap = new HashMap<>();
            groupDetailsMap.put(grpId, groupInfoDTO);
            etagMap = commonInfoUtil.formSubscriberNotification(grpDistMap, groupEtagMap,
                    com.kodiak.xdms.server.common.resources.KnConstants.DOC_CHANGE_TYPE.REPLACE.value(), etagMap, groupDetailsMap, grpBasicInfo.getGroupCreatedBy());
            respDto.setChangeLogMap(etagMap);
            respDto.setLiEventList(liEventList);
            respDto.setEtag(String.valueOf(groupEtagMap.get(grpId)));
            respDto.setMdnCorpId(grpBasicInfo.getGroupCorpId()); // Provides the CorpId of the Group owner.
            respDto.setGroupCreatedBy(grpBasicInfo.getGroupCreatedBy());
            respDto.setNewGroupDisplayName(groupInfoDTO.getGroupDisplayName());
            respDto.setActualDeletedBroadcaster(actualDeletedBrdstr);
            if (null != groupPersistDTO.getUgwInterop()) {
                respDto.setLmrInteropFlag(groupPersistDTO.getUgwInterop());
            }
            respDto.setGrpSIPUri(groupSipUri);

            if (null == recordFsValue && null != grpBasicInfo.getRecordingFs()) {
                recordFsValue = grpBasicInfo.getRecordingFs();
            }
            respDto.setRecordingFs(recordFsValue);

            populate(respDto);
            if (responseDTO.getFailedDataList() != null && !responseDTO.getFailedDataList().isEmpty()) {
                respDto.setFailedDataList(responseDTO.getFailedDataList());
            }

            //Changes for PDMBB-12990
            //Assign Zones and Position
            //If new flag is not null and is enabled then only do below
            String autoAssignZoneChannelFlag = genInfoUtil.retrieveMSSvcsCommonConfig(clusterId, persisterTxn)
                    .get(AUTO_ASSIGN_ZONE_POSITION);
            knLogger.debug(methodName, "autoAssignZoneChannelFlag:", autoAssignZoneChannelFlag);
            if (autoAssignZoneChannelFlag != null && autoAssignZoneChannelFlag.equals("1")) {
                // If auto-assign is disabled, return disabled status
                Collection<? extends KnCorpSubscriberDTO> memberListToBeAdded = groupInfoDTO.getAddedMemberDTOMdns();
                if (memberListToBeAdded == null || memberListToBeAdded.isEmpty()) {
                    knLogger.debug(methodName, "AutoAssign memberListToBeAdded is NULL");
                    if (modifiedMembers != null && !modifiedMembers.isEmpty()) {
                        memberListToBeAdded = modifiedMembers.stream().filter(mem -> mem.getBroadcaster() == BROADCAST_BROUP_BROADCASTER).collect(Collectors.toList());
                    }
                }
                if (memberListToBeAdded != null && !memberListToBeAdded.isEmpty()) {
                    Map<String, Object> assignmentResult = performAutoAssignZonesAndChannels(
                            Arrays.asList(groupInfoDTO.getGroupId()),
                            memberListToBeAdded,
                            corpProfile,
                            contactInfoUtil,
                            persisterTxn
                    );
                    String autoZonePositionStatus = (String) assignmentResult.get("status");
                    // After performAutoAssignZonesAndChannels succeeds update notification with zone/channel data
                    if (ZONE_ASSIGNMENT_STATUS.ASSIGNED.value().equals(autoZonePositionStatus) || ZONE_ASSIGNMENT_STATUS.PARTIAL.value().equals(autoZonePositionStatus)) {
                        etagMap = updateAddlTGNotification(groupInfoDTO.getGroupId(), etagMap, xdmsHome, persisterTxn);
                        respDto.setChangeLogMap(etagMap);
                    }
                    List<String> unassignedMdns = (List<String>) assignmentResult.get("unassignedMdns");
                    respDto.setZonePositionAssignmentStatus(autoZonePositionStatus);
                    if (unassignedMdns != null && !unassignedMdns.isEmpty()) {
                        respDto.setUnassignedMdns(unassignedMdns);
                    }
                    knLogger.debug(methodName, "respDto with zonePositionAssignmentStatus:", respDto.getZonePositionAssignmentStatus());
                }
                else{
                    respDto.setZonePositionAssignmentStatus(ZONE_ASSIGNMENT_STATUS.DISABLED.value());
                    knLogger.info(methodName, "No Members for Auto Assignment. Status:", respDto.getZonePositionAssignmentStatus());
                }
            }
            else{
                respDto.setZonePositionAssignmentStatus(ZONE_ASSIGNMENT_STATUS.DISABLED.value());
                knLogger.info(methodName, "Auto-assignment disabled. Status:", respDto.getZonePositionAssignmentStatus());
            }

        } catch (KnValidationException ve) {
            knLogger.error(methodName, "KnValidationException occured while modify Group - ", ve);
            populate(respDto, ve);
        } catch (KnCorpBOException be) {
            knLogger.error(methodName, "KnCorpBOException occured while modify Group - ", be);
            populate(respDto, be);
        } catch (Exception e) {
            knLogger.error(methodName, "KnValidationException occured while modify Group - ",
                    new KnException(KnErrorCodes.BOEntity.INTERNAL_ERROR, e.getMessage(), e));
            populate(respDto, e);
        }
        return respDto;
    }

    public KnCorpResponseDTO updateGrpBroadcasters(String mdn, KnPersisterTxn persisterTxn) {
        String methodName = "updateGrpBroadcasters(String, KnPersisterTxn)";
        KnCorpResponseDTO respDTO = new KnCorpResponseDTO();
        try {
            String xdmsHome = KnGeneralUtil.getXDMServerPttServerId();
            // retrieve group id list where mdn is broadcaster
            // get the group info for all group ids - getGrpsNameEtagInfo
            // disable the broadcaster
            // delete from distribution
            // Form notification data
            // form LI Data
            List<Integer> brdstGrpIds = groupInfoUtil.getBroadcstGroupList(mdn, xdmsHome, persisterTxn);
            if (!brdstGrpIds.isEmpty()) {
                List<KnCorpGroupDTO> groupInfoList = groupInfoUtil.getGrpsNameEtagInfo(brdstGrpIds, xdmsHome, persisterTxn);
                List<String> mdnList = new ArrayList<>(1);
                mdnList.add(mdn);
                Map<Integer, List<String>> groupMemMap = new HashMap<>(brdstGrpIds.size());
                Map<Integer, Integer> groupEtagMap = new HashMap<>(brdstGrpIds.size());
                //Map<Integer, String> grpNameMap = new HashMap<>(brdstGrpIds.size());
                for (KnCorpGroupDTO groupDTO : groupInfoList) {
                    groupMemMap.put(groupDTO.getGroupId(), mdnList);
                    groupEtagMap.put(groupDTO.getGroupId(), groupDTO.getETag());
                    //grpNameMap.put(groupDTO.getGroupId(), groupDTO.getGroupDisplayName().trim());
                }

                groupInfoUtil.deleteGroupDistInfo(groupMemMap, xdmsHome, persisterTxn);
                groupInfoUtil.updateGrpBroadcasters(groupMemMap, xdmsHome, persisterTxn);

                //Updating and preparing directory details and etag.
                Map<String, KnOPDirChgDTO> etagMap = contactInfoUtil.updateSubscribersDirectory(mdnList, null, xdmsHome, persisterTxn);
                commonInfoUtil.formSubscriberNotification(groupMemMap, groupEtagMap,
                        null, com.kodiak.xdms.server.common.resources.KnConstants.DOC_CHANGE_TYPE.REMOVE.value(), etagMap, null, null);

                KnCorpInOutParamDTO corpInOutParamDTO = new KnCorpInOutParamDTO();

                groupInfoUtil.cleanUpCampedGrp(groupMemMap, corpInOutParamDTO, xdmsHome, persisterTxn);

                knLogger.debug(methodName, "groupMemMap: - ", KnGDPRTemplate.mapMdnAsListValue(groupMemMap));
                etagMap = commonInfoUtil.formTGSCDocumentNotification(corpInOutParamDTO, etagMap, xdmsHome, persisterTxn);

                LinkedList<KnLIEventDTO> liEventList = new LinkedList<>();
                for (KnCorpGroupDTO groupDTO : groupInfoList) {
                    KnCorpGroupInfoPersistDTO groupInfoPersistDTO = new KnCorpGroupInfoPersistDTO();
                    groupInfoPersistDTO.setCorpId(groupDTO.getCorpId());
                    groupInfoPersistDTO.setGroupDisplayName(groupDTO.getGroupDisplayName().trim());
                    LinkedList<KnLIEventDTO> liList = populateDeleteGroupLIData(etagMap, xdmsHome, groupInfoPersistDTO,persisterTxn);
                    if (liList.size() > 0) {
                        liEventList.addAll(liList);
                    } else {
                        break;
                    }
                }
                knLogger.debug(methodName, "liEventList - " + liEventList);

                for (Entry<String, KnOPDirChgDTO> entry : etagMap.entrySet()) {
                    KnOPDirChgDTO values = entry.getValue();
                    if (values != null) {
                        Collection<KnOPDocChgDTO> doclist = values.getDocChgDTO();
                        if (doclist != null) {
                            for (KnOPDocChgDTO changeDoc : doclist) {
                                changeDoc.setGroupType(BROADCAST_GROUP);
                            }
                        }
                    }
                }

                respDTO.setChangeLogMap(etagMap);
                respDTO.setLiEventList(liEventList);
            }
            populate(respDTO);
        } catch (KnCorpBOException e) {
            knLogger.error(methodName, "KnCorpBOException occured while updating group broadcaster - ", e);
            populate(respDTO, e);
        } catch (Exception e) {
            knLogger.error(methodName, "Unexpected Exception occured while updating group broadcaster  - ",
                    new KnException(KnErrorCodes.BOEntity.INTERNAL_ERROR, e.getMessage(), e));
            populate(respDTO, e);
        }
        return respDTO;
    }

    @Override
    /**
     * This method is used to get the Linked corporates groupo List
     * The method will return all the groups present for the group mdns present in the corporate.
     */
    public KnLinkedGroupInfoRespDTO getPoCLinkedGroupList(KnIPLinkedGroupInfoDTO pocGrpListDTO, KnPersisterTxn persisterTxn) {
        String methodName = "getPoCLinkedGroupList(KnIPPocLinkedGroupListDTO, KnPersisterTxn)";
        KnLinkedGroupInfoRespDTO respDTO = new KnLinkedGroupInfoRespDTO();
        try {

            int corpId = pocGrpListDTO.getCorpId();
            Object hookResp = null;
            //Step:
            //get the Corp profile details from cache
            knLogger.debug(methodName, "Fetch the corpProfile profile if cached or fetch from the DB the details");
            KnCorpProfileDTO corpProfile = commonInfoUtil.getProfileDetails(String.valueOf(corpId), CORP_PROFILE, false, persisterTxn);
            knLogger.debug(methodName, "Retrieved Corp Profile details - ", corpProfile);
            String xdmsHome = corpProfile.getXdmsHome();
            List<String> mdnList = new ArrayList<String>();

            //Invoking custom hook
            KnCorpHookRespDTO responseDTO = new KnCorpHookRespDTO();
            Map<String, Object> customParams = pocGrpListDTO.getCustomParamMap();
            if (pocGrpListDTO.getHierarchyType() == HIERARCHY_TYPE.HIERARCHY) {
                customParams.put(LINKED_CORPORATE_ETAG, corpProfile.getCorpMasterListEtag());
                customParams.put(PERSISTER_TXN, persisterTxn);
                customParams.put(PTT_SERVER_ID, xdmsHome);
                pocGrpListDTO.setCustomParamMap(customParams);
                KnCorpHookIPDTO hookIPDTO = new KnCorpHookIPDTO();
                hookIPDTO.setAction(KnActions.ACTIONS.GET_BAN_FAN_MDN_LIST);
                hookIPDTO.setData(pocGrpListDTO);
                KnProcessInvokerImpl processInvoker = KnProcessInvokerImpl.getInstance();
                hookResp = processInvoker.invokeHook(CUSTOM_CORP_USER_HOOK, hookIPDTO);
                if (hookResp instanceof KnCorpHookRespDTO) {
                    responseDTO = (KnCorpHookRespDTO) hookResp;
                    if (responseDTO.getData() != null && responseDTO.getData() instanceof List) {
                        mdnList = (List<String>) responseDTO.getData();
                        if (com.kodiak.xdms.server.common.resources.KnConstants.RESPONSE_STATUS.FAILURE.value() == responseDTO.getStatus()) {
                            knLogger.error(methodName, "Returning Failure response");
                            populateXdmResponseFroomHook(responseDTO, respDTO);
                            return respDTO;
                        }
                    }
                }
            }
            Collection<Integer> sgClientTyes = new ArrayList<>();
            sgClientTyes.add(GROUPMDN.value());
            sgClientTyes.add(SUBSCR_CLIENT_TYPE.SGMDNPATCH.value());
            //get the corporates mdn list from db
            if (pocGrpListDTO.getHierarchyType() == HIERARCHY_TYPE.NON_HIERARCHY) {
                mdnList = new ArrayList<String>(contactInfoUtil.getMdnsSpecificToClients(corpId, sgClientTyes, xdmsHome, true, persisterTxn));
            }
            KnPoCLinkedGroupListPersistDTO poCLinkedGroupListPersistDTO = new KnPoCLinkedGroupListPersistDTO();
            poCLinkedGroupListPersistDTO.setInputDTO(pocGrpListDTO);
            //check if the poc nni intefcae is enabled.
            //check if the corporate is linked or not from the DG.CORP_GW_LINKED_ACCOUNTINFO only the linked then this api wil be used.
            KnCorpGWLinkedAccountInfoDTO linkedAccInfo = commonInfoUtil.getCorporateLinkedAccountInfo(corpProfile.getLinkedGwKey(), xdmsHome, true, persisterTxn);
            poCLinkedGroupListPersistDTO.setAccountId(linkedAccInfo.getAccountId());
            poCLinkedGroupListPersistDTO.setGwEtag(linkedAccInfo.getGwEtag());

            knLogger.debug(methodName, "Invoking ValidationFW. DTO - ", poCLinkedGroupListPersistDTO);
            //performs business validation
            validatorFW.validate(poCLinkedGroupListPersistDTO);
            knLogger.debug(methodName, "Validation completed Successfully.");

            //get the group ids for the mdn list i.e for the ban /fan subscribers list
            Map<Integer, List<String>> subscGroupIdMap = groupInfoUtil.getSubscriberGroupIds(mdnList, xdmsHome, true, persisterTxn);
            Set<Integer> groupIds = subscGroupIdMap.keySet();
            List<Integer> grpIds = new ArrayList<Integer>(groupIds);
            ArrayList<KnCorpGroupDTO> groupDetails = groupInfoUtil.getGroupBasicInfoList(grpIds, xdmsHome, true, persisterTxn);
            List<KnLinkedGroupInfo> linkedGroupList = new ArrayList<KnLinkedGroupInfo>();
            groupDetails.forEach(groupInfo -> {
                if (subscGroupIdMap.get(groupInfo.getGroupId()) != null) {
                    subscGroupIdMap.get(groupInfo.getGroupId()).forEach(grpMdn -> {
                        KnLinkedGroupInfo corpGroupDTO = new KnLinkedGroupInfo();
                        corpGroupDTO.setGroupId(groupInfo.getGroupId());
                        corpGroupDTO.setGroupName(groupInfo.getGroupDisplayName());
                        corpGroupDTO.setGroupType(groupInfo.getGroupType());
                        corpGroupDTO.setGroupMdn(grpMdn);
                        if (groupInfo.getGroupCreatedBy() != CREATED_BY.ABDG.value()) linkedGroupList.add(corpGroupDTO);
                    });
                }
            });
            knLogger.debug(methodName, "linkedGroupList.", linkedGroupList);
            respDTO.setLinkedGroupList(linkedGroupList);
            populate(respDTO);
        } catch (KnCorpBOException e) {
            knLogger.error(methodName, "KnCorpBOException occured while updating group broadcaster - ", e);
            populate(respDTO, e);
        } catch (Exception e) {
            knLogger.error(methodName, "Unexpected Exception occured while updating group broadcaster  - ",
                    new KnException(KnErrorCodes.BOEntity.INTERNAL_ERROR, e.getMessage(), e));
            populate(respDTO, e);
        }

        return respDTO;
    }

    /**
     * Method to remove requestMDN from all the groups private list.
     * 1. Validate if corporate exist.
     * 2. Validate if request MDN is part of corporation (internal)
     * 3. Validate the masterListEtag--CustomParam:(Warning Message)
     * If validation successful:
     * 4. Determine the groups for the requestMDN is part of from the group memberList table for the corporate.
     * 5. Get the member distributed to these group.
     * 6. Get the private list Ids for the groups.
     * 7. Delete the MDN from from these sublist.
     * 5. Delete the RequestMDN from groupDistribution, groupMemberList Table.
     * 6. if the group becomes empty we will have to remove the group.
     * 7. update the etag of the group document.
     * 8. update the etag of the directory document.
     * 9. update the count using the store procedure.
     * 10. Notification will happen at the end of the operation for the requestMDN.
     *
     * @param subscriberInfoDTO
     * @param persisterTxn
     * @return
     */
    @Override
    public KnCorpResponseDTO removeSubscribersAllGroups(KnIPCorpContactDTO subscriberInfoDTO, KnPersisterTxn persisterTxn) {
        String methodName = "removeSubscribersAllGroups(subscriberInfoDTO, persisterTxn)";
        knLogger.info(methodName, "ENTRY : Input DTO Passed - ", subscriberInfoDTO);
        //Step: creating Response DTO object
        KnCorpResponseDTO respDTO = new KnCorpResponseDTO();
        KnCorpInOutParamDTO corpInOutParamDTO = new KnCorpInOutParamDTO();
        try {
            int corpId = subscriberInfoDTO.getCorpId();
            //Step:get the Corp profile details from cache
            knLogger.debug(methodName, "Fetch the corpProfile profile if cached or fetch from the DB the details");
            KnCorpProfileDTO corpProfile = commonInfoUtil.getProfileDetails(String.valueOf(corpId), CORP_PROFILE, false, persisterTxn);
            knLogger.info(methodName, "Corporate Profile - ", corpProfile);
            //Step: IDTYPEget the Subscriber profile details from cache
            knLogger.debug(methodName, "Fetch the subscProfile profile if cached or fetch from the DB the details");
            KnSubsProfileDTO subscProfile = commonInfoUtil.getProfileDetails(subscriberInfoDTO.getMdn(),
                    PUBLIC_PROFILE, false, persisterTxn);
            knLogger.info(methodName, "subscProfile Profile - ", subscProfile);
            //use the xdms home pttServerId from Corp profile
            String xdmsHomePttId = corpProfile.getXdmsHome();
            //Invoking custom hook
            knLogger.debug(methodName, "Custom Call");
            KnCorpHookRespDTO responseDTO = new KnCorpHookRespDTO();
            Map<String, Object> customParams = subscriberInfoDTO.getCustomParamMap();
            if (subscriberInfoDTO.getHierarchyType() == HIERARCHY_TYPE.HIERARCHY) {
                contactInfoUtil.checkValidHierarchySubs(Collections.singletonList(subscriberInfoDTO.getMdn()), customParams, xdmsHomePttId, persisterTxn);
                customParams.put(CURRENT_MASTER_LIST_ETAG, corpProfile.getCorpMasterListEtag());
                customParams.put(PERSISTER_TXN, persisterTxn);
                customParams.put(PTT_SERVER_ID, xdmsHomePttId);
                knLogger.debug(methodName, "customParams after the change - ", customParams);
                subscriberInfoDTO.setCustomParamMap(customParams);
                KnCorpHookIPDTO hookIPDTO = new KnCorpHookIPDTO();
                hookIPDTO.setAction(KnActions.ACTIONS.REMOVE_SUBSCRIBERS_ALL_GROUPS);
                hookIPDTO.setData(subscriberInfoDTO);
                KnProcessInvokerImpl processInvoker = KnProcessInvokerImpl.getInstance();
                knLogger.debug(methodName, "Call before Hook.Process Invoker - ", processInvoker);
                Object hookResp = processInvoker.invokeHook(CUSTOM_CORP_USER_HOOK, hookIPDTO);
                if (hookResp != null && hookResp instanceof KnCorpHookRespDTO) {
                    responseDTO = (KnCorpHookRespDTO) hookResp;
                    knLogger.debug(methodName, "Call After Hook");
                    if (com.kodiak.xdms.server.common.resources.KnConstants.RESPONSE_STATUS.FAILURE.value() == responseDTO.getStatus()) {
                        knLogger.error(methodName, "Returning Failure response");
                        populateXdmResponseFroomHook(responseDTO, respDTO);
                        return respDTO;
                    }
                }
            }

            String mdn = subscriberInfoDTO.getMdn();
            LinkedList<String> mdnList = new LinkedList<String>();
            mdnList.add(subscriberInfoDTO.getMdn());
            KnContactDetailsPersistDTO valPersistDTO = new KnContactDetailsPersistDTO();
            valPersistDTO.setInputDTO(subscriberInfoDTO);
            KnCorpSubscriberDTO subsDTO = new KnCorpSubscriberDTO();
            subsDTO.setMdn(mdn);
            subsDTO.setCorpId(corpId);
            valPersistDTO.setSubscDto(subsDTO);
            valPersistDTO.setSubsCorpId(subscProfile.getCorpId());
            knLogger.debug(methodName, "After setting of the validation framework object ", "valPersistDTO - ", valPersistDTO);
            knLogger.debug(methodName, "Invoking Validation FW - ", valPersistDTO);
            validatorFW.validate(valPersistDTO);
            knLogger.info(methodName, "Validation completed successfully");
            //Determine the groups for the requestMDN is part of from the group memberList table for the corporate.
            Map<Integer, List<String>> subscGroupIdMap = groupInfoUtil.getSubscriberGroupIds(mdnList, xdmsHomePttId, false, persisterTxn);
            if (subscGroupIdMap != null && !subscGroupIdMap.isEmpty()) {
                Set<Integer> groupIds = subscGroupIdMap.keySet();
                //GroupId filter for ABDG Group:
                Collection<Integer> abdgGroupIds = groupInfoUtil.getCorpGroupCountIntf(corpId, CREATED_BY.ABDG.value(), xdmsHomePttId, persisterTxn);
                for (Integer grp : abdgGroupIds) {
                    groupIds.remove(grp);
                }
                Collection<Integer> grpIds = new ArrayList<Integer>(groupIds);
                knLogger.debug(methodName, "grpIds - ", grpIds);
                // Get the member distributed to these group
                Map<Integer, Collection<String>> groupDistList = groupInfoUtil.getGroupSubscriberDistList(grpIds, xdmsHomePttId, persisterTxn);
                knLogger.debug(methodName, "groupDistList - ", KnGDPRTemplate.mapMdnAsValue(groupDistList));
                //Get the private list Ids for the groups.
                ArrayList<Integer> privateGroupSublistList = groupInfoUtil.getAllGroupsPrivateList(grpIds, xdmsHomePttId, persisterTxn);
                knLogger.debug(methodName, "privateGroupSublistList - ", privateGroupSublistList);
                Set<Integer> CorpListIdOnlyPushedViaPrivateGroupList = sublistInfoUtil.SelectCorpListIdOnlyPushedViaPrivateGroupList(privateGroupSublistList, mdn, xdmsHomePttId, persisterTxn);
                //Removing the mdn from the DG.CORPLISTMEMBER table for all the GroupIds..
                sublistInfoUtil.deleteSublistMembersForRequestMDN(privateGroupSublistList, mdn, xdmsHomePttId, persisterTxn);
                // Broadcaster Group
                Set<Integer> bgGroupList = groupInfoUtil.getGroupSupervisorList(groupIds, xdmsHomePttId, persisterTxn);
                knLogger.debug(methodName, "bgGroupList - ", bgGroupList);
                //Delete the requestMDN from the groupMemberList table for the groupIds and delete the member from the distribution table.
                //The empty group have to deleted as well.
                LinkedHashMap<Integer, LinkedList<Integer>> delGroupMemStatus = new LinkedHashMap<Integer, LinkedList<Integer>>();
                LinkedHashMap<Integer, LinkedList<String>> actualMdnToBeDeletedFromGroupMap = new LinkedHashMap<Integer, LinkedList<String>>();
                Map<Integer, Collection<String>> removedLocWatcherMap = new HashMap<>();
                HashSet<String> modifiedMDNList = new HashSet<>();
                Set<Integer> grpIdsForEtagChange = new HashSet<>();
                Collection<String> disabledOdlMember = new HashSet<>();
                Map<String, KnOPDirChgDTO> etagMap = new HashMap<String, KnOPDirChgDTO>();
                Map<Integer, Integer> groupMapListForProfileUpdate = new HashMap<>();
                if (groupDistList != null && !groupDistList.isEmpty()) {
                    for (Entry<Integer, Collection<String>> entry : groupDistList.entrySet()) {
                        Integer groupId = entry.getKey();
                        groupMapListForProfileUpdate.put(groupId, CB_MAPPING.ETAG_CHANGE.value());
                        Collection<String> memberMdnList = entry.getValue();
                        for (String memberMDN : memberMdnList) {
                            LinkedList<String> mdnTobeDeleted = new LinkedList<>();
                            if (memberMDN.equals(mdn)) {
                                mdnTobeDeleted.add(memberMDN);
                                actualMdnToBeDeletedFromGroupMap.put(groupId, mdnTobeDeleted);
                            }
                            modifiedMDNList.add(memberMDN);
                        }
                    }

                    if (bgGroupList != null && !bgGroupList.isEmpty()) {
                        for (int bgGroup : bgGroupList) {
                            actualMdnToBeDeletedFromGroupMap.put(bgGroup, mdnList);
                            grpIdsForEtagChange.add(bgGroup);
                        }
                    }
                    Collection<String> removedLocWatcher = new ArrayList<>();
                    knLogger.debug(methodName, "actualMdnToBeDeletedFromGroupMap - ", KnGDPRTemplate.mapMdnAsLinkedValue(actualMdnToBeDeletedFromGroupMap));
                    Collection<KnCorpGroupMemberDTO> grpMemberDetails = groupInfoUtil.getCorpGroupMemberForLocWatcher(actualMdnToBeDeletedFromGroupMap.keySet(), xdmsHomePttId, persisterTxn);
                    for (KnCorpGroupMemberDTO grpMem : grpMemberDetails) {
                        disabledOdlMember.add(grpMem.getMdn());
                        if (grpMem.getLocWatcher() == ENABLED) {
                            Collection<String> removedLocWatchers = null;
                            if (removedLocWatcherMap.get(grpMem.getGroupId()) != null) {
                                removedLocWatchers = removedLocWatcherMap.get(grpMem.getGroupId());
                                removedLocWatchers.add(grpMem.getMdn());
                            } else {
                                removedLocWatchers = new ArrayList<>();
                                removedLocWatchers.add(grpMem.getMdn());
                                removedLocWatcherMap.put(grpMem.getGroupId(), removedLocWatchers);
                            }
                        }
                    }
                    respDTO.setRemovedLocWatcherList(removedLocWatcher);
                    disabledOdlMember.add(subscriberInfoDTO.getMdn());
                    knLogger.info(methodName, "XX grpMemberDetails - ", grpMemberDetails);
                    delGroupMemStatus = groupInfoUtil.deleteCorpGroupMemberList(actualMdnToBeDeletedFromGroupMap, xdmsHomePttId, persisterTxn);
                    knLogger.debug(methodName, "delGroupMemStatus - ", delGroupMemStatus);
                }
                //Group:
                Map<String, Collection<String>> groupFailurePairingMap = new HashMap<>();
                Collection<KnCorpAddlTGInfoDTO> delAddlTGList = new ArrayList<>();
                Map<Integer, Collection<KnCorpAddlTGInfoDTO>> existingAddlTGList = new HashMap<>();
                Collection<KnCorpAddlTGInfoDTO> subsAddlTGList = groupInfoUtil.getSubsAddlDetails(groupIds, xdmsHomePttId, persisterTxn);
                // Additional Talk Group:
                for (KnCorpAddlTGInfoDTO addlTg : subsAddlTGList) {
                    Collection<KnCorpAddlTGInfoDTO> existAddl = null;
                    if (existingAddlTGList.get(addlTg.getGroupId()) != null) {
                        existAddl = existingAddlTGList.get(addlTg.getGroupId());
                        existAddl.add(addlTg);
                    } else {
                        existAddl = new ArrayList<>();
                        existAddl.add(addlTg);
                        existingAddlTGList.put(addlTg.getGroupId(), existAddl);
                    }
                }
                knLogger.debug(methodName, "existingAddlTGList - Group", existingAddlTGList);
                Map<String, Collection<String>> actualDeletedGroupMemberMap = getDeletedMembers(actualMdnToBeDeletedFromGroupMap, delGroupMemStatus);
                //LocWatcher: Removed
                Collection<String> finalLocWatcherRemoved = new ArrayList<>();
                actualDeletedGroupMemberMap.forEach((grpId, deletedMem) -> {
                    Collection<String> actualLocWatcher = removedLocWatcherMap.get(Integer.parseInt(grpId));
                    if (actualLocWatcher != null)
                        finalLocWatcherRemoved.addAll(actualLocWatcher.stream().filter(deletedMem::contains).collect(Collectors.toList()));
                });
                respDTO.setRemovedLocWatcherList(finalLocWatcherRemoved);
                if (actualDeletedGroupMemberMap != null && !actualDeletedGroupMemberMap.isEmpty()) {
                    Map<String, Collection<String>> emergDestUserMap = corpSubsProvInfoUtil.getEmergDestUserMap(actualDeletedGroupMemberMap.keySet(),
                            xdmsHomePttId, persisterTxn);
                    knLogger.debug(methodName, "emergDestUserMap-- ", KnGDPRTemplate.mapKeyValueListMdn(emergDestUserMap));
                    if (emergDestUserMap != null && !emergDestUserMap.isEmpty()) {
                        emergDestUserMap.forEach((emergDest, emergUser) -> {
                            Collection<String> removedGroupMember = actualDeletedGroupMemberMap.get(emergDest);
                            Collection<String> mappedDestination = emergUser.stream().filter(removedGroupMember::contains).collect(Collectors.toList());
                            if (mappedDestination != null && !mappedDestination.isEmpty())
                                groupFailurePairingMap.put(emergDest, mappedDestination);
                        });
                    }
                    knLogger.debug(methodName, "groupFailurePairingMap-- ", KnGDPRTemplate.mapKeyValueListMdn(groupFailurePairingMap));
                    if (!groupFailurePairingMap.isEmpty()) {
                        knLogger.error(methodName, "Emergency Destination Mapping Exists - Group");
                        throw new KnCorpBOValidationException(KnErrorCodes.Validator.EMERGENCY_DESTINATION_MAPPING_EXISTS_FOR_GROUP,
                                "Emergency Destination Mapping Exists for Group--", CORP_GROUP_MANAGER,
                                REMOVE_SUBSCRIBERS_ALL_GROUPS, "", groupFailurePairingMap.keySet().toString(), "");
                    }
                }
                Collection<KnCorpSubscriberDTO> removedMembersList = contactInfoUtil.getSubscribersInfo(mdnList, xdmsHomePttId, persisterTxn);
                Collection<KnCorpSubscriberDTO> uniqueMdnToBeDeletedToGroup =
                        contactInfoUtil.getDistinctMembers(removedMembersList, groupIds, corpId, xdmsHomePttId, persisterTxn);
                //Filter out the actually added members and deleted members as same member can be already present in the group via sublist etc
                Map<Integer, Map<String, Collection<String>>> memberDetailsList = commonInfoUtil.filterAddedRemovedMembers(groupDistList,
                        null, uniqueMdnToBeDeletedToGroup, corpId);
                knLogger.debug(methodName, "memberDetailsList - ", KnGDPRTemplate.mapMdnOfMap(memberDetailsList));
                //DAO calls to delete from the dg.corpgroupdistinfo table
                for (int grpId : groupIds) {
                    Collection<String> deletedMembers = (memberDetailsList.get(grpId)).get(KnPersisterConstants.DELTED_MEMBERS);
                    if (deletedMembers != null && !deletedMembers.isEmpty()) {
                        groupInfoUtil.deleteFrmCorpGroupDistInfo(memberDetailsList, xdmsHomePttId, persisterTxn);
                    }
                }
                //Deleting from group member list
                // groupInfoUtil.deleteGrpMemList(mdnList, xdmsHomePttId, persisterTxn);

                Collection<Integer> groupSublistId = new ArrayList<>(privateGroupSublistList);
                knLogger.debug(methodName, "groupSublistId - ", groupSublistId);
                sublistInfoUtil.updateSublistsSubscribersContactCount(groupSublistId, corpProfile.getMaxContactsPerSubsc(),
                        corpProfile.getMaxMemPerCorpGroup(), corpProfile.getMaxMembersPerDispatchGroup(), xdmsHomePttId, persisterTxn, corpProfile.getMaxMemPerBCGrp());


                Map<Integer, Collection<String>> groupDistListAfterModify = new HashMap<Integer, Collection<String>>();
                //This variable is to hold the deleted members in the deleted groups (less than 1 member group Ids)
                Map<Integer, Collection<String>> deletedMembersMap = new HashMap<Integer, Collection<String>>();
                groupDistListAfterModify = groupInfoUtil.getGroupSubscriberDistList(grpIds, xdmsHomePttId, persisterTxn);

                //This variable is to hold the actilly deleted members from group member list table for each group id.
                Map<Integer, Collection<String>> actualDeletedMembers = commonInfoUtil.filterDeletedGroupMembers(groupDistListAfterModify, groupDistList);
                knLogger.debug("actualDeletedMembers-,", KnGDPRTemplate.mapMdnAsValue(actualDeletedMembers));

                for (Entry<Integer, Collection<String>> grpStatusEntry : actualDeletedMembers.entrySet()) {
                    Integer groupId = grpStatusEntry.getKey();
                    Collection<String> memberMdnList = grpStatusEntry.getValue();
                    knLogger.debug(methodName, "memberMdnListTTT - ", KnGDPRTemplate.mdnList(memberMdnList));
                    if (!grpStatusEntry.getValue().isEmpty()) {
                        grpIdsForEtagChange.add(groupId);
                    }
                    knLogger.debug(methodName, "grpIdsForEtagChange - ", grpIdsForEtagChange);

                }

                Map<Integer, Integer> groupEtagMap = groupInfoUtil.updateGroupListEtag(grpIdsForEtagChange, xdmsHomePttId, persisterTxn);
                knLogger.info(methodName, "groupEtagMap - ", groupEtagMap);
                // update the etag of PrivateList of input Subscriber.
                knLogger.debug(methodName, "Updating the Etag of PrivateList of the subscriber");

                knLogger.debug(methodName, "SelectCorpListIdOnlyPushedViaPrivateGroupList - ", CorpListIdOnlyPushedViaPrivateGroupList);
                sublistInfoUtil.fetchAndUpdateSublistEtag(CorpListIdOnlyPushedViaPrivateGroupList, xdmsHomePttId, persisterTxn);

                // Updating the Impacted tables for input MDN.
                //etagMap = contactInfoUtil.updateSubscribersDirectory(modifiedMDNList, etagMap, xdmsHomePttId, persisterTxn);

                //Determine the deleted and the modified groups
                Map<String, HashMap<Integer, String>> groupListStatus = groupInfoUtil.getGroupListStatus(grpIds, xdmsHomePttId, persisterTxn);
                knLogger.debug("groupListStatus-,", groupListStatus);
                // Delete corp groups with < 1 members
                Set<Integer> delGroupIdList = new HashSet<>();
                if (groupListStatus.get(DELETED) != null && groupListStatus.get(DELETED).keySet() != null) {
                    delGroupIdList = groupListStatus.get(DELETED).keySet();
                    if (delGroupIdList != null && !delGroupIdList.isEmpty()) {
                        for (Integer grpId : delGroupIdList) {
                            Collection<String> delMembersList = groupDistListAfterModify.get(grpId);
                            deletedMembersMap.put(grpId, delMembersList);
                            groupMapListForProfileUpdate.put(grpId, CB_MAPPING.NEED_TO_REMOVE.value());
                            //for the contact added to update the directory
                            //contactMemSet.addAll(delMembersList);
                        }
                        for (Integer groupId : delGroupIdList) {
                            if (existingAddlTGList.get(groupId) != null)
                                delAddlTGList.addAll(existingAddlTGList.get(groupId));
                            groupDistListAfterModify.remove(groupId);
                        }
                    }
                }
                Map<Integer, KnCorpGroupDTO> groupDetailsMap = groupInfoUtil.getGroupBasicDetailsMap(grpIds, xdmsHomePttId, persisterTxn);
                knLogger.debug(methodName, "groupDetailsMap - ", groupDetailsMap);
                if (subsAddlTGList != null && !subsAddlTGList.isEmpty()) {
                    Map<Integer, Integer> groupCorpIdMap = new HashMap<>();
                    groupCorpIdMap = groupInfoUtil.getGroupCorpIdMap((List<KnCorpAddlTGInfoDTO>) subsAddlTGList, xdmsHomePttId, persisterTxn);
                    delAddlTGList.addAll(subsAddlTGList.stream().filter(addlMem -> (actualDeletedGroupMemberMap
                            .get(String.valueOf(addlMem.getGroupId())) != null) && actualDeletedGroupMemberMap
                            .get(String.valueOf(addlMem.getGroupId())).contains(addlMem.getMdn())).collect(Collectors.toList()));
                    Collection<String> mdnForAddlTg = subsAddlTGList.stream().map(KnCorpAddlTGInfoDTO::getMdn).distinct().collect(Collectors.toList());
                    groupInfoUtil.deleteSubsAddlTGList(delAddlTGList, xdmsHomePttId, persisterTxn);
                    subsAddlTGList.removeAll(delAddlTGList);
                    subsAddlTGList.forEach(subsAddl -> {
                        subsAddl.setGroupMemCount(groupDetailsMap.get(subsAddl.getGroupId()).getGroupMemCount());
                    });
                    etagMap = groupInfoUtil.updateAddlTalkGroupImpactedTables(xdmsHomePttId, mdnForAddlTg, persisterTxn, etagMap);
                    knLogger.debug(methodName, "etagMap AddlTG - ", KnGDPRTemplate.mapKeyMdn(etagMap));
                    knLogger.debug(methodName, "groupCorpId - ", groupCorpIdMap);
                    if (!groupCorpIdMap.isEmpty()) {
                        etagMap = formXcapAddlTGDiffNotification(etagMap, null,
                                subsAddlTGList, delAddlTGList, groupCorpIdMap);
                        knLogger.debug(methodName, "etagMap AddlTG -diff - ", KnGDPRTemplate.mapKeyMdn(etagMap));
                    }
                }
                //Deleting Groups.
                if (!delGroupIdList.isEmpty())
                    groupInfoUtil.deleteAllGroups(delGroupIdList, xdmsHomePttId, corpInOutParamDTO, persisterTxn);
                //Updating the group member count
                sublistInfoUtil.updateSublistsSubscribersContactCount(groupSublistId, corpProfile.getMaxContactsPerSubsc(),
                        corpProfile.getMaxMemPerCorpGroup(), corpProfile.getMaxMembersPerDispatchGroup(), xdmsHomePttId, persisterTxn, corpProfile.getMaxMemPerBCGrp());
                     /*
                        Get the group member count and group type for the groupIds and set these values into etag Map
                     */

                knLogger.debug(methodName, "actualDeletedMembers - ", KnGDPRTemplate.mapMdnAsValue(actualDeletedMembers));
                if (!groupEtagMap.isEmpty()) {
                    if (!actualDeletedMembers.isEmpty()) {
                        etagMap = commonInfoUtil.formSubscriberNotification(actualDeletedMembers, groupEtagMap,
                                com.kodiak.xdms.server.common.resources.KnConstants.DOC_CHANGE_TYPE.REMOVE.value(), etagMap, groupDetailsMap, null);
                    }

                    knLogger.debug(methodName, "deletedMembersMap - ", KnGDPRTemplate.mapMdnAsValue(deletedMembersMap));
                    if (!deletedMembersMap.isEmpty()) {
                        etagMap = commonInfoUtil.formSubscriberNotification(deletedMembersMap, groupEtagMap,
                                com.kodiak.xdms.server.common.resources.KnConstants.DOC_CHANGE_TYPE.REMOVE.value(), etagMap, groupDetailsMap, null);
                    }

                    knLogger.debug(methodName, "groupDistListAfterModify - ", KnGDPRTemplate.mapMdnAsValue(groupDistListAfterModify));
                    if (!groupDistListAfterModify.isEmpty()) {
                        etagMap = commonInfoUtil.formSubscriberNotification(groupDistListAfterModify, groupEtagMap,
                                com.kodiak.xdms.server.common.resources.KnConstants.DOC_CHANGE_TYPE.REPLACE.value(), etagMap, groupDetailsMap, null);
                    }

                    if (!CorpListIdOnlyPushedViaPrivateGroupList.isEmpty()) {
                        etagMap = contactInfoUtil.updateDistinctSubcribersDirectory(modifiedMDNList, grpIds, etagMap, xdmsHomePttId, persisterTxn);
                    }
                }
                knLogger.debug(methodName, "etagMap1 - ", KnGDPRTemplate.mapKeyMdn(etagMap));
                // Preparing the Notification related with this API.
                Map<Integer, Collection<String>> groupDistMap = groupInfoUtil.getGroupSubscriberDistList(grpIds, xdmsHomePttId, persisterTxn);
                etagMap = formXcapDiffNotification(etagMap, null, null,
                        null, null, actualMdnToBeDeletedFromGroupMap, null,
                        null, groupDistMap, null, delGroupMemStatus, null);
                knLogger.debug(methodName, "etagMap2 - ", KnGDPRTemplate.mapKeyMdn(etagMap));

                Map<String, Collection<KnDocChangeListDTO>> profileMdnEtagMap = corpUserProfileUtil.updateImpactedCBDocuments(String.valueOf(corpId), null,
                        groupMapListForProfileUpdate, null, xdmsHomePttId, persisterTxn);
                respDTO.setProfileMdnEtagMap(profileMdnEtagMap);
                if(profileMdnEtagMap != null && !profileMdnEtagMap.isEmpty()){
                    respDTO.setMcsXcapRootUriMap(genInfoUtil.getXCAPRootURI(new ArrayList<>(profileMdnEtagMap.keySet()), persisterTxn, true));
                }
                //populate Success response
                respDTO.setChangeLogMap(etagMap);

                knLogger.debug(methodName, "Populate the liEventList Data");
                Map<Integer, String> groupNameMap = new HashMap<Integer, String>();
                if (groupListStatus.get(DELETED) != null) {
                    groupNameMap.putAll(groupListStatus.get(DELETED));
                } else if (groupListStatus.get(MODIFIED) != null) {
                    groupNameMap.putAll(groupListStatus.get(MODIFIED));
                }

                LinkedList<KnLIEventDTO> liEventList = populateLIData(etagMap
                        , xdmsHomePttId, groupNameMap, null, groupDistList,persisterTxn);
                knLogger.debug(methodName, "liEventList - " + liEventList);
                respDTO.setDisabledDispatchMemList(disabledOdlMember);
                respDTO.setLiEventList(liEventList);
                respDTO.setEtag(String.valueOf(subscriberInfoDTO.getEtag()));
                respDTO.setMdnCorpId(subscProfile.getCorpId());
            }
            respDTO.setMdnCorpId(corpId);
            populate(respDTO);
            if (responseDTO.getFailedDataList() != null && !responseDTO.getFailedDataList().isEmpty()) {
                respDTO.setFailedDataList(responseDTO.getFailedDataList());
            }

        } catch (KnValidationException ve) {
            knLogger.error(methodName, "KnValidationException occured while removeSubscribersAllGroups - ", ve);
            populate(respDTO, ve);

        } catch (KnCorpBOException be) {
            //corp profile does not exists
            knLogger.error(methodName, "KnCorpBOException occured while removeSubscribersAllGroups - ", be);
            populate(respDTO, be);

        } catch (Exception e) {
            knLogger.error(methodName, "Unexpected exception occured while removeSubscribersAllGroups - ",
                    new KnException(KnErrorCodes.BOEntity.INTERNAL_ERROR, e.getMessage(), e));
            populate(respDTO, e);

        }
        return respDTO;
    }

    private List<String> getDeletedBroadcasters(List<KnCorpSubscriberDTO> finalGroupMemList, List<String> finalBroadcasters) {
        List<String> deletedBroadcasters = new ArrayList<>();
        for (String mdn : finalBroadcasters) {
            KnCorpSubscriberDTO subscriberDTO = new KnCorpSubscriberDTO();
            subscriberDTO.setMdn(mdn);
            if (!finalGroupMemList.contains(subscriberDTO)) {
                deletedBroadcasters.add(mdn);
            }
        }
        finalBroadcasters.removeAll(deletedBroadcasters);
        return deletedBroadcasters;
    }


    public KnCorpGroupListRespDTO getTpSubscriberGroupList(KnIPCorpContactDTO corpContactDTO, KnPersisterTxn persisterTxn) {
        String methodName = "getTpSubscriberGroupList(KnIPCorpContactDTO, KnPersisterTxn)";
        knLogger.info(methodName, "ENTRY : Input DTO Passed - ", corpContactDTO.getMdn());
        KnCorpGroupListRespDTO respDto = new KnCorpGroupListRespDTO();
        try {
            String mdn = corpContactDTO.getMdn();
            knLogger.debug(methodName, "Fetch the SubsProfile profile if cached or fetch from the DB the details");
            KnSubsProfileDTO subscProfile = commonInfoUtil.getProfileDetails(mdn, PUBLIC_PROFILE,
                    false, persisterTxn);
            knLogger.debug(methodName, "Retrieved Subs Profile details - ", subscProfile);
            String xdmsHome = subscProfile.getXdmsHome();
            Collection<KnCorpGroupInfoPersistDTO> subsGroupList = groupInfoUtil.selectTpGroupList(corpContactDTO.getMdn(),
                    subscProfile.getCorpId(), xdmsHome, true, persisterTxn);
            Collection<KnCorpGroupInfoDTO> groupInfoList = new ArrayList<KnCorpGroupInfoDTO>(subsGroupList.size());
            groupInfoList.addAll(subsGroupList);
            respDto.setGroupList(groupInfoList);
            populate(respDto);
        } catch (KnCorpBOException e) {
            knLogger.error(methodName, "KnCorpBOException occured while retrieving Group List - ", e);
            populate(respDto, e);
        } catch (Exception e) {
            knLogger.error(methodName, "Unexpected exception occured while retrieving Group List - ",
                    new KnException(KnErrorCodes.BOEntity.INTERNAL_ERROR, e.getMessage(), e));
            populate(respDto, e);
        }
        knLogger.debug(methodName, "EXIT : GroupList Response - ", respDto);
        return respDto;
    }

    public KnCorpGroupInfoRespDTO getTpSubsCorpGroupDetails(KnIPCorpGroupDTO groupInfoDTO, KnPersisterTxn persisterTxn) {
        String methodName = "getTpSubsCorpGroupDetails(KnIPCorpGroupDTO, KnPersisterTxn)";
        knLogger.info(methodName, "ENTRY : Input DTO Passed with corpId, mdn- ", groupInfoDTO.getCorpId(), " ", groupInfoDTO.getOwner());
        KnCorpGroupInfoRespDTO respDTO = new KnCorpGroupInfoRespDTO();
        try {
            knLogger.debug(methodName, "Fetch the subscribers profile if cached or fetch from the DB the details");
            String mdn = groupInfoDTO.getTpGroupOwner();
            KnSubsProfileDTO subscProfile = commonInfoUtil.getProfileDetails(mdn, PUBLIC_PROFILE, false, persisterTxn);
            String xdmsHome = subscProfile.getXdmsHome();
            int corpId = subscProfile.getCorpId();
            int groupId = groupInfoUtil.selectTpGroup(corpId, groupInfoDTO.getGroupDisplayName(), xdmsHome, true, persisterTxn);
            knLogger.debug(methodName, "groupId--", groupId);
            KnCorpGroupDTO groupBasicInfo = groupInfoUtil.getGroupBasicInfo(groupId, groupInfoDTO.getClientType(), xdmsHome, true, persisterTxn);
            Map<String, KnCorpGroupMemberDTO> grpMemberMap = groupInfoUtil.getGroupMembersList(groupId, xdmsHome, true, persisterTxn);
            List<String> allMemberList = new ArrayList<String>(grpMemberMap.keySet());
            Map<String, KnSubscriberDTO> groupMemberNameMap = contactInfoUtil.getSubscribersNameForCorp(allMemberList, corpId, xdmsHome, true, persisterTxn);
            List<String> extMdnList = contactInfoUtil.filterInternalExternalContactsForSubc(groupMemberNameMap.keySet(), allMemberList);
            Collection<KnCorpGroupMemberDTO> groupMembers = new ArrayList<KnCorpGroupMemberDTO>();
            int memberCount = grpMemberMap.keySet().size();
            Map<String, KnSubscriberDTO> extContNameMap = contactInfoUtil.getExtContName(extMdnList, corpId, xdmsHome, true, persisterTxn);
            for (String memMdn : grpMemberMap.keySet()) {
                KnCorpGroupMemberDTO member = grpMemberMap.get(memMdn);
                member.setMdn(memMdn);
                String memName = null;
                int clientType = 0;
                int contactType = 0;
                int clientPvMajorVersion = 0;
                String userAgent = null;
                if (groupMemberNameMap.get(memMdn) != null) {
                    memName = groupMemberNameMap.get(memMdn).getNetworkName();
                    clientType = groupMemberNameMap.get(memMdn).getClientType();
                    contactType = groupMemberNameMap.get(memMdn).getContact_type();
                    clientPvMajorVersion = groupMemberNameMap.get(memMdn).getClientPVMajorVersion();
                    userAgent = groupMemberNameMap.get(memMdn).getUserAgent();
                }
                if (null == memName) {
                    memName = extContNameMap.get(memMdn).getNetworkName();
                    contactType = extContNameMap.get(memMdn).getContact_type();
                }
                member.setContact_type(contactType);
                member.setClientType(clientType);
                member.setName(memName);
                member.setClientPVmajorVer(clientPvMajorVersion);
                member.setUserAgent(userAgent);
                groupMembers.add(member);
            }

            knLogger.debug(methodName, "groupMembers", groupMembers);
            KnCorpGroupInfoDTO groupResponseDTO = new KnCorpGroupInfoDTO();
            groupResponseDTO.setGroupDisplayName(groupBasicInfo.getGroupDisplayName());
            groupResponseDTO.setGroupId(groupBasicInfo.getGroupId());
            groupResponseDTO.setGroupType(groupBasicInfo.getGroupType());
            groupResponseDTO.setOverrideDnd(groupBasicInfo.getOverrideDnd());
            groupResponseDTO.setCorpId(corpId);
            groupResponseDTO.setGroupMembers(groupMembers);
            groupResponseDTO.setGroupMemCount(memberCount);
            groupResponseDTO.setAvatar(groupBasicInfo.getAvatar());
            groupResponseDTO.setSubscrProtocolversion(subscProfile.getProtocolVersion());
            groupResponseDTO.setAuthorizedLargeTG(groupBasicInfo.getAuthorizedLargeTG());
            groupResponseDTO.setVideoPermission(groupBasicInfo.getVideoPermission()); // fix: null-safe;
            respDTO.setGroupInfoDTO(groupResponseDTO);
            populate(respDTO);
        } catch (KnCorpBOException e) {
            knLogger.error(methodName, "KnCorpBOException occured while retrieving Group Details - ", e);
            populate(respDTO, e);

        } catch (Exception e) {
            knLogger.error(methodName, "Unexpected Exception occured while retrieving Group Details - ",
                    new KnException(KnErrorCodes.BOEntity.INTERNAL_ERROR, e.getMessage(), e));
            populate(respDTO, e);

        }
        knLogger.debug(methodName, "EXIT: GroupDetails Response - ", respDTO);
        return respDTO;
    }

    public KnCorpGrpBasicInfoRespDto getBasicGrpInfoByGrpName(KnIPCorpGroupInfoDTO groupInfoDTO, KnPersisterTxn persisterTxn) {
        String methodName = "getBasicGrpInfoByGrpName(KnIPCorpGroupInfoDTO, KnPersisterTxn)";
        KnCorpGrpBasicInfoRespDto respDTO = new KnCorpGrpBasicInfoRespDto();
        try {
            String xdmsHome = KnGeneralUtil.getXDMServerPttServerId();
            //retrieve group details information
            KnCorpGroupDTO groupDTO = groupInfoUtil.getGroupIdByName(groupInfoDTO.getGroupDisplayName(), groupInfoDTO.getClientType(),
                    groupInfoDTO.getTpRequestMdn(), xdmsHome, persisterTxn);
            groupInfoDTO.setGroupId(groupDTO.getGroupId());
            groupInfoDTO.setCorpId(groupDTO.getCorpId());
            KnCorpGroupInfoPersistDTO groupPersistDTO = groupInfoUtil.getGroupBasicInfoDetails(groupInfoDTO, xdmsHome, persisterTxn,Boolean.FALSE);
            knLogger.debug(methodName, "Retrieved Corp Group Info - ", groupPersistDTO);
            respDTO.setGroupId(groupPersistDTO.getGroupId());
            respDTO.setGroupListId(groupPersistDTO.getGroupMemberListId());
            respDTO.setGrpDisplayName(groupPersistDTO.getGroupDisplayName());
            respDTO.setGrpType(groupPersistDTO.getGroupType());
            respDTO.setGrpEtag(groupPersistDTO.getETag());
            respDTO.setCorpId(groupPersistDTO.getCorpId());
            respDTO.setLmrInteropCapable(groupPersistDTO.getLmrInteropCapable());
            respDTO.setGrpOwner(groupPersistDTO.getTpGroupOwner());
            respDTO.setGroupCreateBy(groupPersistDTO.getGroupCreatedBy());
            respDTO.setRecordingFs(groupPersistDTO.getRecordingFs());
            //For ADBG group group sharing is not supported hence all requests comes from same corp only
            //so setting ownerCorpReq as true to avoid unwanted issues with group sharing
            respDTO.setOwnerCorpReq(true);
            respDTO.setOldLmrInteropFlag(groupPersistDTO.getUgwInterop());
            respDTO.setIsPreConfiguredGroup(groupPersistDTO.getIsPreConfiguredGroup());
            populate(respDTO);
        } catch (KnCorpBOException e) {
            knLogger.error(methodName, "KnCorpBOException occured while retrieving group basic info by name - ", e);
            populate(respDTO, e);
        } catch (Exception e) {
            knLogger.error(methodName, "Unexpected Exception occured while retrieving group basic info by name  - ",
                    new KnException(KnErrorCodes.BOEntity.INTERNAL_ERROR, e.getMessage(), e));
            populate(respDTO, e);
        }
        knLogger.debug(methodName, "Exit - ", respDTO);
        return respDTO;
    }

    @Override
    public KnCorpResponseDTO modifySubscriberTGList(KnIPTalkGroupDTO ipTalkGroupDTO, KnPersisterTxn persisterTxn) {
        String methodName = "modifySubscriberTGList(KnIPTalkGroupDTO ipTalkGroupDTO, KnPersisterTxn persisterTxn)";
        KnXDMTalkGroupServerRespDTO respDTO = new KnXDMTalkGroupServerRespDTO();
        knLogger.debug(methodName, "ipTalkGroupDTO - ", ipTalkGroupDTO);
        try {
            KnCorpProfileDTO corpProfile = commonInfoUtil.getProfileDetails(String.valueOf(ipTalkGroupDTO.getCorpId()),
                    CORP_PROFILE, false, persisterTxn);
            knLogger.debug(methodName, "Retrieved Corp Profile details - ", corpProfile);
            String xdmsHome = corpProfile.getXdmsHome();
            String mdn = ipTalkGroupDTO.getMdn();
            KnSubsProfileDTO subscProfile = commonInfoUtil.getProfileDetails(ipTalkGroupDTO.getMdn(), KnProfileTypes.PUBLIC_PROFILE,
                    false, persisterTxn);
            if (null != ipTalkGroupDTO.getCorpId() && Integer.parseInt(ipTalkGroupDTO.getCorpId()) > 0 && subscProfile.getCorpId() != Integer.parseInt(ipTalkGroupDTO.getCorpId())) {
                throw new KnCorpBOException(KnErrorCodes.BOEntity.SUBSCRIBER_DOES_NOT_BELONG_TO_CORP,
                        "Subscribers Does not belong to the corporation.");
            }
            //Invoking custom hook
            KnCorpHookRespDTO responseDTO = new KnCorpHookRespDTO();
            Map<String, Object> customParams = ipTalkGroupDTO.getCustomParamMap();
            if (ipTalkGroupDTO.getHierarchyType() == HIERARCHY_TYPE.HIERARCHY) {
                if (customParams != null) {
                    contactInfoUtil.checkValidHierarchySubs(Collections.singletonList(mdn), customParams, xdmsHome, persisterTxn);
                    //TODO to check group are from same fan ban
                    customParams.put(CURRENT_MASTER_LIST_ETAG, corpProfile.getCorpMasterListEtag());
                    customParams.put(PERSISTER_TXN, persisterTxn);
                    customParams.put(PTT_SERVER_ID, xdmsHome);
                    ipTalkGroupDTO.setCustomParamMap(customParams);
                    KnCorpHookIPDTO hookIPDTO = new KnCorpHookIPDTO();
                    hookIPDTO.setAction(KnActions.ACTIONS.GET_SCAN_LIST);
                    hookIPDTO.setData(ipTalkGroupDTO);
                    KnProcessInvokerImpl processInvoker = KnProcessInvokerImpl.getInstance();
                    Object hookResp = processInvoker.invokeHook(CUSTOM_CORP_USER_HOOK, hookIPDTO);
                    if (hookResp instanceof KnCorpHookRespDTO) {
                        responseDTO = (KnCorpHookRespDTO) hookResp;
                        if (com.kodiak.xdms.server.common.resources.KnConstants.RESPONSE_STATUS.FAILURE.value() == responseDTO.getStatus()) {
                            knLogger.error(methodName, "Returning Failure response");
                            populateXdmResponseFroomHook(responseDTO, respDTO);
                            return respDTO;
                        } else {
                            if (responseDTO.getFailedDataList() != null && !responseDTO.getFailedDataList().isEmpty()) {
                                respDTO.setFailedDataList(responseDTO.getFailedDataList());
                            }
                        }
                    }
                }
            }
            KnCorpTGSPersistDTO corpTGSPersistDTO = new KnCorpTGSPersistDTO();
            //Subscriber's Profile:
            KnCorpSubscriberDTO subscriberDTO = contactInfoUtil.selectPocSubscriberInfo(mdn, xdmsHome, persisterTxn);

            //Existing Addl TG List from DB for Input MDN:
            Collection<KnCorpAddlTGInfoDTO> existingSubsAddlTGList = groupInfoUtil.getSubsAddlTGList(mdn, xdmsHome, persisterTxn);
            List<Integer> existingDBGroupIds = existingSubsAddlTGList.stream().map(KnCorpGroupDTO::getGroupId).collect(Collectors.toList());
            knLogger.debug(methodName, "existingSubsAddlTGList - ", existingSubsAddlTGList, " existingDBGroupIds :", existingDBGroupIds);

            //Added: Input
            Collection<KnCorpAddlTGInfoDTO> requestSubsAddlTGList = ipTalkGroupDTO.getAddedAddlTgList();
            Set<Integer> reqAddlGroupIds = requestSubsAddlTGList.stream().map(KnCorpGroupDTO::getGroupId).collect(Collectors.toSet());
            knLogger.debug(methodName, "reqAddlGroupIds - ", reqAddlGroupIds, " requestSubsAddlTGList :", requestSubsAddlTGList);

            //Modified: Input
            Collection<KnCorpAddlTGInfoDTO> reqModSubsAddlTGList = ipTalkGroupDTO.getModifiedAddlTgList();
            Set<Integer> reqModifyGroupIds = reqModSubsAddlTGList.stream().map(KnCorpGroupDTO::getGroupId).collect(Collectors.toSet());
            knLogger.debug(methodName, "reqModifyGroupIds - ", reqModifyGroupIds, " reqModSubsAddlTGList :", reqModSubsAddlTGList);

            //Deleted: Input
            Collection<KnCorpAddlTGInfoDTO> reqDelSubsAddlTGList = ipTalkGroupDTO.getRemovedAddlTgList();
            List<Integer> delGroupIds = new ArrayList<>();
            List<String> combinedList = new ArrayList<>();
            if (reqDelSubsAddlTGList != null)
                delGroupIds.addAll(reqDelSubsAddlTGList.stream().map(KnCorpAddlTGInfoDTO::getGroupId)
                        .collect(Collectors.toList()));

            if (ipTalkGroupDTO.getHierarchyType() == HIERARCHY_TYPE.HIERARCHY && customParams != null) {
                if (!reqAddlGroupIds.isEmpty() || !reqModifyGroupIds.isEmpty() || !delGroupIds.isEmpty()) {
                    Collection<String> idListStr = (Collection<String>) customParams.get(com.kodiak.common.resources.KnConstants.IDLIST);
                    Object idTypeObj = customParams.get(IDTYPE);
                    int idTypeValues = idTypeObj instanceof Integer ? (Integer) idTypeObj : Integer.parseInt((String) idTypeObj);

                    if (idListStr != null) {
                        List<Integer> idListInt = (List<Integer>) convertStrToIntColl(idListStr);
                        // Directly collect all IDs into a single list
                        combinedList = Stream.of(reqAddlGroupIds, reqModifyGroupIds, delGroupIds).filter(Objects::nonNull).flatMap(Collection::stream).map(Object::toString).collect(Collectors.toList());

                        commonInfoUtil.validateGroupParams(combinedList, String.valueOf(ipTalkGroupDTO.getCorpId()), idListInt, xdmsHome, idTypeValues, persisterTxn);
                    }
                }
            }
            commonInfoUtil.validateCorpAndGroupParams(combinedList, String.valueOf(ipTalkGroupDTO.getCorpId()), xdmsHome, persisterTxn);

            //disabled AddlTalkGroupListsChecker to allow multy zone across group
            //diasbled AddlTalkGroupListsZCChecker to allow multy zone across group

            //getting flags from common config
            int clusterId = Integer.parseInt(System.getenv(CLUSTERID_ENV_NAME));
            Map<String, String> microServicesParamNameValueMap = genInfoUtil.retrieveMSSvcsCommonConfig(clusterId, persisterTxn);
            String allowGroupAcrossZones = microServicesParamNameValueMap.get(ALLOW_GROUP_ACROSS_ZONES);
            String skipChannelPerZoneValidation = microServicesParamNameValueMap.get(CHANNELPERZONE_VALIDATION);
            int subsClientPVmajorVer = subscriberDTO.getClientPVmajorVer();
            boolean extCnt = contactInfoUtil.isExternalSubscriber(ipTalkGroupDTO.getMdn(), Integer.parseInt(ipTalkGroupDTO.getCorpId()),
                    xdmsHome, persisterTxn);
            String userProfileId = subscriberDTO.getUserProfileId();
            knLogger.debug(methodName," userProfileId:",userProfileId);
            ArrayList<String> upmId = new ArrayList<>();
            upmId.add(userProfileId);
            Map<String, Integer> upmOwnerList = corpUserProfileUtil.getUserProfileOwnerinfo(upmId, xdmsHome, persisterTxn);
            Integer groupOwnerCorpId=Integer.parseInt(ipTalkGroupDTO.getCorpId());
            Map<Integer, Integer> groupIdTypesMap = null;
            if(!upmOwnerList.isEmpty()){
                groupOwnerCorpId=upmOwnerList.get(userProfileId);
                groupIdTypesMap = groupInfoUtil.getValidGrp(new ArrayList<>(reqAddlGroupIds),
                        xdmsHome, persisterTxn);
            }
            knLogger.debug(methodName,"ownerCorpId :",groupOwnerCorpId);
            if(groupIdTypesMap == null)
                groupIdTypesMap = groupInfoUtil.getValidGrpInCorp(new ArrayList<>(reqAddlGroupIds), groupOwnerCorpId,
                        xdmsHome, persisterTxn);
            //changes for group sharing
            //check whether for the given corpId any shared groups are avilable or not
            //if any shared groups are avilable then add shared group info to dbGroupList to avoid rules
            Set<Integer> sharedCorpGrpIds  = new HashSet<>(1);
            Map<Integer,List<KnCorpSharedCorpInfo>> sharedCorpGrpInfoMap = groupInfoUtil.selectGroupSharedCorpInfoBySharedCorpId(groupOwnerCorpId,xdmsHome,persisterTxn);

            if(sharedCorpGrpInfoMap!=null && !sharedCorpGrpInfoMap.isEmpty()) {
                sharedCorpGrpIds = sharedCorpGrpInfoMap.keySet();
                knLogger.debug(methodName, "sharedCorpGrpIds", sharedCorpGrpIds);
            }

            List<Integer> inputBGGroup = groupIdTypesMap.entrySet().stream().filter(map -> map.getValue().equals(BROADCAST_GROUP))
                    .map(Entry::getKey).collect(Collectors.toList());
            List<Integer> grpIdListInCorp = new ArrayList<>(groupIdTypesMap.keySet());
            grpIdListInCorp.addAll(sharedCorpGrpIds);
            Set<Integer> grpTypeSet = new HashSet<>(groupIdTypesMap.values());
            List<Integer> subsGrpList = groupInfoUtil.getSubsGroupIdList(grpIdListInCorp, ipTalkGroupDTO.getMdn(),
                    xdmsHome, persisterTxn);
            knLogger.debug(methodName, "subsGrpList from GroupMembership table ", subsGrpList);

            List<Integer> mcxGroups = new ArrayList<>();
            if(userProfileId!=null){
                //KnCorpUserProfileDTO userProfile = corpUserProfileUtil.getUserProfile(String.valueOf(ipTalkGroupDTO.getCorpId()), userProfileId, xdmsHome, persisterTxn);
                Set<KnCorpGroupListInfoDTO> mcxGroupList =corpUserProfileUtil.retriveGroupProfileInfoByProfileId(userProfileId, xdmsHome, persisterTxn);

                knLogger.debug(methodName, "mcxGroup ", mcxGroupList);
                List<Integer> groupIdListFromProfile = new ArrayList<>();
                if (mcxGroupList != null && mcxGroupList.size() > 0) {
                    groupIdListFromProfile = mcxGroupList.stream().map(KnCorpGroupListInfoDTO::getGroupID).collect(Collectors.toList());
                    knLogger.debug(methodName, "groupIdListFromProfile  ", groupIdListFromProfile);
                    for (KnCorpGroupListInfoDTO info : mcxGroupList) {
                        if (!reqAddlGroupIds.contains(info.getGroupID())) {
                            KnCorpAddlTGInfoDTO tgInfoDTO = new KnCorpAddlTGInfoDTO();
                            tgInfoDTO.setMdn(mdn);
                            tgInfoDTO.setChannelId(info.getGroupChannel());
                            tgInfoDTO.setZoneId(info.getGroupZone());
                            tgInfoDTO.setGroupId(info.getGroupID());
                            if(info.getGroupChannel()!=null&&info.getGroupZone()!=null)
                                existingSubsAddlTGList.add(tgInfoDTO);
                        }
                    }
                }
                Collection<Integer> groupIds = new HashSet<>();
                groupIds.addAll(reqAddlGroupIds);
                groupIds.addAll(groupIdListFromProfile);
                List<KnCorpGroupDTO> groupInfoList = groupInfoUtil.getGroupBasicInfoList(groupIds, xdmsHome, persisterTxn);
                mcxGroups = groupInfoList.stream()
                        .filter(groupDetails -> groupDetails.getMcxGrpInd().intValue() == GROUP_SIZE_TYPE.VLARGE_GROUP.value())
                        .map(KnCorpGroupDTO::getGroupId).collect(Collectors.toList());
                knLogger.debug(methodName, "mcx groups ", mcxGroups);
                subsGrpList.removeAll(mcxGroups);
                subsGrpList.addAll(mcxGroups);
                knLogger.debug(methodName, "subsGrpList from GroupMembership table ", subsGrpList);
            }

            List<KnUserprofileSharedlistDTO> upmSharedList = corpUserProfileUtil.getUserProfileSharedListByUpmId(userProfileId, xdmsHome, persisterTxn);
            boolean isUPMSharingEnabled = false;
            if(upmSharedList != null) {
                // sharedCorpList should contains ownerCorpId and sharedCorpId then isUPMSharingEnabled is made true.
                for (KnUserprofileSharedlistDTO getUPMSharedDetails : upmSharedList) {
                    if (Objects.equals(getUPMSharedDetails.getOwnerCorpId(), Integer.valueOf(ipTalkGroupDTO.getCorpId())) && getUPMSharedDetails.getSharedCorpId() == subscriberDTO.getCorpId()) {
                        isUPMSharingEnabled = true;
                        break;
                    }
                }
            }
            knLogger.debug(methodName,"isUPMSharingEnabled :",isUPMSharingEnabled);

            List<Integer> brdcstGrpIds = groupInfoUtil.getBroadcstGroupList(ipTalkGroupDTO.getMdn(), xdmsHome, persisterTxn);
            Map<Integer, Collection<Integer>> zoneChannelMap = groupInfoUtil.getZoneChannelMap(xdmsHome, persisterTxn);
            knLogger.debug(methodName, "zoneChannelMap ", zoneChannelMap);
            Map<Integer, Collection<String>> groupDistList = groupInfoUtil.getGroupSubscriberDistList(inputBGGroup, xdmsHome, persisterTxn);
            knLogger.debug(methodName, "groupDistList ", KnGDPRTemplate.mapMdnAsValue(groupDistList));
            corpTGSPersistDTO.setZoneChannelMap(zoneChannelMap);
            corpTGSPersistDTO.setMaxZone(corpProfile.getMaxZones());
            corpTGSPersistDTO.setMaxChannelPerZone(corpProfile.getMaxChannelsPerZone());
            corpTGSPersistDTO.setInputDTO(ipTalkGroupDTO);
            corpTGSPersistDTO.setSubsCorpId(subscriberDTO.getCorpId());
            corpTGSPersistDTO.setSubsClientType(subscriberDTO.getClientType());
            corpTGSPersistDTO.setClientMajorVersion(subsClientPVmajorVer);
            corpTGSPersistDTO.setDbAddlTGList(existingSubsAddlTGList);
            corpTGSPersistDTO.setSubsExternalCont(extCnt);
            corpTGSPersistDTO.setGrpListInCorp(grpIdListInCorp);
            corpTGSPersistDTO.setReqGroupTypes(grpTypeSet);
            corpTGSPersistDTO.setGrpIdTypeMap(groupIdTypesMap);
            corpTGSPersistDTO.setSubsGroupList(subsGrpList);
            corpTGSPersistDTO.setBroadcastGrpIds(new HashSet<Integer>(brdcstGrpIds));
            corpTGSPersistDTO.setBgMemberMap(groupDistList);
            corpTGSPersistDTO.setAllowGroupAcrossZones(allowGroupAcrossZones != null ? Integer.parseInt(allowGroupAcrossZones) : 0);
            corpTGSPersistDTO.setCalledFromModifyUPM(ipTalkGroupDTO.isCalledFromModifyUPM());
            corpTGSPersistDTO.setUPMSharingEnabled(isUPMSharingEnabled);
            if(skipChannelPerZoneValidation!=null)
                corpTGSPersistDTO.setSkipChannelPerZoneValidation(Integer.valueOf(skipChannelPerZoneValidation));

            knLogger.debug(methodName, "Before Validation", corpTGSPersistDTO);
            validatorFW.validate(corpTGSPersistDTO);
            knLogger.debug(methodName, "Validation Successfull");
            // Business Logics:
            Collection<KnCorpAddlTGInfoDTO> insertAddlGrpLst = new ArrayList<>();
            Collection<KnCorpAddlTGInfoDTO> modifyInsertAddlGrpLst = new ArrayList<>();
            List<KnCorpAddlTGInfoDTO> deleteAddlGrpLst = new ArrayList<>();
            Collection<KnCorpAddlTGInfoDTO> deleteAddlGrpLstForNotification = new ArrayList<>();
            if (reqModSubsAddlTGList != null && !reqModSubsAddlTGList.isEmpty()
                    && existingSubsAddlTGList != null && !existingSubsAddlTGList.isEmpty()) {
                for (KnCorpAddlTGInfoDTO modReq : reqModSubsAddlTGList) {
                    if (modReq.getZoneName() == null) {
                        modReq.setZoneName(existingSubsAddlTGList.stream()
                                .filter(db -> modReq.getZoneId().equals(db.getZoneId())
                                        && modReq.getChannelId() == db.getChannelId()
                                        && modReq.getGroupId() == db.getGroupId()
                                        && db.getZoneName() != null)
                                .map(db -> db.getZoneName()).findAny()
                                .orElse(null));
                    }
                    //setting back modify req after retaining zone name if null in req.
                    modifyInsertAddlGrpLst.add(modReq);
                }
                //deleting all record for the group passed in the mod request
                for (KnCorpAddlTGInfoDTO dbrecord : existingSubsAddlTGList) {
                    for (KnCorpAddlTGInfoDTO modReqLoop : reqModSubsAddlTGList) {
                        if (modReqLoop.getGroupId() == dbrecord.getGroupId()) {
                            deleteAddlGrpLst.add(dbrecord);
                        }
                    }
                }

                knLogger.debug("modifyInsertAddlGrpLst ::", modifyInsertAddlGrpLst);
                knLogger.debug("deleteAddlGrpLst ::", deleteAddlGrpLst);
            }

            if (existingSubsAddlTGList != null) {
                delGroupIds.forEach(delGrpId -> {
                    List<KnCorpAddlTGInfoDTO> delAddlTGList = existingSubsAddlTGList.stream().filter(g -> {
                        if (delGrpId.equals(g.getGroupId())) {
                            return true;
                        }
                        return false;
                    }).collect(Collectors.toList());
                    deleteAddlGrpLst.addAll(delAddlTGList);
                    deleteAddlGrpLstForNotification.addAll(delAddlTGList);
                });
                knLogger.debug("delAddlTGList ::", deleteAddlGrpLst);
                knLogger.debug("deleteAddlGrpLstForNotification ::", deleteAddlGrpLstForNotification);
            }
            insertAddlGrpLst.addAll(modifyInsertAddlGrpLst);
            insertAddlGrpLst.addAll(requestSubsAddlTGList);
            //DeleteCall:
            if (!deleteAddlGrpLst.isEmpty())
                groupInfoUtil.deleteSubsAddlTGList(deleteAddlGrpLst, xdmsHome, persisterTxn);
            // Insert Call:
            if (!insertAddlGrpLst.isEmpty()) {
                if(!mcxGroups.isEmpty()){
                    List<Integer> finalMcxGroups = mcxGroups;
                    List<KnCorpAddlTGInfoDTO> filteredAddlGrpLst = insertAddlGrpLst.stream()
                            .filter(e -> !finalMcxGroups.contains(e.getGroupId()))
                            .collect(Collectors.toList());
                    if(!filteredAddlGrpLst.isEmpty()){
                        groupInfoUtil.insertSubsAddlTGList(filteredAddlGrpLst, xdmsHome, persisterTxn);
                    }
                }else{
                    groupInfoUtil.insertSubsAddlTGList(insertAddlGrpLst, xdmsHome, persisterTxn);
                }
            }
            // Notification Preparation:
            Collection<String> mdnList = new ArrayList<>();
            mdnList.add(mdn);

            //GroupIds:
            Set<Integer> groupIdList = new HashSet<>();
            if (existingDBGroupIds != null) groupIdList.addAll(existingDBGroupIds);
            if (reqAddlGroupIds != null) groupIdList.addAll(reqAddlGroupIds);
            if (reqModifyGroupIds != null) groupIdList.addAll(reqModifyGroupIds);
            KnIPCorpContactDTO contactDTO = new KnIPCorpContactDTO();
            contactDTO.setMdn(mdn);
            contactDTO.setCorpId(Integer.parseInt(ipTalkGroupDTO.getCorpId()));
            Collection<KnCorpGroupInfoPersistDTO> groupList = groupInfoUtil.getSubsGroupListForXcap(contactDTO, 0, xdmsHome, persisterTxn);
            Map<Integer, KnCorpGroupInfoPersistDTO> groupDetailsMap = groupList.stream().filter(grpList -> groupIdList.contains(grpList.getGroupId()))
                    .collect(Collectors.toMap(KnCorpGroupInfoPersistDTO::getGroupId, request -> request));
            knLogger.debug(methodName, "groupDetailsMap -- ", groupDetailsMap);
            requestSubsAddlTGList.forEach(reqList -> {
                KnCorpGroupInfoPersistDTO reqData = groupDetailsMap.get(reqList.getGroupId());
                if (reqData != null) {
                    reqList.setGroupType(reqData.getGroupType());
                    reqList.setGroupMemCount(reqData.getGroupMemberCount());
                    reqList.setGroupCreatedBy(reqData.getGroupCreatedBy());
                    reqList.setAvatar(reqData.getAvatar());
                }
            });
            modifyInsertAddlGrpLst.forEach(modList -> {
                KnCorpGroupInfoPersistDTO modData = groupDetailsMap.get(modList.getGroupId());
                if (modData != null) {
                    modList.setGroupType(modData.getGroupType());
                    modList.setGroupMemCount(modData.getGroupMemberCount());
                    modList.setGroupCreatedBy(modData.getGroupCreatedBy());
                    modList.setAvatar(modData.getAvatar());
                }
            });
            Map<String, KnOPDirChgDTO> etagMap = groupInfoUtil.updateAddlTalkGroupImpactedTables(xdmsHome, mdnList, persisterTxn, null);
            knLogger.debug(methodName, "etagMap - ", KnGDPRTemplate.mapKeyMdn(etagMap));
            Collection<KnCorpAddlTGInfoDTO> allAddlTgList = new ArrayList<>();
            if (null != ipTalkGroupDTO.getAddedAddlTgList() && null != ipTalkGroupDTO.getModifiedAddlTgList() && null != ipTalkGroupDTO.getRemovedAddlTgList()) {
                allAddlTgList.addAll(ipTalkGroupDTO.getAddedAddlTgList());
                allAddlTgList.addAll(ipTalkGroupDTO.getModifiedAddlTgList());
                allAddlTgList.addAll(ipTalkGroupDTO.getRemovedAddlTgList());
            }
            Map<Integer, Integer> groupCorpIdMap = new HashMap<>();
            if (allAddlTgList != null && !allAddlTgList.isEmpty()) {
                groupCorpIdMap = groupInfoUtil.getGroupCorpIdMap((List<KnCorpAddlTGInfoDTO>) allAddlTgList, xdmsHome, persisterTxn);
            }
            knLogger.debug(methodName, "groupCorpId - ", groupCorpIdMap);
            if (null != groupCorpIdMap && !groupCorpIdMap.isEmpty()) {
                if (subsClientPVmajorVer >= PROTOCOL_VERSION_16) {
                    modifyInsertAddlGrpLst.addAll(requestSubsAddlTGList);
                    etagMap = formXcapAddlTGDiffNotification(etagMap, null, modifyInsertAddlGrpLst,
                            deleteAddlGrpLstForNotification, groupCorpIdMap);
                } else {
                    etagMap = formXcapAddlTGDiffNotification(etagMap, requestSubsAddlTGList, modifyInsertAddlGrpLst,
                            deleteAddlGrpLstForNotification, groupCorpIdMap);
                }
            }

            knLogger.debug(methodName, "etagMap 333 - ", KnGDPRTemplate.mapKeyMdn(etagMap));
            // todo: LI Notification Preparation. // no SDD requirements.
            respDTO.setChangeLogMap(etagMap);
            populate(respDTO);
            // PDMBB-12990
            // Updating the AUTO_ASSIGN_TRACKER to Manual in POCSUBSCR_ADDLINFO
            String pttServerID = genInfoUtil.retrieveLocalXDMPttServerId();
            groupInfoUtil.updateAutoAssignTracker(Collections.singletonList(ipTalkGroupDTO.getMdn()), AUTO_ASSIGN_TRACKER.MANUALLY_ASSIGNED.value(), persisterTxn, pttServerID);
        } catch (KnValidationException e) {
            populate(respDTO, e);
            knLogger.error(methodName, "KnValidationException occured while modifySubscriberTGList", e);
        } catch (KnCorpBOException e) {
            populate(respDTO, e);
            knLogger.error(methodName, "KnCorpBOException occured while modifySubscriberTGList", e);
        } catch (Exception e) {
            populate(respDTO, e);
            knLogger.error(methodName, "Unexpected exception occured while modifySubscriberTGList ", new KnException(
                    KnErrorCodes.BOEntity.INTERNAL_ERROR, e.getMessage(), e));
        }
        return respDTO;
    }

    @Override
    public KnCorpResponseDTO modifyBulkSubscriberTGList(KnIPTalkGroupDTO ipTalkGroupDTO, KnPersisterTxn persisterTxn) {
        String methodName = "modifyBulkSubscriberTGList(KnIPTalkGroupDTO ipTalkGroupDTO, KnPersisterTxn persisterTxn)";
        KnXDMTalkGroupServerRespDTO respDTO = new KnXDMTalkGroupServerRespDTO();
        knLogger.debug(methodName, "ipTalkGroupDTO - ", ipTalkGroupDTO);
        try {
            KnCorpProfileDTO corpProfile = commonInfoUtil.getProfileDetails(String.valueOf(ipTalkGroupDTO.getCorpId()),
                    CORP_PROFILE, false, persisterTxn);
            knLogger.debug(methodName, "Retrieved Corp Profile details - ", corpProfile);
            String xdmsHome = corpProfile.getXdmsHome();
            String mdn = ipTalkGroupDTO.getMdn();
            //Invoking custom hook
            KnCorpHookRespDTO responseDTO = new KnCorpHookRespDTO();
            Map<String, Object> customParams = ipTalkGroupDTO.getCustomParamMap();
            if (ipTalkGroupDTO.getHierarchyType() == HIERARCHY_TYPE.HIERARCHY) {
                if (customParams != null) {
                    customParams.put(CURRENT_MASTER_LIST_ETAG, corpProfile.getCorpMasterListEtag());
                    customParams.put(PERSISTER_TXN, persisterTxn);
                    customParams.put(PTT_SERVER_ID, xdmsHome);
                    ipTalkGroupDTO.setCustomParamMap(customParams);
                    KnCorpHookIPDTO hookIPDTO = new KnCorpHookIPDTO();
                    hookIPDTO.setAction(KnActions.ACTIONS.GET_SCAN_LIST);
                    hookIPDTO.setData(ipTalkGroupDTO);
                    KnProcessInvokerImpl processInvoker = KnProcessInvokerImpl.getInstance();
                    Object hookResp = processInvoker.invokeHook(CUSTOM_CORP_USER_HOOK, hookIPDTO);
                    if (hookResp instanceof KnCorpHookRespDTO) {
                        responseDTO = (KnCorpHookRespDTO) hookResp;
                        if (com.kodiak.xdms.server.common.resources.KnConstants.RESPONSE_STATUS.FAILURE.value() == responseDTO.getStatus()) {
                            knLogger.error(methodName, "Returning Failure response");
                            populateXdmResponseFroomHook(responseDTO, respDTO);
                            return respDTO;
                        } else {
                            if (responseDTO.getFailedDataList() != null && !responseDTO.getFailedDataList().isEmpty()) {
                                respDTO.setFailedDataList(responseDTO.getFailedDataList());
                            }
                        }
                    }
                }
            }
            //Subscriber's Profile:
            KnCorpSubscriberDTO subscriberDTO = contactInfoUtil.selectPocSubscriberInfo(mdn, xdmsHome, persisterTxn);

            //Existing Addl TG List from DB for Input MDN:
            Collection<KnCorpAddlTGInfoDTO> existingSubsAddlTGList = groupInfoUtil.getSubsAddlTGList(mdn, xdmsHome, persisterTxn);
            List<Integer> existingDBGroupIds = existingSubsAddlTGList.stream().map(KnCorpGroupDTO::getGroupId).collect(Collectors.toList());
            knLogger.debug(methodName, "existingSubsAddlTGList - ", existingSubsAddlTGList, " existingDBGroupIds :", existingDBGroupIds);

            //Added: Input
            Collection<KnCorpAddlTGInfoDTO> requestSubsAddlTGList = ipTalkGroupDTO.getAddedAddlTgList();
            Set<Integer> reqAddlGroupIds = requestSubsAddlTGList.stream().map(KnCorpGroupDTO::getGroupId).collect(Collectors.toSet());
            knLogger.debug(methodName, "reqAddlGroupIds - ", reqAddlGroupIds, " requestSubsAddlTGList :", requestSubsAddlTGList);

            //Modified: Input
            Collection<KnCorpAddlTGInfoDTO> reqModSubsAddlTGList = ipTalkGroupDTO.getModifiedAddlTgList();
            Set<Integer> reqModifyGroupIds = reqModSubsAddlTGList.stream().map(KnCorpGroupDTO::getGroupId).collect(Collectors.toSet());
            knLogger.debug(methodName, "reqModifyGroupIds - ", reqModifyGroupIds, " reqModSubsAddlTGList :", reqModSubsAddlTGList);

            //Deleted: Input
            Collection<KnCorpAddlTGInfoDTO> reqDelSubsAddlTGList = ipTalkGroupDTO.getRemovedAddlTgList();
            List<Integer> delGroupIds = new ArrayList<>();
            if (reqDelSubsAddlTGList != null)
                delGroupIds.addAll(reqDelSubsAddlTGList.stream().map(KnCorpAddlTGInfoDTO::getGroupId)
                        .collect(Collectors.toList()));

            //disabled AddlTalkGroupListsChecker to allow multy zone across group
            //diasbled AddlTalkGroupListsZCChecker to allow multy zone across group

            String userProfileId = subscriberDTO.getUserProfileId();
            knLogger.debug(methodName, " userProfileId:", userProfileId);
            ArrayList<String> upmId = new ArrayList<>();
            upmId.add(userProfileId);
            Map<String, Integer> upmOwnerList = corpUserProfileUtil.getUserProfileOwnerinfo(upmId, xdmsHome, persisterTxn);
            Integer groupOwnerCorpId = Integer.parseInt(ipTalkGroupDTO.getCorpId());
            Map<Integer, Integer> groupIdTypesMap = null;
            if (!upmOwnerList.isEmpty()) {
                groupOwnerCorpId = upmOwnerList.get(userProfileId);
                groupIdTypesMap = groupInfoUtil.getValidGrp(new ArrayList<>(reqAddlGroupIds),
                        xdmsHome, persisterTxn);
            }
            knLogger.debug(methodName, "ownerCorpId :", groupOwnerCorpId);
            if (groupIdTypesMap == null)
                groupIdTypesMap = groupInfoUtil.getValidGrpInCorp(new ArrayList<>(reqAddlGroupIds), groupOwnerCorpId,
                        xdmsHome, persisterTxn);
            //changes for group sharing
            //check whether for the given corpId any shared groups are avilable or not
            //if any shared groups are avilable then add shared group info to dbGroupList to avoid rules
            Set<Integer> sharedCorpGrpIds = new HashSet<>(1);
            Map<Integer, List<KnCorpSharedCorpInfo>> sharedCorpGrpInfoMap = groupInfoUtil.selectGroupSharedCorpInfoBySharedCorpId(groupOwnerCorpId, xdmsHome, persisterTxn);

            if (sharedCorpGrpInfoMap != null && !sharedCorpGrpInfoMap.isEmpty()) {
                sharedCorpGrpIds = sharedCorpGrpInfoMap.keySet();
                knLogger.debug(methodName, "sharedCorpGrpIds", sharedCorpGrpIds);
            }

            List<Integer> inputBGGroup = groupIdTypesMap.entrySet().stream().filter(map -> map.getValue().equals(BROADCAST_GROUP))
                    .map(Entry::getKey).collect(Collectors.toList());
            List<Integer> grpIdListInCorp = new ArrayList<>(groupIdTypesMap.keySet());
            grpIdListInCorp.addAll(sharedCorpGrpIds);
            Set<Integer> grpTypeSet = new HashSet<>(groupIdTypesMap.values());
            List<Integer> subsGrpList = groupInfoUtil.getSubsGroupIdList(grpIdListInCorp, ipTalkGroupDTO.getMdn(),
                    xdmsHome, persisterTxn);
            knLogger.debug(methodName, "subsGrpList from GroupMembership table ", subsGrpList);

            List<Integer> mcxGroups = new ArrayList<>();
            if (userProfileId != null) {
                //KnCorpUserProfileDTO userProfile = corpUserProfileUtil.getUserProfile(String.valueOf(ipTalkGroupDTO.getCorpId()), userProfileId, xdmsHome, persisterTxn);
                Set<KnCorpGroupListInfoDTO> mcxGroupList = corpUserProfileUtil.retriveGroupProfileInfoByProfileId(userProfileId, xdmsHome, persisterTxn);

                knLogger.debug(methodName, "mcxGroup ", mcxGroupList);
                List<Integer> groupIdListFromProfile = new ArrayList<>();
                if (mcxGroupList != null && mcxGroupList.size() > 0) {
                    groupIdListFromProfile = mcxGroupList.stream().map(KnCorpGroupListInfoDTO::getGroupID).collect(Collectors.toList());
                    knLogger.debug(methodName, "groupIdListFromProfile  ", groupIdListFromProfile);
                    for (KnCorpGroupListInfoDTO info : mcxGroupList) {
                        if (!reqAddlGroupIds.contains(info.getGroupID())) {
                            KnCorpAddlTGInfoDTO tgInfoDTO = new KnCorpAddlTGInfoDTO();
                            tgInfoDTO.setMdn(mdn);
                            tgInfoDTO.setChannelId(info.getGroupChannel());
                            tgInfoDTO.setZoneId(info.getGroupZone());
                            tgInfoDTO.setGroupId(info.getGroupID());
                            if (info.getGroupChannel() != null && info.getGroupZone() != null)
                                existingSubsAddlTGList.add(tgInfoDTO);
                        }
                    }
                }
                Collection<Integer> groupIds = new HashSet<>();
                groupIds.addAll(reqAddlGroupIds);
                groupIds.addAll(groupIdListFromProfile);
                List<KnCorpGroupDTO> groupInfoList = groupInfoUtil.getGroupBasicInfoList(groupIds, xdmsHome, persisterTxn);
                mcxGroups = groupInfoList.stream()
                        .filter(groupDetails -> groupDetails.getMcxGrpInd().intValue() == GROUP_SIZE_TYPE.VLARGE_GROUP.value())
                        .map(KnCorpGroupDTO::getGroupId).collect(Collectors.toList());
                knLogger.debug(methodName, "mcx groups ", mcxGroups);
                subsGrpList.removeAll(mcxGroups);
                subsGrpList.addAll(mcxGroups);
                knLogger.debug(methodName, "subsGrpList from GroupMembership table ", subsGrpList);
            }

            List<KnUserprofileSharedlistDTO> upmSharedList = corpUserProfileUtil.getUserProfileSharedListByUpmId(userProfileId, xdmsHome, persisterTxn);
            boolean isUPMSharingEnabled = false;
            if (upmSharedList != null) {
                // sharedCorpList should contains ownerCorpId and sharedCorpId then isUPMSharingEnabled is made true.
                for (KnUserprofileSharedlistDTO getUPMSharedDetails : upmSharedList) {
                    if (Objects.equals(getUPMSharedDetails.getOwnerCorpId(), Integer.valueOf(ipTalkGroupDTO.getCorpId())) && getUPMSharedDetails.getSharedCorpId() == subscriberDTO.getCorpId()) {
                        isUPMSharingEnabled = true;
                        break;
                    }
                }
            }
            knLogger.debug(methodName, "isUPMSharingEnabled :", isUPMSharingEnabled);

            List<Integer> brdcstGrpIds = groupInfoUtil.getBroadcstGroupList(ipTalkGroupDTO.getMdn(), xdmsHome, persisterTxn);
            Map<Integer, Collection<Integer>> zoneChannelMap = groupInfoUtil.getZoneChannelMap(xdmsHome, persisterTxn);
            knLogger.debug(methodName, "zoneChannelMap ", zoneChannelMap);
            Map<Integer, Collection<String>> groupDistList = groupInfoUtil.getGroupSubscriberDistList(inputBGGroup, xdmsHome, persisterTxn);
            knLogger.debug(methodName, "groupDistList ", KnGDPRTemplate.mapMdnAsValue(groupDistList));
            knLogger.debug(methodName, "Validation Successfull");
            // Business Logics:
            Collection<KnCorpAddlTGInfoDTO> insertAddlGrpLst = new ArrayList<>();
            Collection<KnCorpAddlTGInfoDTO> modifyInsertAddlGrpLst = new ArrayList<>();
            List<KnCorpAddlTGInfoDTO> deleteAddlGrpLst = new ArrayList<>();
            Collection<KnCorpAddlTGInfoDTO> deleteAddlGrpLstForNotification = new ArrayList<>();
            if (reqModSubsAddlTGList != null && !reqModSubsAddlTGList.isEmpty()
                    && existingSubsAddlTGList != null && !existingSubsAddlTGList.isEmpty()) {
                for (KnCorpAddlTGInfoDTO modReq : reqModSubsAddlTGList) {
                    if (modReq.getZoneName() == null) {
                        modReq.setZoneName(existingSubsAddlTGList.stream()
                                .filter(db -> modReq.getZoneId().equals(db.getZoneId())
                                        && modReq.getChannelId() == db.getChannelId()
                                        && modReq.getGroupId() == db.getGroupId()
                                        && db.getZoneName() != null)
                                .map(db -> db.getZoneName()).findAny()
                                .orElse(null));
                    }
                    //setting back modify req after retaining zone name if null in req.
                    modifyInsertAddlGrpLst.add(modReq);
                }
                //deleting all record for the group passed in the mod request
                for (KnCorpAddlTGInfoDTO dbrecord : existingSubsAddlTGList) {
                    for (KnCorpAddlTGInfoDTO modReqLoop : reqModSubsAddlTGList) {
                        if (modReqLoop.getGroupId() == dbrecord.getGroupId()) {
                            deleteAddlGrpLst.add(dbrecord);
                        }
                    }
                }

                knLogger.debug("modifyInsertAddlGrpLst ::", modifyInsertAddlGrpLst);
                knLogger.debug("deleteAddlGrpLst ::", deleteAddlGrpLst);
            }

            if (existingSubsAddlTGList != null) {
                delGroupIds.forEach(delGrpId -> {
                    List<KnCorpAddlTGInfoDTO> delAddlTGList = existingSubsAddlTGList.stream().filter(g -> {
                        if (delGrpId.equals(g.getGroupId())) {
                            return true;
                        }
                        return false;
                    }).collect(Collectors.toList());
                    deleteAddlGrpLst.addAll(delAddlTGList);
                    deleteAddlGrpLstForNotification.addAll(delAddlTGList);
                });
                knLogger.debug("delAddlTGList ::", deleteAddlGrpLst);
                knLogger.debug("deleteAddlGrpLstForNotification ::", deleteAddlGrpLstForNotification);
            }
            insertAddlGrpLst.addAll(modifyInsertAddlGrpLst);
            insertAddlGrpLst.addAll(requestSubsAddlTGList);
            //DeleteCall:
            if (!deleteAddlGrpLst.isEmpty())
                groupInfoUtil.deleteSubsAddlTGList(deleteAddlGrpLst, xdmsHome, persisterTxn);
            // Insert Call:
            if (!insertAddlGrpLst.isEmpty()) {
                if (!mcxGroups.isEmpty()) {
                    List<Integer> finalMcxGroups = mcxGroups;
                    List<KnCorpAddlTGInfoDTO> filteredAddlGrpLst = insertAddlGrpLst.stream()
                            .filter(e -> !finalMcxGroups.contains(e.getGroupId()))
                            .collect(Collectors.toList());
                    if (!filteredAddlGrpLst.isEmpty()) {
                        groupInfoUtil.insertSubsAddlTGList(filteredAddlGrpLst, xdmsHome, persisterTxn);
                    }
                } else {
                    groupInfoUtil.insertSubsAddlTGList(insertAddlGrpLst, xdmsHome, persisterTxn);
                }
            }
            // Notification Preparation:
            Collection<String> mdnList = new ArrayList<>();
            mdnList.add(mdn);

            //GroupIds:
            Set<Integer> groupIdList = new HashSet<>();
            if (existingDBGroupIds != null) groupIdList.addAll(existingDBGroupIds);
            if (reqAddlGroupIds != null) groupIdList.addAll(reqAddlGroupIds);
            if (reqModifyGroupIds != null) groupIdList.addAll(reqModifyGroupIds);
            KnIPCorpContactDTO contactDTO = new KnIPCorpContactDTO();
            contactDTO.setMdn(mdn);
            contactDTO.setCorpId(Integer.parseInt(ipTalkGroupDTO.getCorpId()));
            Collection<KnCorpGroupInfoPersistDTO> groupList = groupInfoUtil.getSubsGroupListForXcap(contactDTO, 0, xdmsHome, persisterTxn);
            Map<Integer, KnCorpGroupInfoPersistDTO> groupDetailsMap = groupList.stream().filter(grpList -> groupIdList.contains(grpList.getGroupId()))
                    .collect(Collectors.toMap(KnCorpGroupInfoPersistDTO::getGroupId, request -> request));
            knLogger.debug(methodName, "groupDetailsMap -- ", groupDetailsMap);
            requestSubsAddlTGList.forEach(reqList -> {
                KnCorpGroupInfoPersistDTO reqData = groupDetailsMap.get(reqList.getGroupId());
                if (reqData != null) {
                    reqList.setGroupType(reqData.getGroupType());
                    reqList.setGroupMemCount(reqData.getGroupMemberCount());
                    reqList.setGroupCreatedBy(reqData.getGroupCreatedBy());
                    reqList.setAvatar(reqData.getAvatar());
                }
            });
            modifyInsertAddlGrpLst.forEach(modList -> {
                KnCorpGroupInfoPersistDTO modData = groupDetailsMap.get(modList.getGroupId());
                if (modData != null) {
                    modList.setGroupType(modData.getGroupType());
                    modList.setGroupMemCount(modData.getGroupMemberCount());
                    modList.setGroupCreatedBy(modData.getGroupCreatedBy());
                    modList.setAvatar(modData.getAvatar());
                }
            });

            populate(respDTO);
        } catch (KnCorpBOException e) {
            populate(respDTO, e);
            knLogger.error(methodName, "KnCorpBOException occured while modifyBulkSubscriberTGList", e);
        } catch (Exception e) {
            populate(respDTO, e);
            knLogger.error(methodName, "Unexpected exception occured while modifyBulkSubscriberTGList ", new KnException(
                    KnErrorCodes.BOEntity.INTERNAL_ERROR, e.getMessage(), e));
        }
        return respDTO;
    }

    @Override
    public KnXDMTalkGroupServerRespDTO getSubscriberTGList(KnIPTalkGroupDTO ipTalkGroupDTO, KnPersisterTxn persisterTxn) {
        String methodName = "getSubscriberTGList(KnIPTalkGroupDTO ipTalkGroupDTO, KnPersisterTxn persisterTxn)";
        KnXDMTalkGroupServerRespDTO respDTO = new KnXDMTalkGroupServerRespDTO();
        try {
            KnCorpProfileDTO corpProfile = commonInfoUtil.getProfileDetails(String.valueOf(ipTalkGroupDTO.getCorpId()),
                    CORP_PROFILE, false, persisterTxn);
            knLogger.debug(methodName, "Retrieved Corp Profile details - ", corpProfile);
            String xdmsHome = corpProfile.getXdmsHome();
            String mdn = ipTalkGroupDTO.getMdn();
            KnSubsProfileDTO subscProfile = commonInfoUtil.getProfileDetails(mdn, KnProfileTypes.PUBLIC_PROFILE,
                    false, persisterTxn);
            if (null != ipTalkGroupDTO.getCorpId() && Integer.parseInt(ipTalkGroupDTO.getCorpId()) > 0 && subscProfile.getCorpId() != Integer.parseInt(ipTalkGroupDTO.getCorpId())) {
                throw new KnCorpBOException(KnErrorCodes.BOEntity.SUBSCRIBER_DOES_NOT_BELONG_TO_CORP,
                        "Subscribers Does not belong to the corporation.");
            }
            //Invoking custom hook
            KnCorpHookRespDTO responseDTO = new KnCorpHookRespDTO();
            Map<String, Object> customParams = ipTalkGroupDTO.getCustomParamMap();
            if (ipTalkGroupDTO.getHierarchyType() == HIERARCHY_TYPE.HIERARCHY) {
                if (customParams != null) {
                    contactInfoUtil.checkValidHierarchySubs(Collections.singletonList(mdn), customParams, xdmsHome, persisterTxn);
                    customParams.put(CURRENT_MASTER_LIST_ETAG, corpProfile.getCorpMasterListEtag());
                    customParams.put(PERSISTER_TXN, persisterTxn);
                    customParams.put(PTT_SERVER_ID, xdmsHome);
                    ipTalkGroupDTO.setCustomParamMap(customParams);
                    KnCorpHookIPDTO hookIPDTO = new KnCorpHookIPDTO();
                    hookIPDTO.setAction(KnActions.ACTIONS.GET_SCAN_LIST);
                    hookIPDTO.setData(ipTalkGroupDTO);
                    KnProcessInvokerImpl processInvoker = KnProcessInvokerImpl.getInstance();
                    Object hookResp = processInvoker.invokeHook(CUSTOM_CORP_USER_HOOK, hookIPDTO);
                    if (hookResp instanceof KnCorpHookRespDTO) {
                        responseDTO = (KnCorpHookRespDTO) hookResp;
                        if (com.kodiak.xdms.server.common.resources.KnConstants.RESPONSE_STATUS.FAILURE.value() == responseDTO.getStatus()) {
                            knLogger.error(methodName, "Returning Failure response");
                            populateXdmResponseFroomHook(responseDTO, respDTO);
                            return respDTO;
                        } else {
                            if (responseDTO.getFailedDataList() != null && !responseDTO.getFailedDataList().isEmpty()) {
                                respDTO.setFailedDataList(responseDTO.getFailedDataList());
                            }
                        }
                    }
                }
            }
            KnCorpTGSPersistDTO corpTGSPersistDTO = new KnCorpTGSPersistDTO();
            KnCorpSubscriberDTO subscriberDTO = contactInfoUtil.selectPocSubscriberInfo(mdn, xdmsHome, true, persisterTxn);

            Collection<KnCorpAddlTGInfoDTO> subsAddlTGList = groupInfoUtil.getSubsAddlTGList(mdn, xdmsHome, true, persisterTxn);
            String userProfileId = subscriberDTO.getUserProfileId();
            knLogger.debug(methodName, " userprofileId - ", userProfileId);
            if(userProfileId!=null){
                //  KnCorpUserProfileDTO userProfile = corpUserProfileUtil.getUserProfile(String.valueOf(ipTalkGroupDTO.getCorpId()), userProfileId, xdmsHome, persisterTxn);
                Set<KnCorpGroupListInfoDTO> mcxGroupList=corpUserProfileUtil.retriveGroupProfileInfoByProfileId(userProfileId, xdmsHome, true, persisterTxn);

                knLogger.debug(methodName, "mcxGroup ", mcxGroupList);
                if (mcxGroupList != null && mcxGroupList.size() > 0) {
                    List<Integer> groupIdListFromProfile = mcxGroupList.stream().map(KnCorpGroupListInfoDTO::getGroupID).collect(Collectors.toList());
                    knLogger.debug(methodName, "groupIdListFromProfile  ", groupIdListFromProfile);
                    List<KnCorpGroupDTO> groupInfoList = groupInfoUtil.getGroupBasicInfoList(groupIdListFromProfile, xdmsHome, true, persisterTxn);

                    for(KnCorpGroupListInfoDTO info : mcxGroupList){

                        KnCorpAddlTGInfoDTO tgInfoDTO = new KnCorpAddlTGInfoDTO();
                        tgInfoDTO.setMdn(ipTalkGroupDTO.getMdn());
                        tgInfoDTO.setChannelId(info.getGroupChannel());
                        tgInfoDTO.setZoneId(info.getGroupZone());
                        tgInfoDTO.setGroupId(info.getGroupID());
                        subsAddlTGList.add(tgInfoDTO);

                    }

                }
                knLogger.debug(methodName, "subsGrpList from GroupMembership table ", subsAddlTGList);
            }
            knLogger.debug(methodName, "subsAddlTGList - ", subsAddlTGList);
            corpTGSPersistDTO.setInputDTO(ipTalkGroupDTO);
            corpTGSPersistDTO.setSubsCorpId(subscriberDTO.getCorpId());
            corpTGSPersistDTO.setSubsClientType(subscriberDTO.getClientType());
            corpTGSPersistDTO.setDbAddlTGList(subsAddlTGList);
            knLogger.debug(methodName, "Before Validation", corpTGSPersistDTO);
            validatorFW.validate(corpTGSPersistDTO);
            knLogger.debug(methodName, "Validation Successfull");
            respDTO.setAddlTGList(subsAddlTGList);
            populate(respDTO);
        } catch (KnValidationException e) {
            populate(respDTO, e);
            knLogger.error(methodName, "KnValidationException occured while getSubscriberTGList", e);
        } catch (KnCorpBOException e) {
            populate(respDTO, e);
            knLogger.error(methodName, "KnCorpBOException occured while getSubscriberTGList", e);
        } catch (Exception e) {
            populate(respDTO, e);
            knLogger.error(methodName, "Unexpected exception occured while getSubscriberTGList ", new KnException(
                    KnErrorCodes.BOEntity.INTERNAL_ERROR, e.getMessage(), e));
        }
        return respDTO;
    }

    @Override
    public KnXDMTalkGroupServerRespDTO getSubsTGList(KnIPTalkGroupDTO ipTalkGroupDTO, KnPersisterTxn persisterTxn) {
        String methodName = "getSubsTGList(KnIPTalkGroupDTO ipTalkGroupDTO, KnPersisterTxn persisterTxn)";
        KnXDMTalkGroupServerRespDTO respDTO = new KnXDMTalkGroupServerRespDTO();
        try {
            String mdn = ipTalkGroupDTO.getMdn();
            Collection<String> mdnList = new ArrayList<>();
            mdnList.add(mdn);
            KnSubsProfileDTO subsProfileDTO = commonInfoUtil.getProfileDetails(mdn, PUBLIC_PROFILE, false, persisterTxn);
            knLogger.debug(methodName, "Retrieved Corp Profile details - ", subsProfileDTO);
            String xdmsHome = subsProfileDTO.getXdmsHome();
            int indexDocEtag = ipTalkGroupDTO.getIfNoneMatch();
            KnCorpTGSPersistDTO corpTGSPersistDTO = new KnCorpTGSPersistDTO();
            Collection<KnCorpAddlTGInfoDTO> subsAddlTGList = groupInfoUtil.getSubsAddlTGList(mdn, xdmsHome, true, persisterTxn);
            knLogger.debug(methodName, "subsAddlTGList - ", subsAddlTGList);
            Map<String, Long> addlEtagmap = groupInfoUtil.getSubsAddlEtagMap(mdnList, xdmsHome, true, persisterTxn);
            knLogger.debug(methodName, "addlEtagmap - ", KnGDPRTemplate.mapKeyMdn(addlEtagmap));
            corpTGSPersistDTO.setInputDTO(ipTalkGroupDTO);
            corpTGSPersistDTO.setMcpttCompliance(subsProfileDTO.getMcpttCompliance());
            corpTGSPersistDTO.setMcPttId(subsProfileDTO.getMcpttId());
            corpTGSPersistDTO.setServiceAuthStatus(subsProfileDTO.getServiceAuthStatus());
            knLogger.debug(methodName, "Before Validation", corpTGSPersistDTO);
            validatorFW.validate(corpTGSPersistDTO);
            knLogger.debug(methodName, "Validation Successfull");
            if (indexDocEtag > 0 && (addlEtagmap.get(mdn) != null && indexDocEtag == addlEtagmap.get(mdn))) {
                knLogger.info(methodName, "emergency Document not modifed :", addlEtagmap.get(mdn));
                throw new KnCorpBOValidationException(DOC_NOT_MODIFIED, "Auth Document not modified", CORP_GROUP_MANAGER,
                        GET_SUBS_TG_LIST_XCAP, "", addlEtagmap.get(mdn).toString(), "");
            }
            KnIPCorpContactDTO contactDTO = new KnIPCorpContactDTO();
            contactDTO.setMdn(mdn);
            contactDTO.setCorpId(subsProfileDTO.getCorpId());
            contactDTO.setName(subsProfileDTO.getNetworkName());
            String userProfileId = subsProfileDTO.getUserProfileId();
            knLogger.debug(methodName, " userprofileId - ", userProfileId);
            List<Integer> missedGroups = new ArrayList<>();
            Collection<KnCorpGroupInfoPersistDTO> groupList = groupInfoUtil.getSubsGroupListForXcapOnMdn(contactDTO, 0, xdmsHome, true, persisterTxn);
            Map<Integer, KnCorpGroupInfoPersistDTO> groupMap = groupList.stream().collect(Collectors.toMap(KnCorpGroupInfoPersistDTO::getGroupId, data -> data));
            if(userProfileId!=null && subsProfileDTO.getClientMajorVersion() >= PROTOCOL_VERSION_19){
                KnCorpUserProfileDTO userProfile = corpUserProfileUtil.getUserProfile(String.valueOf(contactDTO.getCorpId()), userProfileId, xdmsHome, persisterTxn);
                knLogger.debug(methodName, "userProfile ", userProfile);
                if (userProfile.getGroupList() != null && userProfile.getGroupList().size() > 0) {
                    Set<Integer> groupIdListFromProfile = userProfile.getGroupList().stream().map(KnCorpGroupListInfoDTO::getGroupID).collect(Collectors.toSet());
                    Set<Integer> mergedGroups = new HashSet<>();
                    mergedGroups.addAll(groupMap.keySet());
                    mergedGroups.addAll(groupIdListFromProfile);
                    missedGroups.addAll(mergedGroups);
                    missedGroups.removeAll(groupMap.keySet());
                    for(KnCorpGroupListInfoDTO info : userProfile.getGroupList()){
                        if(missedGroups.contains(info.getGroupID())) {
                            KnCorpAddlTGInfoDTO tgInfoDTO = new KnCorpAddlTGInfoDTO();
                            tgInfoDTO.setChannelId(info.getGroupChannel());
                            tgInfoDTO.setZoneId(info.getGroupZone());
                            tgInfoDTO.setGroupId(info.getGroupID());
                            tgInfoDTO.setMdn(mdn);
                            subsAddlTGList.add(tgInfoDTO);
                        }
                    }
                }
            }
            Map<Integer, KnCorpGroupDTO> groupMap1 = new HashMap<>();
            knLogger.debug(methodName, "missed groups due to mcx profile -", missedGroups);
            if(!missedGroups.isEmpty()){
                groupMap1 = groupInfoUtil.getGroupBasicDetailsMap(missedGroups, xdmsHome, true, persisterTxn);
            }
            knLogger.debug(methodName, "groupList -- ", groupList);
            Collection<KnCorpAddlTGInfoDTO> addlTGList = new ArrayList<>();
            if (subsProfileDTO.getClientMajorVersion() > 0 && subsProfileDTO.getClientMajorVersion() <= PROTOCOL_VERSION_13) {
                addlTGList.addAll(subsAddlTGList);
            } else {
                subsAddlTGList.addAll(groupMap.keySet().stream().filter(g -> !subsAddlTGList.stream()
                                .map(KnCorpAddlTGInfoDTO::getGroupId).collect(Collectors.toList()).contains(g))
                        .collect(Collectors.toList()).stream().map(KnCorpAddlTGInfoDTO::new)
                        .collect(Collectors.toList()));
                knLogger.debug(methodName, "New subsAddlTGList -- ", subsAddlTGList);
                Map<Integer, KnCorpGroupDTO> finalGroupMap = groupMap1;
                subsAddlTGList.forEach(adlGrp -> {
                    KnCorpGroupInfoPersistDTO grpList = groupMap.get(adlGrp.getGroupId());
                    if(grpList != null){
                        adlGrp.setOSMListId(grpList.getOSMListId());
                        adlGrp.setGroupType(grpList.getGroupType());
                        adlGrp.setGroupCreatedBy(grpList.getGroupCreatedBy());
                        adlGrp.setGroupMemCount(grpList.getGroupMemberCount());
                        if (subsProfileDTO.getClientType() == PTTRADIOHANDSETCLIENT || subsProfileDTO.getClientType() == PTTRADIOCROSSCARRIERCLIENT
                                || subsProfileDTO.getClientType() == PTTRADIOWIFIONLYCLIENT)
                            adlGrp.setAvatar(grpList.getAvatar());
                        if(subsProfileDTO.getClientMajorVersion() >= PROTOCOL_VERSION_19){
                            adlGrp.setMcxGrpInd(grpList.getMcxGrpInd());
                        }
                        addlTGList.add(adlGrp);
                    }
                    KnCorpGroupDTO grpList1 = finalGroupMap.get(adlGrp.getGroupId());
                    if(grpList1 != null){
                        adlGrp.setOSMListId(grpList1.getOSMListId());
                        adlGrp.setGroupType(grpList1.getGroupType());
                        adlGrp.setGroupCreatedBy(grpList1.getGroupCreatedBy());
                        adlGrp.setGroupMemCount(grpList1.getGroupMemCount());
                        if (subsProfileDTO.getClientType() == PTTRADIOHANDSETCLIENT || subsProfileDTO.getClientType() == PTTRADIOCROSSCARRIERCLIENT
                                || subsProfileDTO.getClientType() == PTTRADIOWIFIONLYCLIENT)
                            adlGrp.setAvatar(grpList1.getAvatar());
                        if(subsProfileDTO.getClientMajorVersion() >= PROTOCOL_VERSION_19){
                            adlGrp.setMcxGrpInd(grpList1.getMcxGrpInd());
                        }
                        addlTGList.add(adlGrp);
                    }
                });
            }
            List<KnCorpAddlTGInfoDTO> newList = new ArrayList<>(addlTGList);
            Collections.sort(newList);
            knLogger.debug(methodName, "newList -- ", newList);
            respDTO.setAddlTGList(newList);
            Map<Integer, Integer> groupCorpIdMap = groupInfoUtil.getGroupCorpIdMap(newList, xdmsHome, persisterTxn);
            if (null != groupCorpIdMap && !groupCorpIdMap.isEmpty()) {
                respDTO.setGroupIDcorpIDMap(groupCorpIdMap);
            }
            //respDTO.setMdnCorpId(subsProfileDTO.getCorpId());
            respDTO.setSubscrProtocolversion(subsProfileDTO.getClientMajorVersion());
            if (!addlEtagmap.isEmpty() && addlEtagmap.get(mdn) != null)
                respDTO.setEtag(String.valueOf(addlEtagmap.get(mdn)));
            knLogger.debug("respDTO::", respDTO);
            populate(respDTO);
        } catch (KnValidationException e) {
            populate(respDTO, e);
            knLogger.error(methodName, "KnValidationException occured while getSubscriberTGList", e);
        } catch (KnCorpBOException e) {
            populate(respDTO, e);
            knLogger.error(methodName, "KnCorpBOException occured while getSubscriberTGList", e);
        } catch (Exception e) {
            populate(respDTO, e);
            knLogger.error(methodName, "Unexpected exception occured while getSubscriberTGList ", new KnException(
                    KnErrorCodes.BOEntity.INTERNAL_ERROR, e.getMessage(), e));
        }
        knLogger.debug(methodName, "trespDTO", respDTO);
        return respDTO;
    }

    @Override
    public KnCorpResponseDTO deleteTGList(KnIPTalkGroupDTO ipTalkGroupDTO, KnPersisterTxn persisterTxn) {
        String methodName = "deleteTGList(KnIPTalkGroupDTO ipTalkGroupDTO, KnPersisterTxn persisterTxn)";
        KnXDMTalkGroupServerRespDTO respDTO = new KnXDMTalkGroupServerRespDTO();
        try {
            KnCorpProfileDTO corpProfile = commonInfoUtil.getProfileDetails(String.valueOf(ipTalkGroupDTO.getCorpId()),
                    CORP_PROFILE, false, persisterTxn);
            knLogger.debug(methodName, "Retrieved Corp Profile details - ", corpProfile);
            String xdmsHome = corpProfile.getXdmsHome();
            String mdn = ipTalkGroupDTO.getMdn();
            KnSubsProfileDTO subscProfile = commonInfoUtil.getProfileDetails(mdn, KnProfileTypes.PUBLIC_PROFILE,
                    false, persisterTxn);
            if (null != ipTalkGroupDTO.getCorpId() && Integer.parseInt(ipTalkGroupDTO.getCorpId()) > 0 && subscProfile.getCorpId() != Integer.parseInt(ipTalkGroupDTO.getCorpId())) {
                throw new KnCorpBOException(KnErrorCodes.BOEntity.SUBSCRIBER_DOES_NOT_BELONG_TO_CORP,
                        "Subscribers Does not belong to the corporation.");
            }
            //Invoking custom hook
            KnCorpHookRespDTO responseDTO = new KnCorpHookRespDTO();
            Map<String, Object> customParams = ipTalkGroupDTO.getCustomParamMap();
            if (ipTalkGroupDTO.getHierarchyType() == HIERARCHY_TYPE.HIERARCHY) {
                if (customParams != null) {
                    contactInfoUtil.checkValidHierarchySubs(Collections.singletonList(mdn), customParams, xdmsHome, persisterTxn);
                    customParams.put(CURRENT_MASTER_LIST_ETAG, corpProfile.getCorpMasterListEtag());
                    customParams.put(PERSISTER_TXN, persisterTxn);
                    customParams.put(PTT_SERVER_ID, xdmsHome);
                    ipTalkGroupDTO.setCustomParamMap(customParams);
                    KnCorpHookIPDTO hookIPDTO = new KnCorpHookIPDTO();
                    hookIPDTO.setAction(KnActions.ACTIONS.GET_SCAN_LIST);
                    hookIPDTO.setData(ipTalkGroupDTO);
                    KnProcessInvokerImpl processInvoker = KnProcessInvokerImpl.getInstance();
                    Object hookResp = processInvoker.invokeHook(CUSTOM_CORP_USER_HOOK, hookIPDTO);
                    if (hookResp instanceof KnCorpHookRespDTO) {
                        responseDTO = (KnCorpHookRespDTO) hookResp;
                        if (com.kodiak.xdms.server.common.resources.KnConstants.RESPONSE_STATUS.FAILURE.value() == responseDTO.getStatus()) {
                            knLogger.error(methodName, "Returning Failure response");
                            populateXdmResponseFroomHook(responseDTO, respDTO);
                            return respDTO;
                        } else {
                            if (responseDTO.getFailedDataList() != null && !responseDTO.getFailedDataList().isEmpty()) {
                                respDTO.setFailedDataList(responseDTO.getFailedDataList());
                            }
                        }
                    }
                }
            }
            KnCorpTGSPersistDTO corpTGSPersistDTO = new KnCorpTGSPersistDTO();
            KnCorpSubscriberDTO subscriberDTO = contactInfoUtil.selectPocSubscriberInfo(mdn, xdmsHome, persisterTxn);
            Collection<KnCorpAddlTGInfoDTO> subsAddlTGList = groupInfoUtil.getSubsAddlTGList(mdn, xdmsHome, persisterTxn);
            knLogger.debug(methodName, "subsAddlTGList - ", subsAddlTGList);
            corpTGSPersistDTO.setInputDTO(ipTalkGroupDTO);
            corpTGSPersistDTO.setSubsCorpId(subscriberDTO.getCorpId());
            corpTGSPersistDTO.setSubsClientType(subscriberDTO.getClientType());
            corpTGSPersistDTO.setDbAddlTGList(subsAddlTGList);
            knLogger.debug(methodName, "Before Validation", corpTGSPersistDTO);
            validatorFW.validate(corpTGSPersistDTO);
            knLogger.debug(methodName, "Validation Successfull");
            //DeleteCall:
            Collection<String> mdnList = new ArrayList<>();
            mdnList.add(mdn);
            groupInfoUtil.deleteSubsAddlTalkGroup(mdnList, xdmsHome, persisterTxn);
            //groupInfoUtil.deleteSubsAddlTalkGroupDoc(mdnList, xdmsHome, persisterTxn);
            Map<String, KnOPDirChgDTO> etagMap = new HashMap<>();
            //etagMap = commonInfoUtil.formMdnAddlTGListDeleteNotification(mdn, etagMap);
            //knLogger.debug(methodName, "etagMap - ", etagMap);
            etagMap = groupInfoUtil.updateAddlTalkGroupImpactedTables(xdmsHome, mdnList, persisterTxn, etagMap);
            knLogger.debug(methodName, "etagMap - ", KnGDPRTemplate.mapKeyMdn(etagMap));
            Map<Integer, Integer> groupCorpIdMap = new HashMap<>();
            if (subsAddlTGList != null && !subsAddlTGList.isEmpty()) {
                groupCorpIdMap = groupInfoUtil.getGroupCorpIdMap((List<KnCorpAddlTGInfoDTO>) subsAddlTGList, xdmsHome, persisterTxn);
            }
            knLogger.debug(methodName, "groupCorpId - ", groupCorpIdMap);
            if (null != groupCorpIdMap && !groupCorpIdMap.isEmpty()) {
                etagMap = formXcapAddlTGDiffNotification(etagMap, null, null,
                        subsAddlTGList, groupCorpIdMap);
                knLogger.debug(methodName, "etagMap 333 - ", KnGDPRTemplate.mapKeyMdn(etagMap));
            }
            // todo: LI Notification Preparation. // no SDD requirements.
            respDTO.setChangeLogMap(etagMap);
            populate(respDTO);
        } catch (KnValidationException e) {
            populate(respDTO, e);
            knLogger.error(methodName, "KnValidationException occured while deleteTGList", e);
        } catch (KnCorpBOException e) {
            populate(respDTO, e);
            knLogger.error(methodName, "KnCorpBOException occured while deleteTGList", e);
        } catch (Exception e) {
            populate(respDTO, e);
            knLogger.error(methodName, "Unexpected exception occured while deleteTGList ", new KnException(
                    KnErrorCodes.BOEntity.INTERNAL_ERROR, e.getMessage(), e));
        }
        return respDTO;
    }

    public KnCorpGroupListRespDTO getSubsGroupList(KnIPCorpContactDTO corpContactDTO, KnPersisterTxn persisterTxn) {

        String methodName = "getSubsGroupList(KnIPCorpContactDTO, KnPersisterTxn)";
        knLogger.info(methodName, "ENTRY : Input DTO Passed with corpId , mdn - ", corpContactDTO.getCorpId(), " ", corpContactDTO.getMdn());
        KnCorpGroupListRespDTO respDto = new KnCorpGroupListRespDTO();

        try {
            int corpId = corpContactDTO.getCorpId();
            //Step:
            //get the Corp profile details from cache
            knLogger.debug(methodName, "Fetch the corpProfile profile if cached or fetch from the DB the details");
            KnCorpProfileDTO corpProfile = commonInfoUtil.getProfileDetails(String.valueOf(corpId),
                    CORP_PROFILE, false, persisterTxn);
            KnSubsProfileDTO subsProfileDTO = commonInfoUtil.getProfileDetails(corpContactDTO.getMdn(), PUBLIC_PROFILE, false, persisterTxn);
            knLogger.debug(methodName, "Retrieved Corp Profile details - ", corpProfile);
            String xdmsHome = corpProfile.getXdmsHome();

            //Invoking custom hook
            KnCorpHookRespDTO responseDTO = new KnCorpHookRespDTO();
            if (CLIENT_TYPE_WCSR != corpContactDTO.getClientType()) {
                Map<String, Object> customParams = corpContactDTO.getCustomParamMap();
                if (corpContactDTO.getHierarchyType() == HIERARCHY_TYPE.HIERARCHY) {
                    customParams.put(CURRENT_MASTER_LIST_ETAG, corpProfile.getCorpMasterListEtag());
                    customParams.put(PERSISTER_TXN, persisterTxn);
                    customParams.put(PTT_SERVER_ID, xdmsHome);
                    corpContactDTO.setCustomParamMap(customParams);
                    KnCorpHookIPDTO hookIPDTO = new KnCorpHookIPDTO();
                    hookIPDTO.setAction(KnActions.ACTIONS.GET_SUBSC_GROUP_LIST);
                    hookIPDTO.setData(corpContactDTO);
                    KnProcessInvokerImpl processInvoker = KnProcessInvokerImpl.getInstance();
                    Object hookResp = processInvoker.invokeHook(CUSTOM_CORP_USER_HOOK, hookIPDTO);
                    if (hookResp instanceof KnCorpHookRespDTO) {
                        responseDTO = (KnCorpHookRespDTO) hookResp;
                        if (com.kodiak.xdms.server.common.resources.KnConstants.RESPONSE_STATUS.FAILURE.value() == responseDTO.getStatus()) {
                            knLogger.error(methodName, "Returning Failure response");
                            populateXdmResponseFroomHook(responseDTO, respDto);
                            return respDto;
                        }
                    }
                }
            }

            /*Collection<String> mdnList = new ArrayList<String>();
            mdnList.add(corpContactDTO.getMdn());*/
            KnReverseContactPersistDto contactPersistDto = new KnReverseContactPersistDto();
            int subscribersCount = contactInfoUtil.getSubscribersCount(corpContactDTO.getMdn(), corpId, xdmsHome, persisterTxn);
            boolean isSubscrExternalCont = false;
            if (subscribersCount < 1) {
                isSubscrExternalCont = contactInfoUtil.isExternalContExist(corpContactDTO.getMdn(), corpId, xdmsHome, persisterTxn);
            }
            contactPersistDto.setInputDTO(corpContactDTO);
            contactPersistDto.setSubscriberCount(subscribersCount);
            contactPersistDto.setExternalContact(isSubscrExternalCont);
            contactPersistDto.setMcpttId(subsProfileDTO.getMcpttId());
            contactPersistDto.setMcpttCompliance(subsProfileDTO.getMcpttCompliance());
            knLogger.debug(methodName, "Before Validation DTO passed - ", contactPersistDto);
            validatorFW.validate(contactPersistDto);
            knLogger.debug(methodName, "After Validation ");

            //Step:
            //retrieve group info
            Collection<KnCorpGroupInfoPersistDTO> subsGroupList = groupInfoUtil.getSubsGroupList(corpContactDTO,
                    corpProfile.getMaxMemPerCorpGroup(), xdmsHome, persisterTxn);
            Collection<KnCorpGroupInfoPersistDTO> filteredGroupList = new ArrayList<>();
            if (corpContactDTO.getClientType() != CLIENT_TYPE_WCSR) {
                filteredGroupList = subsGroupList.stream()
                        .filter(grpDto -> grpDto.getGroupCreatedBy() != CREATED_BY.ABDG.value()).collect(Collectors.toList());
            } else {
                filteredGroupList = subsGroupList;
            }

            Collection<Integer> groupIds = new ArrayList<>();
            if (!filteredGroupList.isEmpty()) {
                for (KnCorpGroupInfoPersistDTO groupInfo : filteredGroupList) {
                    groupIds.add(groupInfo.getGroupId());
                }
            }

            if (!groupIds.isEmpty()) {
                Map<Integer, Collection<KnCorpGroupMemberDTO>> groupSupervisorList = groupInfoUtil.getGrpSubsc(groupIds, xdmsHome, persisterTxn);
                Set<String> mdnLists = new HashSet<String>();
                if (groupSupervisorList != null && !groupSupervisorList.isEmpty()) {
                    for (Entry<Integer, Collection<KnCorpGroupMemberDTO>> entry : groupSupervisorList.entrySet()) {
                        Collection<KnCorpGroupMemberDTO> groupMemberDTO = entry.getValue();
                        for (KnCorpGroupMemberDTO memberDTO : groupMemberDTO) {
                            mdnLists.add(memberDTO.getMdn());
                        }
                    }
                }
                Map<String, String> subscNameList = contactInfoUtil.getSubscribersName(mdnLists, xdmsHome, persisterTxn);
                for (KnCorpGroupInfoPersistDTO grpPersistDTO : filteredGroupList) {
                    if (groupSupervisorList != null) {
                        Collection<KnCorpGroupMemberDTO> supervisorMemberList = groupSupervisorList.get(grpPersistDTO.getGroupId());
                        if (supervisorMemberList != null) {
                            for (KnCorpGroupMemberDTO contactDTO : supervisorMemberList) {
                                String mdn = contactDTO.getMdn();
                                if (subscNameList.containsKey(mdn)) {
                                    contactDTO.setName(subscNameList.get(mdn));
                                }
                            }
                        }
                        grpPersistDTO.setGroupSupervisor(supervisorMemberList);
                    }
                }
            }

            Collection<KnCorpGroupInfoDTO> groupInfoList = new ArrayList<KnCorpGroupInfoDTO>(filteredGroupList.size());
            groupInfoList.addAll(filteredGroupList);
            respDto.setGroupList(groupInfoList);
            populate(respDto);
            if (responseDTO.getFailedDataList() != null && !responseDTO.getFailedDataList().isEmpty()) {
                respDto.setFailedDataList(responseDTO.getFailedDataList());
            }

        } catch (KnCorpBOException e) {
            knLogger.error(methodName, "KnCorpBOException occured while retrieving Group List - ", e);
            populate(respDto, e);

        } catch (Exception e) {
            knLogger.error(methodName, "Unexpected exception occured while retrieving Group List - ",
                    new KnException(KnErrorCodes.BOEntity.INTERNAL_ERROR, e.getMessage(), e));
            populate(respDto, e);

        }
        knLogger.debug(methodName, "EXIT : GroupList Response - ", respDto);
        knLogger.debug(methodName, "EXIT : GroupList Response - ", respDto.getGroupList());
        return respDto;
    }

    public KnCorpGroupListRespDTO getMobileSyncLocSupervisors(KnIPSubscriberInfoDTO subscriberInfoDTO, KnPersisterTxn persisterTxn) {
        String methodName = "getMobileSyncLocSupervisors(KnIPSubscriberInfoDTO, KnPersisterTxn)";
        knLogger.info(methodName, "ENTRY : Input DTO Passed - ", subscriberInfoDTO);
        KnCorpGroupListRespDTO respDto = new KnCorpGroupListRespDTO();
        try {
            Map<Integer, List<KnCorpGroupMemberDTO>> respMap = new HashMap<>();
            String xdmsHome = KnGeneralUtil.getXDMServerPttServerId();
            List<String> mdnList = subscriberInfoDTO.getMdnList();
            Map<String, Collection<Integer>> subsGroupListMap = groupInfoUtil.getGroupListForSubs(mdnList, xdmsHome, true, persisterTxn);
            Set<Integer> groupIdList = new HashSet<>();
            subsGroupListMap.forEach((mdn, groupIds) -> {
                groupIdList.addAll(groupIds);
            });
            Map<Integer, List<String>> grpMemberDetails = groupInfoUtil.getCorpGroupMemberForLocSupervisor(groupIdList, xdmsHome, persisterTxn);

            Set<String> grpMembers = new HashSet<>();
            grpMemberDetails.forEach((groupId, members) -> {
                grpMembers.addAll(members);
            });
            Map<String, KnCorpSubscriberDTO> contDetailsMap = contactInfoUtil.getSubsribersCorporateDetails(grpMembers, xdmsHome, persisterTxn);
            grpMemberDetails.forEach((groupId, mems) -> {
                List<KnCorpGroupMemberDTO> memberDTOS = new ArrayList<>();
                if (mems != null) {
                    mems.forEach(locSu -> {
                        KnCorpGroupMemberDTO groupMemberDTO = new KnCorpGroupMemberDTO();
                        groupMemberDTO.setGroupId(groupId);
                        groupMemberDTO.setMdn(locSu);
                        groupMemberDTO.setSubsActiveFS2(contDetailsMap.get(locSu).getSubsActiveFS2());
                        memberDTOS.add(groupMemberDTO);
                    });
                }
                respMap.put(groupId, memberDTOS);
            });
            respDto.setGroupMembers(respMap);
            respDto.setFleetMemGroupIds(subsGroupListMap);
            populate(respDto);
        } catch (KnCorpBOException e) {
            knLogger.error(methodName, "KnCorpBOException occured while retrieving mobileSync LocWatcher - ", e);
            populate(respDto, e);
        } catch (Exception e) {
            knLogger.error(methodName, "Unexpected exception occured while retrieving mobileSync LocWatcher - ",
                    new KnException(KnErrorCodes.BOEntity.INTERNAL_ERROR, e.getMessage(), e));
            populate(respDto, e);
        }
        knLogger.debug(methodName, "EXIT : GroupList Response - ", respDto.getGroupMembers());
        return respDto;
    }

