            var reqSubscListMap = new HashMap<Integer, List<KnCorpSubscriberDTO>>();
//            Collection<KnCorpSubscriberDTO> reqExtMemList = pocMdnPersistDto.getExternalMdnList();
            var reqExteStrContListMap = new HashMap<Integer, List<String>>();

